const fs = require('fs');
const path = require('path');
const readline = require('readline');
const { createClient } = require('@supabase/supabase-js');

// Parse CLI arguments
const args = {};
process.argv.slice(2).forEach(arg => {
  if (arg.startsWith('--')) {
    const parts = arg.split('=');
    const key = parts[0].substring(2);
    let value = parts.slice(1).join('=');
    if (value.startsWith('"') && value.endsWith('"')) {
      value = value.substring(1, value.length - 1);
    } else if (value.startsWith("'") && value.endsWith("'")) {
      value = value.substring(1, value.length - 1);
    }
    args[key] = value;
  }
});

const scanDir = args.dir;
const workspaceId = args.workspace;
const agentSender = args.agentSender || args['agent-sender'] || 'Genesys Voyage';

if (!scanDir || !workspaceId) {
  console.log(`
Batch Importer Usage:
  node scripts/batch-import-chats.js \\
    --dir="path/to/chats/folder" \\
    --workspace="workspace-uuid" \\
    --agent-sender="Genesys Voyage"

Example:
  node scripts/batch-import-chats.js \\
    --dir="D:\\New folder (2)\\Daily_CRM" \\
    --workspace="0384aa61-25ad-440f-9a43-603f9779cde4"
  `);
  process.exit(1);
}

if (!fs.existsSync(scanDir)) {
  console.error(`Error: Directory not found at ${scanDir}`);
  process.exit(1);
}

// Load environment variables from .env.local
const envPath = path.join(__dirname, '..', '.env.local');
if (!fs.existsSync(envPath)) {
  console.error('Error: .env.local not found in project root');
  process.exit(1);
}

const envContent = fs.readFileSync(envPath, 'utf8');
const envVars = {};
envContent.split(/\r?\n/).forEach(line => {
  const match = line.match(/^\s*([^#=]+)\s*=\s*(.*)$/);
  if (match) {
    const key = match[1].trim();
    let val = match[2].trim();
    if (val.startsWith('"') && val.endsWith('"')) {
      val = val.substring(1, val.length - 1);
    } else if (val.startsWith("'") && val.endsWith("'")) {
      val = val.substring(1, val.length - 1);
    }
    envVars[key] = val;
  }
});

const supabaseUrl = envVars.NEXT_PUBLIC_SUPABASE_URL;
const supabaseServiceKey = envVars.SUPABASE_SERVICE_ROLE_KEY;
const supabase = createClient(supabaseUrl, supabaseServiceKey);

// Find all WhatsApp chat text files recursively
function getChatFiles(dir, filesList = []) {
  const items = fs.readdirSync(dir);
  for (const item of items) {
    const fullPath = path.join(dir, item);
    const stat = fs.statSync(fullPath);
    if (stat.isDirectory()) {
      if (item !== 'node_modules' && item !== '.next' && item !== '.git') {
        getChatFiles(fullPath, filesList);
      }
    } else if (stat.isFile() && item.startsWith('WhatsApp Chat with') && item.endsWith('.txt')) {
      filesList.push(fullPath);
    }
  }
  return filesList;
}

// Extract contact name from filename
function extractContactName(filePath) {
  const filename = path.basename(filePath);
  // Matches "WhatsApp Chat with " followed by the name up to ".txt"
  const match = filename.match(/^WhatsApp Chat with (.*?)\.txt$/i);
  return match ? match[1].trim() : null;
}

// WhatsApp date parsing
function parseDate(dateStr, timeStr) {
  const [monthStr, dayStr, yearStr] = dateStr.split('/');
  let year = parseInt(yearStr);
  if (year < 100) year += 2000;

  const cleanTime = timeStr.replace(/[\u202F\u00A0\s]+/g, ' ').trim();
  const parts = cleanTime.split(' ');
  const timePart = parts[0];
  const ampm = parts[1];

  const timeComponents = timePart.split(':');
  let hour = parseInt(timeComponents[0]);
  const minute = parseInt(timeComponents[1]);
  const second = timeComponents[2] ? parseInt(timeComponents[2]) : 0;

  if (ampm && ampm.toUpperCase() === 'PM' && hour < 12) hour += 12;
  if (ampm && ampm.toUpperCase() === 'AM' && hour === 12) hour = 0;

  return new Date(year, parseInt(monthStr) - 1, parseInt(dayStr), hour, minute, second);
}

// Parse WhatsApp chat text
function parseWhatsAppChat(text) {
  const lines = text.split(/\r?\n/);
  const messages = [];
  let currentMsg = null;

  const bracketRegex = /^\[(\d{1,2}\/\d{1,2}\/\d{2,4}),\s*(\d{1,2}:\d{2}(?::\d{2})?[\u202F\s]*[AP]M)\]\s*(.*)$/i;
  const standardRegex = /^(\d{1,2}\/\d{1,2}\/\d{2,4}),\s*(\d{1,2}:\d{2}(?::\d{2})?[\u202F\s]*[AP]M)\s*-\s*(.*)$/i;

  for (const line of lines) {
    const bracketMatch = line.match(bracketRegex);
    const standardMatch = line.match(standardRegex);
    const match = bracketMatch || standardMatch;

    if (match) {
      if (currentMsg) {
        messages.push(currentMsg);
        currentMsg = null;
      }
      const dateStr = match[1];
      const timeStr = match[2];
      const rest = match[3];

      const senderMatch = rest.match(/^([^:]+):\s*(.*)$/);
      if (senderMatch) {
        const sender = senderMatch[1].trim();
        const textContent = senderMatch[2].trim();
        try {
          const timestamp = parseDate(dateStr, timeStr);
          currentMsg = { timestamp, sender, text: textContent };
        } catch (e) {
          // ignore parsing error line
        }
      }
    } else if (currentMsg) {
      currentMsg.text += '\n' + line;
    }
  }

  if (currentMsg) {
    messages.push(currentMsg);
  }
  return messages;
}

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

const askQuestion = (query) => new Promise((resolve) => rl.question(query, resolve));

let workspaceName = '';

async function importSingleChat(filePath, contactName, phoneNum, userId) {
  console.log(`\n--------------------------------------------------`);
  console.log(`Starting import for: "${contactName}" (${phoneNum})`);
  
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const rawParsed = parseWhatsAppChat(fileContent);
  
  const customerSender = contactName;
  const filtered = rawParsed.filter(m => m.sender === customerSender || m.sender === agentSender);
  
  if (filtered.length === 0) {
    console.warn(`⚠️ Warning: No messages matched senders "${customerSender}" or "${agentSender}".`);
    console.log('Unique senders found in file:');
    const uniqueSenders = [...new Set(rawParsed.map(m => m.sender))];
    uniqueSenders.forEach(s => console.log(` - "${s}"`));
    
    // Auto-fallback: if there are only 2 unique senders, and one is agentSender, assign the other as customer!
    const nonAgentSenders = uniqueSenders.filter(s => s !== agentSender);
    if (nonAgentSenders.length === 1) {
      const fallbackCustomer = nonAgentSenders[0];
      console.log(`Found only one other sender: "${fallbackCustomer}". Using this as customer.`);
      return importSingleChatWithMappedSenders(filePath, fallbackCustomer, phoneNum, userId);
    }
    
    console.log('Skipping file.');
    return false;
  }

  return importSingleChatWithMappedSenders(filePath, customerSender, phoneNum, userId, filtered);
}

async function importSingleChatWithMappedSenders(filePath, customerSender, phoneNum, userId, preFiltered = null) {
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const messages = preFiltered || parseWhatsAppChat(fileContent).filter(m => m.sender === customerSender || m.sender === agentSender);

  // 1. Fetch or create contact
  let { data: contact, error: contactErr } = await supabase
    .from('contacts')
    .select('*')
    .eq('phone', phoneNum)
    .eq('workspace_id', workspaceId)
    .maybeSingle();

  if (contactErr) {
    console.error('Failed to query contact:', contactErr);
    return false;
  }

  if (!contact) {
    console.log(`Creating new contact "${customerSender}" with phone ${phoneNum}...`);
    const { data: newContact, error: createErr } = await supabase
      .from('contacts')
      .insert({
        workspace_id: workspaceId,
        user_id: userId,
        phone: phoneNum,
        name: customerSender
      })
      .select('*')
      .single();

    if (createErr || !newContact) {
      console.error('Failed to create contact:', createErr);
      return false;
    }
    contact = newContact;
  }

  // 2. Fetch or create conversation
  let { data: conversation, error: convErr } = await supabase
    .from('conversations')
    .select('*')
    .eq('contact_id', contact.id)
    .eq('workspace_id', workspaceId)
    .maybeSingle();

  if (convErr) {
    console.error('Failed to query conversation:', convErr);
    return false;
  }

  if (!conversation) {
    console.log('Creating new conversation...');
    const { data: newConv, error: createConvErr } = await supabase
      .from('conversations')
      .insert({
        workspace_id: workspaceId,
        user_id: userId,
        contact_id: contact.id,
        status: 'open',
        unread_count: 0
      })
      .select('*')
      .single();

    if (createConvErr || !newConv) {
      console.error('Failed to create conversation:', createConvErr);
      return false;
    }
    conversation = newConv;
  } else {
    console.log(`Conversation found (ID: ${conversation.id})`);
    console.log('Clearing existing messages in this conversation to prevent duplicates...');
    const { error: clearErr } = await supabase
      .from('messages')
      .delete()
      .eq('conversation_id', conversation.id);
    if (clearErr) {
      console.warn('Warning: Could not clear existing messages:', clearErr.message);
    }
  }

  // 3. Insert messages
  console.log(`Ingesting ${messages.length} messages...`);
  let imported = 0;
  const chunkSize = 50;

  for (let i = 0; i < messages.length; i += chunkSize) {
    const chunk = messages.slice(i, i + chunkSize);
    const rows = chunk.map(m => {
      const lines = m.text.split('\n');
      const firstLine = lines[0];
      const isMedia = firstLine.match(/^(.*?)\s*\(file attached\)$/i);
      let contentType = 'text';
      let mediaUrl = null;
      let contentText = m.text;

      if (isMedia) {
        const filename = isMedia[1].trim();
        const ext = path.extname(filename).toLowerCase();
        if (['.png', '.jpg', '.jpeg', '.gif', '.webp'].includes(ext)) {
          contentType = 'image';
        } else if (['.mp4', '.mov', '.avi', '.mkv'].includes(ext)) {
          contentType = 'video';
        } else if (['.mp3', '.wav', '.ogg', '.m4a', '.aac'].includes(ext)) {
          contentType = 'audio';
        } else {
          contentType = 'document';
        }

        // Try to locate file in the same directory as the chat file
        const chatDir = path.dirname(filePath);
        const sourceFilePath = path.join(chatDir, filename);

        if (fs.existsSync(sourceFilePath)) {
          const sanitizeName = (name) => name.replace(/[^a-zA-Z0-9 _-]/g, '').trim();
          const workspaceSubdir = sanitizeName(workspaceName);
          const contactSubdir = sanitizeName(contact.name || customerSender);
          
          const destDir = path.join(__dirname, '..', 'public', 'uploads', workspaceSubdir, contactSubdir);
          fs.mkdirSync(destDir, { recursive: true });
          
          const destFilePath = path.join(destDir, filename);
          try {
            fs.copyFileSync(sourceFilePath, destFilePath);
            mediaUrl = `/uploads/${workspaceSubdir}/${contactSubdir}/${filename}`;
            contentText = lines.slice(1).join('\n').trim() || filename;
            console.log(`Copied media attachment: ${filename}`);
          } catch (copyErr) {
            console.error(`Failed to copy file ${filename}:`, copyErr.message);
          }
        } else {
          console.warn(`⚠️ Warning: Media file "${filename}" referenced in chat but not found in folder.`);
        }
      }

      return {
        conversation_id: conversation.id,
        sender_type: m.sender === customerSender ? 'customer' : 'agent',
        content_type: contentType,
        content_text: contentText || ' ',
        media_url: mediaUrl,
        status: 'read',
        created_at: m.timestamp.toISOString()
      };
    });

    const { error: insertErr } = await supabase.from('messages').insert(rows);
    if (insertErr) {
      // Individual fallback
      for (const row of rows) {
        const { error: singleErr } = await supabase.from('messages').insert(row);
        if (!singleErr) imported++;
      }
    } else {
      imported += rows.length;
    }
  }

  console.log(`Success: Imported ${imported} messages.`);

  // 4. Update conversation preview
  if (messages.length > 0) {
    const lastMsg = messages[messages.length - 1];
    await supabase
      .from('conversations')
      .update({
        last_message_text: lastMsg.text || '',
        last_message_at: lastMsg.timestamp.toISOString()
      })
      .eq('id', conversation.id);
  }

  return true;
}

async function main() {
  console.log('Scanning for WhatsApp chat files...');
  const chatFiles = getChatFiles(scanDir);
  console.log(`Found ${chatFiles.length} WhatsApp chat files.`);

  if (chatFiles.length === 0) {
    console.log('No chat files starting with "WhatsApp Chat with" and ending in ".txt" were found.');
    process.exit(0);
  }

  // Verify workspace & get a user ID to assign contact ownership
  const { data: workspace, error: wsErr } = await supabase
    .from('workspaces')
    .select('name')
    .eq('id', workspaceId)
    .single();

  if (wsErr || !workspace) {
    console.error('Workspace verification failed. Verify the workspace UUID.');
    process.exit(1);
  }
  workspaceName = workspace.name;

  const { data: members, error: memErr } = await supabase
    .from('workspace_members')
    .select('user_id')
    .eq('workspace_id', workspaceId)
    .limit(1);

  if (memErr || !members || members.length === 0) {
    console.error('No members found in workspace.');
    process.exit(1);
  }
  const defaultUserId = members[0].user_id;

  console.log(`Target Workspace: "${workspace.name}"`);
  console.log('==================================================');

  for (let i = 0; i < chatFiles.length; i++) {
    const filePath = chatFiles[i];
    const contactName = extractContactName(filePath);
    if (!contactName) continue;

    console.log(`\n[${i + 1}/${chatFiles.length}] File: ${path.basename(filePath)}`);

    // Try to find the contact by name in the database
    const { data: existingContacts, error: searchErr } = await supabase
      .from('contacts')
      .select('name, phone')
      .eq('workspace_id', workspaceId)
      .ilike('name', `%${contactName}%`);

    let phoneNum = null;

    if (!searchErr && existingContacts && existingContacts.length > 0) {
      // Direct or partial name match found
      if (existingContacts.length === 1) {
        phoneNum = existingContacts[0].phone;
        console.log(`Found match in CRM: "${existingContacts[0].name}" (${phoneNum})`);
      } else {
        console.log(`Multiple matching contacts found in CRM:`);
        existingContacts.forEach((c, idx) => console.log(`  ${idx + 1}. ${c.name} (${c.phone})`));
        const selection = await askQuestion(`Select contact number (1-${existingContacts.length}) or enter a custom phone, or press enter to skip: `);
        const selIdx = parseInt(selection) - 1;
        if (selIdx >= 0 && selIdx < existingContacts.length) {
          phoneNum = existingContacts[selIdx].phone;
        } else if (selection.trim()) {
          phoneNum = selection.trim();
        }
      }
    }

    // If no match found or skipped, ask for phone number
    if (!phoneNum) {
      // Check if the contact name itself is a clean phone number
      const cleanName = contactName.replace(/[+\s()-]/g, '');
      if (/^\d{8,15}$/.test(cleanName)) {
        phoneNum = contactName;
        console.log(`Contact name matches a phone number layout. Using: ${phoneNum}`);
      } else {
        const answer = await askQuestion(`No contact found for "${contactName}".\n👉 Please enter their phone number to import (or press Enter to skip this file): `);
        if (answer.trim()) {
          phoneNum = answer.trim();
        } else {
          console.log(`Skipping file.`);
          continue;
        }
      }
    }

    // Run the import
    try {
      await importSingleChat(filePath, contactName, phoneNum, defaultUserId);
    } catch (err) {
      console.error(`Failed to import chat for ${contactName}:`, err.message);
    }
  }

  console.log('\n==================================================');
  console.log('Batch import completed!');
  rl.close();
}

main().catch(err => {
  console.error(err);
  rl.close();
});

/**
 * Generates the per-operation CRUD RLS migration from the resource
 * catalog in src/lib/auth/resources.ts.
 *
 * Run:  node --experimental-strip-types scripts/generate-crud-rls.mjs > supabase/migrations/074_crud_rbac.sql
 *
 * Why generated: 32 resources x 120 tables x 4 operations is ~480
 * policies. Hand-writing them guarantees typos and, worse, guarantees
 * the UI matrix and the database drift apart. Both now come from one
 * catalog.
 */

const { RESOURCES, ACTIONS, ACTION_SQL, MODULE_KEYS, RESOURCES: _r } = await import(
  "../src/lib/auth/resources.ts"
);

const out = [];
const w = (s = "") => out.push(s);

w(`-- ============================================================
-- 074_crud_rbac.sql   *** GENERATED — DO NOT EDIT BY HAND ***
--
-- Source: src/lib/auth/resources.ts
-- Regenerate: node --experimental-strip-types scripts/generate-crud-rls.mjs \\
--               > supabase/migrations/074_crud_rbac.sql
--
-- Per-resource, per-operation CRUD permissions enforced in the
-- database. Every permission is '<resource>:<action>' (e.g.
-- 'payroll:read', 'contacts:delete') stored in
-- workspace_roles.permissions, and each table gets four RESTRICTIVE
-- policies — one per SQL operation — so "read but never delete" is a
-- real boundary even against direct API calls.
--
-- RESTRICTIVE policies only narrow: existing permissive policies keep
-- their per-row logic and now additionally require the matching CRUD
-- permission. Owners/admins short-circuit inside the helper.
-- service_role bypasses RLS entirely, so webhooks and system jobs are
-- unaffected.
--
-- Rollout is non-disruptive — see the seeding section: existing roles
-- are granted every action they could already perform, and the three
-- built-in roles (Owner / Admin / Viewer) are created per workspace.
-- Nobody loses access on deploy; admins then untick what they want to
-- restrict.
--
-- Idempotent.
-- ============================================================
`);

// ── helper function ────────────────────────────────────────────────
w(`-- ---------------------------------------------------------------
-- 1. Permission helper: '<resource>:<action>' lookup.
--
-- Mirrors has_workspace_permission (migration 049) but is written for
-- the CRUD keys, and ALSO requires the row's module to be granted, so
-- a role can be shut out of a whole module without unticking 4x32
-- boxes. STABLE + SECURITY DEFINER so RLS can call it cheaply.
-- ---------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.has_resource_permission(
  p_workspace_id UUID,
  p_user_id      UUID,
  p_resource     TEXT,
  p_action       TEXT,
  p_module       TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_perms JSONB;
BEGIN
  IF p_user_id IS NULL OR p_workspace_id IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Owners and admins bypass the matrix entirely.
  IF EXISTS (
    SELECT 1 FROM public.workspace_members
    WHERE workspace_id = p_workspace_id
      AND user_id = p_user_id
      AND role IN ('owner', 'admin')
  ) THEN
    RETURN TRUE;
  END IF;

  SELECT wr.permissions INTO v_perms
  FROM public.workspace_members wm
  JOIN public.workspace_roles wr ON wr.id = wm.role_id
  WHERE wm.workspace_id = p_workspace_id
    AND wm.user_id = p_user_id;

  -- No role assigned → no access to gated resources.
  IF v_perms IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Module gate. Absent key = allowed, so roles created before the
  -- module keys existed keep working (073 seeds them anyway).
  IF p_module IS NOT NULL
     AND v_perms ? ('module_' || p_module)
     AND COALESCE((v_perms->>('module_' || p_module))::boolean, false) IS NOT TRUE THEN
    RETURN FALSE;
  END IF;

  RETURN COALESCE((v_perms->>(p_resource || ':' || p_action))::boolean, false);
END
$fn$;

REVOKE ALL ON FUNCTION public.has_resource_permission(UUID, UUID, TEXT, TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_resource_permission(UUID, UUID, TEXT, TEXT, TEXT) TO authenticated, service_role;
`);

// ── seeding ────────────────────────────────────────────────────────
const allKeys = RESOURCES.flatMap((r) => ACTIONS.map((a) => `${r.key}:${a}`));
const viewerKeys = RESOURCES.map((r) => `${r.key}:read`);
const moduleKeys = MODULE_KEYS.map((m) => `module_${m}`);

const jsonAll = JSON.stringify(
  Object.fromEntries([
    ...allKeys.map((k) => [k, true]),
    ...moduleKeys.map((k) => [k, true]),
  ]),
);
const jsonViewer = JSON.stringify(
  Object.fromEntries([
    ...allKeys.map((k) => [k, viewerKeys.includes(k)]),
    ...moduleKeys.map((k) => [k, true]),
  ]),
);

w(`-- ---------------------------------------------------------------
-- 2. Built-in roles: Owner / Admin / Viewer, per workspace.
--    Owner+Admin get the full matrix (their bypass makes it
--    informational); Viewer is read-everything, no writes, and stays
--    editable so an admin can narrow which modules a viewer sees.
-- ---------------------------------------------------------------
INSERT INTO public.workspace_roles (workspace_id, name, description, permissions, is_system)
SELECT w.id, 'Owner', 'Full access including billing and deleting the workspace.', '${jsonAll}'::jsonb, true
FROM public.workspaces w
WHERE NOT EXISTS (
  SELECT 1 FROM public.workspace_roles r WHERE r.workspace_id = w.id AND r.name = 'Owner'
);

INSERT INTO public.workspace_roles (workspace_id, name, description, permissions, is_system)
SELECT w.id, 'Admin', 'Manage the team, settings and every module.', '${jsonAll}'::jsonb, true
FROM public.workspaces w
WHERE NOT EXISTS (
  SELECT 1 FROM public.workspace_roles r WHERE r.workspace_id = w.id AND r.name = 'Admin'
);

INSERT INTO public.workspace_roles (workspace_id, name, description, permissions, is_system)
SELECT w.id, 'Viewer', 'Read-only across every module. Cannot create, edit or delete.', '${jsonViewer}'::jsonb, true
FROM public.workspaces w
WHERE NOT EXISTS (
  SELECT 1 FROM public.workspace_roles r WHERE r.workspace_id = w.id AND r.name = 'Viewer'
);

-- ---------------------------------------------------------------
-- 3. Non-disruptive seeding of EXISTING roles.
--
--    Any role missing CRUD keys is granted every action for the
--    modules it already had — i.e. exactly what its holders could do
--    before this migration. Existing keys are never overwritten, so a
--    re-run can't undo an admin's later choices.
-- ---------------------------------------------------------------
UPDATE public.workspace_roles wr
SET permissions = seed.perms || wr.permissions
FROM (
  SELECT r.id,
         jsonb_object_agg(k.key, true) AS perms
  FROM public.workspace_roles r
  CROSS JOIN (VALUES`);

const seedRows = RESOURCES.flatMap((r) =>
  ACTIONS.map((a) => `    ('${r.key}:${a}', '${r.module}')`),
);
w(seedRows.join(",\n"));
w(`  ) AS k(key, module)
  WHERE NOT (r.permissions ? k.key)
    -- only grant modules the role already had (073 defaulted these to true)
    AND COALESCE((r.permissions->>('module_' || k.module))::boolean, true) IS TRUE
  GROUP BY r.id
) AS seed
WHERE wr.id = seed.id;

-- Viewers must never gain writes from the blanket seed above.
UPDATE public.workspace_roles
SET permissions = permissions || '${JSON.stringify(
    Object.fromEntries(
      RESOURCES.flatMap((r) =>
        ACTIONS.filter((a) => a !== "read").map((a) => [`${r.key}:${a}`, false]),
      ),
    ),
  )}'::jsonb
WHERE is_system = true AND name = 'Viewer';

-- ---------------------------------------------------------------
-- 4. Backfill role_id for members that still have none, so the matrix
--    is actually consulted instead of failing closed.
-- ---------------------------------------------------------------
UPDATE public.workspace_members wm
SET role_id = wr.id
FROM public.workspace_roles wr
WHERE wm.role_id IS NULL
  AND wr.workspace_id = wm.workspace_id
  AND wr.is_system = true
  AND wr.name = CASE
        WHEN wm.role = 'owner'  THEN 'Owner'
        WHEN wm.role = 'admin'  THEN 'Admin'
        WHEN wm.role = 'viewer' THEN 'Viewer'
        ELSE 'Admin'   -- legacy 'member' rows keep today's full access
      END;
`);

// ── policies ───────────────────────────────────────────────────────
w(`-- ---------------------------------------------------------------
-- 5. Per-operation RESTRICTIVE policies.
--
--    to_regclass guards mean a table from an unapplied module
--    migration is skipped rather than aborting the run.
--
--    CRITICAL: a RESTRICTIVE policy only ever subtracts. Postgres
--    grants nothing unless at least one PERMISSIVE policy matches, so
--    enabling RLS on a table that has none would return ZERO rows for
--    every non-service-role caller — including owners. Any table
--    without a permissive policy therefore gets a baseline
--    workspace-membership one first, preserving the access it has
--    today (and closing the tenant hole where RLS was simply off).
-- ---------------------------------------------------------------`);

const direct = [];
const children = [];
for (const r of RESOURCES) {
  for (const t of r.tables) {
    if (t.scope === "workspace") direct.push([t.name, r.key, r.module]);
    else children.push([t.name, t.scope.parent, t.scope.fk, r.key, r.module]);
  }
}

w(`
DO $crud$
DECLARE
  r RECORD;
  act RECORD;
BEGIN
  FOR r IN
    SELECT * FROM (VALUES`);
w(direct.map(([t, res, mod]) => `      ('${t}','${res}','${mod}')`).join(",\n"));
w(`    ) AS t(tbl, resource, module)
  LOOP
    IF to_regclass('public.'||r.tbl) IS NULL THEN CONTINUE; END IF;
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.tbl);

    -- Guarantee a permissive baseline so enabling RLS can't black the
    -- table out. Only added when the table has no permissive policy of
    -- its own; existing ones are left exactly as they are.
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'public' AND tablename = r.tbl AND permissive = 'PERMISSIVE'
    ) THEN
      EXECUTE format(
        'CREATE POLICY %I ON public.%I FOR ALL '
        'USING (public.is_active_workspace_member(workspace_id, auth.uid())) '
        'WITH CHECK (public.is_active_workspace_member(workspace_id, auth.uid()))',
        'members_baseline', r.tbl);
    END IF;

    FOR act IN
      SELECT * FROM (VALUES ${ACTIONS.map(
        (a) => `('${a}','${ACTION_SQL[a]}')`,
      ).join(", ")}) AS a(action, op)
    LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',
                     'crud_'||act.action, r.tbl);
      IF act.op = 'INSERT' THEN
        EXECUTE format(
          'CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR INSERT '
          'WITH CHECK (public.has_resource_permission(workspace_id, auth.uid(), %L, %L, %L))',
          'crud_'||act.action, r.tbl, r.resource, act.action, r.module);
      ELSIF act.op = 'UPDATE' THEN
        EXECUTE format(
          'CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR UPDATE '
          'USING (public.has_resource_permission(workspace_id, auth.uid(), %L, %L, %L)) '
          'WITH CHECK (public.has_resource_permission(workspace_id, auth.uid(), %L, %L, %L))',
          'crud_'||act.action, r.tbl, r.resource, act.action, r.module,
          r.resource, act.action, r.module);
      ELSE
        EXECUTE format(
          'CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR %s '
          'USING (public.has_resource_permission(workspace_id, auth.uid(), %L, %L, %L))',
          'crud_'||act.action, r.tbl, act.op, r.resource, act.action, r.module);
      END IF;
    END LOOP;
  END LOOP;
END
$crud$;

DO $crudc$
DECLARE
  r RECORD;
  act RECORD;
  pred TEXT;
BEGIN
  FOR r IN
    SELECT * FROM (VALUES`);
w(
  children
    .map(([t, p, fk, res, mod]) => `      ('${t}','${p}','${fk}','${res}','${mod}')`)
    .join(",\n"),
);
w(`    ) AS t(tbl, parent, fk, resource, module)
  LOOP
    IF to_regclass('public.'||r.tbl) IS NULL OR to_regclass('public.'||r.parent) IS NULL THEN
      CONTINUE;
    END IF;
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.tbl);

    IF NOT EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'public' AND tablename = r.tbl AND permissive = 'PERMISSIVE'
    ) THEN
      EXECUTE format(
        'CREATE POLICY %I ON public.%I FOR ALL '
        'USING (EXISTS (SELECT 1 FROM public.%I p WHERE p.id = %I.%I '
        '  AND public.is_active_workspace_member(p.workspace_id, auth.uid()))) '
        'WITH CHECK (EXISTS (SELECT 1 FROM public.%I p WHERE p.id = %I.%I '
        '  AND public.is_active_workspace_member(p.workspace_id, auth.uid())))',
        'members_baseline', r.tbl, r.parent, r.tbl, r.fk, r.parent, r.tbl, r.fk);
    END IF;

    FOR act IN
      SELECT * FROM (VALUES ${ACTIONS.map(
        (a) => `('${a}','${ACTION_SQL[a]}')`,
      ).join(", ")}) AS a(action, op)
    LOOP
      -- workspace resolved through the parent row
      pred := format(
        'EXISTS (SELECT 1 FROM public.%I p WHERE p.id = %I.%I '
        'AND public.has_resource_permission(p.workspace_id, auth.uid(), %L, %L, %L))',
        r.parent, r.tbl, r.fk, r.resource, act.action, r.module);
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',
                     'crud_'||act.action, r.tbl);
      IF act.op = 'INSERT' THEN
        EXECUTE format('CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR INSERT WITH CHECK (%s)',
                       'crud_'||act.action, r.tbl, pred);
      ELSIF act.op = 'UPDATE' THEN
        EXECUTE format('CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR UPDATE USING (%s) WITH CHECK (%s)',
                       'crud_'||act.action, r.tbl, pred, pred);
      ELSE
        EXECUTE format('CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR %s USING (%s)',
                       'crud_'||act.action, r.tbl, act.op, pred);
      END IF;
    END LOOP;
  END LOOP;
END
$crudc$;`);

