    const { data } = await supabase
      .from("commerce_chart_of_accounts")
      .select("id, account_code, account_name, account_type")
      .eq("workspace_id", workspaceId)
      .order("account_code");
    setAccounts((data as Account[]) || []);
  }, [supabase, workspaceId]);

  useEffect(() => {
    void fetchAccounts();
  }, [fetchAccounts]);

  const totals = useMemo(() => {
    const debit = lines.reduce((s, l) => s + (Number(l.debit) || 0), 0);
    const credit = lines.reduce((s, l) => s + (Number(l.credit) || 0), 0);
    return { debit, credit, balanced: Math.abs(debit - credit) < 0.005 && debit > 0 };
  }, [lines]);

  function setLine(i: number, patch: Partial<Line>) {
    setLines((prev) => prev.map((l, j) => (j === i ? { ...l, ...patch } : l)));
  }

  async function handlePost() {
    if (!workspaceId) return;
    if (!narration.trim()) {
      toast.error("A narration is required");
      return;
    }
    const filled = lines.filter((l) => l.account_id && (Number(l.debit) > 0 || Number(l.credit) > 0));
    if (filled.length < 2) {
      toast.error("A journal entry needs at least two lines");
      return;
    }
    if (!totals.balanced) {
      toast.error("Debits and credits must balance before posting");
      return;
    }
    setPosting(true);
    try {
      const res = await fetch("/api/accounting/journal", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          workspace_id: workspaceId,
          narration: narration.trim(),
          voucher_date: voucherDate,
          lines: filled.map((l) => ({
            account_id: l.account_id,
            debit: Number(l.debit) || 0,
            credit: Number(l.credit) || 0,
          })),
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to post entry");
      toast.success(`Voucher ${json.voucher.voucher_number} posted`);
      setNarration("");
      setLines([{ ...BLANK_LINE }, { ...BLANK_LINE }]);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to post entry");
    } finally {
      setPosting(false);
    }
  }

  return (
    <div className="p-(--page-padding-desktop)">
      <PageHeader
        title="New Journal Entry"
        description="Post a manual voucher. Debits and credits must balance — the ledger enforces it."
      />

      <Card>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-muted-foreground">Voucher date</label>
              <Input type="date" value={voucherDate} onChange={(e) => setVoucherDate(e.target.value)} />
            </div>
            <div className="space-y-1.5 sm:col-span-2">
              <label className="text-xs font-medium text-muted-foreground">Narration</label>
              <Textarea plain
                value={narration}
                onChange={(e) => setNarration(e.target.value)}
                placeholder="What is this entry for?"
                rows={1}
              />
            </div>
          </div>

          <div className="space-y-2">
            <div className="grid grid-cols-[1fr_8rem_8rem_2.5rem] gap-2 text-xs font-medium text-muted-foreground">
              <span>Account</span>
              <span className="text-right">Debit</span>
              <span className="text-right">Credit</span>
              <span />
            </div>
            {lines.map((l, i) => (
              <div key={i} className="grid grid-cols-[1fr_8rem_8rem_2.5rem] items-center gap-2">
                <Select value={l.account_id} onValueChange={(v) => v && setLine(i, { account_id: v })}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select account" />
                  </SelectTrigger>
                  <SelectContent searchPlaceholder="Search accounts...">
                    {accounts.map((a) => (
                      <SelectItem key={a.id} value={a.id}>
                        {a.account_code} — {a.account_name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Input
                  className="text-right"
                  type="number" min="0" placeholder="0.00"
                  value={l.debit}
                  onChange={(e) => setLine(i, { debit: e.target.value, credit: e.target.value ? "" : l.credit })}
                />
                <Input
                  className="text-right"
                  type="number" min="0" placeholder="0.00"
                  value={l.credit}
                  onChange={(e) => setLine(i, { credit: e.target.value, debit: e.target.value ? "" : l.debit })}
                />
                <IconAction
                  label="Remove line"
                  icon={<Trash2 />}
                  variant="ghost"
                  disabled={lines.length <= 2}
                  onClick={() => setLines((prev) => prev.filter((_, j) => j !== i))}
                />
              </div>
            ))}
            <IconAction label="Add line" icon={<Plus />} variant="outline" onClick={() => setLines((prev) => [...prev, { ...BLANK_LINE }])} />
          </div>

          <div className="flex items-center justify-between border-t border-border pt-4">
            <div
              className={`inline-flex h-7 items-center gap-1.5 border px-2.5 text-xs font-medium ${
                totals.balanced
                  ? "border-emerald-500/20 bg-emerald-500/10 text-emerald-400"
                  : "border-yellow-500/20 bg-yellow-500/10 text-yellow-400"
              }`}
            >
              <Scale className="size-3.5" />
              {totals.balanced
                ? "Balanced"
                : `Off by ${formatCurrency(Math.abs(totals.debit - totals.credit), defaultCurrency, { decimals: 2 })}`}
            </div>
            <div className="flex items-center gap-4 text-sm">
              <span className="text-muted-foreground">
                Dr <span className="font-medium text-foreground">{formatCurrency(totals.debit, defaultCurrency, { decimals: 2 })}</span>
              </span>
              <span className="text-muted-foreground">
                Cr <span className="font-medium text-foreground">{formatCurrency(totals.credit, defaultCurrency, { decimals: 2 })}</span>
              </span>
              <IconAction label="Post Voucher" icon={posting ? <Loader2 className="animate-spin" /> : <BookOpenCheck />} onClick={handlePost} disabled={posting || !totals.balanced} />
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { assertAffected } from '@/lib/supabase/affected-rows';
import { PageHeader } from '@/components/shared/page-header';
import { useWorkspace } from '@/hooks/use-workspace';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Laptop, Plus, Loader2 } from 'lucide-react';
import { AssignAssetForm } from '@/components/assets/assign-asset-form';
import { IconAction } from "@/components/ui/icon-action";

export default function AssetsPage() {
  const supabase = createClient();
  const { activeWorkspace, can } = useWorkspace();
  const canManagePeople = can('people_manage');

  const [loading, setLoading] = useState(true);
  const [assets, setAssets] = useState<any[]>([]);
  const [showAssign, setShowAssign] = useState(false);

  const fetchAssets = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const { data: rawData, error } = await supabase
        .from('employee_assets')
        .select(`*, workspace_members( id, user_id )`)
        .eq('workspace_id', activeWorkspace.id)
        .order('created_at', { ascending: false });

      if (error) throw error;

      // Two-step: enrich with profile data
      let data: any[] = rawData || [];
      if (data.length > 0) {
        const userIds = data.map((d: any) => d.workspace_members?.user_id).filter(Boolean);
        if (userIds.length > 0) {
          const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name').in('user_id', userIds);
          const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
          data = data.map((d: any) => ({
            ...d,
            workspace_members: d.workspace_members
              ? { ...d.workspace_members, profiles: profileMap[d.workspace_members.user_id] || null }
              : null,
          }));
        }
      }
      setAssets(data);
    } catch {
      toast.error('Failed to load assets');
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id]);

  useEffect(() => {
    fetchAssets();
  }, [fetchAssets]);

  if (!canManagePeople) {
    return (
      <div className="flex items-center justify-center h-[50vh]">
        <div className="text-center">
          <Laptop className="size-12 text-muted-foreground mx-auto mb-4" />
          <h2 className="text-lg font-medium text-foreground">Access Denied</h2>
          <p className="text-sm text-muted-foreground mt-1">You need people management permissions to view assets.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PageHeader 
        title="Asset Management" 
        description="Track company laptops, phones, and physical assets assigned to employees."
        action={
          <IconAction label="Assign Asset" icon={<Plus className="size-4 " />} onClick={() => setShowAssign(true)} className="bg-primary text-primary-foreground hover:bg-primary/90" />
        }
      />
      
      <AssignAssetForm 
        open={showAssign} 
        onOpenChange={setShowAssign} 
        onSaved={fetchAssets} 
      />

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border bg-muted/20 hover:bg-transparent">
              <TableHead>Asset Name</TableHead>
              <TableHead>Serial Number</TableHead>
              <TableHead>Assigned To</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-right">Action</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={5} className="text-center py-12">
                  <Loader2 className="size-6 animate-spin mx-auto text-primary" />
                </TableCell>
              </TableRow>
            ) : assets.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="text-center py-12 text-muted-foreground">
                  No assets assigned yet.
                </TableCell>
              </TableRow>
            ) : (
              assets.map((asset) => {
                const profile = Array.isArray(asset.workspace_members?.profiles) 
                  ? asset.workspace_members?.profiles[0] 
                  : asset.workspace_members?.profiles;
                  
                const isReturned = !!asset.returned_date;

                return (
                  <TableRow key={asset.id} className="border-border hover:bg-muted/50">
                    <TableCell className="font-medium">{asset.asset_name}</TableCell>
                    <TableCell className="text-muted-foreground font-mono text-xs">{asset.serial_number || 'N/A'}</TableCell>
                    <TableCell>
                      {profile?.full_name ? profile.full_name : <span className="text-muted-foreground italic">Unassigned</span>}
                    </TableCell>
                    <TableCell>
                      {isReturned ? (
                        <Badge variant="outline" className="text-emerald-500 border-emerald-500/20 bg-emerald-500/10">Returned</Badge>
                      ) : (
                        <Badge variant="outline" className="text-blue-500 border-blue-500/20 bg-blue-500/10">In Use</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      {!isReturned && (
                        <Button
                          variant="ghost" size="sm"
                          onClick={async () => {
                            try {
                              const result = await supabase
                                .from('employee_assets')
                                .update({ returned_date: new Date().toISOString().slice(0, 10) })
                                .eq('id', asset.id)
                                .select('id');
                              assertAffected(result, 'this asset', 'update');
                            } catch (err) {
                              toast.error(err instanceof Error ? err.message : 'Failed to mark returned');
                              return;
                            }
                            toast.success('Marked as returned');
                            void fetchAssets();
                          }}
                        >
                          Mark Returned
                        </Button>
                      )}
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { 
  Search, 
  Loader2, 
  CalendarClock, 
  MapPin, 
  Building2, 
  Home, 
  Briefcase, 
  FileCheck2, 
  Clock,
  Plus
} from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { PunchAction } from '@/components/attendance/punch-action';
import { AttendanceRequestModal } from '@/components/attendance/request-modal';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { LocationMapModal } from '@/components/attendance/location-map-modal';
import { sanitizeErrorMessage } from '@/lib/commerce/barcode-utils';
import { IconAction } from "@/components/ui/icon-action";

export default function AttendancePage() {
  const supabase = createClient();
  const { activeWorkspace, activeMember, can } = useWorkspace();
  const canManageAttendance = can('attendance_manage'); 

  const [activeTab, setActiveTab] = useState<'LOGS' | 'APPROVALS' | 'ANALYTICS'>('LOGS');
  const [records, setRecords] = useState<any[]>([]);
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showRequestModal, setShowRequestModal] = useState(false);

  // Leaflet Location Map Modal State
  const [mapModalOpen, setMapModalOpen] = useState(false);
  const [selectedLocationMap, setSelectedLocationMap] = useState<{
    location: any;
    title: string;
    employeeName: string;
    timestamp: string;
    workLocation: string;
    deviceInfo: any;
    ipAddress: string | null;
  } | null>(null);

  // Takes an options object rather than positional arguments: the device
  // and IP fields brought it to seven, at which point call sites become
  // unreadable and easy to mis-order.
  const openMapModal = (opts: {
    location: any;
    title: string;
    employeeName: string;
    timestamp: string;
    workLocation: string;
    deviceInfo?: any;
    ipAddress?: string | null;
  }) => {
    setSelectedLocationMap({
      location: opts.location,
      title: opts.title,
      employeeName: opts.employeeName,
      timestamp: opts.timestamp,
      workLocation: opts.workLocation,
      deviceInfo: opts.deviceInfo ?? null,
      ipAddress: opts.ipAddress ?? null,
    });
    setMapModalOpen(true);
  };

  // Analytics Metrics
  const [totalWorkingHours, setTotalWorkingHours] = useState(0);
  const [totalNetProductive, setTotalNetProductive] = useState(0);
  const [totalOvertimeHours, setTotalOvertimeHours] = useState(0);
  const [lateCount, setLateCount] = useState(0);

  const fetchAttendanceData = useCallback(async () => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    setLoading(true);

    try {
      // 1. Fetch Attendance Logs.
      // NOTE: workspace_members.user_id references auth.users, so a
      // PostgREST `workspace_members(profiles(...))` embed is
      // impossible — names are enriched with an explicit two-step
      // fetch (members, then profiles by user_id), like the
      // Employees page does.
      let query = supabase
        .from('attendance')
        .select('*')
        .eq('workspace_id', activeWorkspace.id)
        .order('attendance_date', { ascending: false });

      if (!canManageAttendance) {
        query = query.eq('workspace_member_id', activeMember.id);
      }

      // eslint-disable-next-line prefer-const -- `data` is reassigned in the fallback path below
      const { data: rawData, error } = await query;
      if (error) throw error;

      const { data: members } = await supabase
        .from('workspace_members')
        .select('id, user_id, role')
        .eq('workspace_id', activeWorkspace.id);
      const userIds = (members || []).map((m) => m.user_id);
      const { data: profileRows } = userIds.length
        ? await supabase.from('profiles').select('user_id, full_name, avatar_url').in('user_id', userIds)
        : { data: [] as { user_id: string; full_name: string | null; avatar_url: string | null }[] };
      const profileByUser: Record<string, unknown> = {};
      (profileRows || []).forEach((p) => { profileByUser[p.user_id] = p; });
      const memberProfilesMap: Record<string, unknown> = {};
      (members || []).forEach((m) => {
        memberProfilesMap[m.id] = { ...m, profiles: profileByUser[m.user_id] || null };
      });

      const data = (rawData || []).map((r) => ({
        ...r,
        workspace_members: memberProfilesMap[r.workspace_member_id] || null,
      }));

      const list = data || [];
      setRecords(list);

      // Compute Analytics
      let sumHours = 0;
      let sumNet = 0;
      let sumOt = 0;
      let lates = 0;

      list.forEach((r) => {
        sumHours += Number(r.working_hours || 0);
        sumNet += Number(r.net_productive_hours || r.working_hours || 0);
        sumOt += Number(r.overtime_hours || 0);
        if (r.status === 'Late') lates += 1;
      });

      setTotalWorkingHours(parseFloat(sumHours.toFixed(1)));
      setTotalNetProductive(parseFloat(sumNet.toFixed(1)));
      setTotalOvertimeHours(parseFloat(sumOt.toFixed(1)));
      setLateCount(lates);

      // 2. Fetch Regularization Requests
      let reqQuery = supabase
        .from('hr_attendance_requests')
        .select('*')
        .eq('workspace_id', activeWorkspace.id)
        .order('created_at', { ascending: false });

      if (!canManageAttendance) {
        reqQuery = reqQuery.eq('workspace_member_id', activeMember.id);
      }

      const { data: reqData, error: reqError } = await reqQuery;
      if (reqError) throw reqError;
      setRequests(
        (reqData || []).map((r) => ({
          ...r,
          workspace_members: memberProfilesMap[r.workspace_member_id] || null,
        }))
      );
    } catch (err: any) {
      toast.error(sanitizeErrorMessage(err, 'Failed to load attendance logs'));
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id, activeMember?.id, canManageAttendance]);

  useEffect(() => {
    fetchAttendanceData();
  }, [fetchAttendanceData]);

  const handleApprovalAction = async (requestId: string, status: 'APPROVED' | 'REJECTED') => {
    if (!activeMember?.id) return;
    try {
      const { data: request, error } = await supabase
        .from('hr_attendance_requests')
        .update({
          status,
          approved_by: activeMember.id,
        })
        .eq('id', requestId)
        .select()
        .single();

      if (error) throw error;

      // Approval APPLIES the regularization to the attendance record —
      // previously it only recoloured a badge and the record stayed
      // wrong forever.
      if (status === 'APPROVED' && request) {
        const patch: Record<string, unknown> = {};
        if (request.requested_punch_in) patch.punch_in_time = request.requested_punch_in;
        if (request.requested_punch_out) patch.punch_out_time = request.requested_punch_out;
        if (request.requested_punch_in && request.requested_punch_out) {
          patch.working_hours = (
            Math.max(
              0,
              new Date(request.requested_punch_out).getTime() -
                new Date(request.requested_punch_in).getTime()
            ) / 3600000
          ).toFixed(2);
        }
        if (Object.keys(patch).length > 0) {
          const { data: existing } = await supabase
            .from('attendance')
            .select('id')
            .eq('workspace_member_id', request.workspace_member_id)
            .eq('attendance_date', request.attendance_date)
            .maybeSingle();
          const { error: applyError } = existing
            ? await supabase.from('attendance').update(patch).eq('id', existing.id)
            : await supabase.from('attendance').insert({
                workspace_id: request.workspace_id,
                workspace_member_id: request.workspace_member_id,
                attendance_date: request.attendance_date,
                status: 'Present',
                ...patch,
              });
          if (applyError) {
            toast.error(sanitizeErrorMessage(applyError, 'Approved, but failed to apply to the attendance record'));
          }
        }
      }

      toast.success(`Request ${status.toLowerCase()} successfully`);
      fetchAttendanceData();
    } catch (err: any) {
      toast.error(sanitizeErrorMessage(err, 'Failed to update request status'));
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'Present': return <Badge className="bg-emerald-500/15 text-emerald-400 border-emerald-500/30">Present</Badge>;
      case 'Late': return <Badge className="bg-amber-500/15 text-amber-400 border-amber-500/30">Late Arrival</Badge>;
      case 'Half-Day': return <Badge className="bg-purple-500/15 text-purple-400 border-purple-500/30">Half-Day</Badge>;
      case 'Remote': return <Badge className="bg-blue-500/15 text-blue-400 border-blue-500/30">Work From Home</Badge>;
      default: return <Badge className="bg-muted text-foreground">{status || 'Present'}</Badge>;
    }
  };

  const getLocationIcon = (loc: string) => {
    if (loc === 'WFH') return <Home className="h-3.5 w-3.5 text-blue-400" />;
    if (loc === 'CLIENT_SITE') return <Briefcase className="h-3.5 w-3.5 text-purple-400" />;
    return <Building2 className="h-3.5 w-3.5 text-emerald-400" />;
  };

  const filteredRecords = records.filter((r) => {
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    const profile = Array.isArray(r.workspace_members?.profiles) 
      ? r.workspace_members?.profiles[0] 
      : r.workspace_members?.profiles;
    return profile?.full_name?.toLowerCase().includes(q) || r.status?.toLowerCase().includes(q);
  });

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto text-foreground">
      {/* Page Header with Punch Action & Request Trigger */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-card/80 p-5 rounded-3xl border border-border backdrop-blur-xl shadow-2xl">
        <div>
          <h1 className="text-xl font-bold text-foreground tracking-tight flex items-center gap-2.5">
            <Clock className="h-5 w-5 text-primary" />
            Attendance &amp; Time Tracking
          </h1>
          <p className="text-muted-foreground text-xs mt-0.5">
            Real-time punch logs, shift tracking &amp; break management.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <PunchAction onPunch={fetchAttendanceData} />
          <IconAction label="Regularization Request" icon={<Plus className="h-4 w-4 text-[#00aef0]" />} onClick={() => setShowRequestModal(true)}
            variant="outline"
            className="border-border bg-background text-foreground hover:text-foreground font-bold rounded-xl h-10 gap-1.5 text-xs" />
        </div>
      </div>

      {/* Overview Analytics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="p-4 bg-card border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Total Logged Hours</div>
          <div className="text-2xl font-extrabold text-foreground mt-1">{totalWorkingHours} hrs</div>
          <div className="text-[11px] text-muted-foreground mt-1">Gross working time</div>
        </div>

        <div className="p-4 bg-card border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Net Productive Hours</div>
          <div className="text-2xl font-extrabold text-[#00aef0] mt-1">{totalNetProductive} hrs</div>
          <div className="text-[11px] text-muted-foreground mt-1">Total Hours minus Break Time</div>
        </div>

        <div className="p-4 bg-card border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Approved Overtime</div>
          <div className="text-2xl font-extrabold text-emerald-400 mt-1">{totalOvertimeHours} hrs</div>
          <div className="text-[11px] text-muted-foreground mt-1">Comp-off eligible</div>
        </div>

        <div className="p-4 bg-card border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Late Arrivals</div>
          <div className="text-2xl font-extrabold text-amber-400 mt-1">{lateCount}</div>
          <div className="text-[11px] text-muted-foreground mt-1">Exceeding shift grace time</div>
        </div>
      </div>

      {/* Dynamic Tabs */}
      <div className="flex items-center justify-between border-b border-border pb-2">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setActiveTab('LOGS')}
            className={`px-4 py-2 text-xs font-bold rounded-xl transition-all ${
              activeTab === 'LOGS'
                ? 'bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            Live Attendance Logs &amp; Breaks
          </button>
          <button
            onClick={() => setActiveTab('APPROVALS')}
            className={`px-4 py-2 text-xs font-bold rounded-xl transition-all relative ${
              activeTab === 'APPROVALS'
                ? 'bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            Manager Approvals
            {requests.filter((r) => r.status === 'PENDING').length > 0 && (
              <span className="ml-1.5 px-1.5 py-0.5 rounded-full text-[10px] bg-rose-500 text-foreground font-extrabold">
                {requests.filter((r) => r.status === 'PENDING').length}
              </span>
            )}
          </button>
        </div>

        {activeTab === 'LOGS' && (
          <div className="relative w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
            <Input
              placeholder="Search employee..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 h-9 bg-background border-border text-foreground text-xs rounded-xl"
            />
          </div>
        )}
      </div>

      {/* TAB 1: Attendance & Break Logs */}
      {activeTab === 'LOGS' && (
        <div className="rounded-2xl border border-border bg-card/60 overflow-hidden shadow-2xl">
          {loading ? (
            <div className="flex items-center justify-center p-12 text-muted-foreground text-xs">
              <Loader2 className="h-5 w-5 animate-spin mr-2" />
              Loading Attendance Records...
            </div>
          ) : filteredRecords.length === 0 ? (
            <div className="flex flex-col items-center justify-center p-12 text-muted-foreground text-xs">
              <CalendarClock className="h-8 w-8 text-muted-foreground mb-2" />
              <span>No attendance logs found for this period.</span>
            </div>
          ) : (
            <Table>
              <TableHeader className="bg-background/80 text-xs text-muted-foreground border-b border-border">
                <TableRow>
                  <TableHead className="py-3.5">Date</TableHead>
                  <TableHead>Employee</TableHead>
                  <TableHead>Location</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Punch In</TableHead>
                  <TableHead>Punch Out</TableHead>
                  <TableHead>Break Hours</TableHead>
                  <TableHead className="text-right">Net Productive</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody className="divide-y divide-border/60 text-xs">
                {filteredRecords.map((r) => {
                  const profile = Array.isArray(r.workspace_members?.profiles) 
                    ? r.workspace_members?.profiles[0] 
                    : r.workspace_members?.profiles;
                  const name = profile?.full_name || 'Team Member';
                  const avatar = profile?.avatar_url || '';

                  return (
                    <TableRow key={r.id} className="hover:bg-muted/40 transition-colors">
                      <TableCell className="font-mono text-foreground font-bold">
                        {r.attendance_date}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Avatar className="h-7 w-7">
                            <AvatarImage src={avatar} />
                            <AvatarFallback className="bg-muted text-[10px] text-foreground">
                              {name.slice(0, 2).toUpperCase()}
                            </AvatarFallback>
                          </Avatar>
                          <span className="font-semibold text-foreground">{name}</span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <button
                          type="button"
                          onClick={() => openMapModal({
                            location: r.punch_in_location || r.punch_out_location,
                            title: `Attendance GPS Location (${r.work_location || 'OFFICE'})`,
                            employeeName: name,
                            timestamp: r.punch_in_time ? new Date(r.punch_in_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : r.attendance_date,
                            workLocation: r.work_location || 'OFFICE',
                            deviceInfo: r.punch_in_device_json || r.punch_out_device_json,
                            ipAddress: r.punch_in_ip || r.punch_out_ip,
                          })}
                          className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-foreground hover:bg-muted/80 transition-colors font-medium text-xs border border-border/60"
                          title="Click to view Leaflet Location Map"
                        >
                          {getLocationIcon(r.work_location)}
                          <span>{r.work_location || 'OFFICE'}</span>
                          <MapPin className="h-3 w-3 text-primary ml-0.5" />
                        </button>
                      </TableCell>
                      <TableCell>{getStatusBadge(r.status)}</TableCell>
                      <TableCell>
                        {r.punch_in_time ? (
                          <div className="flex items-center gap-1.5 font-mono text-foreground">
                            <span>{new Date(r.punch_in_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                            <button
                              type="button"
                              onClick={() => openMapModal({
                                location: r.punch_in_location,
                                title: "Punch In GPS Location",
                                employeeName: name,
                                timestamp: new Date(r.punch_in_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                                workLocation: r.work_location || 'OFFICE',
                                deviceInfo: r.punch_in_device_json,
                                ipAddress: r.punch_in_ip,
                              })}
                              className="p-1 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/10 rounded-md transition-colors"
                              title="View Leaflet GPS Map"
                            >
                              <MapPin className="h-3.5 w-3.5" />
                            </button>
                          </div>
                        ) : '—'}
                      </TableCell>
                      <TableCell>
                        {r.punch_out_time ? (
                          <div className="flex items-center gap-1.5 font-mono text-foreground">
                            <span>{new Date(r.punch_out_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                            <button
                              type="button"
                              onClick={() => openMapModal({
                                location: r.punch_out_location,
                                title: "Punch Out GPS Location",
                                employeeName: name,
                                timestamp: new Date(r.punch_out_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                                workLocation: r.work_location || 'OFFICE',
                                deviceInfo: r.punch_out_device_json,
                                ipAddress: r.punch_out_ip,
                              })}
                              className="p-1 text-rose-600 dark:text-rose-400 hover:bg-rose-500/10 rounded-md transition-colors"
                              title="View Leaflet GPS Map"
                            >
                              <MapPin className="h-3.5 w-3.5" />
                            </button>
                          </div>
                        ) : '—'}
                      </TableCell>
                      <TableCell className="font-mono text-amber-400">
                        {r.break_hours ? `${r.break_hours} hrs` : '0 hrs'}
                      </TableCell>
                      <TableCell className="text-right font-mono font-extrabold text-[#00aef0]">
                        {r.net_productive_hours || r.working_hours || 0} hrs
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          )}
        </div>
      )}

      {/* TAB 2: Manager Approvals Hub */}
      {activeTab === 'APPROVALS' && (
        <div className="rounded-2xl border border-border bg-card/60 overflow-hidden shadow-2xl p-4">
          <h2 className="text-sm font-bold text-foreground mb-3 flex items-center gap-2">
            <FileCheck2 className="h-4 w-4 text-[#00aef0]" />
            Attendance Regularization &amp; Correction Requests
          </h2>

          {requests.length === 0 ? (
            <div className="py-12 text-center text-muted-foreground text-xs">
              No regularization requests submitted yet.
            </div>
          ) : (
            <Table>
              <TableHeader className="bg-background/80 text-xs text-muted-foreground border-b border-border">
                <TableRow>
                  <TableHead>Employee</TableHead>
                  <TableHead>Request Type</TableHead>
                  <TableHead>Date</TableHead>
                  <TableHead>Requested Time</TableHead>
                  <TableHead>Reason</TableHead>
                  <TableHead>Status</TableHead>
                  {canManageAttendance && <TableHead className="text-right">Actions</TableHead>}
                </TableRow>
              </TableHeader>
              <TableBody className="divide-y divide-border/60 text-xs">
                {requests.map((req) => (
                  <TableRow key={req.id}>
                    <TableCell className="font-semibold text-foreground">
                      {req.workspace_members?.profiles?.full_name || 'Employee'}
                    </TableCell>
                    <TableCell>
                      <span className="font-mono text-[11px] font-bold px-2 py-0.5 rounded-none bg-muted text-[#00aef0]">
                        {req.request_type}
                      </span>
                    </TableCell>
                    <TableCell className="font-mono text-muted-foreground">{req.attendance_date}</TableCell>
                    <TableCell className="font-mono text-foreground">
                      {req.requested_punch_in ? new Date(req.requested_punch_in).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—'}
                      {' → '}
                      {req.requested_punch_out ? new Date(req.requested_punch_out).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—'}
                    </TableCell>
                    <TableCell className="text-foreground max-w-xs truncate">{req.reason}</TableCell>
                    <TableCell>
                      {req.status === 'APPROVED' ? (
                        <Badge className="bg-emerald-500/15 text-emerald-400">Approved</Badge>
                      ) : req.status === 'REJECTED' ? (
                        <Badge className="bg-rose-500/15 text-rose-400">Rejected</Badge>
                      ) : (
                        <Badge className="bg-amber-500/15 text-amber-400">Pending Approval</Badge>
                      )}
                    </TableCell>
                    {canManageAttendance && (
                      <TableCell className="text-right space-x-1.5">
                        {req.status === 'PENDING' && (
                          <>
                            <Button
                              onClick={() => handleApprovalAction(req.id, 'APPROVED')}
                              className="h-7 text-xs bg-emerald-600 hover:bg-emerald-700 text-foreground font-bold px-2.5 rounded-lg"
                            >
                              Approve
                            </Button>
                            <Button
                              onClick={() => handleApprovalAction(req.id, 'REJECTED')}
                              variant="destructive"
                              className="h-7 text-xs font-bold px-2.5 rounded-lg"
                            >
                              Reject
                            </Button>
                          </>
                        )}
                      </TableCell>
                    )}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </div>
      )}

      {/* Regularization Modal */}
      <AttendanceRequestModal
        open={showRequestModal}
        onOpenChange={setShowRequestModal}
        onSubmitted={fetchAttendanceData}
      />

      {/* Leaflet GPS Location Map Modal */}
      <LocationMapModal
        open={mapModalOpen}
        onOpenChange={setMapModalOpen}
        location={selectedLocationMap?.location || null}
        title={selectedLocationMap?.title || "GPS Location Map"}
        employeeName={selectedLocationMap?.employeeName}
        timestamp={selectedLocationMap?.timestamp}
        workLocation={selectedLocationMap?.workLocation}
        deviceInfo={selectedLocationMap?.deviceInfo}
        ipAddress={selectedLocationMap?.ipAddress}
      />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import {
  BookOpen,
  RefreshCw,
  Landmark,
  Banknote,
  ArrowUpRight,
  FileCheck,
  CheckCircle2,
  Calendar,
  Layers,
} from "lucide-react";
import { toast } from "sonner";
import { IconAction } from "@/components/ui/icon-action";

export default function AccountingLedgerPage() {
  const { activeWorkspace } = useWorkspace();
  const [activeTab, setActiveTab] = useState<"DAYBOOK" | "ACCOUNTS">("DAYBOOK");
  const [accounts, setAccounts] = useState<any[]>([]);
  const [journals, setJournals] = useState<any[]>([]);
  const [summary, setSummary] = useState<{
    cash_in_hand: number;
    bank_accounts: number;
    customer_khata: number;
    total_sales_revenue: number;
  }>({
    cash_in_hand: 0,
    bank_accounts: 0,
    customer_khata: 0,
    total_sales_revenue: 0,
  });
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const res = await fetch(
        `/api/commerce/accounting?workspace_id=${activeWorkspace.id}`
      );
      const json = await res.json();
      if (res.ok) {
        setAccounts(json.accounts || []);
        setJournals(json.journal_vouchers || []);
        if (json.summary) {
          setSummary(json.summary);
        }
      }
    } catch {
      toast.error("Failed to load accounting ledger");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [activeWorkspace?.id]);

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <BookOpen className="h-6 w-6 text-[#00aef0]" />
            Automated Accounting & Double-Entry Ledger
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Real-time journal vouchers posted automatically from POS billing payment modes.
          </p>
        </div>
        <IconAction label="Refresh Books" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchData}
          variant="outline"
          className="border-border text-foreground gap-1.5 rounded-xl h-11" />
      </div>

      {/* Account Balance Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
        <div className="p-4 bg-card/80 border border-border rounded-2xl flex items-center gap-3">
          <div className="h-10 w-10 rounded-xl bg-emerald-500/10 text-emerald-400 flex items-center justify-center font-bold">
            <Banknote className="h-5 w-5" />
          </div>
          <div>
            <div className="text-xs text-muted-foreground font-medium">Cash in Hand</div>
            <div className="text-lg font-bold text-foreground mt-0.5">
              ₹{Number(summary.cash_in_hand || 0).toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </div>
          </div>
        </div>

        <div className="p-4 bg-card/80 border border-border rounded-2xl flex items-center gap-3">
          <div className="h-10 w-10 rounded-xl bg-sky-500/10 text-sky-400 flex items-center justify-center font-bold">
            <Landmark className="h-5 w-5" />
          </div>
          <div>
            <div className="text-xs text-muted-foreground font-medium">Bank Accounts</div>
            <div className="text-lg font-bold text-foreground mt-0.5">
              ₹{Number(summary.bank_accounts || 0).toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </div>
          </div>
        </div>

        <div className="p-4 bg-card/80 border border-border rounded-2xl flex items-center gap-3">
          <div className="h-10 w-10 rounded-xl bg-amber-500/10 text-amber-400 flex items-center justify-center font-bold">
            <BookOpen className="h-5 w-5" />
          </div>
          <div>
            <div className="text-xs text-muted-foreground font-medium">Customer Khata (Receivable)</div>
            <div className="text-lg font-bold text-amber-400 mt-0.5">
              ₹{Number(summary.customer_khata || 0).toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </div>
          </div>
        </div>

        <div className="p-4 bg-card/80 border border-border rounded-2xl flex items-center gap-3">
          <div className="h-10 w-10 rounded-xl bg-purple-500/10 text-purple-400 flex items-center justify-center font-bold">
            <ArrowUpRight className="h-5 w-5" />
          </div>
          <div>
            <div className="text-xs text-muted-foreground font-medium">Total Sales Revenue</div>
            <div className="text-lg font-bold text-foreground mt-0.5">
              ₹{Number(summary.total_sales_revenue || 0).toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </div>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex items-center gap-2 border-b border-border pb-2">
        <button
          onClick={() => setActiveTab("DAYBOOK")}
          className={`px-4 py-2 text-sm font-semibold rounded-xl transition-all ${
            activeTab === "DAYBOOK"
              ? "bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20"
              : "text-muted-foreground hover:text-foreground"
          }`}
        >
          General Daybook & Journal Vouchers ({journals.length})
        </button>
        <button
          onClick={() => setActiveTab("ACCOUNTS")}
          className={`px-4 py-2 text-sm font-semibold rounded-xl transition-all ${
            activeTab === "ACCOUNTS"
              ? "bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20"
              : "text-muted-foreground hover:text-foreground"
          }`}
        >
          Chart of Accounts (GL) ({accounts.length})
        </button>
      </div>

      {/* Content based on Active Tab */}
      {activeTab === "DAYBOOK" ? (
        <div className="space-y-4">
          {loading ? (
            <div className="py-12 text-center text-muted-foreground text-sm bg-card/50 rounded-2xl border border-border">
              Loading POS Journal Vouchers...
            </div>
          ) : journals.length === 0 ? (
            <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl p-12 text-center text-muted-foreground space-y-3">
              <BookOpen className="h-10 w-10 mx-auto text-muted-foreground" />
              <p className="text-base font-semibold text-foreground">Automated Accounting Active</p>
              <p className="text-xs text-muted-foreground max-w-md mx-auto">
                Every sales transaction completed on the POS Terminal will automatically generate double-entry Debit & Credit vouchers and post to your General Ledger.
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              {journals.map((voucher) => (
                <div
                  key={voucher.id}
                  className="bg-card/80 border border-border rounded-2xl p-4 space-y-3 shadow-md"
                >
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-border/80 pb-3">
                    <div className="flex items-center gap-2.5">
                      <span className="bg-[#00aef0]/10 text-[#00aef0] px-2.5 py-0.5 rounded-lg text-xs font-mono font-bold">
                        {voucher.voucher_number}
                      </span>
                      <span className="text-xs text-muted-foreground font-medium">
                        Ref: <strong className="text-foreground font-mono">{voucher.reference_type}</strong>
                      </span>
                      <span className="inline-flex items-center px-2 py-0.5 rounded-md text-[10px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                        <CheckCircle2 className="h-3 w-3 mr-1" />
                        POSTED
                      </span>
                    </div>

                    <div className="flex items-center gap-3 text-xs text-muted-foreground font-mono">
                      <span className="flex items-center gap-1">
                        <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                        {new Date(voucher.created_at).toLocaleString()}
                      </span>
                    </div>
                  </div>

                  <p className="text-xs text-foreground font-medium">
                    {voucher.narration || "POS Sales Automated Double-Entry Voucher"}
                  </p>

                  {/* Journal Debit / Credit Breakdown */}
                  <div className="rounded-xl border border-border bg-background overflow-hidden">
                    <table className="w-full text-left text-xs text-foreground">
                      <thead className="bg-card/90 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
                        <tr>
                          <th className="py-2 px-3">GL Ledger Account</th>
                          <th className="py-2 px-3 text-right">Debit (Dr)</th>
                          <th className="py-2 px-3 text-right">Credit (Cr)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/60">
                        {(voucher.items || []).map((item: any, idx: number) => (
                          <tr key={item.id || idx}>
                            <td className="py-2 px-3 font-semibold text-foreground">
                              <span className="font-mono text-[#00aef0] mr-2">
                                [{item.account?.account_code || "1000"}]
                              </span>
                              {item.account?.account_name || "General Ledger Account"}
                            </td>
                            <td className="py-2 px-3 text-right font-mono font-bold text-emerald-400">
                              {Number(item.debit_amount || 0) > 0
                                ? `₹${Number(item.debit_amount).toFixed(2)}`
                                : "-"}
                            </td>
                            <td className="py-2 px-3 text-right font-mono font-bold text-sky-400">
                              {Number(item.credit_amount || 0) > 0
                                ? `₹${Number(item.credit_amount).toFixed(2)}`
                                : "-"}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      ) : (
        <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm text-foreground">
              <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
                <tr>
                  <th className="py-3.5 px-4">Code</th>
                  <th className="py-3.5 px-4">Ledger Account Name</th>
                  <th className="py-3.5 px-4">Account Type</th>
                  <th className="py-3.5 px-4">Category</th>
                  <th className="py-3.5 px-4 text-right">Current Balance</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/60">
                {accounts.map((acc) => (
                  <tr key={acc.id || acc.account_code} className="hover:bg-muted/40 transition-colors">
                    <td className="py-3.5 px-4 font-mono font-bold text-[#00aef0]">
                      {acc.account_code}
                    </td>
                    <td className="py-3.5 px-4 font-semibold text-foreground">
                      {acc.account_name}
                    </td>
                    <td className="py-3.5 px-4 text-xs font-mono text-muted-foreground">
                      <span className="bg-muted px-2 py-0.5 rounded-lg border border-border">
                        {acc.account_type}
                      </span>
                    </td>
                    <td className="py-3.5 px-4 text-xs uppercase text-muted-foreground font-mono">
                      {acc.sub_category || acc.category || "GENERAL"}
                    </td>
                    <td className="py-3.5 px-4 text-right font-extrabold text-foreground">
                      ₹{Number(acc.current_balance || acc.balance || 0).toLocaleString("en-IN", {
                        minimumFractionDigits: 2,
                      })}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { BulkEntryDialog } from '@/components/ui/bulk-entry-dialog';
import { IconAction } from '@/components/ui/icon-action';
import { PageHeader } from '@/components/shared/page-header';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Plus, Layers, Search, Bookmark, Loader2, Edit3, Trash2 } from 'lucide-react';
import { toast } from 'sonner';

export default function BrandsPage() {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [brands, setBrands] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  
  // Modal states
  const [openModal, setOpenModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [bulkAddOpen, setBulkAddOpen] = useState(false);
  const [editingBrand, setEditingBrand] = useState<any | null>(null);

  // Form State
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');

  const fetchBrands = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const { data, error } = await supabase
        .from('brands')
        .select('*')
        .eq('workspace_id', activeWorkspace.id)
        .order('name', { ascending: true });

      if (error) {
        // Fallback: derive brands from products. The table is
        // `commerce_products` (there is no `products`) and the column is
        // `manufacturer_name`, so this fallback previously errored too and
        // always produced an empty list.
        const { data: prodData } = await supabase
          .from('commerce_products')
          .select('manufacturer_name')
          .eq('workspace_id', activeWorkspace.id);

        const uniqueBrands = Array.from(
          new Set((prodData || []).map(p => p.manufacturer_name).filter(Boolean))
        ).map((bName, idx) => ({
          id: `brand_${idx}`,
          name: bName,
          description: 'Product Brand / Manufacturer',
          created_at: new Date().toISOString()
        }));

        setBrands(uniqueBrands);
      } else {
        setBrands(data || []);
      }
    } catch {
      setBrands([]);
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id]);

  useEffect(() => {
    fetchBrands();
  }, [fetchBrands]);

  const handleOpenAdd = () => {
    setEditingBrand(null);
    setName('');
    setDescription('');
    setOpenModal(true);
  };

  const handleOpenEdit = (brand: any) => {
    setEditingBrand(brand);
    setName(brand.name || '');
    setDescription(brand.description || '');
    setOpenModal(true);
  };

  /** Insert every typed or pasted row in one statement. */
  const bulkAdd = async (rows: Record<string, string>[]) => {
    const { error } = await supabase.from('brands').insert(
      rows.map((r) => ({ workspace_id: activeWorkspace!.id, name: r.name.trim(), description: r.description?.trim() || '' }))
    );
    if (error) throw error;
    toast.success(`Added ${rows.length} brand${rows.length === 1 ? '' : 's'}.`);
    fetchBrands();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !name.trim()) return;

    setSaving(true);
    try {
      if (editingBrand?.id && !editingBrand.id.startsWith('brand_')) {
        const { error } = await supabase
          .from('brands')
          .update({ name: name.trim(), description: description.trim() })
          .eq('id', editingBrand.id);

        if (error) throw error;
        toast.success('Brand updated successfully');
      } else {
        const { error } = await supabase
          .from('brands')
          .insert({
            workspace_id: activeWorkspace.id,
            name: name.trim(),
            description: description.trim()
          });

        if (error) throw error;
        toast.success('Brand created successfully');
      }

      setOpenModal(false);
      fetchBrands();
    } catch (err: any) {
      toast.error(err.message || 'Failed to save brand');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this brand?')) return;
    try {
      const { error } = await supabase.from('brands').delete().eq('id', id);
      if (error) throw error;
      toast.success('Brand deleted');
      fetchBrands();
    } catch (err: any) {
      toast.error(err.message || 'Failed to delete brand');
    }
  };

  const filteredBrands = brands.filter(b =>
    b.name?.toLowerCase().includes(search.toLowerCase()) ||
    b.description?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <PageHeader
        title="Product Brands"
        description="Manage product manufacturers, suppliers, and brand catalogs."
        action={
          <div className="flex items-center gap-2">
            <IconAction label="Bulk add" icon={<Layers className="size-4 " />} variant="outline" onClick={() => setBulkAddOpen(true)} />
            <IconAction label="Add Brand" icon={<Plus className="size-4 " />} onClick={handleOpenAdd} className="bg-primary text-primary-foreground" />
          </div>
        }
      />

      <div className="flex items-center gap-2 max-w-sm">
        <div className="relative w-full">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input
            placeholder="Search brands..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-8 bg-card border-border"
          />
        </div>
      </div>

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent">
              <TableHead className="text-muted-foreground">Brand / Manufacturer</TableHead>
              <TableHead className="text-muted-foreground">Description</TableHead>
              <TableHead className="text-muted-foreground w-24 text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-12">
                  <Loader2 className="size-6 animate-spin mx-auto text-primary" />
                  <p className="text-sm text-muted-foreground mt-2">Loading brands...</p>
                </TableCell>
              </TableRow>
            ) : filteredBrands.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-12">
                  <Bookmark className="size-8 mx-auto text-muted-foreground mb-2" />
                  <p className="text-sm text-muted-foreground">No brands found.</p>
                </TableCell>
              </TableRow>
            ) : (
              filteredBrands.map(brand => (
                <TableRow key={brand.id} className="border-border hover:bg-muted/50">
                  <TableCell className="font-medium text-foreground">{brand.name}</TableCell>
                  <TableCell className="text-muted-foreground text-sm">{brand.description || '-'}</TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-1">
                      <IconAction
                        label={`Edit ${brand.name}`}
                        icon={<Edit3 className="size-4" />}
                        onClick={() => handleOpenEdit(brand)}
                      />
                      <IconAction
                        label={`Delete ${brand.name}`}
                        icon={<Trash2 className="size-4" />}
                        onClick={() => handleDelete(brand.id)}
                        destructive
                      />
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={openModal} onOpenChange={setOpenModal}>
        <DialogContent className="sm:max-w-[480px] bg-card border-border rounded-xl p-6 shadow-2xl">
          <DialogHeader>
            <DialogTitle>{editingBrand ? 'Edit Brand' : 'Add Brand'}</DialogTitle>
            <DialogDescription>Define brand names and details for your products.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleSubmit} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Brand / Manufacturer Name <span className="text-red-500">*</span></Label>
              <Input
                placeholder="e.g. Nike, Apple, Samsung, Ray-Ban"
                value={name}
                onChange={e => setName(e.target.value)}
                required
                className="bg-card border-border"
              />
            </div>

            <div className="space-y-2">
              <Label>Description</Label>
              <Input
                placeholder="Optional brand notes..."
                value={description}
                onChange={e => setDescription(e.target.value)}
                className="bg-card border-border"
              />
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setOpenModal(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null}
                {editingBrand ? 'Save Changes' : 'Create Brand'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <BulkEntryDialog
        open={bulkAddOpen}
        onOpenChange={setBulkAddOpen}
        title="Add several brands"
        scope="brands"
        workspaceId={activeWorkspace?.id}
        noun="brand"
        columns={[
          { key: 'name', label: 'Brand name', required: true, placeholder: 'e.g. Samsung' },
          { key: 'description', label: 'Description', placeholder: 'Optional' },
        ]}
        onSubmit={bulkAdd}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { BulkEntryDialog } from '@/components/ui/bulk-entry-dialog';
import { IconAction } from '@/components/ui/icon-action';
import { PageHeader } from '@/components/shared/page-header';
