} from '@/components/ui/dialog';
import { Plus, Layers, Search, Tag, Loader2, Edit3, Trash2 } from 'lucide-react';
import { toast } from 'sonner';

export default function CategoriesPage() {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [categories, setCategories] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  
  // Modal states
  const [openModal, setOpenModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [bulkAddOpen, setBulkAddOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<any | null>(null);

  // Form State
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');

  const fetchCategories = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const { data, error } = await supabase
        .from('categories')
        .select('*')
        .eq('workspace_id', activeWorkspace.id)
        .order('name', { ascending: true });

      if (error) {
        // Fallback: derive categories from products. The table is
        // `commerce_products` (there is no `products`) and the category is a
        // `category_id` FK rather than a name column, so this fallback
        // previously errored too and always produced an empty list.
        const { data: prodData } = await supabase
          .from('commerce_products')
          .select('category_id, commerce_categories(name)')
          .eq('workspace_id', activeWorkspace.id);

        const uniqueCats = Array.from(
          new Set(
            (prodData || [])
              .map((p) => (p.commerce_categories as { name?: string } | null)?.name)
              .filter(Boolean)
          )
        ).map((catName, idx) => ({
          id: `cat_${idx}`,
          name: catName,
          description: 'Product Category',
          created_at: new Date().toISOString()
        }));

        setCategories(uniqueCats);
      } else {
        setCategories(data || []);
      }
    } catch {
      setCategories([]);
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id]);

  useEffect(() => {
    fetchCategories();
  }, [fetchCategories]);

  const handleOpenAdd = () => {
    setEditingCategory(null);
    setName('');
    setDescription('');
    setOpenModal(true);
  };

  const handleOpenEdit = (cat: any) => {
    setEditingCategory(cat);
    setName(cat.name || '');
    setDescription(cat.description || '');
    setOpenModal(true);
  };

  /** Insert every typed or pasted row in one statement. */
  const bulkAdd = async (rows: Record<string, string>[]) => {
    const { error } = await supabase.from('categories').insert(
      rows.map((r) => ({ workspace_id: activeWorkspace!.id, name: r.name.trim(), description: r.description?.trim() || '' }))
    );
    if (error) throw error;
    toast.success(`Added ${rows.length} category${rows.length === 1 ? '' : 's'}.`);
    fetchCategories();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !name.trim()) return;

    setSaving(true);
    try {
      if (editingCategory?.id && !editingCategory.id.startsWith('cat_')) {
        const { error } = await supabase
          .from('categories')
          .update({ name: name.trim(), description: description.trim() })
          .eq('id', editingCategory.id);

        if (error) throw error;
        toast.success('Category updated successfully');
      } else {
        const { error } = await supabase
          .from('categories')
          .insert({
            workspace_id: activeWorkspace.id,
            name: name.trim(),
            description: description.trim()
          });

        if (error) throw error;
        toast.success('Category created successfully');
      }

      setOpenModal(false);
      fetchCategories();
    } catch (err: any) {
      toast.error(err.message || 'Failed to save category');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this category?')) return;
    try {
      const { error } = await supabase.from('categories').delete().eq('id', id);
      if (error) throw error;
      toast.success('Category deleted');
      fetchCategories();
    } catch (err: any) {
      toast.error(err.message || 'Failed to delete category');
    }
  };

  const filteredCategories = categories.filter(c =>
    c.name?.toLowerCase().includes(search.toLowerCase()) ||
    c.description?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <PageHeader
        title="Product Categories"
        description="Organize your store inventory into structured product categories."
        action={
          <div className="flex items-center gap-2">
            <IconAction label="Bulk add" icon={<Layers className="size-4 " />} variant="outline" onClick={() => setBulkAddOpen(true)} />
            <IconAction label="Add Category" icon={<Plus className="size-4 " />} onClick={handleOpenAdd} className="bg-primary text-primary-foreground" />
          </div>
        }
      />

      <div className="flex items-center gap-2 max-w-sm">
        <div className="relative w-full">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input
            placeholder="Search categories..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-8 bg-card border-border"
          />
        </div>
      </div>

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent">
              <TableHead className="text-muted-foreground">Category Name</TableHead>
              <TableHead className="text-muted-foreground">Description</TableHead>
              <TableHead className="text-muted-foreground w-24 text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-12">
                  <Loader2 className="size-6 animate-spin mx-auto text-primary" />
                  <p className="text-sm text-muted-foreground mt-2">Loading categories...</p>
                </TableCell>
              </TableRow>
            ) : filteredCategories.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-12">
                  <Tag className="size-8 mx-auto text-muted-foreground mb-2" />
                  <p className="text-sm text-muted-foreground">No categories found.</p>
                </TableCell>
              </TableRow>
            ) : (
              filteredCategories.map(cat => (
                <TableRow key={cat.id} className="border-border hover:bg-muted/50">
                  <TableCell className="font-medium text-foreground">{cat.name}</TableCell>
                  <TableCell className="text-muted-foreground text-sm">{cat.description || '-'}</TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-1">
                      <IconAction
                        label={`Edit ${cat.name}`}
                        icon={<Edit3 className="size-4" />}
                        onClick={() => handleOpenEdit(cat)}
                      />
                      <IconAction
                        label={`Delete ${cat.name}`}
                        icon={<Trash2 className="size-4" />}
                        onClick={() => handleDelete(cat.id)}
                        destructive
                      />
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={openModal} onOpenChange={setOpenModal}>
        <DialogContent className="sm:max-w-[480px] bg-card border-border rounded-xl p-6 shadow-2xl">
          <DialogHeader>
            <DialogTitle>{editingCategory ? 'Edit Category' : 'Add Category'}</DialogTitle>
            <DialogDescription>Define category names and descriptions for your catalog.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleSubmit} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Category Name <span className="text-red-500">*</span></Label>
              <Input
                placeholder="e.g. Apparel, Electronics, Groceries"
                value={name}
                onChange={e => setName(e.target.value)}
                required
                className="bg-card border-border"
              />
            </div>

            <div className="space-y-2">
              <Label>Description</Label>
              <Input
                placeholder="Optional category description..."
                value={description}
                onChange={e => setDescription(e.target.value)}
                className="bg-card border-border"
              />
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setOpenModal(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null}
                {editingCategory ? 'Save Changes' : 'Create Category'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <BulkEntryDialog
        open={bulkAddOpen}
        onOpenChange={setBulkAddOpen}
        title="Add several categorys"
        scope="categories"
        workspaceId={activeWorkspace?.id}
        noun="category"
        columns={[
          { key: 'name', label: 'Category name', required: true, placeholder: 'e.g. Electronics' },
          { key: 'description', label: 'Description', placeholder: 'Optional' },
        ]}
        onSubmit={bulkAdd}
      />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { 
  FileText, 
  RefreshCw, 
  Search, 
  Download, 
  QrCode, 
  ShieldCheck
} from "lucide-react";
import { toast } from "sonner";
import { sanitizeErrorMessage } from "@/lib/commerce/barcode-utils";
import { IconAction } from "@/components/ui/icon-action";

export default function GstReportsPage() {
  const { activeWorkspace } = useWorkspace();
  const [activeTab, setActiveTab] = useState<"GSTR1" | "GSTR2B" | "TAX_SUMMARY">("GSTR1");
  const [summary, setSummary] = useState<any>({
    totalTaxableSales: 0,
    totalOutputGst: 0,
    totalInputGst: 0,
    netGstLiability: 0,
    totalCgst: 0,
    totalSgst: 0,
    totalIgst: 0,
    activeInvoiceCount: 0,
  });
  const [entries, setEntries] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");

  // E-Invoice QR Modal State
  const [selectedEInvoice, setSelectedEInvoice] = useState<any | null>(null);

  const fetchGstData = async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/commerce/gst/reports?workspace_id=${activeWorkspace.id}`);
      const json = await res.json();
      if (res.ok && json.summary) {
        setSummary(json.summary);
        setEntries(json.entries || []);
      }
    } catch (err: any) {
      const msg = sanitizeErrorMessage(err, "Failed to load GST reports");
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGstData();
  }, [activeWorkspace?.id]);

  const handleExportCsv = () => {
    try {
      const headers = ["Invoice No", "Date", "Party Name", "GSTIN", "HSN/SAC", "Taxable Value", "CGST", "SGST", "IGST", "Total GST", "IRN"];
      const rows = entries.map((e) => [
        e.invoice_number,
        e.invoice_date,
        `"${e.party_name || ""}"`,
        e.gstin || "",
        e.hsn_sac_code || "",
        e.taxable_amount,
        e.cgst_amount,
        e.sgst_amount,
        e.igst_amount,
        e.total_gst,
        e.irn_number || "",
      ]);

      const csvContent = [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.setAttribute("href", url);
      link.setAttribute("download", `GSTR1_Report_${Date.now()}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      toast.success("GSTR-1 report exported successfully!");
    } catch (e: any) {
      toast.error(sanitizeErrorMessage(e, "Export failed"));
    }
  };

  const filteredEntries = entries.filter((e) => {
    if (activeTab === "GSTR1" && e.ledger_type !== "OUTPUT") return false;
    if (activeTab === "GSTR2B" && e.ledger_type !== "INPUT") return false;

    const q = query.toLowerCase();
    return (
      e.invoice_number?.toLowerCase().includes(q) ||
      e.party_name?.toLowerCase().includes(q) ||
      e.gstin?.toLowerCase().includes(q)
    );
  });

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <FileText className="h-6 w-6 text-[#00aef0]" />
            GST Filing & E-Invoicing Engine
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            GSTR-1 Sales Report, GSTR-2B Input Tax Credit (ITC), CGST/SGST/IGST splitting, and B2B IRN generation.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <IconAction label="Refresh" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchGstData} variant="outline" className="border-border text-foreground gap-1.5 rounded-xl h-11" />
          <IconAction label="Export GSTR CSV" icon={<Download className="h-4 w-4" />} onClick={handleExportCsv}
            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20 gap-2 h-11" />
        </div>
      </div>

      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="p-4 bg-card/90 border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Total Taxable Sales</div>
          <div className="text-xl font-extrabold text-foreground mt-1">
            ₹{summary.totalTaxableSales.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
          </div>
          <div className="text-[11px] text-muted-foreground mt-1">Excludes GST component</div>
        </div>

        <div className="p-4 bg-card/90 border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Output GST Collected</div>
          <div className="text-xl font-extrabold text-rose-400 mt-1">
            ₹{summary.totalOutputGst.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
          </div>
          <div className="text-[11px] text-muted-foreground mt-1 flex items-center gap-2">
            <span>CGST: ₹{summary.totalCgst.toFixed(2)}</span>
            <span>SGST: ₹{summary.totalSgst.toFixed(2)}</span>
          </div>
        </div>

        <div className="p-4 bg-card/90 border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Input Tax Credit (ITC)</div>
          <div className="text-xl font-extrabold text-emerald-400 mt-1">
            ₹{summary.totalInputGst.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
          </div>
          <div className="text-[11px] text-muted-foreground mt-1">Claimable on purchases</div>
        </div>

        <div className="p-4 bg-card/90 border border-border rounded-2xl">
          <div className="text-xs text-muted-foreground font-medium">Net GST Liability</div>
          <div className="text-xl font-extrabold text-[#00aef0] mt-1">
            ₹{summary.netGstLiability.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
          </div>
          <div className="text-[11px] text-muted-foreground mt-1">Output GST - Input Credit</div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex items-center justify-between border-b border-border pb-2">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setActiveTab("GSTR1")}
            className={`px-4 py-2 text-sm font-semibold rounded-xl transition-all ${
              activeTab === "GSTR1"
                ? "bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            GSTR-1 Outward Sales Report
          </button>
          <button
            onClick={() => setActiveTab("GSTR2B")}
            className={`px-4 py-2 text-sm font-semibold rounded-xl transition-all ${
              activeTab === "GSTR2B"
                ? "bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            GSTR-2B Inward Purchase (ITC) Report
          </button>
        </div>
        <div className="relative w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Filter Invoice / GSTIN..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-9 h-9 bg-background border-border text-foreground rounded-xl text-xs"
          />
        </div>
      </div>

      {/* Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4">Invoice #</th>
                <th className="py-3.5 px-4">Date</th>
                <th className="py-3.5 px-4">Party / Buyer</th>
                <th className="py-3.5 px-4">GSTIN</th>
                <th className="py-3.5 px-4">HSN/SAC</th>
                <th className="py-3.5 px-4 text-right">Taxable Value</th>
                <th className="py-3.5 px-4 text-right">CGST</th>
                <th className="py-3.5 px-4 text-right">SGST</th>
                <th className="py-3.5 px-4 text-right">IGST</th>
                <th className="py-3.5 px-4 text-right">Total Invoice</th>
                <th className="py-3.5 px-4 text-center">E-Invoice IRN</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={11} className="py-12 text-center text-muted-foreground text-sm">
                    Loading GST Tax Ledger...
                  </td>
                </tr>
              ) : filteredEntries.length === 0 ? (
                <tr>
                  <td colSpan={11} className="py-12 text-center text-muted-foreground text-sm">
                    No active GST ledger entries found for this report period.
                  </td>
                </tr>
              ) : (
                filteredEntries.map((e) => (
                  <tr key={e.id} className="hover:bg-muted/40 transition-colors">
                    <td className="py-3.5 px-4 font-mono font-bold text-foreground">
                      #{e.invoice_number}
                    </td>
                    <td className="py-3.5 px-4 text-xs text-muted-foreground">
                      {e.invoice_date}
                    </td>
                    <td className="py-3.5 px-4 font-bold text-foreground">
                      {e.party_name || "POS Retail Customer"}
                    </td>
                    <td className="py-3.5 px-4 font-mono text-xs text-muted-foreground">
                      {e.gstin || "URP (Unregistered)"}
                    </td>
                    <td className="py-3.5 px-4 font-mono text-xs text-[#00aef0]">
                      {e.hsn_sac_code || "7113"}
                    </td>
                    <td className="py-3.5 px-4 text-right font-medium text-foreground">
                      ₹{Number(e.taxable_amount).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-right text-xs text-muted-foreground">
                      ₹{Number(e.cgst_amount || 0).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-right text-xs text-muted-foreground">
                      ₹{Number(e.sgst_amount || 0).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-right text-xs text-muted-foreground">
                      ₹{Number(e.igst_amount || 0).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-right font-extrabold text-[#00aef0]">
                      ₹{Number(e.total_invoice_amount).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-center">
                      {e.irn_number ? (
                        <button
                          onClick={() => setSelectedEInvoice(e)}
                          className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 hover:bg-emerald-500/20"
                        >
                          <ShieldCheck className="h-3 w-3" />
                          IRN Active
                        </button>
                      ) : (
                        <span className="text-muted-foreground text-xs">B2C Retail</span>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Signed E-Invoice QR Modal */}
      {selectedEInvoice && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-3xl max-w-md w-full p-6 space-y-4 shadow-2xl text-foreground">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <ShieldCheck className="h-5 w-5 text-emerald-400" />
                Signed E-Invoice IRN &amp; QR
              </h2>
              <button onClick={() => setSelectedEInvoice(null)} className="text-muted-foreground hover:text-foreground">
                ✕
              </button>
            </div>

            <div className="space-y-3 text-xs">
              <div>
                <span className="text-muted-foreground block">IRN (64-Char Hash):</span>
                <span className="font-mono text-[11px] text-[#00aef0] break-all bg-background p-2 rounded-lg block mt-0.5 border border-border">
                  {selectedEInvoice.irn_number}
                </span>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <span className="text-muted-foreground block">Ack Number:</span>
                  <span className="font-mono text-foreground font-bold">{selectedEInvoice.ack_number}</span>
                </div>
                <div>
                  <span className="text-muted-foreground block">Ack Date:</span>
                  <span className="text-foreground">{selectedEInvoice.ack_date ? new Date(selectedEInvoice.ack_date).toLocaleDateString() : "—"}</span>
                </div>
              </div>

              {/* QR Code Payload Simulation */}
              <div className="flex flex-col items-center justify-center p-4 bg-white rounded-2xl border border-border text-black">
                <QrCode className="h-28 w-28 text-black" />
                <span className="text-[10px] font-mono text-gray-600 mt-2">Government Signed QR Code Payload</span>
              </div>
            </div>

            <div className="flex justify-end pt-2 border-t border-border">
              <Button onClick={() => setSelectedEInvoice(null)} className="bg-[#00aef0] text-foreground font-bold rounded-xl">
                Close Viewer
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Layers, Plus, ArrowUpRight, RefreshCw, Search, AlertTriangle, Barcode, CheckCircle2 } from "lucide-react";
import { toast } from "sonner";
import { IconAction } from "@/components/ui/icon-action";

export default function InventoryPage() {
  const { activeWorkspace } = useWorkspace();
  const [inventory, setInventory] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [showStockModal, setShowStockModal] = useState(false);

  // Form State for Adding Stock
  const [barcodeSearch, setBarcodeSearch] = useState("");
  const [selectedProductId, setSelectedProductId] = useState("");
  const [selectedProductObj, setSelectedProductObj] = useState<any | null>(null);
  const [movementType, setMovementType] = useState<"INWARD" | "ADJUSTMENT">("INWARD");
  const [quantity, setQuantity] = useState("");
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);
  const quantityInputRef = useRef<HTMLInputElement>(null);

  // Barcode Scanner Global Keyboard Stream Listener
  const barcodeBufferRef = useRef<string>("");
  const lastKeyTimeRef = useRef<number>(0);

  const fetchInventory = async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/commerce/inventory?workspace_id=${activeWorkspace.id}`);
      const json = await res.json();
      if (res.ok && json.inventory) {
        setInventory(json.inventory);
      }
    } catch {
      toast.error("Failed to load inventory levels");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchInventory();
  }, [activeWorkspace?.id]);

  // Global Barcode Scan Listener (Zero-Click Modal Opening)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Hotkey F3 to open stock modal
      if (e.key === "F3") {
        e.preventDefault();
        setShowStockModal(true);
        return;
      }

      // Detect hardware barcode scanner stream (rapid key presses < 30ms apart ending in Enter)
      const now = Date.now();
      const diff = now - lastKeyTimeRef.current;
      lastKeyTimeRef.current = now;

      if (diff > 50) {
        barcodeBufferRef.current = "";
      }

      if (e.key === "Enter") {
        const scannedCode = barcodeBufferRef.current.trim();
        if (scannedCode.length >= 4) {
          const matched = inventory.find(
            (item) =>
              (item.barcode && item.barcode.toLowerCase() === scannedCode.toLowerCase()) ||
              item.sku.toLowerCase() === scannedCode.toLowerCase()
          );

          if (matched) {
            e.preventDefault();
            setSelectedProductId(matched.id);
            setSelectedProductObj(matched);
            setBarcodeSearch(scannedCode);
            setShowStockModal(true);
            toast.success(`Barcode Scanned: ${matched.name}`);
            setTimeout(() => {
              quantityInputRef.current?.focus();
            }, 100);
          }
        }
        barcodeBufferRef.current = "";
      } else if (e.key.length === 1) {
        barcodeBufferRef.current += e.key;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [inventory]);

  useEffect(() => {
    if (showStockModal) {
      setTimeout(() => {
        if (!selectedProductId) {
          barcodeInputRef.current?.focus();
        } else {
          quantityInputRef.current?.focus();
        }
      }, 100);
    }
  }, [showStockModal, selectedProductId]);

  // Handle Barcode Scan / Quick Search Match inside Modal
  const handleBarcodeOrQueryChange = (val: string) => {
    setBarcodeSearch(val);
    if (!val.trim()) {
      setSelectedProductId("");
      setSelectedProductObj(null);
      return;
    }

    const matched = inventory.find(
      (item) =>
        (item.barcode && item.barcode.toLowerCase() === val.trim().toLowerCase()) ||
        item.sku.toLowerCase() === val.trim().toLowerCase() ||
        item.name.toLowerCase().includes(val.trim().toLowerCase())
    );

    if (matched) {
      setSelectedProductId(matched.id);
      setSelectedProductObj(matched);
      setTimeout(() => {
        quantityInputRef.current?.focus();
      }, 50);
    }
  };

  const handleSelectProductDropdown = (id: string) => {
    setSelectedProductId(id);
    const matched = inventory.find((item) => item.id === id);
    setSelectedProductObj(matched || null);
    if (matched) {
      setBarcodeSearch(matched.barcode || matched.sku || matched.name);
    }
  };

  const handleAddStock = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !selectedProductId || !quantity) {
      toast.error("Please scan a valid product and enter quantity");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/commerce/inventory", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          workspace_id: activeWorkspace.id,
          product_id: selectedProductId,
          movement_type: movementType,
          quantity: Number(quantity),
          notes,
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to add stock");

      toast.success(`Stock updated for ${selectedProductObj?.name || 'Product'}!`);
      setShowStockModal(false);
      setSelectedProductId("");
      setSelectedProductObj(null);
      setBarcodeSearch("");
      setQuantity("");
      setNotes("");
      fetchInventory();
    } catch (err: any) {
      toast.error(err.message || "Failed to update stock");
    } finally {
      setSaving(false);
    }
  };

  const filteredInventory = inventory.filter((item) =>
    item.name.toLowerCase().includes(query.toLowerCase()) ||
    item.sku.toLowerCase().includes(query.toLowerCase()) ||
    (item.barcode && item.barcode.toLowerCase().includes(query.toLowerCase()))
  );

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <Layers className="h-6 w-6 text-[#00aef0]" />
            Inventory & Stock Movements
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Track real-time stock levels, reorder thresholds, and log stock additions via barcode scan or F3 hotkey.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <IconAction label="Refresh" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchInventory} variant="outline" className="border-border text-foreground gap-1.5 rounded-xl h-11" />
          <IconAction label="Add / Adjust Stock (F3)" icon={<Plus className="h-4 w-4" />} onClick={() => {
              setBarcodeSearch("");
              setSelectedProductId("");
              setSelectedProductObj(null);
              setQuantity("");
              setNotes("");
              setShowStockModal(true);
            }}
            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20 gap-2 h-11" />
        </div>
      </div>

      {/* Search */}
      <div className="flex items-center gap-3 bg-card/80 p-3 rounded-2xl border border-border backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search stock by Product Name, SKU, or Barcode..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border text-foreground rounded-xl focus:border-[#00aef0]"
          />
        </div>
      </div>

      {/* Inventory Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4">Product Name</th>
                <th className="py-3.5 px-4 hidden sm:table-cell">SKU / Barcode</th>
                <th className="py-3.5 px-4 text-center hidden md:table-cell">Unit</th>
                <th className="py-3.5 px-4 text-right">Current Stock</th>
                <th className="py-3.5 px-4 text-right hidden sm:table-cell">Reorder Threshold</th>
                <th className="py-3.5 px-4 text-center">Stock Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-muted-foreground text-sm">
                    Loading Stock Levels...
                  </td>
                </tr>
              ) : filteredInventory.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-muted-foreground text-sm">
                    No inventory records found. Add products in the Master Catalog first, then click &quot;Add / Adjust Stock&quot;.
                  </td>
                </tr>
              ) : (
                filteredInventory.map((item) => {
                  const currentQty = item.current_stock || 0;
                  const isLowStock = currentQty <= (item.reorder_level || 10);
                  return (
                    <tr key={item.id} className="hover:bg-muted/40 transition-colors">
                      <td className="py-3.5 px-4 font-semibold text-foreground">
                        {item.name}
                      </td>
                      <td className="py-3.5 px-4 font-mono text-xs text-muted-foreground hidden sm:table-cell">
                        <div>{item.sku}</div>
                        {item.barcode && (
                          <div className="text-[11px] text-[#00aef0] flex items-center gap-1 mt-0.5">
                            <Barcode className="h-3 w-3" /> {item.barcode}
                          </div>
                        )}
                      </td>
                      <td className="py-3.5 px-4 text-center uppercase text-xs text-muted-foreground font-mono hidden md:table-cell">
                        {item.unit}
                      </td>
                      <td className="py-3.5 px-4 text-right font-extrabold text-base text-foreground">
                        {currentQty} <span className="text-xs font-normal text-muted-foreground">{item.unit}</span>
                      </td>
                      <td className="py-3.5 px-4 text-right text-xs text-muted-foreground hidden sm:table-cell">
                        {item.reorder_level || 10} {item.unit}
                      </td>
                      <td className="py-3.5 px-4 text-center">
                        {isLowStock ? (
                          <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-amber-500/10 text-amber-400 border border-amber-500/20">
                            <AlertTriangle className="h-3 w-3" />
                            Low Stock
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                            <ArrowUpRight className="h-3 w-3" />
                            In Stock
                          </span>
                        )}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add / Adjust Stock Modal */}
      {showStockModal && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-3xl max-w-md w-full p-6 space-y-4 shadow-2xl">
            <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
              <Plus className="h-5 w-5 text-[#00aef0]" />
              Add / Adjust Stock
            </h2>

            <form onSubmit={handleAddStock} className="space-y-4">
              {/* 1-Scan Barcode Input */}
              <div className="space-y-1.5 bg-background p-3 rounded-2xl border border-border">
                <Label className="text-xs font-bold text-[#00aef0] flex items-center gap-1.5">
                  <Barcode className="h-4 w-4" /> 1-Scan Barcode / Search Product
                </Label>
                <div className="relative">
                  <Input
                    ref={barcodeInputRef}
                    type="text"
                    placeholder="Scan product barcode here with scanner..."
                    value={barcodeSearch}
                    onChange={(e) => handleBarcodeOrQueryChange(e.target.value)}
                    className="bg-card border-border text-foreground h-10 rounded-xl px-3 text-xs font-mono focus:border-[#00aef0]"
                  />
                </div>

                {selectedProductObj && (
                  <div className="mt-2 bg-emerald-500/10 p-2.5 rounded-xl border border-emerald-500/20 flex items-center justify-between text-xs">
                    <div>
                      <div className="font-extrabold text-emerald-400 flex items-center gap-1">
                        <CheckCircle2 className="h-3.5 w-3.5" /> Matched: {selectedProductObj.name}
                      </div>
                      <div className="text-[11px] text-muted-foreground mt-0.5">
                        SKU: {selectedProductObj.sku} | Current Stock: {selectedProductObj.current_stock || 0} {selectedProductObj.unit}
                      </div>
                    </div>
                  </div>
                )}
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-foreground">Or Select Product from List *</Label>
                <select
                  required
                  value={selectedProductId}
                  onChange={(e) => handleSelectProductDropdown(e.target.value)}
                  className="w-full bg-background border border-border text-foreground h-10 rounded-xl px-3 text-sm focus:border-[#00aef0]"
                >
                  <option value="">-- Choose a Product --</option>
                  {inventory.map((prod) => (
                    <option key={prod.id} value={prod.id}>
                      {prod.name} ({prod.sku}) — Current: {prod.current_stock || 0} {prod.unit}
                    </option>
                  ))}
                </select>
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-foreground">Action Type</Label>
                <select
                  value={movementType}
                  onChange={(e) => setMovementType(e.target.value as any)}
                  className="w-full bg-background border border-border text-foreground h-10 rounded-xl px-3 text-sm focus:border-[#00aef0]"
                >
                  <option value="INWARD">Stock Inward (+ New Delivery)</option>
                  <option value="ADJUSTMENT">Stock Adjustment (+ Manual Addition)</option>
                </select>
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-foreground">Quantity to Add *</Label>
                <Input
                  ref={quantityInputRef}
                  type="number"
                  required
                  placeholder="e.g. 50"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                  className="bg-background border-border text-foreground h-10 rounded-xl font-bold text-base focus:border-[#00aef0]"
                />
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-foreground">Notes / Invoice Ref</Label>
                <Input
                  type="text"
                  placeholder="e.g. Received from Supplier Bill #1042"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="bg-background border-border text-foreground h-10 rounded-xl text-xs"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setShowStockModal(false)}
                  className="border-border text-foreground rounded-xl"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={saving || !selectedProductId}
                  className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl px-6"
                >
                  {saving ? "Updating..." : "Add Stock"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Wallet,
  Search,
  Send,
  RefreshCw,
  UserPlus,
  Plus,
  IndianRupee,
  AlertTriangle,
  Users,
  CheckCircle2,
  X,
  Info,
  Phone,
  Building,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import { toast } from "sonner";
import { WhatsAppReminderModal } from "@/components/finance/whatsapp-reminder-modal";
import { IconAction } from "@/components/ui/icon-action";

export default function CustomerLedgerPage() {
  const { activeWorkspace } = useWorkspace();
  const [customers, setCustomers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");

  // Add Customer Modal State
  const [showAddCustomerModal, setShowAddCustomerModal] = useState(false);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [company, setCompany] = useState("");
  const [creditLimit, setCreditLimit] = useState("50000");

  // Record Payment Collection Modal State
  const [selectedPayCustomer, setSelectedPayCustomer] = useState<any | null>(null);
  const [payAmount, setPayAmount] = useState("");
  const [payMode, setPayMode] = useState<"CASH" | "UPI" | "BANK">("CASH");
  const [payNotes, setPayNotes] = useState("");

  const [saving, setSaving] = useState(false);

  const fetchLedger = async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/commerce/ledger?workspace_id=${activeWorkspace.id}`);
      const json = await res.json();
      if (res.ok && json.customers) {
        setCustomers(json.customers);
      }
    } catch {
      toast.error("Failed to load customer khata ledger");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLedger();
  }, [activeWorkspace?.id]);

  const handleCreateCustomer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || (!firstName && !phone)) {
      toast.error("Customer Name or Phone Number is required");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/commerce/ledger", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "CREATE_CUSTOMER",
          workspace_id: activeWorkspace.id,
          first_name: firstName,
          last_name: lastName,
          phone_number: phone,
          email,
          company,
          credit_limit: Number(creditLimit || 50000),
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to create customer");

      toast.success("New Customer added to CRM & Khata Ledger!");
      setShowAddCustomerModal(false);
      setFirstName("");
      setLastName("");
      setPhone("");
      setEmail("");
      setCompany("");
      setCreditLimit("50000");
      fetchLedger();
    } catch (err: any) {
      toast.error(err.message || "Failed to add customer");
    } finally {
      setSaving(false);
    }
  };

  const handleRecordPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !selectedPayCustomer || !payAmount) {
      toast.error("Payment amount is required");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/commerce/ledger", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "RECORD_PAYMENT",
          workspace_id: activeWorkspace.id,
          contact_id: selectedPayCustomer.id,
          payment_amount: Number(payAmount),
          payment_mode: payMode,
          notes: payNotes,
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to record payment");

      toast.success(
        `Recorded Khata payment of ₹${Number(payAmount).toFixed(2)} for ${selectedPayCustomer.displayName}!`
      );
      setSelectedPayCustomer(null);
      setPayAmount("");
      setPayNotes("");
      fetchLedger();
    } catch (err: any) {
      toast.error(err.message || "Failed to record payment");
    } finally {
      setSaving(false);
    }
  };

  const [selectedWaCustomer, setSelectedWaCustomer] = useState<any>(null);
  const [waModalOpen, setWaModalOpen] = useState(false);

  const handleWhatsAppReminder = (c: any) => {
    const rawPhone = c.phone || c.phone_number;
    if (!rawPhone) {
      toast.error("Customer phone number is missing");
      return;
    }
    setSelectedWaCustomer(c);
    setWaModalOpen(true);
  };

  // Compute Stats
  const totalCustomersCount = customers.length;
  const totalUdharBalance = customers.reduce(
    (acc, c) => acc + Number(c.outstanding_balance || 0),
    0
  );
  const overLimitCount = customers.filter(
    (c) => Number(c.outstanding_balance || 0) > Number(c.credit_limit || 50000)
  ).length;

  const [page, setPage] = useState(1);
  const pageSize = 20;

  const filteredCustomers = customers.filter(
    (c) =>
      c.displayName?.toLowerCase().includes(query.toLowerCase()) ||
      c.phone?.includes(query) ||
      c.phone_number?.includes(query) ||
      c.company?.toLowerCase().includes(query.toLowerCase())
  );

  const totalPages = Math.max(1, Math.ceil(filteredCustomers.length / pageSize));
  const displayedCustomers = filteredCustomers.slice(
    (page - 1) * pageSize,
    page * pageSize
  );

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <Wallet className="h-6 w-6 text-[#00aef0]" />
            Customer Khata &amp; Credit Risk Ledger
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Track customer credit balances (Udhar), set credit limits, collect payments, and send WhatsApp payment reminders.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <IconAction label="Refresh Books" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchLedger}
            variant="outline"
            className="border-border text-foreground gap-1.5 rounded-xl h-11" />
          <IconAction label="Add New Customer" icon={<UserPlus className="h-4 w-4" />} onClick={() => setShowAddCustomerModal(true)}
            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20 gap-2 h-11" />
        </div>
      </div>

      {/* Workflow Guidance Banner */}
      <div className="bg-card/90 border border-border p-4 rounded-2xl flex items-center gap-3 text-xs text-foreground">
        <Info className="h-5 w-5 text-[#00aef0] shrink-0" />
        <div>
          <strong className="text-foreground block font-bold text-sm">
            How Customer Khata Works:
          </strong>
          Customers created here are automatically saved to your <span className="text-[#00aef0] font-bold">CRM Contacts</span> and available in <span className="text-[#00aef0] font-bold">POS Billing</span>. When a POS checkout is completed using <span className="text-amber-400 font-bold">KHATA_CREDIT</span> mode, their pending balance increases here. Click <strong>Record Payment</strong> to collect cash/UPI and clear their Udhar balance!
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="p-4 bg-card/90 border border-border rounded-2xl flex items-center justify-between">
          <div>
            <div className="text-xs text-muted-foreground font-medium">Total Registered Customers</div>
            <div className="text-2xl font-extrabold text-[#00aef0] mt-1">{totalCustomersCount}</div>
          </div>
          <div className="h-10 w-10 bg-[#00aef0]/10 border border-[#00aef0]/20 rounded-xl flex items-center justify-center text-[#00aef0]">
            <Users className="h-5 w-5" />
          </div>
        </div>

        <div className="p-4 bg-card/90 border border-border rounded-2xl flex items-center justify-between">
          <div>
            <div className="text-xs text-muted-foreground font-medium">Total Pending Udhar Balance</div>
            <div className="text-2xl font-extrabold text-amber-400 mt-1">
              ₹{totalUdharBalance.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </div>
          </div>
          <div className="h-10 w-10 bg-amber-500/10 border border-amber-500/20 rounded-xl flex items-center justify-center text-amber-400">
            <IndianRupee className="h-5 w-5" />
          </div>
        </div>

        <div className="p-4 bg-card/90 border border-border rounded-2xl flex items-center justify-between">
          <div>
            <div className="text-xs text-muted-foreground font-medium">Over Credit Limit Alerts</div>
            <div className="text-2xl font-extrabold text-rose-400 mt-1">{overLimitCount}</div>
          </div>
          <div className="h-10 w-10 bg-rose-500/10 border border-rose-500/20 rounded-xl flex items-center justify-center text-rose-400">
            <AlertTriangle className="h-5 w-5" />
          </div>
        </div>
      </div>

      {/* Search Bar */}
      <div className="flex items-center gap-3 bg-card/80 p-3 rounded-2xl border border-border backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search Customer by Name, Phone Number, or Company..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border text-foreground rounded-xl focus:border-[#00aef0]"
          />
        </div>
      </div>

      {/* Khata Ledger Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4 w-[28%]">Customer Name</th>
                <th className="py-3.5 px-4 w-[24%]">Phone &amp; Email</th>
                <th className="py-3.5 px-4 text-right w-[16%]">Credit Limit</th>
                <th className="py-3.5 px-4 text-right w-[16%]">Pending Udhar Balance</th>
                <th className="py-3.5 px-4 text-center w-[16%]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={5} className="py-12 text-center text-muted-foreground text-sm">
                    Loading Customer Khata Ledger...
                  </td>
                </tr>
              ) : displayedCustomers.length === 0 ? (
                <tr>
                  <td colSpan={5} className="py-12 text-center text-muted-foreground text-sm space-y-3">
                    <Users className="h-10 w-10 mx-auto text-muted-foreground mb-2" />
                    <p className="text-foreground font-semibold">No Customers Found</p>
                    <p className="text-xs text-muted-foreground max-w-sm mx-auto">
                      Add customer details to start tracking credit limits and Khata payments.
                    </p>
                    <IconAction label="Add First Customer" icon={<UserPlus className="h-4 w-4" />} onClick={() => setShowAddCustomerModal(true)}
                      className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl gap-2 mt-2" />
                  </td>
                </tr>
              ) : (
                displayedCustomers.map((contact) => {
                  const bal = Number(contact.outstanding_balance || 0);
                  const limit = Number(contact.credit_limit || 50000);
                  const isOverLimit = bal > limit;

                  return (
                    <tr key={contact.id} className="hover:bg-muted/40 transition-colors">
                      <td className="py-3.5 px-4 font-extrabold text-foreground">
                        <div>{contact.displayName}</div>
                        {contact.company && (
                          <span className="block text-[11px] text-muted-foreground font-normal">
                            {contact.company}
                          </span>
                        )}
                      </td>
                      <td className="py-3.5 px-4 text-xs text-foreground">
                        {(contact.phone || contact.phone_number) && (
                          <div className="flex items-center gap-1 font-mono text-foreground">
                            <Phone className="h-3 w-3 text-[#00aef0]" />
                            {contact.phone || contact.phone_number}
                          </div>
                        )}
                        {contact.email && (
                          <div className="text-[11px] text-muted-foreground">{contact.email}</div>
                        )}
                      </td>
                      <td className="py-3.5 px-4 text-right font-medium text-foreground">
                        ₹{limit.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
                      </td>
                      <td className="py-3.5 px-4 text-right font-extrabold">
                        <span
                          className={
                            bal > 0
                              ? isOverLimit
                                ? "text-rose-400"
                                : "text-amber-400"
                              : "text-emerald-400"
                          }
                        >
                          ₹{bal.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
                        </span>
                      </td>
                      <td className="py-3.5 px-4 text-center">
                        <div className="flex items-center justify-center gap-2">
                          <IconAction label="Record Payment" icon={<IndianRupee className="h-3.5 w-3.5" />} onClick={() => setSelectedPayCustomer(contact)}
                            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold text-xs rounded-xl gap-1 h-8 px-3" />
                          <IconAction label="WhatsApp" icon={<Send className="h-3.5 w-3.5" />} variant="outline"
                            onClick={() => handleWhatsAppReminder(contact)}
                            className="border-emerald-600/30 bg-emerald-600/10 hover:bg-emerald-600/20 text-emerald-400 font-bold text-xs rounded-xl gap-1 h-8 px-3" />
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Pagination Bar */}
      {filteredCustomers.length > 0 && (
        <div className="flex flex-col sm:flex-row items-center justify-between gap-3 bg-card/80 border border-border p-3.5 rounded-2xl text-xs text-foreground backdrop-blur-md">
          <div>
            Showing <strong className="text-foreground">{(page - 1) * pageSize + 1}</strong> to{" "}
            <strong className="text-foreground">
              {Math.min(page * pageSize, filteredCustomers.length)}
            </strong>{" "}
            of <strong className="text-foreground">{filteredCustomers.length}</strong> registered customers
          </div>
          <div className="flex items-center gap-2">
            <IconAction label="Previous" icon={<ChevronLeft className="h-4 w-4" />} variant="outline"
              disabled={page === 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              className="border-border text-foreground h-8 gap-1 rounded-xl disabled:opacity-40" />
            <span className="font-bold text-foreground px-3 py-1 bg-background rounded-lg border border-border">
              Page {page} of {totalPages}
            </span>
            <IconAction label="Next" icon={<ChevronRight className="h-4 w-4" />} variant="outline"
              disabled={page >= totalPages}
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              className="border-border text-foreground h-8 gap-1 rounded-xl disabled:opacity-40" />
          </div>
        </div>
      )}

      {/* Add New Customer Modal */}
      {showAddCustomerModal && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto overflow-x-hidden [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
          <div className="bg-card border border-border rounded-3xl max-w-lg w-full p-6 space-y-4 shadow-2xl text-foreground overflow-x-hidden">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <UserPlus className="h-5 w-5 text-[#00aef0]" />
                Add New Customer to CRM &amp; Khata
              </h2>
              <button onClick={() => setShowAddCustomerModal(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            <form onSubmit={handleCreateCustomer} className="space-y-3 text-xs">
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">First Name *</Label>
                  <Input
                    required
                    type="text"
                    placeholder="e.g. Ramesh"
                    value={firstName}
                    onChange={(e) => setFirstName(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Last Name</Label>
                  <Input
                    type="text"
                    placeholder="e.g. Kumar"
                    value={lastName}
                    onChange={(e) => setLastName(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Phone Number *</Label>
                  <Input
                    required
                    type="text"
                    placeholder="e.g. 9876543210"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Email Address</Label>
                  <Input
                    type="email"
                    placeholder="e.g. ramesh@gmail.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Company / Shop Name</Label>
                  <Input
                    type="text"
                    placeholder="e.g. Ramesh Traders"
                    value={company}
                    onChange={(e) => setCompany(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Credit Limit (₹)</Label>
                  <Input
                    type="number"
                    value={creditLimit}
                    onChange={(e) => setCreditLimit(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs font-bold"
                  />
                </div>
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border">
                <Button type="button" variant="outline" onClick={() => setShowAddCustomerModal(false)} className="border-border text-foreground rounded-xl h-10">
                  Cancel
                </Button>
                <Button type="submit" disabled={saving} className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl h-10 px-5">
                  {saving ? "Adding..." : "Add Customer"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Record Payment Collection Modal */}
      {selectedPayCustomer && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto overflow-x-hidden [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
          <div className="bg-card border border-border rounded-3xl max-w-md w-full p-6 space-y-4 shadow-2xl text-foreground overflow-x-hidden">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <IndianRupee className="h-5 w-5 text-[#00aef0]" />
                Collect Khata Payment
              </h2>
              <button onClick={() => setSelectedPayCustomer(null)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="bg-background p-3 rounded-2xl border border-border space-y-1 text-xs">
              <span className="text-muted-foreground block">Customer Name:</span>
              <strong className="text-foreground text-sm font-extrabold block">
                {selectedPayCustomer.displayName}
              </strong>
              <div className="flex items-center justify-between pt-1">
                <span className="text-muted-foreground">Current Pending Udhar:</span>
                <span className="text-amber-400 font-extrabold text-sm">
                  ₹{Number(selectedPayCustomer.outstanding_balance || 0).toFixed(2)}
                </span>
              </div>
            </div>

            <form onSubmit={handleRecordPayment} className="space-y-3 text-xs">
              <div className="space-y-1">
                <Label className="text-xs text-foreground">Payment Collected Amount (₹) *</Label>
                <Input
                  required
                  type="number"
                  placeholder="Enter collected cash/UPI amount..."
                  value={payAmount}
                  onChange={(e) => setPayAmount(e.target.value)}
                  className="bg-background border-border text-foreground rounded-xl h-10 text-xs font-bold text-base"
                />
              </div>

              <div className="space-y-1">
                <Label className="text-xs text-foreground">Payment Collection Mode</Label>
                <select
                  value={payMode}
                  onChange={(e) => setPayMode(e.target.value as any)}
                  className="w-full bg-background border border-border text-foreground rounded-xl h-10 px-3 text-xs font-bold"
                >
                  <option value="CASH">CASH Collection</option>
                  <option value="UPI">UPI / GPay / PhonePe</option>
                  <option value="BANK">Bank Transfer / Cheque</option>
                </select>
              </div>

              <div className="space-y-1">
                <Label className="text-xs text-foreground">Notes / Remarks</Label>
                <Input
                  type="text"
                  placeholder="e.g. Partial cash payment received"
                  value={payNotes}
                  onChange={(e) => setPayNotes(e.target.value)}
                  className="bg-background border-border text-foreground rounded-xl h-9 text-xs"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border">
                <Button type="button" variant="outline" onClick={() => setSelectedPayCustomer(null)} className="border-border text-foreground rounded-xl h-10">
                  Cancel
                </Button>
                <Button type="submit" disabled={saving} className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl h-10 px-5">
                  {saving ? "Saving..." : "Record Payment"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeWorkspace?.id && (
        <WhatsAppReminderModal
          open={waModalOpen}
          onOpenChange={setWaModalOpen}
          customer={selectedWaCustomer}
          workspaceId={activeWorkspace.id}
          workspaceName={activeWorkspace.name || "Daily CRM"}
        />
      )}
    </div>
  );
}

