          unit_conversion_factor: Number(conversionFactor || 1),
          purchase_price: Number(purchasePrice || 0),
          selling_price: Number(sellingPrice || 0),
          wholesale_rate: Number(wholesaleRate || sellingPrice || 0),
          distributor_rate: Number(distributorRate || sellingPrice || 0),
          online_rate: Number(onlineRate || sellingPrice || 0),
          mrp: Number(mrp || sellingPrice || 0),
          min_selling_price: Number(minSellingPrice || 0),
          tax_rate: Number(taxRate || 0),
          cess_rate: Number(cessRate || 0),
          is_tax_inclusive: isTaxInclusive,
          initial_stock: Number(initialStock || 0),
          reorder_level: Number(reorderLevel || 10),
          reorder_quantity: Number(reorderQuantity || 50),
          min_stock_level: Number(minStockLevel || 5),
          max_stock_level: Number(maxStockLevel || 1000),
          shelf_number: shelfNumber || undefined,
          bin_location: binLocation || undefined,
          allow_negative_stock: allowNegativeStock,
          track_batch: trackBatch,
          track_serial: trackSerial,
          track_expiry: trackExpiry,
          attributes: {
            industry_template: activeTemplate,
            pack_size: packSize || undefined,
            apparel_size: apparelSize || undefined,
            apparel_color: apparelColor || undefined,
            apparel_fabric: apparelFabric || undefined,
            apparel_fit: apparelFit || undefined,
            salt_composition: saltComposition || undefined,
            oem_part_number: oemPartNumber || undefined,
            custom_user_fields: customValuesMap,
          },
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || `Failed to ${isEdit ? "update" : "create"} product`);

      toast.success(isEdit ? "Enterprise Product Master Updated!" : "Enterprise Product Master Created!");
      setShowAddModal(false);
      handleResetForm();
      fetchProducts();

      if (isEdit && selectedViewProduct?.id === editingProduct.id && json.product) {
        setSelectedViewProduct(json.product);
      } else if (!isEdit && json.product) {
        setSelectedBarcodeProduct(json.product);
        setShowTagModal(true);
      }
    } catch (err: any) {
      const msg = sanitizeErrorMessage(err, "Failed to save product");
      toast.error(msg);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <Package className="h-6 w-6 text-[#00aef0]" />
            Products & Enterprise Master Catalog
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Manage multi-unit conversions, tiered rates, HSN codes, custom attributes, and bin locations.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Link href="/settings?tab=retail">
            <Button variant="outline" className="border-border text-foreground gap-1.5 rounded-xl h-11">
              <Settings className="h-4 w-4 text-[#00aef0]" />
              Master Template: <span className="text-[#00aef0] font-extrabold">{activeTemplate}</span>
            </Button>
          </Link>
          <IconAction label="Add New Product" icon={<Plus className="h-4 w-4" />} onClick={() => {
              syncTemplateFromSettings();
              handleResetForm();
              setActiveTab("BASIC");
              setShowAddModal(true);
            }}
            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20 gap-2 h-11" />
        </div>
      </div>

      {/* Search & Filter */}
      <div className="flex items-center gap-3 bg-card/80 p-3 rounded-2xl border border-border backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search by Product Name, SKU, Barcode, Size, Color, or Brand..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border text-foreground rounded-xl focus:border-[#00aef0]"
          />
        </div>
        <IconAction label="Refresh" icon={<RefreshCw className="h-3.5 w-3.5" />} variant="outline" onClick={fetchProducts} className="h-10 border-border text-foreground gap-1.5 rounded-xl" />
      </div>

      {/* Products Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4">Product Name</th>
                <th className="py-3.5 px-4 hidden sm:table-cell">SKU / Barcode</th>
                <th className="py-3.5 px-4 hidden md:table-cell">HSN Code</th>
                <th className="py-3.5 px-4 hidden lg:table-cell">Units & Conversion</th>
                <th className="py-3.5 px-4 text-right hidden sm:table-cell">MRP</th>
                <th className="py-3.5 px-4 text-right">Selling Price</th>
                <th className="py-3.5 px-4 text-right hidden md:table-cell">GST Rate</th>
                <th className="py-3.5 px-4 text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={8} className="py-12 text-center text-muted-foreground text-sm">
                    Loading Products...
                  </td>
                </tr>
              ) : products.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-12 text-center text-muted-foreground text-sm">
                    No products added yet. Click &quot;Add New Product&quot; to populate catalog.
                  </td>
                </tr>
              ) : (
                products.map((product) => (
                  <tr key={product.id} className="hover:bg-muted/40 transition-colors">
                    <td className="py-3.5 px-4 font-semibold text-foreground">
                      <button
                        onClick={() => {
                          setSelectedViewProduct(product);
                          setShowViewModal(true);
                        }}
                        className="text-left font-bold text-foreground hover:text-[#00aef0] transition-colors flex flex-col group cursor-pointer"
                      >
                        <span className="group-hover:underline flex items-center gap-1.5">
                          {product.name}
                        </span>
                        {product.attributes?.apparel_size && (
                          <span className="block text-[11px] text-purple-400 font-normal">
                            Size: {product.attributes.apparel_size} | Color: {product.attributes.apparel_color || 'Default'}
                          </span>
                        )}
                        {product.attributes?.salt_composition && (
                          <span className="block text-[11px] text-emerald-400 font-normal">
                            Salt: {product.attributes.salt_composition}
                          </span>
                        )}
                        {product.attributes?.oem_part_number && (
                          <span className="block text-[11px] text-amber-400 font-normal">
                            OEM #: {product.attributes.oem_part_number} | Fitment: {product.attributes.vehicle_fitment || 'Universal'}
                          </span>
                        )}
                      </button>
                    </td>
                    <td className="py-3.5 px-4 font-mono text-xs text-muted-foreground hidden sm:table-cell">
                      <div>{product.sku}</div>
                      {product.barcode && (
                        <div className="flex items-center gap-1 text-[11px] text-[#00aef0] mt-0.5">
                          <Barcode className="h-3 w-3" />
                          {product.barcode}
                        </div>
                      )}
                    </td>
                    <td className="py-3.5 px-4 font-mono text-xs text-muted-foreground hidden md:table-cell">
                      {product.hsn_sac_code || "6203"}
                    </td>
                    <td className="py-3.5 px-4 text-xs text-muted-foreground hidden lg:table-cell">
                      {product.base_unit || "PCS"} (1 {product.purchase_unit || "PACK"} = {product.unit_conversion_factor || 6})
                    </td>
                    <td className="py-3.5 px-4 text-right text-muted-foreground hidden sm:table-cell">
                      ₹{Number(product.mrp || product.selling_price).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-right font-bold text-[#00aef0]">
                      ₹{Number(product.selling_price).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-right text-xs text-muted-foreground hidden md:table-cell">
                      {product.tax_rate}%
                    </td>
                    <td className="py-3.5 px-4 text-center">
                      <div className="flex items-center justify-center gap-2">
                        <IconAction label="View Details" icon={<Eye className="h-3.5 w-3.5 text-[#00aef0]" />} variant="outline"
                          onClick={() => {
                            setSelectedViewProduct(product);
                            setShowViewModal(true);
                          }}
                          className="border-border hover:border-[#00aef0] bg-card hover:bg-muted text-foreground hover:text-[#00aef0] font-semibold text-xs rounded-xl gap-1.5 h-8" />
                        <IconAction label="Edit" icon={<Pencil className="h-3.5 w-3.5 text-purple-400" />} variant="outline"
                          onClick={() => handleOpenEditModal(product)}
                          className="border-border hover:border-purple-500 bg-purple-500/10 hover:bg-purple-500/20 text-purple-300 font-semibold text-xs rounded-xl gap-1.5 h-8" />
                        <IconAction label="Print Tag" icon={<Printer className="h-3.5 w-3.5" />} variant="outline"
                          onClick={() => {
                            setSelectedBarcodeProduct(product);
                            setShowTagModal(true);
                          }}
                          className="border-border hover:border-[#00aef0] text-foreground hover:text-[#00aef0] font-semibold text-xs rounded-xl gap-1.5 h-8" />
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Product Details Modal Component */}
      <ProductDetailsModal
        isOpen={showViewModal}
        onClose={() => setShowViewModal(false)}
        product={selectedViewProduct}
        onEdit={(prod) => handleOpenEditModal(prod)}
        onPrintTag={(prod) => {
          setSelectedBarcodeProduct(prod);
          setShowTagModal(true);
        }}
      />

      {/* Barcode Tag Modal Component */}
      <BarcodeTagModal
        isOpen={showTagModal}
        onClose={() => setShowTagModal(false)}
        product={selectedBarcodeProduct}
        workspaceName={activeWorkspace?.name || "Daily CRM Store"}
      />

      {/* Multi-Tab Add/Edit Product Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-card border border-border rounded-3xl max-w-2xl w-full p-6 space-y-4 shadow-2xl my-8">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
                <Package className="h-5 w-5 text-[#00aef0]" />
                {editingProduct ? `Edit Product Master (${editingProduct.sku})` : "Add Enterprise Product Master"}
              </h2>
              <button onClick={() => setShowAddModal(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            {/* Configured Master Template Info Bar */}
            <div className="bg-background p-3 rounded-2xl border border-border flex items-center justify-between">
              <div className="flex items-center gap-2 text-xs">
                <Sparkles className="h-4 w-4 text-[#00aef0]" />
                <span className="text-muted-foreground">Active Business Template:</span>
                <span className="font-extrabold text-[#00aef0] text-sm">{activeTemplate}</span>
              </div>
              <Link href="/settings?tab=retail" className="text-[11px] text-[#00aef0] hover:underline flex items-center gap-1 font-semibold">
                <Settings className="h-3 w-3" /> Settings
              </Link>
            </div>

            {/* Modal Tabs Header */}
            <div className="flex items-center gap-1 border-b border-border pb-2 overflow-x-auto">
              {[
                { id: "BASIC", label: "Basic Info", icon: Package },
                { id: "UNITS_PRICING", label: "Units & Rates", icon: Banknote },
                { id: "TAX", label: "GST & Statutory", icon: ShieldCheck },
                { id: "INVENTORY", label: "Stock & Location", icon: Warehouse },
                { id: "SETTINGS", label: "Tracking & Flags", icon: Sliders },
                { id: "CUSTOM_FIELDS", label: "+ Custom Fields Builder", icon: PlusCircle },
              ].map((tab) => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as any)}
                    className={`px-3 py-1.5 text-xs font-bold rounded-xl flex items-center gap-1.5 transition-all whitespace-nowrap ${
                      activeTab === tab.id
                        ? "bg-[#00aef0] text-foreground shadow-md shadow-[#00aef0]/20"
                        : "text-muted-foreground hover:text-foreground hover:bg-muted/50"
                    }`}
                  >
                    <Icon className="h-3.5 w-3.5" />
                    {tab.label}
                  </button>
                );
              })}
            </div>

            <form onSubmit={handleCreateProduct} className="space-y-4">
              {/* Tab 1: Basic Info */}
              {activeTab === "BASIC" && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5 sm:col-span-2">
                    <Label className="text-xs text-foreground">Product Name *</Label>
                    <Input
                      required
                      type="text"
                      placeholder="e.g. Men's Cotton Denim Shirt / Paracetamol 650mg / Frame Glasses"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      className="bg-background border-border text-foreground rounded-xl h-10"
                    />
                  </div>

                  {/* DYNAMIC CARD: HANDCRAFTED GIFTS */}
                  {activeTemplate === "HANDCRAFTED_GIFTS" && (
                    <div className="space-y-2.5 bg-rose-500/10 p-3.5 rounded-2xl border border-rose-500/20 sm:col-span-2">
                      <Label className="text-xs text-rose-300 font-extrabold flex items-center gap-1.5 uppercase tracking-wider">
                        <Gem className="h-4 w-4 text-rose-400" /> Handcrafted &amp; Handmade Gift Attributes
                      </Label>
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <Label className="text-[11px] text-foreground">Artisan / Craftsperson Name</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Rajasthani Clay Guild / Jaipur Artisans"
                            value={artisanName}
                            onChange={(e) => setArtisanName(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Handcrafting Lead Time (Days)</Label>
                          <Input
                            type="text"
                            placeholder="e.g. 3-5 Days"
                            value={craftingTimeDays}
                            onChange={(e) => setCraftingTimeDays(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Gift Box &amp; Packaging Type</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Handmade Wooden Box / Jute Potli"
                            value={giftPackagingType}
                            onChange={(e) => setGiftPackagingType(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Personalization / Custom Engraving Notes</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Name Engraving, Custom Photo Print"
                            value={customizationNotes}
                            onChange={(e) => setCustomizationNotes(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                      </div>
                    </div>
                  )}

                  {/* DYNAMIC CARD: EVENT BULK GIFTS */}
                  {activeTemplate === "EVENT_BULK_GIFTS" && (
                    <div className="space-y-2.5 bg-amber-500/10 p-3.5 rounded-2xl border border-amber-500/20 sm:col-span-2">
                      <Label className="text-xs text-amber-300 font-extrabold flex items-center gap-1.5 uppercase tracking-wider">
                        <Sparkles className="h-4 w-4 text-amber-400" /> Wedding &amp; Corporate Bulk Return Gift Attributes
                      </Label>
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <Label className="text-[11px] text-foreground">Target Event Category</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Wedding Return Gift / Corporate Gifting / Festival Hamper"
                            value={eventTypeTarget}
                            onChange={(e) => setEventTypeTarget(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Minimum Order Qty (MOQ)</Label>
                          <Input
                            type="text"
                            placeholder="e.g. 50 Pcs minimum"
                            value={minOrderQuantity}
                            onChange={(e) => setMinOrderQuantity(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Tiered Bulk Rates (50-200 pcs / 200+ pcs)</Label>
                          <Input
                            type="text"
                            placeholder="e.g. 50-200 pcs @ ₹180 / 200+ pcs @ ₹150"
                            value={bulkTier1Price}
                            onChange={(e) => setBulkTier1Price(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Custom Branding Tag &amp; Thank-You Card</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Custom Event Logo Card Included"
                            value={customizationNotes}
                            onChange={(e) => setCustomizationNotes(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                      </div>
                    </div>
                  )}

                  {/* DYNAMIC CARD: GARMENTS & APPAREL ATTRIBUTES */}
                  {activeTemplate === "GARMENT" && (
                    <div className="space-y-2.5 bg-purple-500/10 p-3.5 rounded-2xl border border-purple-500/20 sm:col-span-2">
                      <Label className="text-xs text-purple-300 font-extrabold flex items-center gap-1.5 uppercase tracking-wider">
                        <Shirt className="h-4 w-4 text-purple-400" /> Garment & Apparel Attributes (Size, Color, Fabric, Fit)
                      </Label>
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <Label className="text-[11px] text-foreground">Apparel Size</Label>
                          <Input
                            type="text"
                            placeholder="e.g. S / M / L / XL / 38 / 40"
                            value={apparelSize}
                            onChange={(e) => setApparelSize(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Color / Shade</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Navy Blue / Crimson / Off-White"
                            value={apparelColor}
                            onChange={(e) => setApparelColor(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Fabric / Material</Label>
                          <Input
                            type="text"
                            placeholder="e.g. 100% Cotton / Denim / Silk"
                            value={apparelFabric}
                            onChange={(e) => setApparelFabric(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Fit / Style</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Slim Fit / Regular / Oversized"
                            value={apparelFit}
                            onChange={(e) => setApparelFit(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                      </div>
                    </div>
                  )}

                  {/* DYNAMIC CARD: FOOTWEAR SHOWROOM ATTRIBUTES */}
                  {activeTemplate === "FOOTWEAR" && (
                    <div className="space-y-2.5 bg-cyan-500/10 p-3.5 rounded-2xl border border-cyan-500/20 sm:col-span-2">
                      <Label className="text-xs text-cyan-300 font-extrabold flex items-center gap-1.5 uppercase tracking-wider">
                        <Tag className="h-4 w-4 text-cyan-400" /> Footwear Showroom Attributes (Size, Heel Height, Sole, Closure)
                      </Label>
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <Label className="text-[11px] text-foreground">Shoe Size (UK / US / EU)</Label>
                          <Input
                            type="text"
                            placeholder="e.g. UK 6 / UK 7 / UK 8 / UK 9 / EU 42"
                            value={apparelSize}
                            onChange={(e) => setApparelSize(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Color / Shade</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Tan Brown / Matte Black / White"
                            value={apparelColor}
                            onChange={(e) => setApparelColor(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Upper / Sole Material</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Genuine Leather / Rubber / EVA"
                            value={soleMaterial}
                            onChange={(e) => setSoleMaterial(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Heel Height / Type</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Flat / 2 Inches / Block Heel"
                            value={heelHeight}
                            onChange={(e) => setHeelHeight(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div>
                          <Label className="text-[11px] text-foreground">Closure Type</Label>
                          <Input
                            type="text"
                            placeholder="e.g. Lace-Up / Slip-On / Velcro"
                            value={closureType}
                            onChange={(e) => setClosureType(e.target.value)}
                            className="bg-background border-border text-foreground rounded-xl h-9 text-xs mt-1"
                          />
                        </div>
                        <div className="flex items-center pt-5">
                          <label className="flex items-center gap-2 text-xs text-cyan-300 cursor-pointer">
                            <input
                              type="checkbox"
                              checked={isWaterproof}
                              onChange={(e) => setIsWaterproof(e.target.checked)}
                              className="rounded-none border-border text-cyan-500"
                            />
                            Waterproof / All-Weather Footwear
                          </label>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* DYNAMIC CARD: JEWELLERY */}
                  {activeTemplate === "JEWELLERY" && (
                    <div className="space-y-2.5 bg-amber-500/10 p-3.5 rounded-2xl border border-amber-500/20 sm:col-span-2">
                      <Label className="text-xs text-amber-300 font-extrabold flex items-center gap-1.5 uppercase tracking-wider">
                        <Gem className="h-4 w-4 text-amber-400" /> Jewellery Attributes (Karat, Weight, Making Charges)
                      </Label>
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <Label className="text-[11px] text-foreground">Karat Purity</Label>
                          <select
                            value={karatPurity}
