                    <Label className="text-xs text-foreground">SKU Code *</Label>
                    <Input
                      required
                      type="text"
                      value={sku}
                      onChange={(e) => setSku(e.target.value)}
                      className="bg-background border-border text-foreground font-mono text-xs rounded-xl h-10"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Barcode (13-Digit EAN/UPC)</Label>
                    <Input
                      type="text"
                      value={barcode}
                      onChange={(e) => setBarcode(e.target.value)}
                      className="bg-background border-border text-foreground font-mono text-xs rounded-xl h-10"
                    />
                  </div>

                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground font-semibold">Product Category</Label>
                    <select
                      value={categoryName}
                      onChange={(e) => setCategoryName(e.target.value)}
                      className="w-full bg-background border border-border text-foreground rounded-xl h-10 text-xs px-3 focus:outline-none focus:ring-1 focus:ring-[#00aef0]"
                    >
                      <option value="">-- Select Category --</option>
                      {categoriesList.map((cat: any) => (
                        <option key={cat.id || cat.name} value={cat.name}>{cat.name}</option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground font-semibold">Manufacturer / Brand</Label>
                    <select
                      value={manufacturer}
                      onChange={(e) => setManufacturer(e.target.value)}
                      className="w-full bg-background border border-border text-foreground rounded-xl h-10 text-xs px-3 focus:outline-none focus:ring-1 focus:ring-[#00aef0]"
                    >
                      <option value="">-- Select Brand / Manufacturer --</option>
                      {brandsList.map((brand: any) => (
                        <option key={brand.id || brand.name} value={brand.name}>{brand.name}</option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-1.5 sm:col-span-2">
                    <Label className="text-xs text-foreground">Alias Name / Alternate Search Terms</Label>
                    <Input
                      type="text"
                      placeholder="Alternate search term"
                      value={aliasName}
                      onChange={(e) => setAliasName(e.target.value)}
                      className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                    />
                  </div>
                </div>
              )}

              {/* Tab 2: Units & Multi-Tier Pricing */}
              {activeTab === "UNITS_PRICING" && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground font-semibold">Base Sales Unit</Label>
                    <select
                      value={baseUnit}
                      onChange={(e) => setBaseUnit(e.target.value)}
                      className="w-full bg-background border border-border text-foreground rounded-xl h-10 text-xs px-3 font-mono uppercase focus:outline-none focus:ring-1 focus:ring-[#00aef0]"
                    >
                      {unitsList.map((u: any) => (
                        <option key={u.id || u.code} value={u.code}>{u.name} ({u.code})</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground font-semibold">Purchase Packaging Unit</Label>
                    <select
                      value={purchaseUnit}
                      onChange={(e) => setPurchaseUnit(e.target.value)}
                      className="w-full bg-background border border-border text-foreground rounded-xl h-10 text-xs px-3 font-mono uppercase focus:outline-none focus:ring-1 focus:ring-[#00aef0]"
                    >
                      {unitsList.map((u: any) => (
                        <option key={u.id || u.code} value={u.code}>{u.name} ({u.code})</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-1.5 sm:col-span-2">
                    <Label className="text-xs text-foreground">Conversion Factor (e.g. 1 Pack = 6 Pieces)</Label>
                    <Input
                      type="number"
                      value={conversionFactor}
                      onChange={(e) => setConversionFactor(e.target.value)}
                      className="bg-background border-border text-foreground rounded-xl h-10 text-xs font-mono"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Purchase Rate (₹)</Label>
                    <Input
                      type="number"
                      step="0.01"
                      placeholder="0.00"
                      value={purchasePrice}
                      onChange={(e) => setPurchasePrice(e.target.value)}
                      className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">MRP (Maximum Retail Price ₹)</Label>
                    <Input
                      type="number"
                      step="0.01"
                      placeholder="0.00"
                      value={mrp}
                      onChange={(e) => setMrp(e.target.value)}
                      className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Standard Selling Rate (₹)</Label>
                    <Input
                      type="number"
                      step="0.01"
                      placeholder="0.00"
                      value={sellingPrice}
                      onChange={(e) => setSellingPrice(e.target.value)}
                      className="bg-background border-border text-foreground font-bold rounded-xl h-10 text-xs text-[#00aef0]"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Wholesale Rate (₹)</Label>
                    <Input
                      type="number"
                      step="0.01"
                      placeholder="0.00"
                      value={wholesaleRate}
                      onChange={(e) => setWholesaleRate(e.target.value)}
                      className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                    />
                  </div>
                </div>
              )}

              {/* Tab 3: Tax & Statutory */}
              {activeTab === "TAX" && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">HSN / SAC Code</Label>
                    <Input
                      type="text"
                      value={hsnSacCode}
                      onChange={(e) => setHsnSacCode(e.target.value)}
                      className="bg-background border-border text-foreground font-mono text-xs rounded-xl h-10"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">GST Slab Rate (%)</Label>
                    <Input
                      type="number"
                      value={taxRate}
                      onChange={(e) => setTaxRate(e.target.value)}
                      placeholder="5"
                      className="bg-background border-border text-foreground font-mono text-xs rounded-xl h-10"
                    />
                  </div>
                  <div className="space-y-1.5 sm:col-span-2">
                    <label className="flex items-center gap-2 text-xs text-foreground cursor-pointer pt-2">
                      <input
                        type="checkbox"
                        checked={isTaxInclusive}
                        onChange={(e) => setIsTaxInclusive(e.target.checked)}
                        className="rounded-none border-border text-[#00aef0]"
                      />
                      Selling Price is Tax Inclusive (GST Included)
                    </label>
                  </div>
                </div>
              )}

              {/* Tab 4: Stock & Warehousing Location */}
              {activeTab === "INVENTORY" && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Initial Opening Stock</Label>
                    <Input
                      type="number"
                      value={initialStock}
                      onChange={(e) => setInitialStock(e.target.value)}
                      className="bg-background border-border text-foreground font-mono text-xs rounded-xl h-10"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Reorder Threshold Level</Label>
                    <Input
                      type="number"
                      value={reorderLevel}
                      onChange={(e) => setReorderLevel(e.target.value)}
                      className="bg-background border-border text-foreground font-mono text-xs rounded-xl h-10"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Shelf Number</Label>
                    <Input
                      type="text"
                      placeholder="e.g. Rack A-2"
                      value={shelfNumber}
                      onChange={(e) => setShelfNumber(e.target.value)}
                      className="bg-background border-border text-foreground text-xs rounded-xl h-10"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-foreground">Bin Location Code</Label>
                    <Input
                      type="text"
                      placeholder="e.g. BIN-204"
                      value={binLocation}
                      onChange={(e) => setBinLocation(e.target.value)}
                      className="bg-background border-border text-foreground text-xs rounded-xl h-10"
                    />
                  </div>
                </div>
              )}

              {/* Tab 5: Tracking & Flags */}
              {activeTab === "SETTINGS" && (
                <div className="space-y-3 pt-2">
                  <label className="flex items-center gap-2 text-xs text-foreground cursor-pointer">
                    <input
                      type="checkbox"
                      checked={trackBatch}
                      onChange={(e) => setTrackBatch(e.target.checked)}
                      className="rounded-none border-border text-[#00aef0]"
                    />
                    Enable Batch Number & Expiry Date Tracking (FEFO)
                  </label>
                  <label className="flex items-center gap-2 text-xs text-foreground cursor-pointer">
                    <input
                      type="checkbox"
                      checked={trackSerial}
                      onChange={(e) => setTrackSerial(e.target.checked)}
                      className="rounded-none border-border text-[#00aef0]"
                    />
                    Enable Serial Number / IMEI Tracking
                  </label>
                  <label className="flex items-center gap-2 text-xs text-foreground cursor-pointer">
                    <input
                      type="checkbox"
                      checked={allowNegativeStock}
                      onChange={(e) => setAllowNegativeStock(e.target.checked)}
                      className="rounded-none border-border text-[#00aef0]"
                    />
                    Allow Sales when Stock is Zero / Negative
                  </label>
                </div>
              )}

              {/* Tab 6: Interactive Ad-Hoc Custom Fields Builder */}
              {activeTab === "CUSTOM_FIELDS" && (
                <div className="space-y-4 pt-2">
                  <div className="bg-background p-3 rounded-2xl border border-border space-y-3">
                    <Label className="text-xs text-[#00aef0] font-bold flex items-center gap-1.5">
                      <PlusCircle className="h-4 w-4" /> Add Custom Field Definition for {activeTemplate}
                    </Label>
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                      <Input
                        type="text"
                        placeholder="Field Name (e.g. Bluetooth Version / Designer Name)"
                        value={newFieldName}
                        onChange={(e) => setNewFieldName(e.target.value)}
                        className="bg-card border-border text-foreground text-xs h-9"
                      />
                      <select
                        value={newFieldType}
                        onChange={(e) => setNewFieldType(e.target.value as any)}
                        className="bg-card border-border text-foreground text-xs rounded-xl px-2 h-9"
                      >
                        <option value="TEXT">Text Field</option>
                        <option value="NUMBER">Number Field</option>
                        <option value="DROPDOWN">Dropdown List</option>
                        <option value="BOOLEAN">Yes / No Toggle</option>
                      </select>
                      <IconAction label="Add Field" icon={<Plus className="h-3.5 w-3.5" />} type="button"
                        onClick={handleAddCustomField}
                        className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold text-xs h-9 rounded-xl gap-1" />
                    </div>
                  </div>

                  {/* Render Added Custom Fields */}
                  <div className="space-y-2 max-h-48 overflow-y-auto">
                    {customFields.length === 0 ? (
                      <div className="text-center py-6 text-muted-foreground text-xs">
                        No ad-hoc custom fields added yet. Use the builder above to add fields like Bluetooth Version, Designer Name, or Wi-Fi Standard.
                      </div>
                    ) : (
                      customFields.map((cf) => (
                        <div key={cf.id} className="flex items-center justify-between bg-background p-2.5 rounded-xl border border-border text-xs">
                          <div className="flex-1 pr-2">
                            <Label className="text-xs text-foreground font-bold">{cf.name}</Label>
                            <Input
                              type={cf.type === "NUMBER" ? "number" : "text"}
                              placeholder={`Enter ${cf.name}...`}
                              value={cf.value || ""}
                              onChange={(e) =>
                                setCustomFields((prev) =>
                                  prev.map((item) => (item.id === cf.id ? { ...item, value: e.target.value } : item))
                                )
                              }
                              className="bg-card border-border text-foreground text-xs h-8 mt-1"
                            />
                          </div>
                          <button
                            type="button"
                            onClick={() => handleRemoveCustomField(cf.id)}
                            className="text-rose-400 hover:text-rose-300 p-1"
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}

              <div className="flex items-center justify-end gap-2 pt-4 border-t border-border">
                <Button type="button" variant="outline" onClick={() => setShowAddModal(false)} className="border-border text-foreground rounded-xl h-10">
                  Cancel
                </Button>
                <Button type="submit" disabled={saving} className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl h-10 px-6">
                  {saving ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin mr-2" />
                      {editingProduct ? "Updating Product..." : "Saving Product..."}
                    </>
                  ) : editingProduct ? (
                    "Update Product Master"
                  ) : (
                    "Save Product Master"
                  )}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Truck,
  Plus,
  Package,
  RefreshCw,
  Search,
  CheckCircle2,
  Clock,
  Trash2,
  X,
  Building2,
  Info,
  ArrowDownLeft,
} from "lucide-react";
import { toast } from "sonner";

import { ProductCombobox } from "@/components/commerce/product-combobox";
import { IconAction } from "@/components/ui/icon-action";

interface POItemInput {
  id: string;
  product_id: string;
  product_name: string;
  quantity: number;
  unit_cost: number;
}

export default function PurchasesPage() {
  const { activeWorkspace } = useWorkspace();
  const [purchaseOrders, setPurchaseOrders] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [products, setProducts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [showAddModal, setShowAddModal] = useState(false);
  const [saving, setSaving] = useState(false);

  // Form State
  const [selectedSupplierId, setSelectedSupplierId] = useState("");
  const [poStatus, setPoStatus] = useState<"ORDERED" | "RECEIVED">("RECEIVED");
  const [notes, setNotes] = useState("");
  const [poItems, setPoItems] = useState<POItemInput[]>([]);

  // Item Selector State inside modal
  const [selectedProductId, setSelectedProductId] = useState("");
  const [itemQty, setItemQty] = useState("10");
  const [itemCost, setItemCost] = useState("");

  const fetchPurchasesData = async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const [poRes, suppRes, prodRes] = await Promise.all([
        fetch(`/api/commerce/purchases?workspace_id=${activeWorkspace.id}`),
        fetch(`/api/commerce/suppliers?workspace_id=${activeWorkspace.id}`),
        fetch(`/api/commerce/products?workspace_id=${activeWorkspace.id}`),
      ]);

      const poJson = await poRes.json();
      const suppJson = await suppRes.json();
      const prodJson = await prodRes.json();

      if (poRes.ok) setPurchaseOrders(poJson.purchase_orders || []);
      if (suppRes.ok) setSuppliers(suppJson.suppliers || []);
      if (prodRes.ok) setProducts(prodJson.products || []);
    } catch {
      toast.error("Failed to load purchase orders data");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPurchasesData();
  }, [activeWorkspace?.id]);

  const handleAddItemToPO = () => {
    if (!selectedProductId) {
      toast.error("Please select a product from catalog");
      return;
    }
    const matchedProd = products.find((p) => p.id === selectedProductId);
    if (!matchedProd) return;

    const qtyNum = Number(itemQty || 1);
    const costNum = Number(itemCost || matchedProd.purchase_price || 0);

    const newItem: POItemInput = {
      id: `${Date.now()}-${Math.random()}`,
      product_id: matchedProd.id,
      product_name: matchedProd.name,
      quantity: qtyNum,
      unit_cost: costNum,
    };

    setPoItems((prev) => [...prev, newItem]);
    setSelectedProductId("");
    setItemQty("10");
    setItemCost("");
    toast.success(`Added ${matchedProd.name} to order`);
  };

  const handleRemoveItemFromPO = (id: string) => {
    setPoItems((prev) => prev.filter((item) => item.id !== id));
  };

  const handleCreatePO = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id) return;
    if (poItems.length === 0) {
      toast.error("Please add at least one product item to the purchase order");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/commerce/purchases", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          workspace_id: activeWorkspace.id,
          supplier_id: selectedSupplierId || undefined,
          status: poStatus,
          notes,
          items: poItems.map((item) => ({
            product_id: item.product_id,
            quantity: item.quantity,
            unit_cost: item.unit_cost,
          })),
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to create Purchase Order");

      toast.success(
        poStatus === "RECEIVED"
          ? "Purchase Order created & Stock Inward logged into Inventory!"
          : "Purchase Order created!"
      );
      setShowAddModal(false);
      setSelectedSupplierId("");
      setNotes("");
      setPoItems([]);
      fetchPurchasesData();
    } catch (err: any) {
      toast.error(err.message || "Failed to create purchase order");
    } finally {
      setSaving(false);
    }
  };

  const grandTotalPO = poItems.reduce(
    (acc, item) => acc + item.quantity * item.unit_cost,
    0
  );

  const filteredPOs = purchaseOrders.filter(
    (po) =>
      po.po_number?.toLowerCase().includes(query.toLowerCase()) ||
      po.supplier?.company_name?.toLowerCase().includes(query.toLowerCase())
  );

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <Truck className="h-6 w-6 text-[#00aef0]" />
            Purchase Orders & Goods Inward
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Manage procurement, supplier purchase orders, and stock inward bills.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <IconAction label="Refresh" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchPurchasesData}
            variant="outline"
            className="border-border text-foreground gap-1.5 rounded-xl h-11" />
          <IconAction label="Create Purchase Order" icon={<Plus className="h-4 w-4" />} onClick={() => setShowAddModal(true)}
            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20 gap-2 h-11" />
        </div>
      </div>

      {/* Business Workflow Banner */}
      <div className="bg-card/90 border border-border p-4 rounded-2xl flex items-center gap-3 text-xs text-foreground">
        <Info className="h-5 w-5 text-[#00aef0] shrink-0" />
        <div>
          <strong className="text-foreground block font-bold text-sm">
            Procurement & Stock Inward Workflow:
          </strong>
          Select a Supplier → Add catalog products & purchase costs → Setting status to{" "}
          <span className="text-emerald-400 font-bold">RECEIVED</span> automatically updates inventory stock levels across your catalog!
        </div>
      </div>

      {/* Search Bar */}
      <div className="flex items-center gap-3 bg-card/80 p-3 rounded-2xl border border-border backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search by PO Number or Supplier Name..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border text-foreground rounded-xl focus:border-[#00aef0]"
          />
        </div>
      </div>

      {/* Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4">PO #</th>
                <th className="py-3.5 px-4 hidden sm:table-cell">Date</th>
                <th className="py-3.5 px-4">Supplier</th>
                <th className="py-3.5 px-4 text-center hidden md:table-cell">Items Count</th>
                <th className="py-3.5 px-4 text-right">Total Cost</th>
                <th className="py-3.5 px-4 text-center">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-muted-foreground text-sm">
                    Loading Purchase Orders...
                  </td>
                </tr>
              ) : filteredPOs.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-muted-foreground text-sm space-y-3">
                    <Package className="h-10 w-10 mx-auto text-muted-foreground mb-2" />
                    <p className="text-foreground font-semibold">No Purchase Orders Created Yet</p>
                    <p className="text-xs text-muted-foreground max-w-sm mx-auto">
                      Create purchase orders to order stock from suppliers and track inward stock receipts.
                    </p>
                    <IconAction label="Create First Purchase Order" icon={<Plus className="h-4 w-4" />} onClick={() => setShowAddModal(true)}
                      className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl gap-2 mt-2" />
                  </td>
                </tr>
              ) : (
                filteredPOs.map((po) => (
                  <tr key={po.id} className="hover:bg-muted/40 transition-colors">
                    <td className="py-3.5 px-4 font-mono font-bold text-foreground">
                      #{po.po_number}
                    </td>
                    <td className="py-3.5 px-4 text-xs text-muted-foreground hidden sm:table-cell">
                      {new Date(po.created_at).toLocaleDateString()}
                    </td>
                    <td className="py-3.5 px-4 text-xs font-semibold text-foreground">
                      {po.supplier?.company_name || "Direct Vendor"}
                    </td>
                    <td className="py-3.5 px-4 text-center text-xs font-bold text-[#00aef0] hidden md:table-cell">
                      {po.items?.length || 0} Items
                    </td>
                    <td className="py-3.5 px-4 text-right font-extrabold text-foreground">
                      ₹{Number(po.total_amount || 0).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-center">
                      {po.status === "RECEIVED" ? (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                          <CheckCircle2 className="h-3 w-3" />
                          RECEIVED (Stock Inward)
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-semibold bg-amber-500/10 text-amber-400 border border-amber-500/20">
                          <Clock className="h-3 w-3" />
                          {po.status || "ORDERED"}
                        </span>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Create Purchase Order Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto overflow-x-hidden [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
          <div className="bg-card border border-border rounded-3xl max-w-2xl w-full p-6 space-y-4 shadow-2xl text-foreground my-8 overflow-x-hidden">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <Truck className="h-5 w-5 text-[#00aef0]" />
                Create Purchase Order &amp; Stock Inward
              </h2>
              <button onClick={() => setShowAddModal(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            <form onSubmit={handleCreatePO} className="space-y-4 text-xs">
              {/* Supplier & Status */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Select Supplier / Vendor</Label>
                  <select
                    value={selectedSupplierId}
                    onChange={(e) => setSelectedSupplierId(e.target.value)}
                    className="w-full bg-background border border-border text-foreground rounded-xl h-10 px-3 text-xs"
                  >
                    <option value="">-- Direct Supplier / Vendor --</option>
                    {suppliers.map((s) => (
                      <option key={s.id} value={s.id}>
                        {s.company_name} ({s.contact_person || "Vendor"})
                      </option>
                    ))}
                  </select>
                </div>

                <div className="space-y-1">
                  <Label className="text-xs text-foreground">PO Status</Label>
                  <select
                    value={poStatus}
                    onChange={(e) => setPoStatus(e.target.value as any)}
                    className="w-full bg-background border border-border text-foreground rounded-xl h-10 px-3 text-xs font-bold"
                  >
                    <option value="RECEIVED">RECEIVED (Auto Inward Stock into Catalog)</option>
                    <option value="ORDERED">ORDERED (Pending Goods Receipt)</option>
                  </select>
                </div>
              </div>

              {/* Add Items Builder Card */}
              <div className="bg-background p-4 rounded-2xl border border-border space-y-3">
                <h4 className="text-xs font-bold uppercase tracking-wider text-[#00aef0] flex items-center gap-1.5">
                  <Package className="h-4 w-4" /> Add Catalog Items to PO
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                  <div className="sm:col-span-1">
                    <Label className="text-[11px] text-muted-foreground">Search &amp; Select Product</Label>
                    <div className="mt-1">
                      <ProductCombobox
                        products={products}
                        selectedProductId={selectedProductId}
                        onSelect={(p) => {
                          if (p) {
                            setSelectedProductId(p.id);
                            setItemCost(String(p.purchase_price || p.selling_price || 0));
                          } else {
                            setSelectedProductId("");
                          }
                        }}
                        placeholder="Type name, SKU, or scan barcode..."
                      />
                    </div>
                  </div>
                  <div>
                    <Label className="text-[11px] text-muted-foreground">Inward Qty</Label>
                    <Input
                      type="number"
                      min="1"
                      value={itemQty}
                      onChange={(e) => setItemQty(e.target.value)}
                      className="bg-card border-border text-foreground rounded-xl h-9 text-xs mt-1"
                    />
                  </div>
                  <div>
                    <Label className="text-[11px] text-muted-foreground">Unit Purchase Price (₹)</Label>
                    <Input
                      type="number"
                      placeholder="Cost price..."
                      value={itemCost}
                      onChange={(e) => setItemCost(e.target.value)}
                      className="bg-card border-border text-foreground rounded-xl h-9 text-xs mt-1"
                    />
                  </div>
                </div>
                <IconAction label="Add Line Item" icon={<Plus className="h-3.5 w-3.5" />} type="button"
                  onClick={handleAddItemToPO}
                  className="bg-[#00aef0]/10 hover:bg-[#00aef0]/20 text-[#00aef0] font-bold rounded-xl text-xs h-8 w-full gap-1" />
              </div>

              {/* Added Line Items Table */}
              {poItems.length > 0 && (
                <div className="rounded-2xl border border-border bg-background overflow-hidden">
                  <table className="w-full text-left text-xs text-foreground">
                    <thead className="bg-card font-semibold text-muted-foreground border-b border-border">
                      <tr>
                        <th className="py-2 px-3">Product</th>
                        <th className="py-2 px-3 text-center">Qty</th>
                        <th className="py-2 px-3 text-right">Cost</th>
                        <th className="py-2 px-3 text-right">Total</th>
                        <th className="py-2 px-3 text-center">Action</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-border/60">
                      {poItems.map((item) => (
                        <tr key={item.id}>
                          <td className="py-2 px-3 font-semibold text-foreground">
                            {item.product_name}
                          </td>
                          <td className="py-2 px-3 text-center font-bold">
                            {item.quantity}
                          </td>
                          <td className="py-2 px-3 text-right">
                            ₹{item.unit_cost.toFixed(2)}
                          </td>
                          <td className="py-2 px-3 text-right font-bold text-[#00aef0]">
                            ₹{(item.quantity * item.unit_cost).toFixed(2)}
                          </td>
                          <td className="py-2 px-3 text-center">
                            <button
                              type="button"
                              onClick={() => handleRemoveItemFromPO(item.id)}
                              className="text-rose-400 hover:text-rose-300"
                            >
                              <Trash2 className="h-4 w-4" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <div className="p-3 bg-card/90 text-right text-xs font-bold text-foreground border-t border-border">
                    Grand Total: <span className="text-[#00aef0] text-sm font-extrabold ml-2">₹{grandTotalPO.toFixed(2)}</span>
                  </div>
                </div>
              )}

              {/* Notes */}
              <div className="space-y-1">
                <Label className="text-xs text-foreground">Notes / Remarks</Label>
                <Input
                  type="text"
                  placeholder="e.g. Stock batch received at Main Warehouse"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="bg-background border-border text-foreground rounded-xl h-9 text-xs"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border">
                <Button type="button" variant="outline" onClick={() => setShowAddModal(false)} className="border-border text-foreground rounded-xl h-10">
                  Cancel
                </Button>
                <Button type="submit" disabled={saving} className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl h-10 px-5">
                  {saving ? "Saving PO..." : "Save Purchase Order"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { BarChart3, Download, Landmark, ArrowUpRight } from "lucide-react";
import { IconAction } from "@/components/ui/icon-action";

export default function ReportsHubPage() {
  useWorkspace();
  const [activeTab, setActiveTab] = useState<"TRIAL_BALANCE" | "PL_STATEMENT" | "BALANCE_SHEET" | "AGING">("TRIAL_BALANCE");

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <BarChart3 className="h-6 w-6 text-[#00aef0]" />
            Financial Statements & Executive BI Analytics
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Real-time Trial Balance, Profit & Loss Statement, Balance Sheet, and AR/AP Aging Analysis.
          </p>
        </div>
        <IconAction label="Export Financial PDF/Excel" icon={<Download className="h-4 w-4" />} variant="outline" className="border-border text-foreground gap-1.5 rounded-xl h-11" />
      </div>

      {/* Tabs */}
      <div className="flex items-center gap-2 border-b border-border pb-2 overflow-x-auto">
        {(["TRIAL_BALANCE", "PL_STATEMENT", "BALANCE_SHEET", "AGING"] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 text-sm font-semibold rounded-xl transition-all ${
              activeTab === tab
                ? "bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            {tab === "TRIAL_BALANCE" && "Trial Balance Sheet"}
            {tab === "PL_STATEMENT" && "Profit & Loss (P&L)"}
            {tab === "BALANCE_SHEET" && "Balance Sheet"}
            {tab === "AGING" && "AR/AP Aging Analysis"}
          </button>
        ))}
      </div>

      {/* Content Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="p-5 bg-card/90 border border-border rounded-2xl space-y-2">
          <div className="text-xs text-muted-foreground font-bold uppercase">Total Revenue (YTD)</div>
          <div className="text-2xl font-extrabold text-foreground">₹1,24,500.00</div>
          <div className="text-xs text-emerald-400 flex items-center gap-1">
            <ArrowUpRight className="h-4 w-4" /> +14.2% from last month
          </div>
        </div>

        <div className="p-5 bg-card/90 border border-border rounded-2xl space-y-2">
          <div className="text-xs text-muted-foreground font-bold uppercase">Cost of Goods Sold (COGS)</div>
          <div className="text-2xl font-extrabold text-rose-400">₹78,200.00</div>
          <div className="text-xs text-muted-foreground">Gross Margin: 37.1%</div>
        </div>

        <div className="p-5 bg-card/90 border border-border rounded-2xl space-y-2">
          <div className="text-xs text-muted-foreground font-bold uppercase">Net Operating Profit</div>
          <div className="text-2xl font-extrabold text-emerald-400">₹46,300.00</div>
          <div className="text-xs text-muted-foreground">After operational expenses</div>
        </div>
      </div>

      {/* Main Financial Table View */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl p-8 text-center text-muted-foreground">
        <Landmark className="h-10 w-10 mx-auto text-[#00aef0] mb-3" />
        <h3 className="text-lg font-bold text-foreground">Real-Time General Ledger Reconciliation Active</h3>
        <p className="text-xs text-muted-foreground max-w-md mx-auto mt-1">
          Trial Balance reconciled automatically: Total Debit (₹1,24,500.00) = Total Credit (₹1,24,500.00).
        </p>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  RefreshCw,
  Plus,
  ArrowLeftRight,
  Search,
  CheckCircle2,
  X,
  FileText,
  Info,
  Receipt,
} from "lucide-react";
import { toast } from "sonner";
import { ProductCombobox } from "@/components/commerce/product-combobox";
import { IconAction } from "@/components/ui/icon-action";

export default function ReturnsPage() {
  const { activeWorkspace } = useWorkspace();
  const [returnsList, setReturnsList] = useState<any[]>([]);
  const [salesOrders, setSalesOrders] = useState<any[]>([]);
  const [products, setProducts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [showAddModal, setShowAddModal] = useState(false);
  const [saving, setSaving] = useState(false);

  // Form State
  const [selectedOrderId, setSelectedOrderId] = useState("");
  const [returnReason, setReturnReason] = useState<
    "DEFECTIVE" | "EXPIRED" | "WRONG_ITEM" | "CUSTOMER_MIND_CHANGE" | "OTHER"
  >("CUSTOMER_MIND_CHANGE");
  const [refundMode, setRefundMode] = useState<"CASH" | "BANK" | "KHATA_CREDIT">("CASH");
  const [refundAmount, setRefundAmount] = useState("");
  const [selectedProductId, setSelectedProductId] = useState("");
  const [quantityReturned, setQuantityReturned] = useState("1");
  const [restockInventory, setRestockInventory] = useState(true);

  const fetchReturnsData = async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const [retRes, salesRes, prodRes] = await Promise.all([
        fetch(`/api/commerce/returns?workspace_id=${activeWorkspace.id}`),
        fetch(`/api/commerce/sales?workspace_id=${activeWorkspace.id}`),
        fetch(`/api/commerce/products?workspace_id=${activeWorkspace.id}`),
      ]);

      const retJson = await retRes.json();
      const salesJson = await salesRes.json();
      const prodJson = await prodRes.json();

      if (retRes.ok) setReturnsList(retJson.returns || []);
      if (salesRes.ok) setSalesOrders(salesJson.sales_orders || []);
      if (prodRes.ok) setProducts(prodJson.products || []);
    } catch {
      toast.error("Failed to load returns data");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchReturnsData();
  }, [activeWorkspace?.id]);

  const handleProcessReturn = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !refundAmount) {
      toast.error("Refund amount is required");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/commerce/returns", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          workspace_id: activeWorkspace.id,
          sales_order_id: selectedOrderId || undefined,
          return_reason: returnReason,
          refund_mode: refundMode,
          total_refund_amount: Number(refundAmount),
          product_id: selectedProductId || undefined,
          quantity_returned: Number(quantityReturned || 1),
          restock_inventory: restockInventory,
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to process return");

      toast.success(
        restockInventory
          ? "Return processed & Item restocked into inventory!"
          : "Return ticket logged!"
      );
      setShowAddModal(false);
      setSelectedOrderId("");
      setRefundAmount("");
      setSelectedProductId("");
      fetchReturnsData();
    } catch (err: any) {
      toast.error(err.message || "Failed to process return");
    } finally {
      setSaving(false);
    }
  };

  const filtered = returnsList.filter(
    (r) =>
      r.return_number?.toLowerCase().includes(query.toLowerCase()) ||
      r.sales_order?.order_number?.toLowerCase().includes(query.toLowerCase())
  );

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <RefreshCw className="h-6 w-6 text-[#00aef0]" />
            Sales &amp; Purchase Returns
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Process customer sales returns, credit notes, and restock returned products.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <IconAction label="Refresh" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchReturnsData}
            variant="outline"
            className="border-border text-foreground gap-1.5 rounded-xl h-11" />
          <IconAction label="Process Return" icon={<Plus className="h-4 w-4" />} onClick={() => setShowAddModal(true)}
            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20 gap-2 h-11" />
        </div>
      </div>

      {/* Business Workflow Banner */}
      <div className="bg-card/90 border border-border p-4 rounded-2xl flex items-center gap-3 text-xs text-foreground">
        <Info className="h-5 w-5 text-[#00aef0] shrink-0" />
        <div>
          <strong className="text-foreground block font-bold text-sm">
            Sales Returns Workflow:
          </strong>
          Select Ref Invoice → Choose return reason &amp; refund mode → Selecting{" "}
          <span className="text-emerald-400 font-bold">Restock Inventory</span> automatically adds returned items back into active stock!
        </div>
      </div>

      {/* Search */}
      <div className="flex items-center gap-3 bg-card/80 p-3 rounded-2xl border border-border backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search by Return # or Ref Invoice #..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border text-foreground rounded-xl focus:border-[#00aef0]"
          />
        </div>
      </div>

      {/* Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4">Return #</th>
                <th className="py-3.5 px-4">Date</th>
                <th className="py-3.5 px-4">Ref Order #</th>
                <th className="py-3.5 px-4">Reason</th>
                <th className="py-3.5 px-4">Refund Mode</th>
                <th className="py-3.5 px-4 text-right">Refund Amount</th>
                <th className="py-3.5 px-4 text-center">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={7} className="py-12 text-center text-muted-foreground text-sm">
                    Loading Return Tickets...
                  </td>
                </tr>
              ) : filtered.length === 0 ? (
                <tr>
                  <td colSpan={7} className="py-12 text-center text-muted-foreground text-sm space-y-3">
                    <ArrowLeftRight className="h-10 w-10 mx-auto text-muted-foreground mb-2" />
                    <p className="text-foreground font-semibold">No Sales Returns Logged</p>
                    <p className="text-xs text-muted-foreground max-w-sm mx-auto">
                      Issue credit notes for sales returns or record damaged stock returns.
                    </p>
                    <IconAction label="Process First Return" icon={<Plus className="h-4 w-4" />} onClick={() => setShowAddModal(true)}
                      className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl gap-2 mt-2" />
                  </td>
                </tr>
              ) : (
                filtered.map((ret) => (
                  <tr key={ret.id} className="hover:bg-muted/40 transition-colors">
                    <td className="py-3.5 px-4 font-mono font-bold text-foreground">
                      #{ret.return_number}
                    </td>
                    <td className="py-3.5 px-4 text-xs text-muted-foreground">
                      {new Date(ret.created_at).toLocaleDateString()}
                    </td>
                    <td className="py-3.5 px-4 font-mono text-xs text-[#00aef0]">
                      {ret.sales_order?.order_number ? `#${ret.sales_order.order_number}` : "Direct Return"}
                    </td>
                    <td className="py-3.5 px-4 text-xs text-foreground font-medium">
                      {ret.return_reason?.replace(/_/g, " ")}
                    </td>
                    <td className="py-3.5 px-4 text-xs font-semibold text-foreground">
                      {ret.refund_mode}
                    </td>
                    <td className="py-3.5 px-4 text-right font-extrabold text-rose-400">
                      ₹{Number(ret.total_refund_amount || 0).toFixed(2)}
                    </td>
                    <td className="py-3.5 px-4 text-center">
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                        <CheckCircle2 className="h-3 w-3" />
                        PROCESSED
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Process Return Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto overflow-x-hidden [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
          <div className="bg-card border border-border rounded-3xl max-w-lg w-full p-6 space-y-4 shadow-2xl text-foreground my-8 overflow-x-hidden">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <RefreshCw className="h-5 w-5 text-[#00aef0]" />
                Process Sales Return &amp; Credit Note
              </h2>
              <button onClick={() => setShowAddModal(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            <form onSubmit={handleProcessReturn} className="space-y-3 text-xs">
              <div className="space-y-1">
                <Label className="text-xs text-foreground">Select Ref Sales Order / Invoice</Label>
                <select
                  value={selectedOrderId}
                  onChange={(e) => {
                    setSelectedOrderId(e.target.value);
                    const o = salesOrders.find((so) => so.id === e.target.value);
                    if (o) setRefundAmount(String(o.grand_total || 0));
                  }}
                  className="w-full bg-background border border-border text-foreground rounded-xl h-10 px-3 text-xs"
                >
                  <option value="">-- Direct Retail Return --</option>
                  {salesOrders.map((so) => (
                    <option key={so.id} value={so.id}>
                      Invoice #{so.order_number} (₹{Number(so.grand_total).toFixed(2)})
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Return Reason</Label>
                  <select
                    value={returnReason}
                    onChange={(e) => setReturnReason(e.target.value as any)}
                    className="w-full bg-background border border-border text-foreground rounded-xl h-10 px-2 text-xs"
                  >
                    <option value="CUSTOMER_MIND_CHANGE">Customer Mind Change</option>
                    <option value="DEFECTIVE">Defective Product</option>
                    <option value="EXPIRED">Expired Product</option>
                    <option value="WRONG_ITEM">Wrong Item Billed</option>
                    <option value="OTHER">Other Reason</option>
                  </select>
                </div>

                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Refund Mode</Label>
                  <select
                    value={refundMode}
                    onChange={(e) => setRefundMode(e.target.value as any)}
                    className="w-full bg-background border border-border text-foreground rounded-xl h-10 px-2 text-xs font-bold"
                  >
                    <option value="CASH">CASH (Refund from Drawer)</option>
                    <option value="BANK">BANK / UPI Refund</option>
                    <option value="KHATA_CREDIT">KHATA CREDIT (Reduce Balance)</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Product to Restock (Optional)</Label>
                  <ProductCombobox
                    products={products}
                    selectedProductId={selectedProductId}
                    onSelect={(p) => setSelectedProductId(p ? p.id : "")}
                    placeholder="Search product to restock..."
                  />
                </div>

                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Refund Amount (₹) *</Label>
                  <Input
                    required
                    type="number"
                    placeholder="Enter amount..."
                    value={refundAmount}
                    onChange={(e) => setRefundAmount(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs font-bold"
                  />
                </div>
              </div>

              {selectedProductId && (
                <div className="flex items-center gap-2 bg-background p-3 rounded-xl border border-border">
                  <input
                    type="checkbox"
                    id="restockCheck"
                    checked={restockInventory}
                    onChange={(e) => setRestockInventory(e.target.checked)}
                    className="rounded-none bg-card border-border text-[#00aef0]"
                  />
                  <Label htmlFor="restockCheck" className="text-xs text-foreground cursor-pointer">
                    Restock returned item into active Inventory stock
                  </Label>
                </div>
              )}

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border">
                <Button type="button" variant="outline" onClick={() => setShowAddModal(false)} className="border-border text-foreground rounded-xl h-10">
                  Cancel
                </Button>
                <Button type="submit" disabled={saving} className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl h-10 px-5">
                  {saving ? "Processing..." : "Process Return"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Receipt,
  RefreshCw,
  Search,
  Printer,
  Eye,
  X,
  CreditCard,
  Banknote,
  Smartphone,
  BookOpen,
  Calendar,
  User,
  ShoppingBag,
  CheckCircle2,
  FileText,
} from "lucide-react";
import { toast } from "sonner";
import { IconAction } from "@/components/ui/icon-action";

export default function SalesPage() {
  const { activeWorkspace } = useWorkspace();
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [selectedOrder, setSelectedOrder] = useState<any | null>(null);
  const [showInvoiceModal, setShowInvoiceModal] = useState(false);

  const fetchOrders = async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const res = await fetch(
        `/api/commerce/sales?workspace_id=${activeWorkspace.id}&query=${encodeURIComponent(query)}`
      );
      const json = await res.json();
      if (res.ok && json.sales_orders) {
        setOrders(json.sales_orders);
      }
    } catch {
      toast.error("Failed to load sales orders");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, [activeWorkspace?.id, query]);

  const totalRevenue = orders.reduce(
    (acc, order) => acc + Number(order.grand_total || 0),
    0
  );

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <Receipt className="h-6 w-6 text-[#00aef0]" />
            Sales Orders & Tax Invoices
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            View real-time completed POS checkout transactions, B2B sales invoices, and customer receipts.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="bg-card border border-border px-4 py-2 rounded-xl text-right">
            <span className="text-[11px] text-muted-foreground font-semibold uppercase tracking-wider block">
              Total Invoiced Revenue
            </span>
            <span className="text-lg font-extrabold text-[#00aef0]">
              ₹{totalRevenue.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </span>
          </div>
          <IconAction label="Refresh Orders" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchOrders}
            variant="outline"
            className="border-border text-foreground gap-1.5 rounded-xl h-11" />
        </div>
      </div>

      {/* Search Bar */}
      <div className="flex items-center gap-3 bg-card/80 p-3 rounded-2xl border border-border backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search by Order #, Invoice Series, Customer Phone..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border text-foreground rounded-xl focus:border-[#00aef0]"
          />
        </div>
      </div>

      {/* Sales Orders Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4">Order / Invoice #</th>
                <th className="py-3.5 px-4 hidden sm:table-cell">Date &amp; Time</th>
                <th className="py-3.5 px-4">Customer</th>
                <th className="py-3.5 px-4 hidden lg:table-cell">Channel</th>
                <th className="py-3.5 px-4 hidden md:table-cell">Payment Method</th>
                <th className="py-3.5 px-4 text-right hidden lg:table-cell">Tax Total</th>
                <th className="py-3.5 px-4 text-right">Grand Total</th>
                <th className="py-3.5 px-4 text-center">Status</th>
                <th className="py-3.5 px-4 text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={9} className="py-12 text-center text-muted-foreground text-sm">
