                      </td>
                      <td className="py-3.5 px-4 uppercase text-xs font-bold text-[#00aef0] hidden lg:table-cell">
                        <span className="bg-[#00aef0]/10 px-2 py-0.5 rounded-lg border border-[#00aef0]/20">
