                        </span>
                      </td>
                      <td className="py-3.5 px-4 text-xs text-foreground font-semibold hidden md:table-cell">
                        <span className="flex items-center gap-1.5">
                          {order.payment_method === "CASH" && <Banknote className="h-3.5 w-3.5 text-emerald-400" />}
                          {order.payment_method === "UPI" && <Smartphone className="h-3.5 w-3.5 text-purple-400" />}
                          {order.payment_method === "CARD" && <CreditCard className="h-3.5 w-3.5 text-sky-400" />}
                          {order.payment_method === "KHATA_CREDIT" && <BookOpen className="h-3.5 w-3.5 text-amber-400" />}
                          {order.payment_method}
                        </span>
                      </td>
                      <td className="py-3.5 px-4 text-right text-xs text-muted-foreground hidden lg:table-cell">
                        ₹{Number(order.tax_total || 0).toFixed(2)}
                      </td>
                      <td className="py-3.5 px-4 text-right font-extrabold text-foreground">
                        ₹{Number(order.grand_total).toFixed(2)}
                      </td>
                      <td className="py-3.5 px-4 text-center">
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                          <CheckCircle2 className="h-3 w-3 mr-1" />
                          {order.payment_status || "PAID"}
                        </span>
                      </td>
                      <td className="py-3.5 px-4 text-center">
                        <IconAction label="View Invoice" icon={<Eye className="h-3.5 w-3.5 text-[#00aef0]" />} variant="outline"
                          onClick={() => {
                            setSelectedOrder(order);
                            setShowInvoiceModal(true);
                          }}
                          className="border-border hover:border-[#00aef0] bg-card hover:bg-muted text-foreground hover:text-[#00aef0] text-xs rounded-xl gap-1.5 h-8" />
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Invoice Detail Modal */}
      {showInvoiceModal && selectedOrder && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-md flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-card border border-border rounded-3xl max-w-2xl w-full p-6 space-y-6 shadow-2xl my-8 text-foreground relative">
            {/* Modal Header */}
            <div className="flex items-center justify-between border-b border-border pb-4">
              <div>
                <span className="bg-[#00aef0]/10 text-[#00aef0] px-2.5 py-0.5 rounded-lg text-xs font-bold uppercase tracking-wider flex items-center gap-1 w-fit">
                  <Receipt className="h-3.5 w-3.5" /> Tax Invoice #{selectedOrder.order_number}
                </span>
                <h2 className="text-xl font-extrabold text-foreground tracking-tight mt-1">
                  POS Sales Receipt
                </h2>
                <div className="flex items-center gap-3 text-xs text-muted-foreground mt-1">
                  <span className="flex items-center gap-1">
                    <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                    {new Date(selectedOrder.created_at).toLocaleString()}
                  </span>
                  <span>•</span>
                  <span className="text-emerald-400 font-semibold">
                    Payment Status: {selectedOrder.payment_status || "PAID"}
                  </span>
                </div>
              </div>
              <button
                onClick={() => setShowInvoiceModal(false)}
                className="p-2 text-muted-foreground hover:text-foreground hover:bg-muted rounded-xl transition-colors"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            {/* Customer & Counter Banner */}
            <div className="grid grid-cols-2 gap-3 bg-background p-3.5 rounded-2xl border border-border text-xs">
              <div>
                <span className="text-muted-foreground block">Customer Information</span>
                <span className="font-bold text-foreground block mt-0.5">
                  {selectedOrder.customer
                    ? `${selectedOrder.customer.first_name} ${selectedOrder.customer.last_name || ""}`
                    : selectedOrder.is_walkin_customer
                    ? "Walk-in Retail Customer"
                    : selectedOrder.customer_mobile || "Guest Customer"}
                </span>
                {selectedOrder.customer_gstin && (
                  <span className="text-[11px] text-muted-foreground block font-mono">
                    GSTIN: {selectedOrder.customer_gstin}
                  </span>
                )}
              </div>
              <div>
                <span className="text-muted-foreground block">Billing Details</span>
                <span className="font-bold text-[#00aef0] block mt-0.5 uppercase">
                  Counter: {selectedOrder.counter_number || "COUNTER-1"} ({selectedOrder.channel || "POS"})
                </span>
                <span className="text-[11px] text-muted-foreground block">
                  Payment Mode: {selectedOrder.payment_method}
                </span>
              </div>
            </div>

            {/* Line Items Table */}
            <div className="rounded-2xl border border-border overflow-hidden bg-background">
              <table className="w-full text-left text-xs text-foreground">
                <thead className="bg-card/90 font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
                  <tr>
                    <th className="py-2.5 px-3">Item Description</th>
                    <th className="py-2.5 px-3 text-center">Qty</th>
                    <th className="py-2.5 px-3 text-right">Unit Price</th>
                    <th className="py-2.5 px-3 text-right">GST %</th>
                    <th className="py-2.5 px-3 text-right">Amount</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/60">
                  {(selectedOrder.items || []).map((item: any, idx: number) => (
                    <tr key={item.id || idx}>
                      <td className="py-2.5 px-3 font-semibold text-foreground">
                        {item.product?.name || `Product ID #${item.product_id}`}
                        {item.product?.sku && (
                          <span className="block text-[10px] text-muted-foreground font-mono">
                            SKU: {item.product.sku}
                          </span>
                        )}
                      </td>
                      <td className="py-2.5 px-3 text-center font-bold">
                        {item.quantity}
                      </td>
                      <td className="py-2.5 px-3 text-right">
                        ₹{Number(item.selling_price || item.unit_price || 0).toFixed(2)}
                      </td>
                      <td className="py-2.5 px-3 text-right text-purple-400 font-mono">
                        {item.tax_rate || 0}%
                      </td>
                      <td className="py-2.5 px-3 text-right font-extrabold text-foreground">
                        ₹{Number(item.total_price || item.quantity * item.selling_price).toFixed(2)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Totals Summary */}
            <div className="bg-background p-4 rounded-2xl border border-border space-y-2 text-xs">
              <div className="flex justify-between text-muted-foreground">
                <span>Subtotal</span>
                <span>₹{Number(selectedOrder.subtotal || 0).toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-muted-foreground">
                <span>GST Tax Total</span>
                <span>₹{Number(selectedOrder.tax_total || 0).toFixed(2)}</span>
              </div>
              {Number(selectedOrder.discount_amount || 0) > 0 && (
                <div className="flex justify-between text-emerald-400 font-semibold">
                  <span>Discount Applied</span>
                  <span>-₹{Number(selectedOrder.discount_amount).toFixed(2)}</span>
                </div>
              )}
              <div className="border-t border-border pt-2 flex justify-between text-sm font-extrabold text-foreground">
                <span>Grand Total</span>
                <span className="text-[#00aef0] text-base">
                  ₹{Number(selectedOrder.grand_total).toFixed(2)}
                </span>
              </div>
            </div>

            {/* Footer */}
            <div className="flex items-center justify-between border-t border-border pt-4">
              <span className="text-[11px] text-muted-foreground">
                Daily CRM Enterprise POS Billing System
              </span>
              <div className="flex items-center gap-2">
                <IconAction label="Print Receipt" icon={<Printer className="h-4 w-4" />} variant="outline"
                  onClick={() => {
                    window.print();
                    toast.success("Printing invoice receipt...");
                  }}
                  className="border-border hover:border-[#00aef0] text-foreground hover:text-[#00aef0] gap-1.5 rounded-xl text-xs h-10" />
                <Button
                  onClick={() => setShowInvoiceModal(false)}
                  className="bg-muted hover:bg-muted text-foreground font-bold rounded-xl text-xs h-10 px-5"
                >
                  Close
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Building2, Plus, RefreshCw, Search, Phone, Mail, X, Layers, Edit3, Trash2, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { IconAction } from "@/components/ui/icon-action";
import { BulkEntryDialog } from "@/components/ui/bulk-entry-dialog";
import { BulkActionBar, SelectAllCheckbox, SelectRowCheckbox } from "@/components/ui/bulk-action-bar";

export default function SuppliersPage() {
  const { activeWorkspace } = useWorkspace();
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");

  // Modal & Selection state
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingSupplier, setEditingSupplier] = useState<any | null>(null);
  const [bulkAddOpen, setBulkAddOpen] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);

  // Form state
  const [companyName, setCompanyName] = useState("");
  const [contactPerson, setContactPerson] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [gstin, setGstin] = useState("");
  const [address, setAddress] = useState("");
  const [outstandingBalance, setOutstandingBalance] = useState("0");

  const fetchSuppliers = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/commerce/suppliers?workspace_id=${activeWorkspace.id}`);
      const json = await res.json();
      if (res.ok && json.suppliers) {
        setSuppliers(json.suppliers);
      }
    } catch {
      toast.error("Failed to load suppliers");
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id]);

  useEffect(() => {
    fetchSuppliers();
  }, [fetchSuppliers]);

  const handleOpenAdd = () => {
    setEditingSupplier(null);
    setCompanyName("");
    setContactPerson("");
    setPhone("");
    setEmail("");
    setGstin("");
    setAddress("");
    setOutstandingBalance("0");
    setShowAddModal(true);
  };

  const handleOpenEdit = (supplier: any) => {
    setEditingSupplier(supplier);
    setCompanyName(supplier.company_name || "");
    setContactPerson(supplier.contact_person || "");
    setPhone(supplier.phone || "");
    setEmail(supplier.email || "");
    setGstin(supplier.gstin || "");
    setAddress(supplier.address || "");
    setOutstandingBalance(String(supplier.outstanding_balance || 0));
    setShowAddModal(true);
  };

  const handleSaveSupplier = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !companyName.trim()) {
      toast.error("Company Name is required");
      return;
    }

    setSaving(true);
    try {
      const isEdit = !!editingSupplier?.id;
      const url = "/api/commerce/suppliers";
      const method = isEdit ? "PUT" : "POST";
      const payload = {
        id: editingSupplier?.id,
        workspace_id: activeWorkspace.id,
        company_name: companyName.trim(),
        contact_person: contactPerson.trim() || undefined,
        phone: phone.trim() || undefined,
        email: email.trim() || undefined,
        gstin: gstin.trim() || undefined,
        address: address.trim() || undefined,
        outstanding_balance: Number(outstandingBalance) || 0,
      };

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || `Failed to ${isEdit ? "update" : "create"} supplier`);

      toast.success(isEdit ? "Supplier updated successfully!" : "Supplier added to Master Directory!");
      setShowAddModal(false);
      fetchSuppliers();
    } catch (err: any) {
      toast.error(err.message || "Failed to save supplier");
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteSupplier = async (id: string, name: string) => {
    if (!activeWorkspace?.id) return;
    if (!confirm(`Are you sure you want to delete supplier "${name}"?`)) return;

    setDeleting(true);
    try {
      const res = await fetch(`/api/commerce/suppliers?id=${id}&workspace_id=${activeWorkspace.id}`, {
        method: "DELETE",
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to delete supplier");

      toast.success("Supplier deleted successfully!");
      setSelectedIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
      fetchSuppliers();
    } catch (err: any) {
      toast.error(err.message || "Failed to delete supplier");
    } finally {
      setDeleting(false);
    }
  };

  const handleBulkDelete = async () => {
    if (!activeWorkspace?.id || selectedIds.size === 0) return;
    if (!confirm(`Are you sure you want to delete ${selectedIds.size} selected supplier(s)?`)) return;

    setDeleting(true);
    try {
      const res = await fetch("/api/commerce/suppliers", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          workspace_id: activeWorkspace.id,
          ids: Array.from(selectedIds),
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to delete selected suppliers");

      toast.success(`Deleted ${selectedIds.size} suppliers.`);
      setSelectedIds(new Set());
      fetchSuppliers();
    } catch (err: any) {
      toast.error(err.message || "Failed to delete selected suppliers");
    } finally {
      setDeleting(false);
    }
  };

  const handleBulkAddSuppliers = async (rows: Record<string, string>[]) => {
    if (!activeWorkspace?.id) return;
    try {
      for (const row of rows) {
        if (!row.company_name?.trim()) continue;
        await fetch("/api/commerce/suppliers", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            workspace_id: activeWorkspace.id,
            company_name: row.company_name.trim(),
            contact_person: row.contact_person?.trim() || undefined,
            phone: row.phone?.trim() || undefined,
            email: row.email?.trim() || undefined,
            gstin: row.gstin?.trim() || undefined,
            address: row.address?.trim() || undefined,
          }),
        });
      }
      toast.success(`Added ${rows.length} supplier${rows.length === 1 ? "" : "s"}.`);
      fetchSuppliers();
    } catch {
      toast.error("Failed to bulk add suppliers.");
    }
  };

  const filtered = suppliers.filter(
    (s) =>
      s.company_name?.toLowerCase().includes(query.toLowerCase()) ||
      s.contact_person?.toLowerCase().includes(query.toLowerCase()) ||
      s.phone?.includes(query) ||
      s.gstin?.toLowerCase().includes(query.toLowerCase())
  );

  const allFilteredSelected = filtered.length > 0 && filtered.every((s) => selectedIds.has(s.id));
  const someFilteredSelected = filtered.some((s) => selectedIds.has(s.id));

  const toggleSelectAll = () => {
    if (allFilteredSelected) {
      const next = new Set(selectedIds);
      filtered.forEach((s) => next.delete(s.id));
      setSelectedIds(next);
    } else {
      const next = new Set(selectedIds);
      filtered.forEach((s) => next.add(s.id));
      setSelectedIds(next);
    }
  };

  const toggleSelectRow = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) {
      next.delete(id);
    } else {
      next.add(id);
    }
    setSelectedIds(next);
  };

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground tracking-tight flex items-center gap-2.5">
            <Building2 className="h-6 w-6 text-[#00aef0]" />
            Supplier & Vendor Master Directory
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Master directory of wholesalers, manufacturers, GSTIN details, and stock suppliers.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <IconAction label="Refresh" icon={<RefreshCw className="h-4 w-4" />} onClick={fetchSuppliers} variant="outline" className="border-border text-foreground gap-1.5 rounded-xl h-11" />
          <IconAction label="Bulk Add" icon={<Layers className="h-4 w-4" />} onClick={() => setBulkAddOpen(true)} variant="outline" className="border-border text-foreground gap-1.5 rounded-xl h-11" />
          <IconAction label="Add New Supplier" icon={<Plus className="h-4 w-4" />} onClick={handleOpenAdd}
            className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20 gap-2 h-11" />
        </div>
      </div>

      {/* Search */}
      <div className="flex items-center gap-3 bg-card/80 p-3 rounded-2xl border border-border backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search by Company Name, Contact Person, Phone, or GSTIN..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border text-foreground rounded-xl focus:border-[#00aef0]"
          />
        </div>
      </div>

      {/* Table */}
      <div className="rounded-2xl border border-border bg-card/50 backdrop-blur-xl overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-foreground">
            <thead className="bg-background/80 text-xs font-semibold uppercase tracking-wider text-muted-foreground border-b border-border">
              <tr>
                <th className="py-3.5 px-4 w-10">
                  <SelectAllCheckbox
                    checked={allFilteredSelected}
                    indeterminate={someFilteredSelected && !allFilteredSelected}
                    onChange={toggleSelectAll}
                  />
                </th>
                <th className="py-3.5 px-4">Company Name</th>
                <th className="py-3.5 px-4 hidden md:table-cell">Contact Person</th>
                <th className="py-3.5 px-4">Phone &amp; Email</th>
                <th className="py-3.5 px-4 hidden sm:table-cell">GSTIN</th>
                <th className="py-3.5 px-4 hidden lg:table-cell">Address</th>
                <th className="py-3.5 px-4 text-right">Outstanding Balance</th>
                <th className="py-3.5 px-4 text-right w-24">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {loading ? (
                <tr>
                  <td colSpan={8} className="py-12 text-center text-muted-foreground text-sm">
                    Loading Suppliers...
                  </td>
                </tr>
              ) : filtered.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-12 text-center text-muted-foreground text-sm space-y-3">
                    <Building2 className="h-10 w-10 mx-auto text-muted-foreground mb-2" />
                    <p className="text-foreground font-semibold">No Suppliers Registered Yet</p>
                    <p className="text-xs text-muted-foreground max-w-sm mx-auto">
                      Add vendor details, GSTIN, contact numbers, and track supplier payables.
                    </p>
                    <IconAction label="Add New Supplier" icon={<Plus className="h-4 w-4" />} onClick={handleOpenAdd}
                      className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl gap-2 mt-2" />
                  </td>
                </tr>
              ) : (
                filtered.map((supplier) => {
                  const isSelected = selectedIds.has(supplier.id);
                  return (
                    <tr key={supplier.id} className={`hover:bg-muted/40 transition-colors ${isSelected ? "bg-muted/30" : ""}`}>
                      <td className="py-3.5 px-4">
                        <SelectRowCheckbox
                          checked={isSelected}
                          onToggle={() => toggleSelectRow(supplier.id)}
                          label={`Select ${supplier.company_name}`}
                        />
                      </td>
                      <td className="py-3.5 px-4 font-bold text-foreground">
                        {supplier.company_name}
                      </td>
                      <td className="py-3.5 px-4 text-xs text-foreground hidden md:table-cell">
                        {supplier.contact_person || "N/A"}
                      </td>
                      <td className="py-3.5 px-4 text-xs text-muted-foreground">
                        {supplier.phone && (
                          <div className="flex items-center gap-1 text-foreground">
                            <Phone className="h-3 w-3 text-[#00aef0]" /> {supplier.phone}
                          </div>
                        )}
                        {supplier.email && (
                          <div className="flex items-center gap-1 text-muted-foreground text-[11px]">
                            <Mail className="h-3 w-3 text-muted-foreground" /> {supplier.email}
                          </div>
                        )}
                      </td>
                      <td className="py-3.5 px-4 font-mono text-xs text-[#00aef0] hidden sm:table-cell">
                        {supplier.gstin || "URP"}
                      </td>
                      <td className="py-3.5 px-4 text-xs text-muted-foreground hidden lg:table-cell">
                        {supplier.address || "N/A"}
                      </td>
                      <td className="py-3.5 px-4 text-right font-extrabold text-foreground">
                        ₹{Number(supplier.outstanding_balance || 0).toFixed(2)}
                      </td>
                      <td className="py-3.5 px-4 text-right">
                        <div className="flex items-center justify-end gap-1">
                          <IconAction
                            label="Edit"
                            icon={<Edit3 className="h-4 w-4" />}
                            onClick={() => handleOpenEdit(supplier)}
                            variant="ghost"
                            className="h-8 w-8 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted"
                          />
                          <IconAction
                            label="Delete"
                            icon={<Trash2 className="h-4 w-4 text-destructive" />}
                            onClick={() => handleDeleteSupplier(supplier.id, supplier.company_name)}
                            variant="ghost"
                            className="h-8 w-8 rounded-lg hover:bg-destructive/10"
                          />
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Bulk Action Bar */}
      <BulkActionBar
        count={selectedIds.size}
        onClear={() => setSelectedIds(new Set())}
        noun="supplier"
        busy={deleting}
      >
        <Button
          variant="destructive"
          size="sm"
          onClick={handleBulkDelete}
          disabled={deleting}
          className="rounded-lg h-8 px-3 text-xs gap-1.5"
        >
          <Trash2 className="h-3.5 w-3.5" />
          Delete Selected ({selectedIds.size})
        </Button>
      </BulkActionBar>

      {/* Bulk Entry Dialog */}
      <BulkEntryDialog
        open={bulkAddOpen}
        onOpenChange={setBulkAddOpen}
        scope="suppliers"
        workspaceId={activeWorkspace?.id || ""}
        title="Bulk Add Suppliers & Vendors"
        description="Paste or type multiple supplier details at once. Enter one supplier per row."
        columns={[
          { key: "company_name", label: "Company Name *", required: true },
          { key: "contact_person", label: "Contact Person" },
          { key: "phone", label: "Phone Number" },
          { key: "email", label: "Email Address" },
          { key: "gstin", label: "GSTIN Number" },
          { key: "address", label: "Address" },
        ]}
        onSubmit={handleBulkAddSuppliers}
      />

      {/* Add / Edit Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto overflow-x-hidden [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
          <div className="bg-card border border-border rounded-3xl max-w-lg w-full p-6 space-y-4 shadow-2xl text-foreground overflow-x-hidden">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <Building2 className="h-5 w-5 text-[#00aef0]" />
                {editingSupplier ? "Edit Supplier / Vendor" : "Add New Supplier / Vendor"}
              </h2>
              <button onClick={() => setShowAddModal(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            <form onSubmit={handleSaveSupplier} className="space-y-3 text-xs">
              <div className="space-y-1">
                <Label className="text-xs text-foreground">Supplier / Company Name *</Label>
                <Input
                  required
                  type="text"
                  placeholder="e.g. Acme Wholesale Pvt Ltd"
                  value={companyName}
                  onChange={(e) => setCompanyName(e.target.value)}
                  className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Contact Person</Label>
                  <Input
                    type="text"
                    placeholder="e.g. Ramesh Kumar"
                    value={contactPerson}
                    onChange={(e) => setContactPerson(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Phone Number</Label>
                  <Input
                    type="text"
                    placeholder="e.g. 9876543210"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Email Address</Label>
                  <Input
                    type="email"
                    placeholder="e.g. vendor@acme.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">GSTIN Number</Label>
                  <Input
                    type="text"
                    placeholder="e.g. 27ABCDE1234F1Z5"
                    value={gstin}
                    onChange={(e) => setGstin(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs uppercase"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Office / Warehouse Address</Label>
                  <Input
                    type="text"
                    placeholder="e.g. Plot 42, Industrial Area, Mumbai"
                    value={address}
                    onChange={(e) => setAddress(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-foreground">Outstanding Balance (₹)</Label>
                  <Input
                    type="number"
                    step="0.01"
                    placeholder="0.00"
                    value={outstandingBalance}
                    onChange={(e) => setOutstandingBalance(e.target.value)}
                    className="bg-background border-border text-foreground rounded-xl h-10 text-xs font-mono"
                  />
                </div>
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border">
                <Button type="button" variant="outline" onClick={() => setShowAddModal(false)} className="border-border text-foreground rounded-xl h-10">
                  Cancel
                </Button>
                <Button type="submit" disabled={saving} className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl h-10 px-5">
                  {saving ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin mr-2" />
                      {editingSupplier ? "Updating..." : "Saving..."}
                    </>
                  ) : editingSupplier ? (
                    "Update Supplier"
                  ) : (
                    "Save Supplier"
                  )}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { BulkEntryDialog } from '@/components/ui/bulk-entry-dialog';
import { IconAction } from '@/components/ui/icon-action';
import { PageHeader } from '@/components/shared/page-header';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Plus, Layers, Search, Scale, Loader2, Edit3, Trash2, Sparkles } from 'lucide-react';
import { toast } from 'sonner';

const DEFAULT_UNITS = [
  { name: 'Pieces', code: 'PCS', precision: 0 },
  { name: 'Kilograms', code: 'KG', precision: 2 },
  { name: 'Grams', code: 'GM', precision: 2 },
  { name: 'Liters', code: 'LTR', precision: 2 },
  { name: 'Meters', code: 'MTR', precision: 2 },
  { name: 'Box (12 pcs)', code: 'BOX', precision: 0 },
  { name: 'Carton', code: 'CTN', precision: 0 },
  { name: 'Pack', code: 'PKT', precision: 0 },
];

export default function UnitsPage() {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [units, setUnits] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  
  // Modal states
  const [openModal, setOpenModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [bulkAddOpen, setBulkAddOpen] = useState(false);
  const [editingUnit, setEditingUnit] = useState<any | null>(null);

  // Form State
  const [name, setName] = useState('');
  const [code, setCode] = useState('');

  const fetchUnits = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const { data, error } = await supabase
        .from('units')
        .select('*')
        .eq('workspace_id', activeWorkspace.id)
        .order('name', { ascending: true });

      if (error || !data || data.length === 0) {
        // Fallback default list
        setUnits(DEFAULT_UNITS.map((u, idx) => ({ id: `unit_${idx}`, ...u })));
      } else {
        setUnits(data);
      }
    } catch {
      setUnits(DEFAULT_UNITS.map((u, idx) => ({ id: `unit_${idx}`, ...u })));
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id]);

  useEffect(() => {
    fetchUnits();
  }, [fetchUnits]);

  const handleSeedDefaults = async () => {
    if (!activeWorkspace?.id) return;
    setSaving(true);

    try {
      const rows = DEFAULT_UNITS.map(u => ({
        workspace_id: activeWorkspace.id,
        name: u.name,
        code: u.code,
      }));

      await supabase.from('units').upsert(rows, { onConflict: 'workspace_id,code' });
      toast.success('Default measurement units added!');
      fetchUnits();
    } catch (err: any) {
      toast.error(err.message || 'Failed to seed default units');
    } finally {
      setSaving(false);
    }
  };

  const handleOpenAdd = () => {
    setEditingUnit(null);
    setName('');
    setCode('');
    setOpenModal(true);
  };

  const handleOpenEdit = (unit: any) => {
    setEditingUnit(unit);
    setName(unit.name || '');
    setCode(unit.code || '');
    setOpenModal(true);
  };

  /** Insert every typed or pasted row in one statement. */
  const bulkAdd = async (rows: Record<string, string>[]) => {
    const { error } = await supabase.from('units').insert(
      rows.map((r) => ({ workspace_id: activeWorkspace!.id, name: r.name.trim(), code: r.code.trim().toUpperCase() }))
    );
    if (error) throw error;
    toast.success(`Added ${rows.length} unit${rows.length === 1 ? '' : 's'}.`);
    fetchUnits();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !name.trim() || !code.trim()) return;

    setSaving(true);
    try {
      if (editingUnit?.id && !editingUnit.id.startsWith('unit_')) {
        const { error } = await supabase
          .from('units')
          .update({ name: name.trim(), code: code.trim().toUpperCase() })
          .eq('id', editingUnit.id);

        if (error) throw error;
        toast.success('Unit updated successfully');
      } else {
        const { error } = await supabase
          .from('units')
          .insert({
            workspace_id: activeWorkspace.id,
            name: name.trim(),
            code: code.trim().toUpperCase()
          });

        if (error) throw error;
        toast.success('Unit created successfully');
      }

      setOpenModal(false);
      fetchUnits();
    } catch (err: any) {
      toast.error(err.message || 'Failed to save unit');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this unit?')) return;
    try {
      const { error } = await supabase.from('units').delete().eq('id', id);
      if (error) throw error;
      toast.success('Unit deleted');
      fetchUnits();
    } catch (err: any) {
      toast.error(err.message || 'Failed to delete unit');
    }
  };

  const filteredUnits = units.filter(u =>
    u.name?.toLowerCase().includes(search.toLowerCase()) ||
    u.code?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <PageHeader
        title="Units of Measurement"
        description="Manage product quantity units, short codes, and conversion metrics."
        action={
          <div className="flex items-center gap-2">
            <IconAction label="Seed Defaults" icon={<Sparkles className="size-4 text-amber-500" />} variant="outline" onClick={handleSeedDefaults} disabled={saving} className="border-border" />
            <IconAction label="Bulk add" icon={<Layers className="size-4 " />} variant="outline" onClick={() => setBulkAddOpen(true)} className="border-border" />
            <IconAction label="Add Unit" icon={<Plus className="size-4 " />} onClick={handleOpenAdd} className="bg-primary text-primary-foreground" />
          </div>
        }
      />

      <div className="flex items-center gap-2 max-w-sm">
        <div className="relative w-full">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input
            placeholder="Search units..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-8 bg-card border-border"
          />
        </div>
      </div>

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent">
              <TableHead className="text-muted-foreground">Unit Name</TableHead>
              <TableHead className="text-muted-foreground">Unit Code</TableHead>
              <TableHead className="text-muted-foreground w-24 text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-12">
                  <Loader2 className="size-6 animate-spin mx-auto text-primary" />
                  <p className="text-sm text-muted-foreground mt-2">Loading measurement units...</p>
                </TableCell>
              </TableRow>
            ) : filteredUnits.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-12">
                  <Scale className="size-8 mx-auto text-muted-foreground mb-2" />
                  <p className="text-sm text-muted-foreground">No measurement units found.</p>
                </TableCell>
              </TableRow>
            ) : (
              filteredUnits.map(unit => (
                <TableRow key={unit.id} className="border-border hover:bg-muted/50">
                  <TableCell className="font-medium text-foreground">{unit.name}</TableCell>
                  <TableCell className="text-muted-foreground font-mono text-xs uppercase">{unit.code}</TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-1">
                      <IconAction
                        label={`Edit ${unit.name}`}
                        icon={<Edit3 className="size-4" />}
                        onClick={() => handleOpenEdit(unit)}
                      />
                      <IconAction
                        label={`Delete ${unit.name}`}
                        icon={<Trash2 className="size-4" />}
                        onClick={() => handleDelete(unit.id)}
                        destructive
                      />
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={openModal} onOpenChange={setOpenModal}>
        <DialogContent className="sm:max-w-[480px] bg-card border-border rounded-xl p-6 shadow-2xl">
          <DialogHeader>
            <DialogTitle>{editingUnit ? 'Edit Unit' : 'Add Measurement Unit'}</DialogTitle>
            <DialogDescription>Define unit names and short codes (e.g. PCS, KG, BOX).</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleSubmit} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Unit Name <span className="text-red-500">*</span></Label>
              <Input
                placeholder="e.g. Pieces, Kilograms, Box"
                value={name}
                onChange={e => setName(e.target.value)}
                required
                className="bg-card border-border"
              />
            </div>

            <div className="space-y-2">
              <Label>Unit Code (Short Symbol) <span className="text-red-500">*</span></Label>
              <Input
                placeholder="e.g. PCS, KG, LTR, BOX"
                value={code}
                onChange={e => setCode(e.target.value)}
                required
                className="bg-card border-border uppercase font-mono"
              />
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setOpenModal(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null}
                {editingUnit ? 'Save Changes' : 'Create Unit'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <BulkEntryDialog
        open={bulkAddOpen}
        onOpenChange={setBulkAddOpen}
        title="Add several units"
        scope="units"
        workspaceId={activeWorkspace?.id}
        noun="unit"
        columns={[
          { key: 'name', label: 'Unit name', required: true, placeholder: 'e.g. Kilogram' },
          { key: 'code', label: 'Code', required: true, placeholder: 'e.g. KG' },
        ]}
        onSubmit={bulkAdd}
      />
    </div>
  );
}

