"use client";

import { useState, useEffect, useCallback } from "react";
import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { SignatoryModal } from "@/components/documents/signatory-modal";
import {
  UserCheck,
  Plus,
  Trash2,
  Edit3,
  ShieldCheck,
  Building,
  Loader2
} from "lucide-react";
import { IconAction } from "@/components/ui/icon-action";

export default function SignatoriesPage() {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  const [loading, setLoading] = useState(true);
  const [signatories, setSignatories] = useState<any[]>([]);
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedSignatory, setSelectedSignatory] = useState<any | null>(null);

  const fetchSignatories = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("company_signatories")
        .select("*")
        .eq("workspace_id", activeWorkspace.id)
        .order("created_at", { ascending: false });

      if (error) throw error;
      setSignatories(data || []);
    } catch (err: any) {
      toast.error(err.message || "Failed to load signatories.");
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, supabase]);

  useEffect(() => {
    fetchSignatories();
  }, [fetchSignatories]);

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to remove this signatory?")) return;
    try {
      const { error } = await supabase
        .from("company_signatories")
        .delete()
        .eq("id", id)
        .eq("workspace_id", activeWorkspace!.id);
      if (error) throw error;
      toast.success("Signatory removed.");
      fetchSignatories();
    } catch (err: any) {
      toast.error(err.message || "Failed to delete signatory.");
    }
  };

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto text-foreground">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-card/80 p-5 rounded-3xl border border-border shadow-xs">
        <div>
          <h1 className="text-xl font-bold text-foreground tracking-tight flex items-center gap-2.5">
            <UserCheck className="size-5 text-purple-500" />
            Corporate Signatories &amp; Stamps Vault
          </h1>
          <p className="text-xs text-muted-foreground mt-0.5">
            Manage authorized signatories (CEO, HR, Finance, Legal) with signatures and seal stamps.
          </p>
        </div>

        <IconAction label="Add New Signatory" icon={<Plus className="size-3.5" />} onClick={() => {
            setSelectedSignatory(null);
            setModalOpen(true);
          }}
          className="bg-primary text-primary-foreground text-xs h-9 font-semibold gap-1.5 shadow-xs" />
      </div>

      {/* Grid */}
      {loading ? (
        <div className="flex items-center justify-center p-12 text-muted-foreground text-xs">
          <Loader2 className="size-5 animate-spin mr-2" />
          Loading Signatories...
        </div>
      ) : signatories.length === 0 ? (
        <div className="text-center p-12 bg-card rounded-2xl border border-border space-y-3">
          <UserCheck className="size-10 text-muted-foreground mx-auto" />
          <h3 className="text-sm font-bold">No Authorized Signatories Configured</h3>
          <p className="text-xs text-muted-foreground max-w-md mx-auto">
            Add company signatories (e.g. HR Manager, CEO) to attach digital signatures and stamps to generated letters.
          </p>
          <IconAction label="Add Signatory" icon={<Plus className="size-3.5 " />} onClick={() => setModalOpen(true)}
            className="bg-primary text-primary-foreground text-xs h-8" />
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {signatories.map((sig) => (
            <div key={sig.id} className="bg-card border border-border p-5 rounded-2xl shadow-xs space-y-4 relative">
              <div className="flex items-start justify-between">
                <div>
                  <h3 className="font-bold text-sm text-foreground flex items-center gap-1.5">
                    {sig.name}
                    {sig.is_default && (
                      <Badge className="bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20 text-[10px]">
                        Default
                      </Badge>
                    )}
                  </h3>
                  <p className="text-xs text-muted-foreground">{sig.designation} ({sig.department || 'HR'})</p>
                </div>
              </div>

              {/* Previews */}
              <div className="grid grid-cols-2 gap-2 pt-2 border-t border-border/60 text-[11px]">
                <div className="bg-muted/40 p-2 rounded-xl text-center">
                  <span className="text-muted-foreground block text-[10px]">Signature</span>
                  {sig.signature_url ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={sig.signature_url} alt="Signature" className="h-8 mx-auto object-contain mt-1" />
                  ) : (
                    <span className="text-slate-400 italic">No image</span>
                  )}
                </div>

                <div className="bg-muted/40 p-2 rounded-xl text-center">
                  <span className="text-muted-foreground block text-[10px]">Seal Stamp</span>
                  {sig.stamp_url ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={sig.stamp_url} alt="Stamp" className="h-8 mx-auto object-contain mt-1" />
                  ) : (
                    <span className="text-slate-400 italic">No image</span>
                  )}
                </div>
              </div>

              <div className="flex justify-end gap-1 pt-2">
                <IconAction label="Edit" icon={<Edit3 className="size-3.5 " />} variant="ghost"
                  onClick={() => {
                    setSelectedSignatory(sig);
                    setModalOpen(true);
                  }}
                  className="h-7 px-2 text-xs" />
                <IconAction
                  label="Delete"
                  icon={<Trash2 className="size-3.5" />}
                  variant="ghost"
                  onClick={() => handleDelete(sig.id)}
                  className="h-7 px-2 text-xs text-rose-500 hover:bg-rose-500/10"
                />
              </div>
            </div>
          ))}
        </div>
      )}

      <SignatoryModal
        open={modalOpen}
        onOpenChange={setModalOpen}
        onSaved={fetchSignatories}
        initialData={selectedSignatory}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, use } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ChevronLeft, Loader2 } from 'lucide-react';
import { StatusBadge } from '@/components/shared/status-badge';
import { useWorkspace } from '@/hooks/use-workspace';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { useRouter } from 'next/navigation';
import { EmployeeProfileOverview } from '@/components/employees/employee-profile-overview';
import { EmployeeAssetsTab } from '@/components/employees/employee-assets-tab';
import { EmployeeDocumentsTab } from '@/components/employees/employee-documents-tab';
import { EmployeeAttendanceTab } from '@/components/employees/employee-attendance-tab';
import { EmployeeCompensationTab } from '@/components/employees/employee-compensation-tab';
import { EmployeeLettersTab } from '@/components/employees/employee-letters-tab';

export default function EmployeeProfilePage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const supabase = createClient();
  const router = useRouter();
  const { activeWorkspace, can } = useWorkspace();
  const canManagePeople = can('people_manage');

  const [employee, setEmployee] = useState<any | null>(null);
  const [departments, setDepartments] = useState<any[]>([]);
  const [designations, setDesignations] = useState<any[]>([]);
  const [managers, setManagers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchProfileData = useCallback(async () => {
    if (!id) return;
    setLoading(true);

    try {
      let empData: any = null;

      // Step 1: Query employee_profiles by workspace_member_id or id
      // employee_profiles is keyed by workspace_member_id and has no `id`
      // column; the previous `.or(...,id.eq.)` filter referenced a column
      // that does not exist, so this query always errored and the page
      // limped along on the fallback below.
      const { data: rawEmp } = await supabase
        .from('employee_profiles')
        .select('*')
        .eq('workspace_member_id', id)
        .maybeSingle();

      if (rawEmp) {
        empData = { ...rawEmp };
      } else {
        // Step 2: Try finding workspace_member directly by id or user_id
        const { data: member } = await supabase
          .from('workspace_members')
          .select('id, user_id, role, workspace_id')
          .or(`id.eq.${id},user_id.eq.${id}`)
          .maybeSingle();

        if (member) {
          const { data: empByMember } = await supabase
            .from('employee_profiles')
            .select('*')
            .eq('workspace_member_id', member.id)
            .maybeSingle();

          if (empByMember) {
            empData = { ...empByMember };
          } else {
            // Auto-fallback profile for active workspace member
            empData = {
              workspace_member_id: member.id,
              workspace_id: member.workspace_id || activeWorkspace?.id,
              status: 'ACTIVE',
              joining_date: new Date().toISOString().slice(0, 10),
              employment_type: 'FULL_TIME',
            };
          }
          empData.workspace_members = member;
        }
      }

      if (!empData) {
        setEmployee(null);
        setLoading(false);
        return;
      }

      // Step 3: Ensure workspace_members is populated
      if (!empData.workspace_members && empData.workspace_member_id) {
        const { data: member } = await supabase
          .from('workspace_members')
          .select('id, user_id, role, workspace_id')
          .eq('id', empData.workspace_member_id)
          .maybeSingle();
        empData.workspace_members = member || null;
      }

      // Step 4: Enrich workspace_members with profiles (full_name, email, avatar_url)
      if (empData?.workspace_members?.user_id) {
        const { data: prof } = await supabase
          .from('profiles')
          .select('user_id, full_name, email, avatar_url')
          .eq('user_id', empData.workspace_members.user_id)
          .maybeSingle();
        if (prof) {
          empData.workspace_members.profiles = prof;
        }
      }

      setEmployee(empData);

      // Step 5: Fetch reference data for departments, designations, managers
      const targetWsId = empData.workspace_id || activeWorkspace?.id;
      if (targetWsId) {
        const [deptRes, desigRes, rawMgrRes] = await Promise.all([
          supabase.from('departments').select('id, name').eq('workspace_id', targetWsId).order('name'),
          supabase.from('designations').select('id, title').eq('workspace_id', targetWsId).order('title'),
          supabase.from('employee_profiles').select(`workspace_member_id, workspace_id`).eq('workspace_id', targetWsId)
        ]);

        if (deptRes.data) setDepartments(deptRes.data);
        if (desigRes.data) setDesignations(desigRes.data);

        if (rawMgrRes.data && rawMgrRes.data.length > 0) {
          const mgrMemberIds = rawMgrRes.data.map((m: any) => m.workspace_member_id).filter(Boolean);
          const { data: mgrMembers } = await supabase
            .from('workspace_members')
            .select('id, user_id')
            .in('id', mgrMemberIds);
          
          const mgrUserIds = (mgrMembers || []).map((m: any) => m.user_id).filter(Boolean);
          const { data: mgrProfilesData } = await supabase
            .from('profiles')
            .select('user_id, full_name')
            .in('user_id', mgrUserIds);
          
          const mgrProfileMap = Object.fromEntries((mgrProfilesData || []).map((p: any) => [p.user_id, p]));
          const memberMap = Object.fromEntries((mgrMembers || []).map((m: any) => [m.id, m]));

          setManagers(rawMgrRes.data.map((m: any) => {
            const wm = memberMap[m.workspace_member_id];
            return {
              workspace_member_id: m.workspace_member_id,
              workspace_members: wm ? { ...wm, profiles: mgrProfileMap[wm.user_id] || null } : null
            };
          }));
        }
      }
    } catch (err: any) {
      console.error('Error fetching employee profile:', err);
      toast.error('Failed to load employee profile');
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id, id]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <Loader2 className="size-8 animate-spin text-primary" />
        <p className="text-sm text-muted-foreground mt-4">Loading profile...</p>
      </div>
    );
  }

  if (!employee) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <p className="text-sm text-muted-foreground mb-4">Employee not found.</p>
        <Button variant="outline" onClick={() => router.push('/employees')}>Back to Directory</Button>
      </div>
    );
  }

  const profile = Array.isArray(employee.workspace_members?.profiles) 
    ? employee.workspace_members?.profiles[0] 
    : employee.workspace_members?.profiles;
  const fullName = profile?.full_name?.trim() || profile?.email?.split('@')[0] || 'Employee Profile';

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-2 mb-2 text-sm text-muted-foreground hover:text-foreground transition-colors cursor-pointer w-fit" onClick={() => router.push('/employees')}>
        <ChevronLeft className="size-4" />
        Back to Directory
      </div>

      <div className="flex flex-col md:flex-row md:items-start justify-between gap-6 pb-6 border-b border-border">
        <div className="flex items-center gap-4">
          <Avatar className="size-16 border border-border">
            {profile?.avatar_url && <AvatarImage src={profile.avatar_url} />}
            <AvatarFallback className="bg-primary/10 text-primary text-xl font-medium">
              {fullName.charAt(0).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          <div className="flex flex-col">
            <h1 className="text-lg font-semibold tracking-tight text-foreground flex items-center gap-3">
              {fullName}
              <StatusBadge status={employee.status || 'ACTIVE'} />
            </h1>
            <p className="text-sm text-muted-foreground mt-1">{profile?.email}</p>
          </div>
        </div>
      </div>

      <Tabs defaultValue="overview" className="w-full">
        <TabsList className="bg-muted w-full justify-start overflow-x-auto h-auto p-1 rounded-lg">
          <TabsTrigger value="overview" className="py-2">Overview</TabsTrigger>
          <TabsTrigger value="compensation" className="py-2">Compensation</TabsTrigger>
          <TabsTrigger value="attendance" className="py-2">Attendance</TabsTrigger>
          <TabsTrigger value="letters" className="py-2">Letters</TabsTrigger>
          <TabsTrigger value="assets" className="py-2">Assets</TabsTrigger>
          <TabsTrigger value="documents" className="py-2">Documents</TabsTrigger>
        </TabsList>

        <div className="mt-6">
          <TabsContent value="overview" className="m-0 focus-visible:outline-none focus-visible:ring-0">
            <EmployeeProfileOverview 
              employee={employee} 
              departments={departments}
              designations={designations}
              managers={managers}
              canEdit={canManagePeople}
              onSaved={fetchProfileData}
            />
          </TabsContent>
          <TabsContent value="compensation" className="m-0 focus-visible:outline-none">
            {employee.workspace_member_id ? (
              <EmployeeCompensationTab
                workspaceMemberId={employee.workspace_member_id}
                canEdit={canManagePeople}
              />
            ) : (
              <p className="text-sm text-muted-foreground">
                Onboard this member as an employee before setting compensation.
              </p>
            )}
          </TabsContent>
          <TabsContent value="attendance" className="m-0 focus-visible:outline-none">
            {employee.workspace_member_id ? (
              <EmployeeAttendanceTab
                workspaceMemberId={employee.workspace_member_id}
                canEdit={canManagePeople}
              />
            ) : (
              <p className="text-sm text-muted-foreground">
                Onboard this member as an employee before setting attendance rules.
              </p>
            )}
          </TabsContent>
          <TabsContent value="letters" className="m-0 focus-visible:outline-none">
            {employee.workspace_member_id ? (
              <EmployeeLettersTab
                workspaceMemberId={employee.workspace_member_id}
                canEdit={canManagePeople}
                context={{
                  employee_name: fullName,
                  employee_code: employee.employee_code ?? null,
                  designation:
                    designations.find((d: any) => d.id === employee.designation_id)?.title ?? null,
                  department:
                    departments.find((d: any) => d.id === employee.department_id)?.name ?? null,
                  joining_date: employee.joining_date ?? null,
                  email: profile?.email ?? null,
                  salary: employee.ctc_annual ? String(employee.ctc_annual) : null,
                }}
              />
            ) : (
              <p className="text-sm text-muted-foreground">
                Onboard this member as an employee before issuing letters.
              </p>
            )}
          </TabsContent>
          <TabsContent value="assets" className="m-0 focus-visible:outline-none">
            <EmployeeAssetsTab employeeId={id} canEdit={canManagePeople} />
          </TabsContent>
          <TabsContent value="documents" className="m-0 focus-visible:outline-none">
            <EmployeeDocumentsTab employeeId={id} canEdit={canManagePeople} />
          </TabsContent>
        </div>
      </Tabs>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from '@/components/ui/dropdown-menu';
import { Search, MoreHorizontal, UserSquare, Loader2, Mail } from 'lucide-react';
import { PageHeader } from '@/components/shared/page-header';
import { StatusBadge } from '@/components/shared/status-badge';
import { useWorkspace } from '@/hooks/use-workspace';
import { useRowSelection } from '@/hooks/use-row-selection';
import { affectedCount } from '@/lib/supabase/affected-rows';
import {
  BulkActionBar,
  SelectAllCheckbox,
  SelectRowCheckbox,
} from '@/components/ui/bulk-action-bar';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { useRouter } from 'next/navigation';
import { OnboardEmployeeForm } from '@/components/employees/onboard-employee-form';
import { UserPlus } from 'lucide-react';
import { IconAction } from "@/components/ui/icon-action";

export default function EmployeesPage() {
  const supabase = createClient();
  const router = useRouter();
  const { activeWorkspace } = useWorkspace();

  const [employees, setEmployees] = useState<any[]>([]);
  const [bulkBusy, setBulkBusy] = useState(false);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showOnboard, setShowOnboard] = useState(false);

  const fetchEmployees = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      // employee_profiles has TWO foreign keys to workspace_members —
      // workspace_member_id (the employee) and manager_workspace_member_id
      // (their manager) — so the embed MUST name which one. Without the
      // hint PostgREST refuses it with "more than one relationship was
      // found", the whole select fails, and the fallback below drops
      // departments and designations: that is why those columns rendered
      // as "-" for every employee.
      // 1. Try querying employee_profiles with joined relations
      let { data: rawData, error } = await supabase
        .from('employee_profiles')
        .select(`
          *,
          departments ( name ),
          designations ( title ),
          workspace_members!workspace_member_id ( id, user_id, role )
        `)
        .eq('workspace_id', activeWorkspace.id);

      // Fallback query if relational join returned an error
      if (error || !rawData) {
        console.warn('Relational fetch for employee_profiles failed, running fallback:', error?.message);
        const { data: fbData, error: fbErr } = await supabase
          .from('employee_profiles')
          .select('*')
          .eq('workspace_id', activeWorkspace.id);

        if (fbErr) throw fbErr;
        rawData = fbData || [];

        // Manual join for workspace_members
        const memberIds = rawData.map(e => e.workspace_member_id).filter(Boolean);
        if (memberIds.length > 0) {
          const { data: membersData } = await supabase
            .from('workspace_members')
            .select('id, user_id, role')
            .in('id', memberIds);
          const memberMap = Object.fromEntries((membersData || []).map(m => [m.id, m]));
          rawData.forEach(e => {
            e.workspace_members = memberMap[e.workspace_member_id] || null;
          });
        }
      }

      // Enrich workspace_members with profile data
      let data: any[] = rawData || [];
      const userIds = data.map((e: any) => e.workspace_members?.user_id).filter(Boolean);
      if (userIds.length > 0) {
        const { data: profilesData } = await supabase
          .from('profiles')
          .select('user_id, full_name, email, avatar_url')
          .in('user_id', userIds);
        const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
        data = data.map((e: any) => ({
          ...e,
          workspace_members: e.workspace_members
            ? { ...e.workspace_members, profiles: profileMap[e.workspace_members.user_id] || null }
            : null,
        }));
      }

      setEmployees(data);
    } catch (err: any) {
      console.error('Failed to load employees:', err);
      toast.error('Failed to load employees');
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id]);

  useEffect(() => {
    fetchEmployees();
  }, [fetchEmployees]);

  const filteredEmployees = useMemo(() => {
    if (!search.trim()) return employees;
    const query = search.toLowerCase();
    return employees.filter((emp) => {
      const profile = Array.isArray(emp.workspace_members?.profiles)
        ? emp.workspace_members?.profiles[0]
        : emp.workspace_members?.profiles;
      return (
        emp.employee_code?.toLowerCase().includes(query) ||
        profile?.full_name?.toLowerCase().includes(query) ||
        profile?.email?.toLowerCase().includes(query)
      );
    });
  }, [employees, search]);

  const selection = useRowSelection(
    filteredEmployees,
    (e: { workspace_member_id: string }) => e.workspace_member_id
  );

  /** Set the status of every selected employee in one statement. */
  const bulkSetStatus = async (status: 'ACTIVE' | 'INACTIVE') => {
    const ids = selection.selectedIds;
    if (ids.length === 0) return;
    setBulkBusy(true);
    try {
      const result = await supabase
        .from('employee_profiles')
        .update({ status })
        .in('workspace_member_id', ids)
        .eq('workspace_id', activeWorkspace!.id)
        .select('workspace_member_id');
      const outcome = affectedCount(result, ids.length, 'employees');
      if (outcome.partial) toast.warning(outcome.message);
      else toast.success(outcome.message);
      selection.clear();
      fetchEmployees();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Failed to update employees');
    } finally {
      setBulkBusy(false);
    }
  };


  const viewEmployeeDetails = (employeeId: string) => {
    router.push(`/employees/${employeeId}`);
  };

  return (
    <div className="space-y-6">
      <PageHeader 
        title="Employee Directory" 
        description="View and manage all employees across the organization."
        action={
          <IconAction label="Onboard Employee" icon={<UserPlus className="size-4 " />} onClick={() => setShowOnboard(true)} className="bg-primary text-primary-foreground hover:bg-primary/90" />
        }
      />
      
      <OnboardEmployeeForm 
        open={showOnboard} 
        onOpenChange={setShowOnboard} 
        onSaved={fetchEmployees} 
      />

      <div className="flex flex-col sm:flex-row gap-2">
        <div className="relative w-full max-w-sm">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by name, email, or ID..."
            className="pl-8 bg-card border-border text-foreground placeholder:text-muted-foreground"
          />
        </div>
      </div>

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent">
              <TableHead className="w-8">
                <SelectAllCheckbox
                  checked={selection.allVisibleSelected}
                  indeterminate={selection.someVisibleSelected}
                  onChange={selection.toggleAllVisible}
                  label="Select all employees"
                />
              </TableHead>
              <TableHead className="text-muted-foreground">Employee</TableHead>
              <TableHead className="text-muted-foreground hidden sm:table-cell">ID</TableHead>
              <TableHead className="text-muted-foreground hidden md:table-cell">Department</TableHead>
              <TableHead className="text-muted-foreground hidden lg:table-cell">Designation</TableHead>
              <TableHead className="text-muted-foreground">Status</TableHead>
              <TableHead className="text-muted-foreground w-12" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={7} className="text-center py-12">
                  <div className="flex flex-col items-center gap-2">
                    <Loader2 className="size-6 animate-spin text-primary" />
                    <p className="text-sm text-muted-foreground">Loading employees...</p>
                  </div>
                </TableCell>
              </TableRow>
            ) : filteredEmployees.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={7} className="text-center py-12">
                  <div className="flex flex-col items-center gap-2">
                    <UserSquare className="size-8 text-muted-foreground" />
                    <p className="text-sm text-muted-foreground">
                      {search ? 'No employees match your search.' : 'No employees found.'}
                    </p>
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              filteredEmployees.map((emp) => {
                const profile = Array.isArray(emp.workspace_members?.profiles) 
                  ? emp.workspace_members?.profiles[0] 
                  : emp.workspace_members?.profiles;

                const fullName = profile?.full_name || 'Unknown User';
                const email = profile?.email || '';
                
                return (
                  <TableRow
                    key={emp.workspace_member_id}
                    data-selected={selection.isSelected(emp.workspace_member_id) || undefined}
                    className="border-border hover:bg-muted/50 cursor-pointer data-[selected]:bg-primary/5"
                    onClick={() => viewEmployeeDetails(emp.workspace_member_id)}
                  >
                    {/* The row navigates on click, so the checkbox cell must
                        swallow the event or ticking a box opens the profile. */}
                    <TableCell className="w-8" onClick={(e) => e.stopPropagation()}>
                      <SelectRowCheckbox
                        checked={selection.isSelected(emp.workspace_member_id)}
                        onToggle={(o) => selection.toggle(emp.workspace_member_id, o)}
                        label={`Select ${fullName}`}
                      />
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar className="size-9 border border-border">
                          {profile?.avatar_url && <AvatarImage src={profile.avatar_url} />}
                          <AvatarFallback className="bg-primary/10 text-primary font-medium">
                            {fullName.charAt(0).toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex flex-col min-w-0">
                          <span className="text-sm font-medium text-foreground truncate">
                            {fullName}
                          </span>
                          <span className="text-xs text-muted-foreground truncate flex items-center gap-1">
                            <Mail className="size-3" />
                            {email}
                          </span>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell className="text-muted-foreground font-mono text-xs hidden sm:table-cell">
                      {emp.employee_code || '-'}
                    </TableCell>
                    <TableCell className="text-muted-foreground text-sm hidden md:table-cell">
                      {emp.departments?.name || '-'}
                    </TableCell>
                    <TableCell className="text-muted-foreground text-sm hidden lg:table-cell">
                      {emp.designations?.title || '-'}
                    </TableCell>
                    <TableCell>
                      <StatusBadge status={emp.status || 'ACTIVE'} />
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger
                          render={
                            <Button
                              variant="ghost"
                              size="icon-sm"
                              className="text-muted-foreground hover:text-foreground"
                              onClick={(e) => e.stopPropagation()}
                            />
                          }
                        >
                          <MoreHorizontal className="size-4" />
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end" className="bg-popover border-border">
                          <DropdownMenuItem
                            onClick={(e) => {
                              e.stopPropagation();
                              viewEmployeeDetails(emp.workspace_member_id);
                            }}
                            className="text-popover-foreground focus:bg-muted focus:text-foreground cursor-pointer"
                          >
                            <UserSquare className="size-4 mr-2" />
                            View Profile
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      <BulkActionBar
        count={selection.selectedCount}
        hiddenCount={selection.hiddenSelectedCount}
        onClear={selection.clear}
        busy={bulkBusy}
        noun="employee"
      >
        <Button size="sm" variant="outline" onClick={() => bulkSetStatus('ACTIVE')} disabled={bulkBusy} className="h-7 text-xs">
          Mark active
        </Button>
        <Button size="sm" variant="outline" onClick={() => bulkSetStatus('INACTIVE')} disabled={bulkBusy} className="h-7 text-xs">
          Mark inactive
        </Button>
      </BulkActionBar>
    </div>
  );
}

'use client';

import * as React from 'react';
import { useRouter } from 'next/navigation';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  ArrowLeft,
  Plus,
  Trash2,
  Copy,
  Check,
  ChevronUp,
  ChevronDown,
  ExternalLink,
  Loader2,
  Settings2,
  Database,
  FileText,
} from 'lucide-react';
import type {
  CustomForm,
  CustomFormField,
  FormFieldType,
  FormMappingType,
} from '@/types';
import { IconAction } from "@/components/ui/icon-action";

interface CustomFieldDef {
  id: string;
  field_name: string;
  field_type: string;
}

interface PipelineStageDef {
  id: string;
  pipeline_id: string;
  name: string;
}

interface PipelineDef {
  id: string;
  name: string;
  pipeline_stages?: PipelineStageDef[];
}

export default function FormBuilderPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const router = useRouter();
  const supabase = createClient();
  const { id: formId } = React.use(params);

  // Data State
  const [form, setForm] = React.useState<CustomForm | null>(null);
  const [fields, setFields] = React.useState<Partial<CustomFormField>[]>([]);
  const [submissions, setSubmissions] = React.useState<any[]>([]);
  const [pipelines, setPipelines] = React.useState<PipelineDef[]>([]);
  const [customFields, setCustomFields] = React.useState<CustomFieldDef[]>([]);

  // Loading States
  const [loading, setLoading] = React.useState(true);
  const [savingFields, setSavingFields] = React.useState(false);
  const [savingIntegrations, setSavingIntegrations] = React.useState(false);

  // Navigation / Tabs
  const [activeTab, setActiveTab] = React.useState('builder');

  // Editing State
  const [formTitle, setFormTitle] = React.useState('');
  const [formDesc, setFormDesc] = React.useState('');
  const [selectedFieldId, setSelectedFieldId] = React.useState<string | null>(null);
  const [deletedFieldIds, setDeletedFieldIds] = React.useState<string[]>([]);

  // Integration State
  const [createDealOnSubmit, setCreateDealOnSubmit] = React.useState(false);
  const [selectedPipelineId, setSelectedPipelineId] = React.useState<string>('');
  const [selectedStageId, setSelectedStageId] = React.useState<string>('');

  // UI state
  const [copied, setCopied] = React.useState(false);

  // Fetch all page data
  const fetchData = React.useCallback(async () => {
    setLoading(true);
    try {
      // 1. Fetch Form
      const { data: formData, error: formErr } = await supabase
        .from('custom_forms')
        .select('*')
        .eq('id', formId)
        .maybeSingle();

      if (formErr) throw formErr;
      if (!formData) {
        toast.error('Form not found');
        router.push('/forms');
        return;
      }

      setForm(formData);
      setFormTitle(formData.title);
      setFormDesc(formData.description || '');
      setCreateDealOnSubmit(!!(formData.pipeline_id && formData.stage_id));
      setSelectedPipelineId(formData.pipeline_id || '');
      setSelectedStageId(formData.stage_id || '');

      // 2. Fetch Fields
      const { data: fieldsData, error: fieldsErr } = await supabase
        .from('custom_form_fields')
        .select('*')
        .eq('form_id', formId)
        .order('position', { ascending: true });

      if (fieldsErr) throw fieldsErr;
      setFields(fieldsData || []);

      // 3. Fetch Pipelines with Stages
      const { data: pipelinesData, error: pipelinesErr } = await supabase
        .from('pipelines')
        .select('*, pipeline_stages(*)');

      if (pipelinesErr) throw pipelinesErr;
      setPipelines(pipelinesData || []);

      // 4. Fetch Custom Field definitions
      const { data: customFieldsData, error: cfErr } = await supabase
        .from('custom_fields')
        .select('id, field_name, field_type')
        .order('field_name');

      if (cfErr) throw cfErr;
      setCustomFields(customFieldsData || []);

      // 5. Fetch Submissions
      const { data: subsData, error: subsErr } = await supabase
        .from('custom_form_submissions')
        .select(`
          id,
          created_at,
          submitted_values,
          contacts (id, name, phone, email),
          deals (id, title, value)
        `)
        .eq('form_id', formId)
        .order('created_at', { ascending: false });

      if (subsErr) throw subsErr;
      setSubmissions(subsData || []);

    } catch (err: any) {
      toast.error(err.message || 'Error fetching form builder data');
    } finally {
      setLoading(false);
    }
  }, [formId, supabase, router]);

  React.useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Selected Field ref
  const selectedField = fields.find((f) => f.id === selectedFieldId);

  // Add field helper
  const addField = (type: FormFieldType) => {
    const tempId = `temp-${Date.now()}`;
    const newField: Partial<CustomFormField> = {
      id: tempId,
      form_id: formId,
      label: `New ${type.charAt(0).toUpperCase() + type.slice(1)} Field`,
      field_type: type,
      is_required: false,
      placeholder: '',
      mapping_type: 'none',
      options: type === 'select' ? ['Option 1', 'Option 2'] : undefined,
      position: fields.length,
    };

    setFields([...fields, newField]);
    setSelectedFieldId(tempId);
  };

  // Delete field helper
  const removeField = (id: string) => {
    if (!id.startsWith('temp-')) {
      setDeletedFieldIds([...deletedFieldIds, id]);
    }
    setFields(fields.filter((f) => f.id !== id));
    if (selectedFieldId === id) {
      setSelectedFieldId(null);
    }
  };

  // Reordering helpers
  const moveField = (index: number, direction: 'up' | 'down') => {
    if (direction === 'up' && index === 0) return;
    if (direction === 'down' && index === fields.length - 1) return;

    const newIndex = direction === 'up' ? index - 1 : index + 1;
    const updated = [...fields];
    // Swap positions
    const temp = updated[index];
    updated[index] = updated[newIndex];
    updated[newIndex] = temp;

    setFields(updated);
  };

  // Field change updates
  const updateSelectedField = (updates: Partial<CustomFormField>) => {
    if (!selectedFieldId) return;
    setFields(
      fields.map((f) => (f.id === selectedFieldId ? { ...f, ...updates } : f))
    );
  };

  // Batch Save Form & Fields
  const saveFormAndFields = async () => {
    if (!formTitle.trim()) {
      toast.error('Form title is required');
      return;
    }

    setSavingFields(true);
    try {
      // 1. Update form metadata
      const { error: formErr } = await supabase
        .from('custom_forms')
        .update({
          title: formTitle.trim(),
          description: formDesc.trim() || null,
          updated_at: new Date().toISOString(),
        })
        .eq('id', formId);

      if (formErr) throw formErr;

      // 2. Delete removed fields
      if (deletedFieldIds.length > 0) {
        const { error: delErr } = await supabase
          .from('custom_form_fields')
          .delete()
          .in('id', deletedFieldIds);

        if (delErr) throw delErr;
        setDeletedFieldIds([]);
      }

      // 3. Upsert current fields
      const existingFieldsPayload: any[] = [];
      const newFieldsPayload: any[] = [];

      fields.forEach((f, index) => {
        const payload: any = {
          form_id: formId,
          label: f.label?.trim() || 'Field Label',
          field_type: f.field_type,
          placeholder: f.placeholder?.trim() || null,
          is_required: !!f.is_required,
          options: f.options || null,
          mapping_type: f.mapping_type || 'none',
          mapping_key: f.mapping_key || null,
          position: index,
        };

        if (f.id && !f.id.startsWith('temp-')) {
          payload.id = f.id;
          existingFieldsPayload.push(payload);
        } else {
          newFieldsPayload.push(payload);
        }
      });

      let savedExisting: any[] = [];
      let savedNew: any[] = [];

      if (existingFieldsPayload.length > 0) {
        const { data: upserted, error: fieldsErr } = await supabase
          .from('custom_form_fields')
          .upsert(existingFieldsPayload)
          .select();

        if (fieldsErr) throw fieldsErr;
        savedExisting = upserted || [];
      }

      if (newFieldsPayload.length > 0) {
        const { data: inserted, error: fieldsErr } = await supabase
          .from('custom_form_fields')
          .insert(newFieldsPayload)
          .select();

        if (fieldsErr) throw fieldsErr;
        savedNew = inserted || [];
      }

      const savedFields = [...savedExisting, ...savedNew].sort((a, b) => a.position - b.position);

      setFields(savedFields);
      // Reset selected field to the DB ID if it was temporary
      if (selectedFieldId && selectedFieldId.startsWith('temp-')) {
        const tempIndex = fields.findIndex((f) => f.id === selectedFieldId);
        if (tempIndex !== -1 && savedFields[tempIndex]) {
          setSelectedFieldId(savedFields[tempIndex].id);
        }
      }

      toast.success('Form changes saved successfully');
      setForm((prev: any) => ({ ...prev, title: formTitle.trim(), description: formDesc.trim() }));
    } catch (err: any) {
      toast.error(err.message || 'Failed to save form fields');
    } finally {
      setSavingFields(false);
    }
  };

  // Save integration deal rules
  const saveIntegrations = async () => {
    setSavingIntegrations(true);
    try {
      const pipelineId = createDealOnSubmit && selectedPipelineId ? selectedPipelineId : null;
      const stageId = createDealOnSubmit && selectedStageId ? selectedStageId : null;

      const { error } = await supabase
        .from('custom_forms')
        .update({
          pipeline_id: pipelineId,
          stage_id: stageId,
          updated_at: new Date().toISOString(),
        })
        .eq('id', formId);

      if (error) throw error;

      toast.success('Integration settings saved successfully');
      setForm((prev: any) => ({ ...prev, pipeline_id: pipelineId, stage_id: stageId }));
    } catch (err: any) {
      toast.error(err.message || 'Failed to save integrations');
    } finally {
      setSavingIntegrations(false);
    }
  };

  const copyShareLink = async () => {
    const origin = typeof window !== 'undefined' ? window.location.origin : '';
    const shareLink = `${origin}/forms/shared/${formId}`;
    try {
      await navigator.clipboard.writeText(shareLink);
      setCopied(true);
      toast.success('Public form link copied');
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('Failed to copy link');
    }
  };

  // Active stages list based on pipeline selection
  const activeStages =
    pipelines.find((p) => p.id === selectedPipelineId)?.pipeline_stages || [];

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-40 gap-3">
        <Loader2 className="size-8 animate-spin text-primary" />
        <p className="text-sm text-muted-foreground">Loading form builder...</p>
      </div>
    );
  }

  if (!form) return null;

  return (
    <div className="space-y-6">
      {/* Header Panel */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-border pb-5">
        <div className="flex items-center gap-3">
          <IconAction
            label="Back"
            icon={<ArrowLeft className="size-5" />}
            variant="ghost"
            onClick={() => router.push('/forms')}
            className="text-muted-foreground hover:text-foreground"
          />
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-xl font-bold text-foreground line-clamp-1">
                {form.title}
              </h1>
              <span
                className={`px-2 py-0.5 text-[10px] font-semibold rounded-full ${
                  form.is_active
                    ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
                    : 'bg-muted text-muted-foreground border border-border'
                }`}
              >
                {form.is_active ? 'Active' : 'Inactive'}
              </span>
            </div>
            <p className="text-xs text-muted-foreground mt-0.5">Form ID: {form.id}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <IconAction label="Copy Public Link" icon={copied ? <Check className="size-4 text-emerald-400" /> : <Copy className="size-4 " />} variant="outline"
            onClick={copyShareLink}
            className="border-border hover:bg-muted text-foreground" />

          <Button
            variant="ghost"
            onClick={() => {
              const origin = typeof window !== 'undefined' ? window.location.origin : '';
              window.open(`${origin}/forms/shared/${form.id}`, '_blank');
            }}
            className="text-foreground hover:text-foreground"
          >
            <ExternalLink className="size-4 mr-1.5" />
            View Form
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
        <TabsList className="bg-card border border-border p-1">
          <TabsTrigger value="builder" className="data-[state=active]:bg-primary data-[state=active]:text-primary-foreground text-muted-foreground">
            Form Builder
          </TabsTrigger>
          <TabsTrigger value="integrations" className="data-[state=active]:bg-primary data-[state=active]:text-primary-foreground text-muted-foreground">
            Pipelines Integration
          </TabsTrigger>
          <TabsTrigger value="responses" className="data-[state=active]:bg-primary data-[state=active]:text-primary-foreground text-muted-foreground">
            Responses ({submissions.length})
          </TabsTrigger>
        </TabsList>

        {/* Tab 1: Builder */}
        <TabsContent value="builder" className="focus-visible:outline-none">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
            {/* Left Canvas Panel */}
            <div className="lg:col-span-2 space-y-4">
              {/* Form Metadata */}
              <Card className="bg-card/60 border-border text-foreground">
                <CardHeader className="pb-3">
                  <CardTitle className="text-sm font-semibold text-foreground">Form Details</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-1.5">
                    <Label htmlFor="form-meta-title" className="text-muted-foreground">Form Title</Label>
                    <Input
                      id="form-meta-title"
                      value={formTitle}
                      onChange={(e) => setFormTitle(e.target.value)}
                      placeholder="e.g. Lead Contact Sheet"
                      className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label htmlFor="form-meta-desc" className="text-muted-foreground">Description / Instructions</Label>
                    <Textarea
                      id="form-meta-desc"
                      value={formDesc}
                      onChange={(e) => setFormDesc(e.target.value)}
                      placeholder="Enter the form description or welcome message shown to leads..."
                      className="bg-muted border-border text-foreground placeholder:text-muted-foreground min-h-[70px]"
                    />
                  </div>
                </CardContent>
              </Card>

              {/* Dynamic Field Canvas List */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-semibold text-foreground">Form Fields Structure</h3>
                  <span className="text-xs text-muted-foreground">{fields.length} fields configured</span>
                </div>

                {fields.length === 0 ? (
                  <div className="rounded-lg border border-dashed border-border p-8 text-center bg-card/20">
                    <p className="text-sm text-muted-foreground italic">No fields configured. Click below to add your first question.</p>
                  </div>
                ) : (
                  <div className="space-y-2.5">
                    {fields.map((field, idx) => {
                      const isSelected = field.id === selectedFieldId;
                      let mappingBadge = 'No CRM Sync';
                      if (field.field_type === 'file') {
                        mappingBadge = 'Auto Deal File Sync';
                      } else if (field.mapping_type === 'contact_field') {
                        mappingBadge = `Contact ➔ ${field.mapping_key}`;
                      } else if (field.mapping_type === 'contact_custom_field') {
                        const matchedCf = customFields.find((cf) => cf.id === field.mapping_key);
                        mappingBadge = `Custom Field ➔ ${matchedCf?.field_name || 'unknown'}`;
                      } else if (field.mapping_type === 'deal_field') {
                        mappingBadge = `Deal ➔ ${field.mapping_key}`;
                      }

                      return (
                        <div
                          key={field.id}
                          onClick={() => setSelectedFieldId(field.id || null)}
                          className={`group flex items-center justify-between border rounded-lg p-3.5 bg-card/40 hover:bg-card/70 transition-all cursor-pointer ${
                            isSelected
                              ? 'border-primary bg-card/80 ring-1 ring-primary/20'
                              : 'border-border/80'
                          }`}
                        >
                          <div className="flex items-center gap-3 min-w-0 flex-1">
                            {/* Position Ordering Arrows */}
                            <div className="flex flex-col gap-0.5 shrink-0 opacity-40 group-hover:opacity-100 transition-opacity">
                              <button
                                type="button"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  moveField(idx, 'up');
                                }}
                                disabled={idx === 0}
                                className="text-muted-foreground hover:text-foreground disabled:text-foreground"
                              >
                                <ChevronUp className="size-4" />
                              </button>
                              <button
                                type="button"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  moveField(idx, 'down');
                                }}
                                disabled={idx === fields.length - 1}
                                className="text-muted-foreground hover:text-foreground disabled:text-foreground"
                              >
                                <ChevronDown className="size-4" />
                              </button>
                            </div>

                            <div className="min-w-0">
                              <div className="flex items-center gap-2 flex-wrap">
                                <span className="font-medium text-sm text-foreground">
                                  {field.label || <span className="italic text-muted-foreground">Untitled Field</span>}
                                </span>
                                {field.is_required && (
                                  <span className="text-xs text-red-400 font-semibold">* Required</span>
                                )}
                              </div>
                              <div className="flex items-center gap-2 mt-1 flex-wrap">
                                <span className="text-[10px] px-1.5 py-0.5 font-semibold bg-muted rounded-none text-foreground uppercase">
                                  {field.field_type}
                                </span>
                                <span className="text-[10px] px-1.5 py-0.5 font-semibold bg-muted rounded-none text-muted-foreground flex items-center gap-1">
                                  <Database className="size-2.5" />
                                  {mappingBadge}
                                </span>
                              </div>
                            </div>
                          </div>

                          <IconAction
                            label="Delete"
                            icon={<Trash2 className="size-4" />}
                            variant="ghost"
                            onClick={(e) => {
                              e.stopPropagation();
                              removeField(field.id!);
                            }}
                            className="text-muted-foreground hover:text-red-400 hover:bg-red-500/10 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity"
                          />
                        </div>
                      );
                    })}
                  </div>
                )}

                {/* Add Fields Quick Actions */}
                <div className="border border-border/80 rounded-lg p-4 bg-background/40">
                  <span className="text-xs text-muted-foreground block mb-2.5 font-semibold uppercase">Add Form Element</span>
                  <div className="flex flex-wrap gap-2">
                    {[
                      { type: 'text', label: 'Single Line Text' },
                      { type: 'textarea', label: 'Paragraph Area' },
                      { type: 'email', label: 'Email Field' },
                      { type: 'phone', label: 'Phone Number' },
                      { type: 'number', label: 'Number Input' },
                      { type: 'select', label: 'Select Dropdown' },
                      { type: 'checkbox', label: 'Checkbox' },
                      { type: 'file', label: 'File/Document Upload' },
                    ].map((item) => (
                      <Button
                        key={item.type}
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => addField(item.type as FormFieldType)}
                        className="bg-card border-border hover:bg-muted text-xs text-foreground"
                      >
                        <Plus className="size-3.5 mr-1" />
                        {item.label}
                      </Button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Right Settings Configuration Panel */}
            <div className="space-y-4">
              <Card className="bg-card border-border text-foreground sticky top-4">
                <CardHeader>
                  <CardTitle className="text-sm font-semibold text-foreground flex items-center gap-2">
                    <Settings2 className="size-4 text-primary" />
                    Field Mapping Settings
                  </CardTitle>
                  <CardDescription className="text-muted-foreground text-xs">
                    Configure validation and map form questions directly to CRM fields.
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  {!selectedField ? (
                    <div className="text-center py-10">
                      <p className="text-xs text-muted-foreground italic">Select a field on the canvas to edit its details and mapping settings.</p>
                    </div>
                  ) : (
                    <>
                      {/* Label */}
                      <div className="space-y-1.5">
                        <Label htmlFor="field-label" className="text-muted-foreground text-xs">Field Label</Label>
                        <Input
                          id="field-label"
                          value={selectedField.label || ''}
                          onChange={(e) => updateSelectedField({ label: e.target.value })}
                          className="bg-muted border-border text-foreground placeholder:text-muted-foreground text-sm"
                        />
                      </div>

                      {/* Placeholder */}
                      {selectedField.field_type !== 'checkbox' && selectedField.field_type !== 'file' && (
                        <div className="space-y-1.5">
                          <Label htmlFor="field-placeholder" className="text-muted-foreground text-xs">Placeholder Text</Label>
                          <Input
                            id="field-placeholder"
                            value={selectedField.placeholder || ''}
                            onChange={(e) => updateSelectedField({ placeholder: e.target.value })}
                            className="bg-muted border-border text-foreground placeholder:text-muted-foreground text-sm"
                          />
                        </div>
                      )}

                      {/* Select Options */}
                      {selectedField.field_type === 'select' && (
                        <div className="space-y-1.5">
                          <Label htmlFor="field-options" className="text-muted-foreground text-xs">Dropdown Options</Label>
                          <Input
                            id="field-options"
                            value={selectedField.options ? selectedField.options.join(', ') : ''}
                            onChange={(e) =>
                              updateSelectedField({
                                options: e.target.value
                                  .split(',')
                                  .map((opt) => opt.trim())
                                  .filter(Boolean),
                              })
                            }
                            placeholder="Option A, Option B, Option C"
                            className="bg-muted border-border text-foreground placeholder:text-muted-foreground text-sm"
                          />
                          <p className="text-[10px] text-muted-foreground italic">Separate options with commas.</p>
                        </div>
                      )}

                      {/* Required Toggle */}
                      <div className="flex items-center justify-between border-y border-border py-3 mt-2">
                        <Label htmlFor="field-req" className="text-foreground text-xs font-semibold uppercase">Is Field Required?</Label>
                        <Switch
                          id="field-req"
                          checked={!!selectedField.is_required}
                          onCheckedChange={(checked) => updateSelectedField({ is_required: checked })}
                          className="data-checked:bg-primary data-unchecked:bg-muted"
                        />
                      </div>

                      {/* CRM Mapping Type */}
                      {selectedField.field_type === 'file' ? (
                        <div className="rounded-md bg-background/40 border border-border p-3 mt-2 space-y-1">
                          <p className="text-xs text-primary font-medium">Auto Deal File Sync</p>
                          <p className="text-[10px] text-muted-foreground leading-normal">
                            Uploaded documents are automatically saved to your CRM file vault and linked to the generated pipeline deal.
                          </p>
                        </div>
                      ) : (
                        <div className="space-y-1.5">
                          <Label htmlFor="mapping-type" className="text-muted-foreground text-xs">Map response values to</Label>
                          <Select
                            value={selectedField.mapping_type || 'none'}
                            onValueChange={(val) =>
                              updateSelectedField({
                                mapping_type: (val || 'none') as FormMappingType,
                                mapping_key: undefined,
                              })
                            }
                          >
                            <SelectTrigger className="bg-muted border-border text-foreground text-xs">
                              <SelectValue placeholder="No mapping" />
                            </SelectTrigger>
                            <SelectContent className="bg-muted border-border text-foreground text-xs">
                              <SelectItem value="none">Do not map (Save raw answer only)</SelectItem>
                              <SelectItem value="contact_field">Contact (Standard Attribute)</SelectItem>
                              <SelectItem value="contact_custom_field">Contact (Custom Field)</SelectItem>
                              <SelectItem value="deal_field">Pipeline Deal Property</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      )}

                      {/* CRM Mapping Key */}
                      {selectedField.field_type !== 'file' && selectedField.mapping_type === 'contact_field' && (
                        <div className="space-y-1.5">
                          <Label htmlFor="mapping-key-contact" className="text-muted-foreground text-xs">Select Contact Field</Label>
                          <Select
                            value={selectedField.mapping_key || ''}
                            onValueChange={(val) => updateSelectedField({ mapping_key: val || undefined })}
                          >
                            <SelectTrigger className="bg-muted border-border text-foreground text-xs">
                              <SelectValue placeholder="Choose attribute" />
                            </SelectTrigger>
                            <SelectContent className="bg-muted border-border text-foreground text-xs">
                              <SelectItem value="name">Full Name</SelectItem>
                              <SelectItem value="phone">Phone Number (For Deduplication)</SelectItem>
                              <SelectItem value="email">Email Address</SelectItem>
                              <SelectItem value="company">Company Name</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      )}

                      {selectedField.field_type !== 'file' && selectedField.mapping_type === 'contact_custom_field' && (
                        <div className="space-y-1.5">
                          <Label htmlFor="mapping-key-custom" className="text-muted-foreground text-xs">Select Custom Field</Label>
                          {customFields.length === 0 ? (
                            <p className="text-[10px] text-muted-foreground italic">No custom fields created in your CRM contacts.</p>
                          ) : (
                            <Select
                              key={`cf-${selectedField.mapping_key}-${customFields.length}`}
                              value={selectedField.mapping_key || ''}
                              onValueChange={(val) => updateSelectedField({ mapping_key: val || undefined })}
                            >
                              <SelectTrigger className="bg-muted border-border text-foreground text-xs">
                                <SelectValue placeholder="Choose custom field" />
                              </SelectTrigger>
                              <SelectContent className="bg-muted border-border text-foreground text-xs">
                                {customFields.map((cf) => (
                                  <SelectItem key={cf.id} value={cf.id}>
                                    {cf.field_name} ({cf.field_type})
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          )}
                        </div>
                      )}

                      {selectedField.field_type !== 'file' && selectedField.mapping_type === 'deal_field' && (
                        <div className="space-y-1.5">
                          <Label htmlFor="mapping-key-deal" className="text-muted-foreground text-xs">Select Deal Field</Label>
                          <Select
                            value={selectedField.mapping_key || ''}
                            onValueChange={(val) => updateSelectedField({ mapping_key: val || undefined })}
                          >
                            <SelectTrigger className="bg-muted border-border text-foreground text-xs">
                              <SelectValue placeholder="Choose deal attribute" />
                            </SelectTrigger>
                            <SelectContent className="bg-muted border-border text-foreground text-xs">
                              <SelectItem value="title">Deal Title</SelectItem>
                              <SelectItem value="value">Deal Value (Financial)</SelectItem>
                              <SelectItem value="notes">Deal Description / Notes</SelectItem>
                              <SelectItem value="expected_close_date">Expected Close Date</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      )}
                    </>
                  )}
                </CardContent>
                {selectedField && (
                  <CardFooter className="border-t border-border pt-3 flex justify-between">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setSelectedFieldId(null)}
                      className="text-muted-foreground hover:text-foreground"
                    >
                      Deselect
                    </Button>
                    <IconAction label="Remove Field" icon={<Trash2 className="size-3.5 " />} variant="destructive"
                      onClick={() => removeField(selectedFieldId!)}
                      className="bg-red-950/20 border border-red-500/30 text-red-400 hover:bg-red-500 hover:text-foreground text-xs" />
                  </CardFooter>
                )}
              </Card>
            </div>
          </div>

          {/* Floating Save button */}
          <div className="flex justify-end mt-6">
            <IconAction label="Save Form & Canvas" icon={<Loader2 className="size-4 animate-spin " />} onClick={saveFormAndFields}
              disabled={savingFields}
              className="bg-primary hover:bg-primary-hover text-primary-foreground" />
          </div>
        </TabsContent>

        {/* Tab 2: Integrations */}
        <TabsContent value="integrations" className="focus-visible:outline-none">
          <Card className="bg-card border-border text-foreground max-w-xl">
            <CardHeader>
              <CardTitle className="text-foreground">Pipeline Automation Settings</CardTitle>
              <CardDescription className="text-muted-foreground text-sm">
                Automatically generate deals for incoming form responses and route them to specific pipelines and stages.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Toggle automation */}
              <div className="flex items-center justify-between border-b border-border pb-4">
                <div>
                  <Label htmlFor="auto-deal" className="text-foreground font-medium">Create a Pipeline Deal</Label>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Generate an open deal linked to the contact card upon form submission.
                  </p>
                </div>
                <Switch
                  id="auto-deal"
                  checked={createDealOnSubmit}
                  onCheckedChange={setCreateDealOnSubmit}
                  className="data-checked:bg-primary data-unchecked:bg-muted"
                />
              </div>

              {createDealOnSubmit && (
                <div className="space-y-4 animate-fadeIn">
                  {/* Select Pipeline */}
                  <div className="space-y-1.5">
                    <Label htmlFor="target-pipeline" className="text-muted-foreground">Target Pipeline</Label>
                    {pipelines.length === 0 ? (
                      <p className="text-xs text-muted-foreground italic">No pipelines created yet. Go to Pipelines to build one.</p>
                    ) : (
                      <Select
                        key={`pipeline-${selectedPipelineId}-${pipelines.length}`}
                        value={selectedPipelineId}
                        onValueChange={(val) => {
                          setSelectedPipelineId(val || '');
                          setSelectedStageId('');
                        }}
                      >
                        <SelectTrigger className="bg-muted border-border text-foreground">
                          <SelectValue placeholder="Select a pipeline..." />
                        </SelectTrigger>
                        <SelectContent className="bg-muted border-border text-foreground">
                          {pipelines.map((p) => (
                            <SelectItem key={p.id} value={p.id}>
                              {p.name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  </div>

                  {/* Select Pipeline Stage */}
                  <div className="space-y-1.5">
                    <Label htmlFor="target-stage" className="text-muted-foreground">Target Stage</Label>
                    <Select
                      key={`stage-${selectedStageId}-${activeStages.length}`}
                      value={selectedStageId}
                      onValueChange={(val) => setSelectedStageId(val || '')}
                      disabled={!selectedPipelineId}
                    >
                      <SelectTrigger className="bg-muted border-border text-foreground disabled:opacity-50">
                        <SelectValue placeholder={selectedPipelineId ? "Choose pipeline stage..." : "Choose pipeline first..."} />
                      </SelectTrigger>
                      <SelectContent className="bg-muted border-border text-foreground">
                        {activeStages.map((stage) => (
                          <SelectItem key={stage.id} value={stage.id}>
                            {stage.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>
              )}
            </CardContent>
            <CardFooter className="border-t border-border pt-4 flex justify-end">
              <IconAction label="Save Integration Rules" icon={<Loader2 className="size-4 animate-spin " />} onClick={saveIntegrations}
                disabled={savingIntegrations || (createDealOnSubmit && (!selectedPipelineId || !selectedStageId))}
                className="bg-primary hover:bg-primary-hover text-primary-foreground" />
            </CardFooter>
          </Card>
        </TabsContent>

        {/* Tab 3: Responses */}
        <TabsContent value="responses" className="focus-visible:outline-none">
          <Card className="bg-card border-border text-foreground">
            <CardHeader className="pb-3">
              <CardTitle className="text-foreground">Submission History</CardTitle>
              <CardDescription className="text-muted-foreground text-sm">
                Complete log of responses filled out by leads, cross-referenced with your CRM entities.
              </CardDescription>
            </CardHeader>
            <CardContent className="p-0 overflow-x-auto">
              {submissions.length === 0 ? (
                <div className="text-center py-20">
                  <FileText className="size-12 mx-auto text-muted-foreground mb-3" />
                  <h3 className="text-md font-semibold text-foreground">No submissions yet</h3>
                  <p className="text-xs text-muted-foreground mt-1 max-w-xs mx-auto">
                    Share the public form link. When leads fill it out, their details and answers will appear here.
                  </p>
                </div>
              ) : (
                <table className="w-full text-left border-collapse text-xs">
                  <thead>
                    <tr className="border-b border-border bg-background/40 text-muted-foreground">
                      <th className="p-4 font-semibold">Submission Date</th>
                      <th className="p-4 font-semibold">Linked Contact</th>
                      <th className="p-4 font-semibold">Linked Deal</th>
                      {fields.map((field) => (
                        <th key={field.id} className="p-4 font-semibold">
                          {field.label}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {submissions.map((sub) => (
                      <tr key={sub.id} className="border-b border-border/80 hover:bg-background/20">
                        <td className="p-4 text-muted-foreground whitespace-nowrap">
                          {new Date(sub.created_at).toLocaleString()}
                        </td>
                        <td className="p-4 font-medium text-foreground whitespace-nowrap">
                          {sub.contacts ? (
                            <button
                              type="button"
                              onClick={() => router.push(`/contacts?id=${sub.contacts.id}`)}
                              className="text-primary hover:underline"
                            >
                              {sub.contacts.name || sub.contacts.phone}
                            </button>
                          ) : (
                            <span className="text-muted-foreground italic">Deleted contact</span>
                          )}
                        </td>
                        <td className="p-4 whitespace-nowrap">
                          {sub.deals ? (
                            <span className="px-2 py-0.5 rounded-none bg-blue-500/10 text-blue-400 border border-blue-500/20">
                              {sub.deals.title}
                            </span>
                          ) : (
                            <span className="text-muted-foreground italic">—</span>
                          )}
                        </td>
                        {fields.map((field) => {
                          const val = sub.submitted_values[field.id!] !== undefined
                            ? sub.submitted_values[field.id!]
                            : sub.submitted_values[field.label!];

                          const displayVal = Array.isArray(val)
                            ? val.join(', ')
                            : typeof val === 'boolean'
                              ? (val ? 'Yes' : 'No')
                              : val;

                          return (
                            <td key={field.id} className="p-4 text-foreground max-w-[200px] truncate">
                              {displayVal !== undefined && displayVal !== null && displayVal !== '' ? (
                                String(displayVal)
                              ) : (
                                <span className="text-muted-foreground italic">empty</span>
                              )}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { useWorkspace } from '@/hooks/use-workspace';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from '@/components/ui/dropdown-menu';
import { Switch } from '@/components/ui/switch';
import {
  Plus,
  FileText,
  Copy,
  Pencil,
  Trash2,
  Loader2,
  ExternalLink,
  MoreVertical,
  Check,
} from 'lucide-react';
import type { CustomForm } from '@/types';
import { IconAction } from "@/components/ui/icon-action";

export default function FormsPage() {
  const supabase = createClient();
  const router = useRouter();
  const { activeWorkspace } = useWorkspace();

  const [forms, setForms] = useState<CustomForm[]>([]);
  const [submissionCounts, setSubmissionCounts] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);

  // Creation State
  const [createOpen, setCreateOpen] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [creating, setCreating] = useState(false);

  // Delete State
  const [deleteTarget, setDeleteTarget] = useState<CustomForm | null>(null);
  const [deleting, setDeleting] = useState(false);

  // Copy success mapping
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const fetchForms = useCallback(async () => {
    if (!activeWorkspace?.id) {
      setLoading(false);
      return;
    }
    setLoading(true);

    try {
      // Fetch forms
      const { data: formsData, error: formsErr } = await supabase
        .from('custom_forms')
        .select('*')
        .eq('workspace_id', activeWorkspace.id)
        .order('created_at', { ascending: false });

      if (formsErr) throw formsErr;

      // Fetch submission counts
      const { data: subsData, error: subsErr } = await supabase
        .from('custom_form_submissions')
        .select('form_id');

      if (subsErr) throw subsErr;

      const counts: Record<string, number> = {};
      subsData?.forEach((sub) => {
        counts[sub.form_id] = (counts[sub.form_id] || 0) + 1;
      });

      setSubmissionCounts(counts);
      setForms(formsData || []);
    } catch (err: any) {
      toast.error(err.message || 'Failed to load forms');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, supabase]);

  useEffect(() => {
    fetchForms();
  }, [fetchForms]);

  const handleCreate = async () => {
    if (!newTitle.trim() || !activeWorkspace?.id) {
      toast.error('Form title is required');
      return;
    }

    setCreating(true);
    try {
      const { data: newForm, error } = await supabase
        .from('custom_forms')
        .insert({
          workspace_id: activeWorkspace.id,
          title: newTitle.trim(),
          description: newDesc.trim() || null,
          is_active: true,
        })
        .select()
        .single();

      if (error) throw error;

      toast.success('Form created successfully');
      setCreateOpen(false);
      setNewTitle('');
      setNewDesc('');
      router.push(`/forms/${newForm.id}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to create form');
    } finally {
      setCreating(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;

    setDeleting(true);
    try {
      const { error } = await supabase
        .from('custom_forms')
        .delete()
        .eq('id', deleteTarget.id);

      if (error) throw error;

      toast.success('Form deleted successfully');
      setForms((prev) => prev.filter((f) => f.id !== deleteTarget.id));
      setDeleteTarget(null);
    } catch (err: any) {
      toast.error(err.message || 'Failed to delete form');
    } finally {
      setDeleting(false);
    }
  };

  const toggleStatus = async (form: CustomForm, nextStatus: boolean) => {
    try {
      const { error } = await supabase
        .from('custom_forms')
        .update({ is_active: nextStatus, updated_at: new Date().toISOString() })
        .eq('id', form.id);

      if (error) throw error;

      setForms((prev) =>
        prev.map((f) => (f.id === form.id ? { ...f, is_active: nextStatus } : f))
      );
      toast.success(nextStatus ? 'Form activated' : 'Form deactivated');
    } catch (err: any) {
      toast.error(err.message || 'Failed to update status');
    }
  };

  const copyShareLink = async (formId: string) => {
    const origin = typeof window !== 'undefined' ? window.location.origin : '';
    const shareLink = `${origin}/forms/shared/${formId}`;
    try {
      await navigator.clipboard.writeText(shareLink);
      setCopiedId(formId);
      toast.success('Public share link copied to clipboard');
      setTimeout(() => setCopiedId(null), 2000);
    } catch {
      toast.error('Failed to copy link');
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold text-foreground">Custom Forms</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Build forms to capture and ingest leads directly into your contacts and pipelines.
          </p>
        </div>
        <IconAction label="Create Form" icon={<Plus className="size-4 " />} onClick={() => setCreateOpen(true)}
          className="bg-primary hover:bg-primary-hover text-primary-foreground" />
      </div>

      {/* Grid List */}
      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 gap-3">
          <Loader2 className="size-8 animate-spin text-primary" />
          <p className="text-sm text-muted-foreground">Loading forms...</p>
        </div>
      ) : forms.length === 0 ? (
        <div className="rounded-lg border border-dashed border-border p-12 text-center bg-card/20 backdrop-blur-sm">
          <div className="flex flex-col items-center gap-3 max-w-sm mx-auto">
            <div className="size-12 rounded-full bg-muted flex items-center justify-center text-primary">
              <FileText className="size-6" />
            </div>
            <h3 className="text-lg font-medium text-foreground">No forms created yet</h3>
            <p className="text-sm text-muted-foreground">
              Create a custom form, map its inputs to Contact properties or Pipelines, and publish the sharing link to generate leads automatically.
            </p>
            <IconAction label="Create your first form" icon={<Plus className="size-4 " />} onClick={() => setCreateOpen(true)}
              className="mt-2 bg-primary hover:bg-primary-hover text-primary-foreground" />
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {forms.map((form) => (
            <div
              key={form.id}
              className="group relative rounded-xl border border-border/80 bg-card/50 hover:bg-card/80 hover:border-border/80 transition-all duration-200 p-5 flex flex-col justify-between gap-4"
            >
              <div>
                {/* Title and Top Row */}
                <div className="flex items-start justify-between gap-3">
                  <h3 className="font-semibold text-foreground group-hover:text-primary transition-colors line-clamp-1">
                    {form.title}
                  </h3>
                  <DropdownMenu>
                    <DropdownMenuTrigger render={<Button variant="ghost" size="icon-sm" className="text-muted-foreground hover:text-foreground" aria-label="More actions"
                          />} >
                      <MoreVertical className="size-4" />
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="bg-card border-border text-foreground">
                      <DropdownMenuItem
                        onClick={() => router.push(`/forms/${form.id}`)}
                        className="hover:bg-muted focus:bg-muted focus:text-foreground"
                      >
                        <Pencil className="size-4 mr-2" />
                        Edit / Build
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        onClick={() => copyShareLink(form.id)}
                        className="hover:bg-muted focus:bg-muted focus:text-foreground"
                      >
                        <Copy className="size-4 mr-2" />
                        Copy Share Link
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        onClick={() => {
                          const origin = typeof window !== 'undefined' ? window.location.origin : '';
                          window.open(`${origin}/forms/shared/${form.id}`, '_blank');
                        }}
                        className="hover:bg-muted focus:bg-muted focus:text-foreground"
                      >
                        <ExternalLink className="size-4 mr-2" />
                        Open Public Form
                      </DropdownMenuItem>
                      <div className="h-px bg-muted my-1" />
                      <DropdownMenuItem
                        onClick={() => setDeleteTarget(form)}
                        className="text-red-400 focus:bg-red-500/10 focus:text-red-300"
                      >
                        <Trash2 className="size-4 mr-2" />
                        Delete Form
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>

                <p className="text-xs text-muted-foreground mt-1 line-clamp-2 min-h-[2rem]">
                  {form.description || <span className="italic text-muted-foreground">No description</span>}
                </p>
              </div>

              {/* Bottom analytics/actions */}
              <div className="flex items-center justify-between border-t border-border/80 pt-3 mt-1 text-xs">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <span className="font-semibold text-foreground">
                    {submissionCounts[form.id] || 0}
                  </span>
                  <span>responses</span>
                </div>

                <div className="flex items-center gap-3">
                  <button
                    onClick={() => copyShareLink(form.id)}
                    className="text-muted-foreground hover:text-foreground p-1 rounded-none hover:bg-muted transition-colors"
                    title="Copy Public Link"
                  >
                    {copiedId === form.id ? (
                      <Check className="size-3.5 text-emerald-400" />
                    ) : (
                      <Copy className="size-3.5" />
                    )}
                  </button>

                  <div className="flex items-center gap-1.5">
                    <Label className="text-muted-foreground text-[10px] uppercase font-medium">Active</Label>
                    <Switch
                      checked={form.is_active}
                      onCheckedChange={(checked) => toggleStatus(form, checked)}
                      className="data-checked:bg-primary data-unchecked:bg-muted"
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Dialog */}
      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent className="bg-card border-border text-foreground max-w-md">
          <DialogHeader>
            <DialogTitle className="text-foreground">Create New Form</DialogTitle>
            <DialogDescription className="text-muted-foreground text-sm">
              Enter a name and optional description. You will customize fields and mappings on the next screen.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <Label htmlFor="form-title" className="text-foreground">Form Title</Label>
              <Input
                id="form-title"
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                placeholder="e.g. Website Contact Form"
                className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="form-desc" className="text-foreground">Description</Label>
              <Textarea
                id="form-desc"
                value={newDesc}
                onChange={(e) => setNewDesc(e.target.value)}
                placeholder="Briefly state the goal of this form..."
                className="bg-muted border-border text-foreground placeholder:text-muted-foreground min-h-[80px]"
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setCreateOpen(false)}
              className="border-border text-foreground hover:bg-muted hover:text-foreground"
            >
              Cancel
            </Button>
            <Button
              onClick={handleCreate}
              disabled={creating || !newTitle.trim()}
              className="bg-primary hover:bg-primary-hover text-primary-foreground"
            >
              {creating ? <Loader2 className="size-4 animate-spin" /> : 'Create & Design'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Dialog */}
      <Dialog open={!!deleteTarget} onOpenChange={(open) => !open && setDeleteTarget(null)}>
        <DialogContent className="bg-card border-border text-foreground max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-foreground">Delete Form</DialogTitle>
            <DialogDescription className="text-muted-foreground text-sm">
              Are you sure you want to delete <span className="text-foreground font-medium">&quot;{deleteTarget?.title}&quot;</span>? All fields and submissions will be permanently removed. This action cannot be undone.
            </DialogDescription>
          </DialogHeader>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setDeleteTarget(null)}
              className="border-border text-foreground hover:bg-muted hover:text-foreground"
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleDelete}
              disabled={deleting}
              className="bg-red-600 hover:bg-red-700 text-foreground"
            >
              {deleting ? <Loader2 className="size-4 animate-spin" /> : 'Delete Permanently'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

/**
 * Employee Handbook — company details first, then a generated
 * 13-section handbook living inside the existing Policies machinery
 * (versioned content, publish flow, signed acknowledgements).
 *
 * Flow: HR fills Company Details → Generate → sections appear as
 * DRAFT policies → HR reviews/edits/publishes in Policies →
 * employees read & digitally sign each section → progress tracked
 * here. Regenerating only creates missing sections; edits are never
 * overwritten.
 */

import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  BookMarked, Building2, Check, ChevronDown, ChevronRight, Loader2, Plus, Printer, Sparkles, Trash2, Edit3, Send, PlusCircle, ArrowUp, ArrowDown
} from "lucide-react";

import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { PageHeader } from "@/components/ui/page-header";
import { EmptyState } from "@/components/ui/empty-state";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import { AddPolicyDialog } from "@/components/handbook/add-policy-dialog";
import { PrintableHandbookModal } from "@/components/handbook/printable-handbook-modal";
import { PolicyEditorModal } from "@/components/policies/policy-editor-modal";
import { IntegrationShareButtons } from "@/components/integrations/integration-share-buttons";
import { IconAction } from "@/components/ui/icon-action";

interface SectionStatus {
  order: number;
  key: string;
  title: string;
  mandatory: boolean;
  policy_id: string | null;
  status: string | null;
  acknowledged: number;
}

interface DetailsForm {
  legal_name: string;
  brand_name: string;
  director_name: string;
  registered_address: string;
  website: string;
  contact_email: string;
  welcome_message: string;
  vision: string;
  mission: string;
  core_values: string;
  office_start: string;
  office_end: string;
  working_days: string;
  lunch_minutes: string;
  break_minutes: string;
  probation_months: string;
  notice_period_days: string;
  payroll_cycle: string;
  salary_day: string;
  casual_leave_days: string;
  sick_leave_days: string;
  earned_leave_days: string;
  posh_committee: string;
}

const BLANK: DetailsForm = {
  legal_name: "", brand_name: "", director_name: "", registered_address: "",
  website: "", contact_email: "", welcome_message: "", vision: "", mission: "",
  core_values: "", office_start: "09:30", office_end: "18:30",
  working_days: "Monday to Friday", lunch_minutes: "45", break_minutes: "15",
  probation_months: "3", notice_period_days: "30", payroll_cycle: "Monthly",
  salary_day: "7", casual_leave_days: "12", sick_leave_days: "6",
  earned_leave_days: "15", posh_committee: "",
};

const NUMERIC_FIELDS: (keyof DetailsForm)[] = [
  "lunch_minutes", "break_minutes", "probation_months", "notice_period_days",
  "salary_day", "casual_leave_days", "sick_leave_days", "earned_leave_days",
];

const STATUS_CLASSES: Record<string, string> = {
  DRAFT: "bg-yellow-500/10 text-yellow-400 border-yellow-500/20",
  PENDING_APPROVAL: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  PUBLISHED: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
  ARCHIVED: "bg-muted/10 text-muted-foreground border-border/20",
};

export default function HandbookPage() {
  const router = useRouter();
  const supabase = createClient();
  const { activeWorkspace, activeRole, activeMember, can } = useWorkspace();
  const workspaceId = activeWorkspace?.id;
  const isAdmin = activeRole === "owner" || activeRole === "admin";
  const canView = can("people_view");

  const [loading, setLoading] = useState(true);
  const [migrationPending, setMigrationPending] = useState(false);
  const [sections, setSections] = useState<SectionStatus[]>([]);
  const [memberCount, setMemberCount] = useState(0);
  const [missing, setMissing] = useState<string[]>([]);
  const [form, setForm] = useState<DetailsForm>({ ...BLANK });
  const [hasDetails, setHasDetails] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [addPolicyOpen, setAddPolicyOpen] = useState(false);
  const [printModalOpen, setPrintModalOpen] = useState(false);
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingPolicyId, setEditingPolicyId] = useState<string | null>(null);

  const existingPolicyIds = useMemo(
    () => sections.map((s) => s.policy_id).filter(Boolean) as string[],
    [sections]
  );

  const handlePrint = () => {
    setPrintModalOpen(true);
  };

  const handlePublishPolicy = async (policyId: string) => {
    try {
      const res = await fetch(`/api/hr/policies/${policyId}/approve`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ comments: "Published from Handbook" }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to publish policy");
      toast.success("Policy published successfully!");
      void load();
    } catch (err: any) {
      toast.error(err.message || "Failed to publish policy");
    }
  };

  const handleDeletePolicy = async (policyId: string) => {
    if (!confirm("Are you sure you want to delete this policy section?")) return;
    try {
      const res = await fetch(`/api/hr/policies/${policyId}`, { method: "DELETE" });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to delete policy");
      toast.success("Policy deleted successfully!");
      void load();
    } catch (err: any) {
      toast.error(err.message || "Failed to delete policy");
    }
  };

  const moveUp = (index: number) => {
    if (index <= 0) return;
    setSections((prev) => {
      const next = [...prev];
      const temp = next[index];
      next[index] = next[index - 1];
      next[index - 1] = temp;
      const reordered = next.map((item, idx) => ({ ...item, order: idx + 1 }));
      if (workspaceId) {
        localStorage.setItem(`handbook_section_order_${workspaceId}`, JSON.stringify(reordered.map((s) => s.key)));
      }
      return reordered;
    });
    toast.success("Section moved up");
  };

  const moveDown = (index: number) => {
    if (index >= sections.length - 1) return;
    setSections((prev) => {
      const next = [...prev];
      const temp = next[index];
      next[index] = next[index + 1];
      next[index + 1] = temp;
      const reordered = next.map((item, idx) => ({ ...item, order: idx + 1 }));
      if (workspaceId) {
        localStorage.setItem(`handbook_section_order_${workspaceId}`, JSON.stringify(reordered.map((s) => s.key)));
      }
      return reordered;
    });
    toast.success("Section moved down");
  };

  const load = useCallback(async () => {
    if (!workspaceId) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/hr/handbook?workspace_id=${workspaceId}`);
      const json = await res.json();
      if (!res.ok) {
        if (json.error === "MIGRATION_078_PENDING") {
          setMigrationPending(true);
          return;
        }
        throw new Error(json.error || "Failed to load handbook status");
      }
      let loadedSections: SectionStatus[] = json.sections ?? [];
      const savedOrderStr = localStorage.getItem(`handbook_section_order_${workspaceId}`);
      if (savedOrderStr) {
        try {
          const savedKeys: string[] = JSON.parse(savedOrderStr);
          const keyMap = new Map(loadedSections.map((s) => [s.key, s]));
          const reordered: SectionStatus[] = [];
          for (const key of savedKeys) {
            if (keyMap.has(key)) {
              reordered.push(keyMap.get(key)!);
              keyMap.delete(key);
            }
          }
          for (const s of keyMap.values()) {
            reordered.push(s);
          }
          loadedSections = reordered.map((s, idx) => ({ ...s, order: idx + 1 }));
        } catch {
          // ignore invalid order JSON
        }
      }
      setSections(loadedSections);
      setMemberCount(json.member_count ?? 0);
      setMissing(json.missing ?? []);
      const d = json.details;
      setHasDetails(!!d);
      setDetailsOpen(!d || (json.missing ?? []).length > 0);
      if (d) {
        setForm((prev) => {
          const next = { ...prev };
          for (const k of Object.keys(prev) as (keyof DetailsForm)[]) {
            if (d[k] !== null && d[k] !== undefined) next[k] = String(d[k]);
          }
          return next;
        });
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to load handbook");
    } finally {
      setLoading(false);
    }
  }, [workspaceId]);

  useEffect(() => {
    void load();
  }, [load]);

  const generated = useMemo(() => sections.filter((s) => s.policy_id).length, [sections]);

  async function handleSaveDetails() {
    if (!workspaceId || !activeMember?.id) return;
    setSaving(true);
    try {
      const payload: Record<string, unknown> = { workspace_id: workspaceId, updated_by: activeMember.id };
      for (const [k, v] of Object.entries(form)) {
        payload[k] = NUMERIC_FIELDS.includes(k as keyof DetailsForm)
          ? Number(v) || 0
          : v.trim() || null;
      }
      const { error } = await supabase.from("company_details").upsert(payload, { onConflict: "workspace_id" });
      if (error) throw error;
      toast.success("Company details saved");
      await load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save details");
    } finally {
      setSaving(false);
    }
  }

  async function handleGenerate() {
    if (!workspaceId) return;
    setGenerating(true);
    try {
      const res = await fetch("/api/hr/handbook", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ workspace_id: workspaceId }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to generate handbook");
      toast.success(
        json.created > 0
          ? `${json.created} section${json.created === 1 ? "" : "s"} generated as drafts`
          : "All sections already exist — nothing to generate"
      );
      await load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to generate handbook");
    } finally {
      setGenerating(false);
    }
  }

  function field(label: string, key: keyof DetailsForm, props: { textarea?: boolean; placeholder?: string; type?: string } = {}) {
    const required = ["legal_name", "director_name", "vision", "mission", "core_values"].includes(key);
    return (
      <div className="space-y-1.5">
        <label className="text-xs font-medium text-muted-foreground">
          {label}
          {required && <span className="ml-0.5 text-red-400">*</span>}
        </label>
        {props.textarea ? (
          <Textarea
            value={form[key]}
            onChange={(e) => setForm({ ...form, [key]: e.target.value })}
            placeholder={props.placeholder}
            rows={2}
          />
        ) : (
          <Input
            type={props.type ?? "text"}
            value={form[key]}
            onChange={(e) => setForm({ ...form, [key]: e.target.value })}
            placeholder={props.placeholder}
          />
        )}
      </div>
    );
  }

  if (!canView) {
    return (
      <div className="flex h-[50vh] items-center justify-center">
        <EmptyState icon={BookMarked} title="Access denied" description="You need HR access to view the handbook." />
      </div>
    );
  }

  return (
    <div className="p-(--page-padding-desktop) space-y-5">
      <PageHeader
        title="Employee Handbook"
        description="Company details feed a 13-section handbook. Sections publish through Policies and employees sign digitally."
        badge={
          generated > 0 ? (
            <span className="inline-flex h-6 items-center border border-emerald-500/20 bg-emerald-500/10 px-2 text-xs font-medium text-emerald-400">
              {generated}/13 sections
            </span>
          ) : undefined
        }
        actions={
          <div className="flex items-center gap-2">
            {workspaceId && (
              <IntegrationShareButtons
                workspaceId={workspaceId}
                documentTitle="Employee Handbook & Corporate Policies"
                documentSummary="Company operational guidelines and employee handbook."
              />
            )}
            <IconAction label="Print / Export PDF" icon={<Printer className="size-4 " />} variant="outline" onClick={handlePrint} />
            {isAdmin && (
              <>
                <IconAction label="Create Custom Policy" icon={<PlusCircle className="size-4 text-primary" />} variant="outline" onClick={() => { setEditingPolicyId(null); setEditorOpen(true); }} />
                <IconAction label="Attach Existing Policy" icon={<Plus className="size-4 text-primary" />} variant="outline" onClick={() => setAddPolicyOpen(true)} />
                <Button onClick={handleGenerate} disabled={generating || migrationPending || missing.length > 0}>
                  {generating ? <Loader2 className="animate-spin" /> : <Sparkles />}
                  {generated > 0 ? "Generate Missing Sections" : "Generate Handbook"}
                </Button>
              </>
            )}
          </div>
        }
      />

      {migrationPending ? (
        <EmptyState
          icon={BookMarked}
          title="Company details table not set up yet"
          description="Apply migration 078 to this database, then reload."
        />
      ) : (
        <>
          {/* ── company details ─────────────────────────── */}
          <Card>
            <CardHeader
              className="cursor-pointer"
              onClick={() => setDetailsOpen((o) => !o)}
            >
              <CardTitle className="flex items-center gap-2 text-base">
                {detailsOpen ? <ChevronDown className="size-4" /> : <ChevronRight className="size-4" />}
                <Building2 className="size-4" />
                Company Details
                {hasDetails && missing.length === 0 && (
                  <span className="inline-flex h-5 items-center gap-1 border border-emerald-500/20 bg-emerald-500/10 px-1.5 text-[11px] font-medium text-emerald-400">
                    <Check className="size-3" /> complete
                  </span>
                )}
                {missing.length > 0 && (
                  <span className="inline-flex h-5 items-center border border-yellow-500/20 bg-yellow-500/10 px-1.5 text-[11px] font-medium text-yellow-400">
                    {missing.length} required field{missing.length === 1 ? "" : "s"} missing
                  </span>
                )}
              </CardTitle>
            </CardHeader>
            {detailsOpen && (
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
                  {field("Legal name", "legal_name", { placeholder: "Daylink Tech Labs Private Limited" })}
                  {field("Brand name", "brand_name", { placeholder: "Daylink" })}
                  {field("Director name", "director_name")}
                  {field("Registered address", "registered_address")}
                  {field("Website", "website")}
                  {field("HR contact email", "contact_email")}
                </div>
                <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                  {field("Director's welcome message", "welcome_message", { textarea: true, placeholder: "Optional — a default is used if empty" })}
                  {field("Vision", "vision", { textarea: true })}
                  {field("Mission", "mission", { textarea: true })}
                  {field("Core values (one per line)", "core_values", { textarea: true, placeholder: "Ownership\nCraft\nClient trust" })}
                </div>
                <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-6">
                  {field("Office start", "office_start", { placeholder: "09:30" })}
                  {field("Office end", "office_end", { placeholder: "18:30" })}
                  {field("Working days", "working_days")}
                  {field("Lunch (min)", "lunch_minutes", { type: "number" })}
                  {field("Breaks (min)", "break_minutes", { type: "number" })}
                  {field("Probation (months)", "probation_months", { type: "number" })}
                  {field("Notice period (days)", "notice_period_days", { type: "number" })}
                  {field("Payroll cycle", "payroll_cycle")}
                  {field("Salary day of month", "salary_day", { type: "number" })}
                  {field("Casual leave / yr", "casual_leave_days", { type: "number" })}
                  {field("Sick leave / yr", "sick_leave_days", { type: "number" })}
                  {field("Earned leave / yr", "earned_leave_days", { type: "number" })}
                </div>
                {field("POSH committee (leave empty for the <10 employees Local Committee note)", "posh_committee", { textarea: true })}
                {isAdmin && (
                  <div className="flex justify-end">
                    <IconAction label="Save Details" icon={saving ? <Loader2 className="animate-spin" /> : <Check />} onClick={handleSaveDetails} disabled={saving} />
                  </div>
                )}
              </CardContent>
            )}
          </Card>

          {/* ── sections ────────────────────────────────── */}
          <Card>
            <CardContent>
              {loading ? (
                <div className="flex min-h-[160px] items-center justify-center text-muted-foreground">
                  <Loader2 className="size-4 animate-spin" />
                </div>
              ) : generated === 0 ? (
                <EmptyState
                  icon={BookMarked}
                  title="Handbook not generated yet"
                  description={
                    missing.length > 0
                      ? "Complete the required company details above, save, then generate."
                      : "Company details are complete — generate the 13 sections as draft policies."
                  }
                />
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-10">#</TableHead>
                      <TableHead>Section</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Acknowledged</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {sections.map((s, index) => (
                      <TableRow key={s.key}>
                        <TableCell className="text-muted-foreground">
                          <div className="flex items-center gap-1.5">
                            <span className="w-4 font-mono text-xs">{s.order}</span>
                            {isAdmin && (
                              <div className="flex flex-col gap-0.5">
                                <button
                                  type="button"
                                  disabled={index === 0}
                                  onClick={() => moveUp(index)}
                                  className="p-0.5 text-muted-foreground hover:text-foreground disabled:opacity-20 disabled:hover:text-muted-foreground transition-colors"
                                  title="Move section up"
                                >
                                  <ArrowUp className="size-3" />
                                </button>
                                <button
                                  type="button"
                                  disabled={index === sections.length - 1}
                                  onClick={() => moveDown(index)}
                                  className="p-0.5 text-muted-foreground hover:text-foreground disabled:opacity-20 disabled:hover:text-muted-foreground transition-colors"
                                  title="Move section down"
                                >
                                  <ArrowDown className="size-3" />
                                </button>
                              </div>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="font-medium">
                          {s.title.replace(/^Handbook §\d+ — /, "")}
                          {s.mandatory && (
                            <span className="ml-1.5 text-[10px] uppercase text-muted-foreground">mandatory</span>
                          )}
                        </TableCell>
                        <TableCell>
                          {s.status ? (
                            <span className={`inline-flex h-6 items-center border px-2 text-xs font-medium ${STATUS_CLASSES[s.status] ?? ""}`}>
                              {s.status.replace("_", " ").toLowerCase()}
                            </span>
                          ) : (
                            <span className="text-xs text-muted-foreground">not generated</span>
                          )}
                        </TableCell>
                        <TableCell className="text-right text-muted-foreground">
                          {s.policy_id ? `${s.acknowledged}/${memberCount}` : "—"}
                        </TableCell>
                        <TableCell className="text-right">
                          {s.policy_id && (
                            <div className="flex items-center justify-end gap-1">
                              {isAdmin && s.status === "DRAFT" && (
                                <IconAction label="Publish" icon={<Send className="size-3 " />} variant="outline"
                                  className="text-xs text-emerald-500 hover:text-emerald-600 hover:bg-emerald-500/10 border-emerald-500/20"
                                  onClick={() => handlePublishPolicy(s.policy_id!)} />
                              )}
                              {isAdmin && (
                                <IconAction label="Edit" icon={<Edit3 className="size-3.5 " />} variant="ghost"
                                  className="text-xs"
                                  onClick={() => {
                                    setEditingPolicyId(s.policy_id);
                                    setEditorOpen(true);
                                  }} />
                              )}
                              <Button size="sm" variant="outline" className="text-xs" onClick={() => router.push(`/policies/${s.policy_id}/read`)}>
                                Read & Sign
                              </Button>
                              {isAdmin && (
                                <IconAction
                                  label="Delete"
                                  icon={<Trash2 className="size-3.5" />}
                                  variant="ghost"
                                  className="text-xs text-destructive hover:text-destructive hover:bg-destructive/10"
                                  onClick={() => handleDeletePolicy(s.policy_id!)}
                                />
                              )}
                            </div>
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </>
      )}

      {workspaceId && (
        <>
          <AddPolicyDialog
            open={addPolicyOpen}
            onOpenChange={setAddPolicyOpen}
            workspaceId={workspaceId}
            existingPolicyIds={existingPolicyIds}
            onAdded={() => void load()}
          />
          <PrintableHandbookModal
            open={printModalOpen}
            onOpenChange={setPrintModalOpen}
            workspaceId={workspaceId}
            workspaceName={activeWorkspace?.name || "Daily CRM"}
          />
          <PolicyEditorModal
            open={editorOpen}
            onOpenChange={setEditorOpen}
            policyId={editingPolicyId}
            onSaved={() => void load()}
          />
        </>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { EmptyState } from '@/components/ui/empty-state';
import { Button } from '@/components/ui/button';
import { BulkEntryDialog } from '@/components/ui/bulk-entry-dialog';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Calendar, Plus, Layers, Loader2, RefreshCw } from 'lucide-react';
import { toast } from 'sonner';
import { IconAction } from "@/components/ui/icon-action";

export default function HolidaysPage() {
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can('people_manage');

  const [holidays, setHolidays] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [bulkAddOpen, setBulkAddOpen] = useState(false);

  const [title, setTitle] = useState('');
  const [date, setDate] = useState('');
  const [holidayType, setHolidayType] = useState('COMPANY');
  const [recurrenceType, setRecurrenceType] = useState('YEARLY');
  const [description] = useState('');

  /** Posts through the same API route the single-add form uses, so
   *  validation and permission checks are identical. Sequential because
   *  the route takes one record per call. */
  const bulkAdd = async (rows: Record<string, string>[]) => {
    const failures: string[] = [];
    for (const r of rows) {
      const res = await fetch('/api/hr/holidays', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workspaceId: activeWorkspace!.id, title: r.title.trim(), date: r.date.trim(), description: r.description?.trim() || null }),
      });
      if (!res.ok) {
        const j = await res.json().catch(() => ({}));
        failures.push(`${r.title}: ${j.error || res.statusText}`);
      }
    }
    fetchHolidays();
    if (failures.length > 0) {
      // Partial success is reported honestly rather than as a flat failure.
      throw new Error(
        `${rows.length - failures.length} of ${rows.length} added. Failed: ${failures.slice(0, 3).join('; ')}`
      );
    }
    toast.success(`Added ${rows.length} holiday${rows.length === 1 ? '' : 's'}.`);
  };

  const fetchHolidays = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const res = await fetch(`/api/hr/holidays?workspaceId=${activeWorkspace.id}`);
      const json = await res.json();
      setHolidays(json.holidays || []);
    } catch {
      toast.error('Failed to load holidays');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id]);

  useEffect(() => {
    fetchHolidays();
  }, [fetchHolidays]);

  const handleCreateHoliday = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !date) return;
    if (!activeWorkspace?.id) return;

    setSaving(true);
    try {
      const res = await fetch('/api/hr/holidays', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspaceId: activeWorkspace.id,
          title,
          date,
          holidayType,
          recurrenceType,
          description
        })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success('Holiday added to company calendar');
      setTitle('');
      setDate('');
      setModalOpen(false);
      fetchHolidays();
    } catch (err: any) {
      toast.error(err.message || 'Failed to add holiday');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Holidays Calendar"
        description="Official national, company, and optional holidays linked to attendance & leave rules."
        action={
          canManage && (
            <div className="flex items-center gap-2">
              <IconAction label="Bulk add" icon={<Layers className="size-4 " />} variant="outline" onClick={() => setBulkAddOpen(true)} />
              <IconAction label="Add Holiday" icon={<Plus className="size-4 " />} onClick={() => setModalOpen(true)} className="bg-primary text-primary-foreground" />
            </div>
          )
        }
      />

      {loading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="size-8 animate-spin text-primary" />
        </div>
      ) : holidays.length === 0 ? (
        <EmptyState
          icon={Calendar}
          title="No holidays added yet"
          description="Add company holidays and national observances to automatically adjust attendance & leave calculations."
          action={
            canManage
              ? {
                  label: "Add First Holiday",
                  onClick: () => setModalOpen(true),
                  icon: Plus,
                }
              : undefined
          }
        />
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {holidays.map(h => (
            <Card key={h.id} className="border-border bg-card shadow-sm hover:border-primary/50 transition-colors">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <Badge variant="outline" className="text-[10px] uppercase bg-secondary/50">
                    {h.holiday_type}
                  </Badge>
                  <span className="text-xs font-semibold text-primary">
                    {new Date(`${h.date}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                  </span>
                </div>
                <CardTitle className="text-base font-semibold mt-2">{h.title}</CardTitle>
                <CardDescription className="text-xs line-clamp-1 mt-1">
                  {h.description || (h.holiday_type ? `${h.holiday_type.charAt(0)}${h.holiday_type.slice(1).toLowerCase()} holiday` : 'Company holiday')}
                </CardDescription>
              </CardHeader>
              <CardContent className="pt-0 text-xs text-muted-foreground border-t border-border/50 flex items-center justify-between mt-3 pt-3">
                <span className="flex items-center gap-1">
                  <RefreshCw className="size-3 text-muted-foreground" />
                  {h.recurrence_type === 'YEARLY' ? 'Repeats Every Year' : h.recurrence_type === 'MONTHLY' ? 'Repeats Monthly' : 'One-time Event'}
                </span>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Create Holiday Modal */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Company Holiday</DialogTitle>
            <DialogDescription>Add a holiday date to the company calendar.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateHoliday} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Holiday Title</Label>
              <Input placeholder="e.g. Independence Day" value={title} onChange={e => setTitle(e.target.value)} required />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Date</Label>
                <Input type="date" value={date} onChange={e => setDate(e.target.value)} required />
              </div>
              <div className="space-y-2">
                <Label>Holiday Type</Label>
                <Select value={holidayType} onValueChange={(val) => setHolidayType(val || 'COMPANY')}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="NATIONAL">National Holiday</SelectItem>
                    <SelectItem value="COMPANY">Company Holiday</SelectItem>
                    <SelectItem value="OPTIONAL">Optional / Floating</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Recurrence Rule</Label>
              <Select value={recurrenceType} onValueChange={(val) => setRecurrenceType(val || 'YEARLY')}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="YEARLY">Repeats Yearly (e.g. Fixed National Days)</SelectItem>
                  <SelectItem value="NONE">One-Time Event Only</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setModalOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null} Add Holiday
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <BulkEntryDialog
        open={bulkAddOpen}
        onOpenChange={setBulkAddOpen}
        title="Add several holidays"
        scope="holidays"
        workspaceId={activeWorkspace?.id}
        noun="holiday"
        columns={[
          { key: 'title', label: 'Holiday name', required: true, placeholder: 'Diwali' },
          { key: 'date', label: 'Date (YYYY-MM-DD)', required: true, placeholder: '2026-11-08' },
          { key: 'description', label: 'Notes', placeholder: 'Optional' },
        ]}
        onSubmit={bulkAdd}
      />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { RequireModule } from '@/components/auth/require-module';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Users,
  CalendarClock,
  Briefcase,
  CheckCircle2,
  Clock,
  AlertCircle,
  FileCheck,
  TrendingUp,
  Loader2
} from 'lucide-react';
import { useRouter } from 'next/navigation';
import { IconAction } from "@/components/ui/icon-action";

export default function HRDashboardPage() {
  return (
    <RequireModule module="hr">
      <HRDashboardPageContent />
    </RequireModule>
  );
}

function HRDashboardPageContent() {
  const router = useRouter();
  const { activeWorkspace } = useWorkspace();

  const [loading, setLoading] = useState(true);
  const [metrics, setMetrics] = useState<any>({
    totalEmployees: 0,
    presentToday: 0,
    onLeaveToday: 0,
    pendingApprovals: 0,
    pendingLeaves: 0,
    pendingRequests: 0,
    openJobs: 0
  });

  useEffect(() => {
    async function loadDashboardMetrics() {
      if (!activeWorkspace?.id) return;
      setLoading(true);

      try {
        const res = await fetch(`/api/hr/dashboard?workspaceId=${activeWorkspace.id}`);
        const json = await res.json();
        if (json.metrics) {
          setMetrics(json.metrics);
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }

    loadDashboardMetrics();
  }, [activeWorkspace?.id]);

  if (loading) {
    return (
      <div className="flex justify-center py-20">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PageHeader
        title="HR Executive Dashboard"
        description="Real-time workforce headcount, daily attendance, pending approvals, recruitment, and HR operations."
      />

      {/* Metric Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="border-border bg-card shadow-sm cursor-pointer hover:border-primary/50 transition-colors" onClick={() => router.push('/employees')}>
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium flex items-center justify-between">
              <span>Total Workforce</span>
              <Users className="size-4 text-blue-500" />
            </CardDescription>
            <CardTitle className="text-2xl font-bold">{metrics.totalEmployees}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Active employee profiles
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm cursor-pointer hover:border-emerald-500/50 transition-colors" onClick={() => router.push('/attendance')}>
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium flex items-center justify-between">
              <span>Present Today</span>
              <CheckCircle2 className="size-4 text-emerald-500" />
            </CardDescription>
            <CardTitle className="text-2xl font-bold text-emerald-500">{metrics.presentToday}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Punched in for today&apos;s shift
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm cursor-pointer hover:border-amber-500/50 transition-colors" onClick={() => router.push('/leave')}>
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium flex items-center justify-between">
              <span>Pending Approvals</span>
              <Clock className="size-4 text-amber-500" />
            </CardDescription>
            <CardTitle className="text-2xl font-bold text-amber-500">{metrics.pendingApprovals}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            {metrics.pendingLeaves} Leaves • {metrics.pendingRequests} ESS Requests
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm cursor-pointer hover:border-purple-500/50 transition-colors" onClick={() => router.push('/recruitment')}>
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium flex items-center justify-between">
              <span>Open Job Roles</span>
              <Briefcase className="size-4 text-purple-500" />
            </CardDescription>
            <CardTitle className="text-2xl font-bold text-purple-500">{metrics.openJobs}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Active recruitment openings
          </CardContent>
        </Card>
      </div>

      {/* Actionable HR Operations Panels */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Quick Action Navigation */}
        <Card className="border-border bg-card shadow-sm">
          <CardHeader>
            <CardTitle className="text-base font-semibold">HR Operations & Workflows</CardTitle>
            <CardDescription>Quick access to essential HR management modules</CardDescription>
          </CardHeader>
          <CardContent className="grid grid-cols-2 sm:grid-cols-3 gap-3">
            <IconAction label="Recruitment" icon={<Briefcase className="size-5 text-purple-500" />} variant="outline" onClick={() => router.push('/recruitment')} className="h-20 flex flex-col items-center justify-center gap-1.5 bg-muted/20" />

            <IconAction label="Shifts & Roster" icon={<Clock className="size-5 text-emerald-500" />} variant="outline" onClick={() => router.push('/shifts')} className="h-20 flex flex-col items-center justify-center gap-1.5 bg-muted/20" />

            <IconAction label="Holidays" icon={<CalendarClock className="size-5 text-blue-500" />} variant="outline" onClick={() => router.push('/holidays')} className="h-20 flex flex-col items-center justify-center gap-1.5 bg-muted/20" />

            <IconAction label="Performance" icon={<TrendingUp className="size-5 text-amber-500" />} variant="outline" onClick={() => router.push('/performance')} className="h-20 flex flex-col items-center justify-center gap-1.5 bg-muted/20" />

            <IconAction label="ESS Requests" icon={<FileCheck className="size-5 text-indigo-500" />} variant="outline" onClick={() => router.push('/requests')} className="h-20 flex flex-col items-center justify-center gap-1.5 bg-muted/20" />

            <IconAction label="Policies" icon={<CheckCircle2 className="size-5 text-teal-500" />} variant="outline" onClick={() => router.push('/policies')} className="h-20 flex flex-col items-center justify-center gap-1.5 bg-muted/20" />
          </CardContent>
        </Card>

        {/* Action Needed Alerts */}
        <Card className="border-border bg-card shadow-sm">
          <CardHeader>
            <CardTitle className="text-base font-semibold">Action Needed Today</CardTitle>
            <CardDescription>Operational items requiring HR attention</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex items-center justify-between p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-900 dark:text-amber-200 text-xs">
              <div className="flex items-center gap-2">
                <AlertCircle className="size-4 shrink-0 text-amber-600" />
                <span><strong>{metrics.pendingLeaves} Leave Applications</strong> waiting for approval</span>
              </div>
              <Button size="sm" variant="ghost" onClick={() => router.push('/leave')} className="text-xs text-amber-700 dark:text-amber-300">
