"use client";

import { useState, useCallback, useEffect, useRef } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { createClient } from "@/lib/supabase/client";
import type { Conversation, Message, Contact, ConversationStatus } from "@/types";
import { useRealtime } from "@/hooks/use-realtime";
import { useWorkspace } from "@/hooks/use-workspace";
import { ConversationList } from "@/components/inbox/conversation-list";
import { MessageThread } from "@/components/inbox/message-thread";
import { ContactSidebar } from "@/components/inbox/contact-sidebar";
import { NewChatModal } from "@/components/inbox/new-chat-modal";
import { toast } from "sonner";
import { useMessageNotifications } from "@/hooks/use-message-notifications";
import { WifiOff } from "lucide-react";
import { cn } from "@/lib/utils";

export default function InboxPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { activeWorkspace } = useWorkspace();
  /**
   * `?c=<id>` deep-link support. Used when landing here from the
   * dashboard's recent-conversations list so the right thread opens
   * automatically instead of showing the empty center panel.
   */
  const deepLinkConvId = searchParams.get("c");

  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [activeConversation, setActiveConversation] =
    useState<Conversation | null>(null);
  const [activeContact, setActiveContact] = useState<Contact | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [whatsappConnected, setWhatsappConnected] = useState<boolean | null>(
    null
  );
  const [newChatModalOpen, setNewChatModalOpen] = useState(false);
  // Whether the workspace's chatbot feature is enabled in Settings.
  // Gates the per-conversation bot toggle/indicators — showing a bot
  // pause/resume control while the chatbot is off is just noise.
  const [chatbotEnabled, setChatbotEnabled] = useState(false);

  useEffect(() => {
    const workspaceId = activeWorkspace?.id;
    if (!workspaceId) {
      setChatbotEnabled(false);
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(
          `/api/whatsapp/chatbot-config?workspace_id=${workspaceId}`
        );
        if (!res.ok) return;
        const config = await res.json();
        if (!cancelled) setChatbotEnabled(!!config?.is_enabled);
      } catch {
        // Leave the toggle hidden when the config can't be fetched.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [activeWorkspace?.id]);

  // Fire the deep-link auto-select exactly once per URL — subsequent
  // list refreshes (realtime, manual refetch) must not snap the user
  // back to the deep-linked conversation if they've already clicked
  // elsewhere.
  const autoSelectedForDeepLinkRef = useRef<string | null>(null);

  // Mirror of `conversations` for callbacks that must not be recreated
  // when the list changes (the notification click handler).
  const conversationsRef = useRef<Conversation[]>([]);
  useEffect(() => {
    conversationsRef.current = conversations;
  });

  /** Open a thread by id — used when a desktop notification is clicked. */
  const openConversationById = useCallback(
    (conversationId: string) => {
      const match = conversationsRef.current.find(
        (c) => c.id === conversationId
      );
      if (!match) return;
      setActiveConversation(match);
      setActiveContact(match.contact ?? null);
      setMessages([]);
      autoSelectedForDeepLinkRef.current = conversationId;
      router.replace(`/inbox?c=${conversationId}`, { scroll: false });
    },
    [router]
  );

  const {
    enabled: notificationsEnabled,
    permission: notificationPermission,
    toggle: toggleNotifications,
    notify,
  } = useMessageNotifications({ onOpenConversation: openConversationById });

  // Check WhatsApp connection status on mount
  useEffect(() => {
    const checkConnection = async () => {
      const supabase = createClient();
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const user = session?.user;

      if (!user) return;

      // Table is `whatsapp_config` (singular) — the previous "whatsapp_configs"
      // query always returned no rows, so the banner always showed "not connected".
      const { data } = await supabase
        .from("whatsapp_config")
        .select("status")
        .eq("user_id", user.id)
        .maybeSingle();

      setWhatsappConnected(data?.status === "connected");
    };

    checkConnection();
  }, []);

  // Handle realtime message events
  const handleMessageEvent = useCallback(
    (event: { eventType: string; new: Message; old: Partial<Message> }) => {
      const newMsg = event.new;

      if (event.eventType === "INSERT") {
        // Add to messages if it belongs to active conversation
        if (
          activeConversation &&
          newMsg.conversation_id === activeConversation.id
        ) {
          setMessages((prev) => {
            // Avoid duplicates
            if (prev.some((m) => m.id === newMsg.id)) return prev;
            // Drop only the optimistic bubble this message replaces —
            // clearing every temp- row would delete other in-flight
            // sends (and failed ones the user still needs to see).
            const withoutOptimistic = prev.filter(
              (m) =>
                !m.id.startsWith("temp-") ||
                m.content_type !== newMsg.content_type ||
                (m.content_text ?? "") !== (newMsg.content_text ?? "")
            );
            return [...withoutOptimistic, newMsg];
          });
        }

        // Alert on inbound customer messages. Skipped when the user is
        // already looking at that thread in a focused tab — they can
        // see it arrive.
        const isInbound = newMsg.sender_type === "customer";
        const isViewingThread =
          activeConversation?.id === newMsg.conversation_id &&
          typeof document !== "undefined" &&
          !document.hidden;
        if (isInbound && !isViewingThread) {
          const contactName =
            conversations.find((c) => c.id === newMsg.conversation_id)?.contact
              ?.name ?? "New message";
          notify({
            id: newMsg.id,
            title: contactName,
            body: newMsg.content_text?.slice(0, 140) || "Sent an attachment",
            conversationId: newMsg.conversation_id,
          });
        }

        // Update conversation list preview
        setConversations((prev) =>
          prev.map((c) =>
            c.id === newMsg.conversation_id
              ? {
                  ...c,
                  last_message_text: newMsg.content_text ?? "",
                  last_message_at: newMsg.created_at,
                  unread_count:
                    activeConversation?.id === newMsg.conversation_id
                      ? 0
                      : c.unread_count + 1,
                }
              : c
          )
        );
      }

      if (event.eventType === "UPDATE") {
        // Update message status
        setMessages((prev) =>
          prev.map((m) => (m.id === newMsg.id ? { ...m, ...newMsg } : m))
        );
      }
    },
    [activeConversation, conversations, notify]
  );

  // Handle realtime conversation events
  const handleConversationEvent = useCallback(
    (event: {
      eventType: string;
      new: Conversation;
      old: Partial<Conversation>;
    }) => {
      const conv = event.new;

      if (event.eventType === "INSERT") {
        setConversations((prev) => [conv, ...prev]);
      }

      if (event.eventType === "UPDATE") {
        setConversations((prev) =>
          prev.map((c) => (c.id === conv.id ? { ...c, ...conv } : c))
        );

        // Update active conversation if it changed
        if (activeConversation && conv.id === activeConversation.id) {
          setActiveConversation((prev) =>
            prev ? { ...prev, ...conv } : prev
          );
        }
      }
    },
    [activeConversation]
  );

  // Subscribe to realtime
  useRealtime({
    channelName: "inbox-realtime",
    onMessageEvent: handleMessageEvent,
    onConversationEvent: handleConversationEvent,
    enabled: true,
  });

  const handleConversationsLoaded = useCallback(
    (loaded: Conversation[]) => {
      // The thread the user is reading is read by definition. Without
      // this, a poll that lands before the server-side unread reset is
      // visible re-shows the badge on the conversation they're looking
      // at, so it blinks back on every refresh.
      const activeId = activeConversation?.id;
      setConversations(
        activeId
          ? loaded.map((c) =>
              c.id === activeId && c.unread_count > 0
                ? { ...c, unread_count: 0 }
                : c,
            )
          : loaded,
      );
      // Resolve a pending deep-link here rather than in an effect — this
      // is an event handler, so the setState calls below are allowed by
      // react-hooks/set-state-in-effect. Runs once per ?c=<id> URL value
      // via the ref, so realtime refreshes of the list can't snap the
      // user back to the deep-linked thread after they've navigated.
      // Only ever auto-select when NOTHING is open yet — i.e. on arrival
      // via a ?c=<id> link. Previously this fired whenever the ref
      // didn't match `deepLinkConvId`, which broke starting a new chat:
      // selecting it calls router.replace(?c=<new>), but `deepLinkConvId`
      // still reads the OLD id for a tick, so the next list poll saw
      // ref(new) !== deepLink(old) and yanked the user back into the
      // previous conversation.
      if (
        deepLinkConvId &&
        !activeConversation &&
        autoSelectedForDeepLinkRef.current !== deepLinkConvId &&
        loaded.length > 0
      ) {
        autoSelectedForDeepLinkRef.current = deepLinkConvId;
        // Nothing is open at this point (guarded above), so applying the
        // deep link can't clobber an already-loaded thread's messages.
        const match = loaded.find((c) => c.id === deepLinkConvId);
        if (match) {
          setActiveConversation(match);
          setActiveContact(match.contact ?? null);
          setMessages([]);
        }
      }
    },
    [deepLinkConvId, activeConversation?.id]
  );

  const handleSelectConversation = useCallback(
    (conv: Conversation) => {
      // Re-clicking the already-active conversation would clear the
      // messages array, but the fetch effect in MessageThread only re-runs
      // when conversationId changes — so messages would stay empty until
      // the user navigated away and back. Bail out early instead.
      if (activeConversation?.id === conv.id) return;
      setActiveConversation(conv);
      setActiveContact(conv.contact ?? null);
      setMessages([]);
      // Optimistically clear the unread badge for the opened thread —
      // MessageThread resets the server-side unread_count, but waiting
      // for realtime/polling to echo that back leaves the badge lingering
      // for a few seconds after the user has already opened the chat.
      if (conv.unread_count > 0) {
        setConversations((prev) =>
          prev.map((c) => (c.id === conv.id ? { ...c, unread_count: 0 } : c))
        );
      }
      // Record the selection on the deep-link ref BEFORE we change the
      // URL. The router.replace below flips `deepLinkConvId`, which can
      // in turn cause ConversationList to refetch and eventually call
      // handleConversationsLoaded again. Without this line, the ref
      // still points at the previous value, the auto-select block
      // sees `ref !== deepLinkConvId`, fires a second time, and
      // clobbers the messages MessageThread just fetched.
      autoSelectedForDeepLinkRef.current = conv.id;
      // Reflect the selection in the URL so a refresh lands the user
      // back in the same thread, and so copy-paste links work. Use
      // replace() to avoid polluting browser history with every click.
      router.replace(`/inbox?c=${conv.id}`, { scroll: false });
    },
    [activeConversation?.id, router]
  );

  // Mobile "back" — deselect the conversation so the list pane comes
  // back. Also clears the ?c= param so a refresh lands on the list
  // instead of re-opening the thread the user just backed out of.
  const handleCloseConversation = useCallback(() => {
    setActiveConversation(null);
    setActiveContact(null);
    setMessages([]);
    // Clearing the ref lets the deep-link auto-selector fire again if
    // the user later visits /inbox?c=<same-id> — desirable UX.
    autoSelectedForDeepLinkRef.current = null;
    router.replace("/inbox", { scroll: false });
  }, [router]);


  /**
   * Merge a freshly-fetched server list with any optimistic messages
   * still in flight.
   *
   * A plain `setMessages(loaded)` was why a just-sent (or just-received)
   * bubble appeared, vanished for a second, then came back: the send
   * inserts a `temp-…` bubble immediately, a poll that lands before the
   * row is readable returns a list without it, and replacing the array
   * wholesale deleted the bubble until the next poll saw the real row.
   *
   * Optimistic bubbles are kept until the server list contains an
   * equivalent message (same kind + text), so a failed send also stays
   * put with its error state instead of silently disappearing.
   */
  const handleMessagesLoaded = useCallback((loaded: Message[]) => {
    setMessages((prev) => {
      const pending = prev.filter((m) => m.id.startsWith("temp-"));
      if (pending.length === 0) return loaded;

      const serverKeys = new Set(
        loaded.map((m) => `${m.content_type}|${m.content_text ?? ""}`),
      );
      const stillPending = pending.filter(
        (m) => !serverKeys.has(`${m.content_type}|${m.content_text ?? ""}`),
      );
      return stillPending.length > 0 ? [...loaded, ...stillPending] : loaded;
    });
  }, []);

  const handleNewMessage = useCallback((msg: Message) => {
    setMessages((prev) => {
      if (prev.some((m) => m.id === msg.id)) return prev;
      return [...prev, msg];
    });
  }, []);

  const handleUpdateMessage = useCallback(
    (id: string, updates: Partial<Message>) => {
      setMessages((prev) =>
        prev.map((m) => (m.id === id ? { ...m, ...updates } : m))
      );
    },
    []
  );

  const handleStatusChange = useCallback(
    (conversationId: string, status: ConversationStatus) => {
      setConversations((prev) =>
        prev.map((c) => (c.id === conversationId ? { ...c, status } : c))
      );
      if (activeConversation?.id === conversationId) {
        setActiveConversation((prev) => (prev ? { ...prev, status } : prev));
      }
    },
    [activeConversation]
  );

  const handleAssignChange = useCallback(
    (conversationId: string, assignedAgentId: string | null) => {
      setConversations((prev) =>
        prev.map((c) =>
          c.id === conversationId
            ? { ...c, assigned_agent_id: assignedAgentId ?? undefined }
            : c
        )
      );
      if (activeConversation?.id === conversationId) {
        setActiveConversation((prev) =>
          prev
            ? { ...prev, assigned_agent_id: assignedAgentId ?? undefined }
            : prev
        );
      }
    },
    [activeConversation]
  );

  const handleConversationCreated = useCallback(
    (conv: Conversation) => {
      setConversations((prev) => {
        if (prev.some((c) => c.id === conv.id)) return prev;
        return [conv, ...prev];
      });
      handleSelectConversation(conv);
    },
    [handleSelectConversation]
  );

  const handleDeleteConversation = useCallback(
    async (conversationId: string) => {
      if (!confirm("Are you sure you want to delete this conversation? All messages in this chat will be permanently removed.")) {
        return;
      }

      try {
        const res = await fetch(`/api/conversations/${conversationId}`, {
          method: "DELETE",
        });

        const data = await res.json();
        if (!res.ok) {
          toast.error(data.error || "Failed to delete conversation");
          return;
        }

        toast.success("Conversation deleted");
        setConversations((prev) => prev.filter((c) => c.id !== conversationId));
        if (activeConversation?.id === conversationId) {
          setActiveConversation(null);
          setActiveContact(null);
          setMessages([]);
        }
      } catch (err) {
        console.error("Error deleting conversation:", err);
        toast.error("Failed to delete conversation");
      }
    },
    [activeConversation?.id]
  );

  // On mobile (<lg) we show a SINGLE pane — either the list or the
  // thread — rather than cramming both side-by-side. Selecting a
  // conversation slides the thread in; the thread's back button pops
  // it back to the list. On lg+ both panes render side-by-side as
  // before, unchanged.
  const hasActiveConv = !!activeConversation;

  return (
    <div className="flex h-[calc(100vh-var(--topbar-height))] flex-col overflow-hidden">
      {/* WhatsApp connection banner — in the flex column, not absolute,
          so it pushes the panels down instead of overlapping them. */}
      {whatsappConnected === false && (
        <div className="flex shrink-0 items-center justify-center gap-2 border-b border-amber-500/20 bg-amber-500/10 px-4 py-2">
          <WifiOff className="h-4 w-4 text-amber-400" />
          <p className="text-xs text-amber-400">
            WhatsApp® is not connected. Go to Settings to connect your account.
          </p>
        </div>
      )}

      <div className="flex flex-1 overflow-hidden">
        {/* Left panel: Conversation list.
            Hidden on mobile when a conversation is selected so the
            thread can occupy the full width. Always visible on lg+. */}
        <div
          className={cn(
            "flex h-full flex-1 lg:flex-none",
            hasActiveConv ? "hidden lg:flex" : "flex",
          )}
        >
          <ConversationList
            activeConversationId={activeConversation?.id ?? null}
            onSelect={handleSelectConversation}
            conversations={conversations}
            onConversationsLoaded={handleConversationsLoaded}
            workspaceId={activeWorkspace?.id}
            onOpenNewChat={() => setNewChatModalOpen(true)}
            onDeleteConversation={handleDeleteConversation}
            chatbotEnabled={chatbotEnabled}
            notificationsEnabled={notificationsEnabled}
            notificationPermission={notificationPermission}
            onToggleNotifications={toggleNotifications}
          />
        </div>

        {/* Center panel: Message thread.
            Hidden on mobile when no conversation is selected so the
            list can occupy the full width. Always visible on lg+
            (shows its own empty-state if no thread is picked yet). */}
        <div
          className={cn(
            "flex h-full flex-1 lg:flex",
            hasActiveConv ? "flex" : "hidden lg:flex",
          )}
        >
          <MessageThread
            conversation={activeConversation}
            contact={activeContact}
            messages={messages}
            onMessagesLoaded={handleMessagesLoaded}
            onNewMessage={handleNewMessage}
            onUpdateMessage={handleUpdateMessage}
            onStatusChange={handleStatusChange}
            onAssignChange={handleAssignChange}
            onBack={handleCloseConversation}
            onOpenNewChat={() => setNewChatModalOpen(true)}
            onDeleteConversation={handleDeleteConversation}
            chatbotEnabled={chatbotEnabled}
          />
        </div>

        {/* Right panel: Contact sidebar — desktop only. */}
        <div className="hidden lg:block">
          <ContactSidebar contact={activeContact} />
        </div>
      </div>

      <NewChatModal
        open={newChatModalOpen}
        onOpenChange={setNewChatModalOpen}
        workspaceId={activeWorkspace?.id}
        onConversationCreated={handleConversationCreated}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Search, Loader2, Umbrella, CheckCircle2, XCircle, Plus } from 'lucide-react';
import { PageHeader } from '@/components/shared/page-header';
import { useWorkspace } from '@/hooks/use-workspace';
import { assertAffected } from '@/lib/supabase/affected-rows';
import { Input } from '@/components/ui/input';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { LeaveRequestForm } from '@/components/leave/leave-request-form';
import { IconAction } from "@/components/ui/icon-action";

export default function LeavePage() {
  const supabase = createClient();
  const { activeWorkspace, activeMember, can } = useWorkspace();
  const canApproveLeave = can('leave_approve') || can('people_manage'); 

  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [formOpen, setFormOpen] = useState(false);

  const fetchLeaveRequests = useCallback(async () => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    setLoading(true);

    let query = supabase
      .from('leave_requests')
      .select(`
        *,
        workspace_members!leave_requests_workspace_member_id_fkey ( id, user_id ),
        approver:workspace_members!leave_requests_approved_by_fkey ( id, user_id )
      `)
      .eq('workspace_id', activeWorkspace.id)
      .order('created_at', { ascending: false });

    if (!canApproveLeave) {
      query = query.eq('workspace_member_id', activeMember.id);
    }

    const { data, error } = await query;

    if (!error && data && data.length > 0) {
      // Two-step profile enrichment for both member and approver user_ids
      const allUserIds = [
        ...data.map((r: any) => r.workspace_members?.user_id),
        ...data.map((r: any) => r.approver?.user_id)
      ].filter(Boolean);
      const uniqueUserIds = [...new Set(allUserIds)];
      const profileMap: Record<string, any> = {};
      if (uniqueUserIds.length > 0) {
        const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name, avatar_url').in('user_id', uniqueUserIds);
        (profilesData || []).forEach((p: any) => { profileMap[p.user_id] = p; });
      }
      data.forEach((r: any) => {
        if (r.workspace_members?.user_id) r.workspace_members.profiles = profileMap[r.workspace_members.user_id] || null;
        if (r.approver?.user_id) r.approver.profiles = profileMap[r.approver.user_id] || null;
      });
    }


    if (error) {
      toast.error('Failed to load leave requests');
    } else {
      let filtered = data || [];
      if (search.trim()) {
        const q = search.toLowerCase();
        filtered = filtered.filter(r => {
          const profile = Array.isArray(r.workspace_members?.profiles) 
            ? r.workspace_members?.profiles[0] 
            : r.workspace_members?.profiles;
          return profile?.full_name?.toLowerCase().includes(q) || r.leave_type?.toLowerCase().includes(q);
        });
      }
      setRequests(filtered);
    }
    setLoading(false);
  }, [supabase, activeWorkspace?.id, activeMember?.id, canApproveLeave, search]);

  useEffect(() => {
    fetchLeaveRequests();
  }, [fetchLeaveRequests]);

  const [actionLoadingId, setActionLoadingId] = useState<{ id: string; action: 'approved' | 'rejected' } | null>(null);

  const handleUpdateStatus = async (id: string, status: 'approved' | 'rejected') => {
    if (!activeMember?.id) return;
    setActionLoadingId({ id, action: status });
    try {
      const result = await supabase
        .from('leave_requests')
        .update({
          status,
          approved_by: activeMember.id
        })
        .eq('id', id)
        .select('id');

      assertAffected(result, 'the leave request');
      toast.success(`Leave request ${status === 'approved' ? 'approved' : 'rejected'}`);
      fetchLeaveRequests();
    } catch (error: any) {
      toast.error(error.message || `Failed to ${status} request`);
    } finally {
      setActionLoadingId(null);
    }
  };

  const renderStatusBadge = (status: string) => {
    const s = (status || 'pending').toLowerCase();
    if (s === 'approved') {
      return (
        <Badge variant="outline" className="bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/30 gap-1 font-semibold px-2.5 py-0.5 rounded-full">
          <CheckCircle2 className="size-3.5 text-emerald-500" /> Approved
        </Badge>
      );
    }
    if (s === 'rejected') {
      return (
        <Badge variant="outline" className="bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/30 gap-1 font-semibold px-2.5 py-0.5 rounded-full">
          <XCircle className="size-3.5 text-red-500" /> Rejected
        </Badge>
      );
    }
    return (
      <Badge variant="outline" className="bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/30 font-semibold px-2.5 py-0.5 rounded-full">
        Pending
      </Badge>
    );
  };

  return (
    <div className="space-y-6">
      <PageHeader 
        title="Leave Management" 
        description={canApproveLeave ? "Review and manage team leave requests." : "Track your time off and submit new requests."}
        action={
          <IconAction label="Request Leave" icon={<Plus className="size-4 " />} onClick={() => setFormOpen(true)} className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm" />
        }
      />

      <div className="flex flex-col sm:flex-row gap-2">
        <div className="relative w-full max-w-sm">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={canApproveLeave ? "Search by employee name or leave type..." : "Search leave types..."}
            className="pl-8 bg-card border-border text-foreground placeholder:text-muted-foreground"
          />
        </div>
      </div>

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent">
              {canApproveLeave && <TableHead className="text-muted-foreground">Employee</TableHead>}
              <TableHead className="text-muted-foreground">Leave Type</TableHead>
              <TableHead className="text-muted-foreground">Dates</TableHead>
              <TableHead className="text-muted-foreground hidden lg:table-cell">Reason</TableHead>
              <TableHead className="text-muted-foreground">Status</TableHead>
              <TableHead className="text-muted-foreground text-right pr-6">{canApproveLeave ? "Actions" : ""}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={canApproveLeave ? 6 : 5} className="text-center py-12">
                  <div className="flex flex-col items-center gap-2">
                    <Loader2 className="size-6 animate-spin text-primary" />
                    <p className="text-sm text-muted-foreground">Loading leave requests...</p>
                  </div>
                </TableCell>
              </TableRow>
            ) : requests.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={canApproveLeave ? 6 : 5} className="text-center py-12">
                  <div className="flex flex-col items-center gap-2">
                    <Umbrella className="size-8 text-muted-foreground" />
                    <p className="text-sm text-muted-foreground">
                      No leave requests found.
                    </p>
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              requests.map((record) => {
                const profile = Array.isArray(record.workspace_members?.profiles) 
                  ? record.workspace_members?.profiles[0] 
                  : record.workspace_members?.profiles;
                const fullName = profile?.full_name || 'Unknown User';

                const from = new Date(record.from_date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
                const to = new Date(record.to_date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
                const dateStr = from === to ? from : `${from} - ${to}`;
                const isPending = (record.status || 'pending').toLowerCase() === 'pending';
                const isRowLoading = actionLoadingId?.id === record.id;

                return (
                  <TableRow key={record.id} className="border-border hover:bg-muted/50 transition-colors">
                    {canApproveLeave && (
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Avatar className="size-7 border border-border">
                            {profile?.avatar_url && <AvatarImage src={profile.avatar_url} />}
                            <AvatarFallback className="bg-primary/10 text-primary text-xs font-medium">
                              {fullName.charAt(0).toUpperCase()}
                            </AvatarFallback>
                          </Avatar>
                          <span className="text-sm font-medium text-foreground">{fullName}</span>
                        </div>
                      </TableCell>
                    )}
                    <TableCell className="font-medium text-foreground">
                      {record.leave_type}
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {dateStr}
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground hidden lg:table-cell truncate max-w-[200px]" title={record.reason}>
                      {record.reason || '-'}
                    </TableCell>
                    <TableCell>
                      {renderStatusBadge(record.status)}
                    </TableCell>
                    <TableCell className="text-right pr-4">
                      {canApproveLeave && isPending ? (
                        <div className="flex items-center justify-end gap-2">
                          <Button
                            size="sm"
                            onClick={() => handleUpdateStatus(record.id, 'approved')}
                            disabled={isRowLoading}
                            className="h-8 px-3 text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white shadow-sm gap-1.5 transition-all rounded-lg"
                          >
                            {isRowLoading && actionLoadingId?.action === 'approved' ? (
                              <Loader2 className="size-3.5 animate-spin" />
                            ) : (
                              <CheckCircle2 className="size-3.5" />
                            )}
                            Approve
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleUpdateStatus(record.id, 'rejected')}
                            disabled={isRowLoading}
                            className="h-8 px-3 text-xs font-semibold border-red-500/30 text-red-600 dark:text-red-400 hover:bg-red-500/10 hover:text-red-700 active:scale-95 shadow-xs gap-1.5 transition-all rounded-lg"
                          >
                            {isRowLoading && actionLoadingId?.action === 'rejected' ? (
                              <Loader2 className="size-3.5 animate-spin" />
                            ) : (
                              <XCircle className="size-3.5" />
                            )}
                            Reject
                          </Button>
                        </div>
                      ) : (
                        <span className="text-xs text-muted-foreground font-mono">
                          {record.approver?.profiles?.full_name ? `By ${record.approver.profiles.full_name}` : '—'}
                        </span>
                      )}
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      <LeaveRequestForm
        open={formOpen}
        onOpenChange={setFormOpen}
        onSaved={fetchLeaveRequests}
      />
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { toast } from "sonner";
import { Loader2, Plus, Umbrella, CheckCircle2, XCircle, Clock } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { PageHeader } from "@/components/ui/page-header";
import { LeaveRequestForm } from "@/components/leave/leave-request-form";
import { IconAction } from "@/components/ui/icon-action";

interface LeaveRow {
  id: string;
  leave_type: string;
  from_date: string;
  to_date: string;
  status: string;
  reason: string | null;
  approved_by?: string | null;
  approver?: {
    id: string;
    user_id: string;
    profiles?: {
      full_name: string;
      avatar_url?: string;
    } | null;
  } | null;
}

const STATUS_STYLES: Record<string, string> = {
  approved: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/30 font-semibold",
  rejected: "bg-rose-500/10 text-rose-600 dark:text-rose-400 border-rose-500/30 font-semibold",
  pending: "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/30 font-semibold",
};

/** The employee's own leave: request it, and see where each request stands. */
export default function MyLeavePage() {
  const supabase = createClient();
  const { activeWorkspace, activeMember } = useWorkspace();
  const [rows, setRows] = useState<LeaveRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [formOpen, setFormOpen] = useState(false);

  const fetchMine = useCallback(async () => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("leave_requests")
        .select(`
          id, leave_type, from_date, to_date, status, reason, approved_by,
          approver:workspace_members!leave_requests_approved_by_fkey ( id, user_id )
        `)
        .eq("workspace_id", activeWorkspace.id)
        .eq("workspace_member_id", activeMember.id)
        .order("from_date", { ascending: false });

      if (error) throw error;

      let resultRows = (data as any[] | null) || [];

      if (resultRows.length > 0) {
        const approverUserIds = resultRows.map((r) => r.approver?.user_id).filter(Boolean);
        const uniqueUserIds = [...new Set(approverUserIds)];
        const profileMap: Record<string, any> = {};

        if (uniqueUserIds.length > 0) {
          const { data: profilesData } = await supabase
            .from("profiles")
            .select("user_id, full_name, avatar_url")
            .in("user_id", uniqueUserIds);

          (profilesData || []).forEach((p: any) => {
            profileMap[p.user_id] = p;
          });
        }

        resultRows.forEach((r) => {
          if (r.approver?.user_id) {
            r.approver.profiles = profileMap[r.approver.user_id] || null;
          }
        });
      }

      setRows(resultRows);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to load your leave");
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id, activeMember?.id]);

  useEffect(() => {
    fetchMine();
  }, [fetchMine]);

  return (
    <div className="space-y-5">
      <PageHeader
        title="My Leave"
        description="Request time off and track where each request stands."
        actions={
          <IconAction label="Request leave" icon={<Plus className="size-4" />} onClick={() => setFormOpen(true)} className="gap-1.5" />
        }
      />

      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="size-5 animate-spin text-muted-foreground" />
        </div>
      ) : rows.length === 0 ? (
        <div className="rounded-xl border border-dashed border-border py-14 text-center">
          <Umbrella className="mx-auto size-7 text-muted-foreground/60" />
          <p className="mt-3 text-sm font-medium text-foreground">No leave requested yet</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Your requests and their approval status will appear here.
          </p>
        </div>
      ) : (
        <div className="divide-y divide-border rounded-xl border border-border bg-card">
          {rows.map((r) => {
            const approverName = r.approver?.profiles?.full_name;
            const statusKey = (r.status || "pending").toLowerCase();

            return (
              <div key={r.id} className="flex items-center justify-between gap-3 px-4 py-3.5 hover:bg-muted/40 transition-colors">
                <div className="min-w-0">
                  <p className="text-sm font-semibold text-foreground">
                    {r.leave_type} · {r.from_date} to {r.to_date}
                  </p>
                  {r.reason && <p className="truncate text-xs text-muted-foreground mt-0.5">{r.reason}</p>}
                </div>
                <div className="flex flex-col items-end gap-1 shrink-0">
                  <Badge variant="outline" className={`text-[10px] uppercase tracking-wider font-bold px-2 py-0.5 rounded-md ${STATUS_STYLES[statusKey] ?? ""}`}>
                    {r.status}
                  </Badge>
                  {statusKey === "approved" && (
                    <span className="text-[11px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1 font-medium">
                      <CheckCircle2 className="size-3" />
                      {approverName ? `Approved by ${approverName}` : "Approved"}
                    </span>
                  )}
                  {statusKey === "rejected" && (
                    <span className="text-[11px] text-rose-600 dark:text-rose-400 flex items-center gap-1 font-medium">
                      <XCircle className="size-3" />
                      {approverName ? `Rejected by ${approverName}` : "Rejected"}
                    </span>
                  )}
                  {statusKey === "pending" && (
                    <span className="text-[11px] text-muted-foreground flex items-center gap-1">
                      <Clock className="size-3 text-amber-500" /> Awaiting Review
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      <LeaveRequestForm open={formOpen} onOpenChange={setFormOpen} onSaved={fetchMine} />
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { toast } from "sonner";
import { Loader2, Plus, Clock, Calendar, ChevronDown, Trash2, Search, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { PageHeader } from "@/components/ui/page-header";
import { TimeLogForm } from "@/components/timesheets/time-log-form";
import { IconAction } from "@/components/ui/icon-action";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface TimeLogRow {
  id: string;
  log_date: string;
  duration: number;
  description: string | null;
  billable: boolean;
  task?: {
    title: string;
    project?: {
      name: string;
    } | null;
  } | null;
}

/** The employee's own logged time, grouped by date with expandable accordions and calendar filtering. */
export default function MyTimesheetsPage() {
  const supabase = createClient();
  const { activeWorkspace, activeMember } = useWorkspace();

  const [logs, setLogs] = useState<TimeLogRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [formOpen, setFormOpen] = useState(false);

  // Filters
  const [selectedDateFilter, setSelectedDateFilter] = useState<string>("");
  const [searchQuery, setSearchQuery] = useState<string>("");

  // Collapsed states
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});

  const fetchMine = useCallback(async () => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("time_logs")
        .select(`
          id, log_date, duration, description, billable,
          task:tasks!time_logs_task_id_fkey ( title, project:projects!tasks_project_id_fkey ( name ) )
        `)
        .eq("workspace_id", activeWorkspace.id)
        .eq("workspace_member_id", activeMember.id)
        .order("log_date", { ascending: false })
        .order("created_at", { ascending: false })
        .limit(200);

      if (error) throw error;
      setLogs((data as any[]) || []);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to load your timesheets");
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id, activeMember?.id]);

  useEffect(() => {
    fetchMine();
  }, [fetchMine]);

  // Group logs by date
  const groupedLogs = useMemo(() => {
    const map = new Map<string, { dateKey: string; displayDate: string; totalHours: number; logs: TimeLogRow[] }>();

    logs.forEach((log) => {
      const dateKey = log.log_date;
      if (!map.has(dateKey)) {
        const [year, month, day] = dateKey.split("-").map(Number);
        const dateObj = new Date(year, month - 1, day);
        const displayDate = dateObj.toLocaleDateString("en-US", {
          weekday: "short",
          month: "short",
          day: "numeric",
          year: "numeric",
        });
        map.set(dateKey, { dateKey, displayDate, totalHours: 0, logs: [] });
      }
      const group = map.get(dateKey)!;
      group.logs.push(log);
      group.totalHours += Number(log.duration || 0);
    });

    return Array.from(map.values());
  }, [logs]);

  // Filter grouped logs
  const filteredGroupedLogs = useMemo(() => {
    return groupedLogs.filter((group) => {
      if (selectedDateFilter && group.dateKey !== selectedDateFilter) {
        return false;
      }
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const matches = group.logs.some(
          (l) =>
            (l.task?.title || "").toLowerCase().includes(q) ||
            (l.description || "").toLowerCase().includes(q)
        );
        if (!matches) return false;
      }
      return true;
    });
  }, [groupedLogs, selectedDateFilter, searchQuery]);

  const toggleDate = (dateKey: string) => {
    setCollapsedDates((prev) => ({
      ...prev,
      [dateKey]: !prev[dateKey],
    }));
  };

  const handleDeleteLog = async (logId: string) => {
    try {
      const { error } = await supabase.from("time_logs").delete().eq("id", logId);
      if (error) throw error;
      toast.success("Time log deleted");
      setLogs((prev) => prev.filter((l) => l.id !== logId));
    } catch (err) {
      toast.error("Failed to delete time log");
    }
  };

  return (
    <div className="space-y-5">
      <PageHeader
        title="My Timesheets"
        description="The time you have logged against projects and tasks."
        actions={
          <IconAction
            label="Log Time"
            icon={<Plus className="size-4" />}
            onClick={() => setFormOpen(true)}
            className="gap-1.5 bg-primary text-primary-foreground hover:bg-primary/90 shadow-xs"
          />
        }
      />

      {/* Filter Toolbar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 bg-card border border-border rounded-xl shadow-xs">
        <div className="flex items-center gap-2.5 flex-wrap">
          <div className="flex items-center gap-2 bg-muted/50 border border-border px-3 py-1.5 rounded-lg text-xs font-semibold">
            <Calendar className="size-4 text-primary shrink-0" />
            <span className="text-foreground">Filter by Date:</span>
            <Input
              type="date"
              value={selectedDateFilter}
              onChange={(e) => setSelectedDateFilter(e.target.value)}
              className="h-7 w-auto bg-background text-xs border-border px-2 py-0 cursor-pointer"
            />
          </div>

          {selectedDateFilter && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => setSelectedDateFilter("")}
              className="h-8 px-2.5 text-xs text-muted-foreground hover:text-foreground gap-1"
            >
              <X className="size-3.5" /> Show All Dates
            </Button>
          )}
        </div>

        <div className="flex items-center gap-2">
          <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-2.5 top-2.5 size-3.5 text-muted-foreground" />
            <Input
              placeholder="Search task title or details..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="h-8 text-xs pl-8 bg-background border-border"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery("")}
                className="absolute right-2.5 top-2.5 text-muted-foreground hover:text-foreground"
              >
                <X className="size-3.5" />
              </button>
            )}
          </div>
        </div>
      </div>

      {loading ? (
        <div className="rounded-xl border border-border bg-card py-16 text-center">
          <Loader2 className="size-6 animate-spin text-primary mx-auto" />
          <p className="text-xs text-muted-foreground mt-2">Loading your timesheets...</p>
        </div>
      ) : filteredGroupedLogs.length === 0 ? (
        <div className="rounded-xl border border-dashed border-border bg-card py-16 text-center">
          <Clock className="size-8 text-muted-foreground/60 mx-auto" />
          <p className="mt-3 text-sm font-semibold text-foreground">
            {selectedDateFilter ? `No time logs found for ${selectedDateFilter}` : "No time logged yet"}
          </p>
          <p className="mt-1 text-xs text-muted-foreground">
            {selectedDateFilter ? 'Click "Show All Dates" or select another date from the calendar.' : 'Click "Log Time" above to add your time entries.'}
          </p>
          {selectedDateFilter && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => setSelectedDateFilter("")}
              className="mt-4 text-xs font-semibold"
            >
              Show All Dates
            </Button>
          )}
        </div>
      ) : (
        <div className="space-y-3">
          {filteredGroupedLogs.map((group) => {
            const isCollapsed = collapsedDates[group.dateKey] === true;

            return (
              <div key={group.dateKey} className="rounded-xl border border-border bg-card overflow-hidden transition-all shadow-xs">

                {/* Daily Header Summary Row */}
                <div
                  onClick={() => toggleDate(group.dateKey)}
                  className="flex items-center justify-between px-5 py-3.5 bg-muted/40 hover:bg-muted/70 transition-colors cursor-pointer select-none border-b border-border/60"
                >
                  <div className="flex items-center gap-3">
                    <button
                      type="button"
                      className="size-6 rounded-md bg-background border border-border flex items-center justify-center text-muted-foreground hover:text-foreground transition-transform"
                    >
                      <ChevronDown className={`size-4 transition-transform duration-200 ${isCollapsed ? "-rotate-90" : "rotate-0"}`} />
                    </button>
                    <div className="flex items-center gap-2.5">
                      <Calendar className="size-4 text-primary" />
                      <span className="text-sm font-bold text-foreground">{group.displayDate}</span>
                      <Badge variant="outline" className="text-[11px] bg-background text-muted-foreground border-border font-medium">
                        {group.logs.length} {group.logs.length === 1 ? "entry" : "entries"}
                      </Badge>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <Badge className="bg-primary/10 text-primary hover:bg-primary/15 border-primary/20 font-mono font-bold px-2.5 py-0.5 text-xs">
                      {group.totalHours.toFixed(1)} hrs logged
                    </Badge>
                  </div>
                </div>

                {/* Expandable Entries List */}
                {!isCollapsed && (
                  <Table>
                    <TableHeader className="bg-muted/10">
                      <TableRow className="border-border hover:bg-transparent">
                        <TableHead className="text-xs text-muted-foreground pl-6">Task / Project</TableHead>
                        <TableHead className="text-xs text-muted-foreground">Description</TableHead>
                        <TableHead className="text-xs text-muted-foreground w-28">Hours</TableHead>
                        <TableHead className="text-xs text-muted-foreground w-24">Billable</TableHead>
                        <TableHead className="text-xs text-muted-foreground w-12 text-right pr-6"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {group.logs.map((log) => (
                        <TableRow key={log.id} className="border-border/60 hover:bg-muted/40 transition-colors">
                          <TableCell className="pl-6 py-3">
                            <div className="flex flex-col">
                              <span className="font-semibold text-foreground text-sm">{log.task?.title || "General / Unassigned"}</span>
                              {log.task?.project && (
                                <span className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5 font-medium">
                                  {log.task.project.name}
                                </span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell className="text-xs text-muted-foreground max-w-sm truncate py-3" title={log.description || ""}>
                            {log.description || <span className="italic opacity-60">No details provided</span>}
                          </TableCell>
                          <TableCell className="font-mono text-sm font-bold text-foreground py-3">
                            {Number(log.duration ?? 0)}h
                          </TableCell>
                          <TableCell className="py-3">
                            {log.billable ? (
                              <Badge variant="outline" className="bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/30 text-[10px] uppercase font-bold">Billable</Badge>
                            ) : (
                              <span className="text-muted-foreground text-xs font-medium">-</span>
                            )}
                          </TableCell>
                          <TableCell className="text-right pr-6 py-3">
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleDeleteLog(log.id);
                              }}
                              className="size-7 text-muted-foreground hover:text-rose-600 hover:bg-rose-500/10 rounded-lg"
                              title="Delete entry"
                            >
                              <Trash2 className="size-3.5" />
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </div>
            );
          })}
        </div>
      )}

      <TimeLogForm open={formOpen} onOpenChange={setFormOpen} onSaved={fetchMine} />
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Folder, File, Upload, Trash2, ArrowLeft } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { toast } from "sonner";
import { Label } from "@/components/ui/label";
import { IconAction } from "@/components/ui/icon-action";
import { EmptyState } from "@/components/ui/empty-state";

export default function MediaPage() {
  const { activeWorkspace } = useWorkspace();
  const [folders, setFolders] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [currentFolder, setCurrentFolder] = useState<any | null>(null);
  const [folderHistory, setFolderHistory] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [newFolderName, setNewFolderName] = useState("");
  const [isFolderDialogOpen, setIsFolderDialogOpen] = useState(false);

  useEffect(() => {
    if (activeWorkspace) {
      fetchMedia();
    }
  }, [activeWorkspace, currentFolder]);

  const fetchMedia = async () => {
    setLoading(true);
    try {
      const parentId = currentFolder ? currentFolder.id : 'null';
      const res = await fetch(`/api/media?workspace_id=${activeWorkspace?.id}&parent_id=${parentId}`);
      if (!res.ok) throw new Error("Failed to load media");
      const data = await res.json();
      setFolders(data.folders || []);
      setFiles(data.files || []);
    } catch (e: any) {
      toast.error(e.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateFolder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFolderName.trim()) return;
    try {
      const parentId = currentFolder ? currentFolder.id : null;
      const res = await fetch('/api/media', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspace_id: activeWorkspace?.id,
          name: newFolderName.trim(),
          parent_id: parentId
        })
      });
      if (!res.ok) throw new Error("Failed to create folder");
      toast.success("Folder created");
      setNewFolderName("");
      setIsFolderDialogOpen(false);
      fetchMedia();
    } catch (e: any) {
      toast.error(e.message);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeWorkspace) return;

    const formData = new FormData();
    formData.append("file", file);
    formData.append("workspace_id", activeWorkspace.id);
    if (currentFolder) {
      formData.append("folder_id", currentFolder.id);
    }

    try {
      const res = await fetch('/api/media/upload', {
        method: 'POST',
        body: formData,
      });
      if (!res.ok) throw new Error("Failed to upload file");
      toast.success("File uploaded");
      fetchMedia();
    } catch (e: any) {
      toast.error(e.message);
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleDeleteFile = async (id: string) => {
    if (!confirm("Delete this file?")) return;
    try {
      const res = await fetch(`/api/media?file_id=${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error("Failed to delete file");
      toast.success("File deleted");
      fetchMedia();
    } catch (e: any) {
      toast.error(e.message);
    }
  };

  const handleDeleteFolder = async (id: string) => {
    if (!confirm("Delete this folder and all its contents?")) return;
    try {
      const res = await fetch(`/api/media?folder_id=${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error("Failed to delete folder");
      toast.success("Folder deleted");
      fetchMedia();
    } catch (e: any) {
      toast.error(e.message);
    }
  };

  const navigateIntoFolder = (folder: any) => {
    setFolderHistory([...folderHistory, currentFolder]);
    setCurrentFolder(folder);
  };

  const navigateUp = () => {
    if (folderHistory.length > 0) {
      const newHistory = [...folderHistory];
      const previous = newHistory.pop();
      setFolderHistory(newHistory);
      setCurrentFolder(previous);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes < 1024) return bytes + ' B';
    else if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    else return (bytes / 1048576).toFixed(1) + ' MB';
  };

  return (
    <div className="flex h-full flex-col p-8 bg-background">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-lg font-semibold tracking-tight text-foreground flex items-center gap-3">
            {currentFolder && (
              <IconAction
                label="Back"
                icon={<ArrowLeft className="w-5 h-5 text-muted-foreground" />}
                variant="ghost"
                onClick={navigateUp}
                className="rounded-full"
              />
            )}
            {currentFolder ? currentFolder.name : "Media Library"}
          </h1>
          <p className="text-muted-foreground mt-1">
            Manage your workspace documents, images, and videos.
          </p>
        </div>
        <div className="flex gap-3">
          <Dialog open={isFolderDialogOpen} onOpenChange={setIsFolderDialogOpen}>
            <DialogTrigger render={<Button variant="outline" className="border-border text-foreground" />}>
                <Folder className="w-4 h-4 mr-2" />
                New Folder
            </DialogTrigger>
            <DialogContent className="bg-card border-border text-foreground">
              <DialogHeader>
                <DialogTitle>Create Folder</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleCreateFolder} className="space-y-4 pt-4">
                <div className="space-y-2">
                  <Label>Folder Name</Label>
                  <Input 
                    value={newFolderName} 
                    onChange={e => setNewFolderName(e.target.value)} 
                    placeholder="e.g. Invoices"
                    className="bg-background border-border"
                    autoFocus
                  />
                </div>
                <Button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-foreground">
                  Create Folder
                </Button>
              </form>
            </DialogContent>
          </Dialog>

          <IconAction label="Upload File" icon={<Upload className="w-4 h-4 " />} onClick={() => fileInputRef.current?.click()}
            className="bg-blue-600 hover:bg-blue-700 text-foreground shadow-lg shadow-blue-500/20" />
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            onChange={handleFileUpload}
          />
        </div>
      </div>

      {loading ? (
        <div className="flex-1 flex items-center justify-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      ) : (
        <div className="flex-1 bg-card/50 border border-border rounded-xl p-6 overflow-y-auto">
          {folders.length === 0 && files.length === 0 ? (
            <EmptyState
              icon={Folder}
              title="This folder is empty"
              description="Upload images, documents, or create sub-folders to organize media."
              action={{
                label: "Upload File",
                onClick: () => fileInputRef.current?.click(),
                icon: Upload,
              }}
            />
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
              {/* Folders */}
              {folders.map(folder => (
                <div 
                  key={folder.id}
                  className="group flex flex-col items-center justify-center p-4 bg-card border border-border hover:border-border rounded-xl cursor-pointer transition-colors relative"
                  onDoubleClick={() => navigateIntoFolder(folder)}
                  onClick={() => navigateIntoFolder(folder)}
                >
                  <Folder className="w-12 h-12 text-blue-500/80 mb-3" fill="currentColor" />
                  <span className="text-sm font-medium text-foreground truncate w-full text-center">
                    {folder.name}
                  </span>
                  
                  <button 
                    onClick={(e) => { e.stopPropagation(); handleDeleteFolder(folder.id); }}
                    className="absolute top-2 right-2 p-1.5 bg-background/80 hover:bg-red-500/20 text-muted-foreground hover:text-red-400 rounded-md opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))}

              {/* Files */}
              {files.map(file => (
                <div 
                  key={file.id}
                  className="group flex flex-col items-center justify-center p-4 bg-card border border-border hover:border-blue-900/30 rounded-xl transition-colors relative"
                >
                  <a href={file.local_path} target="_blank" rel="noreferrer" className="w-full flex flex-col items-center">
                    {file.mime_type?.startsWith('image/') ? (
                      <div className="w-16 h-16 mb-3 rounded-lg overflow-hidden bg-background border border-border">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img src={file.local_path} alt={file.name} className="w-full h-full object-cover" />
                      </div>
                    ) : (
                      <File className="w-12 h-12 text-muted-foreground mb-3" />
                    )}
                    <span className="text-sm font-medium text-foreground truncate w-full text-center hover:text-blue-400 transition-colors">
                      {file.name}
                    </span>
                    <span className="text-xs text-muted-foreground mt-1">
                      {formatSize(file.file_size)}
                    </span>
                  </a>
                  
                  <button 
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleDeleteFile(file.id); }}
                    className="absolute top-2 right-2 p-1.5 bg-background/80 hover:bg-red-500/20 text-muted-foreground hover:text-red-400 rounded-md opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Plus, Loader2, Award } from 'lucide-react';
import { toast } from 'sonner';
import { IconAction } from "@/components/ui/icon-action";

export default function PerformancePage() {
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can('people_manage');

  const [cycles, setCycles] = useState<any[]>([]);
  const [goals, setGoals] = useState<any[]>([]);
  const [promotions, setPromotions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const [cycleModalOpen, setCycleModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const [cycleName, setCycleName] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const fetchPerformanceData = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const res = await fetch(`/api/hr/performance?workspaceId=${activeWorkspace.id}`);
      const json = await res.json();
      setCycles(json.cycles || []);
      setGoals(json.goals || []);
      setPromotions(json.promotions || []);
    } catch {
      toast.error('Failed to load performance data');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id]);

  useEffect(() => {
    fetchPerformanceData();
  }, [fetchPerformanceData]);

  const handleCreateCycle = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!cycleName.trim() || !startDate || !endDate) return;
    if (!activeWorkspace?.id) return;

    setSaving(true);
    try {
      const res = await fetch('/api/hr/performance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'CREATE_CYCLE',
          workspaceId: activeWorkspace.id,
          name: cycleName,
          startDate,
          endDate
        })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success('Performance Review Cycle created');
      setCycleName('');
      setCycleModalOpen(false);
      fetchPerformanceData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to create review cycle');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Performance & Appraisals"
        description="Manage annual/quarterly review cycles, OKRs, employee goals, self-reviews, and promotion history."
        action={
          canManage && (
            <IconAction label="Start Review Cycle" icon={<Plus className="size-4 " />} onClick={() => setCycleModalOpen(true)} className="bg-primary text-primary-foreground" />
          )
        }
      />

      <Tabs defaultValue="cycles" className="space-y-6">
        <TabsList className="bg-muted/50 border border-border">
          <TabsTrigger value="cycles">Review Cycles ({cycles.length})</TabsTrigger>
          <TabsTrigger value="goals">Employee OKRs / Goals ({goals.length})</TabsTrigger>
          <TabsTrigger value="promotions">Promotion History ({promotions.length})</TabsTrigger>
        </TabsList>

        <TabsContent value="cycles">
          {loading ? (
            <div className="flex justify-center py-16">
              <Loader2 className="size-8 animate-spin text-primary" />
            </div>
          ) : cycles.length === 0 ? (
            <Card className="border-border bg-card shadow-sm">
              <CardContent className="flex flex-col items-center justify-center py-16 text-center">
                <Award className="size-12 text-muted-foreground opacity-20 mb-4" />
                <h3 className="text-lg font-semibold text-foreground mb-1">No Review Cycles Defined</h3>
                <p className="text-sm text-muted-foreground max-w-sm mb-6">
                  Start a performance appraisal cycle (e.g. Q1 2027 Review) to collect self-ratings and manager reviews.
                </p>
                {canManage && (
                  <IconAction label="Create Review Cycle" icon={<Plus className="size-4 " />} onClick={() => setCycleModalOpen(true)} />
                )}
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {cycles.map(c => (
                <Card key={c.id} className="border-border bg-card shadow-sm">
                  <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                      <Badge className="bg-emerald-600 text-foreground text-[10px] uppercase">{c.status}</Badge>
                      <span className="text-xs text-muted-foreground">{c.start_date} – {c.end_date}</span>
                    </div>
                    <CardTitle className="text-base font-semibold mt-2">{c.name}</CardTitle>
                  </CardHeader>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="goals">
          {goals.length === 0 && (
            <p className="text-sm text-muted-foreground py-8 text-center">
              No goals yet. Goals are created per review cycle from an employee's review.
            </p>
          )}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {goals.map(g => (
              <Card key={g.id} className="border-border bg-card shadow-sm">
                <CardHeader>
                  <CardTitle className="text-base font-semibold">{g.title}</CardTitle>
                  <CardDescription className="text-xs">{g.description || 'Employee OKR goal.'}</CardDescription>
                </CardHeader>
              </Card>
            ))}
          </div>
        </TabsContent>

        <TabsContent value="promotions">
          <Card className="border-border bg-card shadow-sm">
            <CardHeader>
              <CardTitle className="text-base font-semibold">Promotion History Audit Log</CardTitle>
              <CardDescription>Track designation advancements and salary revisions.</CardDescription>
            </CardHeader>
            <CardContent>
              {promotions.length === 0 ? (
                <p className="text-sm text-muted-foreground py-8 text-center">No promotions recorded yet.</p>
              ) : (
                <div className="space-y-3">
                  {promotions.map(p => (
                    <div key={p.id} className="p-3 border border-border rounded-lg flex items-center justify-between text-xs">
                      <div>
                        <span className="font-semibold text-foreground">{p.oldDesig?.title || 'Previous'} → {p.newDesig?.title || 'New Designation'}</span>
                        <span className="text-muted-foreground block text-[11px] mt-0.5">Reason: {p.promotion_reason}</span>
                      </div>
                      <Badge variant="outline">{p.effective_date}</Badge>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Create Cycle Modal */}
      <Dialog open={cycleModalOpen} onOpenChange={setCycleModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Start Performance Review Cycle</DialogTitle>
            <DialogDescription>Define an appraisal period for employee self-reviews and manager evaluations.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateCycle} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Cycle Name</Label>
              <Input placeholder="e.g. Annual Appraisal 2026" value={cycleName} onChange={e => setCycleName(e.target.value)} required />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Start Date</Label>
                <Input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} required />
              </div>
              <div className="space-y-2">
                <Label>End Date</Label>
                <Input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} required />
              </div>
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setCycleModalOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null} Start Cycle
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

