'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Loader2, Calendar, Briefcase, Plus } from 'lucide-react';
import { PlanningView } from '@/components/projects/planning-view';
import { SprintBurndown } from '@/components/projects/sprint-burndown';
import { ProjectVelocity } from '@/components/projects/project-velocity';
import { ProjectForm } from '@/components/projects/project-form';
import { IconAction } from "@/components/ui/icon-action";

export default function PlanningPage() {
  const supabase = createClient();
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can('projects_manage');

  const [projects, setProjects] = useState<any[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [projectFormOpen, setProjectFormOpen] = useState(false);

  const fetchProjects = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    const { data } = await supabase
      .from('projects')
      .select('id, name, project_type')
      .eq('workspace_id', activeWorkspace.id)
      .order('created_at', { ascending: false });

    const projList = data || [];
    setProjects(projList);

    if (projList.length > 0 && !selectedProjectId) {
      setSelectedProjectId(projList[0].id);
    }

    setLoading(false);
  }, [activeWorkspace?.id, supabase, selectedProjectId]);

  useEffect(() => {
    fetchProjects();
  }, [fetchProjects]);

  const selectedProject = projects.find((p) => p.id === selectedProjectId);
  const isKanban = selectedProject?.project_type?.toUpperCase() === 'KANBAN';
  const isWaterfall = ['WATERFALL', 'BASIC'].includes(selectedProject?.project_type?.toUpperCase() || '');

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <Loader2 className="size-8 animate-spin text-primary" />
        <p className="text-sm text-muted-foreground mt-4">Loading planning data...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PageHeader
        title="Planning Hub"
        description="Plan Sprints, manage Epics, backlog grooming, and track team velocity."
        action={
          <div className="flex items-center gap-3">
            {projects.length > 0 && (
              <Select value={selectedProjectId} onValueChange={(val) => setSelectedProjectId(val || '')}>
                <SelectTrigger className="w-[240px] bg-card border-border">
                  <SelectValue placeholder="Select Project">
                    {selectedProject ? `${selectedProject.name} (${selectedProject.project_type || 'SCRUM'})` : 'Select Project'}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent>
                  {projects.map((p) => (
                    <SelectItem key={p.id} value={p.id} label={p.name}>
                      <div className="flex items-center justify-between w-full gap-2">
                        <span>{p.name}</span>
                        <span className="text-[10px] uppercase font-semibold px-1.5 py-0.5 rounded-none bg-muted text-muted-foreground">
                          {p.project_type || 'SCRUM'}
                        </span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
            {canManage && (
              <IconAction label="New Project" icon={<Plus className="size-4 " />} onClick={() => setProjectFormOpen(true)} className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm" />
            )}
          </div>
        }
      />

      {projects.length === 0 ? (
        <Card className="border-border shadow-sm">
          <CardContent className="flex flex-col items-center justify-center py-16 text-center">
            <Calendar className="size-12 text-muted-foreground opacity-20 mb-4" />
            <h3 className="text-lg font-semibold text-foreground mb-1">No Projects Found</h3>
            <p className="text-sm text-muted-foreground max-w-sm mb-6">
              Create your first project to start planning tasks and workflows.
            </p>
            {canManage && (
              <IconAction label="Create Project" icon={<Plus className="size-4 " />} onClick={() => setProjectFormOpen(true)} />
            )}
          </CardContent>
        </Card>
      ) : selectedProjectId ? (
        isKanban ? (
          <Card className="border-border bg-card shadow-sm">
            <CardContent className="p-8 text-center space-y-4">
              <div className="inline-flex items-center justify-center p-3 rounded-full bg-blue-500/10 text-blue-600 mb-2">
                <Briefcase className="size-8" />
              </div>
              <h3 className="text-xl font-bold text-foreground">{selectedProject?.name} (Kanban Project)</h3>
              <p className="text-muted-foreground max-w-lg mx-auto text-sm">
                Kanban projects operate on continuous flow without fixed Sprints or Sprint Burndown charts. Work items are managed directly on the project&apos;s Kanban Board.
              </p>
              <div className="pt-2">
                <Button onClick={() => window.location.href = `/projects/${selectedProjectId}`} variant="outline" className="border-border">
                  Go to {selectedProject?.name} Kanban Board
                </Button>
              </div>
            </CardContent>
          </Card>
        ) : isWaterfall ? (
          <Card className="border-border bg-card shadow-sm">
            <CardContent className="p-8 text-center space-y-4">
              <div className="inline-flex items-center justify-center p-3 rounded-full bg-amber-500/10 text-amber-600 mb-2">
                <Calendar className="size-8" />
              </div>
              <h3 className="text-xl font-bold text-foreground">{selectedProject?.name} (Waterfall Project)</h3>
              <p className="text-muted-foreground max-w-lg mx-auto text-sm">
                Waterfall projects follow sequential milestones and deliverables using Gantt timelines instead of Sprints.
              </p>
              <div className="pt-2">
                <Button onClick={() => window.location.href = `/projects/${selectedProjectId}`} variant="outline" className="border-border">
                  Go to {selectedProject?.name} Gantt & Milestones
                </Button>
              </div>
            </CardContent>
          </Card>
        ) : (
          /* SCRUM Project */
          <div className="space-y-8">
            <PlanningView projectId={selectedProjectId} canManage={canManage} />

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <SprintBurndown projectId={selectedProjectId} />
              <ProjectVelocity projectId={selectedProjectId} />
            </div>
          </div>
        )
      ) : null}

      <ProjectForm
        open={projectFormOpen}
        onOpenChange={setProjectFormOpen}
        onSaved={fetchProjects}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, use } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  Download,
  ArrowLeft,
  Loader2,
  UserCheck
} from 'lucide-react';
import { toast } from 'sonner';
import { createClient } from '@/lib/supabase/client';
import { useRouter } from 'next/navigation';
import { IconAction } from "@/components/ui/icon-action";

export default function PolicyAuditPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const router = useRouter();
  const { activeWorkspace } = useWorkspace();

  const supabase = createClient();
  const [policy, setPolicy] = useState<any>(null);
  const [memberNames, setMemberNames] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadAuditData() {
      if (!id || !activeWorkspace?.id) return;
      setLoading(true);

      try {
        const res = await fetch(`/api/hr/policies/${id}`);
        const json = await res.json();
        if (json.policy) {
          setPolicy(json.policy);
        }

        const { data: members } = await supabase
          .from('workspace_members')
          .select('id, user_id')
          .eq('workspace_id', activeWorkspace.id);
        const userIds = (members || []).map((m) => m.user_id);
        const { data: profs } = userIds.length
          ? await supabase.from('profiles').select('user_id, full_name').in('user_id', userIds)
          : { data: [] as { user_id: string; full_name: string | null }[] };
        const byUser: Record<string, string> = {};
        (profs || []).forEach((p) => { byUser[p.user_id] = p.full_name || '—'; });
        const names: Record<string, string> = {};
        (members || []).forEach((m) => { names[m.id] = byUser[m.user_id] || '—'; });
        setMemberNames(names);
      } catch {
        toast.error('Failed to load compliance audit logs');
      } finally {
        setLoading(false);
      }
    }

    loadAuditData();
  }, [id, activeWorkspace?.id]);

  const handleExportCSV = () => {
    if (!activeWorkspace?.id || !id) return;
    window.open(`/api/hr/policies/export?workspaceId=${activeWorkspace.id}&policyId=${id}`, '_blank');
  };

  if (loading) {
    return (
      <div className="flex justify-center py-20">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!policy) {
    return (
      <div className="text-center py-16">
        <p className="text-muted-foreground">Audit log not found.</p>
        <Button onClick={() => router.push('/policies')} className="mt-4">
          Return to Policies
        </Button>
      </div>
    );
  }

  const acknowledgements = policy.acknowledgements || [];
  const versions = policy.versions || [];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <IconAction label="Back to Policies" icon={<ArrowLeft className="size-4 " />} variant="ghost" onClick={() => router.push('/policies')} className="text-muted-foreground" />
        <IconAction label="Export Audit CSV" icon={<Download className="size-4 " />} variant="outline" onClick={handleExportCSV} className="bg-card" />
      </div>

      <PageHeader
        title={`Audit Trail: ${policy.title}`}
        description="Immutable read-only compliance evidence, cryptographic SHA-256 signatures, and employee sign-off timestamps."
      />

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium">Total Signatures Captured</CardDescription>
            <CardTitle className="text-2xl font-bold text-emerald-500">{acknowledgements.length}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Court-admissible digital sign-offs
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium">Policy Versions</CardDescription>
            <CardTitle className="text-2xl font-bold">{versions.length}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Immutable document history snapshots
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium">Governance Mode</CardDescription>
            <CardTitle className="text-2xl font-bold text-blue-500">Read-Only Audit</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Zero edit permissions for audit integrity
          </CardContent>
        </Card>
      </div>

      {/* Acknowledgements Table */}
      <Card className="border-border bg-card shadow-sm">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <UserCheck className="size-4 text-primary" /> Employee Sign-Off Log
          </CardTitle>
          <CardDescription>
            Verified legal sign-offs with typed name, IP address, and SHA-256 cryptographic content hashes.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {acknowledgements.length === 0 ? (
            <p className="text-sm text-muted-foreground py-8 text-center">No employee signatures recorded yet.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead className="bg-muted/50 border-b border-border text-muted-foreground font-medium">
                  <tr>
                    <th className="p-3">Employee</th>
                    <th className="p-3">Version</th>
                    <th className="p-3">Status</th>
                    <th className="p-3">Typed Legal Signature</th>
                    <th className="p-3">SHA-256 Content Hash</th>
                    <th className="p-3">IP Address</th>
                    <th className="p-3">Timestamp</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {acknowledgements.map((a: any) => (
                    <tr key={a.id} className="hover:bg-muted/20">
                      <td className="p-3 font-medium text-foreground">
                        {memberNames[a.workspace_member_id] || '—'}
                      </td>
                      <td className="p-3">
                        <Badge variant="outline" className="text-[10px]">v{a.version_number}</Badge>
                      </td>
                      <td className="p-3">
                        <Badge variant={a.status === 'ACTIVE' ? 'default' : 'secondary'} className={a.status === 'ACTIVE' ? 'bg-emerald-600 text-foreground' : ''}>
                          {a.status}
                        </Badge>
                      </td>
                      <td className="p-3 font-mono font-medium">{a.signature_value}</td>
                      <td className="p-3 font-mono text-[10px] opacity-70 truncate max-w-[140px]" title={a.content_hash}>
                        {a.content_hash}
                      </td>
                      <td className="p-3 font-mono text-[11px]">{a.ip_address || '—'}</td>
                      <td className="p-3 text-muted-foreground">{new Date(a.acknowledged_at).toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, use } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import {
  ShieldCheck,
  CheckCircle2,
  Loader2,
  ArrowLeft,
  FileCode,
  Sparkles
} from 'lucide-react';
import { toast } from 'sonner';
import { useRouter } from 'next/navigation';
import { markdownToHtml } from '@/lib/markdown-utils';
import { IntegrationShareButtons } from '@/components/integrations/integration-share-buttons';
import { IconAction } from "@/components/ui/icon-action";

export default function PolicyReadPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const router = useRouter();
  const { activeWorkspace, activeMember } = useWorkspace();

  const [policy, setPolicy] = useState<any>(null);
  const [activeVersion, setActiveVersion] = useState<any>(null);
  const [existingAck, setExistingAck] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Scroll verification & signature state
  const scrollRef = useRef<HTMLDivElement>(null);
  const [scrolledToBottom, setScrolledToBottom] = useState(false);
  // Real reading time for the acknowledgement record.
  const readStartRef = useRef<number>(Date.now());

  // Content shorter than the scroll box never fires a scroll event —
  // unlock immediately when there is nothing to scroll.
  useEffect(() => {
    const el = scrollRef.current;
    if (el && el.scrollHeight <= el.clientHeight + 30) {
      setScrolledToBottom(true);
    }
  }, [loading, activeVersion?.id]);
  const [agreed, setAgreed] = useState(false);
  const [typedName, setTypedName] = useState('');
  const [signing, setSigning] = useState(false);

  useEffect(() => {
    async function loadPolicyData() {
      if (!id || !activeWorkspace?.id) return;
      setLoading(true);

      try {
        const res = await fetch(`/api/hr/policies/${id}`);
        const json = await res.json();
        if (json.policy) {
          const p = json.policy;
          setPolicy(p);

          const verList = p.versions || [];
          const maxVerNum = verList.reduce((max: number, v: any) => Math.max(max, v.version_number || 1), 0);
          const publishedVer = verList.find((v: any) => v.version_number === maxVerNum);
          setActiveVersion(publishedVer);

          // Check if already signed
          if (activeMember?.id && publishedVer) {
            const acks = p.acknowledgements || [];
            const ack = acks.find((a: any) => a.version_id === publishedVer.id && a.workspace_member_id === activeMember.id && a.status === 'ACTIVE');
            setExistingAck(ack || null);
          }
        }
      } catch {
        toast.error('Failed to load policy document');
      } finally {
        setLoading(false);
      }
    }

    loadPolicyData();
  }, [id, activeWorkspace?.id, activeMember?.id]);

  // Scroll verification handler
  const handleScroll = () => {
    if (!scrollRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = scrollRef.current;
    if (scrollTop + clientHeight >= scrollHeight - 30) {
      setScrolledToBottom(true);
    }
  };

  const handleSignPolicy = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!typedName.trim()) {
      toast.error('Please type your full legal name');
      return;
    }
    if (!activeWorkspace?.id || !activeMember?.id || !activeVersion) return;

    setSigning(true);
    try {
      const res = await fetch(`/api/hr/policies/${id}/acknowledge`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspaceId: activeWorkspace.id,
          versionId: activeVersion.id,
          versionNumber: activeVersion.version_number,
          memberId: activeMember.id,
          signatureValue: typedName.trim(),
          signatureType: 'TYPED_NAME',
          readTimeSeconds: Math.max(1, Math.round((Date.now() - readStartRef.current) / 1000)),
          readTillBottom: scrolledToBottom
        })
      });

      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success('Policy document legally signed and recorded!');
      setExistingAck(json.acknowledgement);
    } catch (err: any) {
      toast.error(err.message || 'Failed to record signature');
    } finally {
      setSigning(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-20">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!policy || !activeVersion) {
    return (
      <div className="text-center py-16">
        <p className="text-muted-foreground">Policy document not found or unpublished.</p>
        <Button onClick={() => router.push('/policies')} className="mt-4">
          Return to Policies
        </Button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <IconAction label="Back to Policies" icon={<ArrowLeft className="size-4 " />} variant="ghost" onClick={() => router.push('/policies')} className="text-muted-foreground" />
        <div className="flex items-center gap-2">
          {activeWorkspace?.id && (
            <IntegrationShareButtons
              workspaceId={activeWorkspace.id}
              documentTitle={`Policy Document: ${policy.title}`}
              documentSummary={`Policy document version v${activeVersion.version_number}`}
            />
          )}
          <Badge variant="outline" className="text-xs bg-card">
            {policy.category.replace(/_/g, ' ')}
          </Badge>
          <Badge className="bg-emerald-600 text-foreground">
            Version v{activeVersion.version_number}
          </Badge>
        </div>
      </div>

      {/* Policy Reader Header */}
      <Card className="border-border bg-card shadow-sm">
        <CardHeader>
          <div className="flex items-start justify-between">
            <div>
              <CardTitle className="text-xl font-bold text-foreground">{policy.title}</CardTitle>
              <CardDescription className="text-xs mt-1 flex items-center gap-4">
                <span>Published: {new Date(activeVersion.published_at || policy.updated_at).toLocaleDateString()}</span>
                <span>Effective: {new Date(activeVersion.effective_at || policy.created_at).toLocaleDateString()}</span>
              </CardDescription>
            </div>
            <div className="text-right">
              <span className="text-[11px] font-mono text-muted-foreground flex items-center gap-1 justify-end">
                <FileCode className="size-3 text-primary" /> SHA-256 Hash
              </span>
              <span className="text-[10px] font-mono opacity-70 block truncate max-w-[180px]">
                {activeVersion.content_hash || 'SHA-256 Pending'}
              </span>
            </div>
          </div>

          {activeVersion.change_summary && (
            <div className="mt-3 p-2.5 rounded-none bg-primary/5 border border-primary/20 text-xs flex items-center gap-2 text-primary">
              <Sparkles className="size-4 shrink-0" />
              <span><strong>What&apos;s New in v{activeVersion.version_number}:</strong> {activeVersion.change_summary}</span>
            </div>
          )}
        </CardHeader>

        {/* Policy Text Reader Scroll Box */}
        <CardContent>
          <div
            ref={scrollRef}
            onScroll={handleScroll}
            className="border border-border rounded-lg p-6 max-h-[450px] overflow-y-auto bg-muted/10 font-sans text-sm leading-relaxed space-y-4 shadow-inner"
          >
            {activeVersion.content ? (
              <div
                className="rich-text max-w-none text-sm leading-relaxed space-y-3"
                dangerouslySetInnerHTML={{ __html: markdownToHtml(activeVersion.content) }}
              />
            ) : (
              <p className="text-muted-foreground italic">No document content available.</p>
            )}
            <div className="pt-8 text-center text-xs text-muted-foreground border-t border-border/40">
              --- END OF POLICY DOCUMENT ---
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Signature Box / Status */}
      {existingAck ? (
        <Card className="border-emerald-500/30 bg-emerald-500/5 shadow-sm">
          <CardContent className="py-6 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="size-10 rounded-full bg-emerald-500/20 text-emerald-600 flex items-center justify-center">
                <CheckCircle2 className="size-6" />
              </div>
              <div>
                <h4 className="text-sm font-semibold text-emerald-900 dark:text-emerald-200">
                  Policy Legally Signed & Acknowledged
                </h4>
                <p className="text-xs text-muted-foreground mt-0.5">
                  Signed by <strong>{existingAck.signature_value}</strong> on {new Date(existingAck.acknowledged_at).toLocaleString()}
                </p>
                <span className="text-[10px] font-mono text-muted-foreground opacity-80 block mt-1">
                  SHA-256 Proof: {existingAck.content_hash} • IP: {existingAck.ip_address}
                </span>
              </div>
            </div>
            <Badge variant="outline" className="border-emerald-500 text-emerald-600 bg-emerald-50 dark:bg-emerald-950">
              Active Signature
            </Badge>
          </CardContent>
        </Card>
      ) : activeVersion.mandatory ? (
        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <ShieldCheck className="size-4 text-primary" /> Legal Digital Signature & Sign-Off
            </CardTitle>
            <CardDescription>
              {scrolledToBottom
                ? 'Document review verified. Type your full legal name below to complete sign-off.'
                : 'Please scroll through the entire document above to unlock the sign-off box.'}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSignPolicy} className="space-y-4">
              <div className="p-3.5 rounded-lg border border-primary/20 bg-primary/5 space-y-2">
                <p className="text-xs font-semibold text-primary uppercase tracking-wider">
                  Employee Read & Sign Legal Attestation
                </p>
                <div className="flex items-start space-x-2.5">
                  <Checkbox
                    id="agree-terms"
                    checked={agreed}
                    onCheckedChange={(c) => setAgreed(!!c)}
                    disabled={!scrolledToBottom}
                    className="mt-0.5"
                  />
                  <label
                    htmlFor="agree-terms"
                    className={`text-xs leading-relaxed ${scrolledToBottom ? 'cursor-pointer text-foreground font-medium' : 'text-muted-foreground'}`}
                  >
                    <strong>Formal Attestation:</strong> I, {typedName.trim() || '[Employee Name]'}, hereby formally attest and declare under penalty of company disciplinary policy that I have thoroughly read, fully understood, and voluntarily agree to comply with all terms, standards, and obligations outlined in this document.
                  </label>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 pt-1">
                <div className="sm:col-span-2 space-y-1">
                  <Input
                    placeholder="Type your full legal name to attest & sign (e.g. John Doe)"
                    value={typedName}
                    onChange={(e) => setTypedName(e.target.value)}
                    disabled={!scrolledToBottom || !agreed}
                    className="bg-popover"
                  />
                  <p className="text-[10px] text-muted-foreground">Your typed full legal name serves as a binding digital signature with SHA-256 audit proof.</p>
                </div>
                <Button
                  type="submit"
                  disabled={!scrolledToBottom || !agreed || !typedName.trim() || signing}
                  className="bg-primary text-primary-foreground h-10"
                >
                  {signing ? <Loader2 className="size-4 animate-spin mr-2" /> : <ShieldCheck className="size-4 mr-2" />}
                  Attest & Sign Policy
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      ) : null}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Shield,
  Plus,
  Download,
  Search,
  Eye,
  FileCode2,
  Send,
  Loader2,
  Layers,
  Trash2
} from 'lucide-react';
import { toast } from 'sonner';
import { useRouter, useSearchParams } from 'next/navigation';
import { ComplianceBanner } from '@/components/policies/compliance-banner';
import { PolicyEditorModal } from '@/components/policies/policy-editor-modal';
import { IconAction } from "@/components/ui/icon-action";

export default function PoliciesDashboardPage() {
  const router = useRouter();
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can('people_manage');

  const supabase = createClient();
  const [policies, setPolicies] = useState<any[]>([]);
  // Real compliance rate: ACTIVE sign-offs vs (published mandatory
  // policies x workspace members). Replaces a hardcoded "96.4%".
  const [complianceRate, setComplianceRate] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [activeTab, setActiveTab] = useState('ALL');

  const [editorOpen, setEditorOpen] = useState(false);
  const [editingPolicyId, setEditingPolicyId] = useState<string | null>(null);

  // Deep link: /policies?edit=<policyId> opens the editor directly
  // (the Employee Handbook's "Manage" buttons land here).
  const searchParams = useSearchParams();
  useEffect(() => {
    const editId = searchParams.get('edit');
    if (editId) {
      setEditingPolicyId(editId);
      setEditorOpen(true);
    }
  }, [searchParams]);

  const fetchPolicies = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      let url = `/api/hr/policies?workspaceId=${activeWorkspace.id}`;
      if (search.trim()) url += `&search=${encodeURIComponent(search.trim())}`;

      const res = await fetch(url);
      const json = await res.json();
      setPolicies(json.policies || []);

      const published = (json.policies || []).filter(
        (p: { status: string; versions?: { mandatory?: boolean }[] }) =>
          p.status === 'PUBLISHED' && (p.versions || []).some((v) => v.mandatory)
      );
      if (published.length === 0) {
        setComplianceRate(null);
      } else {
        const [{ count: memberCount }, { count: ackCount }] = await Promise.all([
          supabase
            .from('workspace_members')
            .select('id', { count: 'exact', head: true })
            .eq('workspace_id', activeWorkspace.id),
          supabase
            .from('hr_policy_acknowledgements')
            .select('id', { count: 'exact', head: true })
            .eq('workspace_id', activeWorkspace.id)
            .eq('status', 'ACTIVE')
            .in('policy_id', published.map((p: { id: string }) => p.id)),
        ]);
        const denominator = (memberCount ?? 0) * published.length;
        setComplianceRate(denominator > 0 ? Math.min(100, ((ackCount ?? 0) / denominator) * 100) : null);
      }
    } catch (err) {
      console.error(err);
      toast.error('Failed to load HR policies');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, search]);

  useEffect(() => {
    fetchPolicies();
  }, [fetchPolicies]);

  // Compute Executive Compliance Metrics
  const totalPolicies = policies.length;
  const publishedPolicies = policies.filter(p => p.status === 'PUBLISHED');
  const draftPolicies = policies.filter(p => p.status === 'DRAFT');

  const handleApprove = async (id: string) => {
    try {
      const res = await fetch(`/api/hr/policies/${id}/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ comments: 'Approved by HR Admin' })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success(`Policy v${json.publishedVersion} approved and published with SHA-256 hash!`);
      fetchPolicies();
    } catch (err: any) {
      toast.error(err.message || 'Failed to approve policy');
    }
  };

  const handleExportCSV = () => {
    if (!activeWorkspace?.id) return;
    window.open(`/api/hr/policies/export?workspaceId=${activeWorkspace.id}`, '_blank');
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this policy?')) return;
    try {
      const res = await fetch(`/api/hr/policies/${id}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to delete policy');

      toast.success('Policy deleted successfully!');
      fetchPolicies();
    } catch (err: any) {
      toast.error(err.message || 'Failed to delete policy');
    }
  };

  const filteredPolicies = policies.filter(p => {
    if (activeTab === 'ALL') return true;
    if (activeTab === 'PUBLISHED') return p.status === 'PUBLISHED';
    if (activeTab === 'DRAFT') return p.status === 'DRAFT';
    return p.category === activeTab;
  });

  return (
    <div className="space-y-6">
      <ComplianceBanner />

      <PageHeader
        title="HR Policies & Legal Compliance"
        description="Manage company policies, Terms & Conditions, versioning, SHA-256 legal sign-offs, and compliance audits."
        action={
          <div className="flex items-center gap-3">
            {canManage && (
              <IconAction label="Export Audit CSV" icon={<Download className="size-4 " />} variant="outline" onClick={handleExportCSV} className="bg-card" />
            )}
            {canManage && (
              <IconAction label="Create Policy" icon={<Plus className="size-4 " />} onClick={() => { setEditingPolicyId(null); setEditorOpen(true); }} className="bg-primary text-primary-foreground shadow-sm" />
            )}
          </div>
        }
      />

      {/* Executive Compliance Metrics Overview */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium">Compliance Rate</CardDescription>
            <CardTitle className="text-2xl font-bold text-emerald-500">
              {complianceRate === null ? '—' : `${complianceRate.toFixed(1)}%`}
            </CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Targeted employee digital sign-offs
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium">Total Documents</CardDescription>
            <CardTitle className="text-2xl font-bold">{totalPolicies}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            {publishedPolicies.length} Published • {draftPolicies.length} Drafts
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium">Active Handbook Rules</CardDescription>
            <CardTitle className="text-2xl font-bold text-blue-500">{publishedPolicies.length}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Enforced with SHA-256 legal hash
          </CardContent>
        </Card>

        <Card className="border-border bg-card shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs font-medium">Pending Approvals</CardDescription>
            <CardTitle className="text-2xl font-bold text-amber-500">{draftPolicies.length}</CardTitle>
          </CardHeader>
          <CardContent className="text-xs text-muted-foreground">
            Drafts requiring HR review & publish
          </CardContent>
        </Card>
      </div>

      {/* Search & Tabs */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full sm:w-auto">
          <TabsList className="bg-muted/50 border border-border">
            <TabsTrigger value="ALL">All Policies</TabsTrigger>
            <TabsTrigger value="PUBLISHED">Published</TabsTrigger>
            <TabsTrigger value="DRAFT">Drafts</TabsTrigger>
            <TabsTrigger value="CODE_OF_CONDUCT">Code of Conduct</TabsTrigger>
            <TabsTrigger value="LEAVE">Leave Rules</TabsTrigger>
          </TabsList>
        </Tabs>

        <div className="relative w-full sm:w-[260px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input
            placeholder="Search policies..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 bg-card border-border"
          />
        </div>
      </div>

      {/* Policy Documents List */}
      {loading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="size-8 animate-spin text-primary" />
        </div>
      ) : filteredPolicies.length === 0 ? (
        <Card className="border-border bg-card shadow-sm">
          <CardContent className="flex flex-col items-center justify-center py-16 text-center">
            <Shield className="size-12 text-muted-foreground opacity-20 mb-4" />
            <h3 className="text-lg font-semibold text-foreground mb-1">No HR Policies Found</h3>
            <p className="text-sm text-muted-foreground max-w-sm mb-6">
              Create your company&apos;s Code of Conduct, Leave Rules, and Terms & Conditions for employee digital sign-off.
            </p>
            {canManage && (
              <IconAction label="Create First Policy" icon={<Plus className="size-4 " />} onClick={() => { setEditingPolicyId(null); setEditorOpen(true); }} />
            )}
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredPolicies.map((p) => {
            const versions = p.versions || [];
            const maxVerNum = versions.reduce((max: number, v: any) => Math.max(max, v.version_number || 1), 0);
            const latestVer = versions.find((v: any) => v.version_number === maxVerNum);

            return (
              <Card key={p.id} className="border-border bg-card shadow-sm hover:border-primary/50 transition-colors flex flex-col justify-between">
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between gap-2 mb-2">
                    <Badge variant="outline" className="text-[10px] uppercase tracking-wider bg-secondary/50">
                      {p.category.replace(/_/g, ' ')}
                    </Badge>
                    <Badge
                      variant={p.status === 'PUBLISHED' ? 'default' : 'secondary'}
                      className={p.status === 'PUBLISHED' ? 'bg-emerald-600 hover:bg-emerald-700 text-foreground' : ''}
                    >
                      {p.status === 'PUBLISHED' ? `v${maxVerNum} Published` : 'Draft'}
                    </Badge>
                  </div>
                  <CardTitle className="text-base font-semibold line-clamp-1">{p.title}</CardTitle>
                  <CardDescription className="text-xs line-clamp-2 mt-1">
                    {latestVer?.change_summary || 'Company HR policy document for employee sign-off.'}
                  </CardDescription>
                </CardHeader>

                <CardContent className="pt-0 space-y-4">
                  {p.linked_module && p.linked_module !== 'NONE' && (
                    <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground bg-muted/30 px-2.5 py-1 rounded-none border border-border">
                      <Layers className="size-3.5 text-primary" />
                      <span>Linked Setting: <strong className="text-foreground">{p.linked_module}</strong></span>
                    </div>
                  )}

                  <div className="flex items-center justify-between text-xs text-muted-foreground pt-2 border-t border-border/50">
                    <span>{latestVer?.mandatory ? '🔒 Mandatory Sign-Off' : '📖 Optional Reading'}</span>
                    <span>Updated {new Date(p.updated_at).toLocaleDateString()}</span>
                  </div>

                  <div className="flex items-center justify-end gap-2 pt-2">
                    {p.status === 'PUBLISHED' ? (
                      <>
                        <IconAction label="Audit Trail" icon={<FileCode2 className="size-3.5 " />} variant="outline"
                          onClick={() => router.push(`/policies/${p.id}/audit`)}
                          className="text-xs" />
                        <IconAction label="Read & Sign" icon={<Eye className="size-3.5 " />} onClick={() => router.push(`/policies/${p.id}/read`)}
                          className="text-xs bg-primary text-primary-foreground" />
                      </>
                    ) : (
                      <>
                        {canManage && (
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => { setEditingPolicyId(p.id); setEditorOpen(true); }}
                            className="text-xs"
                          >
                            Edit Draft
                          </Button>
                        )}
                        {canManage && (
                          <IconAction label="Approve & Publish" icon={<Send className="size-3.5 " />} onClick={() => handleApprove(p.id)}
                            className="text-xs bg-emerald-600 hover:bg-emerald-700 text-foreground" />
                        )}
                        {canManage && (
                          <IconAction label="Delete" icon={<Trash2 className="size-3.5 " />} variant="ghost"
                            onClick={() => handleDelete(p.id)}
                            className="text-xs text-destructive hover:text-destructive hover:bg-destructive/10" />
                        )}
                      </>
                    )}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Editor Modal */}
      <PolicyEditorModal
        open={editorOpen}
        onOpenChange={(open) => {
          setEditorOpen(open);
          if (!open && searchParams.get('edit')) {
            router.replace('/policies');
          }
        }}
        policyId={editingPolicyId}
        onSaved={fetchPolicies}
      />
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { RequireModule } from "@/components/auth/require-module";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { 
  ShoppingCart, 
  Search, 
  Trash2, 
  Plus, 
  Minus, 
  Landmark,
  PauseCircle,
  PlayCircle,
  X,
  Calculator,
  Split
} from "lucide-react";
import { toast } from "sonner";
import { extractCleanSku } from "@/lib/commerce/barcode-utils";
import { IconAction } from "@/components/ui/icon-action";

interface CartItem {
  product_id: string;
  name: string;
  sku: string;
  barcode?: string;
  selling_price: number;
  tax_rate: number;
  quantity: number;
  serial_numbers?: string[];
  imei_numbers?: string[];
}

export default function POSTerminalPage() {
  return (
    <RequireModule module="retail">
      <POSTerminalPageContent />
    </RequireModule>
  );
}

function POSTerminalPageContent() {
  const { activeWorkspace } = useWorkspace();
  const [query, setQuery] = useState("");
  const [products, setProducts] = useState<any[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [, setLoadingProducts] = useState(false);
  
  // Customer & Pricing State
  const [customerType, setCustomerType] = useState<"RETAIL" | "WHOLESALE" | "DISTRIBUTOR">("RETAIL");
  const [customerMobile, setCustomerMobile] = useState("");
  const [customerGstin] = useState("");
  const [promoCode, setPromoCode] = useState("");

  // Payment States
  const [isGstBill] = useState(true);
  const [selectedPayment, setSelectedPayment] = useState<"CASH" | "UPI" | "CARD" | "SPLIT">("CASH");
  const [upiBankAccount, setUpiBankAccount] = useState("");
  const [bankAccountsList, setBankAccountsList] = useState<any[]>([]);
  
  // Split Payment Amounts
  const [splitCashAmount, setSplitCashAmount] = useState<number>(0);
  const [splitUpiAmount, setSplitUpiAmount] = useState<number>(0);

  const [discountAmount, setDiscountAmount] = useState<number>(0);
  const [cashReceived, setCashReceived] = useState<number>(0);
  const [checkoutLoading, setCheckoutLoading] = useState(false);

  // Held Bills Drawer State
  const [heldBills, setHeldBills] = useState<any[]>([]);
  const [showHeldDrawer, setShowHeldDrawer] = useState(false);

  // Cash Denomination Drawer State for Z-Report Shift Closing
  const [showShiftCloseModal, setShowShiftCloseModal] = useState(false);
  const [denominations, setDenominations] = useState({
    "2000": 0, "500": 0, "200": 0, "100": 0, "50": 0, "20": 0, "10": 0, "coins": 0
  });

  // Serial/IMEI Modal State
  const [showSerialModal, setShowSerialModal] = useState(false);
  const [selectedItemForSerial, setSelectedItemForSerial] = useState<CartItem | null>(null);
  const [serialInput, setSerialInput] = useState("");

  const searchInputRef = useRef<HTMLInputElement>(null);

  // Auto-focus search input
  useEffect(() => {
    searchInputRef.current?.focus();

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "F2") {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Fetch products and load dynamic bank accounts
  useEffect(() => {
    if (!activeWorkspace?.id) return;

    // Load custom bank accounts
    const saved = localStorage.getItem(`retail_bank_accounts_${activeWorkspace.id}`);
    if (saved) {
      const parsed = JSON.parse(saved);
      setBankAccountsList(parsed);
      if (parsed.length > 0) {
        setUpiBankAccount(`${parsed[0].name} (vpa: ${parsed[0].vpa})`);
      }
    } else {
      const defaultAccounts = [
        { id: "1", name: "HDFC Bank Primary", vpa: "store@hdfc" },
        { id: "2", name: "ICICI Bank Current", vpa: "store@icici" },
        { id: "3", name: "SBI Business Account", vpa: "store@sbi" },
        { id: "4", name: "Store Static QR Code", vpa: "merchant@paytm" }
      ];
      setBankAccountsList(defaultAccounts);
      setUpiBankAccount("HDFC Bank Primary (vpa: store@hdfc)");
    }

    const fetchProducts = async () => {
      setLoadingProducts(true);
      const cleanSearchQuery = extractCleanSku(query);
      try {
        const res = await fetch(`/api/commerce/products?workspace_id=${activeWorkspace.id}&query=${encodeURIComponent(cleanSearchQuery)}`);
        const contentType = res.headers.get("content-type") || "";
        if (!res.ok || !contentType.includes("application/json")) {
          console.error("Fetch products failed with status:", res.status);
          return;
        }
        const json = await res.json();
        if (json.products) {
          setProducts(json.products);

          if (cleanSearchQuery && json.products.length === 1 && (json.products[0].barcode === cleanSearchQuery || json.products[0].sku === cleanSearchQuery)) {
            addToCart(json.products[0]);
            setQuery("");
          }
        }
      } catch (err: any) {
        console.error("Error fetching products:", err);
      } finally {
        setLoadingProducts(false);
      }
    };

    const timer = setTimeout(fetchProducts, 300);
    return () => clearTimeout(timer);
  }, [query, activeWorkspace?.id]);

  const addToCart = (product: any) => {
    setCart((prevCart) => {
      const existing = prevCart.find((item) => item.product_id === product.id);
      if (existing) {
        return prevCart.map((item) =>
          item.product_id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [
        ...prevCart,
        {
          product_id: product.id,
          name: product.name,
          sku: product.sku,
          barcode: product.barcode,
          selling_price: Number(product.selling_price || 0),
          tax_rate: Number(product.tax_rate || 0),
          quantity: 1,
          serial_numbers: [],
          imei_numbers: [],
        },
      ];
    });
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart((prevCart) =>
      prevCart
        .map((item) => {
          if (item.product_id === productId) {
            const newQty = item.quantity + delta;
            return newQty > 0 ? { ...item, quantity: newQty } : null;
          }
          return item;
        })
        .filter(Boolean) as CartItem[]
    );
  };

  const removeFromCart = (productId: string) => {
    setCart((prevCart) => prevCart.filter((item) => item.product_id !== productId));
  };

  // Hold Current Bill
  const handleHoldBill = () => {
    if (cart.length === 0) {
      toast.error("Cart is empty");
      return;
    }
    const newHold = {
      id: Date.now().toString(),
      hold_number: `HOLD-${Date.now().toString().slice(-4)}`,
      items: cart,
      customer_type: customerType,
      created_at: new Date().toLocaleTimeString(),
    };
    setHeldBills((prev) => [newHold, ...prev]);
    setCart([]);
    toast.success(`Bill ${newHold.hold_number} placed on hold!`);
  };

  // Recall Held Bill
  const handleRecallBill = (held: any) => {
    setCart(held.items);
    setHeldBills((prev) => prev.filter((h) => h.id !== held.id));
    setShowHeldDrawer(false);
    toast.success(`Recalled ${held.hold_number}`);
  };

  // Add Serial/IMEI to Item
  const handleSaveSerial = () => {
    if (!selectedItemForSerial || !serialInput.trim()) return;
    setCart((prev) =>
      prev.map((item) =>
        item.product_id === selectedItemForSerial.product_id
          ? { ...item, serial_numbers: [...(item.serial_numbers || []), serialInput.trim()] }
          : item
      )
    );
    setSerialInput("");
    setShowSerialModal(false);
    toast.success("Serial Number saved to item");
  };

  // Calculations
  const subtotal = cart.reduce((acc, item) => acc + item.quantity * item.selling_price, 0);
  const taxTotal = isGstBill
    ? cart.reduce((acc, item) => acc + (item.quantity * item.selling_price * item.tax_rate) / 100, 0)
    : 0;
  const grandTotal = Math.max(0, subtotal + taxTotal - discountAmount);
  const changeReturned = Math.max(0, cashReceived - grandTotal);

  // Auto-set Split UPI Amount when Split Cash changes
  useEffect(() => {
    if (selectedPayment === "SPLIT") {
      const remaining = Math.max(0, grandTotal - splitCashAmount);
      setSplitUpiAmount(remaining);
    }
  }, [splitCashAmount, grandTotal, selectedPayment]);

  // Shift Close Cash Counter Total
  const totalCountedCash = 
    denominations["2000"] * 2000 +
    denominations["500"] * 500 +
    denominations["200"] * 200 +
    denominations["100"] * 100 +
    denominations["50"] * 50 +
    denominations["20"] * 20 +
    denominations["10"] * 10 +
    denominations["coins"];

  const handleCheckout = async () => {
    if (cart.length === 0) {
      toast.error("Cart is empty");
      return;
    }

    if (!activeWorkspace?.id) return;

    let paymentBreakdown: any[] = [];
    if (selectedPayment === "SPLIT") {
      if (splitCashAmount + splitUpiAmount < grandTotal) {
        toast.error("Split payment amounts do not cover the Grand Total!");
        return;
      }
      paymentBreakdown = [
        { mode: "CASH", amount: splitCashAmount },
        // The engine expects `bank_account_id` (a commerce_bank_accounts
        // id); it validates and falls back to the default bank ledger
        // when this is a legacy free-text label.
        { mode: "UPI", amount: splitUpiAmount, bank_account_id: upiBankAccount },
      ];
    } else if (selectedPayment === "UPI") {
      paymentBreakdown = [
        { mode: "UPI", amount: grandTotal, bank_account_id: upiBankAccount },
      ];
    } else {
      paymentBreakdown = [
        { mode: selectedPayment, amount: grandTotal },
      ];
    }

    setCheckoutLoading(true);
    try {
      const res = await fetch("/api/commerce/pos/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          workspace_id: activeWorkspace.id,
          customer_type: customerType,
          customer_mobile: customerMobile || undefined,
          customer_gstin: customerGstin || undefined,
          is_gst_bill: isGstBill,
          payment_method: selectedPayment,
          payment_breakdown: paymentBreakdown,
          discount_amount: Number(discountAmount || 0),
          cash_received: selectedPayment === "CASH" ? Number(cashReceived || 0) : grandTotal,
          change_returned: selectedPayment === "CASH" ? changeReturned : 0,
          promo_code_applied: promoCode || undefined,
          items: cart,
        }),
      });

      const contentType = res.headers.get("content-type") || "";
      let json: any = {};
      if (contentType.includes("application/json")) {
        json = await res.json();
      }

      if (!res.ok) {
        throw new Error(json.error || `Checkout endpoint error (${res.status}). Please restart dev server if route was recently added.`);
      }

      toast.success(`Order #${json.order?.order_number || "completed"} completed & Journal posted!`);
      setCart([]);
      setDiscountAmount(0);
      setCashReceived(0);
      setSplitCashAmount(0);
      setSplitUpiAmount(0);
      setPromoCode("");
    } catch (err: any) {
      toast.error(err.message || "Checkout failed");
    } finally {
      setCheckoutLoading(false);
    }
  };

  return (
    <div className="flex h-[calc(100vh-4rem)] flex-col lg:flex-row gap-4 p-4 bg-background text-foreground overflow-hidden">
      {/* LEFT: Product Catalog & Search */}
      <div className="flex-1 flex flex-col gap-4 min-w-0">
        {/* Search Bar & Actions */}
        <div className="flex flex-wrap sm:flex-nowrap items-center gap-2 bg-card/90 p-2.5 sm:p-3.5 rounded-2xl border border-border backdrop-blur-md shadow-lg">
          <div className="relative flex-1 min-w-[180px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              ref={searchInputRef}
              type="text"
              placeholder="Scan Barcode or Search (F2)..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="pl-9 h-10 sm:h-11 bg-background border-border text-foreground rounded-xl focus:border-[#00aef0] font-medium text-xs sm:text-sm"
            />
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <IconAction label="Held Bills" icon={<PauseCircle className="h-4 w-4" />} variant="outline"
              onClick={() => setShowHeldDrawer(true)}
              className="h-10 sm:h-11 border-border bg-background text-amber-400 hover:bg-card gap-1.5 rounded-xl px-2.5 text-xs" />
            <IconAction label="Z-Report" icon={<Calculator className="h-4 w-4" />} variant="outline"
              onClick={() => setShowShiftCloseModal(true)}
              className="h-10 sm:h-11 border-border bg-background text-emerald-400 hover:bg-card gap-1.5 rounded-xl px-2.5 text-xs" />
          </div>
        </div>

        {/* Customer Type Selector */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between bg-card/50 p-2.5 rounded-xl border border-border/80 gap-2.5">
          <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
            <span className="text-xs text-muted-foreground font-bold shrink-0 pr-1">Customer Type:</span>
            {(["RETAIL", "WHOLESALE", "DISTRIBUTOR"] as const).map((type) => (
              <button
                key={type}
                onClick={() => setCustomerType(type)}
                className={`px-2.5 py-1 rounded-lg text-xs font-bold transition-all whitespace-nowrap shrink-0 ${
                  customerType === type
                    ? "bg-[#00aef0] text-foreground shadow-md"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                {type}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2 w-full sm:w-auto">
            <Input
              type="text"
              placeholder="Customer Mobile #"
              value={customerMobile}
              onChange={(e) => setCustomerMobile(e.target.value)}
              className="h-8 w-full sm:w-36 bg-background border-border text-xs text-foreground rounded-lg"
            />
          </div>
        </div>

        {/* Product Grid */}
        <div className="flex-1 overflow-y-auto grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 pr-1 content-start">
          {products.map((product) => (
            <div
              key={product.id}
              onClick={() => addToCart(product)}
              className="bg-card/60 border border-border hover:border-[#00aef0]/50 rounded-2xl p-3 flex flex-col justify-between cursor-pointer transition-all hover:scale-[1.02] shadow-md group"
            >
              <div>
                <div className="text-xs font-bold text-foreground group-hover:text-[#00aef0] transition-colors line-clamp-2">
                  {product.name}
                </div>
                <div className="text-[11px] font-mono text-muted-foreground mt-1">SKU: {product.sku}</div>
              </div>
              <div className="flex flex-col gap-1.5 mt-3 pt-2 border-t border-border/60">
                <div className="flex items-center justify-between">
                  <div className="flex flex-col">
                    {product.mrp && Number(product.mrp) > Number(product.selling_price) && (
                      <span className="text-[10px] text-muted-foreground line-through">
                        ₹{Number(product.mrp).toFixed(2)}
                      </span>
                    )}
                    <span className="text-xs font-extrabold text-[#00aef0]">
                      ₹{Number(product.selling_price).toFixed(2)}
                    </span>
                  </div>
                  <span className="text-[10px] bg-muted text-muted-foreground px-1.5 py-0.5 rounded-none font-mono">
                    {product.base_unit || "PCS"}
                  </span>
                </div>
                {product.mrp && Number(product.mrp) > Number(product.selling_price) && (
                  <div className="flex items-center justify-between text-[10px]">
                    <span className="text-emerald-400 font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded-lg border border-emerald-500/20">
                      {Math.round(((Number(product.mrp) - Number(product.selling_price)) / Number(product.mrp)) * 100)}% OFF
                    </span>
                    <span className="text-muted-foreground">
                      Save ₹{(Number(product.mrp) - Number(product.selling_price)).toFixed(0)}
                    </span>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT: Current Cart Order Panel & Checkout */}
      <div className="w-full lg:w-96 bg-card/90 border border-border rounded-3xl p-4 flex flex-col justify-between shadow-2xl backdrop-blur-md">
        <div className="space-y-3 overflow-hidden flex flex-col h-full">
          <div className="flex items-center justify-between border-b border-border pb-3">
            <h2 className="font-extrabold text-foreground text-base flex items-center gap-2">
              <ShoppingCart className="h-5 w-5 text-[#00aef0]" />
              Current Order
            </h2>
            <button
              onClick={handleHoldBill}
              className="text-amber-400 hover:text-amber-300 text-xs font-bold flex items-center gap-1 bg-amber-500/10 px-2.5 py-1 rounded-lg border border-amber-500/20"
            >
              <PauseCircle className="h-3.5 w-3.5" /> Hold Bill
            </button>
          </div>

          {/* Cart Items List */}
          <div className="flex-1 overflow-y-auto space-y-2 pr-1">
            {cart.length === 0 ? (
              <div className="text-center py-16 text-muted-foreground text-xs">
                Cart is empty. Scan barcode or click product to add.
              </div>
            ) : (
              cart.map((item) => (
                <div key={item.product_id} className="bg-background p-2.5 rounded-xl border border-border/80 flex items-center justify-between">
                  <div className="flex-1 pr-2">
                    <div className="font-bold text-foreground text-xs line-clamp-1">{item.name}</div>
                    <div className="text-[11px] text-[#00aef0] font-semibold mt-0.5">
                      ₹{item.selling_price.toFixed(2)} × {item.quantity} = ₹{(item.selling_price * item.quantity).toFixed(2)}
                    </div>
                    {item.serial_numbers && item.serial_numbers.length > 0 && (
                      <div className="text-[10px] text-emerald-400 font-mono">
                        S/N: {item.serial_numbers.join(", ")}
                      </div>
                    )}
                  </div>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => {
                        setSelectedItemForSerial(item);
                        setShowSerialModal(true);
                      }}
                      className="p-1 text-muted-foreground hover:text-foreground text-[10px] font-mono bg-card border border-border rounded-none"
                    >
                      +S/N
                    </button>
                    <button onClick={() => updateQuantity(item.product_id, -1)} className="p-1 text-muted-foreground hover:text-foreground">
                      <Minus className="h-3 w-3" />
                    </button>
                    <span className="font-bold text-foreground w-5 text-center">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.product_id, 1)} className="p-1 text-muted-foreground hover:text-foreground">
                      <Plus className="h-3 w-3" />
                    </button>
                    <button onClick={() => removeFromCart(item.product_id)} className="p-1 text-rose-400 hover:text-rose-300 ml-1">
                      <Trash2 className="h-3 w-3" />
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Totals & Payment Actions */}
        <div className="border-t border-border pt-3 space-y-3 mt-2">
          <div className="space-y-1.5 text-xs text-muted-foreground">
            <div className="flex justify-between">
              <span>Subtotal</span>
              <span className="text-foreground font-semibold">₹{subtotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between">
              <span>GST Total</span>
              <span className="text-foreground font-semibold">₹{taxTotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-emerald-400">
              <span>Discount</span>
              <span>-₹{Number(discountAmount || 0).toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-base font-extrabold text-foreground pt-2 border-t border-border">
              <span>Grand Total</span>
              <span className="text-[#00aef0]">₹{grandTotal.toFixed(2)}</span>
            </div>
          </div>

          {/* Payment Method Selector Grid */}
          <div className="grid grid-cols-4 gap-1 pt-1">
            {(["CASH", "UPI", "CARD", "SPLIT"] as const).map((method) => (
              <button
                key={method}
                onClick={() => setSelectedPayment(method)}
                className={`py-2 rounded-xl text-[11px] font-bold transition-all flex items-center justify-center gap-1 ${
                  selectedPayment === method
                    ? "bg-[#00aef0] text-foreground shadow-lg"
                    : "bg-background text-muted-foreground border border-border"
                }`}
              >
                {method === "SPLIT" && <Split className="h-3 w-3" />}
                {method}
              </button>
            ))}
          </div>

          {/* UPI Bank Account Selection */}
          {(selectedPayment === "UPI" || selectedPayment === "SPLIT") && (
            <div className="bg-background p-2.5 rounded-xl border border-border space-y-1">
              <Label className="text-[11px] text-[#00aef0] font-bold flex items-center gap-1">
                <Landmark className="h-3.5 w-3.5" /> Destination Bank Account / UPI Handle
              </Label>
              <select
                value={upiBankAccount}
                onChange={(e) => setUpiBankAccount(e.target.value)}
                className="w-full bg-card border border-border text-foreground rounded-lg text-xs h-8 px-2"
              >
                {bankAccountsList.map((acc) => (
                  <option key={acc.id} value={`${acc.name} (vpa: ${acc.vpa})`}>
                    {acc.name} ({acc.vpa})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Split Payment Controls */}
          {selectedPayment === "SPLIT" && (
            <div className="bg-background p-2.5 rounded-xl border border-border space-y-2">
              <div className="flex justify-between items-center text-xs font-bold text-foreground">
                <span>Split Cash & UPI Payment</span>
                <span className="text-[#00aef0]">Total: ₹{grandTotal.toFixed(2)}</span>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <Label className="text-[10px] text-muted-foreground">Cash Amount (₹)</Label>
                  <Input
                    type="number"
                    value={splitCashAmount || ""}
                    onChange={(e) => setSplitCashAmount(Number(e.target.value || 0))}
                    placeholder="0.00"
                    className="bg-card border-border text-foreground text-xs h-8 font-bold"
                  />
                </div>
                <div>
                  <Label className="text-[10px] text-muted-foreground">UPI Amount (₹)</Label>
                  <Input
                    type="number"
                    value={splitUpiAmount || ""}
                    onChange={(e) => setSplitUpiAmount(Number(e.target.value || 0))}
                    placeholder="0.00"
                    className="bg-card border-border text-emerald-400 text-xs h-8 font-bold"
                  />
                </div>
              </div>
            </div>
          )}

          <Button
            onClick={handleCheckout}
            disabled={checkoutLoading || cart.length === 0}
            className="w-full bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold h-12 rounded-xl shadow-lg shadow-[#00aef0]/20 text-sm"
          >
            {checkoutLoading ? "Processing..." : `Complete Checkout (₹${grandTotal.toFixed(2)})`}
          </Button>
        </div>
      </div>

      {/* Held Bills Drawer Modal */}
      {showHeldDrawer && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-3xl max-w-md w-full p-6 space-y-4 shadow-2xl">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <PauseCircle className="h-5 w-5 text-amber-400" />
                Held Bills Queue
              </h2>
              <button onClick={() => setShowHeldDrawer(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-2 max-h-80 overflow-y-auto">
              {heldBills.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground text-xs">
                  No bills currently on hold.
                </div>
              ) : (
                heldBills.map((held) => (
                  <div key={held.id} className="p-3 bg-background border border-border rounded-xl flex items-center justify-between">
                    <div>
                      <div className="font-bold text-foreground text-xs">{held.hold_number}</div>
                      <div className="text-[11px] text-muted-foreground">{held.items.length} item(s) • Held at {held.created_at}</div>
                    </div>
                    <IconAction label="Recall" icon={<PlayCircle className="h-3.5 w-3.5" />} onClick={() => handleRecallBill(held)} className="bg-amber-500 hover:bg-amber-600 text-foreground font-bold text-xs rounded-lg gap-1" />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* Cash Denomination Shift Closing Modal */}
      {showShiftCloseModal && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-3xl max-w-md w-full p-6 space-y-4 shadow-2xl">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                <Calculator className="h-5 w-5 text-emerald-400" />
                Day-End Z-Report Cash Counter
              </h2>
              <button onClick={() => setShowShiftCloseModal(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-3 text-xs">
              {(["500", "200", "100", "50", "20", "10", "coins"] as const).map((denom) => (
                <div key={denom} className="space-y-1">
                  <Label className="text-[11px] text-muted-foreground uppercase">₹{denom} Count</Label>
                  <Input
                    type="number"
                    value={denominations[denom]}
                    onChange={(e) => setDenominations((prev) => ({ ...prev, [denom]: Number(e.target.value || 0) }))}
                    className="bg-background border-border text-foreground text-xs h-9"
                  />
                </div>
              ))}
            </div>

            <div className="pt-3 border-t border-border flex items-center justify-between">
              <div>
                <div className="text-xs text-muted-foreground">Total Counted Cash</div>
                <div className="text-xl font-extrabold text-emerald-400">₹{totalCountedCash.toFixed(2)}</div>
              </div>
              <Button onClick={() => { toast.success("Shift closed & Z-Report generated!"); setShowShiftCloseModal(false); }} className="bg-emerald-600 hover:bg-emerald-500 text-foreground font-bold rounded-xl h-10 px-4 text-xs">
                Close Shift
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Serial Number Modal */}
      {showSerialModal && selectedItemForSerial && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-3xl max-w-sm w-full p-6 space-y-4 shadow-2xl">
            <div className="flex items-center justify-between border-b border-border pb-3">
              <h2 className="text-sm font-bold text-foreground">Add Serial / IMEI Number</h2>
              <button onClick={() => setShowSerialModal(false)} className="text-muted-foreground hover:text-foreground">
                <X className="h-4 w-4" />
              </button>
            </div>
            <div className="space-y-2">
              <Label className="text-xs text-muted-foreground">{selectedItemForSerial.name}</Label>
              <Input
                type="text"
                placeholder="Scan or enter Serial # / IMEI"
                value={serialInput}
                onChange={(e) => setSerialInput(e.target.value)}
                className="bg-background border-border text-foreground text-xs h-10 font-mono"
              />
            </div>
            <Button onClick={handleSaveSerial} className="w-full bg-[#00aef0] text-foreground font-bold h-10 text-xs rounded-xl">
              Save Serial Number
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

