                </TabsContent>
              </div>
            </Tabs>
          );
        }

        // Default: SCRUM
        return (
          <Tabs defaultValue="overview" className="w-full">
            <TabsList className="bg-muted w-full justify-start overflow-x-auto h-auto p-1 rounded-lg">
              <TabsTrigger value="overview" className="py-2">Overview</TabsTrigger>
