              <span>Go-live support, listing corrections, maintenance assistance, regular marketplace updates, and monthly digital marketing content publishing.</span>
            </li>
          </ul>
        </div>

        {/* Section 5: Terms & Conditions */}
        <div className="space-y-3">
          <h3 className="font-bold text-sm uppercase text-[#00aef0] tracking-wider border-b border-border/40 pb-1">
            5. TERMS &amp; CONDITIONS
          </h3>
          <div className="space-y-2 text-xs text-muted-foreground leading-relaxed">
            <p>
              <strong className="text-foreground">• Scope of Services:</strong> The quotation covers onboarding to Amazon &amp; Blinkit, listing setup, website development (up to 5 pages), ongoing marketplace management, and monthly digital marketing services as specifically mentioned above.
            </p>
            <p>
              <strong className="text-foreground">• Client Dependencies:</strong> Timely completion depends on the client providing required documents, product details, images, approvals, GST/KYC information, and access credentials on time.
            </p>
            <p>
              <strong className="text-foreground">• Payment Terms:</strong> 50% advance to initiate the project and 50% before final handover of the initial setup. Monthly maintenance and digital marketing charges are payable in advance at the start of each billing cycle.
            </p>
            <p>
              <strong className="text-foreground">• Digital Marketing Deliverables:</strong> Monthly deliverables include 20–24 creatives (16–20 static posts and 4 reels) with captions, hashtags, and scheduling as per an approved content calendar.
            </p>
            <p>
              <strong className="text-foreground">• Validity &amp; Jurisdiction:</strong> This quotation is valid for 15 days from the date of issue. Any disputes shall be subject to the jurisdiction of courts in Belagavi, Karnataka.
            </p>
          </div>
        </div>

        {/* Section 6: Acceptance & Dual Signature Block */}
        <div className="space-y-4 pt-4 border-t border-border/60">
          <p className="text-xs text-muted-foreground font-semibold">
            Acceptance: By signing below or issuing a Purchase Order, the client accepts this proposal and the commercial terms mentioned above.
          </p>

          <div className="grid grid-cols-2 gap-8 text-xs pt-2">
            <div className="border border-border/80 rounded-sm p-4 h-32 flex flex-col justify-between">
              <span className="font-bold text-foreground">
                For {clientCompanySafe || clientNameSafe}
              </span>
              <span className="text-muted-foreground text-[11px]">
                (Signature &amp; Stamp)
              </span>
            </div>

            <div className="border border-border/80 rounded-sm p-4 h-32 flex flex-col justify-between">
              <span className="font-bold text-foreground">
                For {workspace?.company_name || "Daylink Tech Labs Pvt Ltd"}
              </span>
              <span className="text-muted-foreground text-[11px]">
                (Signature &amp; Stamp)
              </span>
            </div>
          </div>
        </div>

        {/* Document Footer */}
        <div className="border-t border-border/60 pt-4 text-center text-[10px] text-muted-foreground">
          {workspace?.company_name || "Daylink Tech Labs Pvt. Ltd."} | Commercial Proposal — {clientCompanySafe || clientNameSafe} | Confidential
        </div>
      </Card>
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  Calculator,
  Plus,
  Search,
  Edit,
  Eye,
  Copy,
  Trash2,
  Loader2,
} from "lucide-react";

import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/hooks/use-auth";
import { useWorkspace } from "@/hooks/use-workspace";
import { formatCurrency } from "@/lib/currency";
import type { Quotation } from "@/types";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { IconAction } from "@/components/ui/icon-action";
import { TableSkeleton } from "@/components/ui/table-skeleton";

export default function QuotationsPage() {
  const router = useRouter();
  const supabase = createClient();
  const { user, accountId } = useAuth();
  const { activeWorkspace, defaultCurrency } = useWorkspace();
  const workspaceId = activeWorkspace?.id || accountId;

  const [quotes, setQuotes] = useState<Quotation[]>([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("All");

  const fetchQuotations = async () => {
    if (!workspaceId) return;
    try {
      const { data, error } = await supabase
        .from("quotations")
        .select(`
          *,
          client:contacts(id, name, email, phone, company),
          deal:deals(id, title, value)
        `)
        .eq("workspace_id", workspaceId)
        .order("updated_at", { ascending: false });

      if (error) throw error;
      setQuotes(data || []);
    } catch (err: any) {
      console.error("Error fetching quotations:", err.message);
      toast.error("Failed to load quotations");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (workspaceId) {
      fetchQuotations();
    }
  }, [workspaceId]);

  // Handle New Quotation Generation
  const handleCreateQuotation = async () => {
    if (!workspaceId || !user?.id) return;
    setCreating(true);

    try {
      // 1. Fetch default terms
      const { data: wsData } = await supabase
        .from("workspaces")
        .select("default_quotation_terms")
        .eq("id", workspaceId)
        .single();

      const defaultTerms = wsData?.default_quotation_terms || "";

      // 2. Generate Quotation ID (QT-YYYYMMDD-XXXX)
      const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, "");
      const randomSuffix = Math.floor(1000 + Math.random() * 9000);
      const generatedId = `QT-${dateStr}-${randomSuffix}`;

      // 3. Set validity date to 30 days from now
      const validUntilDate = new Date();
      validUntilDate.setDate(validUntilDate.getDate() + 30);
      const validUntilStr = validUntilDate.toISOString().split("T")[0];

      // 4. Create the draft quote record
      const { data: quote, error } = await supabase
        .from("quotations")
        .insert({
          workspace_id: workspaceId,
          user_id: user.id,
          quotation_id: generatedId,
          document_title: "COMMERCIAL PROPOSAL",
          valid_until: validUntilStr,
          status: "Draft",
          notes_terms: defaultTerms,
          version: 1,
          total_one_time: 0,
          total_recurring: 0,
        })
        .select()
        .single();

      if (error) throw error;

      toast.success("Draft quotation created");
      router.push(`/quotations/${quote.id}/edit`);
    } catch (err: any) {
      toast.error(err.message || "Failed to start quotation");
    } finally {
      setCreating(false);
    }
  };

  // Handle Version Duplication
  const handleDuplicateVersion = async (quote: Quotation) => {
    if (!workspaceId || !user?.id) return;
    const confirmMsg = `Create a new version of ${quote.quotation_id}? This will increment version to v${quote.version + 1} and copy all line items.`;
    if (!confirm(confirmMsg)) return;

    setLoading(true);
    try {
      // 1. Create new quote version
      const nextVersion = quote.version + 1;
      const { data: newQuote, error: qErr } = await supabase
        .from("quotations")
        .insert({
          workspace_id: workspaceId,
          user_id: user.id,
          quotation_id: quote.quotation_id,
          deal_id: quote.deal_id,
          client_id: quote.client_id,
          document_title: quote.document_title,
          document_subtitle: quote.document_subtitle,
          date_created: new Date().toISOString().split("T")[0],
          valid_until: quote.valid_until,
          status: "Draft", // New version starts as Draft
          notes_terms: quote.notes_terms,
          payment_terms: quote.payment_terms,
          total_one_time: quote.total_one_time,
          total_recurring: quote.total_recurring,
          version: nextVersion,
        })
        .select()
        .single();

      if (qErr) throw qErr;

      // 2. Fetch sections + line items of the current version to copy
      const { data: sections, error: sErr } = await supabase
        .from("quotation_sections")
        .select("*, quotation_line_items(*)")
        .eq("quotation_id", quote.id)
        .order("position", { ascending: true });

      if (sErr) throw sErr;

      if (sections && sections.length > 0) {
        for (const sec of sections) {
          // Clone Section
          const { data: newSec, error: secErr } = await supabase
            .from("quotation_sections")
            .insert({
              workspace_id: workspaceId,
              quotation_id: newQuote.id,
              title: sec.title,
              position: sec.position,
            })
            .select()
            .single();

          if (secErr) throw secErr;

          // Clone Line Items inside this Section
          if (sec.quotation_line_items && sec.quotation_line_items.length > 0) {
            const clonedItems = sec.quotation_line_items.map((item: any) => ({
              workspace_id: workspaceId,
              section_id: newSec.id,
              name: item.name,
              description: item.description,
              price: item.price,
              pricing_type: item.pricing_type,
              qty: item.qty,
              is_recommended: item.is_recommended,
              is_free: item.is_free,
              free_condition_note: item.free_condition_note,
              source: item.source,
              position: item.position,
            }));

            const { error: itemsErr } = await supabase
              .from("quotation_line_items")
              .insert(clonedItems);

            if (itemsErr) throw itemsErr;
          }
        }
      }

      toast.success(`Created version v${nextVersion} (Draft)`);
      fetchQuotations();
      router.push(`/quotations/${newQuote.id}/edit`);
    } catch (err: any) {
      toast.error(err.message || "Failed to clone quotation version");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteQuotation = async (id: string) => {
    if (!confirm("Are you sure you want to delete this quotation version? This cannot be undone.")) return;
    try {
      const { error } = await supabase
        .from("quotations")
        .delete()
        .eq("id", id);

      if (error) throw error;
      toast.success("Quotation deleted");
      fetchQuotations();
    } catch {
      toast.error("Failed to delete quotation");
    }
  };

  // Filtered Quotations
  const filteredQuotes = useMemo(() => {
    return quotes.filter((q) => {
      const clientName = q.client?.name || "";
      const clientCompany = q.client?.company || "";
      const matchesSearch =
        q.quotation_id.toLowerCase().includes(search.toLowerCase()) ||
        q.document_title.toLowerCase().includes(search.toLowerCase()) ||
        clientName.toLowerCase().includes(search.toLowerCase()) ||
        clientCompany.toLowerCase().includes(search.toLowerCase());

      const matchesStatus = statusFilter === "All" || q.status === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [quotes, search, statusFilter]);

  const statusColors: Record<string, string> = {
    Draft: "bg-zinc-500/10 text-zinc-400 border-zinc-500/20",
    Sent: "bg-blue-500/10 text-blue-400 border-blue-500/20",
    Viewed: "bg-purple-500/10 text-purple-400 border-purple-500/20",
    Accepted: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
    Rejected: "bg-red-500/10 text-red-400 border-red-500/20",
    Expired: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  };

  return (
    <div className="space-y-6 p-6 animate-in fade-in-50 duration-200">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-lg font-semibold tracking-tight text-foreground flex items-center gap-2">
            <Calculator className="size-6 text-primary" />
            Quotations
          </h1>
          <p className="text-sm text-muted-foreground">
            Create, brand, edit, and send commercial proposals to your CRM contacts.
          </p>
        </div>
        <Button
          onClick={handleCreateQuotation}
          disabled={creating || loading}
          className="bg-primary text-primary-foreground hover:bg-primary/90"
        >
          {creating ? (
            <>
              <Loader2 className="mr-1.5 size-4 animate-spin" /> Creating...
            </>
          ) : (
            <>
              <Plus className="mr-1.5 size-4" /> New Quotation
            </>
          )}
        </Button>
      </div>

      {/* Summary Cards */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card className="border-border bg-card">
          <CardHeader className="pb-2">
            <CardTitle className="text-xs font-medium text-muted-foreground uppercase">
              Total Drafts & Sent
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-foreground">
              {quotes.filter((q) => ["Draft", "Sent"].includes(q.status)).length}
            </div>
            <p className="text-xs text-muted-foreground mt-1">Pending approval</p>
          </CardContent>
        </Card>
        <Card className="border-border bg-card">
          <CardHeader className="pb-2">
            <CardTitle className="text-xs font-medium text-muted-foreground uppercase">
              Accepted Proposals
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-emerald-400">
              {quotes.filter((q) => q.status === "Accepted").length}
            </div>
            <p className="text-xs text-muted-foreground mt-1">Converted successfully</p>
          </CardContent>
        </Card>
        <Card className="border-border bg-card">
          <CardHeader className="pb-2">
            <CardTitle className="text-xs font-medium text-muted-foreground uppercase">
              Won Revenue (One-Time)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-foreground">
              {formatCurrency(
                quotes
                  .filter((q) => q.status === "Accepted")
                  .reduce((sum, q) => sum + Number(q.total_one_time), 0),
                defaultCurrency,
                { decimals: 2 },
              )}
            </div>
            <p className="text-xs text-muted-foreground mt-1">Active client accounts</p>
          </CardContent>
        </Card>
      </div>

      {/* Main Board */}
      <Card className="border-border bg-card">
        <CardHeader className="pb-3 flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-border/40">
          <div>
            <CardTitle className="text-sm font-semibold">All Proposals</CardTitle>
            <CardDescription className="text-xs">
              Manage version iterations and preview client-facing assets.
            </CardDescription>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {/* Tabs */}
            <div className="flex items-center rounded-lg border border-border/60 bg-muted p-0.5">
              {["All", "Draft", "Sent", "Accepted", "Rejected"].map((status) => (
                <button
                  key={status}
                  onClick={() => setStatusFilter(status)}
                  className={`px-3 py-1 text-xs font-medium rounded-md transition-colors ${
                    statusFilter === status
                      ? "bg-popover text-foreground shadow-sm"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  {status}
                </button>
              ))}
            </div>

            {/* Search */}
            <div className="relative">
              <Search className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" />
              <Input
                placeholder="Search Client or ID..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-8 bg-muted border-border h-9 w-48 text-sm"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm border-collapse">
                <thead>
                  <tr className="border-b border-border bg-muted/30 text-xs font-medium text-muted-foreground uppercase">
                    <th className="p-4">Quotation ID</th>
                    <th className="p-4">Client</th>
                    <th className="p-4 hidden md:table-cell">Proposal Title</th>
                    <th className="p-4 hidden sm:table-cell">Valid Until</th>
                    <th className="p-4">Totals</th>
                    <th className="p-4">Status</th>
                    <th className="p-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  <TableSkeleton columns={7} rows={5} />
                </tbody>
              </table>
            </div>
          ) : filteredQuotes.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground text-sm border-0">
              No quotations matching these criteria.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm border-collapse">
                <thead>
                  <tr className="border-b border-border bg-muted/30 text-xs font-medium text-muted-foreground uppercase">
                    <th className="p-4">Quotation ID</th>
                    <th className="p-4">Client</th>
                    <th className="p-4 hidden md:table-cell">Proposal Title</th>
                    <th className="p-4 hidden sm:table-cell">Valid Until</th>
                    <th className="p-4">Totals</th>
                    <th className="p-4">Status</th>
                    <th className="p-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/60">
                  {filteredQuotes.map((q) => (
                    <tr key={q.id} className="hover:bg-muted/10 transition-colors">
                      <td className="p-4 font-mono font-bold text-foreground">
                        {q.quotation_id}
                        <span className="ml-1.5 inline-flex items-center rounded-md bg-muted px-1.5 py-0.5 text-xs font-medium text-muted-foreground border border-border/50">
                          v{q.version}
                        </span>
                      </td>
                      <td className="p-4">
                        {q.client ? (
                          <div>
                            <p className="font-semibold text-foreground">{q.client.name}</p>
                            {q.client.company && (
                              <p className="text-xs text-muted-foreground">{q.client.company}</p>
                            )}
                          </div>
                        ) : (
                          <span className="text-muted-foreground text-xs">Unassigned</span>
                        )}
                      </td>
                      <td className="p-4 text-muted-foreground font-medium max-w-xs truncate hidden md:table-cell">
                        {q.document_title}
                        {q.document_subtitle && (
                          <span className="block text-xs font-normal">{q.document_subtitle}</span>
                        )}
                      </td>
                      <td className="p-4 text-muted-foreground font-medium hidden sm:table-cell">
                        {new Date(q.valid_until).toLocaleDateString()}
                      </td>
                      <td className="p-4 font-medium text-foreground">
                        <div>
                          <p className="text-xs text-muted-foreground">One-time:</p>
                          <p className="font-bold">{formatCurrency(Number(q.total_one_time), defaultCurrency, { decimals: 2 })}</p>
                          {Number(q.total_recurring) > 0 && (
                            <p className="text-[10px] text-primary">
                              Recurring: {formatCurrency(Number(q.total_recurring), defaultCurrency)}/mo
                            </p>
                          )}
                        </div>
                      </td>
                      <td className="p-4">
                        <span className={`inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-semibold ${statusColors[q.status]}`}>
                          {q.status}
                        </span>
                      </td>
                      <td className="p-4 text-right">
                        <div className="flex items-center justify-end gap-1.5">
                          <IconAction
                            label="Preview Proposal"
                            icon={<Eye className="size-4" />}
                            variant="ghost"
                            onClick={() => router.push(`/quotations/${q.id}/preview`)}
                            className="h-8 w-8 text-muted-foreground hover:text-foreground"
                          />
                          <IconAction
                            label="Edit Proposal"
                            icon={<Edit className="size-4" />}
                            variant="ghost"
                            onClick={() => router.push(`/quotations/${q.id}/edit`)}
                            className="h-8 w-8 text-muted-foreground hover:text-foreground"
                          />
                          <IconAction
                            label="Create New Version"
                            icon={<Copy className="size-4" />}
                            variant="ghost"
                            onClick={() => handleDuplicateVersion(q)}
                            className="h-8 w-8 text-muted-foreground hover:text-primary"
                          />
                          <IconAction
                            label="Delete Proposal"
                            icon={<Trash2 className="size-4" />}
                            variant="ghost"
                            onClick={() => handleDeleteQuotation(q.id)}
                            className="h-8 w-8 text-muted-foreground hover:text-red-400"
                          />
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Plus, Loader2, UserCheck, ChevronRight } from 'lucide-react';
import { toast } from 'sonner';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { IconAction } from "@/components/ui/icon-action";

const STAGES = ['APPLIED', 'SCREENING', 'INTERVIEW', 'OFFER', 'HIRED', 'REJECTED'];

export default function RecruitmentPage() {
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can('people_manage');

  const [jobs, setJobs] = useState<any[]>([]);
  const [, setCandidates] = useState<any[]>([]);
  const [applications, setApplications] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const [jobModalOpen, setJobModalOpen] = useState(false);
  const [candModalOpen, setCandModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  // Job Form
  const [jobTitle, setJobTitle] = useState('');
  const [jobLocation, setJobLocation] = useState('Remote / Hybrid');

  // Candidate Form
  const [selectedJobId, setSelectedJobId] = useState('');
  const [candName, setCandName] = useState('');
  const [candEmail, setCandEmail] = useState('');
  const [candPhone, setCandPhone] = useState('');

  const fetchRecruitment = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const res = await fetch(`/api/hr/recruitment?workspaceId=${activeWorkspace.id}`);
      const json = await res.json();
      setJobs(json.jobs || []);
      setCandidates(json.candidates || []);
      setApplications(json.applications || []);
      if (json.jobs?.length > 0 && !selectedJobId) {
        setSelectedJobId(json.jobs[0].id);
      }
    } catch {
      toast.error('Failed to load recruitment data');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, selectedJobId]);

  useEffect(() => {
    fetchRecruitment();
  }, [fetchRecruitment]);

  const handleCreateJob = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!jobTitle.trim() || !activeWorkspace?.id) return;
    setSaving(true);
    try {
      const res = await fetch('/api/hr/recruitment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'CREATE_JOB',
          workspaceId: activeWorkspace.id,
          title: jobTitle,
          location: jobLocation
        })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success('Job Opening created');
      setJobTitle('');
      setJobModalOpen(false);
      fetchRecruitment();
    } catch (err: any) {
      toast.error(err.message || 'Failed to create job');
    } finally {
      setSaving(false);
    }
  };

  const handleAddCandidate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id) return;
    if (!selectedJobId) {
      toast.error('Create a job opening first, then add candidates to it');
      return;
    }
    if (!candName.trim() || !candEmail.trim()) {
      toast.error('Candidate name and email are required');
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/hr/recruitment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'ADD_CANDIDATE',
          workspaceId: activeWorkspace.id,
          jobId: selectedJobId,
          fullName: candName,
          email: candEmail,
          phone: candPhone
        })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success('Candidate added to job pipeline');
      setCandName('');
      setCandEmail('');
      setCandPhone('');
      setCandModalOpen(false);
      fetchRecruitment();
    } catch (err: any) {
      toast.error(err.message || 'Failed to add candidate');
    } finally {
      setSaving(false);
    }
  };

  const handleMoveStage = async (appId: string, newStage: string) => {
    try {
      const res = await fetch('/api/hr/recruitment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'MOVE_STAGE',
          workspaceId: activeWorkspace?.id,
          applicationId: appId,
          newStage
        })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success(`Application moved to ${newStage}`);
      fetchRecruitment();
    } catch (err: any) {
      toast.error(err.message || 'Failed to update stage');
    }
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Recruitment & Hiring ATS"
        description="Manage job openings, candidate recruitment pipelines, interview scheduling, and offer letters."
        action={
          canManage && (
            <div className="flex items-center gap-2">
              <IconAction label="Add Candidate" icon={<UserCheck className="size-4 " />} variant="outline" onClick={() => setCandModalOpen(true)} className="bg-card" />
              <IconAction label="Create Job Opening" icon={<Plus className="size-4 " />} onClick={() => setJobModalOpen(true)} className="bg-primary text-primary-foreground" />
            </div>
          )
        }
      />

      <Tabs defaultValue="pipeline" className="space-y-6">
        <TabsList className="bg-muted/50 border border-border">
          <TabsTrigger value="pipeline">Candidate Pipeline (Kanban)</TabsTrigger>
          <TabsTrigger value="jobs">Job Openings ({jobs.length})</TabsTrigger>
        </TabsList>

        {/* Candidate Pipeline Kanban */}
        <TabsContent value="pipeline" className="space-y-4">
          {loading ? (
            <div className="flex justify-center py-16">
              <Loader2 className="size-8 animate-spin text-primary" />
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-4 overflow-x-auto">
              {STAGES.map(stage => {
                const stageApps = applications.filter(a => a.stage === stage);

                return (
                  <div key={stage} className="bg-muted/30 border border-border rounded-lg p-3 min-w-[200px] flex flex-col gap-3">
                    <div className="flex items-center justify-between font-semibold text-xs text-foreground uppercase tracking-wider">
                      <span>{stage}</span>
                      <Badge variant="secondary" className="text-[10px]">{stageApps.length}</Badge>
                    </div>

                    <div className="space-y-2 min-h-[300px]">
                      {stageApps.map(a => (
                        <Card key={a.id} className="border-border bg-card shadow-xs p-3 space-y-2 text-xs">
                          <div className="font-semibold text-foreground">{a.candidate?.full_name || 'Candidate'}</div>
                          <div className="text-[11px] text-muted-foreground truncate">{a.candidate?.email}</div>
                          <Badge variant="outline" className="text-[9px] bg-secondary/40">
                            {a.job?.title || 'Job Opening'}
                          </Badge>

                          <div className="pt-2 flex items-center justify-between border-t border-border/40 text-[10px]">
                            {stage !== 'HIRED' && stage !== 'REJECTED' && (
                              <button
                                onClick={() => {
                                  const nextIdx = STAGES.indexOf(stage) + 1;
                                  if (nextIdx < STAGES.length) handleMoveStage(a.id, STAGES[nextIdx]);
                                }}
                                className="text-primary hover:underline flex items-center gap-0.5"
                              >
                                Advance <ChevronRight className="size-3" />
                              </button>
                            )}
                          </div>
                        </Card>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </TabsContent>

        {/* Job Openings Tab */}
        <TabsContent value="jobs">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {jobs.map(j => (
              <Card key={j.id} className="border-border bg-card shadow-sm">
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <Badge variant="outline" className="text-[10px] bg-emerald-500/10 text-emerald-500 border-emerald-500/20">
                      {j.status}
                    </Badge>
                    <span className="text-xs text-muted-foreground">{j.location}</span>
                  </div>
                  <CardTitle className="text-base font-semibold mt-2">{j.title}</CardTitle>
                  <CardDescription className="text-xs">{j.employment_type?.replace(/_/g, ' ')}</CardDescription>
                </CardHeader>
              </Card>
            ))}
          </div>
        </TabsContent>
      </Tabs>

      {/* Create Job Modal */}
      <Dialog open={jobModalOpen} onOpenChange={setJobModalOpen}>
        <DialogContent className="sm:max-w-[480px] bg-card border-border rounded-xl p-6 shadow-2xl">
          <DialogHeader>
            <DialogTitle className="text-lg font-semibold text-foreground">Create Job Opening</DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">Post a new open job role for recruitment.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateJob} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Job Title <span className="text-red-500">*</span></Label>
              <Input placeholder="e.g. Senior Frontend Developer" value={jobTitle} onChange={e => setJobTitle(e.target.value)} required className="bg-card border-border" />
            </div>

            <div className="space-y-2">
              <Label>Location</Label>
              <Input placeholder="Remote / New York / Hybrid" value={jobLocation} onChange={e => setJobLocation(e.target.value)} className="bg-card border-border" />
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setJobModalOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null} Create Job
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Add Candidate Modal */}
      <Dialog open={candModalOpen} onOpenChange={setCandModalOpen}>
        <DialogContent className="sm:max-w-[500px] bg-card border-border rounded-xl p-6 shadow-2xl">
          <DialogHeader>
            <DialogTitle className="text-lg font-semibold text-foreground">Add Candidate to Job</DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">Add a candidate application into the recruitment pipeline.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleAddCandidate} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Select Job Opening <span className="text-red-500">*</span></Label>
              <Select value={selectedJobId} onValueChange={(v) => setSelectedJobId(v || '')}>
                <SelectTrigger className="w-full bg-card border-border h-10 text-sm">
                  <SelectValue placeholder="Select a job opening..." />
                </SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {jobs.map(j => (
                    <SelectItem key={j.id} value={j.id} className="cursor-pointer text-sm">
                      {j.title} {j.location ? `(${j.location})` : ''}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Candidate Full Name <span className="text-red-500">*</span></Label>
              <Input placeholder="Jane Doe" value={candName} onChange={e => setCandName(e.target.value)} required className="bg-card border-border" />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Email Address <span className="text-red-500">*</span></Label>
                <Input type="email" placeholder="jane@example.com" value={candEmail} onChange={e => setCandEmail(e.target.value)} required className="bg-card border-border" />
              </div>
              <div className="space-y-2">
                <Label>Phone Number</Label>
                <Input placeholder="+1 555-0199" value={candPhone} onChange={e => setCandPhone(e.target.value)} className="bg-card border-border" />
              </div>
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setCandModalOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null} Add Candidate
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { PageHeader } from '@/components/shared/page-header';
import { useWorkspace } from '@/hooks/use-workspace';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { 
  BarChart3, 
  Users, 
  Clock, 
  CheckSquare, 
  Loader2, 
  TrendingUp, 
  FileDown 
} from 'lucide-react';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { startOfMonth, endOfMonth, format } from 'date-fns';

type EmployeeStats = {
  id: string;
  name: string;
  avatar: string | null;
  designation: string;
  totalTasks: number;
  completedTasks: number;
  loggedHours: number;
  daysPresent: number;
  expectedDays: number;
};

export default function ReportsDashboard() {
  const supabase = createClient();
  const { activeWorkspace, can } = useWorkspace();
  const canManagePeople = can('people_manage');

  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const [stats, setStats] = useState<EmployeeStats[]>([]);
  
  // Aggregate KPIs
  const [totalHours, setTotalHours] = useState(0);
  const [overallAttendance, setOverallAttendance] = useState(0);
  const [totalCompletedTasks, setTotalCompletedTasks] = useState(0);

  const fetchReports = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      // 1. Fetch workspace members
      const { data: rawMembers } = await supabase
        .from('workspace_members')
        .select('id, user_id')
        .eq('workspace_id', activeWorkspace.id);

      const members = rawMembers || [];

      // 2. Fetch employee_profiles
      const { data: empProfiles } = await supabase
        .from('employee_profiles')
        .select('workspace_member_id, designation_id, status')
        .eq('workspace_id', activeWorkspace.id);

      const empProfileMap = new Map((empProfiles || []).map((e: any) => [e.workspace_member_id, e]));

      // 3. Fetch designations
      const { data: desigRows } = await supabase
        .from('designations')
        .select('id, title')
        .eq('workspace_id', activeWorkspace.id);
      const designationById: Record<string, string> = {};
      (desigRows || []).forEach((d) => { designationById[d.id] = d.title; });

      // 4. Two-step profile enrichment
      const userIds = members.map((m: any) => m.user_id).filter(Boolean);
      let profileMap = new Map();
      if (userIds.length > 0) {
        const { data: profilesData } = await supabase
          .from('profiles')
          .select('user_id, full_name, email, avatar_url')
          .in('user_id', userIds);
        profileMap = new Map((profilesData || []).map((p: any) => [p.user_id, p]));
      }

      const startDate = startOfMonth(new Date()).toISOString();
      const endDate = endOfMonth(new Date()).toISOString();

      // 5. Fetch Tasks (safe query)
      // `tasks` has no `status` column — completion lives in
      // project_statuses.category via status_id. Selecting `status` errored,
      // so `tasks` was null and every "tasks completed" figure read zero.
      const { data: tasks } = await supabase
        .from('tasks')
        .select('id, assigned_workspace_member_id, status:project_statuses(category)')
        .eq('workspace_id', activeWorkspace.id)
        .gte('created_at', startDate)
        .lte('created_at', endDate);

      // 6. Fetch Timesheets / Time Logs (safe query)
      // `time_logs` has no `status` column — approval is the boolean
      // `approved`. Filtering on `status` errored, so `timesheets` came back
      // null and every timesheet figure below silently read as zero.
      const { data: timesheets } = await supabase
        .from('time_logs')
        .select('workspace_member_id, duration')
        .eq('workspace_id', activeWorkspace.id)
        .gte('log_date', format(startOfMonth(new Date()), 'yyyy-MM-dd'))
        .lte('log_date', format(endOfMonth(new Date()), 'yyyy-MM-dd'))
        .eq('approved', true);

      // 7. Fetch Attendance (safe query)
      const { data: attendance } = await supabase
        .from('attendance')
        .select('workspace_member_id, status')
        .eq('workspace_id', activeWorkspace.id)
        .gte('attendance_date', format(startOfMonth(new Date()), 'yyyy-MM-dd'))
        .lte('attendance_date', format(endOfMonth(new Date()), 'yyyy-MM-dd'));

      // Calculate working days in current month so far
      let expectedDays = 0;
      const d = startOfMonth(new Date());
      const today = new Date();
      while (d <= today && d <= endOfMonth(new Date())) {
        if (d.getDay() !== 0 && d.getDay() !== 6) expectedDays++;
        d.setDate(d.getDate() + 1);
      }
      if (expectedDays === 0) expectedDays = 1;

      // Aggregate data per employee
      let totalH = 0;
      let totalCT = 0;
      let totalAtt = 0;
      let totalEmp = 0;

      const aggregated: EmployeeStats[] = members.map((mem: any) => {
        const profile = profileMap.get(mem.user_id);
        const empProfile = empProfileMap.get(mem.id);
        
        // Tasks
        const memTasks = (tasks || []).filter(t => t.assigned_workspace_member_id === mem.id);
        const compTasks = memTasks.filter(
          (t) => (t.status as { category?: string } | null)?.category === 'DONE'
        ).length;
        totalCT += compTasks;

        // Hours
        const memTimesheets = (timesheets || []).filter(t => t.workspace_member_id === mem.id);
        const logHours = memTimesheets.reduce((acc, curr) => acc + Number(curr.duration || 0), 0);
        totalH += logHours;

        // Attendance
        const memAtt = (attendance || []).filter(t => t.workspace_member_id === mem.id);
        const presentDays = memAtt.filter(a => a.status === 'Present' || a.status === 'Remote' || a.status === 'Half-Day' || a.status === 'Late').length;
        
        totalAtt += presentDays;
        totalEmp++;

        const name = profile?.full_name?.trim() || profile?.email?.split('@')[0] || 'Employee';

        return {
          id: mem.id,
          name,
          avatar: profile?.avatar_url || null,
          designation: designationById[empProfile?.designation_id || ''] || 'Employee',
          totalTasks: memTasks.length,
          completedTasks: compTasks,
          loggedHours: logHours,
          daysPresent: presentDays,
          expectedDays
        };
      });

      setStats(aggregated);
      setTotalHours(totalH);
      setTotalCompletedTasks(totalCT);
      setOverallAttendance(totalEmp > 0 ? (totalAtt / (expectedDays * totalEmp)) * 100 : 0);

    } catch (err: any) {
      console.error('Error loading reports:', err);
      toast.error('Failed to load report data');
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id]);

  useEffect(() => {
    fetchReports();
  }, [fetchReports]);

  if (!canManagePeople) {
    return (
      <div className="flex items-center justify-center h-[50vh]">
        <div className="text-center">
          <BarChart3 className="size-12 text-muted-foreground mx-auto mb-4" />
          <h2 className="text-lg font-medium text-foreground">Access Denied</h2>
          <p className="text-sm text-muted-foreground mt-1">You need people management permissions to view reports.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PageHeader 
        title="Performance Reports" 
        description="Company-wide operational pulse and employee performance metrics for this month."
        action={
          <Button
            variant="outline"
            className="border-border text-foreground"
            onClick={() => {
              const header = 'Name,Attendance %,Days Present,Expected Days,Logged Hours,Tasks Completed,Total Tasks';
              const rows = stats.map((e) =>
                [
                  `"${e.name.replace(/"/g, '""')}"`,
                  e.expectedDays > 0 ? ((e.daysPresent / e.expectedDays) * 100).toFixed(1) : '0',
                  e.daysPresent, e.expectedDays, e.loggedHours.toFixed(1),
                  e.completedTasks, e.totalTasks,
                ].join(',')
              );
              const blob = new Blob([[header, ...rows].join('\n')], { type: 'text/csv' });
              const a = document.createElement('a');
              a.href = URL.createObjectURL(blob);
              a.download = `hr-monthly-summary-${new Date().toISOString().slice(0, 7)}.csv`;
              a.click();
              URL.revokeObjectURL(a.href);
            }}
          >
            <FileDown className="size-4 mr-2" />
            Export Monthly Summary
          </Button>
        }
      />

      {/* Top Level KPIs */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card className="bg-card border-border shadow-sm">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Team Attendance Rate</CardTitle>
            <Users className="h-4 w-4 text-emerald-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-foreground">
              {loading ? <Loader2 className="size-4 animate-spin" /> : `${overallAttendance.toFixed(1)}%`}
            </div>
            <p className="text-xs text-muted-foreground mt-1 flex items-center">
              <TrendingUp className="size-3 mr-1 text-emerald-500" />
              For current month
            </p>
          </CardContent>
        </Card>

        <Card className="bg-card border-border shadow-sm">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Total Logged Hours</CardTitle>
            <Clock className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-foreground">
              {loading ? <Loader2 className="size-4 animate-spin" /> : totalHours.toFixed(1)}
            </div>
            <p className="text-xs text-muted-foreground mt-1 flex items-center">
              Via approved timesheets
            </p>
          </CardContent>
        </Card>

        <Card className="bg-card border-border shadow-sm">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Tasks Completed</CardTitle>
            <CheckSquare className="h-4 w-4 text-purple-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-foreground">
              {loading ? <Loader2 className="size-4 animate-spin" /> : totalCompletedTasks}
            </div>
            <p className="text-xs text-muted-foreground mt-1 flex items-center">
              Across all active projects
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Leaderboard Table */}
      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent bg-muted/20">
              <TableHead className="text-muted-foreground">Employee</TableHead>
              <TableHead className="text-muted-foreground text-center">Attendance %</TableHead>
              <TableHead className="text-muted-foreground text-center">Hours Logged</TableHead>
              <TableHead className="text-muted-foreground text-center">Task Completion</TableHead>
              <TableHead className="text-muted-foreground w-[150px] text-right">Action</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={5} className="text-center py-12">
                  <div className="flex flex-col items-center gap-2">
                    <Loader2 className="size-6 animate-spin text-primary" />
                    <p className="text-sm text-muted-foreground">Calculating metrics...</p>
                  </div>
                </TableCell>
              </TableRow>
            ) : stats.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={5} className="text-center py-12">
                  <p className="text-sm text-muted-foreground">No active employees found for this period.</p>
                </TableCell>
              </TableRow>
            ) : (
              stats.map((employee) => {
                const attPercent = employee.expectedDays > 0 
                  ? ((employee.daysPresent / employee.expectedDays) * 100) 
                  : 0;
                  
                const taskPercent = employee.totalTasks > 0
                  ? Math.round((employee.completedTasks / employee.totalTasks) * 100)
                  : 0;

                return (
                  <TableRow key={employee.id} className="border-border hover:bg-muted/50 transition-colors">
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar className="size-8 border border-border">
                          {employee.avatar && <AvatarImage src={employee.avatar} />}
                          <AvatarFallback className="bg-primary/10 text-primary text-xs font-medium">
                            {employee.name.charAt(0).toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex flex-col">
                          <span className="font-medium text-foreground">{employee.name}</span>
                          <span className="text-xs text-muted-foreground">{employee.designation}</span>
                        </div>
                      </div>
                    </TableCell>
                    
                    <TableCell className="text-center">
                      <div className="flex flex-col items-center">
                        <span className="font-semibold text-foreground">{attPercent.toFixed(1)}%</span>
                        <span className="text-[10px] text-muted-foreground">{employee.daysPresent} / {employee.expectedDays} days</span>
                      </div>
                    </TableCell>
                    
                    <TableCell className="text-center">
                      <Badge variant="secondary" className="font-mono bg-blue-500/10 text-blue-600 border-none">
                        {employee.loggedHours.toFixed(1)}h
                      </Badge>
                    </TableCell>
                    
                    <TableCell className="text-center">
                      <div className="w-full max-w-[120px] mx-auto flex items-center gap-2">
                        <div className="flex-1 h-2 rounded-full bg-muted overflow-hidden">
                          <div 
                            className="h-full bg-purple-500 rounded-full" 
                            style={{ width: `${taskPercent}%` }} 
                          />
                        </div>
                        <span className="text-xs font-medium text-foreground w-8 text-right">
                          {employee.completedTasks}/{employee.totalTasks}
                        </span>
                      </div>
                    </TableCell>
                    
                    <TableCell className="text-right">
                      <Button variant="ghost" size="sm" className="text-primary hover:text-primary hover:bg-primary/10" onClick={() => router.push(`/employees/${employee.id}`)}>
                        View Profile
                      </Button>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { FileCheck, Plus, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { IconAction } from "@/components/ui/icon-action";

const REQUEST_TYPES = [
  { value: 'SALARY_CERTIFICATE', label: 'Salary Certificate Request' },
  { value: 'EXPERIENCE_LETTER', label: 'Experience & Relieving Letter' },
  { value: 'BANK_DETAILS_CHANGE', label: 'Bank Account Details Change' },
  { value: 'PF_DECLARATION', label: 'PF Declaration / Transfer' },
  { value: 'ADDRESS_CHANGE', label: 'Personal Address Change' },
  { value: 'RESIGNATION', label: 'Official Resignation Intimation' }
];

export default function EmployeeRequestsPage() {
  const { activeWorkspace, activeMember, can } = useWorkspace();
  const canManage = can('people_manage');

  async function decideRequest(requestId: string, status: 'APPROVED' | 'REJECTED') {
    try {
      const res = await fetch('/api/hr/requests', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ requestId, status }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to update request');
      toast.success(`Request ${status.toLowerCase()}`);
      void fetchRequests();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update request');
    }
  }


  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const [requestType, setRequestType] = useState('SALARY_CERTIFICATE');
  const [notes, setNotes] = useState('');

  const fetchRequests = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const res = await fetch(`/api/hr/requests?workspaceId=${activeWorkspace.id}`);
      const json = await res.json();
      setRequests(json.requests || []);
    } catch {
      toast.error('Failed to load employee requests');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id]);

  useEffect(() => {
    fetchRequests();
  }, [fetchRequests]);

  const handleSubmitRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !activeMember?.id) return;

    setSaving(true);
    try {
      const res = await fetch('/api/hr/requests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspaceId: activeWorkspace.id,
          employeeId: activeMember.id,
          requestType,
          notes
        })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success('Request submitted to HR');
      setNotes('');
      setModalOpen(false);
      fetchRequests();
    } catch (err: any) {
      toast.error(err.message || 'Failed to submit request');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Employee Self-Service Requests"
        description="Submit and track HR requests for salary certificates, experience letters, bank account changes, and formal requests."
        action={
          <IconAction label="New ESS Request" icon={<Plus className="size-4 " />} onClick={() => setModalOpen(true)} className="bg-primary text-primary-foreground" />
        }
      />

      {loading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="size-8 animate-spin text-primary" />
        </div>
      ) : requests.length === 0 ? (
        <Card className="border-border bg-card shadow-sm">
          <CardContent className="flex flex-col items-center justify-center py-16 text-center">
            <FileCheck className="size-12 text-muted-foreground opacity-20 mb-4" />
            <h3 className="text-lg font-semibold text-foreground mb-1">No ESS Requests Found</h3>
            <p className="text-sm text-muted-foreground max-w-sm mb-6">
              Submit employee self-service requests for certificates, bank account updates, or official letters.
            </p>
            <IconAction label="Submit First Request" icon={<Plus className="size-4 " />} onClick={() => setModalOpen(true)} />
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {requests.map(r => (
            <Card key={r.id} className="border-border bg-card shadow-sm">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <Badge variant="outline" className="text-[10px] uppercase font-mono bg-secondary/50">
                    {r.request_type.replace(/_/g, ' ')}
                  </Badge>
                  <Badge
                    variant={r.status === 'APPROVED' ? 'default' : r.status === 'REJECTED' ? 'destructive' : 'secondary'}
                    className={r.status === 'APPROVED' ? 'bg-emerald-600 text-foreground' : ''}
                  >
                    {r.status}
                  </Badge>
                </div>
                <CardTitle className="text-base font-semibold mt-2">{r.request_type.replace(/_/g, ' ')}</CardTitle>
                <CardDescription className="text-xs line-clamp-2 mt-1">{r.notes || 'Employee request submission.'}</CardDescription>
              </CardHeader>
              <CardContent className="pt-0 text-xs text-muted-foreground border-t border-border/50 flex items-center justify-between mt-3 pt-3">
                <span>Submitted {new Date(r.created_at).toLocaleDateString()}</span>
                {r.status === 'PENDING' && canManage ? (
                  <span className="flex items-center gap-2">
                    <button
                      className="text-emerald-500 hover:underline"
                      onClick={() => decideRequest(r.id, 'APPROVED')}
                    >
                      Approve
                    </button>
                    <button
                      className="text-red-500 hover:underline"
                      onClick={() => decideRequest(r.id, 'REJECTED')}
                    >
                      Reject
                    </button>
                  </span>
                ) : (
                  <span>{r.status === 'PENDING' ? '⏳ Under HR Review' : 'Resolved'}</span>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Submit Request Modal */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Submit Employee Self-Service Request</DialogTitle>
            <DialogDescription>Select the request type and provide details for HR processing.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleSubmitRequest} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Request Type</Label>
              <Select value={requestType} onValueChange={(val) => setRequestType(val || 'SALARY_CERTIFICATE')}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  {REQUEST_TYPES.map(rt => (
                    <SelectItem key={rt.value} value={rt.value}>{rt.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Details / Notes for HR</Label>
              <Textarea plain
                placeholder="Provide context or the reason for the request. Do NOT include bank details here — HR will collect them securely."
                value={notes}
                onChange={e => setNotes(e.target.value)}
                rows={4}
              />
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setModalOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null} Submit Request
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

