'use client';

import { useMemo, useState, useEffect, type ReactNode } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

import { useAuth } from '@/hooks/use-auth';
import { useTheme } from '@/hooks/use-theme';
import { SettingsRail } from '@/components/settings/settings-rail';
import { SettingsOverview } from '@/components/settings/settings-overview';
import { ProfileForm } from '@/components/settings/profile-form';
import { SecurityPanel } from '@/components/settings/security-panel';
import { AppearancePanel } from '@/components/settings/appearance-panel';
import { WhatsAppConfig } from '@/components/settings/whatsapp-config';
import { ChatbotConfig } from '@/components/settings/chatbot-config';
import { TemplateManager } from '@/components/settings/template-manager';
import { FieldsAndTagsPanel } from '@/components/settings/fields-and-tags-panel';
import { DealsSettings } from '@/components/settings/deals-settings';
import { MembersTab } from '@/components/settings/members-tab';
import { RolesPanel } from '@/components/settings/roles-panel';
import { ApiKeysSettings } from '@/components/settings/api-keys-settings';
import { CatalogSettings } from '@/components/settings/catalog-settings';
import { BrandingSettings } from '@/components/settings/branding-settings';
import { BillingPanel } from '@/components/settings/billing-panel';
import { HRSettingsPanel } from '@/components/settings/hr-settings-panel';
import { TemplateLibraryPanel } from '@/components/settings/template-library-panel';
import { AttendancePolicyPanel } from '@/components/settings/attendance-policy-panel';
import RetailSettingsPage from '@/app/(dashboard)/settings/retail/page';
import { CRMSettingsPanel } from '@/components/settings/crm-settings-panel';
import { AccountingSettingsPanel } from '@/components/settings/accounting-settings-panel';
import { ProjectsSettingsPanel } from '@/components/settings/projects-settings-panel';
import {
  resolveSection,
  type SettingsSection,
} from '@/components/settings/settings-sections';
import { PageHeader } from '@/components/ui/page-header';
import { SettingsSubtabs } from '@/components/settings/settings-subtabs';
import { LetterheadDesigner } from '@/components/documents/letterhead-designer';
import { TimesheetTemplatesManager } from '@/components/settings/timesheet-templates-manager';

export default function SettingsPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { defaultCurrency } = useAuth();
  const { mode } = useTheme();

  // The raw value is kept alongside the resolved section so a folded
  // section (?tab=security) can open its parent on the right sub-tab.
  const rawTab = searchParams.get('tab');
  const [section, setSection] = useState<SettingsSection>(() =>
    resolveSection(searchParams.get('tab'))
  );

  useEffect(() => {
    const nextSection = resolveSection(searchParams.get('tab'));
    setSection(nextSection);
  }, [searchParams]);

  const go = (next: SettingsSection) => {
    setSection(next);
    const params = new URLSearchParams(searchParams.toString());
    params.set('tab', next);
    router.replace(`/settings?${params.toString()}`, { scroll: false });
  };

  // Cheap, fetch-free rail hints. The Overview landing carries the
  // full live status/counts; the rail just surfaces the two that are
  // already in context.
  const hints: Partial<Record<SettingsSection, ReactNode>> = useMemo(
    () => ({
      profile: mode.charAt(0).toUpperCase() + mode.slice(1),
      crm: defaultCurrency,
    }),
    [mode, defaultCurrency],
  );

  const renderPanel = () => {
    switch (section) {
      case 'overview':
        return <SettingsOverview onSelect={go} />;
      case 'profile':
        return (
          <SettingsSubtabs
            initialTab={rawTab === 'security' || rawTab === 'appearance' ? rawTab : undefined}
            tabs={[
              { id: 'profile', label: 'Profile', render: () => <ProfileForm /> },
              { id: 'security', label: 'Security', render: () => <SecurityPanel /> },
              { id: 'appearance', label: 'Appearance', render: () => <AppearancePanel /> },
            ]}
          />
        );
      case 'crm':
        return (
          <SettingsSubtabs
            initialTab={
              rawTab === 'deals' || rawTab === 'fields' || rawTab === 'tags' ? rawTab : undefined
            }
            tabs={[
              { id: 'crm-general', label: 'General', render: () => <CRMSettingsPanel /> },
              { id: 'deals', label: 'Deals', render: () => <DealsSettings /> },
              { id: 'fields', label: 'Fields & tags', render: () => <FieldsAndTagsPanel /> },
            ]}
          />
        );
      case 'accounting':
        return <AccountingSettingsPanel />;
      case 'projects':
        return <ProjectsSettingsPanel />;
      case 'whatsapp':
        return (
          <SettingsSubtabs
            initialTab={
              rawTab === 'chatbot' || rawTab === 'whatsapp-templates' ? rawTab : undefined
            }
            tabs={[
              { id: 'whatsapp', label: 'Connection', render: () => <WhatsAppConfig /> },
              { id: 'chatbot', label: 'Chatbot', render: () => <ChatbotConfig /> },
              {
                id: 'whatsapp-templates',
                label: 'Meta approvals',
                render: () => <TemplateManager />,
              },
            ]}
          />
        );
      case 'templates':
        return <TemplateLibraryPanel />;
      case 'members':
        return (
          <SettingsSubtabs
            initialTab={rawTab === 'roles' || rawTab === 'permissions' ? 'roles' : undefined}
            tabs={[
              { id: 'members-list', label: 'Members', render: () => <MembersTab /> },
              { id: 'roles', label: 'Roles & permissions', render: () => <RolesPanel /> },
            ]}
          />
        );
      case 'billing':
        return <BillingPanel />;
      case 'api':
        return <ApiKeysSettings />;
      case 'catalog':
        return <CatalogSettings />;
      case 'branding':
        return (
          <SettingsSubtabs
            initialTab={rawTab === 'letterhead' ? 'letterhead' : undefined}
            tabs={[
              { id: 'branding', label: 'Company details', render: () => <BrandingSettings /> },
              {
                id: 'letterhead',
                label: 'Letterhead',
                render: () => <LetterheadDesigner />,
              },
            ]}
          />
        );
      case 'hr':
        return (
          <SettingsSubtabs
            initialTab={
              rawTab === 'attendance' || rawTab === 'timesheet-templates' ? rawTab : undefined
            }
            tabs={[
              { id: 'hr', label: 'Shifts, leave & payroll', render: () => <HRSettingsPanel /> },
              {
                id: 'attendance',
                label: 'Attendance & locations',
                render: () => <AttendancePolicyPanel />,
              },
              {
                id: 'timesheet-templates',
                label: 'Timesheet templates',
                render: () => <TimesheetTemplatesManager canEdit />,
              },
            ]}
          />
        );
      case 'retail':
        return <RetailSettingsPage />;
      default:
        return <SettingsOverview onSelect={go} />;
    }
  };

  return (
    <div className="space-y-5">
      <PageHeader
        title="Settings"
        description="Everything in one place — your account and your workspace. Pick a section to manage it."
      />

      <div className="mt-6 grid gap-6 lg:grid-cols-[236px_minmax(0,1fr)] lg:items-start">
        <SettingsRail active={section} onSelect={go} hints={hints} />
        <div className="min-w-0">{renderPanel()}</div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Sparkles, Check, Landmark, Plus, Trash2, QrCode } from "lucide-react";
import { toast } from "sonner";
import { SettingsPanelHead } from "@/components/settings/settings-panel-head";
import { IconAction } from "@/components/ui/icon-action";

export const INDUSTRY_TEMPLATES = [
  { id: "GENERAL_RETAIL", label: "General Retail Store", icon: "", desc: "Standard retail catalog, POS billing, and GST tax management." },
  { id: "GROCERY", label: "Supermarket & Grocery", icon: "", desc: "Pack size, Net/Gross Weight, Storage temp, Best Before, Organic, FEFO expiry." },
  { id: "PHARMACY", label: "Chemist & Pharmacy", icon: "", desc: "Salt Composition, Dosage Form, Strength, Schedule H/H1, Mfg License, Expiry alerts." },
  { id: "GARMENT", label: "Apparel & Garment Store", icon: "", desc: "Size, Color, Fabric, Fit, Gender, Season, Sleeve, Neck, Pattern, Collection, Style Code." },
  { id: "FOOTWEAR", label: "Footwear Showroom", icon: "", desc: "Shoe Size, Material, Color, Heel Height, Sole Material, Closure Type, Waterproof." },
  { id: "ELECTRONICS", label: "Electronics & Mobile Shop", icon: "", desc: "Model #, Processor, RAM, Storage, Display Size, Battery, Serial/IMEI, Warranty." },
  { id: "JEWELLERY", label: "Jewellery & Bullion", icon: "", desc: "Karat Purity, Net/Gross/Stone Weight, Making Charges, Wastage %, Hallmark #, Certification." },
  { id: "HARDWARE", label: "Hardware & Building Material", icon: "", desc: "Material Grade, Dimensions, Length/Width/Diameter, Coating, Standard." },
  { id: "FURNITURE", label: "Furniture Showroom", icon: "", desc: "Dimensions, Wood/Material Type, Color, Finish, Weight Capacity, Room Type." },
  { id: "AUTOMOBILE", label: "Automobile & Spare Parts", icon: "", desc: "OEM Part #, Vehicle Fitment, Engine Type, Model Year, Fuel Type, Position." },
  { id: "BOOKS_STATIONERY", label: "Books & Stationery", icon: "", desc: "ISBN, Author, Publisher, Edition, Language, Genre, Binding Type, Pages." },
  { id: "RESTAURANT", label: "Restaurant & QSR", icon: "", desc: "Veg/Non-Veg/Jain, Spicy Level, KOT Station, Prep Time, Recipe Code, Calories." },
  { id: "MANUFACTURING", label: "Manufacturing & Production", icon: "", desc: "BOM Reference, Routing, Work Center, Yield %, Scrap %, QC Required, Revision." },
  { id: "OPTICAL", label: "Optical & Eyewear Store", icon: "", desc: "Frame Size, Lens Type, Spher/Cyl Power, Axis, PD, Lens/Frame Brand, UV Protection." },
  { id: "COSMETICS", label: "Cosmetics & Beauty", icon: "", desc: "Shade, Skin Type, Hair Type, SPF Rating, Volume (ml), Cruelty Free, Organic." },
  { id: "PET_STORE", label: "Pet Store & Supplies", icon: "", desc: "Pet Type (Dog/Cat), Breed, Age Group, Flavor, Weight, Prescription Food." },
  { id: "CHEMICAL_PAINT", label: "Chemicals & Paint Store", icon: "", desc: "Hazard Class, UN Number, Flash Point, Viscosity, Color Code, Safety Sheet (MSDS)." },
  { id: "AGRICULTURE", label: "Agriculture & Farming", icon: "", desc: "Seed Variety, Crop, Season, Fertilizer Grade, Pesticide Type, License #." },
  { id: "BABY_PRODUCTS", label: "Baby & Infant Products", icon: "", desc: "Age Group (Months), Material, Safety Standard, BPA Free, Non-Toxic." },
  { id: "HANDCRAFTED_GIFTS", label: "Handcrafted & Handmade Gift Shop", icon: "", desc: "Artisan/Maker Name, Handcrafting Lead Days, Personalization Notes, Gift Box Type, Sustainable/Eco-Friendly." },
  { id: "EVENT_BULK_GIFTS", label: "Wedding & Corporate Bulk Return Gifts", icon: "", desc: "Target Event (Wedding/Corporate), Minimum Order Qty (MOQ), Tiered Bulk Rates, Custom Branding Card, Sample Lead Time." },
];

const DEFAULT_ACCOUNTS = [
  { id: "1", name: "HDFC Bank Primary", vpa: "store@hdfc" },
  { id: "2", name: "ICICI Bank Current", vpa: "store@icici" },
  { id: "3", name: "SBI Business Account", vpa: "store@sbi" },
  { id: "4", name: "Store Static QR Code", vpa: "merchant@paytm" }
];

export default function RetailSettingsPage() {
  const { activeWorkspace } = useWorkspace();
  const [selectedTemplate, setSelectedTemplate] = useState("GENERAL_RETAIL");
  const [saving, setSaving] = useState(false);

  // Bank Accounts state
  const [accounts, setAccounts] = useState<any[]>([]);
  const [newName, setNewName] = useState("");
  const [newVpa, setNewVpa] = useState("");

  useEffect(() => {
    if (!activeWorkspace?.id) return;
    const saved = localStorage.getItem(`retail_template_${activeWorkspace.id}`);
    if (saved) {
      setSelectedTemplate(saved);
    }

    const savedAccounts = localStorage.getItem(`retail_bank_accounts_${activeWorkspace.id}`);
    if (savedAccounts) {
      setAccounts(JSON.parse(savedAccounts));
    } else {
      setAccounts(DEFAULT_ACCOUNTS);
      localStorage.setItem(`retail_bank_accounts_${activeWorkspace.id}`, JSON.stringify(DEFAULT_ACCOUNTS));
    }
  }, [activeWorkspace?.id]);

  const handleApplyTemplate = async (templateId: string) => {
    if (!activeWorkspace?.id) return;
    setSaving(true);
    try {
      setSelectedTemplate(templateId);
      localStorage.setItem(`retail_template_${activeWorkspace.id}`, templateId);
      localStorage.setItem('retail_template_active', templateId);
      toast.success(`Workspace Industry Template set to "${templateId}"!`);
    } catch {
      toast.error("Failed to apply preset");
    } finally {
      setSaving(false);
    }
  };

  const handleAddAccount = () => {
    if (!newName.trim() || !newVpa.trim()) {
      toast.error("Account Name and UPI VPA/ID are required");
      return;
    }
    const newAcc = {
      id: Date.now().toString(),
      name: newName.trim(),
      vpa: newVpa.trim()
    };
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    if (activeWorkspace?.id) {
      localStorage.setItem(`retail_bank_accounts_${activeWorkspace.id}`, JSON.stringify(updated));
    }
    setNewName("");
    setNewVpa("");
    toast.success(`Added bank account "${newAcc.name}"`);
  };

  const handleRemoveAccount = (id: string) => {
    const updated = accounts.filter(acc => acc.id !== id);
    setAccounts(updated);
    if (activeWorkspace?.id) {
      localStorage.setItem(`retail_bank_accounts_${activeWorkspace.id}`, JSON.stringify(updated));
    }
    toast.success("Account removed");
  };

  return (
    <section className="space-y-6 max-w-5xl animate-in fade-in-50 duration-200">
      <SettingsPanelHead
        title="Retail & Industry Presets"
        description="Set your workspace industry template and configure active UPI bank accounts for POS terminal payments."
      />

      {/* Active Template Status Card */}
      <div className="bg-card border border-border rounded-2xl p-4 flex items-center justify-between shadow-sm">
        <div>
          <div className="text-xs text-muted-foreground font-bold uppercase tracking-wider">Active Workspace Industry Template</div>
          <div className="text-lg font-extrabold text-primary mt-0.5">{selectedTemplate}</div>
        </div>
        <span className="text-xs bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 px-3 py-1 rounded-xl font-bold">
          System Active
        </span>
      </div>

      {/* Dynamic Bank Accounts / UPI configuration */}
      <div className="bg-card border border-border rounded-2xl p-6 space-y-4 shadow-sm">
        <h2 className="text-sm font-bold text-foreground flex items-center gap-2">
          <Landmark className="size-4 text-primary" />
          UPI Bank Accounts & Destination Handles
        </h2>
        <p className="text-xs text-muted-foreground">
          Configure bank accounts and UPI VPA handles to route UPI and Split payments directly in the POS Checkout panel.
        </p>

        {/* List of accounts */}
        <div className="space-y-2">
          {accounts.map((acc) => (
            <div key={acc.id} className="flex items-center justify-between bg-muted/40 p-3 rounded-xl border border-border/60">
              <div className="flex items-center gap-3">
                <QrCode className="size-4 text-primary" />
                <div>
                  <div className="text-xs font-bold text-foreground">{acc.name}</div>
                  <div className="text-[11px] text-muted-foreground font-mono">{acc.vpa}</div>
                </div>
              </div>
              <button
                onClick={() => handleRemoveAccount(acc.id)}
                className="text-destructive hover:text-destructive/80 p-1.5 rounded-lg hover:bg-destructive/10"
              >
                <Trash2 className="size-4" />
              </button>
            </div>
          ))}
        </div>

        {/* Add Account form */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 pt-2">
          <div className="space-y-1">
            <Label className="text-[10px] text-muted-foreground">Account Name</Label>
            <Input
              type="text"
              placeholder="e.g. HDFC Bank Primary"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              className="h-9 text-xs"
            />
          </div>
          <div className="space-y-1">
            <Label className="text-[10px] text-muted-foreground">UPI ID / VPA Handle</Label>
            <Input
              type="text"
              placeholder="e.g. store@hdfc"
              value={newVpa}
              onChange={(e) => setNewVpa(e.target.value)}
              className="h-9 text-xs font-mono"
            />
          </div>
          <div className="flex items-end">
            <IconAction label="Add UPI Handle" icon={<Plus className="size-3.5" />} onClick={handleAddAccount}
              className="w-full h-9 rounded-xl text-xs font-bold bg-primary hover:bg-primary/90 text-primary-foreground gap-1.5" />
          </div>
        </div>
      </div>

      {/* 1-Click Industry Presets Grid */}
      <div className="space-y-4">
        <h2 className="text-sm font-bold text-foreground flex items-center gap-2">
          <Sparkles className="size-4 text-primary" />
          Select Business Industry Preset (19 Enterprise Templates Supported)
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {INDUSTRY_TEMPLATES.map((tmpl) => {
            const isSelected = selectedTemplate === tmpl.id;
            return (
              <div
                key={tmpl.id}
                onClick={() => handleApplyTemplate(tmpl.id)}
                className={`p-4 rounded-2xl border transition-all cursor-pointer flex flex-col justify-between space-y-3 ${
                  isSelected
                    ? "bg-card border-primary shadow-sm"
                    : "bg-card/50 border-border hover:border-border/80"
                }`}
              >
                <div>
                  <div className="flex items-center justify-between">
                    <h3 className="font-bold text-foreground text-sm">{tmpl.label}</h3>
                    {isSelected && <Check className="size-4 text-primary" />}
                  </div>
                  <p className="text-xs text-muted-foreground mt-1.5 leading-relaxed">{tmpl.desc}</p>
                </div>
                <Button
                  size="sm"
                  disabled={saving || isSelected}
                  className={`w-full rounded-xl text-xs font-bold ${
                    isSelected
                      ? "bg-primary text-primary-foreground"
                      : "bg-muted text-muted-foreground hover:bg-muted/80 border border-border"
                  }`}
                >
                  {isSelected ? "Active Master Template" : "Set As Master Template"}
                </Button>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useWorkspace } from '@/hooks/use-workspace';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { BulkEntryDialog } from '@/components/ui/bulk-entry-dialog';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Clock, Plus, Layers, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { IconAction } from "@/components/ui/icon-action";

export default function ShiftsPage() {
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can('people_manage');

  const [shifts, setShifts] = useState<any[]>([]);
  const [, setAssignments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [bulkAddOpen, setBulkAddOpen] = useState(false);

  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [startTime, setStartTime] = useState('09:30');
  const [endTime, setEndTime] = useState('18:30');
  const [gracePeriod, setGracePeriod] = useState('15');

  /** Posts through the same API route the single-add form uses, so
   *  validation and permission checks are identical. Sequential because
   *  the route takes one record per call. */
  const bulkAdd = async (rows: Record<string, string>[]) => {
    const failures: string[] = [];
    for (const r of rows) {
      const res = await fetch('/api/hr/shifts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workspaceId: activeWorkspace!.id, name: r.name.trim(), code: r.code?.trim() || null, startTime: r.startTime.trim(), endTime: r.endTime.trim() }),
      });
      if (!res.ok) {
        const j = await res.json().catch(() => ({}));
        failures.push(`${r.name}: ${j.error || res.statusText}`);
      }
    }
    fetchShifts();
    if (failures.length > 0) {
      // Partial success is reported honestly rather than as a flat failure.
      throw new Error(
        `${rows.length - failures.length} of ${rows.length} added. Failed: ${failures.slice(0, 3).join('; ')}`
      );
    }
    toast.success(`Added ${rows.length} shift${rows.length === 1 ? '' : 's'}.`);
  };

  const fetchShifts = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const res = await fetch(`/api/hr/shifts?workspaceId=${activeWorkspace.id}`);
      const json = await res.json();
      setShifts(json.shifts || []);
      setAssignments(json.assignments || []);
    } catch {
      toast.error('Failed to load shifts');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id]);

  useEffect(() => {
    fetchShifts();
  }, [fetchShifts]);

  const handleCreateShift = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !startTime || !endTime) return;
    if (!activeWorkspace?.id) return;

    setSaving(true);
    try {
      const res = await fetch('/api/hr/shifts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspaceId: activeWorkspace.id,
          name,
          code,
          startTime,
          endTime,
          gracePeriod
        })
      });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      toast.success('Shift created successfully');
      setName('');
      setCode('');
      setModalOpen(false);
      fetchShifts();
    } catch (err: any) {
      toast.error(err.message || 'Failed to create shift');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Shifts & Work Schedules"
        description="Configure work shifts, start/end hours and grace periods."
        action={
          canManage && (
            <div className="flex items-center gap-2">
              <IconAction label="Bulk add" icon={<Layers className="size-4 " />} variant="outline" onClick={() => setBulkAddOpen(true)} />
              <IconAction label="Add Shift" icon={<Plus className="size-4 " />} onClick={() => setModalOpen(true)} className="bg-primary text-primary-foreground" />
            </div>
          )
        }
      />

      {loading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="size-8 animate-spin text-primary" />
        </div>
      ) : shifts.length === 0 ? (
        <Card className="border-border bg-card shadow-sm">
          <CardContent className="flex flex-col items-center justify-center py-16 text-center">
            <Clock className="size-12 text-muted-foreground opacity-20 mb-4" />
            <h3 className="text-lg font-semibold text-foreground mb-1">No Shifts Defined</h3>
            <p className="text-sm text-muted-foreground max-w-sm mb-6">
              Define work shift schedules (e.g. General Shift, Night Shift) for attendance tracking.
            </p>
            {canManage && (
              <IconAction label="Create First Shift" icon={<Plus className="size-4 " />} onClick={() => setModalOpen(true)} />
            )}
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {shifts.map(s => (
            <Card key={s.id} className="border-border bg-card shadow-sm">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <Badge variant="outline" className="text-xs uppercase font-mono bg-primary/10 text-primary border-primary/20">
                    {s.code}
                  </Badge>
                  <span className="text-xs text-muted-foreground">Grace: {s.grace_period_minutes}m</span>
                </div>
                <CardTitle className="text-base font-semibold mt-2">{s.name}</CardTitle>
                <CardDescription className="text-xs flex items-center gap-1.5 mt-1 font-mono text-foreground">
                  <Clock className="size-3.5 text-emerald-500" />
                  <span>{s.start_time} – {s.end_time}</span>
                </CardDescription>
              </CardHeader>
              <CardContent className="pt-0 text-xs text-muted-foreground border-t border-border/50 flex items-center justify-between mt-3 pt-3">
                <span>{s.is_rotational ? '🔄 Rotational' : '📌 Fixed Shift'}</span>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Create Shift Modal */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create Work Shift</DialogTitle>
            <DialogDescription>Define shift start/end times and late grace period.</DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateShift} className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Shift Name</Label>
              <Input placeholder="e.g. Morning Shift A" value={name} onChange={e => setName(e.target.value)} required />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Shift Code</Label>
                <Input placeholder="MS-A" value={code} onChange={e => setCode(e.target.value)} />
              </div>
              <div className="space-y-2">
                <Label>Grace Period (Mins)</Label>
                <Input type="number" value={gracePeriod} onChange={e => setGracePeriod(e.target.value)} />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Start Time</Label>
                <Input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} required />
              </div>
              <div className="space-y-2">
                <Label>End Time</Label>
                <Input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} required />
              </div>
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => setModalOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={saving}>
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null} Create Shift
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <BulkEntryDialog
        open={bulkAddOpen}
        onOpenChange={setBulkAddOpen}
        title="Add several shifts"
        scope="shifts"
        workspaceId={activeWorkspace?.id}
        noun="shift"
        columns={[
          { key: 'name', label: 'Shift name', required: true, placeholder: 'General' },
          { key: 'code', label: 'Code', placeholder: 'GEN' },
          { key: 'startTime', label: 'Start (HH:MM)', required: true, placeholder: '09:30' },
          { key: 'endTime', label: 'End (HH:MM)', required: true, placeholder: '18:30' },
        ]}
        onSubmit={bulkAdd}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo, Fragment } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from '@/components/ui/dropdown-menu';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Search,
  Loader2,
  CheckSquare,
  MoreHorizontal,
  Plus,
  Calendar,
  AlertCircle,
  List,
  Layers,
  ChevronRight,
  ChevronDown,
  CornerDownRight,
  FolderKanban,
  ChevronsUpDown,
  Filter,
  CheckCircle2,
  Sparkles,
  Bookmark,
  Pencil
} from 'lucide-react';
import { PageHeader } from '@/components/shared/page-header';
import { useWorkspace } from '@/hooks/use-workspace';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { TaskForm } from '@/components/tasks/task-form';
import { IconAction } from "@/components/ui/icon-action";

type ViewMode = 'list' | 'hierarchy';

export default function GlobalTasksPage() {
  const supabase = createClient();
  const { activeWorkspace, activeMember } = useWorkspace();

  const [tasks, setTasks] = useState<any[]>([]);
  const [epics, setEpics] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [typeFilter, setTypeFilter] = useState('ALL');
  const [viewMode, setViewMode] = useState<ViewMode>('hierarchy');

  const [formOpen, setFormOpen] = useState(false);
  const [editTask, setEditTask] = useState<any | null>(null);

  // Expansion states for 4-Level Hierarchy View: Project -> Epic -> Task -> Subtask
  const [expandedProjects, setExpandedProjects] = useState<Record<string, boolean>>({});
  const [expandedEpics, setExpandedEpics] = useState<Record<string, boolean>>({});
  const [expandedParents, setExpandedParents] = useState<Record<string, boolean>>({});

  const fetchTasks = useCallback(async () => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    setLoading(true);

    try {
      // 1. Fetch Epics
      const { data: epicsData, error: epicsErr } = await supabase
        .from('epics')
        .select('id, name, project_id');

      if (epicsErr) {
        console.warn('Epics query warning:', epicsErr);
      }
      setEpics(epicsData || []);

      // 2. Fetch Tasks assigned to user
      const { data, error } = await supabase
        .from('tasks')
        .select(`
          *,
          project:projects!tasks_project_id_fkey ( id, name ),
          epic:epics!tasks_epic_id_fkey ( id, name ),
          assignee:workspace_members!tasks_assigned_workspace_member_id_fkey (
            id, user_id
          )
        `)
        .eq('workspace_id', activeWorkspace.id)
        .eq('assigned_workspace_member_id', activeMember.id)
        .order('due_date', { ascending: true, nullsFirst: false });

      if (error) {
        toast.error('Failed to load tasks');
      } else {
        const taskList = data || [];
        const assigneeUserIds = taskList.map((t: any) => t.assignee?.user_id).filter(Boolean);
        if (assigneeUserIds.length > 0) {
          const { data: profilesData } = await supabase
            .from('profiles')
            .select('user_id, full_name, avatar_url')
            .in('user_id', assigneeUserIds);
          const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
          taskList.forEach((t: any) => {
            if (t.assignee?.user_id) t.assignee.profiles = profileMap[t.assignee.user_id] || null;
          });
        }
        setTasks(taskList);

        // Default all expanded
        const initialProj: Record<string, boolean> = {};
        const initialEpic: Record<string, boolean> = {};
        const initialPar: Record<string, boolean> = {};

        taskList.forEach((t: any) => {
          const projId = t.project_id || 'unassigned';
          const epicKey = `${projId}:${t.epic_id || 'no-epic'}`;
          initialProj[projId] = true;
          initialEpic[epicKey] = true;
          if (!t.parent_id) {
            initialPar[t.id] = true;
          }
        });

        setExpandedProjects(initialProj);
        setExpandedEpics(initialEpic);
        setExpandedParents(initialPar);
      }
    } catch {
      toast.error('Error fetching data');
    } finally {
      setLoading(false);
    }
  }, [supabase, activeWorkspace?.id, activeMember?.id]);

  useEffect(() => {
    fetchTasks();
  }, [fetchTasks]);

  const handleStatusChange = async (id: string, status: string) => {
    try {
      const payload: any = { status };
      if (status === 'completed') payload.completed_at = new Date().toISOString();
      else payload.completed_at = null;

      const { error } = await supabase.from('tasks').update(payload).eq('id', id);
      if (error) throw error;
      toast.success('Task status updated');
      fetchTasks();
    } catch {
      toast.error('Failed to update status');
    }
  };

  const handlePriorityChange = async (id: string, priority: string) => {
    try {
      const { error } = await supabase.from('tasks').update({ priority }).eq('id', id);
      if (error) throw error;
      toast.success('Priority updated');
      fetchTasks();
    } catch {
      toast.error('Failed to update priority');
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority?.toLowerCase()) {
      case 'urgent': return 'text-red-600 bg-red-500/15 border-red-200 hover:bg-red-500/25';
      case 'high': return 'text-orange-600 bg-orange-500/15 border-orange-200 hover:bg-orange-500/25';
      case 'medium': return 'text-blue-600 bg-blue-500/15 border-blue-200 hover:bg-blue-500/25';
      case 'low': return 'text-muted-foreground bg-muted/15 border-border hover:bg-muted/30';
      default: return 'text-muted-foreground bg-muted/15 border-border hover:bg-muted/30';
    }
  };

  const getStatusColor = (status?: string) => {
    const s = (status || 'todo').toLowerCase();
    switch (s) {
      case 'completed': return 'bg-emerald-500/15 text-emerald-700 border-emerald-200 hover:bg-emerald-500/25';
      case 'in_progress': return 'bg-blue-500/15 text-blue-700 border-blue-200 hover:bg-blue-500/25';
      case 'review': return 'bg-purple-500/15 text-purple-700 border-purple-200 hover:bg-purple-500/25';
      default: return 'bg-muted/15 text-foreground border-border hover:bg-muted/30';
    }
  };

  // Filter tasks based on search, status, and type
  const filteredTasks = useMemo(() => {
    return tasks.filter((t) => {
      const matchesSearch = !search.trim() || t.title?.toLowerCase().includes(search.trim().toLowerCase());
      const matchesStatus = statusFilter === 'ALL' || (t.status || 'todo').toLowerCase() === statusFilter.toLowerCase();
      const matchesType = typeFilter === 'ALL' || (t.task_type || 'PROJECT').toUpperCase() === typeFilter.toUpperCase();
      return matchesSearch && matchesStatus && matchesType;
    });
  }, [tasks, search, statusFilter, typeFilter]);

  // 4-Level Hierarchy Grouping: Project -> Epic -> Parent Task -> Subtask
  const hierarchyData = useMemo(() => {
    // 1. Map parent IDs to subtasks
    const subtaskMap = new Map<string, any[]>();
    filteredTasks.forEach((t) => {
      if (t.parent_id) {
        const list = subtaskMap.get(t.parent_id) || [];
        list.push(t);
        subtaskMap.set(t.parent_id, list);
      }
    });

    // 2. Filter top-level tasks (tasks with no parent, OR subtasks whose parent isn't in filtered list)
    const topLevelTasks = filteredTasks.filter((t) => {
      if (!t.parent_id) return true;
      return !filteredTasks.some((parent) => parent.id === t.parent_id);
    });

    // 3. Group by Project
    const projectMap = new Map<string, { id: string; name: string; tasks: any[] }>();
    topLevelTasks.forEach((t) => {
      const projId = t.project_id || 'unassigned';
      const projName = t.project ? t.project.name : 'General & Personal To-dos';
      if (!projectMap.has(projId)) {
        projectMap.set(projId, { id: projId, name: projName, tasks: [] });
      }
      projectMap.get(projId)!.tasks.push({
        ...t,
        subtasks: subtaskMap.get(t.id) || []
      });
    });

    // 4. Group each project's top-level tasks by Epic
    const epicMap = new Map<string, any>(epics.map((e) => [e.id, e]));

    return Array.from(projectMap.values()).map((projectGroup) => {
      const epicGroupMap = new Map<string, { id: string; key: string; name: string; isGeneral: boolean; tasks: any[] }>();

      projectGroup.tasks.forEach((task) => {
        const epicId = task.epic_id || 'no-epic';
        const epicKey = `${projectGroup.id}:${epicId}`;
        const epicObj = epicMap.get(task.epic_id) || task.epic;
        const epicName = epicObj?.name ? epicObj.name : (task.epic_id ? 'Untitled Epic' : 'General Tasks (No Epic)');

        if (!epicGroupMap.has(epicKey)) {
          epicGroupMap.set(epicKey, {
            id: epicId,
            key: epicKey,
            name: epicName,
            isGeneral: !task.epic_id,
            tasks: []
          });
        }
        epicGroupMap.get(epicKey)!.tasks.push(task);
      });

      let projTotal = 0;
      let projCompleted = 0;

      const epicGroups = Array.from(epicGroupMap.values()).map((epicGroup) => {
        epicGroup.tasks.forEach((t) => {
          projTotal += 1;
          if (t.status === 'completed') projCompleted += 1;
          (t.subtasks || []).forEach((st: any) => {
            projTotal += 1;
            if (st.status === 'completed') projCompleted += 1;
          });
        });
        return epicGroup;
      });

      return {
        id: projectGroup.id,
        name: projectGroup.name,
        totalCount: projTotal,
        completedCount: projCompleted,
        epics: epicGroups
      };
    });
  }, [filteredTasks, epics]);

  const toggleProjectExpand = (projId: string) => {
    setExpandedProjects((prev) => ({ ...prev, [projId]: !prev[projId] }));
  };

  const toggleEpicExpand = (epicKey: string) => {
    setExpandedEpics((prev) => ({ ...prev, [epicKey]: !prev[epicKey] }));
  };

  const toggleParentExpand = (taskId: string) => {
    setExpandedParents((prev) => ({ ...prev, [taskId]: !prev[taskId] }));
  };

  const toggleExpandAll = () => {
    const allProjExpanded = Object.values(expandedProjects).every(Boolean);
    const nextState = !allProjExpanded;
    const newProj: Record<string, boolean> = {};
    const newEpic: Record<string, boolean> = {};
    const newPar: Record<string, boolean> = {};

    hierarchyData.forEach((projectGroup) => {
      newProj[projectGroup.id] = nextState;
      projectGroup.epics.forEach((epicGroup) => {
        newEpic[epicGroup.key] = nextState;
        epicGroup.tasks.forEach((t) => {
          newPar[t.id] = nextState;
        });
      });
    });

    setExpandedProjects(newProj);
    setExpandedEpics(newEpic);
    setExpandedParents(newPar);
  };

  // Helper to render task row (and nested subtasks if any)
  const renderTaskRow = (task: any, isSubtask = false) => {
    const isOverdue = task.status !== 'completed' && task.due_date && new Date(task.due_date) < new Date();
    const hasSubtasks = task.subtasks && task.subtasks.length > 0;
    const isExpanded = !!expandedParents[task.id];

    return (
      <Fragment key={task.id}>
        <TableRow className={`border-border hover:bg-muted/50 ${isSubtask ? 'bg-muted/20' : ''}`}>
          <TableCell>
            <div className={`flex items-center gap-2 ${isSubtask ? 'pl-6' : ''}`}>
              {isSubtask ? (
                <CornerDownRight className="size-3.5 text-muted-foreground shrink-0" />
              ) : hasSubtasks ? (
                <button
                  type="button"
                  onClick={() => toggleParentExpand(task.id)}
                  className="p-0.5 rounded hover:bg-muted text-muted-foreground transition-colors shrink-0 cursor-pointer border-0 bg-transparent"
                >
                  {isExpanded ? <ChevronDown className="size-4" /> : <ChevronRight className="size-4" />}
                </button>
              ) : (
                <div className="w-5 shrink-0" />
              )}

              <div className="flex flex-col">
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => { setEditTask(task); setFormOpen(true); }}
                    className={`font-medium text-sm text-foreground text-left hover:text-primary transition-colors cursor-pointer border-0 bg-transparent p-0 ${
                      task.status === 'completed' ? 'line-through text-muted-foreground' : ''
                    }`}
                  >
                    {task.title}
                  </button>
                  {hasSubtasks && (
                    <Badge variant="secondary" className="text-[10px] px-1.5 py-0 font-normal">
                      {task.subtasks.length} {task.subtasks.length === 1 ? 'subtask' : 'subtasks'}
                    </Badge>
                  )}
                </div>
                <span className="text-xs text-muted-foreground capitalize flex items-center gap-1 mt-0.5">
                  {(task.task_type || 'task').toLowerCase()} Task
                </span>
              </div>
            </div>
          </TableCell>

          <TableCell className="text-sm text-muted-foreground hidden md:table-cell">
            {task.project ? task.project.name : '-'}
          </TableCell>

          {/* Priority Column - Interactive Dropdown */}
          <TableCell className="hidden sm:table-cell">
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <button
                    type="button"
                    className={cn(
                      "inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-semibold uppercase border transition-colors cursor-pointer select-none",
                      getPriorityColor(task.priority)
                    )}
                  >
                    <span>{task.priority || 'medium'}</span>
                    <ChevronDown className="size-2.5 opacity-70" />
                  </button>
                }
              />
              <DropdownMenuContent align="start" className="w-32 bg-popover border-border">
                <DropdownMenuItem onClick={() => handlePriorityChange(task.id, 'low')} className="cursor-pointer">
                  Low
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handlePriorityChange(task.id, 'medium')} className="cursor-pointer">
                  Medium
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handlePriorityChange(task.id, 'high')} className="cursor-pointer">
                  High
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handlePriorityChange(task.id, 'urgent')} className="text-red-600 focus:text-red-700 font-medium cursor-pointer">
                  Urgent
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </TableCell>

          {/* Status Column - Interactive Dropdown */}
          <TableCell>
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <button
                    type="button"
                    className={cn(
                      "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold uppercase border transition-colors cursor-pointer select-none",
                      getStatusColor(task.status)
                    )}
                  >
                    <span>{(task.status || 'todo').replace('_', ' ')}</span>
                    <ChevronDown className="size-3 opacity-70" />
                  </button>
                }
              />
              <DropdownMenuContent align="start" className="w-36 bg-popover border-border">
                <DropdownMenuItem onClick={() => handleStatusChange(task.id, 'todo')} className="cursor-pointer">
                  To Do
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleStatusChange(task.id, 'in_progress')} className="cursor-pointer">
                  In Progress
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleStatusChange(task.id, 'review')} className="cursor-pointer">
                  In Review
                </DropdownMenuItem>
                <DropdownMenuItem
                  onClick={() => handleStatusChange(task.id, 'completed')}
                  className="text-emerald-600 focus:text-emerald-700 font-medium cursor-pointer"
                >
                  Completed (Done)
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </TableCell>

          <TableCell className="hidden lg:table-cell">
            {task.due_date ? (
              <span className={`flex items-center gap-1.5 text-sm ${isOverdue ? 'text-red-500 font-medium' : 'text-muted-foreground'}`}>
                {isOverdue ? <AlertCircle className="size-3.5" /> : <Calendar className="size-3.5" />}
                {new Date(task.due_date).toLocaleDateString()}
              </span>
            ) : (
              <span className="text-muted-foreground">-</span>
            )}
          </TableCell>

          <TableCell>
            <div className="flex items-center gap-1">
              <IconAction
                label="Edit Task"
                icon={<Pencil className="size-3.5" />}
                variant="ghost"
                onClick={() => { setEditTask(task); setFormOpen(true); }}
                className="h-7 w-7 text-muted-foreground hover:text-foreground"
              />

              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <button
                      type="button"
                      className="inline-flex items-center justify-center rounded-md h-7 w-7 text-muted-foreground hover:text-foreground hover:bg-muted focus-visible:outline-none border-0 bg-transparent cursor-pointer"
                    >
                      <MoreHorizontal className="size-4" />
                    </button>
                  }
                />
                <DropdownMenuContent align="end" className="bg-popover border-border">
                  <DropdownMenuItem onClick={() => { setEditTask(task); setFormOpen(true); }} className="cursor-pointer">
                    Edit Details
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem onClick={() => handleStatusChange(task.id, 'todo')} className="cursor-pointer">
                    Mark as To Do
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => handleStatusChange(task.id, 'in_progress')} className="cursor-pointer">
                    Mark as In Progress
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => handleStatusChange(task.id, 'review')} className="cursor-pointer">
                    Mark for Review
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    onClick={() => handleStatusChange(task.id, 'completed')}
                    className="text-emerald-600 focus:text-emerald-700 cursor-pointer"
                  >
                    Mark as Completed
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </TableCell>
        </TableRow>

        {/* Render Level 4 Subtasks if parent is expanded */}
        {!isSubtask && hasSubtasks && isExpanded && (
          task.subtasks.map((sub: any) => renderTaskRow(sub, true))
        )}
      </Fragment>
    );
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="My Tasks"
        description="Manage your assigned deliverables across Projects, Epics, Tasks, and Subtasks."
        action={
          <IconAction label="New Task" icon={<Plus className="size-4 " />} onClick={() => { setEditTask(null); setFormOpen(true); }} className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm" />
        }
      />

      {/* Toolbar & View Switcher */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-2 flex-1">
          {/* Search */}
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search tasks..."
              className="pl-8 bg-card border-border text-foreground placeholder:text-muted-foreground h-9"
            />
          </div>

          {/* Status Filter */}
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-36 h-9 bg-card border-border">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ALL">All Statuses</SelectItem>
              <SelectItem value="todo">To Do</SelectItem>
              <SelectItem value="in_progress">In Progress</SelectItem>
              <SelectItem value="review">In Review</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
            </SelectContent>
          </Select>

          {/* Type Filter */}
          <Select value={typeFilter} onValueChange={setTypeFilter}>
            <SelectTrigger className="w-36 h-9 bg-card border-border">
              <SelectValue placeholder="Task Type" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ALL">All Types</SelectItem>
              <SelectItem value="PROJECT">Project Task</SelectItem>
              <SelectItem value="GENERAL">General Task</SelectItem>
              <SelectItem value="SUPPORT">Support</SelectItem>
              <SelectItem value="ADMIN">Admin</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* View Switcher Controls */}
        <div className="flex items-center gap-2 self-end sm:self-auto">
          {viewMode === 'hierarchy' && (
            <IconAction label="Toggle All" icon={<ChevronsUpDown className="size-3.5 " />} variant="outline"
              onClick={toggleExpandAll}
              className="h-9 px-2.5 text-xs border-border"
              title="Expand or collapse all groups" />
          )}

          <div className="flex items-center rounded-lg border border-border bg-card p-1 gap-1">
            <button
              type="button"
              onClick={() => setViewMode('hierarchy')}
              className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-md text-xs font-medium transition-colors cursor-pointer border-0 ${
                viewMode === 'hierarchy'
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted bg-transparent'
              }`}
            >
              <Layers className="size-3.5" />
              Hierarchy
            </button>
            <button
              type="button"
              onClick={() => setViewMode('list')}
              className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-md text-xs font-medium transition-colors cursor-pointer border-0 ${
                viewMode === 'list'
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted bg-transparent'
              }`}
            >
              <List className="size-3.5" />
              List
            </button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      {loading ? (
        <div className="rounded-lg border border-border bg-card py-16 flex flex-col items-center justify-center gap-2">
          <Loader2 className="size-6 animate-spin text-primary" />
          <span className="text-xs text-muted-foreground">Loading tasks...</span>
        </div>
      ) : filteredTasks.length === 0 ? (
        <div className="rounded-lg border border-border bg-card py-16 flex flex-col items-center justify-center gap-2 text-center">
          <CheckSquare className="size-8 text-muted-foreground" />
          <p className="text-sm font-medium text-foreground">No tasks found</p>
          <p className="text-xs text-muted-foreground max-w-sm">
            {search || statusFilter !== 'ALL' || typeFilter !== 'ALL'
              ? 'Try adjusting your filters or search query.'
              : 'You have no assigned tasks in this workspace.'}
          </p>
        </div>
      ) : viewMode === 'list' ? (
        /* FLAT LIST VIEW */
        <div className="rounded-lg border border-border overflow-hidden bg-card">
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-muted-foreground">Task</TableHead>
                <TableHead className="text-muted-foreground hidden md:table-cell">Project Context</TableHead>
                <TableHead className="text-muted-foreground hidden sm:table-cell">Priority</TableHead>
                <TableHead className="text-muted-foreground">Status</TableHead>
                <TableHead className="text-muted-foreground hidden lg:table-cell">Due Date</TableHead>
                <TableHead className="text-muted-foreground w-16 text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredTasks.map((task) => renderTaskRow(task, false))}
            </TableBody>
          </Table>
        </div>
      ) : (
        /* 4-LEVEL HIERARCHY TREE VIEW: PROJECT -> EPIC -> TASK -> SUBTASK */
        <div className="space-y-6">
          {hierarchyData.map((projectGroup) => {
            const isProjectExpanded = expandedProjects[projectGroup.id] ?? true;

            return (
              <div key={projectGroup.id} className="rounded-lg border border-border bg-card overflow-hidden shadow-xs">
                {/* Level 1: Project Header Bar */}
                <div
                  onClick={() => toggleProjectExpand(projectGroup.id)}
                  className="flex items-center justify-between px-4 py-3 bg-muted/40 hover:bg-muted/70 cursor-pointer select-none border-b border-border/60 transition-colors"
                >
                  <div className="flex items-center gap-2">
                    {isProjectExpanded ? (
                      <ChevronDown className="size-4 text-muted-foreground" />
                    ) : (
                      <ChevronRight className="size-4 text-muted-foreground" />
                    )}
                    <FolderKanban className="size-4 text-primary" />
                    <span className="font-semibold text-sm text-foreground">{projectGroup.name}</span>
                    <Badge variant="secondary" className="text-xs font-normal">
                      {projectGroup.totalCount} {projectGroup.totalCount === 1 ? 'item' : 'items'}
                    </Badge>
                  </div>

                  <div className="flex items-center gap-3 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1 font-medium">
                      <CheckCircle2 className="size-3.5 text-emerald-500" />
                      {projectGroup.completedCount} / {projectGroup.totalCount} completed
                    </span>
                  </div>
                </div>

                {/* Level 2: Epics inside Project */}
                {isProjectExpanded && (
                  <div className="p-3 space-y-4 bg-background/50">
                    {projectGroup.epics.map((epicGroup) => {
                      const isEpicExpanded = expandedEpics[epicGroup.key] ?? true;

                      return (
                        <div key={epicGroup.key} className="rounded-md border border-border/70 overflow-hidden bg-card">
                          {/* Level 2: Epic Header */}
                          <div
                            onClick={() => toggleEpicExpand(epicGroup.key)}
                            className="flex items-center justify-between px-3 py-2 bg-muted/20 hover:bg-muted/40 cursor-pointer select-none border-b border-border/40 transition-colors"
                          >
                            <div className="flex items-center gap-2">
                              {isEpicExpanded ? (
                                <ChevronDown className="size-3.5 text-muted-foreground" />
                              ) : (
                                <ChevronRight className="size-3.5 text-muted-foreground" />
                              )}
                              {epicGroup.isGeneral ? (
                                <Bookmark className="size-3.5 text-muted-foreground" />
                              ) : (
                                <Sparkles className="size-3.5 text-purple-500" />
                              )}
                              <span className={`text-xs font-medium ${epicGroup.isGeneral ? 'text-muted-foreground' : 'text-purple-600 dark:text-purple-400 font-semibold'}`}>
                                {epicGroup.isGeneral ? epicGroup.name : `Epic: ${epicGroup.name}`}
                              </span>
                              <Badge variant="outline" className="text-[10px] px-1.5 py-0">
                                {epicGroup.tasks.length} {epicGroup.tasks.length === 1 ? 'task' : 'tasks'}
                              </Badge>
                            </div>
                          </div>

                          {/* Level 3 & Level 4: Tasks & Subtasks Table */}
                          {isEpicExpanded && (
                            <Table>
                              <TableHeader>
                                <TableRow className="border-border hover:bg-transparent bg-muted/10">
                                  <TableHead className="text-muted-foreground text-xs">Task & Subtask</TableHead>
                                  <TableHead className="text-muted-foreground text-xs hidden md:table-cell">Project Context</TableHead>
                                  <TableHead className="text-muted-foreground text-xs hidden sm:table-cell">Priority</TableHead>
                                  <TableHead className="text-muted-foreground text-xs">Status</TableHead>
                                  <TableHead className="text-muted-foreground text-xs hidden lg:table-cell">Due Date</TableHead>
                                  <TableHead className="text-muted-foreground text-xs w-16 text-right">Actions</TableHead>
                                </TableRow>
                              </TableHeader>
                              <TableBody>
                                {epicGroup.tasks.length === 0 ? (
                                  <TableRow className="border-border">
                                    <TableCell colSpan={6} className="text-center py-4 text-xs text-muted-foreground">
                                      No tasks under this epic.
                                    </TableCell>
                                  </TableRow>
                                ) : (
                                  epicGroup.tasks.map((task) => renderTaskRow(task, false))
                                )}
                              </TableBody>
                            </Table>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      <TaskForm
        open={formOpen}
        onOpenChange={setFormOpen}
        task={editTask}
        onSaved={fetchTasks}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/components/ui/tabs';
import { Loader2, Clock, Plus, AlertCircle, BarChart3, ChevronDown, Calendar, Trash2, Search, X } from 'lucide-react';
import { PageHeader } from '@/components/shared/page-header';
import { useWorkspace } from '@/hooks/use-workspace';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { TimeLogForm } from '@/components/timesheets/time-log-form';
import { formatMemberName } from '@/components/tasks/task-form';
import { IconAction } from "@/components/ui/icon-action";

export default function TimesheetsPage() {
  const supabase = createClient();
  const { activeWorkspace, activeMember, can } = useWorkspace();
  const canManageTimesheets = can('attendance_manage') || can('people_manage'); 

  const [myLogs, setMyLogs] = useState<any[]>([]);
  const [teamTimesheets, setTeamTimesheets] = useState<any[]>([]);
  
  const [loading, setLoading] = useState(true);
  const [formOpen, setFormOpen] = useState(false);

  // Calendar / Date Filters
  const [selectedDateFilter, setSelectedDateFilter] = useState<string>(''); // YYYY-MM-DD
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Date filters for team aggregation (Default to today)
  const [reportDate, setReportDate] = useState(new Date().toISOString().split('T')[0]);

  // Track collapsed date groups
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});

  const fetchMyLogs = useCallback(async () => {
    if (!activeWorkspace?.id || !activeMember?.id) return;

    const { data, error } = await supabase
      .from('time_logs')
      .select(`
        *,
        task:tasks!time_logs_task_id_fkey ( title, project_id, project:projects!tasks_project_id_fkey ( name ) )
      `)
      .eq('workspace_id', activeWorkspace.id)
      .eq('workspace_member_id', activeMember.id)
      .order('log_date', { ascending: false })
      .order('created_at', { ascending: false })
      .limit(200);

    if (error) toast.error('Failed to load your time logs');
    else setMyLogs(data || []);
  }, [supabase, activeWorkspace?.id, activeMember?.id]);

  const fetchTeamTimesheets = useCallback(async () => {
    if (!activeWorkspace?.id || !canManageTimesheets) return;

    try {
      const [membersRes, attRes, logsRes] = await Promise.all([
        fetch(`/api/account/members?workspace_id=${activeWorkspace.id}`).then((r) => r.json()).catch(() => ({ members: [] })),
        supabase.from('attendance').select('*').eq('workspace_id', activeWorkspace.id).eq('attendance_date', reportDate),
        supabase.from('time_logs').select('workspace_member_id, duration').eq('workspace_id', activeWorkspace.id).eq('log_date', reportDate)
      ]);

      const loadedMembers = membersRes?.members || [];
      const attList = attRes.data || [];
      const logList = logsRes.data || [];

      // Map logs by workspace_member_id
      const logMap: Record<string, number> = {};
      logList.forEach((log: any) => {
        if (!logMap[log.workspace_member_id]) logMap[log.workspace_member_id] = 0;
        logMap[log.workspace_member_id] += Number(log.duration) || 0;
      });

      // Map attendance by workspace_member_id
      const attMap: Record<string, any> = {};
      attList.forEach((att: any) => {
        attMap[att.workspace_member_id] = att;
      });

      // Aggregate for all team members
      const aggregated = loadedMembers.map((m: any) => {
        const att = attMap[m.id];
        const loggedTime = logMap[m.id] || 0;
        const attendanceHours = att?.working_hours || 0;

        return {
          member_id: m.id,
          name: formatMemberName(m),
          avatar: m.avatar_url,
          status: att?.status || 'OFF',
          attendanceHours,
          loggedTime,
          // Unlogged time = clocked minus logged. This was the other way
          // round, so the column labelled "Unlogged time" lit up orange for
          // people who had logged MORE than they clocked, and showed a green
          // surplus for the ones with an actual gap.
          discrepancy: attendanceHours - loggedTime
        };
      });

      setTeamTimesheets(aggregated);
    } catch (err) {
      console.error('Team timesheets fetch error:', err);
    }
  }, [supabase, activeWorkspace?.id, canManageTimesheets, reportDate]);

  const loadAll = useCallback(async () => {
    setLoading(true);
    await fetchMyLogs();
    if (canManageTimesheets) {
      await fetchTeamTimesheets();
    }
    setLoading(false);
  }, [fetchMyLogs, fetchTeamTimesheets, canManageTimesheets]);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  // Group myLogs by log_date
  const groupedLogs = useMemo(() => {
    const map = new Map<string, { dateKey: string; displayDate: string; totalHours: number; logs: any[] }>();

    myLogs.forEach((log) => {
      const dateKey = log.log_date; // YYYY-MM-DD
      if (!map.has(dateKey)) {
        // Parse date for clean display e.g. "Mon, Aug 3, 2026"
        const [year, month, day] = dateKey.split('-').map(Number);
        const dateObj = new Date(year, month - 1, day);
        const displayDate = dateObj.toLocaleDateString('en-US', {
          weekday: 'short',
          month: 'short',
          day: 'numeric',
          year: 'numeric',
        });
        map.set(dateKey, { dateKey, displayDate, totalHours: 0, logs: [] });
      }
      const group = map.get(dateKey)!;
      group.logs.push(log);
      group.totalHours += Number(log.duration || 0);
    });

    return Array.from(map.values());
  }, [myLogs]);

  // Filter grouped logs by calendar date or search query
  const filteredGroupedLogs = useMemo(() => {
    return groupedLogs.filter((group) => {
      if (selectedDateFilter && group.dateKey !== selectedDateFilter) {
        return false;
      }
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const matches = group.logs.some(
          (l) =>
            (l.task?.title || '').toLowerCase().includes(q) ||
            (l.description || '').toLowerCase().includes(q)
        );
        if (!matches) return false;
      }
      return true;
    });
  }, [groupedLogs, selectedDateFilter, searchQuery]);

  const toggleDate = (dateKey: string) => {
    setCollapsedDates((prev) => ({
      ...prev,
      [dateKey]: !prev[dateKey],
    }));
  };

  const handleDeleteLog = async (logId: string) => {
    try {
      const { error } = await supabase.from('time_logs').delete().eq('id', logId);
      if (error) throw error;
      toast.success('Time log deleted');
      setMyLogs((prev) => prev.filter((l) => l.id !== logId));
    } catch (err: any) {
      toast.error('Failed to delete time log');
    }
  };

  return (
    <div className="space-y-6">
      <PageHeader 
        title="Timesheets" 
        description="Log time against tasks and review team productivity."
        action={
          <IconAction label="Log Time" icon={<Plus className="size-4 " />} onClick={() => setFormOpen(true)} className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm" />
        }
      />

      <Tabs defaultValue="my-logs" className="w-full">
        <TabsList className="bg-muted w-full justify-start overflow-x-auto h-auto p-1 rounded-lg">
          <TabsTrigger value="my-logs" className="py-2 flex items-center gap-2">
            <Clock className="size-4" /> My Time Logs
          </TabsTrigger>
          {canManageTimesheets && (
            <TabsTrigger value="team" className="py-2 flex items-center gap-2">
              <BarChart3 className="size-4" /> Team Reports
            </TabsTrigger>
          )}
        </TabsList>

        <div className="mt-6">
          <TabsContent value="my-logs" className="m-0 focus-visible:outline-none focus-visible:ring-0">
            
            {/* Calendar & Search Toolbar */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 mb-4 p-3 bg-card border border-border rounded-xl shadow-xs">
              <div className="flex items-center gap-2.5 flex-wrap">
                <div className="flex items-center gap-2 bg-muted/50 border border-border px-3 py-1.5 rounded-lg text-xs font-semibold">
                  <Calendar className="size-4 text-primary shrink-0" />
                  <span className="text-foreground">Filter by Date:</span>
                  <Input
                    type="date"
                    value={selectedDateFilter}
                    onChange={(e) => setSelectedDateFilter(e.target.value)}
                    className="h-7 w-auto bg-background text-xs border-border px-2 py-0 cursor-pointer"
                  />
                </div>

                {selectedDateFilter && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => setSelectedDateFilter('')}
                    className="h-8 px-2.5 text-xs text-muted-foreground hover:text-foreground gap-1"
                  >
                    <X className="size-3.5" /> Show All Dates
                  </Button>
                )}
              </div>

              <div className="flex items-center gap-2">
                <div className="relative flex-1 sm:w-64">
                  <Search className="absolute left-2.5 top-2.5 size-3.5 text-muted-foreground" />
                  <Input
                    placeholder="Search task title or details..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="h-8 text-xs pl-8 bg-background border-border"
                  />
                  {searchQuery && (
                    <button
                      onClick={() => setSearchQuery('')}
                      className="absolute right-2.5 top-2.5 text-muted-foreground hover:text-foreground"
                    >
                      <X className="size-3.5" />
                    </button>
                  )}
                </div>
              </div>
            </div>

            {loading ? (
              <div className="rounded-xl border border-border bg-card py-16 text-center">
                <Loader2 className="size-6 animate-spin text-primary mx-auto" />
                <p className="text-xs text-muted-foreground mt-2">Loading your time logs...</p>
              </div>
            ) : filteredGroupedLogs.length === 0 ? (
              <div className="rounded-xl border border-dashed border-border bg-card py-16 text-center">
                <Clock className="size-8 text-muted-foreground/60 mx-auto" />
                <p className="mt-3 text-sm font-semibold text-foreground">
                  {selectedDateFilter ? `No time logs found for ${selectedDateFilter}` : 'No time logged yet'}
                </p>
                <p className="mt-1 text-xs text-muted-foreground">
                  {selectedDateFilter ? 'Click "Show All Dates" or select another date from the calendar.' : 'Click "Log Time" above to add your first entries for the day.'}
                </p>
                {selectedDateFilter && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setSelectedDateFilter('')}
                    className="mt-4 text-xs font-semibold"
                  >
                    Show All Dates
                  </Button>
                )}
              </div>
            ) : (
              <div className="space-y-3">
                {filteredGroupedLogs.map((group) => {
                  const isCollapsed = collapsedDates[group.dateKey] === true;

                  return (
                    <div key={group.dateKey} className="rounded-xl border border-border bg-card overflow-hidden transition-all shadow-xs">
                      
                      {/* Daily Header Summary Row */}
                      <div
                        onClick={() => toggleDate(group.dateKey)}
                        className="flex items-center justify-between px-5 py-3.5 bg-muted/40 hover:bg-muted/70 transition-colors cursor-pointer select-none border-b border-border/60"
                      >
                        <div className="flex items-center gap-3">
                          <button
                            type="button"
                            className="size-6 rounded-md bg-background border border-border flex items-center justify-center text-muted-foreground hover:text-foreground transition-transform"
                          >
                            <ChevronDown className={`size-4 transition-transform duration-200 ${isCollapsed ? '-rotate-90' : 'rotate-0'}`} />
                          </button>
                          <div className="flex items-center gap-2.5">
                            <Calendar className="size-4 text-primary" />
                            <span className="text-sm font-bold text-foreground">{group.displayDate}</span>
                            <Badge variant="outline" className="text-[11px] bg-background text-muted-foreground border-border font-medium">
                              {group.logs.length} {group.logs.length === 1 ? 'entry' : 'entries'}
                            </Badge>
                          </div>
                        </div>

                        <div className="flex items-center gap-3">
                          <Badge className="bg-primary/10 text-primary hover:bg-primary/15 border-primary/20 font-mono font-bold px-2.5 py-0.5 text-xs">
                            {group.totalHours.toFixed(1)} hrs logged
                          </Badge>
                        </div>
                      </div>

                      {/* Expandable Entries List */}
                      {!isCollapsed && (
                        <Table>
                          <TableHeader className="bg-muted/10">
                            <TableRow className="border-border hover:bg-transparent">
                              <TableHead className="text-xs text-muted-foreground pl-6">Task / Project</TableHead>
                              <TableHead className="text-xs text-muted-foreground">Description</TableHead>
                              <TableHead className="text-xs text-muted-foreground w-28">Hours</TableHead>
                              <TableHead className="text-xs text-muted-foreground w-24">Billable</TableHead>
                              <TableHead className="text-xs text-muted-foreground w-12 text-right pr-6"></TableHead>
                            </TableRow>
                          </TableHeader>
                          <TableBody>
                            {group.logs.map((log) => (
                              <TableRow key={log.id} className="border-border/60 hover:bg-muted/40 transition-colors">
                                <TableCell className="pl-6 py-3">
                                  <div className="flex flex-col">
                                    <span className="font-semibold text-foreground text-sm">{log.task?.title || 'General / Unassigned'}</span>
                                    {log.task?.project && (
                                      <span className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5 font-medium">
                                        {log.task.project.name}
                                      </span>
                                    )}
                                  </div>
                                </TableCell>
                                <TableCell className="text-xs text-muted-foreground max-w-sm truncate py-3" title={log.description || ''}>
                                  {log.description || <span className="italic opacity-60">No details provided</span>}
                                </TableCell>
                                <TableCell className="font-mono text-sm font-bold text-foreground py-3">
                                  {Number(log.duration ?? 0)}h
                                </TableCell>
                                <TableCell className="py-3">
                                  {log.billable ? (
                                    <Badge variant="outline" className="bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/30 text-[10px] uppercase font-bold">Billable</Badge>
                                  ) : (
                                    <span className="text-muted-foreground text-xs font-medium">-</span>
                                  )}
                                </TableCell>
                                <TableCell className="text-right pr-6 py-3">
                                  <Button
                                    type="button"
                                    variant="ghost"
                                    size="icon"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      handleDeleteLog(log.id);
                                    }}
                                    className="size-7 text-muted-foreground hover:text-rose-600 hover:bg-rose-500/10 rounded-lg"
                                    title="Delete entry"
                                  >
                                    <Trash2 className="size-3.5" />
                                  </Button>
                                </TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </TabsContent>

          {canManageTimesheets && (
            <TabsContent value="team" className="m-0 focus-visible:outline-none">
              <div className="mb-4 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Input 
                    type="date"
                    value={reportDate}
                    onChange={(e) => setReportDate(e.target.value)}
                    className="w-auto bg-card border-border"
                  />
                  <Button variant="outline" size="sm" onClick={fetchTeamTimesheets}>Run Report</Button>
                </div>
              </div>

              <div className="rounded-lg border border-border overflow-hidden bg-card">
                <Table>
                  <TableHeader>
                    <TableRow className="border-border hover:bg-transparent">
                      <TableHead className="text-muted-foreground">Employee</TableHead>
                      <TableHead className="text-muted-foreground">Attendance Status</TableHead>
                      <TableHead className="text-muted-foreground">Clocked Hours (GPS)</TableHead>
                      <TableHead className="text-muted-foreground">Task Hours Logged</TableHead>
                      <TableHead className="text-muted-foreground">Variance</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {loading ? (
                      <TableRow className="border-border">
                        <TableCell colSpan={5} className="text-center py-12">
                          <Loader2 className="size-6 animate-spin text-primary mx-auto" />
                        </TableCell>
                      </TableRow>
                    ) : teamTimesheets.length === 0 ? (
                      <TableRow className="border-border">
                        <TableCell colSpan={5} className="text-center py-12 text-muted-foreground">
                          No attendance data found for {new Date(reportDate).toLocaleDateString()}. Employees must punch in first.
                        </TableCell>
                      </TableRow>
                    ) : (
                      teamTimesheets.map((row) => (
                        <TableRow key={row.member_id} className="border-border hover:bg-muted/50">
                          <TableCell>
                            <div className="flex items-center gap-2">
                              <Avatar className="size-7 border border-border">
                                {row.avatar && <AvatarImage src={row.avatar} />}
                                <AvatarFallback className="bg-primary/10 text-primary text-xs">{row.name.charAt(0)}</AvatarFallback>
                              </Avatar>
                              <span className="font-medium text-foreground text-sm">{row.name}</span>
                            </div>
                          </TableCell>
                          <TableCell>
                            <Badge variant="outline" className={row.status === 'Absent' ? 'bg-red-500/15 text-red-700' : 'bg-blue-500/15 text-blue-700'}>
                              {row.status}
                            </Badge>
                          </TableCell>
                          <TableCell className="font-mono text-sm">{row.attendanceHours}h</TableCell>
                          <TableCell className="font-mono text-sm font-medium">{row.loggedTime}h</TableCell>
                          <TableCell>
                            {row.discrepancy > 0 ? (
                              <span className="flex items-center gap-1 text-orange-600 text-sm font-medium" title="Unlogged time">
                                <AlertCircle className="size-3.5" /> -{row.discrepancy}h
                              </span>
                            ) : row.discrepancy < 0 ? (
                              <span className="text-emerald-600 text-sm font-medium">
                                +{Math.abs(row.discrepancy)}h
                              </span>
                            ) : (
                              <span className="text-muted-foreground text-sm">Match</span>
                            )}
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </div>
            </TabsContent>
          )}
        </div>
      </Tabs>

      <TimeLogForm
        open={formOpen}
        onOpenChange={setFormOpen}
        onSaved={loadAll}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { Loader2, Activity, ChevronDown, ChevronRight, Briefcase } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { addDays, endOfDay, isAfter, isBefore, parseISO, startOfDay, addMonths } from 'date-fns';

import { formatMemberName } from '@/components/tasks/task-form';

type TimeHorizon = '7' | '14' | '30' | '90';

export default function WorkloadsPage() {
  const { activeWorkspace } = useWorkspace();
  const supabase = createClient();

  const [loading, setLoading] = useState(true);
  const [horizon, setHorizon] = useState<TimeHorizon>('7');
  const [workloadData, setWorkloadData] = useState<any[]>([]);
  const [expandedUsers, setExpandedUsers] = useState<Record<string, boolean>>({});

  const fetchGlobalWorkload = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      // 1. Fetch all members via API & workspace_members with capacity
      const [membersRes, { data: rawMembers, error: membersError }] = await Promise.all([
        fetch(`/api/account/members?workspace_id=${activeWorkspace.id}`).then(r => r.json()).catch(() => ({ members: [] })),
        supabase
          .from('workspace_members')
          .select('id, user_id, weekly_capacity')
          .eq('workspace_id', activeWorkspace.id)
      ]);

      if (membersError) throw membersError;

      const loadedMembers = membersRes?.members || [];
      const memberMapById = Object.fromEntries(loadedMembers.map((m: any) => [m.id, m]));

      const members: any[] = (rawMembers || []).map((m: any) => {
        const enriched = memberMapById[m.id] || m;
        return {
          ...m,
          displayName: formatMemberName(enriched),
          avatar: enriched.avatar_url || enriched.profiles?.avatar_url
        };
      });

      // 2. Fetch all active tasks across all projects
      const { data: tasks, error: tasksError } = await supabase
        .from('tasks')
        .select(`
          id,
          title,
          estimated_hours,
          start_date,
          due_date,
          assigned_workspace_member_id,
          project_id,
          projects ( name )
        `)
        .eq('workspace_id', activeWorkspace.id)
        .is('completed_at', null)
        .not('assigned_workspace_member_id', 'is', null);

      if (tasksError) throw tasksError;

      // Calculate dates
      const today = startOfDay(new Date());
      const endHorizon = endOfDay(addDays(today, parseInt(horizon) - 1));

      const memberMap = new Map<string, any>();

      // Initialize map
      members?.forEach(m => {
        // Default capacity to 40 if not set. Calculate capacity for the chosen horizon.
        // Formula: (Weekly Capacity / 5 working days) * horizon days
        const baseWeekly = m.weekly_capacity || 40;
        const dailyCapacity = baseWeekly / 5;
        // Approximation: assume 5/7 of the horizon days are working days
        const workingDays = Math.floor(parseInt(horizon) * (5/7));
        const totalCapacity = dailyCapacity * (workingDays > 0 ? workingDays : 1);

        memberMap.set(m.id, {
          id: m.id,
          name: m.displayName || 'Team Member',
          avatar: m.avatar,
          capacity: totalCapacity,
          assignedHours: 0,
          utilization: 0,
          tasks: []
        });
      });

      // Filter tasks by horizon and assign hours
      tasks?.forEach(task => {
        if (!task.assigned_workspace_member_id || !memberMap.has(task.assigned_workspace_member_id)) return;
        if (!task.estimated_hours || task.estimated_hours <= 0) return;

        // If task has no dates, assume it's ongoing and count it? Let's count it to be safe, 
        // or strictly filter. We will strictly filter if it has dates.
        if (task.start_date || task.due_date) {
          const start = task.start_date ? parseISO(task.start_date) : today;
          const end = task.due_date ? parseISO(task.due_date) : addMonths(today, 1);
          
          // Check intersection with our horizon window
          if (isAfter(start, endHorizon) || isBefore(end, today)) {
             return; // Task is completely outside the window
          }
        }

        const data = memberMap.get(task.assigned_workspace_member_id);
        data.assignedHours += Number(task.estimated_hours);
        data.tasks.push(task);
      });

      // Calculate utilization
      const processed = Array.from(memberMap.values()).map(m => {
        m.utilization = Math.round((m.assignedHours / m.capacity) * 100);
        return m;
      }).sort((a, b) => b.utilization - a.utilization); // Sort by most overloaded

      setWorkloadData(processed);

    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, horizon, supabase]);

  useEffect(() => {
    fetchGlobalWorkload();
  }, [fetchGlobalWorkload]);

  const toggleUser = (id: string) => {
    setExpandedUsers(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const getUtilizationColor = (utilization: number) => {
    if (utilization > 100) return 'bg-red-500';
    if (utilization > 90) return 'bg-orange-500';
    if (utilization > 70) return 'bg-yellow-500';
    return 'bg-emerald-500';
  };

  if (loading) {
    return <div className="flex justify-center p-12"><Loader2 className="size-8 animate-spin text-primary" /></div>;
  }

  return (
    <div className="p-6 max-w-6xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold tracking-tight">Global Workload</h1>
          <p className="text-muted-foreground text-sm">Analyze team capacity and task distribution across all projects.</p>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-sm font-medium">Time Horizon:</span>
          <Select value={horizon} onValueChange={(val) => setHorizon(val as TimeHorizon)}>
            <SelectTrigger className="w-[160px] bg-card">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="7">Next 7 Days</SelectItem>
              <SelectItem value="14">Next 14 Days</SelectItem>
              <SelectItem value="30">Next 30 Days</SelectItem>
              <SelectItem value="90">Next 90 Days</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="grid gap-4">
        {workloadData.length === 0 ? (
          <div className="text-center py-12 bg-card border border-dashed rounded-lg">
            <Activity className="size-8 mx-auto text-muted-foreground mb-3 opacity-50" />
            <p className="text-muted-foreground">No active members or tasks found.</p>
          </div>
        ) : (
          workloadData.map(member => (
            <Card key={member.id} className="overflow-hidden shadow-sm">
              <div 
                className="p-4 flex items-center justify-between cursor-pointer hover:bg-muted/30 transition-colors"
                onClick={() => toggleUser(member.id)}
              >
                <div className="flex items-center gap-4 w-1/3">
                  {expandedUsers[member.id] ? <ChevronDown className="size-4 text-muted-foreground" /> : <ChevronRight className="size-4 text-muted-foreground" />}
                  <Avatar className="size-10 border">
                    <AvatarImage src={member.avatar} />
                    <AvatarFallback className="bg-primary/10 text-primary font-medium">
                      {member.name.substring(0, 2).toUpperCase()}
                    </AvatarFallback>
                  </Avatar>
                  <span className="font-semibold">{member.name}</span>
                </div>
                
                <div className="w-1/2 px-4 flex items-center gap-4">
                  <div className="flex-1">
                    <div className="flex justify-between text-xs mb-1.5 font-medium">
                      <span>{member.utilization}% Utilized</span>
                      <span className="text-muted-foreground">{member.assignedHours}h / {member.capacity}h</span>
                    </div>
                    {/* Custom progress bar to inject specific color */}
                    <div className="h-2.5 w-full bg-secondary overflow-hidden rounded-full">
                      <div 
                        className={`h-full transition-all duration-500 ease-in-out ${getUtilizationColor(member.utilization)}`}
                        style={{ width: `${Math.min(member.utilization, 100)}%` }}
                      />
                    </div>
                  </div>
                </div>

                <div className="w-1/6 text-right">
                  <Badge variant="outline" className="font-medium">
                    {member.tasks.length} Active Tasks
                  </Badge>
                </div>
              </div>

              {expandedUsers[member.id] && (
                <div className="bg-muted/10 border-t p-4 px-12">
                  {member.tasks.length === 0 ? (
                    <p className="text-sm text-muted-foreground py-2">No tasks assigned in this horizon.</p>
                  ) : (
                    <div className="space-y-3">
                      {member.tasks.map((t: any) => (
                        <div key={t.id} className="flex items-center justify-between text-sm bg-background border p-2 rounded-none shadow-sm">
                          <div className="flex flex-col">
                            <span className="font-medium">{t.title}</span>
                            <span className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5">
                              <Briefcase className="size-3" />
                              {Array.isArray(t.projects) ? t.projects[0]?.name : t.projects?.name}
                            </span>
                          </div>
                          <div className="text-right">
                            <span className="font-semibold text-primary">{t.estimated_hours}h</span>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { getOrCreateDefaultAccounts } from "@/lib/commerce/accounting-engine";

export async function GET(request: Request) {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  if (authError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const workspaceId = searchParams.get("workspace_id");

  if (!workspaceId) {
    return NextResponse.json({ error: "Workspace ID is required" }, { status: 400 });
  }

  try {
    // 1. Ensure chart of accounts exist
    const accountsList = await getOrCreateDefaultAccounts(supabase, workspaceId);

    // Create Account Lookup Map
    const accountMap: Record<string, any> = {};
    (accountsList || []).forEach((acc) => {
      accountMap[acc.id] = acc;
    });

    // 2. Fetch journal entries
    const { data: journalEntries, error: jError } = await supabase
      .from("commerce_journal_entries")
      .select("*")
      .eq("workspace_id", workspaceId)
      .order("created_at", { ascending: false });

    if (jError) {
      return NextResponse.json({ error: jError.message }, { status: 500 });
    }

    const journalIds = (journalEntries || []).map((j) => j.id);

    // 3. Fetch journal lines for these entries
    let journalLines: any[] = [];
    if (journalIds.length > 0) {
      const { data: linesData, error: linesErr } = await supabase
        .from("commerce_journal_lines")
        .select("*")
        .in("journal_entry_id", journalIds);

      if (!linesErr && linesData) {
        journalLines = linesData;
      }
    }

    // Group lines by journal_entry_id
    const linesByEntry: Record<string, any[]> = {};
    const accountBalances: Record<string, { debit: number; credit: number }> = {};

    journalLines.forEach((line) => {
      if (!linesByEntry[line.journal_entry_id]) {
        linesByEntry[line.journal_entry_id] = [];
      }

      const accObj = accountMap[line.account_id] || null;
      linesByEntry[line.journal_entry_id].push({
        ...line,
        account: accObj
          ? {
              account_code: accObj.account_code,
              account_name: accObj.account_name,
              account_type: accObj.account_type,
              sub_category: accObj.sub_category,
            }
          : null,
      });

      if (!accountBalances[line.account_id]) {
        accountBalances[line.account_id] = { debit: 0, credit: 0 };
      }
      accountBalances[line.account_id].debit += Number(line.debit_amount || 0);
      accountBalances[line.account_id].credit += Number(line.credit_amount || 0);
    });

    // Attach items to journal entries
    const formattedVouchers = (journalEntries || []).map((entry) => ({
      ...entry,
      items: linesByEntry[entry.id] || [],
    }));

    // Calculate live GL account balances
    const updatedAccounts = (accountsList || []).map((acc) => {
      const totals = accountBalances[acc.id] || { debit: 0, credit: 0 };
      let calcBalance = 0;
      if (acc.account_type === "ASSET" || acc.account_type === "EXPENSE") {
        calcBalance = totals.debit - totals.credit;
      } else {
        calcBalance = totals.credit - totals.debit;
      }

      return {
        ...acc,
        total_debit: totals.debit,
        total_credit: totals.credit,
        current_balance: Math.max(0, calcBalance),
      };
    });

    // Calculate live summary stats
    let cashInHand = 0;
    let bankAccounts = 0;
    let customerKhata = 0;
    let totalRevenue = 0;

    updatedAccounts.forEach((acc) => {
      const sub = acc.sub_category || "";
      if (sub === "CASH") cashInHand += acc.current_balance;
      if (sub === "BANK") bankAccounts += acc.current_balance;
      if (sub === "CUSTOMER_KHATA") customerKhata += acc.current_balance;
      if (acc.account_type === "REVENUE" || sub === "SALES_REVENUE") totalRevenue += acc.current_balance;
    });

    return NextResponse.json({
      accounts: updatedAccounts,
      journal_vouchers: formattedVouchers,
      summary: {
        cash_in_hand: cashInHand,
        bank_accounts: bankAccounts,
        customer_khata: customerKhata,
        total_sales_revenue: totalRevenue,
      },
    });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Failed to load accounting data" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { postKhataCollection } from "@/lib/accounting/posting";

export async function GET(request: Request) {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  if (authError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const workspaceId = searchParams.get("workspace_id");

  if (!workspaceId) {
    return NextResponse.json({ error: "Workspace ID is required" }, { status: 400 });
  }

  try {
    // 1. Fetch contacts
    const { data: contacts, error: cErr } = await supabase
      .from("contacts")
      .select("*")
      .eq("workspace_id", workspaceId)
      .order("created_at", { ascending: false });

    if (cErr) {
      return NextResponse.json({ error: cErr.message }, { status: 500 });
    }

    const contactIds = (contacts || []).map((c) => c.id);

    // 2. Fetch Khata ledgers for these contacts
    let khataMap: Record<string, any> = {};
    if (contactIds.length > 0) {
      const { data: khataRecords } = await supabase
        .from("commerce_customer_khata")
        .select("*")
        .eq("workspace_id", workspaceId)
        .in("contact_id", contactIds);

      (khataRecords || []).forEach((k) => {
        khataMap[k.contact_id] = k;
      });
    }

    const customerLedgers = (contacts || []).map((c) => {
      const name = c.name || [c.first_name, c.last_name].filter(Boolean).join(" ") || "Unnamed Customer";
      const khata = khataMap[c.id] || null;
      return {
        ...c,
        displayName: name,
        credit_limit: khata ? Number(khata.credit_limit || 50000) : 50000,
        outstanding_balance: khata ? Number(khata.outstanding_balance || 0) : 0,
        credit_days: khata ? Number(khata.credit_days || 30) : 30,
        khata_id: khata?.id || null,
      };
    });

    return NextResponse.json({ customers: customerLedgers });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Failed to load customer ledger" }, { status: 500 });
  }
}

export async function POST(request: Request) {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  if (authError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const body = await request.json();
  const { action = "CREATE_CUSTOMER", workspace_id } = body;

  if (!workspace_id) {
    return NextResponse.json({ error: "Workspace ID is required" }, { status: 400 });
  }

  // Action 1: Create New Customer Contact
  if (action === "CREATE_CUSTOMER") {
    const { first_name, last_name, phone_number, email, company, credit_limit = 50000 } = body;

    if (!first_name && !phone_number) {
      return NextResponse.json({ error: "Customer Name or Phone is required" }, { status: 400 });
    }

    const fullName = [first_name, last_name].filter(Boolean).join(" ") || "Retail Customer";

    // Insert into contacts
    const { data: contact, error: cErr } = await supabase
      .from("contacts")
      .insert({
        workspace_id,
        user_id: user.id,
        name: fullName,
        phone: phone_number || null,
        email: email || null,
        company: company || null,
      })
      .select()
      .single();

    if (cErr || !contact) {
      return NextResponse.json({ error: cErr?.message || "Failed to create contact" }, { status: 500 });
    }

    // Initialize Khata Record
    await supabase.from("commerce_customer_khata").insert({
      workspace_id,
      contact_id: contact.id,
      credit_limit: Number(credit_limit || 50000),
      outstanding_balance: 0,
      credit_days: 30,
    });

    return NextResponse.json({ success: true, customer: contact });
  }

  // Action 2: Record Payment Collection (Udhar Recovery)
  if (action === "RECORD_PAYMENT") {
    const { contact_id, payment_amount, payment_mode = "CASH", notes = "" } = body;

    if (!contact_id || !payment_amount) {
      return NextResponse.json({ error: "Contact ID and Payment Amount are required" }, { status: 400 });
    }

    const payAmt = Number(payment_amount);
    if (!Number.isFinite(payAmt) || payAmt <= 0) {
      return NextResponse.json({ error: "Payment amount must be a positive number" }, { status: 400 });
    }

    // Fetch existing khata
    const { data: existingKhata } = await supabase
      .from("commerce_customer_khata")
      .select("*")
      .eq("workspace_id", workspace_id)
      .eq("contact_id", contact_id)
      .maybeSingle();

    const currentBal = Number(existingKhata?.outstanding_balance || 0);

    // Collecting more than is owed is almost certainly a typo — and
    // silently clamping it (the old behaviour) made the books disagree
    // with the khata forever.
    if (payAmt > currentBal + 0.005) {
      return NextResponse.json(
        { error: `Payment ${payAmt} exceeds outstanding balance ${currentBal}` },
        { status: 400 },
      );
    }

    // Post the balanced voucher FIRST: DR Cash/Bank, CR Customer
    // Khata. If posting fails, the balance is left untouched — the
    // books and the khata never diverge. (The old code wrote a
    // header with no lines: an orphan voucher with no amount, which
    // migration 075 deletes.)
    let posting;
    try {
      posting = await postKhataCollection(supabase, {
        workspace_id,
        contact_id,
        amount: payAmt,
        payment_mode,
        narration: notes || undefined,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to post collection voucher";
      return NextResponse.json({ error: message }, { status: 500 });
    }

    const newBal = currentBal - payAmt;
    if (existingKhata) {
      await supabase
        .from("commerce_customer_khata")
        .update({ outstanding_balance: newBal })
        .eq("id", existingKhata.id);
    } else {
      await supabase.from("commerce_customer_khata").insert({
        workspace_id,
        contact_id,
        outstanding_balance: 0,
      });
    }

    return NextResponse.json({
      success: true,
      new_balance: newBal,
      voucher: { id: posting.journal_entry_id, voucher_number: posting.voucher_number },
    });
  }

  // Action 3: Update Credit Limit
  if (action === "UPDATE_LIMIT") {
    const { contact_id, credit_limit, credit_days } = body;

    const { data: existing } = await supabase
      .from("commerce_customer_khata")
      .select("id")
      .eq("workspace_id", workspace_id)
      .eq("contact_id", contact_id)
      .maybeSingle();

    if (existing) {
      await supabase
        .from("commerce_customer_khata")
        .update({
          credit_limit: Number(credit_limit || 50000),
          credit_days: Number(credit_days || 30),
        })
        .eq("id", existing.id);
    } else {
      await supabase.from("commerce_customer_khata").insert({
        workspace_id,
        contact_id,
        credit_limit: Number(credit_limit || 50000),
        credit_days: Number(credit_days || 30),
        outstanding_balance: 0,
      });
    }

    return NextResponse.json({ success: true });
  }

  return NextResponse.json({ error: "Invalid action" }, { status: 400 });
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { postPOSSalesJournal } from "@/lib/commerce/accounting-engine";
import { evaluatePromotions } from "@/lib/commerce/promotions-engine";

export async function POST(request: Request) {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  if (authError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const body = await request.json();
  const {
    workspace_id,
    customer_id,
    is_walkin_customer = true,
    customer_type = "RETAIL",
    customer_gstin,
    billing_address,
    shipping_address,
    customer_mobile,
    salesman_member_id,
    counter_number = "COUNTER-1",
    invoice_series = "INV/",
    invoice_type = "TAX_INVOICE",
    financial_year = "2026-2027",
    payment_method = "CASH",
    payment_status = "PAID",
    payment_breakdown,
    items,
    discount_amount = 0,
    round_off_amount = 0,
    cash_received = 0,
    change_returned = 0,
    card_type,
    card_approval_number,
    notes = "",
    promo_code_applied,
  } = body;

  if (!workspace_id || !items || !Array.isArray(items) || items.length === 0) {
    return NextResponse.json({ error: "Invalid checkout request: items required" }, { status: 400 });
  }

  // Find active workspace member for user
  const { data: member } = await supabase
    .from("workspace_members")
    .select("id")
    .eq("workspace_id", workspace_id)
    .eq("user_id", user.id)
    .single();

  const cashierMemberId = member?.id || null;

  // 1. Evaluate Promotions via Decoupled Engine
  let promotionDiscountTotal = 0;
  try {
    const promoRes = await evaluatePromotions(supabase, {
      workspace_id,
      customer_id,
      customer_type,
      items,
      coupon_code: promo_code_applied,
    });
    promotionDiscountTotal = promoRes.total_order_discount || 0;
  } catch (promoErr) {
    console.error("Promotion evaluation notice:", promoErr);
  }

  // Calculate Subtotal & Tax Total
  let subtotal = 0;
  let taxTotal = 0;

  const orderItemsData = items.map((item: any) => {
    const itemSubtotal = item.quantity * item.selling_price;
    const itemTax = (itemSubtotal * (item.tax_rate || 0)) / 100;
    subtotal += itemSubtotal;
    taxTotal += itemTax;

    return {
      product_id: item.product_id,
      batch_id: item.batch_id || null,
      warehouse_id: item.warehouse_id || null,
      quantity: item.quantity,
      free_quantity: item.free_quantity || 0,
      unit: item.unit || "PCS",
      mrp: item.mrp || item.selling_price,
      unit_price: item.selling_price,
      selling_price: item.selling_price,
      tax_rate: item.tax_rate || 0,
      total_price: itemSubtotal + itemTax,
      serial_numbers: item.serial_numbers || [],
      imei_numbers: item.imei_numbers || [],
      warranty_months: item.warranty_months || 0,
      item_remarks: item.item_remarks || "",
    };
  });

  const netDiscount = Number(discount_amount || 0) + promotionDiscountTotal;
  const grandTotal = Math.max(0, subtotal + taxTotal - netDiscount + Number(round_off_amount || 0));

  // Generate Document Number via RPC or Fallback
  let orderNumber = `${invoice_series}${Date.now().toString().slice(-6)}`;
  try {
    const { data: rpcNum } = await supabase.rpc("generate_next_document_number", {
      p_workspace_id: workspace_id,
      p_document_type: invoice_type || "INVOICE",
    });
    if (rpcNum) orderNumber = rpcNum;
  } catch {
    console.error("Document number fallback used");
  }

  // 2. Insert Sales Order Header
  const { data: salesOrder, error: orderError } = await supabase
    .from("commerce_sales_orders")
    .insert({
      workspace_id,
      order_number: orderNumber,
      customer_id: customer_id || null,
      is_walkin_customer,
      customer_type,
      customer_gstin: customer_gstin || null,
      billing_address: billing_address || null,
      shipping_address: shipping_address || null,
      customer_mobile: customer_mobile || null,
      salesman_member_id: salesman_member_id || cashierMemberId,
      counter_number,
      invoice_series,
      invoice_type,
      financial_year,
      channel: "POS",
      payment_status: payment_status || "PAID",
      payment_method: payment_method || "CASH",
      subtotal,
      tax_total: taxTotal,
      discount_amount: netDiscount,
      round_off_amount: Number(round_off_amount || 0),
      grand_total: grandTotal,
      cash_received: Number(cash_received || 0),
      change_returned: Number(change_returned || 0),
      card_type: card_type || null,
      card_approval_number: card_approval_number || null,
      cashier_member_id: cashierMemberId,
      notes,
    })
    .select()
    .single();

  if (orderError || !salesOrder) {
    return NextResponse.json({ error: orderError?.message || "Failed to process POS checkout" }, { status: 500 });
  }

  // 3. Insert Sales Order Line Items
  const itemsToInsert = orderItemsData.map((item: any) => ({
    ...item,
    sales_order_id: salesOrder.id,
  }));

  await supabase.from("commerce_sales_items").insert(itemsToInsert);

  // 4. Log Stock Movements
  const movementsToInsert = orderItemsData.map((item: any) => ({
    workspace_id,
    product_id: item.product_id,
    batch_id: item.batch_id || null,
    movement_type: "OUTWARD_SALE",
    stock_status: "AVAILABLE",
    quantity: -Math.abs(item.quantity),
    reference_id: salesOrder.id,
    notes: `POS Checkout Order #${salesOrder.order_number}`,
    created_by: cashierMemberId,
  }));

  await supabase.from("commerce_inventory_movements").insert(movementsToInsert);

  // 5. Post Double-Entry Accounting Journal Vouchers
  const paymentLines = Array.isArray(payment_breakdown) && payment_breakdown.length > 0
    ? payment_breakdown
    : [{ mode: payment_method || "CASH", amount: grandTotal }];

  try {
    await postPOSSalesJournal(supabase, {
      workspace_id,
      sales_order_id: salesOrder.id,
      order_number: salesOrder.order_number,
      customer_id: salesOrder.customer_id,
      total_sales_amount: salesOrder.grand_total,
      payments: paymentLines,
      cashier_member_id: cashierMemberId,
    });
  } catch (acctErr: any) {
    console.error("Accounting posting failed:", acctErr?.message);
  }

  // 6. Record OUTPUT GST Ledger Entry
  const isGstBill = body.is_gst_bill !== false && taxTotal > 0;
  if (isGstBill) {
    try {
      const { recordGstLedgerEntry } = await import("@/lib/commerce/gst/gst-ledger-manager");
      await recordGstLedgerEntry(supabase, {
        workspace_id,
        ledger_type: "OUTPUT",
        invoice_id: salesOrder.id,
        invoice_number: salesOrder.order_number,
        party_name: customer_id ? "Registered Customer" : "POS Retail Customer",
        gstin: customer_gstin || undefined,
        base_amount: subtotal,
        gst_rate: subtotal > 0 ? (taxTotal / subtotal) * 100 : 0,
        is_tax_inclusive: false,
      });
    } catch (gstErr: any) {
      console.error("GST Ledger posting failed:", gstErr?.message);
    }
  }

  // 7. Publish Event Bus: [SaleCompleted]
  await supabase.from("platform_domain_events").insert({
    workspace_id,
    event_type: "SaleCompleted",
    aggregate_id: salesOrder.id,
    payload: {
      order_id: salesOrder.id,
      order_number: salesOrder.order_number,
      customer_id: salesOrder.customer_id,
      customer_type,
      grand_total: salesOrder.grand_total,
      payment_method: salesOrder.payment_method,
      items: orderItemsData,
    },
  });

  return NextResponse.json({
    success: true,
    order: salesOrder,
    message: "POS Checkout, Decoupled Promotions, and Automated Accounting Posted Successfully",
  });
}

