export async function GET(request: Request) {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  if (authError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const workspaceId = searchParams.get("workspace_id");
  const query = searchParams.get("query") || "";

  if (!workspaceId) {
    return NextResponse.json({ error: "Workspace ID is required" }, { status: 400 });
  }

  try {
    let dbQuery = supabase
      .from("commerce_sales_orders")
      .select("*")
      .eq("workspace_id", workspaceId)
      .order("created_at", { ascending: false });

    if (query) {
      dbQuery = dbQuery.or(`order_number.ilike.%${query}%,customer_mobile.ilike.%${query}%`);
    }

    const { data: salesOrders, error } = await dbQuery;

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    const orderIds = (salesOrders || []).map((o) => o.id);
    const customerIds = (salesOrders || []).map((o) => o.customer_id).filter(Boolean);

    // Fetch customer contacts if any
    let contactsMap: Record<string, any> = {};
    if (customerIds.length > 0) {
      const { data: contacts } = await supabase
        .from("contacts")
        .select("id, name, phone, email, company")
        .in("id", customerIds);

      (contacts || []).forEach((c) => {
        contactsMap[c.id] = c;
      });
    }

    // Fetch items for sales orders
    let itemsByOrder: Record<string, any[]> = {};
    if (orderIds.length > 0) {
      const { data: itemsData } = await supabase
        .from("commerce_sales_items")
        .select("*")
        .in("sales_order_id", orderIds);

      const productIds = Array.from(new Set((itemsData || []).map((i) => i.product_id).filter(Boolean)));
      let productsMap: Record<string, any> = {};

      if (productIds.length > 0) {
        const { data: productsData } = await supabase
          .from("commerce_products")
          .select("id, name, sku, barcode")
          .in("id", productIds);

        (productsData || []).forEach((p) => {
          productsMap[p.id] = p;
        });
      }

      (itemsData || []).forEach((item) => {
        if (!itemsByOrder[item.sales_order_id]) {
          itemsByOrder[item.sales_order_id] = [];
        }
        itemsByOrder[item.sales_order_id].push({
          ...item,
          product: productsMap[item.product_id] || null,
        });
      });
    }

    const formattedOrders = (salesOrders || []).map((order) => ({
      ...order,
      customer: contactsMap[order.customer_id] || null,
      items: itemsByOrder[order.id] || [],
    }));

    return NextResponse.json({ sales_orders: formattedOrders });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Failed to load sales orders" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { generateChatbotResponse } from "@/lib/chatbot/ai-service";

export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: conversationId } = await params;
    const supabase = await createClient();

    // 1. Verify User Authentication
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // 2. Fetch last 50 messages from the conversation
    const { data: messages, error } = await supabase
      .from("messages")
      .select("sender_type, content_text, content_type, created_at")
      .eq("conversation_id", conversationId)
      .order("created_at", { ascending: false })
      .limit(50);

    if (error) {
      console.error("[summarize] Error fetching messages:", error);
      return NextResponse.json(
        { error: "Failed to fetch conversation messages" },
        { status: 500 }
      );
    }

    if (!messages || messages.length === 0) {
      return NextResponse.json(
        { error: "No messages found in this conversation to summarize" },
        { status: 404 }
      );
    }

    // Chronological order format: "[Customer]: ..." or "[Agent]: ..."
    const chatTranscript = messages
      .reverse()
      .map((m) => {
        const sender = m.sender_type === "customer" ? "Customer" : "Agent";
        const content = m.content_text || `[${m.content_type || "media"}]`;
        return `${sender}: ${content}`;
      })
      .join("\n");

    // 3. System prompt for structured Groq Llama 3 output
    const systemPrompt = `
You are an executive CRM AI assistant. Summarize the following customer WhatsApp chat transcript cleanly into 3 specific sections:

📌 CUSTOMER ISSUE / GOAL:
(1-2 concise bullet points explaining why the customer reached out or what they need)

🤝 KEY AGREEMENTS & POINTS DISCUSSED:
(1-3 bullet points listing key info, offers, or facts exchanged)

🎯 RECOMMENDED NEXT STEPS:
(1-2 actionable bullet points for the agent taking over this ticket)

Keep it brief, accurate, easy to scan in 10 seconds, and formatted with clean markdown bullets.
`;

    // 4. Call Groq AI via existing AI service
    const summary = await generateChatbotResponse({
      provider: "groq",
      apiKey: null, // Resolves process.env.GROQ_API_KEY
      model: "llama-3.3-70b-versatile",
      systemPrompt,
      history: [],
      userMessage: chatTranscript,
    });

    return NextResponse.json({ summary });
  } catch (error: any) {
    console.error("[summarize] Exception:", error);
    return NextResponse.json(
      { error: error.message || "Failed to generate conversation summary" },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const workspaceId = searchParams.get('workspace_id');

    if (!workspaceId) {
      return NextResponse.json({ error: 'workspace_id is required' }, { status: 400 });
    }

    const supabase = await createClient();

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Security Gate: Enforce workspace membership for multi-tenant isolation
    const { data: member, error: memberErr } = await supabase
      .from('workspace_members')
      .select('id')
      .eq('workspace_id', workspaceId)
      .eq('user_id', user.id)
      .maybeSingle();

    if (memberErr || !member) {
      return NextResponse.json(
        { error: 'Forbidden: You are not a member of this workspace' },
        { status: 403 }
      );
    }

    // Strict Tenant Isolation: Query conversations strictly by workspace_id
    const { data: conversations, error: convError } = await supabase
      .from('conversations')
      .select('*, contact:contacts(*)')
      .eq('workspace_id', workspaceId)
      .order('last_message_at', { ascending: false });

    if (!convError && conversations) {
      return NextResponse.json({ conversations });
    }

    // Fallback: If PostgREST embedding fails, fetch conversations and contacts separately
    console.warn('[conversations GET] Embedded query failed, executing fallback join:', convError);

    const { data: rawConvs, error: rawErr } = await supabase
      .from('conversations')
      .select('*')
      .eq('workspace_id', workspaceId)
      .order('last_message_at', { ascending: false });

    if (rawErr || !rawConvs) {
      return NextResponse.json({ error: 'Failed to fetch conversations' }, { status: 500 });
    }

    const contactIds = Array.from(
      new Set(rawConvs.map((c) => c.contact_id).filter(Boolean))
    );

    let contactsMap: Record<string, any> = {};
    if (contactIds.length > 0) {
      const { data: contacts } = await supabase
        .from('contacts')
        .select('*')
        .eq('workspace_id', workspaceId)
        .in('id', contactIds);

      if (contacts) {
        contactsMap = Object.fromEntries(contacts.map((c) => [c.id, c]));
      }
    }

    const joined = rawConvs.map((c) => ({
      ...c,
      contact: c.contact_id ? contactsMap[c.contact_id] || null : null,
    }));

    return NextResponse.json({ conversations: joined });
  } catch (error) {
    console.error('Error fetching conversations:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import Razorpay from 'razorpay';
import { createClient } from '@/lib/supabase/server';

export async function POST(request: NextRequest) {
  try {
    // Orders are only created for signed-in users — anonymous order
    // creation gave attackers a free primitive for probing the
    // payment flow.
    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json().catch(() => ({}));
    const { amount, currency = 'INR', receipt } = body;

    // Validation
    if (amount === undefined || typeof amount !== 'number') {
      return NextResponse.json(
        { error: 'amount is required and must be a number' },
        { status: 400 }
      );
    }

    if (amount < 100) {
      return NextResponse.json(
        { error: 'Minimum amount is 100 paise (1 INR)' },
        { status: 400 }
      );
    }

    const keyId = process.env.RAZORPAY_KEY_ID;
    const keySecret = process.env.RAZORPAY_KEY_SECRET;

    if (!keyId || !keySecret) {
      console.error('[create-order] Razorpay keys not configured in environment');
      return NextResponse.json(
        { error: 'Razorpay integration keys are not configured.' },
        { status: 500 }
      );
    }

    const razorpay = new Razorpay({
      key_id: keyId,
      key_secret: keySecret,
    });

    const order = await razorpay.orders.create({
      amount,
      currency,
      receipt: receipt || `receipt_${Date.now()}`,
    });

    return NextResponse.json({
      order_id: order.id,
      amount: order.amount,
      currency: order.currency,
    });
  } catch (error: any) {
    console.error('[create-order] Razorpay error:', error);
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { phonesMatch } from '@/lib/whatsapp/phone-utils';
import { writeFile, mkdir } from 'fs/promises';
import { join } from 'path';
import crypto from 'crypto';

// Helper to instantiate supabase admin client
let _adminClient: any = null;
function supabaseAdmin() {
  if (!_adminClient) {
    _adminClient = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    );
  }
  return _adminClient;
