// Enable CORS for external/public form submissions
function corsHeaders() {
  return {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS, PUT, DELETE',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  };
}

export async function OPTIONS() {
  return NextResponse.json({}, { headers: corsHeaders() });
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: formId } = await params;
    const { submitted_values } = await req.json();

    if (!formId) {
      return NextResponse.json(
        { error: 'Missing form ID' },
        { status: 400, headers: corsHeaders() }
      );
    }

    if (!submitted_values || typeof submitted_values !== 'object') {
      return NextResponse.json(
        { error: 'Missing submitted_values object' },
        { status: 400, headers: corsHeaders() }
      );
    }

    const supabase = supabaseAdmin();

    // 1. Fetch form configuration
    const { data: form, error: formError } = await supabase
      .from('custom_forms')
      .select('*')
      .eq('id', formId)
      .eq('is_active', true)
      .maybeSingle();

    if (formError || !form) {
      return NextResponse.json(
        { error: 'Form not found or inactive' },
        { status: 404, headers: corsHeaders() }
      );
    }

    // 2. Fetch form fields
    const { data: fields, error: fieldsError } = await supabase
      .from('custom_form_fields')
      .select('*')
      .eq('form_id', formId)
      .order('position', { ascending: true });

    if (fieldsError || !fields) {
      return NextResponse.json(
        { error: 'Failed to retrieve form fields' },
        { status: 500, headers: corsHeaders() }
      );
    }

    // 3. Resolve Workspace User Owner/Member to attribute contact/deal creation to
    const { data: ownerMember } = await supabase
      .from('workspace_members')
      .select('user_id')
      .eq('workspace_id', form.workspace_id)
      .eq('role', 'owner')
      .limit(1)
      .maybeSingle();

    let creatorUserId = ownerMember?.user_id;

    if (!creatorUserId) {
      const { data: anyMember } = await supabase
        .from('workspace_members')
        .select('user_id')
        .eq('workspace_id', form.workspace_id)
        .limit(1)
        .maybeSingle();
      creatorUserId = anyMember?.user_id;
    }

    if (!creatorUserId) {
      return NextResponse.json(
        { error: 'No active workspace owner or member found' },
        { status: 500, headers: corsHeaders() }
      );
    }

    // 4. Map form submissions to CRM fields
    const contactData: Record<string, string> = {
      name: '',
      phone: '',
      email: '',
      company: '',
    };
    const contactCustomValues: Record<string, string> = {};
    const dealData: Record<string, string> = {
      title: '',
      value: '',
      notes: '',
      expected_close_date: '',
    };

    for (const field of fields) {
      // Find submitted value by field id or fallback to label
      const val = submitted_values[field.id] !== undefined
        ? submitted_values[field.id]
        : submitted_values[field.label];

      if (val === undefined || val === null) continue;

      // Handle boolean or array types (e.g. multi-select) as strings for standard fields
      const strVal = Array.isArray(val)
        ? val.join(', ')
        : typeof val === 'boolean'
          ? (val ? 'Yes' : 'No')
          : String(val).trim();

      if (field.mapping_type === 'contact_field' && field.mapping_key) {
        contactData[field.mapping_key] = strVal;
      } else if (field.mapping_type === 'contact_custom_field' && field.mapping_key) {
        contactCustomValues[field.mapping_key] = strVal;
      } else if (field.mapping_type === 'deal_field' && field.mapping_key) {
        dealData[field.mapping_key] = strVal;
      }
    }

    // Ensure phone number exists (required in CRM contacts table). Generate fallback placeholder if not submitted.
    if (!contactData.phone) {
      if (contactData.email) {
        const cleanEmailPrefix = contactData.email.split('@')[0].replace(/\D/g, '');
        contactData.phone = cleanEmailPrefix ? cleanEmailPrefix.slice(-10) : '0000000000';
      } else {
        // Random 10 digit number
        contactData.phone = Math.floor(1000000000 + Math.random() * 9000000000).toString();
      }
    }

    // 5. Contact Deduplication and Insertion
    // Fetch all contacts in the workspace to perform phonesMatch
    const { data: contacts } = await supabase
      .from('contacts')
      .select('*')
      .eq('workspace_id', form.workspace_id);

    let contactId = '';
    let existingContact = contacts?.find((c: any) => phonesMatch(c.phone, contactData.phone));

    // If no match found by phone, search by email (if email was provided)
    if (!existingContact && contactData.email) {
      const { data: matchedByEmail } = await supabase
        .from('contacts')
        .select('*')
        .eq('workspace_id', form.workspace_id)
        .eq('email', contactData.email)
        .limit(1)
        .maybeSingle();
      existingContact = matchedByEmail;
    }

    if (existingContact) {
      contactId = existingContact.id;
      // Update fields if they changed and were submitted
      const contactUpdates: Record<string, string> = {};
      if (contactData.name && contactData.name !== existingContact.name) {
        contactUpdates.name = contactData.name;
      }
      if (contactData.email && contactData.email !== existingContact.email) {
        contactUpdates.email = contactData.email;
      }
      if (contactData.company && contactData.company !== existingContact.company) {
        contactUpdates.company = contactData.company;
      }

      if (Object.keys(contactUpdates).length > 0) {
        await supabase
          .from('contacts')
          .update({ ...contactUpdates, updated_at: new Date().toISOString() })
          .eq('id', contactId);
      }
    } else {
      // Create new contact
      const { data: newContact, error: insertError } = await supabase
        .from('contacts')
        .insert({
          user_id: creatorUserId,
          workspace_id: form.workspace_id,
          phone: contactData.phone,
          name: contactData.name || 'Form Lead',
          email: contactData.email || null,
          company: contactData.company || null,
        })
        .select()
        .single();

      if (insertError || !newContact) {
        console.error('[Submit Error] Failed to create contact:', insertError);
        return NextResponse.json(
          { error: 'Failed to create contact record' },
          { status: 500, headers: corsHeaders() }
        );
      }
      contactId = newContact.id;
    }

    // 6. Save Contact Custom Values
    for (const [customFieldId, val] of Object.entries(contactCustomValues)) {
      if (!val) continue;
      await supabase
        .from('contact_custom_values')
        .upsert(
          {
            contact_id: contactId,
            custom_field_id: customFieldId,
            value: val,
          },
          { onConflict: 'contact_id,custom_field_id' }
        );
    }

    // 7. Deal Creation (if pipeline and stage integration are configured)
    let dealId: string | null = null;
    const filesToProcess: { fieldKey: string; fileObj: any; relativePath: string; savedName: string; workspaceName: string; subFolder: string }[] = [];
    const sanitize = (name: string) => name.replace(/[^a-zA-Z0-9 _-]/g, '').trim();

    if (form.pipeline_id && form.stage_id) {
      dealId = crypto.randomUUID();
    }

    let workspaceName = form.workspace_id;
    try {
      const { data: wsData } = await supabase.from('workspaces').select('name').eq('id', form.workspace_id).single();
      if (wsData) {
        workspaceName = sanitize(wsData.name);
      }
    } catch (wsErr) {
      console.error('Failed to fetch workspace name:', wsErr);
    }

    const contactName = contactData.name || (existingContact?.name) || 'Form Lead';
    const dealTitle = dealData.title || `Form Submission: ${contactName}`;
    const subFolder = dealId ? sanitize(dealTitle) : 'Form Submissions';

    const processedValues = { ...submitted_values };

    // Identify file uploads in the submission payload and pre-calculate paths
    for (const [key, value] of Object.entries(submitted_values)) {
      if (typeof value === 'object' && value !== null && 'base64' in value && 'name' in value) {
        const fileObj = value as any;
        const uniqueId = Math.random().toString(36).substring(2, 10);
        // The extension MUST be sanitized too — "a.js/../../x" would
        // otherwise let join() escape public/uploads (path traversal).
        const rawExtension = String(fileObj.name).split('.').pop() || 'bin';
        const extension =
          rawExtension.replace(/[^a-zA-Z0-9]/g, '').slice(0, 10) || 'bin';
        const sanitizedOriginalName = sanitize(
          String(fileObj.name).replace(/\.[^.]*$/, '')
        );
        const savedName = `${sanitizedOriginalName}_${uniqueId}.${extension}`;
        const relativePath = `/uploads/${workspaceName}/${subFolder}/${savedName}`;

        filesToProcess.push({
          fieldKey: key,
          fileObj,
          relativePath,
          savedName,
          workspaceName,
          subFolder,
        });

        // Swap out the base64 payload with filesystem URL immediately
        processedValues[key] = relativePath;
      }
    }

    if (form.pipeline_id && form.stage_id && dealId) {
      // Compile readable summary of ALL submitted responses to append to deal notes (using processedValues)
      let responsesSummary = '\n\n--- Form Response Details ---\n';
      for (const field of fields) {
        const val = processedValues[field.id] !== undefined
          ? processedValues[field.id]
          : processedValues[field.label];
        if (val !== undefined && val !== null && val !== '') {
          responsesSummary += `${field.label}: ${
            Array.isArray(val)
              ? val.join(', ')
              : typeof val === 'boolean'
                ? (val ? 'Yes' : 'No')
                : val
          }\n`;
        }
      }

      const rawDealValue = parseFloat(dealData.value);
      const dealValue = isNaN(rawDealValue) ? 0 : rawDealValue;

      // New deals inherit the workspace's default currency instead of
      // a hardcoded USD (workspaces.default_currency, migration 033).
      const { data: wsCurrencyRow } = await supabase
        .from('workspaces')
        .select('default_currency')
        .eq('id', form.workspace_id)
        .maybeSingle();
      const dealCurrency = wsCurrencyRow?.default_currency || 'USD';
      const finalNotes = (dealData.notes ? `${dealData.notes}\n` : '') + responsesSummary;

      const { error: dealError } = await supabase
        .from('deals')
        .insert({
          id: dealId,
          user_id: creatorUserId,
          workspace_id: form.workspace_id,
          pipeline_id: form.pipeline_id,
          stage_id: form.stage_id,
          contact_id: contactId,
          title: dealTitle,
          value: dealValue,
          currency: dealCurrency,
          notes: finalNotes,
          expected_close_date: dealData.expected_close_date || null,
          status: 'open',
        })
        .select()
        .single();

      if (dealError) {
        console.error('[Submit Error] Failed to create deal:', dealError);
        dealId = null;
      }
    }

    // Process file attachments and save (now that the deal is in the DB, FK constraint passes)
    if (filesToProcess.length > 0) {
      for (const item of filesToProcess) {
        try {
          const { fileObj, relativePath, savedName, workspaceName, subFolder } = item;
          const base64Data = fileObj.base64.split(';base64,').pop();
          const buffer = Buffer.from(base64Data, 'base64');

          const uploadDir = join(process.cwd(), 'public', 'uploads', workspaceName, subFolder);
          await mkdir(uploadDir, { recursive: true });

          const filePath = join(uploadDir, savedName);
          await writeFile(filePath, buffer);

          // Insert into media_files table
          const insertData: any = {
            workspace_id: form.workspace_id,
            name: fileObj.name,
            mime_type: fileObj.type,
            file_size: fileObj.size,
            local_path: relativePath,
          };
          if (dealId) {
            insertData.deal_id = dealId;
          }

          const { error: dbErr } = await supabase
            .from('media_files')
            .insert(insertData)
            .select()
            .single();

          if (dbErr) {
            console.error('[File Save Error] DB insert failed:', dbErr);
          }
        } catch (fileErr) {
          console.error('[File Process Error] Failed to process file:', fileErr);
        }
      }
    }

    // 8. Record Submission history log (using processedValues)
    const { data: submissionRecord, error: subError } = await supabase
      .from('custom_form_submissions')
      .insert({
        form_id: formId,
        contact_id: contactId,
        deal_id: dealId,
        submitted_values: processedValues,
      })
      .select()
      .single();

    if (subError) {
      console.error('[Submit Error] Failed to write submission log:', subError);
    }

    return NextResponse.json(
      {
        success: true,
        submissionId: submissionRecord?.id || null,
        contactId,
        dealId,
      },
      { headers: corsHeaders() }
    );

  } catch (error: any) {
    console.error('[submission api error]', error);
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500, headers: corsHeaders() }
    );
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';

export async function GET(request: Request) {
  try {
    const supabase = await createClient();
    const { searchParams } = new URL(request.url);
    const workspaceId = searchParams.get('workspaceId');

    if (!workspaceId) {
      return NextResponse.json({ error: 'workspaceId is required' }, { status: 400 });
    }

    const todayStr = new Date().toISOString().split('T')[0];

    // Fetch parallel dashboard aggregates
    // Table is `attendance` (not attendance_logs), its date column is
    // `attendance_date`, statuses are mixed-case ('Present'), and
    // leave_requests statuses are lowercase — all per migration 039.
    // Workforce counts ACTIVE employee_profiles, matching the card's
    // "Active employee profiles" label (not every invited member).
    const [empRes, attRes, lveRes, reqRes, jobRes] = await Promise.all([
      supabase.from('employee_profiles').select('workspace_member_id', { count: 'exact', head: true }).eq('workspace_id', workspaceId).eq('status', 'ACTIVE'),
      supabase.from('attendance').select('id, status').eq('workspace_id', workspaceId).eq('attendance_date', todayStr),
      supabase.from('leave_requests').select('id, status').eq('workspace_id', workspaceId).eq('status', 'pending'),
      supabase.from('hr_employee_requests').select('id, status').eq('workspace_id', workspaceId).eq('status', 'PENDING'),
      supabase.from('hr_recruitment_jobs').select('id').eq('workspace_id', workspaceId).eq('status', 'OPEN')
    ]);

    const totalEmployees = empRes.count ?? 0;
    const presentToday = attRes.data?.filter(a => a.status === 'Present' || a.status === 'Late' || a.status === 'Remote').length || 0;
    const pendingLeaves = lveRes.data?.length || 0;
    const pendingRequests = reqRes.data?.length || 0;
    const openJobs = jobRes.data?.length || 0;

    return NextResponse.json({
      metrics: {
        totalEmployees,
        presentToday,
        onLeaveToday: totalEmployees > 0 ? Math.max(0, totalEmployees - presentToday) : 0,
        pendingApprovals: pendingLeaves + pendingRequests,
        pendingLeaves,
        pendingRequests,
        openJobs
      }
    });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { HANDBOOK_SECTIONS } from "@/lib/hr/handbook";

/** Positions 1..13 belong to the generated sections. */
const HANDBOOK_SECTION_COUNT = HANDBOOK_SECTIONS.length;

export async function POST(request: Request) {
  try {
    const supabase = await createClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { workspaceId, policyIds } = await request.json();
    if (!workspaceId || !Array.isArray(policyIds) || policyIds.length === 0) {
      return NextResponse.json(
        { error: "Workspace ID and policyIds array are required" },
        { status: 400 }
      );
    }

    const { data: member } = await supabase
      .from("workspace_members")
      .select("id, role")
      .eq("workspace_id", workspaceId)
      .eq("user_id", user.id)
      .single();

    if (!member || !["owner", "admin"].includes(member.role)) {
      return NextResponse.json(
        { error: "Only workspace admins can modify the handbook" },
        { status: 403 }
      );
    }

    // Fetch the policies to attach. Filtering on workspace_id means a
    // caller cannot reach another tenant's policy by id.
    const { data: targetPolicies, error: fetchErr } = await supabase
      .from("hr_policies")
      .select("id, title, handbook_position")
      .eq("workspace_id", workspaceId)
      .in("id", policyIds);

    if (fetchErr) {
      // The column ships in migration 083; say so instead of falling
      // back to the destructive title-rename this route used to do.
      if (/handbook_position|column .* does not exist|schema cache/i.test(fetchErr.message)) {
        return NextResponse.json(
          { error: "Handbook ordering is not set up yet — apply migration 083, then try again." },
          { status: 400 },
        );
      }
      return NextResponse.json({ error: "Failed to fetch selected policies" }, { status: 500 });
    }
    if (!targetPolicies || targetPolicies.length === 0) {
      // Previously returned success with count 0, so the UI reported
      // "Added 1 policy section" when nothing had happened.
      return NextResponse.json(
        { error: "None of those policies exist in this workspace" },
        { status: 404 },
      );
    }

    // Handbook membership is a position, NOT a title change. Renaming
    // the policy mutated it everywhere (lists, exports, audit history)
    // irreversibly, hid it from the "Linked Company Policies" pass and
    // leaked the raw prefix into the printed handbook.
    const { data: lastSection } = await supabase
      .from("hr_policies")
      .select("handbook_position")
      .eq("workspace_id", workspaceId)
      .not("handbook_position", "is", null)
      .order("handbook_position", { ascending: false })
      .limit(1)
      .maybeSingle();

    let nextPosition = Math.max(HANDBOOK_SECTION_COUNT, lastSection?.handbook_position ?? 0) + 1;

    let added = 0;
    for (const p of targetPolicies) {
      if (p.handbook_position != null) continue; // already in the handbook
      const { error: upErr } = await supabase
        .from("hr_policies")
        .update({ handbook_position: nextPosition })
        .eq("id", p.id)
        .eq("workspace_id", workspaceId);
      if (upErr) {
        // Errors used to be discarded, so an RLS denial still reported
        // success while nothing was written.
        return NextResponse.json(
          { error: `Failed to add "${p.title}": ${upErr.message}`, count: added },
          { status: 500 },
        );
      }
      nextPosition++;
      added++;
    }

    return NextResponse.json({ success: true, count: added });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Failed to add section" }, { status: 500 });
  }
}

