import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';
import { headers } from 'next/headers';

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const supabase = await createClient();
    const headersList = await headers();
    const body = await request.json();

    const {
      workspaceId,
      versionId,
      versionNumber,
      memberId,
      signatureValue,
      signatureType,
      readTimeSeconds,
      readTillBottom
    } = body;

    if (!workspaceId || !versionId || !signatureValue) {
      return NextResponse.json({ error: 'Missing required signature parameters' }, { status: 400 });
    }

    // A policy acknowledgement is a compliance signature: it is stamped
    // with a SHA-256 of the content and rendered on the audit trail as
    // proof that a named person read and accepted it. The signing member
    // is therefore derived from the SESSION, never from the request body —
    // trusting `memberId` let anyone file a colleague's signature, with an
    // arbitrary typed name, against a policy they never opened.
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { data: signingMember } = await supabase
      .from('workspace_members')
      .select('id')
      .eq('workspace_id', workspaceId)
      .eq('user_id', user.id)
      .maybeSingle();

    if (!signingMember) {
      return NextResponse.json({ error: 'Not a member of this workspace' }, { status: 403 });
    }

    // The body's memberId is accepted only when it agrees with the session;
    // signing on someone else's behalf is never valid.
    if (memberId && memberId !== signingMember.id) {
      return NextResponse.json(
        { error: 'A policy can only be signed by the person signing in.' },
        { status: 403 }
      );
    }
    const signerId = signingMember.id;

    // 1. Fetch version object to verify content_hash
    const { data: version } = await supabase
      .from('hr_policy_versions')
      .select('content_hash')
      .eq('id', versionId)
      .single();

    if (!version || !version.content_hash) {
      return NextResponse.json({ error: 'Policy version hash not found' }, { status: 400 });
    }

    const ipAddress = headersList.get('x-forwarded-for') || headersList.get('x-real-ip') || '127.0.0.1';
    const userAgent = headersList.get('user-agent') || 'Browser';

    // 2. Insert digital sign-off record
    const { data: ack, error } = await supabase
      .from('hr_policy_acknowledgements')
      .upsert({
        workspace_id: workspaceId,
        policy_id: id,
        version_id: versionId,
        version_number: versionNumber || 1,
        workspace_member_id: signerId,
        content_hash: version.content_hash,
        status: 'ACTIVE',
        signature_type: signatureType || 'TYPED_NAME',
        signature_value: signatureValue.trim(),
        read_time_seconds: readTimeSeconds || 0,
        read_till_bottom: readTillBottom !== undefined ? readTillBottom : true,
        ip_address: ipAddress,
        user_agent: userAgent,
        device_info: userAgent
      }, {
        onConflict: 'version_id,workspace_member_id'
      })
      .select()
      .single();

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true, acknowledgement: ack });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';

async function computeSHA256(text: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const supabase = await createClient();
    const body = await request.json();
    const { approvedBy, comments } = body;

    // 1. Fetch policy header & latest version
    const { data: policy } = await supabase
      .from('hr_policies')
      .select('*, versions:hr_policy_versions(*)')
      .eq('id', id)
      .single();

    if (!policy) {
      return NextResponse.json({ error: 'Policy not found' }, { status: 404 });
    }

    const versions = policy.versions || [];
    const maxVerNum = versions.reduce((max: number, v: any) => Math.max(max, v.version_number || 1), 0);
    const latestVersion = versions.find((v: any) => v.version_number === maxVerNum);

    if (!latestVersion) {
      return NextResponse.json({ error: 'Policy version not found' }, { status: 404 });
    }

    // 2. Compute SHA-256 Content Hash
    const contentHash = await computeSHA256(latestVersion.content || '');

    // 3. Update version as PUBLISHED with hash & timestamps.
    // Errors are checked: RLS denials used to be swallowed here and
    // the route still returned success while nothing was written.
    const nowStr = new Date().toISOString();
    const { error: versionErr } = await supabase.from('hr_policy_versions').update({
      content_hash: contentHash,
      published_at: nowStr,
      effective_at: latestVersion.effective_at || nowStr,
      approved_by: approvedBy || null,
      approved_at: nowStr,
      approval_comments: comments || 'Approved & Published'
    }).eq('id', latestVersion.id);
    if (versionErr) {
      return NextResponse.json({ error: `Failed to publish version: ${versionErr.message}` }, { status: 500 });
    }

    // 4. Update Policy Header status to PUBLISHED
    const { error: headerErr } = await supabase.from('hr_policies').update({
      status: 'PUBLISHED',
      updated_at: nowStr
    }).eq('id', id);
    if (headerErr) {
      return NextResponse.json({ error: `Failed to publish policy: ${headerErr.message}` }, { status: 500 });
    }

    // 5. Update previous acknowledgements for older versions to SUPERSEDED
    await supabase
      .from('hr_policy_acknowledgements')
      .update({ status: 'SUPERSEDED' })
      .eq('policy_id', id)
      .neq('version_id', latestVersion.id)
      .eq('status', 'ACTIVE');

    // 6. Create Notification Logs for active workspace members
    const { data: members } = await supabase
      .from('workspace_members')
      .select('id')
      .eq('workspace_id', policy.workspace_id);

    if (members && members.length > 0) {
      const notifRows = members.map(m => ({
        workspace_id: policy.workspace_id,
        policy_id: id,
        version_id: latestVersion.id,
        workspace_member_id: m.id,
        channel: 'IN_APP',
        status: 'SENT'
      }));
      await supabase.from('hr_policy_notifications').insert(notifRows);
    }

    return NextResponse.json({
      success: true,
      publishedVersion: latestVersion.version_number,
      contentHash
    });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';
import { assertAffected } from '@/lib/supabase/affected-rows';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const supabase = await createClient();

    const { data: policy, error } = await supabase
      .from('hr_policies')
      .select(`
        *,
        owner:workspace_members!hr_policies_owner_workspace_member_id_fkey(
          id, user_id
        ),
        versions:hr_policy_versions(*),
        targets:hr_policy_targets(*),
        acknowledgements:hr_policy_acknowledgements(*)
      `)
      .eq('id', id)
      .single();

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // Two-step: enrich owner with profile data
    if (policy?.owner?.user_id) {
      const { data: profileData } = await supabase.from('profiles').select('user_id, full_name, avatar_url').eq('user_id', policy.owner.user_id).single();
      if (profileData) policy.owner.profiles = profileData;
    }

    return NextResponse.json({ policy });
  } catch (err: any) {
