      .single();

    if (error) throw error;
    return NextResponse.json({ success: true, folder: data });
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { writeFile, mkdir } from "fs/promises";
import { join } from "path";
import { v4 as uuidv4 } from "uuid";

export async function POST(req: NextRequest) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const formData = await req.formData();
    const file = formData.get("file") as File;
    const workspaceId = formData.get("workspace_id") as string;
    const folderId = formData.get("folder_id") as string | null;
    const dealId = formData.get("deal_id") as string | null;
    const autoFolder = formData.get("auto_folder") as string | null; // e.g. deal name
    
    // Helper to sanitize path components
    const sanitize = (name: string) => name.replace(/[^a-zA-Z0-9 _-]/g, '').trim();

    if (!file || !workspaceId) {
      return NextResponse.json({ error: "Missing file or workspace_id" }, { status: 400 });
    }

    // Check active workspace member
    const { data: isMember } = await supabase.rpc('is_active_workspace_member', {
      p_workspace_id: workspaceId,
      p_user_id: user.id
    });
    if (!isMember) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    let targetFolderId = folderId;

    // Auto-create folder for deals if needed
    if (autoFolder && autoFolder !== 'null') {
      // Find if folder exists
      const { data: existingFolder } = await supabase
        .from("media_folders")
        .select("id")
        .eq("workspace_id", workspaceId)
        .eq("name", autoFolder)
        .is("parent_id", null)
        .maybeSingle();
      
      if (existingFolder) {
        targetFolderId = existingFolder.id;
      } else {
        const { data: newFolder, error: folderErr } = await supabase
          .from("media_folders")
          .insert({ workspace_id: workspaceId, name: autoFolder })
          .select()
          .single();
        if (folderErr) throw folderErr;
        targetFolderId = newFolder.id;
      }
    }

    // Save to local filesystem
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);

    // Fetch workspace name
    const { data: workspaceData } = await supabase.from('workspaces').select('name').eq('id', workspaceId).single();
    const workspaceName = workspaceData ? sanitize(workspaceData.name) : workspaceId;

    // Determine subfolder path
    let subFolderPath = '';
    
    // If it belongs to a deal, fetch the deal name
    if (dealId && dealId !== 'null') {
      const { data: dealData } = await supabase.from('deals').select('title').eq('id', dealId).single();
      if (dealData) {
        subFolderPath = sanitize(dealData.title);
      }
    } 
    // Otherwise if it's placed in a specific folder, fetch the folder hierarchy (for now just the folder name)
    else if (targetFolderId && targetFolderId !== 'null') {
      const { data: folderData } = await supabase.from('media_folders').select('name').eq('id', targetFolderId).single();
      if (folderData) {
        subFolderPath = sanitize(folderData.name);
      }
    } else if (autoFolder) {
      subFolderPath = sanitize(autoFolder);
    }

    const uniqueId = uuidv4();
    // Sanitize the extension as well as the stem — an unsanitized
    // extension like "js/../../x" lets join() escape public/uploads.
    const rawExtension = file.name.split('.').pop() || 'bin';
    const extension =
      rawExtension.replace(/[^a-zA-Z0-9]/g, '').slice(0, 10) || 'bin';
    const sanitizedOriginalName = sanitize(file.name.replace(/\.[^.]*$/, ''));
    const savedName = `${sanitizedOriginalName}_${uniqueId.substring(0, 8)}.${extension}`;
    
    // Construct local path: public/uploads/[Workspace Name]/[Subfolder]/[savedName]
    const uploadDir = join(process.cwd(), "public", "uploads", workspaceName, subFolderPath);
    await mkdir(uploadDir, { recursive: true });
    
    const filePath = join(uploadDir, savedName);
    await writeFile(filePath, buffer);

    const relativePath = `/uploads/${workspaceName}${subFolderPath ? `/${subFolderPath}` : ''}/${savedName}`;

    // Insert into DB
    const insertData: any = {
      workspace_id: workspaceId,
      name: file.name,
      mime_type: file.type,
      file_size: file.size,
      local_path: relativePath,
    };
    if (targetFolderId && targetFolderId !== 'null') insertData.folder_id = targetFolderId;
    if (dealId && dealId !== 'null') insertData.deal_id = dealId;

    const { data: dbFile, error: dbErr } = await supabase
      .from("media_files")
      .insert(insertData)
      .select()
      .single();
    
    if (dbErr) throw dbErr;

    return NextResponse.json({ success: true, file: dbFile });

  } catch (error: any) {
    console.error("[upload error]", error);
    return NextResponse.json({ error: error.message || "Internal server error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createAdminClient } from '@/lib/supabase/admin';
import { createClient } from '@/lib/supabase/server';
import { checkRateLimit, rateLimitResponse } from '@/lib/rate-limit';

const VALID_PLANS = ['growth', 'custom'];

export async function POST(request: NextRequest) {
  try {
    // Public lead form — rate-limit per IP so the prospects table
    // can't be flooded by an anonymous loop.
    const ip =
      request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
      'unknown';
    const limit = checkRateLimit(`prospects:${ip}`, {
      limit: 5,
      windowMs: 60_000,
    });
    if (!limit.success) {
      return rateLimitResponse(limit);
    }

    const body = await request.json();

    const { full_name, company_name, email, phone, team_size, plan_interest, message } = body as {
      full_name?: string;
      company_name?: string;
      email?: string;
      phone?: string;
      team_size?: string;
      plan_interest?: string;
      message?: string;
    };

    // Validate required fields
    if (!full_name?.trim() || !company_name?.trim() || !email?.trim()) {
      return NextResponse.json(
        { error: 'full_name, company_name, and email are required' },
        { status: 400 }
      );
    }

    // Basic email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return NextResponse.json({ error: 'Invalid email address' }, { status: 400 });
    }

    const admin = createAdminClient();

    const { data, error } = await admin
      .from('prospects')
      .insert({
        full_name: full_name.trim(),
        company_name: company_name.trim(),
        email: email.trim().toLowerCase(),
        phone: phone?.trim() || null,
        team_size: team_size?.trim() || null,
        plan_interest: VALID_PLANS.includes(plan_interest || '') ? plan_interest : 'growth',
        message: message?.trim() || null,
        status: 'new',
      })
      .select('id')
      .single();

    if (error) {
      console.error('[prospects] Insert error:', error);
      return NextResponse.json({ error: 'Failed to submit. Please try again.' }, { status: 500 });
    }

    return NextResponse.json({ success: true, id: data.id }, { status: 201 });
  } catch (err: any) {
    console.error('[prospects] Unexpected error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

// Allow PATCH to update prospect status (admin only)
export async function PATCH(request: NextRequest) {
  try {
    // "Admin only" must actually be enforced — this mutates the sales
    // pipeline with a service-role client.
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    const { data: profile } = await supabase
      .from('profiles')
      .select('system_role')
      .eq('user_id', user.id)
      .maybeSingle();
    if (profile?.system_role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const admin = createAdminClient();
    const body = await request.json();
    const { id, status } = body as { id?: string; status?: string };

    if (!id || !status) {
      return NextResponse.json({ error: 'id and status required' }, { status: 400 });
    }

    const validStatuses = ['new', 'contacted', 'converted'];
    if (!validStatuses.includes(status)) {
      return NextResponse.json({ error: 'Invalid status' }, { status: 400 });
    }

    const { error } = await admin
      .from('prospects')
      .update({ status, updated_at: new Date().toISOString() })
      .eq('id', id);

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient as createServerClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';
import { PLANS } from '@/config/plans';


/**
 * POST /api/saas-admin/create-owner
 *
 * Body: { full_name, email, password, org_name, plan?, plan_limits? }
 *
 * Security:
 *  1. Caller must be authenticated AND have system_role = 'super_admin'
 *  2. Uses service-role to create auth.users entry (bypasses signup disabled)
 *  3. Calls create_owner_with_workspace RPC to seed root workspace + system roles
 *  4. Stores plan + plan_limits on the new workspace
 */
export async function POST(request: NextRequest) {
  try {
    // --- 1. Authenticate caller ---
    const supabase = await createServerClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // --- 2. Verify super_admin system role ---
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('system_role')
      .eq('user_id', user.id)
      .maybeSingle();

    if (profileError || profile?.system_role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden: super_admin required' }, { status: 403 });
    }

    // --- 3. Parse & validate body ---
    const body = await request.json();
    const { full_name, email, password, org_name, plan, plan_limits } = body as {
      full_name?: string;
      email?: string;
      password?: string;
      org_name?: string;
      plan?: string;
      plan_limits?: Record<string, unknown>;
    };

    if (!full_name?.trim() || !email?.trim() || !password || !org_name?.trim()) {
      return NextResponse.json(
        { error: 'full_name, email, password, and org_name are required' },
        { status: 400 }
      );
    }

    if (password.length < 8) {
      return NextResponse.json(
        { error: 'Password must be at least 8 characters' },
        { status: 400 }
      );
    }

        const selectedPlan = ['free', 'starter', 'growth', 'business', 'custom'].includes(plan || '')
      ? (plan as string)
      : 'free';

    let effectiveLimits = plan_limits;
    if (!effectiveLimits) {
      const planConfig = PLANS.find((p) => p.id === selectedPlan) || PLANS.find((p) => p.id === 'free')!;
      effectiveLimits = {
        max_members: planConfig.maxUsers === 999999 ? null : planConfig.maxUsers,
        max_workspaces: planConfig.maxWorkspaces === 999999 ? null : planConfig.maxWorkspaces,
        max_storage_gb: selectedPlan === 'business' ? 20 : selectedPlan === 'growth' ? 10 : 5,
        channels: ['whatsapp', 'instagram', 'messenger', 'email'],
        max_automations: selectedPlan === 'free' ? 3 : null,
        max_messages: planConfig.monthlyMessageAllowance === 999999 ? null : planConfig.monthlyMessageAllowance,
      };
    }

    // --- 4. Create auth user via admin API ---
    const adminClient = createAdminClient();

    const { data: newUser, error: createError } = await adminClient.auth.admin.createUser({
      email: email.trim().toLowerCase(),
      password,
      email_confirm: true,
      user_metadata: { full_name: full_name.trim() },
    });

    if (createError) {
      if (createError.message?.includes('already been registered')) {
        return NextResponse.json(
          { error: 'A user with this email already exists' },
          { status: 409 }
        );
      }
      console.error('[create-owner] Auth create error:', createError);
      return NextResponse.json({ error: createError.message }, { status: 500 });
    }

    const ownerId = newUser.user.id;

    // --- 5. Create root workspace + seed system roles via SECURITY DEFINER RPC ---
    const { data: wsData, error: wsError } = await adminClient
      .rpc('create_owner_with_workspace', {
        p_user_id: ownerId,
        p_org_name: org_name.trim(),
      })
      .single();

    if (wsError) {
      await adminClient.auth.admin.deleteUser(ownerId);
      console.error('[create-owner] Workspace RPC error:', wsError);
      return NextResponse.json({ error: wsError.message }, { status: 500 });
    }

    const workspaceId = (wsData as any).workspace_id;

    // --- 6. Store plan + limits on the workspace ---
    if (workspaceId) {
      const { error: planError } = await adminClient
        .from('workspaces')
        .update({ plan: selectedPlan, plan_limits: effectiveLimits })
        .eq('id', workspaceId);

      if (planError) {
        console.warn('[create-owner] Plan update warn:', planError.message);
      }
    }

    return NextResponse.json({
      success: true,
      owner_id: ownerId,
      workspace_id: workspaceId,
      workspace_name: (wsData as any).workspace_name,
      plan: selectedPlan,
    });
  } catch (err: any) {
    console.error('[create-owner] Unexpected error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient as createServerClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';

/**
 * GET /api/saas-admin/dashboard-data
 * Returns all workspaces, profiles, and prospects for the admin dashboard.
 * Requires super_admin session — uses admin client to bypass RLS.
 */
export async function GET() {
  try {
    const supabase = await createServerClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { data: profile } = await supabase
      .from('profiles')
      .select('system_role')
      .eq('user_id', user.id)
      .maybeSingle();

    if (profile?.system_role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const admin = createAdminClient();

    // Fetch all in parallel
    const [profilesRes, workspacesRes, membersRes, prospectsRes] = await Promise.all([
      admin.from('profiles').select('*').order('created_at', { ascending: false }),
      admin.from('workspaces').select('id, name, plan, plan_limits, created_at').order('created_at', { ascending: false }),
      admin.from('workspace_members').select('workspace_id'),
      admin.from('prospects').select('*').order('created_at', { ascending: false }),
    ]);

    // Build member counts
    const memberCounts: Record<string, number> = {};
    (membersRes.data || []).forEach(m => {
      memberCounts[m.workspace_id] = (memberCounts[m.workspace_id] || 0) + 1;
    });

    const workspaces = (workspacesRes.data || []).map(w => ({
      ...w,
      member_count: memberCounts[w.id] || 0,
    }));

    return NextResponse.json({
      profiles: profilesRes.data || [],
      workspaces,
      prospects: prospectsRes.data || [],
      errors: {
        profiles: profilesRes.error?.message,
        workspaces: workspacesRes.error?.message,
        prospects: prospectsRes.error?.message,
      },
    });
  } catch (err: any) {
    console.error('[dashboard-data]', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createAdminClient } from '@/lib/supabase/admin';

// Prefer env-provided credentials; the literals remain only as a
// fallback for existing deployments and should be rotated via env.
const ADMIN_EMAIL = process.env.SAAS_ADMIN_EMAIL || 'info@daylink.in';
const ADMIN_PASSWORD = process.env.SAAS_ADMIN_PASSWORD || 'Tech@132';

/**
 * GET /api/saas-admin/seed-admin
 *
 * Idempotent endpoint that ensures the super_admin account exists with
 * the correct password hash (Admin SDK bcrypt, NOT pgcrypto's crypt()).
 *
 * The SQL migration (014_seed_super_admin.sql) creates the auth user with
 * pgcrypto's crypt() which produces a hash the Supabase Auth Go verifier
 * cannot verify. This route resets the password via Admin API to fix that.
 *
 * Called automatically from the login page on first mount.
 * Protected: only works in non-production OR with ADMIN_SEED_SECRET env var.
 */
export async function GET(request: NextRequest) {
  const secret = request.nextUrl.searchParams.get('secret');
  const envSecret = process.env.ADMIN_SEED_SECRET;

  // ADMIN_SEED_SECRET is required in EVERY environment. The previous
  // dev-mode bypass meant any visitor to the login page could reset
  // the super-admin password to the seed value.
  if (!envSecret) {
    return NextResponse.json(
      { error: 'Set ADMIN_SEED_SECRET in env to enable this endpoint' },
      { status: 403 }
    );
  }
  if (secret !== envSecret) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  try {
    const adminClient = createAdminClient();

    // Find the user by looking up profiles (faster than listing all auth users)
    const { data: profileRow } = await adminClient
      .from('profiles')
      .select('user_id, system_role')
      .eq('email', ADMIN_EMAIL)
      .maybeSingle();

    if (profileRow?.user_id) {
      // User exists — reset password via Admin SDK to produce correct hash
      const { error } = await adminClient.auth.admin.updateUserById(profileRow.user_id, {
        password: ADMIN_PASSWORD,
        email_confirm: true,
      });
      if (error) {
        return NextResponse.json({ error: error.message }, { status: 500 });
      }

      // Ensure super_admin role is set
      if (profileRow.system_role !== 'super_admin') {
        await adminClient
          .from('profiles')
          .update({ system_role: 'super_admin' })
          .eq('user_id', profileRow.user_id);
      }

      return NextResponse.json({
        success: true,
        action: 'password_reset',
        email: ADMIN_EMAIL,
      });
    }

    // No user found — create from scratch via Admin SDK
    const { data: newUser, error: createError } = await adminClient.auth.admin.createUser({
      email: ADMIN_EMAIL,
      password: ADMIN_PASSWORD,
      email_confirm: true,
      user_metadata: { full_name: 'Daylink Admin' },
    });

    if (createError) {
      return NextResponse.json({ error: createError.message }, { status: 500 });
    }

    const userId = newUser.user.id;

    // Set system_role after trigger creates the profile
    await new Promise((r) => setTimeout(r, 300)); // brief wait for DB trigger
    await adminClient
      .from('profiles')
      .update({ system_role: 'super_admin', full_name: 'Daylink Admin' })
      .eq('user_id', userId);

    return NextResponse.json({
      success: true,
      action: 'created',
      email: ADMIN_EMAIL,
    });
  } catch (err: any) {
    console.error('[seed-admin]', err);
    return NextResponse.json({ error: err.message || 'Internal error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient as createServerClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';

/**
 * DELETE /api/saas-admin/tenants
 * Permanently deletes ALL non-super_admin users + their workspaces.
 * Requires: authenticated super_admin session.
 */
export async function DELETE() {
  try {
    // 1. Verify caller is super_admin
    const supabase = await createServerClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { data: profile } = await supabase
      .from('profiles')
      .select('system_role')
      .eq('user_id', user.id)
      .maybeSingle();

    if (profile?.system_role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const admin = createAdminClient();

    // 2. Get all non-super_admin profiles
    const { data: tenantProfiles, error: fetchError } = await admin
      .from('profiles')
      .select('user_id, email')
      .neq('system_role', 'super_admin');

    if (fetchError) {
      return NextResponse.json({ error: fetchError.message }, { status: 500 });
    }

    if (!tenantProfiles || tenantProfiles.length === 0) {
      return NextResponse.json({ success: true, deleted: 0, message: 'No tenants to delete.' });
    }

    let deleted = 0;
    const errors: string[] = [];

    // 3. Delete each tenant auth account (cascades profile + workspace_members via FK)
    for (const p of tenantProfiles) {
      const { error: delError } = await admin.auth.admin.deleteUser(p.user_id);
      if (delError) {
        errors.push(`${p.email}: ${delError.message}`);
      } else {
        deleted++;
      }
    }

    // 4. Clean up workspaces that now have NO members at all (FK
    //    cascades removed the memberships with the users). PostgREST
    //    can't evaluate a SQL subquery inside .not('id','in',...) —
    //    the previous version passed one as a string, which either
    //    errored (cleanup silently never ran) or, worse, would treat
    //    the literal as a value list and match EVERY workspace for
    //    deletion. Resolve the member-owned ids first, then delete
    //    only true orphans.
    const { data: memberRows, error: memberErr } = await admin
      .from('workspace_members')
      .select('workspace_id');

    if (memberErr) {
      console.warn('[delete-tenants] Workspace cleanup skipped:', memberErr.message);
    } else {
      const ownedIds = [
        ...new Set((memberRows ?? []).map((m) => m.workspace_id).filter(Boolean)),
      ];
      let orphanQuery = admin.from('workspaces').delete();
      if (ownedIds.length > 0) {
        orphanQuery = orphanQuery.not(
          'id',
          'in',
          `(${ownedIds.join(',')})`
        );
      }
      const { error: wsError } = await orphanQuery;
      // wsError is non-fatal — log it but proceed
      if (wsError) {
        console.warn('[delete-tenants] Workspace cleanup warn:', wsError.message);
      }
    }

    return NextResponse.json({
      success: errors.length === 0,
      deleted,
      errors: errors.length > 0 ? errors : undefined,
    });
  } catch (err: any) {
    console.error('[delete-tenants] Error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient as createServerClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';

/**
 * PATCH /api/saas-admin/users/[id]
 * SaaS Admin blocks or unblocks any user (including owners).
 * When an owner is blocked, the is_owner_blocked RLS function cascades
 * and denies all workspace data access to all tenant members.
 *
 * Body: { action: 'block' | 'unblock' }
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: targetUserId } = await params;

    // Authenticate caller
    const supabase = await createServerClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Verify super_admin
    const { data: profile } = await supabase
      .from('profiles')
      .select('system_role, email')
      .eq('user_id', user.id)
      .maybeSingle();

    if (profile?.system_role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden: super_admin required' }, { status: 403 });
    }

    const body = await request.json();
    const action = body.action as 'block' | 'unblock';
    if (!action || !['block', 'unblock'].includes(action)) {
      return NextResponse.json({ error: 'action must be "block" or "unblock"' }, { status: 400 });
    }

    // Prevent self-block
    if (targetUserId === user.id) {
      return NextResponse.json({ error: 'Cannot block your own account' }, { status: 400 });
    }

    const newStatus = action === 'block' ? 'blocked' : 'active';
    const adminClient = createAdminClient();

    const { error: updateError } = await adminClient
      .from('profiles')
      .update({ status: newStatus })
      .eq('user_id', targetUserId);

    if (updateError) {
      return NextResponse.json({ error: updateError.message }, { status: 500 });
    }

    return NextResponse.json({ success: true, status: newStatus });
  } catch (err: any) {
    console.error('[saas-admin/users PATCH]:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * DELETE /api/saas-admin/users/[id]
 * SaaS Admin permanently deletes a user (removes auth.users entry).
 * Cascades: workspace_members, profiles all deleted via FK.
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: targetUserId } = await params;

    const supabase = await createServerClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { data: profile } = await supabase
      .from('profiles')
      .select('system_role')
      .eq('user_id', user.id)
      .maybeSingle();

    if (profile?.system_role !== 'super_admin') {
      return NextResponse.json({ error: 'Forbidden: super_admin required' }, { status: 403 });
    }

    if (targetUserId === user.id) {
      return NextResponse.json({ error: 'Cannot delete your own account' }, { status: 400 });
    }

    const adminClient = createAdminClient();
    const { error } = await adminClient.auth.admin.deleteUser(targetUserId);
    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[saas-admin/users DELETE]:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

