import { NextRequest, NextResponse } from 'next/server';
import crypto from 'crypto';
import Razorpay from 'razorpay';
import { createClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';
import { PLANS } from '@/config/plans';

export async function POST(request: NextRequest) {
  try {
    // Payment verification mutates the workspace plan — the caller
    // must be a signed-in admin/owner of that workspace. Without this
    // gate, anyone holding a valid signature for a ₹1 order could
    // upgrade ANY workspace to any plan.
    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json().catch(() => ({}));
    const {
      razorpay_payment_id,
      razorpay_order_id,
      razorpay_signature,
      workspace_id,
      plan_id,
    } = body;

    // Validation
    if (
      !razorpay_payment_id ||
      !razorpay_order_id ||
      !razorpay_signature ||
      !workspace_id ||
      !plan_id
    ) {
      return NextResponse.json(
        { error: 'Missing required signature verification fields' },
        { status: 400 }
      );
    }

    const { data: member } = await supabase
      .from('workspace_members')
      .select('role')
      .eq('workspace_id', workspace_id)
      .eq('user_id', user.id)
      .maybeSingle();
    if (!member || !['owner', 'admin'].includes(member.role)) {
      return NextResponse.json(
        { error: 'Forbidden: only workspace owners or admins can change the plan' },
        { status: 403 }
      );
    }

    const keyId = process.env.RAZORPAY_KEY_ID;
    const keySecret = process.env.RAZORPAY_KEY_SECRET;
    if (!keyId || !keySecret) {
      console.error('[verify-payment] Razorpay secret not configured in environment');
      return NextResponse.json(
        { error: 'Razorpay integration keys are not configured.' },
        { status: 500 }
      );
    }

    // Verify HMAC-SHA256 signature: HMAC-SHA256(order_id + "|" + payment_id, KEY_SECRET)
    const generatedSignature = crypto
      .createHmac('sha256', keySecret)
      .update(`${razorpay_order_id}|${razorpay_payment_id}`)
      .digest('hex');

    if (generatedSignature !== razorpay_signature) {
      return NextResponse.json(
        { error: 'Payment signature mismatch. Verification failed.' },
        { status: 400 }
      );
    }

    // Signatures match! Resolve the plan and verify the PAID AMOUNT
    // actually covers it — the signature only proves "this order was
    // paid", not "the right price was paid for this plan".
    const planConfig = PLANS.find((p) => p.id === plan_id);
    if (!planConfig) {
      return NextResponse.json({ error: 'Invalid plan selected' }, { status: 400 });
    }
    if (planConfig.priceMonthly <= 0) {
      return NextResponse.json(
        { error: 'This plan cannot be purchased through checkout.' },
        { status: 400 }
      );
    }

    const razorpay = new Razorpay({ key_id: keyId, key_secret: keySecret });
    let order: { amount: string | number; currency: string };
    try {
      order = await razorpay.orders.fetch(razorpay_order_id);
    } catch (err) {
      console.error('[verify-payment] Failed to fetch order from Razorpay:', err);
      return NextResponse.json(
        { error: 'Could not verify the payment order with Razorpay.' },
        { status: 400 }
      );
    }

    const paidPaise = Number(order.amount);
    const monthlyPaise = planConfig.priceMonthly * 100;
    const yearlyPaise = planConfig.priceYearly * 100;
    if (
      order.currency !== 'INR' ||
      (paidPaise !== monthlyPaise && paidPaise !== yearlyPaise)
    ) {
      console.error(
        `[verify-payment] Amount mismatch for plan ${plan_id}: paid ${paidPaise}, expected ${monthlyPaise} or ${yearlyPaise}`
      );
      return NextResponse.json(
        { error: 'Paid amount does not match the selected plan.' },
        { status: 400 }
      );
    }

    const admin = createAdminClient();

    // Replay guard — one order upgrades one workspace, once.
    const { data: replayed } = await admin
      .from('workspaces')
      .select('id')
      .contains('plan_limits', { last_order_id: razorpay_order_id })
      .limit(1);
    if (replayed && replayed.length > 0) {
      return NextResponse.json(
        { error: 'This payment has already been applied.' },
        { status: 409 }
      );
    }

    // Map limits structure
    const limits = {
      max_members: planConfig.maxUsers === 999999 ? null : planConfig.maxUsers,
      max_workspaces: planConfig.maxWorkspaces === 999999 ? null : planConfig.maxWorkspaces,
      max_storage_gb: planConfig.id === 'business' ? 20 : planConfig.id === 'growth' ? 10 : 5,
      channels: ['whatsapp', 'instagram', 'messenger', 'email'],
      max_automations: planConfig.id === 'free' ? 3 : null,
      max_messages: planConfig.monthlyMessageAllowance === 999999 ? null : planConfig.monthlyMessageAllowance,
      last_order_id: razorpay_order_id,
    };

    const { error: updateError } = await admin
      .from('workspaces')
      .update({
        plan: planConfig.id,
        plan_limits: limits,
      })
      .eq('id', workspace_id);

    if (updateError) {
      console.error('[verify-payment] Workspace plan update failed:', updateError.message);
      return NextResponse.json(
        { error: `Payment verified, but failed to update workspace: ${updateError.message}` },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      message: 'Payment verified and plan updated successfully',
      plan: planConfig.id,
    });
  } catch (error: any) {
    console.error('[verify-payment] Unexpected error:', error);
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { encrypt } from "@/lib/whatsapp/encryption";

/**
 * GET /api/whatsapp/chatbot-config?workspace_id=...
 * Fetches the chatbot configuration for a specific workspace.
 */
export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const workspaceId = searchParams.get("workspace_id");

    if (!workspaceId) {
      return NextResponse.json({ error: "workspace_id parameter is required" }, { status: 400 });
    }

    const supabase = await createClient();

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Security check: Verify workspace membership
    const { data: member, error: memberErr } = await supabase
      .from("workspace_members")
      .select("id")
      .eq("workspace_id", workspaceId)
      .eq("user_id", user.id)
      .maybeSingle();

    if (memberErr || !member) {
      return NextResponse.json(
        { error: "Forbidden: You are not authorized to view this workspace configuration" },
        { status: 403 }
      );
    }

    const { data: config, error: configError } = await supabase
      .from("chatbot_config")
      .select("*")
      .eq("workspace_id", workspaceId)
      .maybeSingle();

    if (configError) {
      console.error("Error fetching chatbot_config:", configError);
      return NextResponse.json({ error: "Failed to fetch chatbot configuration" }, { status: 500 });
    }

    if (!config) {
      // Return a default blank config if none exists yet
      return NextResponse.json({
        is_enabled: false,
        provider: "groq",
        model: "llama-3.3-70b-versatile",
        system_prompt: "You are a helpful customer service assistant for our business.",
        business_context: "",
        auto_pause_duration: 60,
        response_delay: 0,
        bot_name: "AI Assistant",
        api_key_configured: false,
      });
    }

    // Return config without exposing the actual encrypted API key
    return NextResponse.json({
      ...config,
      api_key: undefined, // Redact the key
      api_key_configured: !!config.api_key,
    });
  } catch (error) {
    console.error("Error in chatbot config GET:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

/**
 * POST /api/whatsapp/chatbot-config
 * Creates or updates the chatbot configuration for a workspace.
 */
export async function POST(request: Request) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const {
      workspace_id,
      is_enabled,
      provider,
      api_key,
      model,
      system_prompt,
      business_context,
      auto_pause_duration,
      response_delay,
      bot_name,
    } = body;

    if (!workspace_id) {
      return NextResponse.json({ error: "workspace_id is required" }, { status: 400 });
    }

    // Security check: Verify workspace membership
    const { data: member, error: memberErr } = await supabase
      .from("workspace_members")
      .select("id")
      .eq("workspace_id", workspace_id)
      .eq("user_id", user.id)
      .maybeSingle();

    if (memberErr || !member) {
      return NextResponse.json(
        { error: "Forbidden: You are not authorized to edit this workspace configuration" },
        { status: 403 }
      );
    }

    // Encrypt the API key if a new one is provided
    let encryptedApiKey: string | undefined = undefined;
    if (api_key) {
      try {
        encryptedApiKey = encrypt(api_key);
      } catch (err) {
        console.error("Encryption of API key failed:", err);
        return NextResponse.json({ error: "Failed to securely encrypt API key" }, { status: 500 });
      }
    }

    // Check if configuration already exists
    const { data: existing } = await supabase
      .from("chatbot_config")
      .select("id, api_key")
      .eq("workspace_id", workspace_id)
      .maybeSingle();

    const updatePayload: Record<string, any> = {
      is_enabled: !!is_enabled,
      provider: provider || "groq",
      model: model || "llama-3.3-70b-versatile",
      system_prompt: system_prompt || "You are a helpful customer service assistant for our business.",
      business_context: business_context || "",
      auto_pause_duration: auto_pause_duration !== undefined ? Number(auto_pause_duration) : 60,
      response_delay: response_delay !== undefined ? Number(response_delay) : 0,
      bot_name: bot_name || "AI Assistant",
      updated_at: new Date().toISOString(),
    };

    // If new API key is provided, update it. If not, preserve the existing one.
    if (encryptedApiKey !== undefined) {
      updatePayload.api_key = encryptedApiKey;
    }

    if (existing) {
      const { error: updateError } = await supabase
        .from("chatbot_config")
        .update(updatePayload)
        .eq("workspace_id", workspace_id);

      if (updateError) {
        console.error("Error updating chatbot_config:", updateError);
        return NextResponse.json({ error: "Failed to update chatbot configuration" }, { status: 500 });
      }
    } else {
      const { error: insertError } = await supabase.from("chatbot_config").insert({
        workspace_id,
        ...updatePayload,
        // If it's a new config and no api_key is passed, it remains null (using global fallback)
        api_key: encryptedApiKey || null,
      });

      if (insertError) {
        console.error("Error inserting chatbot_config:", insertError);
        return NextResponse.json({ error: "Failed to save chatbot configuration" }, { status: 500 });
      }
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Error in chatbot config POST:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

/**
