}

import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { getWhatsAppProvider } from '@/lib/whatsapp/providers/factory'
import { decrypt, encrypt, isLegacyFormat } from '@/lib/whatsapp/encryption'
import {
  sanitizePhoneForMeta,
  isValidE164,
  phoneVariants,
  isRecipientNotAllowedError,
} from '@/lib/whatsapp/phone-utils'
import { withMetaErrorHint } from '@/lib/whatsapp/meta-error-hints'
import {
  checkRateLimit,
  rateLimitResponse,
  RATE_LIMITS,
} from '@/lib/rate-limit'
import { checkMessageLimit } from '@/lib/limits'
import type { MessageTemplate } from '@/types'

export async function POST(request: Request) {
  try {
    const supabase = await createClient()

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser()

    if (authError || !user) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    // Per-user rate limit. Bucket key is scoped to this route so
    // `/broadcast` has an independent budget.
    const limit = checkRateLimit(`send:${user.id}`, RATE_LIMITS.send)
    if (!limit.success) {
      return rateLimitResponse(limit)
    }

    const body = await request.json()
    const {
      conversation_id,
      message_type,
      content_text,
      media_url,
      filename,
      template_name,
      template_language,
      template_params,
      template_message_params,
      reply_to_message_id,
    } = body

    if (!conversation_id || !message_type) {
      return NextResponse.json(
        { error: 'conversation_id and message_type are required' },
        { status: 400 }
      )
    }

    const MEDIA_KINDS = ['image', 'video', 'document', 'audio'] as const
    type MediaKind = (typeof MEDIA_KINDS)[number]
    const isMediaSend = (MEDIA_KINDS as readonly string[]).includes(message_type)

    if (!isMediaSend && message_type !== 'text' && message_type !== 'template') {
      return NextResponse.json(
        { error: `Unsupported message_type "${message_type}"` },
        { status: 400 }
      )
    }

    if (message_type === 'text' && !content_text) {
      return NextResponse.json(
        { error: 'content_text is required for text messages' },
        { status: 400 }
      )
    }

    if (message_type === 'template' && !template_name) {
      return NextResponse.json(
        { error: 'template_name is required for template messages' },
        { status: 400 }
      )
    }

    if (isMediaSend && !media_url) {
      return NextResponse.json(
        { error: `media_url is required for ${message_type} messages` },
        { status: 400 }
      )
    }

    // Meta caps media captions at 1024 chars — mirror the composer's limit
    // here so direct API callers get a clear error instead of a Meta 400.
    if (isMediaSend && typeof content_text === 'string' && content_text.length > 1024) {
      return NextResponse.json(
        { error: 'Media captions are limited to 1024 characters' },
        { status: 400 }
      )
    }

    // Fetch conversation with its workspace_id (workspace-scoped RLS applied)
    const { data: conversation, error: convError } = await supabase
      .from('conversations')
      .select('*, contact:contacts(*)')
      .eq('id', conversation_id)
      .single()

    if (convError || !conversation) {
      return NextResponse.json(
        { error: 'Conversation not found' },
        { status: 404 }
      )
    }

    const contact = conversation.contact
    if (!contact?.phone) {
      return NextResponse.json(
        { error: 'Contact phone number not found' },
        { status: 400 }
      )
    }

    // Sanitize and validate phone
    const sanitizedPhone = sanitizePhoneForMeta(contact.phone)
    if (!isValidE164(sanitizedPhone)) {
      return NextResponse.json(
        { error: 'Invalid phone number format' },
        { status: 400 }
      )
    }

    // Fetch WhatsApp config scoped by workspace_id
    const workspaceId = conversation.workspace_id

    // Check message quota limits
    const limitCheck = await checkMessageLimit(workspaceId);
    if (!limitCheck.allowed) {
      return NextResponse.json(
        { error: limitCheck.error || 'Message limit reached. Please upgrade your plan.' },
        { status: 403 }
      );
    }

    const { data: config, error: configError } = await supabase
      .from('whatsapp_config')
      .select('*')
      .eq('workspace_id', workspaceId)
      .maybeSingle()

    if (configError || !config) {
      return NextResponse.json(
        { error: 'WhatsApp not configured for this workspace. Please set up your WhatsApp integration first.' },
        { status: 400 }
      )
    }

    const accessToken = decrypt(config.access_token)

    // Self-heal legacy CBC-encrypted tokens (fire-and-forget)
    if (isLegacyFormat(config.access_token)) {
      void supabase
        .from('whatsapp_config')
        .update({ access_token: encrypt(accessToken) })
        .eq('id', config.id)
        .then(({ error }) => {
          if (error) {
            console.warn(
              '[whatsapp/send] access_token GCM upgrade failed:',
              error.message,
            )
          }
        })
    }

    // Resolve the correct provider driver
    const provider = getWhatsAppProvider(config.provider || 'meta')

    if (isMediaSend && typeof provider.sendMedia !== 'function') {
      return NextResponse.json(
        { error: `Media messages are not supported for the "${config.provider || 'meta'}" provider` },
        { status: 400 }
      )
    }

    // Quoted reply — resolve the parent message's provider (Meta) id so
    // the send carries a `context` and renders as a reply on the
    // recipient's phone. Scoped to the same conversation so a client
    // can't quote across threads/workspaces. Missing/unsent parents are
    // ignored rather than failing the send.
    let contextMessageId: string | undefined
    let replyToMessageId: string | null = null
    if (reply_to_message_id) {
      const { data: parentMsg } = await supabase
        .from('messages')
        .select('id, message_id')
        .eq('id', reply_to_message_id)
        .eq('conversation_id', conversation_id)
        .maybeSingle()
      if (parentMsg) {
        replyToMessageId = parentMsg.id
        if (parentMsg.message_id) contextMessageId = parentMsg.message_id
      }
    }

    // Template sends: load the workspace's template row so the structured
    // send-builder path (media headers, URL-button variables) is used and
    // the correct language code is sent — Meta rejects a template when the
    // language doesn't match an approved translation.
    let templateRow: MessageTemplate | undefined
    let templateLanguage: string | undefined =
      typeof template_language === 'string' && template_language
        ? template_language
        : undefined
    if (message_type === 'template') {
      let templateQuery = supabase
        .from('message_templates')
        .select('*')
        .eq('workspace_id', workspaceId)
        .eq('name', template_name)
      if (templateLanguage) {
        templateQuery = templateQuery.eq('language', templateLanguage)
      }
      const { data: rows } = await templateQuery.limit(1)
      if (rows && rows.length > 0) {
        templateRow = rows[0] as MessageTemplate
        templateLanguage = templateLanguage || templateRow.language
      }
    }

    // Structured per-send template values (body/header/button params).
    // Whitelisted so arbitrary client JSON can't reach the send builder.
    const messageParams =
      message_type === 'template' &&
      template_message_params &&
      typeof template_message_params === 'object'
        ? {
            body: Array.isArray(template_message_params.body)
              ? template_message_params.body
              : undefined,
            headerText:
              typeof template_message_params.headerText === 'string'
                ? template_message_params.headerText
                : undefined,
            buttonParams:
              template_message_params.buttonParams &&
              typeof template_message_params.buttonParams === 'object'
                ? template_message_params.buttonParams
                : undefined,
          }
        : undefined

    // Build a unified send function using the driver
    const attempt = async (phone: string): Promise<string> => {
      if (message_type === 'template') {
        const result = await provider.sendTemplate({
          phoneId: config.phone_number_id,
          wabaId: config.waba_id,
          token: accessToken,
          to: phone,
          templateName: template_name,
          params: template_params || [],
          language: templateLanguage,
          template: templateRow,
          messageParams,
          contextMessageId,
        })
        return result.messageId
      }
      if (isMediaSend) {
        const result = await provider.sendMedia!({
          phoneId: config.phone_number_id,
          wabaId: config.waba_id,
          token: accessToken,
          to: phone,
          kind: message_type as MediaKind,
          link: media_url,
          caption: content_text || undefined,
          filename: typeof filename === 'string' ? filename : undefined,
          contextMessageId,
        })
        return result.messageId
      }
      const result = await provider.sendMessage({
        phoneId: config.phone_number_id,
        wabaId: config.waba_id,
        token: accessToken,
        to: phone,
        text: content_text,
        contextMessageId,
      })
      return result.messageId
    }

    // Phone-variant retry loop (important for Meta sandbox & trunk-0 numbers)
    let waMessageId = ''
    let workingPhone = sanitizedPhone

    try {
      const variants = phoneVariants(sanitizedPhone)
      let lastError: unknown = null

      for (const variant of variants) {
        try {
          waMessageId = await attempt(variant)
          workingPhone = variant
          lastError = null
          break
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err)
          // Only retry when Meta specifically rejects the recipient;
          // other errors (bad token, invalid template) should surface immediately.
          if (!isRecipientNotAllowedError(message)) {
            throw err
          }
          lastError = err
          console.warn(`[whatsapp/send] variant "${variant}" rejected, trying next…`)
        }
      }

      if (lastError) throw lastError
    } catch (err) {
      const message = err instanceof Error ? err.message : 'API error'
      console.error('WhatsApp send failed for all variants:', message)
      return NextResponse.json(
        { error: `WhatsApp API error: ${withMetaErrorHint(message)}` },
        { status: 502 }
      )
    }

    // Auto-correct the contact's stored phone number if an alternate variant succeeded
    if (workingPhone !== sanitizedPhone) {
      console.log(
        `[whatsapp/send] Auto-corrected contact phone: ${sanitizedPhone} → ${workingPhone}`
      )
      await supabase
        .from('contacts')
        .update({ phone: workingPhone })
        .eq('id', contact.id)
    }

    // Insert message into DB.
    //
    // At this point WhatsApp has ALREADY delivered the message, so a
    // failed insert loses it from the CRM permanently. Optional columns
    // (reply_to_message_id — migration 070) are therefore stripped and
    // retried rather than failing the whole write: the reply-quote link
    // is worth far less than the message itself.
    const baseRow: Record<string, unknown> = {
      conversation_id,
      sender_type: 'agent',
      content_type: message_type,
      content_text: content_text || null,
      media_url: media_url || null,
      template_name: template_name || null,
      message_id: waMessageId,
      status: 'sent',
    }

    const insertMessage = async (row: Record<string, unknown>) =>
      supabase.from('messages').insert(row).select().single()

    let { data: messageRecord, error: msgError } = await insertMessage({
      ...baseRow,
      ...(replyToMessageId ? { reply_to_message_id: replyToMessageId } : {}),
    })

    const isMissingColumn = (e: { code?: string; message?: string } | null) =>
      e?.code === 'PGRST204' ||
      e?.code === '42703' ||
      /could not find the .* column|column .* does not exist/i.test(e?.message ?? '')

    if (msgError && replyToMessageId && isMissingColumn(msgError)) {
      console.warn(
        '[whatsapp/send] messages.reply_to_message_id is missing — run migration 070. Saving without the reply link.',
      )
      ;({ data: messageRecord, error: msgError } = await insertMessage(baseRow))
    }

    if (msgError || !messageRecord) {
      console.error('Error inserting sent message:', msgError)
      return NextResponse.json(
        {
          error: `The message was delivered on WhatsApp but could not be saved to the CRM: ${msgError?.message ?? 'unknown error'}`,
          whatsapp_message_id: waMessageId,
          delivered: true,
        },
        { status: 500 }
      )
    }

    // Fetch chatbot configuration to see if we should auto-pause the chatbot
    let botStatusUpdates: Record<string, any> = {}
    const { data: chatbotConfig } = await supabase
      .from('chatbot_config')
      .select('is_enabled, auto_pause_duration')
      .eq('workspace_id', workspaceId)
      .maybeSingle()

    if (chatbotConfig && chatbotConfig.is_enabled && chatbotConfig.auto_pause_duration !== 0) {
      botStatusUpdates = {
        bot_status: 'paused',
        bot_paused_until: chatbotConfig.auto_pause_duration > 0
          ? new Date(Date.now() + chatbotConfig.auto_pause_duration * 60 * 1000).toISOString()
          : null
      }
    }

    // Update conversation last message & bot status
    await supabase
      .from('conversations')
      .update({
        last_message_text: content_text || `[${message_type}]`,
        last_message_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        ...botStatusUpdates
      })
      .eq('id', conversation_id)

    return NextResponse.json({
      success: true,
      message_id: messageRecord.id,
      whatsapp_message_id: waMessageId,
    })
  } catch (error) {
    console.error('Error in WhatsApp send POST:', error)
    return NextResponse.json(
      { error: 'Failed to send message' },
      { status: 500 }
    )
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { generateChatbotResponse } from "@/lib/chatbot/ai-service";
import { decrypt } from "@/lib/whatsapp/encryption";

export async function POST(request: Request) {
  try {
    const { conversationId } = await request.json();

    if (!conversationId) {
      return NextResponse.json({ error: "conversationId is required" }, { status: 400 });
    }

    const supabase = await createClient();

    // Authenticate user
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Fetch conversation to get workspace_id
    const { data: conversation, error: convError } = await supabase
      .from("conversations")
      .select("workspace_id")
      .eq("id", conversationId)
      .maybeSingle();

    if (convError || !conversation) {
      return NextResponse.json({ error: "Conversation not found" }, { status: 404 });
    }

    const workspaceId = conversation.workspace_id;

    // Security check: Verify workspace membership
    const { data: member, error: memberErr } = await supabase
      .from("workspace_members")
      .select("id")
      .eq("workspace_id", workspaceId)
      .eq("user_id", user.id)
      .maybeSingle();

    if (memberErr || !member) {
      return NextResponse.json(
        { error: "Forbidden: You are not authorized to access this workspace" },
        { status: 403 }
      );
    }

    // Fetch chatbot config
    const { data: config, error: configErr } = await supabase
      .from("chatbot_config")
      .select("*")
      .eq("workspace_id", workspaceId)
      .maybeSingle();

    if (configErr || !config) {
      return NextResponse.json({ draft: null, message: "Chatbot not configured" });
    }

    // Fetch message history (last 10 messages)
    const { data: dbMessages, error: msgErr } = await supabase
      .from("messages")
      .select("sender_type, content_text, created_at")
      .eq("conversation_id", conversationId)
      .order("created_at", { ascending: false })
      .limit(10);

    if (msgErr || !dbMessages || dbMessages.length === 0) {
      return NextResponse.json({ draft: null, message: "No message history found" });
    }

    // Format message history chronologically
    const history: { role: "user" | "assistant"; content: string }[] = [];
    const reversedMessages = [...dbMessages].reverse();

    // We take the very last message as the user message if it is from the customer
    const lastMsg = reversedMessages[reversedMessages.length - 1];
    const isLastFromCustomer = lastMsg.sender_type === "customer";
    
    // All preceding messages go into history
    const contextMessages = isLastFromCustomer ? reversedMessages.slice(0, -1) : reversedMessages;

    for (const msg of contextMessages) {
      if (!msg.content_text) continue;
      history.push({
        role: msg.sender_type === "customer" ? "user" : "assistant",
        content: msg.content_text,
      });
    }

    const userMessage = isLastFromCustomer ? (lastMsg.content_text || "") : "Provide a follow-up or reply suggestion based on the context.";

    // Decrypt API key
    let decryptedKey: string | null = null;
    if (config.api_key) {
      try {
        decryptedKey = decrypt(config.api_key);
      } catch (err) {
        console.error("Decrypting tenant API key failed:", err);
      }
    }

    // Construct the specialized system prompt for the draft helper
    const copilotInstructions = `
CRITICAL INSTRUCTIONS FOR AI COPILOT DRAFT SUGGESTIONS:
1. You are an AI assistant helping a human CRM agent draft a response to a patient on WhatsApp.
2. Based on the business context and history, generate a single, highly concise, friendly, and professional response that the agent can review, modify, and send.
3. DO NOT include any introductory greetings like "Here is a suggested reply:" or comments.
4. DO NOT include metadata instructions like "Typing..." or "Buttons:". If choices are required, list them as clean bullet points or write them naturally (e.g. "• Option 1\n• Option 2").
5. Only output the raw text of the message draft itself.
`;

    const systemPrompt = `${config.system_prompt}\n${copilotInstructions}\n\nBusiness Context:\n${config.business_context || ""}`;

    try {
      const draft = await generateChatbotResponse({
        provider: config.provider,
        apiKey: decryptedKey,
        model: config.model,
        systemPrompt,
        history,
        userMessage,
      });

      return NextResponse.json({ draft: draft?.trim() || null });
    } catch (err: any) {
      if (err?.message?.includes('API key is missing')) {
        return NextResponse.json({ draft: null, warning: err.message });
      }
      throw err;
    }
  } catch (error) {
    console.error("Error in suggest-draft route:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { NextResponse } from 'next/server'
import type { SupabaseClient } from '@supabase/supabase-js'
import { createClient } from '@/lib/supabase/server'
import { decrypt } from '@/lib/whatsapp/encryption'
import { submitMessageTemplate } from '@/lib/whatsapp/meta-api'
import {
  validateTemplatePayload,
  type TemplatePayload,
} from '@/lib/whatsapp/template-validators'
import { buildMetaTemplatePayload } from '@/lib/whatsapp/template-components'
import { ensureImageHeaderHandle } from '@/lib/whatsapp/template-header-handle'
import { normalizeStatus } from '@/lib/whatsapp/template-status-normalize'

/**
 * Shared upsert payload builder — both the Meta-failure path and the
 * Meta-success path write nearly identical rows; dropping the shared
 * fields here means adding a column later only touches one spot.
 */
function buildUpsertRow(
  userId: string,
  workspaceId: string,
  payload: TemplatePayload,
  extras: {
    status: 'DRAFT' | string
    metaTemplateId: string | null
    submissionError: string | null
  },
) {
  return {
    // Tenancy is workspace-based: message_templates.workspace_id is
    // NOT NULL (migration 010) and there is no account_id column —
    // the caller's membership in `workspace_id` is enforced below.
    // Original author — kept as audit only. The unique index is
    // still on (user_id, name, language) — see the upsert helper
    // for the cross-teammate dedup follow-up.
    user_id: userId,
    workspace_id: workspaceId,
    name: payload.name,
    category: payload.category,
    language: payload.language,
    header_type: payload.header_type ?? null,
    header_content: payload.header_content ?? null,
    header_media_url: payload.header_media_url ?? null,
    header_handle: payload.header_handle ?? null,
    body_text: payload.body_text,
    footer_text: payload.footer_text ?? null,
    buttons: payload.buttons ?? null,
    sample_values: payload.sample_values ?? null,
    status: extras.status,
    meta_template_id: extras.metaTemplateId,
    submission_error: extras.submissionError,
    // Clear stale rejection_reason whenever we re-submit; the
    // webhook will set it again if Meta still rejects.
    rejection_reason: extras.submissionError ? null : null,
    last_submitted_at: new Date().toISOString(),
  }
}

// Columns added by migration 072 that older databases may not have
// yet. The template is already live on Meta by the time we persist, so
// a missing column must not lose the row — we strip these and retry.
const OPTIONAL_TEMPLATE_COLUMNS = [
  'header_media_url',
  'submission_error',
  'rejection_reason',
  'last_submitted_at',
] as const

function isMissingColumnError(e: { code?: string; message?: string } | null) {
  return (
    e?.code === 'PGRST204' ||
    e?.code === '42703' ||
    /could not find the .* column|column .* does not exist/i.test(
      e?.message ?? '',
    )
  )
}

async function upsertTemplateRow(
  supabase: SupabaseClient,
  row: ReturnType<typeof buildUpsertRow>,
) {
  // TODO(workspace-sharing): conflict target is still scoped to
  // user_id. Once a follow-up migration drops the legacy unique
  // index on (user_id, name, language) and adds (workspace_id,
  // name, language), switch `onConflict` here so two teammates
  // can't shadow each other's same-named template.
  const doUpsert = (payload: Record<string, unknown>) =>
    supabase
      .from('message_templates')
      .upsert(payload, { onConflict: 'user_id,name,language' })
      .select()
      .single()

  const first = await doUpsert(row)
  if (!first.error || !isMissingColumnError(first.error)) return first

  // Retry without the migration-072 columns so the template still
  // saves (minus the extra metadata) on a not-yet-migrated database.
  console.warn(
    '[templates/submit] message_templates is missing optional columns — run migration 072. Saving without them.',
  )
  const stripped: Record<string, unknown> = { ...row }
  for (const col of OPTIONAL_TEMPLATE_COLUMNS) delete stripped[col]
  return doUpsert(stripped)
}

/**
 * Submit a template to Meta for approval AND persist it locally.
 *
 * Auth → fetch whatsapp_config → validate → (DRY_RUN short-circuit) →
 * POST to Meta → upsert local row by (user_id, name, language) with
 * status, meta_template_id, sample_values, last_submitted_at.
 *
 * When WHATSAPP_TEMPLATES_DRY_RUN=true, we skip the network call and
 * insert a row with a synthetic `dry-run-<uuid>` meta_template_id so
 * CI / local dev can exercise the full UI without a real Meta App.
 *
 * On the Meta side this is a one-way trip — a row can only be
 * submitted; editing or deleting requires hsm_id and lives in PR 4.
 */
export async function POST(request: Request) {
  try {
    const supabase = await createClient()
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser()
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    let rawBody: any
    try {
      rawBody = await request.json()
    } catch {
      return NextResponse.json({ error: 'Invalid JSON body.' }, { status: 400 })
    }

    const { workspace_id, ...payload } = rawBody as any

    if (!workspace_id) {
      return NextResponse.json({ error: 'workspace_id is required.' }, { status: 400 })
    }

    // Security Gate: Enforce workspace membership
    const { data: member, error: memberErr } = await supabase
      .from('workspace_members')
      .select('id')
      .eq('workspace_id', workspace_id)
      .eq('user_id', user.id)
      .maybeSingle()

    if (memberErr || !member) {
      return NextResponse.json(
        { error: 'Forbidden: You are not authorized to access this workspace.' },
        { status: 403 },
      )
    }

    if (payload.category === 'Authentication') {
      return NextResponse.json(
        {
          error:
            'AUTHENTICATION templates are not yet supported here — create them in Meta WhatsApp Manager and use "Sync from Meta".',
        },
        { status: 400 },
      )
    }

    try {
      validateTemplatePayload(payload)
    } catch (e) {
      return NextResponse.json(
        { error: e instanceof Error ? e.message : 'Validation failed.' },
        { status: 400 },
      )
    }

    const dryRun =
      process.env.WHATSAPP_TEMPLATES_DRY_RUN === 'true' ||
      process.env.WHATSAPP_TEMPLATES_DRY_RUN === '1'

    let metaTemplateId: string
    let metaStatus: string

    if (dryRun) {
      metaTemplateId = `dry-run-${crypto.randomUUID()}`
      metaStatus = 'PENDING'
    } else {
      const { data: config, error: configError } = await supabase
        .from('whatsapp_config')
        .select('*')
        .eq('workspace_id', workspace_id)
        .single()
      if (configError || !config) {
        return NextResponse.json(
          {
            error:
              'WhatsApp not configured. Connect your WhatsApp Business account in Settings first.',
          },
          { status: 400 },
        )
      }
      if (!config.waba_id) {
        return NextResponse.json(
          {
            error:
              'WABA (WhatsApp Business Account) ID missing. Re-connect your account in Settings.',
          },
          { status: 400 },
        )
      }

      const accessToken = decrypt(config.access_token)

      // Image headers need a Resumable-Upload handle (Meta rejects a
      // plain URL at creation). Derive it from header_media_url before
      // building the payload. Surfaces a 400 with an actionable message
      // (missing META_APP_ID, unreachable URL, wrong type/size).
      try {
        await ensureImageHeaderHandle(payload, accessToken)
      } catch (e) {
        return NextResponse.json(
          { error: e instanceof Error ? e.message : 'Header image upload failed.' },
          { status: 400 },
        )
      }

      const metaPayload = buildMetaTemplatePayload(payload)
      try {
        const meta = await submitMessageTemplate({
          wabaId: config.waba_id,
          accessToken,
          payload: metaPayload,
        })
        metaTemplateId = meta.id
        metaStatus = meta.status
      } catch (e) {
        const message = e instanceof Error ? e.message : 'Meta submit failed.'
        // Persist the failure so the user can retry; row stays DRAFT
        // until they fix and re-submit.
        await upsertTemplateRow(
          supabase,
          buildUpsertRow(user.id, workspace_id, payload, {
            status: 'DRAFT',
            metaTemplateId: null,
            submissionError: message,
          }),
        )
        const isRateLimit = /\b429\b/.test(message)
        return NextResponse.json(
          {
            error: isRateLimit
              ? 'Meta rate limit hit (100 template creates per hour). Try again later.'
              : message,
          },
          { status: isRateLimit ? 429 : 502 },
        )
      }
    }

    const { data: row, error: upsertErr } = await upsertTemplateRow(
      supabase,
      buildUpsertRow(user.id, workspace_id, payload, {
        status: normalizeStatus(metaStatus),
        metaTemplateId,
        submissionError: null,
      }),
    )

    if (upsertErr) {
      // The submit succeeded on Meta's side but we failed to persist
      // locally. That's a data-drift state — surface the meta_template_id
      // so the user can recover via "Sync from Meta".
      return NextResponse.json(
        {
          error: `Submitted to Meta but failed to save locally: ${upsertErr.message}. Run "Sync from Meta" to recover.`,
          meta_template_id: metaTemplateId,
        },
        { status: 500 },
      )
    }

    return NextResponse.json({
      success: true,
      template: row,
      dry_run: dryRun,
    })
  } catch (error) {
    console.error('Error submitting template:', error)
    return NextResponse.json(
      {
        error:
          error instanceof Error ? error.message : 'Failed to submit template.',
      },
      { status: 500 },
    )
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { decrypt, encrypt, isLegacyFormat } from '@/lib/whatsapp/encryption'
import { getMediaUrl } from '@/lib/whatsapp/meta-api'
import { isSamePhoneNumber, normalizePhone } from '@/lib/whatsapp/phone-utils'
import { verifyMetaWebhookSignature } from '@/lib/whatsapp/webhook-signature'
import { runAutomationsForTrigger } from '@/lib/automations/engine'
import { dispatchInboundToFlows } from '@/lib/flows/engine'
import {
  buildParsedInbound,
  extractInteractiveReplyId,
} from '@/lib/flows/parse-inbound'
import {
  handleTemplateWebhookChange,
  isTemplateWebhookField,
} from '@/lib/whatsapp/template-webhook'
import { processChatbotReply } from '@/lib/chatbot/processor'

// Lazy-initialized to avoid build-time crash when env vars are missing
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let _adminClient: any = null
function supabaseAdmin() {
  if (!_adminClient) {
    _adminClient = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    )
  }
  return _adminClient
}



interface WhatsAppMessage {
  id: string
  from: string
  timestamp: string
  type: string
  text?: { body: string }
  image?: { id: string; mime_type: string; caption?: string }
  video?: { id: string; mime_type: string; caption?: string }
  document?: { id: string; mime_type: string; filename?: string; caption?: string }
  audio?: { id: string; mime_type: string }
  sticker?: { id: string; mime_type: string }
  location?: { latitude: number; longitude: number; name?: string; address?: string }
  reaction?: { message_id: string; emoji: string }
  /**
   * Set when the customer taps a button or list row on an interactive
   * message we sent. `button_reply.id` / `list_reply.id` is whatever id
   * we put on the button/row when sending — the Flows engine uses this
   * to advance the per-contact run.
   */
  interactive?: {
    type: 'button_reply' | 'list_reply'
    button_reply?: { id: string; title: string }
    list_reply?: { id: string; title: string; description?: string }
  }
}

interface WhatsAppWebhookEntry {
  id: string
  changes: Array<{
    value: {
      messaging_product: string
      metadata: {
        display_phone_number: string
        phone_number_id: string
      }
      contacts?: Array<{
        profile: { name: string }
        wa_id: string
      }>
      messages?: WhatsAppMessage[]
      statuses?: Array<{
        id: string
        status: string
        timestamp: string
        recipient_id: string
      }>
    }
    field: string
  }>
}

// GET - Webhook verification
export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url)
    const mode = searchParams.get('hub.mode')
    const challenge = searchParams.get('hub.challenge')
    const verifyToken = searchParams.get('hub.verify_token')

    if (mode !== 'subscribe' || !challenge || !verifyToken) {
      // Return 200 for simple uptime pings or third-party provider test checks
      return NextResponse.json(
        { status: 'active', message: 'Daily CRM Webhook is active' },
        { status: 200 }
      )
    }

    // Fetch all whatsapp configs to check verify tokens
    const { data: configs, error: configError } = await supabaseAdmin()
      .from('whatsapp_config')
      .select('id, verify_token')

    if (configError || !configs) {
      console.error('Error fetching configs for verification:', configError)
      return NextResponse.json(
        { error: 'Verification failed' },
        { status: 403 }
      )
    }

    // Check if any config's verify_token matches. Also collect the
    // matching row so we can opportunistically upgrade its token to
    // GCM if it was still in the legacy CBC format.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let matchedConfig: any = null
    for (const config of configs) {
      if (!config.verify_token) continue
      try {
        const decrypted = decrypt(config.verify_token)
        if (decrypted === verifyToken || config.verify_token === verifyToken) {
          matchedConfig = config
          break
        }
      } catch {
        if (config.verify_token === verifyToken) {
          matchedConfig = config
          break
        }
      }
    }

    if (matchedConfig) {
      // Fire-and-forget GCM upgrade. Safe to run on every subscribe
      // since it's a no-op once the column is already GCM.
      if (isLegacyFormat(matchedConfig.verify_token)) {
        void supabaseAdmin()
          .from('whatsapp_config')
          .update({ verify_token: encrypt(verifyToken) })
          .eq('id', matchedConfig.id)
          .then(({ error }: { error: unknown }) => {
            if (error) {
              console.warn(
                '[webhook] verify_token GCM upgrade failed:',
                (error as { message?: string })?.message ?? error,
              )
            }
          })
      }
      // Return challenge as plain text
      return new Response(challenge, {
        status: 200,
        headers: { 'Content-Type': 'text/plain' },
      })
    }

    return NextResponse.json(
      { error: 'Verification token mismatch' },
      { status: 403 }
    )
  } catch (error) {
    console.error('Error in webhook GET verification:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export interface WebhookLogEntry {
  id: string
  timestamp: string
  method: string
  signature: string | null
  userAgent: string | null
  rawBody: string
  status: number
  error?: string | null
}

export const recentWebhookLogs: WebhookLogEntry[] = []

export function recordWebhookLog(entry: Omit<WebhookLogEntry, 'id' | 'timestamp'>) {
  const logItem: WebhookLogEntry = {
    id: Math.random().toString(36).substring(2, 9),
    timestamp: new Date().toISOString(),
    ...entry,
  }
  recentWebhookLogs.unshift(logItem)
  if (recentWebhookLogs.length > 50) {
    recentWebhookLogs.pop()
  }
}

// POST - Receive messages
export async function POST(request: Request) {
  // Read raw body first so we can HMAC-verify the exact bytes Meta
  // signed. request.json() would re-encode and break the signature.
  const rawBody = await request.text()
  const signature = request.headers.get('x-hub-signature-256')
  const userAgent = request.headers.get('user-agent')

  let body: { entry?: WhatsAppWebhookEntry[] }
  try {
    body = JSON.parse(rawBody)
  } catch {
    recordWebhookLog({
      method: 'POST',
      signature,
      userAgent,
      rawBody: rawBody.slice(0, 500),
      status: 400,
      error: 'Invalid JSON',
    })
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  // Normalize flat ApiAuto payload to standard WhatsApp entry structure
  if (!body.entry && (body as any).phoneid) {
    const flat = body as any
    body.entry = [
      {
        id: String(flat.phoneid),
        changes: [
          {
            field: 'messages',
            value: {
              messaging_product: 'whatsapp',
              metadata: {
                display_phone_number: '',
                phone_number_id: String(flat.phoneid),
              },
              contacts: [
                {
                  profile: { name: flat.name || flat.mobile || 'WhatsApp User' },
                  wa_id: String(flat.mobile || ''),
                },
              ],
              messages: [
                {
                  id: flat.msgId || `apiauto-${flat.mobile || 'unknown'}-${Date.now()}`,
                  from: String(flat.mobile || ''),
                  timestamp: String(Math.floor(Date.now() / 1000)),
                  type: 'text',
                  text: { body: flat.message || '' },
                },
              ],
            },
          },
        ],
      },
    ]
  }





  // Determine if signature verification can be safely bypassed.
  // Strategy:
  // 1. If the payload contains phone_number_ids we recognise as 'apiauto' -> bypass
  // 2. If NO Meta signature header is present at all AND there is at least one
  //    apiauto workspace in the DB -> bypass (handles cases where ApiAuto doesn't
  //    include phone_number_id in the top-level metadata field we expect)
  // 3. Otherwise enforce Meta HMAC signature.
  let requiresSignature = true
  let matchedAnyConfig = false
  const phoneIds = new Set<string>()

  if (body.entry) {
    for (const entry of body.entry) {
      for (const change of entry.changes) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const meta = change.value.metadata as any
        // ApiAuto may send phone_number_id at different paths — check all common ones
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const val = change.value as any
        const pid =
          meta?.phone_number_id ||
          meta?.phoneId ||
          val?.phone_number_id ||
          entry.id  // some providers use the entry id as the phone identifier
        if (pid) phoneIds.add(String(pid))
      }
    }
  }

  const { data: dbConfigs } = await supabaseAdmin()
    .from('whatsapp_config')
    .select('*')

  if (phoneIds.size > 0 && dbConfigs) {
    const matchingConfigs = dbConfigs.filter((c: { phone_number_id?: string; waba_id?: string }) => {
      const cPhone = c.phone_number_id?.trim()
      const cWaba = c.waba_id?.trim()
      return Array.from(phoneIds).some(
        (pid) =>
          (cPhone && (cPhone === pid || pid.includes(cPhone))) ||
          (cWaba && (cWaba === pid || pid.includes(cWaba)))
      )
    })
    if (matchingConfigs.length > 0) {
      matchedAnyConfig = true
      requiresSignature = matchingConfigs.some((c: { provider?: string }) => c.provider === 'meta')
    }
  }

  // Fallback: no signature header + at least one apiauto workspace —
  // but ONLY when the payload matched no known config. A payload that
  // names a known Meta phone_number_id must always carry a valid
  // signature; without this guard, one apiauto tenant anywhere on the
  // instance would let anonymous callers inject forged inbound
  // messages into every Meta tenant's inbox. Unmatched payloads are
  // dropped by the tenant-isolation check in processWebhook anyway.
  if (requiresSignature && !signature && !matchedAnyConfig && dbConfigs) {
    const hasApiAuto = dbConfigs.some((c: { provider?: string }) => c.provider === 'apiauto')
    if (hasApiAuto) {
      console.log('[webhook] No signature header — allowing through for apiauto workspace')
      requiresSignature = false
    }
  }

  if (requiresSignature && !verifyMetaWebhookSignature(rawBody, signature, dbConfigs ?? [])) {
    console.warn('[webhook] rejected request with invalid signature. Body preview:', rawBody.slice(0, 200))
    // Record the rejection so /api/admin/webhook-status makes this
    // failure mode visible — a wrong META_APP_SECRET / app_secret
    // otherwise looks like "Meta just never calls us".
    recordWebhookLog({
      method: 'POST',
      signature,
      userAgent,
      rawBody: rawBody.slice(0, 1000),
      status: 401,
      error:
        'Invalid x-hub-signature-256 — the configured Meta App Secret does not match this app. Fix META_APP_SECRET (or the App Secret in Settings → WhatsApp) with the value from Meta App Dashboard → App settings → Basic.',
    })
    return NextResponse.json({ error: 'Invalid signature' }, { status: 401 })
  }

  // Await processWebhook to guarantee serverless execution context stays alive
  // until all database writes (contacts, conversations, messages) are complete.
  try {
    await processWebhook(body)
  } catch (error) {
    console.error('Error processing webhook:', error)
  }

  recordWebhookLog({
    method: 'POST',
    signature,
    userAgent,
    rawBody: rawBody.slice(0, 1000),
    status: 200,
  })

  return NextResponse.json({ status: 'received' }, { status: 200 })
}

async function processWebhook(body: { entry?: WhatsAppWebhookEntry[] }) {
  if (!body.entry) return

  for (const entry of body.entry) {
    for (const change of entry.changes) {
      // Template-lifecycle events (status / quality / components
      // updates from Meta) come in on a different change.field and
      // have a different value shape — route them through the
      // dedicated handler. Skip the messaging branches below so we
      // don't try to read message-shaped fields off a template event.
      if (isTemplateWebhookField(change.field)) {
        await handleTemplateWebhookChange(
          { field: change.field, value: change.value as unknown },
          supabaseAdmin(),
        )
        continue
      }

      const value = change.value

      // Handle status updates
      if (value.statuses) {
        for (const status of value.statuses) {
          await handleStatusUpdate(status)
        }
      }

      // Handle incoming messages
      if (!value.messages || !Array.isArray(value.messages) || value.messages.length === 0) continue

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const meta = value.metadata as any
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const val = value as any
      const phoneNumberId =
        meta?.phone_number_id ||
        meta?.phoneId ||
        val?.phone_number_id ||
        entry.id

      // Find user's config by phone_number_id with smart fallbacks
      const { data: configs } = await supabaseAdmin()
        .from('whatsapp_config')
        .select('*')

      // Strict Multi-Tenant SaaS Isolation: Match config strictly by phone_number_id or waba_id.
      // NEVER fall back to another tenant's workspace config to prevent cross-tenant data leakage.
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      let config: any = null
      if (configs && configs.length > 0) {
        const pId = String(phoneNumberId).trim()
        const eId = String(entry.id).trim()

        config = configs.find(
          (c: { phone_number_id?: string; waba_id?: string }) => {
            const cPhone = c.phone_number_id?.trim()
            const cWaba = c.waba_id?.trim()
            return (
              (cPhone && (cPhone === pId || cPhone === eId || pId.includes(cPhone))) ||
              (cWaba && (cWaba === pId || cWaba === eId || pId.includes(cWaba)))
            )
          }
        )
      }

      if (!config) {
        console.error(
          `[webhook] TENANT ISOLATION GUARANTEE: Unmatched incoming payload (phone_number_id: ${phoneNumberId}, entry_id: ${entry.id}). Dropping request to prevent cross-tenant data leakage.`
        )
        continue
      }

      const decryptedAccessToken = decrypt(config.access_token)

      // Ensure config has a valid workspace_id
      let resolvedWorkspaceId = config.workspace_id
      if (!resolvedWorkspaceId && config.user_id) {
        const { data: member } = await supabaseAdmin()
          .from('workspace_members')
          .select('workspace_id')
          .eq('user_id', config.user_id)
          .limit(1)
          .maybeSingle()

        if (member?.workspace_id) {
          resolvedWorkspaceId = member.workspace_id
          void supabaseAdmin()
            .from('whatsapp_config')
            .update({ workspace_id: resolvedWorkspaceId })
            .eq('id', config.id)
        }
      }

      for (let i = 0; i < value.messages.length; i++) {
        const message = value.messages[i]
        const contact =
          (value.contacts && (value.contacts[i] || value.contacts[0])) ||
          { profile: { name: message.from }, wa_id: message.from }

        await processMessage(
          message,
          contact,
          config.user_id,
          decryptedAccessToken,
          resolvedWorkspaceId
        )
      }
    }
  }
}

// The happy-path status ladder — pending → sent → delivered → read →
// replied. Webhook replays must never regress a recipient back down
// this ladder.
//
// `failed` is NOT on this ladder. It's a terminal side branch that is
// only valid from the early states (pending / sent) — once Meta has
// delivered or the user has read or replied, a later "failed" status
// event is a bug in Meta's pipeline or a spoof attempt and must be
// ignored.
const RECIPIENT_STATUS_LADDER = [
  'pending',
  'sent',
  'delivered',
  'read',
  'replied',
] as const

function ladderLevel(s: string): number {
  const idx = (RECIPIENT_STATUS_LADDER as readonly string[]).indexOf(s)
  return idx < 0 ? -1 : idx
}

/**
 * Can a recipient transition from `current` to `incoming`?
 *   - Along the ladder, only forward moves are allowed.
 *   - `failed` is accepted only from `pending` or `sent`; it's refused
 *     once the recipient has reached any of the success states.
 */
function isValidStatusTransition(current: string, incoming: string): boolean {
  if (incoming === 'failed') {
    return current === 'pending' || current === 'sent'
  }
  if (current === 'failed') {
    return false // failed is terminal
  }
  const ci = ladderLevel(current)
  const ii = ladderLevel(incoming)
  if (ii < 0) return false // unknown incoming status
  if (ci < 0) return true // unknown current — accept anything on the ladder
  return ii > ci
}

async function handleStatusUpdate(status: {
  id: string
  status: string
  timestamp: string
  recipient_id: string
}) {
  // 1) Mirror onto messages (legacy behavior) — Meta's status values
  //    already match the CHECK constraint on messages.status. Apply
  //    the same forward-only ladder as broadcast_recipients so an
  //    out-of-order delivery receipt can't regress a `read` message
  //    back to `delivered` (read ticks flickering off in the inbox).
  const { data: msgRows, error: msgFetchErr } = await supabaseAdmin()
    .from('messages')
    .select('id, status')
    .eq('message_id', status.id)

  if (msgFetchErr) {
    console.error('Error fetching message for status update:', msgFetchErr)
  } else if (msgRows) {
    for (const msgRow of msgRows) {
      if (!isValidStatusTransition(msgRow.status, status.status)) continue
      const { error: msgErr } = await supabaseAdmin()
        .from('messages')
        .update({ status: status.status })
        .eq('id', msgRow.id)
      if (msgErr) {
        console.error('Error updating message status:', msgErr)
      }
    }
  }

  // 2) Mirror onto broadcast_recipients via whatsapp_message_id
  //    (added in migration 003). The aggregate trigger on
  //    broadcast_recipients re-derives the parent broadcast's
  //    sent/delivered/read/failed counts automatically.
  //    Guard the timestamp — a non-numeric value would make
  //    toISOString() throw and abort the whole webhook batch.
  const tsMs = parseInt(status.timestamp) * 1000
  const tsIso = Number.isFinite(tsMs)
    ? new Date(tsMs).toISOString()
    : new Date().toISOString()

  const { data: recipient, error: recFetchErr } = await supabaseAdmin()
    .from('broadcast_recipients')
    .select('id, status')
    .eq('whatsapp_message_id', status.id)
    .maybeSingle()

  if (recFetchErr) {
    console.error('Error fetching broadcast recipient:', recFetchErr)
    return
  }
  if (!recipient) return // message wasn't part of a broadcast — fine

  // Guard transitions — forward-only on the success ladder, and
  // `failed` only from pre-delivered states.
  if (!isValidStatusTransition(recipient.status, status.status)) return

  const update: Record<string, unknown> = { status: status.status }
  if (status.status === 'sent' && !('sent_at' in update)) update.sent_at = tsIso
  if (status.status === 'delivered') update.delivered_at = tsIso
  if (status.status === 'read') update.read_at = tsIso

  const { error: recUpdateErr } = await supabaseAdmin()
    .from('broadcast_recipients')
    .update(update)
    .eq('id', recipient.id)

  if (recUpdateErr) {
    console.error('Error updating broadcast recipient status:', recUpdateErr)
  }
}

/**
 * If an inbound message's sender is on a still-unreplied
 * broadcast_recipients row, flip it to `replied` so the reply count
 * advances on the parent broadcast.
 *
 * Runs on a best-effort basis — failures here must not break the
 * main inbound-message flow, so errors are swallowed with a log.
 */
async function flagBroadcastReplyIfAny(userId: string, contactId: string) {
  try {
    // Most recent outbound broadcast that hasn't been replied to yet.
    const { data: recs, error } = await supabaseAdmin()
      .from('broadcast_recipients')
      .select('id, status, broadcast_id, broadcasts!inner(user_id)')
      .eq('contact_id', contactId)
      .eq('broadcasts.user_id', userId)
      .in('status', ['sent', 'delivered', 'read'])
      .order('created_at', { ascending: false })
      .limit(1)

    if (error || !recs || recs.length === 0) return

    const row = recs[0]
    const { error: updErr } = await supabaseAdmin()
      .from('broadcast_recipients')
      .update({ status: 'replied', replied_at: new Date().toISOString() })
      .eq('id', row.id)

    if (updErr) {
      console.error('Error marking broadcast recipient replied:', updErr)
    }
  } catch (err) {
    console.error('flagBroadcastReplyIfAny failed:', err)
  }
}

async function processMessage(
  message: WhatsAppMessage,
  contact: { profile: { name: string }; wa_id: string },
  userId: string,
  accessToken: string,
  workspaceId: string
) {
  const senderPhone = normalizePhone(message.from)
  const contactName = contact.profile.name

  // Parse message content based on type
  const { contentText, mediaUrl, mediaType } = await parseMessageContent(
    message,
    accessToken
  )

  // Find or create contact
  const contactOutcome = await findOrCreateContact(
    userId,
    senderPhone,
    contactName,
    workspaceId
  )
  if (!contactOutcome) return
  const contactRecord = contactOutcome.contact

  // Find or create conversation
  const conversation = await findOrCreateConversation(
    userId,
    contactRecord.id,
    workspaceId
  )
  if (!conversation) return

  // Insert message — field names MUST match the messages table schema
  // (see supabase/migrations/001_initial_schema.sql):
  //   conversation_id, sender_type, content_type, content_text,
  //   media_url, template_name, message_id, status, created_at
  // `mediaType` is intentionally unused — the schema has no media_type
  // column; the MIME type is only used to construct the proxy URL during
  // parseMessageContent. Silence the unused-var warning:
  void mediaType

  // The messages.content_type CHECK constraint only allows:
  //   text, image, document, audio, video, location, template
  // Map incoming WhatsApp types that aren't in that list to the closest
  // allowed value so the INSERT doesn't fail with a constraint error.
  const ALLOWED_CONTENT_TYPES = new Set([
    'text', 'image', 'document', 'audio', 'video', 'location', 'template', 'interactive',
  ])
  const contentType = ALLOWED_CONTENT_TYPES.has(message.type)
    ? message.type
    : message.type === 'sticker'
      ? 'image'   // stickers are images
      : 'text'    // reaction, unknown → text fallback

  // Determine whether this is the contact's very first inbound message
  // BEFORE we insert, so the count is accurate. Covers the case where
  // the contact row already exists (manual add / CSV import) but they've
  // never messaged us before — which new_contact_created wouldn't catch.
  const { count: priorCustomerMsgCount } = await supabaseAdmin()
    .from('messages')
    .select('id', { count: 'exact', head: true })
    .eq('conversation_id', conversation.id)
    .eq('sender_type', 'customer')
  const isFirstInboundMessage = (priorCustomerMsgCount ?? 0) === 0

  // Guard the timestamp — a malformed value would make toISOString()
  // throw and drop every remaining message in this webhook batch.
  const msgTsMs = parseInt(message.timestamp) * 1000
  const msgCreatedAt = Number.isFinite(msgTsMs)
    ? new Date(msgTsMs).toISOString()
    : new Date().toISOString()

  // Button/list taps carry the reply_id we stamped on the outgoing
  // interactive message — persist it (messages.interactive_reply_id,
  // migration 027) so the inbox can render which option was tapped.
  const interactiveReplyId = extractInteractiveReplyId(message)

  const { error: msgError } = await supabaseAdmin().from('messages').insert({
    conversation_id: conversation.id,
    sender_type: 'customer',
    content_type: contentType,
    content_text: contentText,
    media_url: mediaUrl,
    interactive_reply_id: interactiveReplyId,
    message_id: message.id,
    status: 'delivered',
    created_at: msgCreatedAt,
  })

  if (msgError) {
    console.error('Error inserting message:', msgError)
    return
  }

  // Update conversation. The unread counter uses an atomic SQL
  // increment (migration 053) — a client-side read-modify-write loses
  // counts when two messages of one webhook batch land concurrently.
  // Falls back to the racy version when the RPC isn't installed yet.
  const { error: rpcErr } = await supabaseAdmin().rpc(
    'record_inbound_conversation_update',
    {
      p_conversation_id: conversation.id,
      p_last_message_text: contentText || `[${message.type}]`,
    }
  )
  if (rpcErr) {
    const { error: convError } = await supabaseAdmin()
      .from('conversations')
      .update({
        last_message_text: contentText || `[${message.type}]`,
        last_message_at: new Date().toISOString(),
        unread_count: (conversation.unread_count || 0) + 1,
        updated_at: new Date().toISOString(),
      })
      .eq('id', conversation.id)

    if (convError) {
      console.error('Error updating conversation:', convError)
    }
  }

  // If this contact was a recent broadcast recipient, flag the reply
  // so the broadcast's `replied_count` advances (via the aggregate
  // trigger installed in migration 003).
  await flagBroadcastReplyIfAny(userId, contactRecord.id)

  // ============================================================
  // Flow runner dispatch.
  //
  // If the runner consumes the message (it either advanced an active
  // run or started a new one), we suppress the `new_message_received`
  // + `keyword_match` automation triggers for this inbound. Customer
  // is navigating the bot menu, not sending a fresh trigger word
  // that should fork into automations.
  //
  // The relationship-level triggers (`new_contact_created`,
  // `first_inbound_message`) still fire even when consumed — those
  // are about WHO is messaging, not what they said.
  //
  // Awaited (not fire-and-forget) because we need the `consumed`
  // result before deciding whether to dispatch automations. The
  // runner has its own try/catch and never throws. Accounts with
  // no active flows take the runner's early-exit "no_match" path
  // basically for free (one indexed SELECT for the active run).
  // ============================================================
  // buildParsedInbound maps interactive button/list taps to
  // kind:'interactive_reply' (with the reply_id the engine matches
  // against send_buttons / send_list options); everything else goes
  // through as kind:'text'.
  const flowResult = await dispatchInboundToFlows({
    userId,
    contactId: contactRecord.id,
    conversationId: conversation.id,
    message: buildParsedInbound(message, contentText),
    isFirstInboundMessage,
  })
  const flowConsumed = flowResult.consumed

  // Fire any automations that react to this webhook event. All dispatches
  // run here (not earlier) so the contact, conversation, and inbound
  // message all exist before any step — including send_message — runs.
  // Fire-and-forget: a slow or failing automation must not block the
  // webhook's 200 OK response to Meta.
  const inboundText = contentText ?? message.text?.body ?? ''
  const automationTriggers: (
    | 'new_contact_created'
    | 'first_inbound_message'
    | 'new_message_received'
    | 'keyword_match'
  )[] = []
  // Content-level triggers are suppressed when a flow consumed the
  // message — see the comment block above.
  if (!flowConsumed) {
    automationTriggers.push('new_message_received', 'keyword_match')
  }
  // new_contact_created fires only when the webhook just auto-created the
  // contact row. first_inbound_message fires whenever this is the contact's
  // first-ever customer-sent message — a superset that also catches
  // manually-imported contacts sending for the first time. We dispatch both
  // so users can pick whichever semantic they want; an automation that
  // listens to only one trigger runs only when that trigger matches.
  if (contactOutcome.wasCreated) automationTriggers.unshift('new_contact_created')
  if (isFirstInboundMessage) automationTriggers.unshift('first_inbound_message')
  for (const triggerType of automationTriggers) {
    runAutomationsForTrigger({
      userId,
      triggerType,
      contactId: contactRecord.id,
      context: {
        message_text: inboundText,
        conversation_id: conversation.id,
      },
    }).catch((err) => console.error('[automations] dispatch failed:', err))
  }

  // Trigger AI Chatbot response asynchronously
  if (contentText) {
    processChatbotReply({
      workspaceId,
      conversationId: conversation.id,
      contactId: contactRecord.id,
      messageText: contentText,
    }).catch((err) => {
      console.error('[chatbot] processor failed:', err)
    })
  }
}

async function parseMessageContent(
  message: WhatsAppMessage,
  accessToken: string
): Promise<{
  contentText: string | null
  mediaUrl: string | null
  mediaType: string | null
}> {
  // getMediaUrl signature is (mediaId, accessToken) — earlier code had
  // the args swapped, so every verification hit an invalid Meta URL and
  // fell through to the catch block, leaving mediaUrl as null. That's
  // why images showed up as empty bubbles in the inbox.
  const verifyAndBuildUrl = async (
    mediaId: string
  ): Promise<string | null> => {
    try {
      await getMediaUrl({ mediaId, accessToken })
      return `/api/whatsapp/media/${mediaId}`
    } catch (error) {
      console.error(
        `Failed to verify media ${mediaId} with Meta:`,
        error instanceof Error ? error.message : error
      )
      return null
    }
  }

  switch (message.type) {
    case 'text':
      return {
        contentText: message.text?.body || null,
        mediaUrl: null,
        mediaType: null,
      }

    case 'image':
      if (message.image?.id) {
        return {
          contentText: message.image.caption || null,
          mediaUrl: await verifyAndBuildUrl(message.image.id),
          mediaType: message.image.mime_type,
        }
      }
      return { contentText: null, mediaUrl: null, mediaType: null }

    case 'video':
      if (message.video?.id) {
        return {
          contentText: message.video.caption || null,
          mediaUrl: await verifyAndBuildUrl(message.video.id),
          mediaType: message.video.mime_type,
        }
      }
      return { contentText: null, mediaUrl: null, mediaType: null }

    case 'document':
      if (message.document?.id) {
        return {
          contentText:
            message.document.caption || message.document.filename || null,
          mediaUrl: await verifyAndBuildUrl(message.document.id),
          mediaType: message.document.mime_type,
        }
      }
      return { contentText: null, mediaUrl: null, mediaType: null }

    case 'audio':
      if (message.audio?.id) {
        return {
          contentText: null,
          mediaUrl: await verifyAndBuildUrl(message.audio.id),
          mediaType: message.audio.mime_type,
        }
      }
      return { contentText: null, mediaUrl: null, mediaType: null }

    case 'sticker':
      // Stickers are images under the hood. Treat them as such so the
      // MessageBubble renders the <img>. The caller maps the DB
      // content_type to 'image' for the CHECK constraint.
      if (message.sticker?.id) {
        return {
          contentText: null,
          mediaUrl: await verifyAndBuildUrl(message.sticker.id),
          mediaType: message.sticker.mime_type,
        }
      }
      return { contentText: null, mediaUrl: null, mediaType: null }

    case 'location':
      if (message.location) {
        const loc = message.location
        const locationText = [loc.name, loc.address, `${loc.latitude},${loc.longitude}`]
          .filter(Boolean)
          .join(' - ')
        return {
          contentText: locationText,
          mediaUrl: null,
          mediaType: null,
        }
      }
      return { contentText: null, mediaUrl: null, mediaType: null }

    case 'reaction':
      return {
        contentText: message.reaction?.emoji || null,
        mediaUrl: null,
        mediaType: null,
      }

    case 'interactive': {
      // The customer tapped a reply button or a list row on a message
      // we previously sent. Meta delivers `interactive.button_reply` for
      // 3-button messages and `interactive.list_reply` for list messages.
      // Use the human-readable title as contentText so the inbox bubble
      // renders the tap legibly, and return null for media fields.
      const reply =
        message.interactive?.button_reply ?? message.interactive?.list_reply
      if (reply?.id) {
        return {
          contentText: reply.title || reply.id,
          mediaUrl: null,
          mediaType: null,
        }
      }
      return {
        contentText: '[Interactive reply]',
        mediaUrl: null,
        mediaType: null,
      }
    }

    default:
      return {
        contentText: `[Unsupported message type: ${message.type}]`,
        mediaUrl: null,
        mediaType: null,
      }
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ContactRow = any

interface ContactOutcome {
  contact: ContactRow
  /** True when this call created the row; drives new_contact_created
   *  automation dispatch in processMessage. */
  wasCreated: boolean
}

async function findExistingContactByPhone(
  workspaceId: string,
  phone: string
): Promise<ContactRow | null> {
  const normalized = normalizePhone(phone)
  if (!normalized) return null

  // Preferred path: digit-normalized match in SQL (migration 070).
  // Matching on the raw stored string missed numbers saved with
  // internal spaces ("+91 99023 19132"), which made the webhook create
  // a duplicate contact and drop the customer's reply into a new chat.
  const rpc = await supabaseAdmin().rpc('find_contacts_by_phone_digits', {
    p_workspace_id: workspaceId || null,
    p_digits: normalized,
  })
  if (!rpc.error) {
    // The RPC already orders exact-match-first, then oldest-first.
    return (rpc.data as ContactRow[] | null)?.[0] ?? null
  }

  // Fallback for databases without migration 070: raw-suffix LIKE.
  // Ordered by created_at so a workspace that already has duplicate
  // rows for one number still resolves to the SAME contact every
  // time, instead of whichever row Postgres happened to return first.
  const suffix = normalized.length >= 8 ? normalized.slice(-8) : normalized

  let query = supabaseAdmin().from('contacts').select('*')
  if (workspaceId) {
    query = query.eq('workspace_id', workspaceId)
  }
  const { data, error } = await query
    .like('phone', `%${suffix}`)
    .order('created_at', { ascending: true })

  if (error || !data) return null

  const rows = data as ContactRow[]
  return (
    rows.find((c) => normalizePhone(c.phone) === normalized) ??
    rows.find((c) => isSamePhoneNumber(c.phone, phone)) ??
    null
  )
}

async function findOrCreateContact(
  userId: string,
  phone: string,
  name: string,
  workspaceId: string
): Promise<ContactOutcome | null> {
  const existingContact = await findExistingContactByPhone(workspaceId, phone)

  if (existingContact) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const updatePayload: Record<string, any> = {}
    if (name && name !== existingContact.name) {
      updatePayload.name = name
    }
    if (workspaceId && !existingContact.workspace_id) {
      updatePayload.workspace_id = workspaceId
    }
    if (Object.keys(updatePayload).length > 0) {
      updatePayload.updated_at = new Date().toISOString()
      await supabaseAdmin()
        .from('contacts')
        .update(updatePayload)
        .eq('id', existingContact.id)
    }
    return { contact: existingContact, wasCreated: false }
  }

  // Create new contact
  const { data: newContact, error: createError } = await supabaseAdmin()
    .from('contacts')
    .insert({
      user_id: userId,
      phone,
      name: name || phone,
      workspace_id: workspaceId || null,
    })
    .select()
    .single()

  if (createError) {
    // SQLSTATE 23505: Unique constraint violation (lost insert race)
    // Re-resolve existing contact row instead of dropping the message
    if ((createError as { code?: string })?.code === '23505') {
      const raced = await findExistingContactByPhone(workspaceId, phone)
      if (raced) return { contact: raced, wasCreated: false }
    }
    console.error('Error creating contact:', createError)
    return null
  }

  return { contact: newContact, wasCreated: true }
}

async function findOrCreateConversation(userId: string, contactId: string, workspaceId: string) {
  // Look for existing conversation by contact_id first. The table has
  // no unique constraint on (workspace_id, contact_id), so duplicates
  // can exist — .maybeSingle() would error on >1 row and we'd insert
  // yet another duplicate. Take the most recent one instead.
  let query = supabaseAdmin().from('conversations').select('*').eq('contact_id', contactId)
  if (workspaceId) {
    query = query.eq('workspace_id', workspaceId)
  }

  const { data: existingRows } = await query
    .order('last_message_at', { ascending: false, nullsFirst: false })
    .limit(1)
  const existing = existingRows?.[0]

  if (existing) {
    if (workspaceId && !existing.workspace_id) {
      await supabaseAdmin()
        .from('conversations')
        .update({ workspace_id: workspaceId })
        .eq('id', existing.id)
      existing.workspace_id = workspaceId
    }
    return existing
  }

  // Create new conversation
  const { data: newConv, error: createError } = await supabaseAdmin()
    .from('conversations')
    .insert({
      user_id: userId,
      contact_id: contactId,
      workspace_id: workspaceId || null,
      status: 'open',
      bot_status: 'active',
      last_message_at: new Date().toISOString(),
    })
    .select()
    .single()

  if (createError) {
    if ((createError as { code?: string })?.code === '23505') {
      const raced = await supabaseAdmin()
        .from('conversations')
        .select('*')
        .eq('contact_id', contactId)
        .order('last_message_at', { ascending: false, nullsFirst: false })
        .limit(1)
      if (raced.data?.[0]) return raced.data[0]
    }
    console.error('Error creating conversation:', createError)
    return null
  }

  return newConv
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient as createServerClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';

async function verifyOwner(workspaceId: string) {
  const supabase = await createServerClient();
  const { data: { user }, error } = await supabase.auth.getUser();
  if (error || !user) return { error: 'Unauthorized', status: 401 };

  const { data: member } = await supabase
    .from('workspace_members')
    .select('role')
    .eq('workspace_id', workspaceId)
    .eq('user_id', user.id)
    .maybeSingle();

  if (member?.role !== 'owner') {
    return { error: 'Forbidden: owner role required', status: 403 };
  }
  return { error: null, status: 200 };
}

/**
 * POST /api/workspace/roles
 * Owner creates a custom ABAC role for their workspace.
 *
 * Body: { workspace_id, name, description?, permissions: Record<string, boolean> }
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { workspace_id, name, description, permissions } = body as {
      workspace_id?: string;
      name?: string;
      description?: string;
      permissions?: Record<string, boolean>;
    };

    if (!workspace_id || !name?.trim()) {
      return NextResponse.json(
        { error: 'workspace_id and name are required' },
        { status: 400 }
      );
    }

    const auth = await verifyOwner(workspace_id);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const adminClient = createAdminClient();
    const { data, error } = await adminClient
      .from('workspace_roles')
      .insert({
        workspace_id,
        name: name.trim(),
        description: description?.trim() || null,
        permissions: permissions ?? {},
        is_system: false,
      })
      .select()
      .single();

    if (error) {
      if (error.code === '23505') {
        return NextResponse.json(
          { error: `A role named "${name.trim()}" already exists in this workspace` },
          { status: 409 }
        );
      }
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true, role: data });
  } catch (err: any) {
    console.error('[workspace/roles POST]:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * PATCH /api/workspace/roles
 * Owner updates a role's name, description, or permissions.
 *
 * Body: { workspace_id, role_id, name?, description?, permissions? }
 *
 * System roles (`is_system = true`) used to be rejected outright, which
 * made the built-in Viewer un-narrowable — an admin who wanted a
 * "CRM-only viewer" had to invent a parallel custom role. They are now
 * editable, but ONLY their `permissions` map: the name and description
 * are dropped from the update so Owner / Admin / Viewer can never be
 * renamed out from under the code that looks them up by name (migration
 * 074's seeding, `DEFAULT_ROLE_NAMES`, the members-tab enum mapping).
 * DELETE still refuses system roles entirely, and the owner gate is
 * unchanged.
 */
export async function PATCH(request: NextRequest) {
  try {
    const body = await request.json();
    const { workspace_id, role_id, name, description, permissions } = body as {
      workspace_id?: string;
      role_id?: string;
      name?: string;
      description?: string;
      permissions?: Record<string, boolean>;
    };

    if (!workspace_id || !role_id) {
      return NextResponse.json(
        { error: 'workspace_id and role_id are required' },
        { status: 400 }
      );
    }

    const auth = await verifyOwner(workspace_id);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const adminClient = createAdminClient();

    // Is this a built-in role? Decides which fields may be written.
    const { data: existing, error: lookupError } = await adminClient
      .from('workspace_roles')
      .select('id, is_system')
      .eq('id', role_id)
      .eq('workspace_id', workspace_id)
      .maybeSingle();

    if (lookupError) {
      return NextResponse.json({ error: lookupError.message }, { status: 500 });
    }
    if (!existing) {
      return NextResponse.json({ error: 'Role not found' }, { status: 404 });
    }

    const updates: Record<string, unknown> = {};
    if (permissions) updates.permissions = permissions;
    if (!existing.is_system) {
      if (name?.trim()) updates.name = name.trim();
      if (description !== undefined) updates.description = description;
    } else if (name !== undefined || description !== undefined) {
      // Be explicit rather than silently ignoring a rename attempt.
      return NextResponse.json(
        {
          error:
            'Built-in roles cannot be renamed or re-described — only their permissions can be changed.',
        },
        { status: 400 }
      );
    }

    if (Object.keys(updates).length === 0) {
      return NextResponse.json({ error: 'No updates provided' }, { status: 400 });
    }

    const { data, error } = await adminClient
      .from('workspace_roles')
      .update(updates)
      .eq('id', role_id)
      .eq('workspace_id', workspace_id)
      .select()
      .single();

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true, role: data });
  } catch (err: any) {
    console.error('[workspace/roles PATCH]:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * DELETE /api/workspace/roles
 * Owner deletes a custom role. Rejects if system role or if members use it.
 *
 * Body: { workspace_id, role_id }
 */
export async function DELETE(request: NextRequest) {
  try {
    const body = await request.json();
    const { workspace_id, role_id } = body as {
      workspace_id?: string;
      role_id?: string;
    };

    if (!workspace_id || !role_id) {
      return NextResponse.json(
        { error: 'workspace_id and role_id are required' },
        { status: 400 }
      );
    }

    const auth = await verifyOwner(workspace_id);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const adminClient = createAdminClient();

    // Built-ins are permanent. The `.eq('is_system', false)` filter below
    // would already no-op, but a silent 200 reads as a successful delete
    // in the UI — say so instead.
    const { data: existing } = await adminClient
      .from('workspace_roles')
      .select('is_system')
      .eq('id', role_id)
      .eq('workspace_id', workspace_id)
      .maybeSingle();

    if (existing?.is_system) {
      return NextResponse.json(
        { error: 'Built-in roles cannot be deleted.' },
        { status: 400 }
      );
    }

    // Check: no members assigned this role
    const { count } = await adminClient
      .from('workspace_members')
      .select('id', { count: 'exact', head: true })
      .eq('workspace_id', workspace_id)
      .eq('role_id', role_id);

    if ((count ?? 0) > 0) {
      return NextResponse.json(
        { error: 'Cannot delete role while members are assigned to it. Re-assign them first.' },
        { status: 400 }
      );
    }

    const { error } = await adminClient
      .from('workspace_roles')
      .delete()
      .eq('id', role_id)
      .eq('workspace_id', workspace_id)
      .eq('is_system', false);

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[workspace/roles DELETE]:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient as createServerClient } from '@/lib/supabase/server';
import { getWorkspaceUsageAndLimits } from '@/lib/limits';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const workspaceId = searchParams.get('workspace_id');

    if (!workspaceId) {
      return NextResponse.json({ error: 'workspace_id is required' }, { status: 400 });
    }

    const supabase = await createServerClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Verify membership
    const { data: member, error: memberError } = await supabase
      .from('workspace_members')
      .select('role')
      .eq('workspace_id', workspaceId)
      .eq('user_id', user.id)
      .maybeSingle();

    if (memberError || !member) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const usage = await getWorkspaceUsageAndLimits(workspaceId);
    return NextResponse.json(usage);
  } catch (err: any) {
    console.error('[workspace-usage] error:', err.message);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient as createServerClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';
import { defaultSystemRoleName, type WorkspaceDbRole } from '@/lib/auth/roles';

/** Helper: verify caller is workspace owner or admin */
async function verifyWorkspaceAdmin(workspaceId: string) {
  const supabase = await createServerClient();
  const { data: { user }, error } = await supabase.auth.getUser();
  if (error || !user) return { user: null, role: null, error: 'Unauthorized', status: 401 };

  const { data: member } = await supabase
    .from('workspace_members')
    .select('role')
    .eq('workspace_id', workspaceId)
    .eq('user_id', user.id)
    .maybeSingle();

  if (member?.role !== 'owner' && member?.role !== 'admin') {
    return { user: null, role: null, error: 'Forbidden: owner or admin role required', status: 403 };
  }
  return { user, supabase, role: member.role, error: null, status: 200 };
}

/**
 * POST /api/workspace/users
 * Owner creates a new team member (or adds an existing user) to a workspace.
 *
 * Body: {
 *   workspace_id, full_name, email, password?,
 *   role_id, role_name (display only),
 *   workspace_role: 'admin' | 'member' | 'viewer'  (enum fallback)
 * }
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { workspace_id, full_name, email, password, role_id, workspace_role } = body as {
      workspace_id?: string;
      full_name?: string;
      email?: string;
      password?: string;
      role_id?: string;
      workspace_role?: 'admin' | 'member' | 'viewer';
    };

    if (!workspace_id) {
      return NextResponse.json({ error: 'workspace_id is required' }, { status: 400 });
    }

    const auth = await verifyWorkspaceAdmin(workspace_id);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }
    const callerRole = auth.role;

    if (!email?.trim()) {
      return NextResponse.json({ error: 'email is required' }, { status: 400 });
    }

    const adminClient = createAdminClient();

    // --- Check max_members limit ---
    const { data: wsData } = await adminClient
      .from('workspaces')
      .select('plan_limits')
      .eq('id', workspace_id)
      .single();

    const maxMembers = wsData?.plan_limits?.max_members as number | null;
    if (maxMembers) {
      const { count } = await adminClient
        .from('workspace_members')
        .select('*', { count: 'exact', head: true })
        .eq('workspace_id', workspace_id);
        
      if (count !== null && count >= maxMembers) {
        return NextResponse.json(
          { error: `Member limit reached for this workspace. (Max: ${maxMembers})` },
          { status: 403 }
        );
      }
    }

    const normalizedEmail = email.trim().toLowerCase();
    let targetUserId: string;

    // --- Check if user already exists ---
    // listUsers defaults to 50 per page; past 50 users an existing
    // account wouldn't be found and we'd wrongly try createUser.
    // Paginate until the email is found or the pages run out.
    let existingUser: { id: string; email?: string } | undefined;
    for (let page = 1; page <= 20 && !existingUser; page++) {
      const { data: pageData, error: listErr } = await adminClient.auth.admin.listUsers({
        page,
        perPage: 1000,
      });
      if (listErr || !pageData?.users?.length) break;
      existingUser = pageData.users.find(
        (u) => u.email?.toLowerCase() === normalizedEmail
      );
      if (pageData.users.length < 1000) break;
    }

    if (existingUser) {
      // User exists — just add them to the workspace
      targetUserId = existingUser.id;

      // Check if already a member
      const { supabase } = auth as any;
      const { data: alreadyMember } = await supabase
        .from('workspace_members')
        .select('id')
        .eq('workspace_id', workspace_id)
        .eq('user_id', targetUserId)
        .maybeSingle();

      if (alreadyMember) {
        return NextResponse.json(
          { error: 'User is already a member of this workspace' },
          { status: 409 }
        );
      }
    } else {
      // New user — create auth account
      if (callerRole === 'admin') {
        return NextResponse.json(
          { error: 'Only the workspace owner can create new user accounts.' },
          { status: 403 }
        );
      }

      if (!password || password.length < 8) {
        return NextResponse.json(
          { error: 'Password (min 8 chars) is required for new users' },
          { status: 400 }
        );
      }

      const { data: newUser, error: createError } = await adminClient.auth.admin.createUser({
        email: normalizedEmail,
        password,
        email_confirm: true,
        user_metadata: { full_name: (full_name || '').trim() },
      });

      if (createError) {
        return NextResponse.json({ error: createError.message }, { status: 500 });
      }

      targetUserId = newUser.user.id;
    }

    // --- Insert workspace_members row ---
    // Only 'admin', 'member', and 'viewer' are assignable. The DB
    // enum also accepts 'owner' — without this whitelist an admin
    // could mint new owners (privilege escalation).
    if (workspace_role && !['admin', 'member', 'viewer'].includes(workspace_role)) {
      return NextResponse.json(
        { error: 'workspace_role must be "admin", "member", or "viewer"' },
        { status: 400 }
      );
    }
    const dbRole = (workspace_role || 'member') as WorkspaceDbRole;
    const memberInsert: Record<string, unknown> = {
      workspace_id,
      user_id: targetUserId,
      role: dbRole,
    };

    if (role_id) {
      memberInsert.role_id = role_id;
    } else {
      // A NULL role_id locks the member out of every catalogued table —
      // the CRUD policies are RESTRICTIVE and fail closed — so fall back
      // to the workspace's built-in role rather than leaving it unset.
      const { data: fallbackRole } = await adminClient
        .from('workspace_roles')
        .select('id')
        .eq('workspace_id', workspace_id)
        .eq('is_system', true)
        .eq('name', defaultSystemRoleName(dbRole))
        .maybeSingle();

      if (!fallbackRole) {
        // Seeded per workspace at creation (migrations 015/021). Absent
        // means the workspace was provisioned incompletely; say so rather
        // than create a member who silently cannot read anything.
        return NextResponse.json(
          {
            error: `This workspace has no built-in "${defaultSystemRoleName(dbRole)}" role, so no permissions could be assigned. Create a role under Settings → Roles and pass its role_id.`,
          },
          { status: 409 }
        );
      }
      memberInsert.role_id = fallbackRole.id;
    }

    const { error: insertError } = await adminClient
      .from('workspace_members')
      .insert(memberInsert);

    if (insertError) {
      console.error('[workspace/users POST] insert error:', insertError);
      return NextResponse.json({ error: insertError.message }, { status: 500 });
    }

    return NextResponse.json({
      success: true,
      user_id: targetUserId,
      is_new_user: !existingUser,
    });
  } catch (err: any) {
    console.error('[workspace/users POST] unexpected:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * PATCH /api/workspace/users
 * Owner updates a team member's role or workspace_role.
 *
 * Body: { workspace_id, member_id, role_id?, workspace_role? }
 */
export async function PATCH(request: NextRequest) {
  try {
    const body = await request.json();
    const { workspace_id, member_id, role_id, workspace_role } = body as {
      workspace_id?: string;
      member_id?: string;
      role_id?: string | null;
      workspace_role?: 'admin' | 'member' | 'viewer';
    };

    if (!workspace_id || !member_id) {
      return NextResponse.json(
        { error: 'workspace_id and member_id are required' },
        { status: 400 }
      );
    }

    const auth = await verifyWorkspaceAdmin(workspace_id);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const updates: Record<string, unknown> = {};
    if (role_id) updates.role_id = role_id;
    // Whitelist — the DB enum also accepts 'owner', so an unchecked
    // value would let an admin promote themselves to owner.
    if (workspace_role) {
      if (!['admin', 'member', 'viewer'].includes(workspace_role)) {
        return NextResponse.json(
          { error: 'workspace_role must be "admin", "member", or "viewer"' },
          { status: 400 }
        );
      }
      updates.role = workspace_role;
    }

    const adminClient = createAdminClient();

    // An explicit null means "reset to the workspace default", not "strip
    // all permissions": a NULL role_id fails closed against every
    // RESTRICTIVE CRUD policy and leaves the member unable to read
    // anything, which is never what clearing a role is meant to do.
    if (role_id === null) {
      const targetDbRole = (workspace_role
        ?? (await adminClient
          .from('workspace_members')
          .select('role')
          .eq('workspace_id', workspace_id)
          .eq('id', member_id)
          .maybeSingle()).data?.role
        ?? 'member') as WorkspaceDbRole;

      const { data: fallbackRole } = await adminClient
        .from('workspace_roles')
        .select('id')
        .eq('workspace_id', workspace_id)
        .eq('is_system', true)
        .eq('name', defaultSystemRoleName(targetDbRole))
        .maybeSingle();

      if (!fallbackRole) {
        return NextResponse.json(
          {
            error: `This workspace has no built-in "${defaultSystemRoleName(targetDbRole)}" role to fall back to. Assign a role_id explicitly.`,
          },
          { status: 409 }
        );
      }
      updates.role_id = fallbackRole.id;
    }

    if (Object.keys(updates).length === 0) {
      return NextResponse.json({ error: 'No updates provided' }, { status: 400 });
    }

    const { error } = await adminClient
      .from('workspace_members')
      .update(updates)
      .eq('id', member_id)
      .eq('workspace_id', workspace_id)
      .neq('role', 'owner'); // never demote owner

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[workspace/users PATCH] unexpected:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * DELETE /api/workspace/users
 * Owner removes a team member from a workspace.
 *
 * Body: { workspace_id, member_id }
 */
export async function DELETE(request: NextRequest) {
  try {
    const body = await request.json();
    const { workspace_id, member_id } = body as {
      workspace_id?: string;
      member_id?: string;
    };

    if (!workspace_id || !member_id) {
      return NextResponse.json(
        { error: 'workspace_id and member_id are required' },
        { status: 400 }
      );
    }

    const auth = await verifyWorkspaceAdmin(workspace_id);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const adminClient = createAdminClient();
    const { error } = await adminClient
      .from('workspace_members')
      .delete()
      .eq('id', member_id)
      .eq('workspace_id', workspace_id)
      .neq('role', 'owner'); // can't remove the owner

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[workspace/users DELETE] unexpected:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { toast } from 'sonner';
import { Loader2, CheckCircle2, AlertCircle, Upload, File, X } from 'lucide-react';
import type { CustomForm, CustomFormField } from '@/types';

interface SharedFormClientProps {
  form: CustomForm;
  fields: CustomFormField[];
}

export default function SharedFormClient({ form, fields }: SharedFormClientProps) {
  // Form values state mapping { [fieldId]: value }
  const [values, setValues] = useState<Record<string, any>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleInputChange = (fieldId: string, val: any) => {
    setValues((prev) => ({ ...prev, [fieldId]: val }));
    // Clear error on change
    if (errors[fieldId]) {
      setErrors((prev) => {
        const next = { ...prev };
        delete next[fieldId];
        return next;
      });
    }
  };

  const handleFileChange = (fieldId: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 10 * 1024 * 1024) {
      toast.error('File size exceeds the 10MB limit.');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      handleInputChange(fieldId, {
        name: file.name,
        type: file.type,
        size: file.size,
        base64: base64,
      });
    };
    reader.onerror = () => {
      toast.error('Failed to read file.');
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveFile = (fieldId: string) => {
    handleInputChange(fieldId, undefined);
  };

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    fields.forEach((field) => {
      const val = values[field.id];
      let isPresent = val !== undefined && val !== null;
      if (isPresent) {
        if (typeof val === 'object' && !Array.isArray(val)) {
          isPresent = !!val.base64;
        } else {
          isPresent = String(val).trim() !== '';
        }
      }

      // 1. Required Check
      if (field.is_required && !isPresent) {
        newErrors[field.id] = `${field.label} is required`;
        return;
      }

      if (isPresent && typeof val === 'string') {
        // 2. Email format validation
        if (field.field_type === 'email') {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(val.trim())) {
            newErrors[field.id] = 'Please enter a valid email address';
          }
        }

        // 3. Phone format validation
        if (field.field_type === 'phone') {
          const phoneRegex = /^[+]*[(]{0,1}[0-9]{1,4}[)]{0,1}[-\s\./0-9]*$/;
          if (!phoneRegex.test(val.trim()) || val.trim().replace(/\D/g, '').length < 6) {
            newErrors[field.id] = 'Please enter a valid phone number';
          }
        }
      }
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) {
      toast.error('Please fix validation errors before submitting');
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch(`/api/forms/${form.id}/submit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          submitted_values: values,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || 'Failed to submit form');
      }

      setSubmitted(true);
      toast.success('Form submitted successfully!');
    } catch (err: any) {
      toast.error(err.message || 'Error submitting response');
    } finally {
      setSubmitting(false);
    }
  };

  if (submitted) {
    return (
      <div className="min-h-screen bg-[#0b0f19] flex items-center justify-center p-4 relative overflow-hidden">
        {/* Glow meshes */}
        <div className="absolute top-1/4 left-1/4 size-80 rounded-full bg-primary/10 blur-3xl" />
        <div className="absolute bottom-1/4 right-1/4 size-80 rounded-full bg-indigo-500/10 blur-3xl" />

        <div className="relative max-w-md w-full rounded-2xl border border-border bg-muted/60 backdrop-blur-md p-8 text-center shadow-2xl space-y-5 animate-scaleUp">
          <div className="relative size-16 mx-auto flex items-center justify-center">
            {/* Pulsing ring background */}
            <div className="absolute inset-0 rounded-full bg-emerald-500/20 animate-ping" />
            <CheckCircle2 className="relative size-14 text-emerald-400" />
          </div>

          <div className="space-y-2">
            <h2 className="text-lg font-semibold text-white tracking-tight">Response Submitted</h2>
            <p className="text-sm text-muted-foreground">
              Thank you! Your information has been received and logged in our CRM. A representative will contact you shortly.
            </p>
          </div>

          <div className="pt-3">
            <Button
              onClick={() => {
                setValues({});
                setSubmitted(false);
                setErrors({});
              }}
              className="w-full bg-primary hover:bg-primary-hover text-white"
            >
              Submit Another Response
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0b0f19] flex items-center justify-center p-4 relative overflow-hidden py-12">
      {/* Background radial overlays */}
      <div className="absolute top-1/4 left-1/4 size-96 rounded-full bg-primary/10 blur-3xl" />
      <div className="absolute bottom-1/4 right-1/4 size-96 rounded-full bg-indigo-500/10 blur-3xl" />

      {/* Grid Pattern overlay */}
      <div className="absolute inset-0 bg-[linear-gradient(to_right,#0f172a_1px,transparent_1px),linear-gradient(to_bottom,#0f172a_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_50%,#000_70%,transparent_100%)] opacity-35" />

      <div className="relative max-w-xl w-full rounded-2xl border border-border/80 bg-muted/50 backdrop-blur-md p-7 sm:p-10 shadow-2xl space-y-6">
        {/* Form Title & description */}
        <div className="border-b border-border/80 pb-5 space-y-2">
          <h1 className="text-lg sm:text-lg font-semibold text-white tracking-tight">
            {form.title}
          </h1>
          {form.description && (
            <p className="text-sm text-muted-foreground whitespace-pre-wrap leading-relaxed">
              {form.description}
            </p>
          )}
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="space-y-5">
          {fields.map((field) => {
            const hasError = !!errors[field.id];

            return (
              <div key={field.id} className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <Label htmlFor={field.id} className="text-foreground text-sm font-medium">
                    {field.label}
                    {field.is_required && <span className="text-red-400 ml-1 font-bold">*</span>}
                  </Label>
                </div>

                {/* Text Field Rendering */}
                {(field.field_type === 'text' ||
                  field.field_type === 'email' ||
                  field.field_type === 'phone' ||
                  field.field_type === 'number') && (
                  <Input
                    id={field.id}
                    type={field.field_type === 'number' ? 'number' : 'text'}
                    value={values[field.id] || ''}
                    onChange={(e) => handleInputChange(field.id, e.target.value)}
                    placeholder={field.placeholder || ''}
                    className={`bg-muted/40 border text-foreground placeholder:text-muted-foreground focus:border-primary focus:ring-1 focus:ring-primary/20 h-10 transition-all ${
                      hasError ? 'border-red-500/70 focus:border-red-500' : 'border-border'
                    }`}
                  />
                )}

                {/* Textarea Field Rendering */}
                {field.field_type === 'textarea' && (
                  <Textarea plain
                    id={field.id}
                    value={values[field.id] || ''}
                    onChange={(e) => handleInputChange(field.id, e.target.value)}
                    placeholder={field.placeholder || ''}
                    className={`bg-muted/40 border text-foreground placeholder:text-muted-foreground focus:border-primary focus:ring-1 focus:ring-primary/20 min-h-[90px] transition-all ${
                      hasError ? 'border-red-500/70 focus:border-red-500' : 'border-border'
                    }`}
                  />
                )}

                {/* Select Dropdown Rendering */}
                {field.field_type === 'select' && (
                  <select
                    id={field.id}
                    value={values[field.id] || ''}
                    onChange={(e) => handleInputChange(field.id, e.target.value)}
                    className={`w-full bg-muted/50 border text-foreground focus:border-primary focus:ring-1 focus:ring-primary/20 rounded-md h-10 px-3 transition-all outline-none ${
                      hasError ? 'border-red-500/70' : 'border-border'
                    }`}
                  >
                    <option value="" className="bg-muted text-muted-foreground">
                      Select option...
                    </option>
                    {field.options?.map((opt) => (
                      <option key={opt} value={opt} className="bg-muted text-foreground">
                        {opt}
                      </option>
                    ))}
                  </select>
                )}

                {/* Checkbox Rendering */}
                {field.field_type === 'checkbox' && (
                  <div className="flex items-center space-x-2.5 py-1.5">
                    <input
                      id={field.id}
                      type="checkbox"
                      checked={!!values[field.id]}
                      onChange={(e) => handleInputChange(field.id, e.target.checked)}
                      className="size-4 rounded-none border-border bg-muted/40 text-primary focus:ring-primary/20"
                    />
                    <label htmlFor={field.id} className="text-sm text-muted-foreground select-none">
                      {field.placeholder || 'Please check this box'}
                    </label>
                  </div>
                )}

                {/* File Field Rendering */}
                {field.field_type === 'file' && (
                  <div className="space-y-2">
                    {!values[field.id] ? (
                      <div className="flex items-center justify-center w-full animate-fadeIn">
                        <label
                          htmlFor={field.id}
                          className={`flex flex-col items-center justify-center w-full h-32 border border-dashed rounded-lg cursor-pointer bg-muted/20 hover:bg-muted/40 border-border hover:border-border transition-all ${
                            hasError ? 'border-red-500/70' : 'border-border'
                          }`}
                        >
                          <div className="flex flex-col items-center justify-center pt-5 pb-6">
                            <Upload className="w-8 h-8 mb-2.5 text-muted-foreground" />
                            <p className="mb-1 text-sm text-muted-foreground">
                              <span className="font-semibold text-primary">Click to upload</span> or drag & drop
                            </p>
                            <p className="text-[10px] text-muted-foreground">PDF, Word, Images, etc. (Max 10MB)</p>
                          </div>
                          <input
                            id={field.id}
                            type="file"
                            className="hidden"
                            onChange={(e) => handleFileChange(field.id, e)}
                          />
                        </label>
                      </div>
                    ) : (
                      <div className="flex items-center justify-between p-3 rounded-lg bg-muted/40 border border-border animate-scaleUp">
                        <div className="flex items-center gap-2.5 min-w-0">
                          <File className="w-5 h-5 text-primary shrink-0 animate-pulse" />
                          <div className="min-w-0">
                            <p className="text-sm text-foreground truncate font-medium">
                              {values[field.id].name}
                            </p>
                            <p className="text-[10px] text-muted-foreground">
                              {(values[field.id].size / (1024 * 1024)).toFixed(2)} MB
                            </p>
                          </div>
                        </div>
                        <button
                          type="button"
                          onClick={() => handleRemoveFile(field.id)}
                          className="p-1 rounded-none hover:bg-muted text-muted-foreground hover:text-white transition-colors"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                    )}
                  </div>
                )}

                {/* Error snippet */}
                {hasError && (
                  <div className="flex items-center gap-1.5 text-red-400 text-xs mt-1 animate-slideDown">
                    <AlertCircle className="size-3.5" />
                    <span>{errors[field.id]}</span>
                  </div>
                )}
              </div>
            );
          })}

          {/* Form Actions */}
          <div className="pt-4">
            <Button
              type="submit"
              disabled={submitting}
              className="w-full bg-primary hover:bg-primary-hover text-white font-semibold py-2.5 text-sm transition-all h-10 flex items-center justify-center gap-2"
            >
              {submitting ? (
                <>
                  <Loader2 className="size-4 animate-spin" />
                  Submitting response...
                </>
              ) : (
                'Submit Form'
              )}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, startTransition } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import Script from "next/script";
import { createClient } from "@/lib/supabase/client";
import { AuthProvider, useAuth } from "@/hooks/use-auth";
import { WorkspaceProvider, useWorkspace } from "@/hooks/use-workspace";
import { PLANS } from "@/config/plans";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Building2,
  User,
  CreditCard,
  Sparkles,
  Upload,
  Check,
  Loader2,
  LogOut,
  ChevronRight
} from "lucide-react";
import { toast } from "sonner";
import { INDUSTRY_TEMPLATES } from "@/app/(dashboard)/settings/retail/page";

function OnboardingInner() {
  const { user, profile, signOut } = useAuth();
  const { workspaces, createWorkspace, refreshWorkspaces } = useWorkspace();
  const router = useRouter();
  const supabase = createClient();

  // Step state
  const [step, setStep] = useState(1);

  // Form states
  const [fullName, setFullName] = useState("");
  const [selectedPlan, setSelectedPlan] = useState<string>("free");
  const [billingCycle, setBillingCycle] = useState<"monthly" | "annual">("monthly");
  const [orgName, setOrgName] = useState("");
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [selectedIndustryTemplate, setSelectedIndustryTemplate] = useState("GENERAL_RETAIL");

  // Action states
  const [loading, setLoading] = useState(false);

  // Load pre-filled name from profile
  useEffect(() => {
    if (profile?.full_name && !fullName) {
      setFullName(profile.full_name);
    }
  }, [profile, fullName]);
  const [, setIsUploading] = useState(false);

  // Load pre-selected plan preference from signup step
  useEffect(() => {
    if (typeof window !== "undefined") {
      const savedPlan = localStorage.getItem("crm_onboarding_plan");
      const savedCycle = localStorage.getItem("crm_onboarding_cycle");
      if (savedPlan && PLANS.some((p) => p.id === savedPlan)) {
        setSelectedPlan(savedPlan);
      }
      if (savedCycle === "monthly" || savedCycle === "annual") {
        setBillingCycle(savedCycle);
      }
    }
  }, []);

  // Sync profile full_name if user metadata has it
  useEffect(() => {
    if (user?.user_metadata?.full_name) {
      setFullName(user.user_metadata.full_name);
    }
  }, [user]);

  // If user already has workspaces, they shouldn't be here, redirect them to dashboard
  // If they have a pending invite token in progress, redirect them to the invitation join page.
  // Membership wins over a (possibly stale) invite token so accepted
  // members always land in their workspace's dashboard.
  useEffect(() => {
    if (workspaces.length > 0) {
      router.push("/dashboard");
      return;
    }
    // The token lives in auth user_metadata (set at signup — survives
    // the email-confirmation tab / other devices) with sessionStorage
    // as a same-tab fallback for existing accounts.
    const pendingInvite =
      (typeof user?.user_metadata?.invite_token === "string" &&
      user.user_metadata.invite_token
        ? user.user_metadata.invite_token
        : null) ??
      (typeof window !== "undefined"
        ? sessionStorage.getItem("pending_invite_token")
        : null);
    if (pendingInvite) {
      router.push(`/join/${encodeURIComponent(pendingInvite)}`);
    }
  }, [workspaces, user, router]);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        toast.error("Logo file size must be less than 2MB.");
        return;
      }
      setLogoFile(file);
      const url = URL.createObjectURL(file);
      setLogoPreview(url);
    }
  };

  const handleStep1Submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!fullName.trim()) {
      toast.error("Please enter your full name.");
      return;
    }
    setLoading(true);
    try {
      // Save name to profiles table
      const { error } = await supabase.from("profiles").upsert(
        {
          user_id: user?.id,
          full_name: fullName.trim(),
          email: user?.email,
        },
        { onConflict: "user_id" }
      );
      if (error) throw error;
      setStep(2);
    } catch (err: any) {
      toast.error(err.message || "Failed to update profile name.");
    } finally {
      setLoading(false);
    }
  };

  const handleStep2Submit = () => {
    setStep(3);
  };

  const handleOnboardingComplete = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!orgName.trim()) {
      toast.error("Please enter your company/organization name.");
      return;
    }

    setLoading(true);
    let workspaceId = "";

    try {
      // 1. Create workspace (defaults to 'free' Free Trial)
      const workspace = await createWorkspace(orgName.trim());
      if (!workspace || !workspace.id) {
        throw new Error("Failed to create workspace.");
      }
      workspaceId = workspace.id;

      // Save industry template settings to localStorage
      if (typeof window !== "undefined") {
        localStorage.setItem(`retail_template_${workspaceId}`, selectedIndustryTemplate);
        localStorage.setItem("retail_template_active", selectedIndustryTemplate);
      }

      // 2. Upload logo to Supabase storage public bucket 'avatars'
      let uploadedLogoUrl = null;
      if (logoFile) {
        setIsUploading(true);
        const ext = logoFile.name.split(".").pop()?.toLowerCase() || "png";
        const path = `workspaces/${workspaceId}/logo-${Date.now()}.${ext}`;

        const { error: uploadError } = await supabase.storage
          .from("avatars")
          .upload(path, logoFile, {
            cacheControl: "3600",
            upsert: true,
            contentType: logoFile.type,
          });

        if (uploadError) {
          console.warn("Logo upload failed, skipping: ", uploadError.message);
        } else {
          const {
            data: { publicUrl },
          } = supabase.storage.from("avatars").getPublicUrl(path);
          uploadedLogoUrl = publicUrl;
        }
      }

      // 3. Update workspace details (name + logo_url) safely
      try {
        await supabase
          .from("workspaces")
          .update({
            name: orgName.trim(),
            logo_url: uploadedLogoUrl,
          })
          .eq("id", workspaceId);
      } catch (dbErr) {
        // Fallback in case logo_url migration hasn't loaded yet
        console.warn("Failed to write logo_url to workspace, skipping column: ", dbErr);
      }

      // Clean up localStorage keys
      localStorage.removeItem("crm_onboarding_plan");
      localStorage.removeItem("crm_onboarding_cycle");

      // 4. Handle subscription upgrade if paid tier was chosen
      const plan = PLANS.find((p) => p.id === selectedPlan);
      if (plan && plan.id !== "free" && plan.id !== "custom") {
        const isAnnual = billingCycle === "annual";
        const price = isAnnual ? plan.priceYearly : plan.priceMonthly;
        const amountPaise = price * 100;

        toast.loading("Preparing payment window...");

        const orderRes = await fetch("/api/create-order", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            amount: amountPaise,
            currency: "INR",
            receipt: `rcpt_onb_${workspaceId.substring(0, 10)}`,
          }),
        });

        const orderResult = await orderRes.json();
        toast.dismiss();

        if (!orderRes.ok || !orderResult.order_id) {
          throw new Error(orderResult.error || "Failed to initialize payment gateway order.");
        }

        const options = {
          key: process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || "rzp_test_TEus8m7ilDoAio",
          amount: orderResult.amount,
          currency: orderResult.currency,
          name: "Daily CRM",
          description: `${plan.name} Tier Upgrade (${isAnnual ? "Annual" : "Monthly"})`,
          order_id: orderResult.order_id,
          handler: async function (response: any) {
            try {
              toast.loading("Verifying payment transaction...");
              const verifyRes = await fetch("/api/verify-payment", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  razorpay_payment_id: response.razorpay_payment_id,
                  razorpay_order_id: response.razorpay_order_id,
                  razorpay_signature: response.razorpay_signature,
                  workspace_id: workspaceId,
                  plan_id: plan.id,
                }),
              });

              const verifyResult = await verifyRes.json();
              toast.dismiss();

              if (verifyRes.ok && verifyResult.success) {
                toast.success(`Success! Workspace upgraded to ${plan.name}.`);
                startTransition(() => {
                  refreshWorkspaces();
                  router.push("/dashboard");
                });
              } else {
                toast.error(verifyResult.error || "Failed to verify transaction signature.");
                // Let user into the free trial first
                router.push("/dashboard");
              }
            } catch (err: any) {
              toast.dismiss();
              toast.error(err.message || "Payment verification failed.");
              router.push("/dashboard");
            }
          },
          prefill: {
            name: orgName,
          },
          theme: {
            color: "#0284C7",
          },
          modal: {
            ondismiss: function () {
              toast.info("Payment checkout cancelled. Your workspace has been initialized on Free Trial tier. You can upgrade from Settings anytime.");
              router.push("/dashboard");
            },
          },
        };

        const rzp = new (window as any).Razorpay(options);
        rzp.open();
      } else {
        toast.success("Welcome aboard! Your workspace has been successfully created.");
        startTransition(() => {
          refreshWorkspaces();
          router.push("/dashboard");
        });
      }
    } catch (err: any) {
      toast.dismiss();
      toast.error(err.message || "Failed to complete onboarding.");
    } finally {
      setLoading(false);
      setIsUploading(false);
    }
  };

  const activePlanConfig = PLANS.find((p) => p.id === selectedPlan) || PLANS[0];

  return (
    <div className="min-h-screen bg-muted flex flex-col items-center justify-center p-6 relative overflow-hidden text-foreground">
      <Script src="https://checkout.razorpay.com/v1/checkout.js" strategy="lazyOnload" />

      {/* Ambient backgrounds */}
      <div className="pointer-events-none absolute top-0 left-1/2 -translate-x-1/2 h-[700px] w-[700px] rounded-full bg-primary/5 blur-[120px]" />

      <div className="w-full max-w-4xl flex flex-col items-center relative z-10">
        {/* Header Logo */}
        <div className="flex items-center gap-2 mb-8">
          <Image src="/logolight.png" alt="Daily CRM" width={160} height={40} className="h-9 w-auto object-contain" />
        </div>

        {/* Wizard Progress Steps Bar */}
        <div className="w-full max-w-md flex items-center justify-between mb-8 text-xs font-semibold text-muted-foreground">
          <div className={`flex items-center gap-1.5 ${step >= 1 ? "text-primary" : ""}`}>
            <span className={`h-5 w-5 rounded-full flex items-center justify-center border text-[10px] ${step >= 1 ? "border-primary bg-primary/15" : "border-border"}`}>1</span>
            Profile
          </div>
          <div className="h-px bg-muted flex-1 mx-3" />
          <div className={`flex items-center gap-1.5 ${step >= 2 ? "text-primary" : ""}`}>
            <span className={`h-5 w-5 rounded-full flex items-center justify-center border text-[10px] ${step >= 2 ? "border-primary bg-primary/15" : "border-border"}`}>2</span>
            Plan selection
          </div>
          <div className="h-px bg-muted flex-1 mx-3" />
          <div className={`flex items-center gap-1.5 ${step >= 3 ? "text-primary" : ""}`}>
            <span className={`h-5 w-5 rounded-full flex items-center justify-center border text-[10px] ${step >= 3 ? "border-primary bg-primary/15" : "border-border"}`}>3</span>
            Workspace setup
          </div>
        </div>

        {/* Wizard Step Forms */}
        <div className="w-full bg-muted/60 border border-border/80 backdrop-blur-xl rounded-3xl p-8 md:p-10 shadow-2xl">
          {step === 1 && (
            <form onSubmit={handleStep1Submit} className="space-y-6 max-w-md mx-auto">
              <div className="text-center">
                <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10 border border-primary/20 mb-4 text-primary">
                  <User className="h-6 w-6" />
                </div>
                <h1 className="text-xl font-bold text-white tracking-tight">Set up your profile name</h1>
                <p className="text-muted-foreground text-xs mt-1">Let your team members know who you are.</p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="fullName" className="text-foreground text-xs font-semibold">Your full name</Label>
                <Input
                  id="fullName"
                  type="text"
                  placeholder="e.g. Sarah Chen"
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  className="bg-muted border-border text-foreground h-10 rounded-xl focus:border-primary"
                  required
                  autoFocus
                />
              </div>

              <Button
                type="submit"
                disabled={loading || !fullName.trim()}
                className="w-full bg-primary hover:bg-primary-hover text-primary-foreground h-10 rounded-xl font-bold shadow-lg shadow-primary/10 mt-2"
              >
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Continue"}
                <ChevronRight className="h-4 w-4 ml-1" />
              </Button>
            </form>
          )}

          {step === 2 && (
            <div className="space-y-6">
              <div className="text-center">
                <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10 border border-primary/20 mb-4 text-primary">
                  <CreditCard className="h-6 w-6" />
                </div>
                <h1 className="text-xl font-bold text-white tracking-tight">Select your plan tier</h1>
                <p className="text-muted-foreground text-xs mt-1">All plans exclude GST. Annual plans enjoy 2 months free.</p>

                {/* Billing cycle toggle */}
                <div className="flex items-center justify-center gap-3 mt-4">
                  <button
                    type="button"
                    onClick={() => setBillingCycle("monthly")}
                    className={`px-3 py-1.5 text-xs font-semibold rounded-lg transition-colors ${
                      billingCycle === "monthly"
                        ? "bg-primary text-primary-foreground"
                        : "text-muted-foreground hover:text-foreground bg-muted border border-border"
                    }`}
                  >
                    Monthly
                  </button>
                  <button
                    type="button"
                    onClick={() => setBillingCycle("annual")}
                    className={`px-3 py-1.5 text-xs font-semibold rounded-lg transition-colors relative ${
                      billingCycle === "annual"
                        ? "bg-primary text-primary-foreground"
                        : "text-muted-foreground hover:text-foreground bg-muted border border-border"
                    }`}
                  >
                    Annual
                    <span className="absolute -top-3 -right-6 px-1.5 py-0.5 bg-emerald-500 text-white text-[8px] font-bold rounded-full uppercase tracking-wider scale-90">
                      2 Months Free
                    </span>
                  </button>
                </div>
              </div>

              {/* Plans pricing grid */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {PLANS.map((plan) => {
                  const isSelected = selectedPlan === plan.id;
                  const isFree = plan.priceMonthly === 0;
                  const isCustom = plan.priceMonthly === -1;
                  const displayPrice = isFree
                    ? "₹0"
                    : isCustom
                    ? "Custom"
                    : billingCycle === "annual"
                    ? `₹${plan.priceYearly.toLocaleString()}`
                    : `₹${plan.priceMonthly.toLocaleString()}`;
                  const periodLabel = isFree ? "/14 days" : isCustom ? "" : billingCycle === "annual" ? "/yr" : "/mo";

                  return (
                    <div
                      key={plan.id}
                      onClick={() => setSelectedPlan(plan.id)}
                      className={`relative flex flex-col rounded-2xl p-4 border transition-all cursor-pointer select-none ${
                        isSelected
                          ? "border-primary bg-primary/5 shadow-xl shadow-primary/5"
                          : "border-border bg-muted/40 hover:border-border"
                      }`}
                    >
                      {plan.isRecommended && (
                        <div className="absolute -top-2.5 left-1/2 -translate-x-1/2 px-2 py-0.5 bg-primary text-primary-foreground text-[9px] font-bold rounded-full">
                          POPULAR
                        </div>
                      )}

                      <div className="mb-4">
                        <span className="text-xs font-extrabold text-white block">{plan.name}</span>
                        <div className="flex items-baseline gap-0.5 mt-1">
                          <span className="text-lg font-black text-white">{displayPrice}</span>
                          <span className="text-muted-foreground text-[10px]">{periodLabel}</span>
                        </div>
                        {!isFree && !isCustom && (
                          <span className="text-[9px] text-muted-foreground block leading-tight">
                            {billingCycle === "annual"
                              ? `Equivalent to ₹${Math.round(plan.priceYearly / 12).toLocaleString()}/mo`
                              : `Equivalent to ₹${(plan.priceMonthly * 12).toLocaleString()}/yr`}
                          </span>
                        )}
                      </div>

                      <ul className="space-y-1.5 mb-4 flex-1">
                        {plan.features.slice(0, 3).map((f) => (
                          <li key={f} className="flex items-start gap-1 text-[10px] text-muted-foreground">
                            <Check className="h-3 w-3 text-emerald-500 shrink-0 mt-0.5" />
                            <span>{f}</span>
                          </li>
                        ))}
                      </ul>

                      <div className="flex justify-center mt-2">
                        <div className={`h-4 w-4 rounded-full border flex items-center justify-center ${isSelected ? "border-primary bg-primary" : "border-border"}`}>
                          {isSelected && <Check className="h-2.5 w-2.5 text-white" />}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="flex gap-4 max-w-xs mx-auto mt-6">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setStep(1)}
                  className="w-1/2 border border-border text-muted-foreground hover:text-foreground"
                >
                  Back
                </Button>
                <Button
                  type="button"
