  onSaved: () => void;
}

export function AssignAssetForm({ open, onOpenChange, onSaved }: AssignAssetFormProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [loadingDeps, setLoadingDeps] = useState(true);
  const [employees, setEmployees] = useState<any[]>([]);

  // Form State
  const [saving, setSaving] = useState(false);
  const [memberId, setMemberId] = useState('');
  const [assetName, setAssetName] = useState('');
  const [serialNumber, setSerialNumber] = useState('');

  useEffect(() => {
    if (open && activeWorkspace?.id) {
      loadEmployees();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, activeWorkspace?.id]);

  async function loadEmployees() {
    setLoadingDeps(true);
    try {
      const { data: empData } = await supabase
        .from('employee_profiles')
        // See employees/page.tsx: the embed needs the FK hint because
        // employee_profiles points at workspace_members twice.
        .select('workspace_member_id, workspace_members!workspace_member_id(id, user_id)')
        .eq('workspace_id', activeWorkspace!.id)
        .eq('status', 'ACTIVE');

      const empList = empData || [];
      if (empList.length > 0) {
        const userIds = empList.map((e: any) => e.workspace_members?.user_id).filter(Boolean);
        const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name, email').in('user_id', userIds);
        const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
        const enriched = empList.map((e: any) => ({
          ...e,
          workspace_members: e.workspace_members
            ? { ...e.workspace_members, profiles: profileMap[e.workspace_members.user_id] || null }
            : null
        }));
        setEmployees(enriched);
      } else {
        setEmployees([]);
      }
    } catch {
      toast.error('Failed to load employees');
    } finally {
      setLoadingDeps(false);
    }
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!activeWorkspace?.id || !memberId || !assetName.trim()) return;

    setSaving(true);
    
    try {
      const { error: dbError } = await supabase
        .from('employee_assets')
        .insert({
          workspace_id: activeWorkspace.id,
          workspace_member_id: memberId,
          asset_name: assetName.trim(),
          serial_number: serialNumber.trim() || null,
        });

      if (dbError) throw dbError;
      
      toast.success('Asset successfully assigned!');
      
      // Reset form
      setMemberId('');
      setAssetName('');
      setSerialNumber('');
      
      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to assign asset');
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-popover-foreground">
            Assign Company Asset
          </DialogTitle>
        </DialogHeader>
        
        {loadingDeps ? (
          <div className="py-12 flex justify-center">
            <Loader2 className="size-6 animate-spin text-primary" />
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 py-4">
            
            <div className="space-y-2">
              <Label>Select Employee <span className="text-red-500">*</span></Label>
              {employees.length === 0 ? (
                <div className="text-sm text-amber-500 bg-amber-500/10 p-3 rounded-md border border-amber-500/20">
                  No active employees found. Onboard someone first.
                </div>
              ) : (
                <Select value={memberId} onValueChange={(v) => setMemberId(v || '')} required>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue placeholder="Select an employee..." />
                  </SelectTrigger>
                  <SelectContent>
                    {employees.map(emp => {
                      const profile = Array.isArray(emp.workspace_members?.profiles) 
                        ? emp.workspace_members?.profiles[0] 
                        : emp.workspace_members?.profiles;
                      
                      return (
                        <SelectItem key={emp.workspace_member_id} value={emp.workspace_member_id}>
                          {profile?.full_name?.trim() || profile?.email || emp.workspace_members?.full_name?.trim() || 'Workspace Member'}
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              )}
            </div>

            <div className="space-y-2">
              <Label>Asset Name / Type <span className="text-red-500">*</span></Label>
              <Input
                value={assetName}
                onChange={(e) => setAssetName(e.target.value)}
                placeholder="e.g. MacBook Pro M3 (16-inch)"
                className="bg-card border-border"
                required
              />
            </div>
            
            <div className="space-y-2">
              <Label>Serial / Tracking Number</Label>
              <Input
                value={serialNumber}
                onChange={(e) => setSerialNumber(e.target.value)}
                placeholder="e.g. C02X543210ABC"
                className="bg-card border-border"
              />
              <p className="text-xs text-muted-foreground mt-1">
                Helpful for tracking devices if they are lost or need maintenance.
              </p>
            </div>

            <DialogFooter className="pt-4 border-t border-border mt-6">
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
                className="border-border text-muted-foreground hover:bg-muted"
                disabled={saving}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                className="bg-primary hover:bg-primary/90 text-primary-foreground"
                disabled={saving || !memberId || !assetName.trim()}
              >
                {saving && <Loader2 className="size-4 animate-spin mr-2" />}
                Assign Asset
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import type * as LeafletNS from "leaflet";
import "leaflet/dist/leaflet.css";
import { toast } from "sonner";
import { Loader2, Crosshair, Search, Minus, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  acquirePreciseLocation,
  GeolocationFailure,
  GEOLOCATION_FAILURE_MESSAGES,
  formatDistance,
} from "@/lib/attendance/geolocation";
import { IconAction } from "@/components/ui/icon-action";

export interface GeofenceValue {
  latitude: number | null;
  longitude: number | null;
  radiusM: number;
}

interface GeofenceMapPickerProps {
  value: GeofenceValue;
  onChange: (next: GeofenceValue) => void;
  disabled?: boolean;
  /** Optional label rendered in the marker popup. */
  label?: string;
  heightClass?: string;
}

/** Radius presets covering the realistic range from a desk to a campus. */
const RADIUS_PRESETS = [25, 50, 100, 250, 500, 1000];

const MIN_RADIUS = 10;
const MAX_RADIUS = 5000;

/** Falls back to the centre of India when nothing is set yet. */
const FALLBACK_CENTRE: [number, number] = [20.5937, 78.9629];

/**
 * Interactive geofence editor: drag the pin or click the map to move the
 * centre; size the radius with the slider, the +/- steppers or a preset.
 * (There is no draggable edge handle — an earlier version of this comment
 * claimed one existed.)
 *
 * Leaflet is imported as a real dependency rather than injected from a
 * CDN at runtime. The previous CDN <script> tag had no integrity hash,
 * so a compromise of that host — or any MITM — meant arbitrary JS in an
 * authenticated session. It is loaded dynamically (not at module scope)
 * because Leaflet touches `window` on import and would break SSR.
 */
export function GeofenceMapPicker({
  value,
  onChange,
  disabled = false,
  label,
  heightClass = "h-[320px]",
}: GeofenceMapPickerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<LeafletNS.Map | null>(null);
  const markerRef = useRef<LeafletNS.Marker | null>(null);
  const circleRef = useRef<LeafletNS.Circle | null>(null);
  const LRef = useRef<typeof LeafletNS | null>(null);

  const [ready, setReady] = useState(false);
  const [locating, setLocating] = useState(false);
  const [searching, setSearching] = useState(false);
  const [query, setQuery] = useState("");

  // Held in a ref so the map's event handlers always see current values
  // without needing to be torn down and rebound on every change.
  const valueRef = useRef(value);
  valueRef.current = value;
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  const disabledRef = useRef(disabled);
  disabledRef.current = disabled;

  const setCentre = useCallback((lat: number, lng: number) => {
    onChangeRef.current({
      ...valueRef.current,
      latitude: Number(lat.toFixed(6)),
      longitude: Number(lng.toFixed(6)),
    });
  }, []);

  const setRadius = useCallback((radiusM: number) => {
    const clamped = Math.min(MAX_RADIUS, Math.max(MIN_RADIUS, Math.round(radiusM)));
    onChangeRef.current({ ...valueRef.current, radiusM: clamped });
  }, []);

  // Build the map once.
  useEffect(() => {
    let cancelled = false;

    (async () => {
      const L = (await import("leaflet")).default ?? (await import("leaflet"));
      if (cancelled || !containerRef.current || mapRef.current) return;
      LRef.current = L as typeof LeafletNS;

      const start: [number, number] =
        value.latitude != null && value.longitude != null
          ? [value.latitude, value.longitude]
          : FALLBACK_CENTRE;

      const map = L.map(containerRef.current, {
        center: start,
        zoom: value.latitude != null ? 16 : 5,
        // The page scrolls; grabbing zoom on every wheel event over the
        // map makes the form hard to scroll past.
        scrollWheelZoom: false,
      });
      mapRef.current = map;

      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
        attribution:
          '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
        maxZoom: 19,
      }).addTo(map);

      map.on("click", (e: LeafletNS.LeafletMouseEvent) => {
        if (disabledRef.current) return;
        setCentre(e.latlng.lat, e.latlng.lng);
      });

      setReady(true);
      // The container is often laid out after the map is created (inside a
      // card that is still sizing), leaving grey tiles until a resize.
      setTimeout(() => map.invalidateSize(), 200);
    })();

    return () => {
      cancelled = true;
      mapRef.current?.remove();
      mapRef.current = null;
      markerRef.current = null;
      circleRef.current = null;
    };
    // Intentionally builds once; value changes are applied by the effect below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Reflect the current value onto the map.
  useEffect(() => {
    const L = LRef.current;
    const map = mapRef.current;
    if (!L || !map || !ready) return;

    if (value.latitude == null || value.longitude == null) {
      markerRef.current?.remove();
      circleRef.current?.remove();
      markerRef.current = null;
      circleRef.current = null;
      return;
    }

    const pos: [number, number] = [value.latitude, value.longitude];

    if (!markerRef.current) {
      const icon = L.divIcon({
        className: "geofence-centre-marker",
        html:
          '<div style="width:20px;height:20px;border-radius:50%;background:#0284c7;' +
          'border:3px solid #fff;box-shadow:0 2px 8px rgba(2,132,199,.5)"></div>',
        iconSize: [20, 20],
        iconAnchor: [10, 10],
      });
      const marker = L.marker(pos, { icon, draggable: !disabled }).addTo(map);
      marker.on("dragend", () => {
        const p = marker.getLatLng();
        setCentre(p.lat, p.lng);
      });
      markerRef.current = marker;
      map.setView(pos, Math.max(map.getZoom(), 16));
    } else {
      markerRef.current.setLatLng(pos);
      // draggable is a runtime handler, not a re-render prop.
      if (disabled) markerRef.current.dragging?.disable();
      else markerRef.current.dragging?.enable();
    }

    if (!circleRef.current) {
      circleRef.current = L.circle(pos, {
        radius: value.radiusM,
        color: "#0284c7",
        fillColor: "#0284c7",
        fillOpacity: 0.15,
        weight: 2,
      }).addTo(map);
    } else {
      circleRef.current.setLatLng(pos);
      circleRef.current.setRadius(value.radiusM);
    }

    if (label) {
      markerRef.current.bindPopup(
        // textContent equivalent: build a node so a workspace-supplied
        // label can never inject markup into the popup's innerHTML.
        (() => {
          const el = document.createElement("div");
          el.style.cssText = "font-family:sans-serif;font-size:12px";
          el.textContent = label;
          return el;
        })()
      );
    }
  }, [value.latitude, value.longitude, value.radiusM, ready, disabled, label, setCentre]);

  const handleUseMyLocation = async () => {
    setLocating(true);
    try {
      const fix = await acquirePreciseLocation({ desiredAccuracyM: 30, timeoutMs: 25_000 });
      setCentre(fix.latitude, fix.longitude);
      mapRef.current?.setView([fix.latitude, fix.longitude], 17);
      toast.success(
        `Centre set to your position (±${Math.round(fix.accuracy)}m).` +
          (fix.coarse ? " That is a coarse fix — check the pin before saving." : "")
      );
    } catch (err) {
      toast.error(
        err instanceof GeolocationFailure
          ? err.message
          : GEOLOCATION_FAILURE_MESSAGES.position_unavailable
      );
    } finally {
      setLocating(false);
    }
  };

  const handleSearch = async () => {
    const q = query.trim();
    if (!q) return;
    setSearching(true);
    try {
      // Nominatim is OpenStreetMap's own geocoder and needs no API key.
      const res = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(q)}`,
        { headers: { Accept: "application/json" } }
      );
      if (!res.ok) throw new Error("Search failed");
      const results = (await res.json()) as Array<{ lat: string; lon: string; display_name: string }>;
      if (results.length === 0) {
        toast.error(`No place found for "${q}".`);
        return;
      }
      const lat = parseFloat(results[0].lat);
      const lon = parseFloat(results[0].lon);
      setCentre(lat, lon);
      mapRef.current?.setView([lat, lon], 16);
      toast.success(results[0].display_name);
    } catch {
      toast.error("Could not search for that place. Set the pin manually instead.");
    } finally {
      setSearching(false);
    }
  };

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative min-w-[180px] flex-1">
          <Search className="absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                handleSearch();
              }
            }}
            placeholder="Search an address or place…"
            disabled={disabled || searching}
            className="h-9 pl-8 text-xs"
          />
        </div>
        <IconAction label="Find" icon={searching ? <Loader2 className="size-3.5 animate-spin" /> : <Search className="size-3.5" />} type="button"
          variant="outline"
          onClick={handleSearch}
          disabled={disabled || searching || !query.trim()}
          className="h-9 gap-1.5 text-xs" />
        <IconAction label="Use my location" icon={locating ? <Loader2 className="size-3.5 animate-spin" /> : <Crosshair className="size-3.5" />} type="button"
          variant="outline"
          onClick={handleUseMyLocation}
          disabled={disabled || locating}
          className="h-9 gap-1.5 text-xs" />
      </div>

      <div className={`relative w-full overflow-hidden rounded-xl border border-border ${heightClass}`}>
        <div ref={containerRef} className="h-full w-full" />
        {value.latitude == null && ready && (
          <div className="pointer-events-none absolute inset-x-0 bottom-0 bg-background/90 px-3 py-2 text-center text-xs text-muted-foreground">
            Click anywhere on the map to place the centre.
          </div>
        )}
      </div>

      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label className="text-xs font-semibold">
            Radius — {formatDistance(value.radiusM)}
          </Label>
          <div className="flex items-center gap-1">
            <IconAction
              label="Remove"
              icon={<Minus className="size-3" />}
              type="button"
              variant="outline"
              className="size-7 p-0"
              disabled={disabled || value.radiusM <= MIN_RADIUS}
              onClick={() => setRadius(value.radiusM - (value.radiusM > 100 ? 50 : 10))}
            />
            <IconAction
              label="Add"
              icon={<Plus className="size-3" />}
              type="button"
              variant="outline"
              className="size-7 p-0"
              disabled={disabled || value.radiusM >= MAX_RADIUS}
              onClick={() => setRadius(value.radiusM + (value.radiusM >= 100 ? 50 : 10))}
            />
          </div>
        </div>

        <input
          type="range"
          min={MIN_RADIUS}
          max={MAX_RADIUS}
          step={10}
          value={value.radiusM}
          disabled={disabled}
          onChange={(e) => setRadius(Number(e.target.value))}
          className="w-full accent-primary"
        />

        <div className="flex flex-wrap gap-1.5">
          {RADIUS_PRESETS.map((r) => (
            <button
              key={r}
              type="button"
              disabled={disabled}
              onClick={() => setRadius(r)}
              className={`rounded-md border px-2 py-0.5 text-[11px] font-medium transition-colors disabled:opacity-50 ${
                value.radiusM === r
                  ? "border-primary bg-primary/10 text-primary"
                  : "border-border text-muted-foreground hover:text-foreground"
              }`}
            >
              {formatDistance(r)}
            </button>
          ))}
        </div>

        {value.latitude != null && value.longitude != null && (
          <p className="font-mono text-[11px] text-muted-foreground">
            {value.latitude.toFixed(6)}, {value.longitude.toFixed(6)}
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import type * as LeafletNS from "leaflet";
import "leaflet/dist/leaflet.css";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { MapPin, ExternalLink, ShieldCheck, Crosshair, Clock, Loader2, Navigation, Laptop } from "lucide-react";
import { cn } from "@/lib/utils";
import type { DeviceInfo } from "@/lib/attendance/device-info";
import { IconAction } from "@/components/ui/icon-action";

/** One label/value pair in the device panel; hidden when unknown. */
function DeviceField({
  label,
  value,
  mono,
}: {
  label: string;
  value?: string | null;
  mono?: boolean;
}) {
  return (
    <div className="min-w-0 space-y-0.5">
      <dt className="text-[11px] text-muted-foreground">{label}</dt>
      <dd
        className={cn(
          "truncate font-medium text-foreground",
          mono && "font-mono text-[11px]",
          !value && "text-muted-foreground font-normal"
        )}
        title={value || undefined}
      >
        {value || "Not recorded"}
      </dd>
    </div>
  );
}

interface LocationData {
  latitude: number;
  longitude: number;
  accuracy?: number;
}

interface LocationMapModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  location: LocationData | null;
  title: string;
  employeeName?: string;
  timestamp?: string;
  workLocation?: string;
  /** Self-reported browser/device details captured with the punch. */
  deviceInfo?: Partial<DeviceInfo> | null;
  /** Public IP resolved server-side at punch time. */
  ipAddress?: string | null;
}

export function LocationMapModal({
  open,
  onOpenChange,
  location,
  title,
  employeeName,
  timestamp,
  workLocation = "OFFICE",
  deviceInfo,
  ipAddress,
}: LocationMapModalProps) {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<LeafletNS.Map | null>(null);

  const hasRealGps = Boolean(location && location.latitude && location.longitude);
  const [liveGpsLoading, setLiveGpsLoading] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<LocationData | null>(location);

  // Sync currentLocation when location prop changes
  useEffect(() => {
    setCurrentLocation(location);
  }, [location]);

  // No fallback coordinates. This used to default to a hardcoded Bengaluru
  // point with a fabricated ±25m accuracy, so a record with no GPS — which
  // was every record, because the punch flow swallowed geolocation errors
  // and stored null — displayed as a precise-looking location hundreds of
  // kilometres from where the person actually was. For a feature whose
  // whole purpose is location verification, showing nothing is the only
  // honest option.
  const activeLocation =
    currentLocation && currentLocation.latitude && currentLocation.longitude
      ? currentLocation
      : null;

  const handleFetchLiveDeviceGps = () => {
    if (!navigator.geolocation) {
      toast.error("Geolocation is not supported by your browser.");
      return;
    }
    setLiveGpsLoading(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setLiveGpsLoading(false);
        const liveData = {
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude,
          accuracy: pos.coords.accuracy,
        };
        setCurrentLocation(liveData);
        toast.success(`Device location detected! (${liveData.latitude.toFixed(4)}, ${liveData.longitude.toFixed(4)})`);
      },
      () => {
        setLiveGpsLoading(false);
        toast.error("Unable to access device location. Please allow location permissions in browser settings.");
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  useEffect(() => {
    if (!open || !mapContainerRef.current || !activeLocation) return;

    // Leaflet is a real dependency, imported dynamically because it
    // touches `window` on import and would break SSR. It used to be
    // injected as a <script src="unpkg.com/..."> with no integrity hash,
    // which meant a compromise of that CDN — or any MITM — was arbitrary
    // JS running inside an authenticated session.
    let cancelled = false;

    const initMap = (L: typeof LeafletNS) => {
      if (cancelled || !mapContainerRef.current) return;

      // Clean up existing map instance
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
      }

      const { latitude, longitude, accuracy } = activeLocation;

      // Initialize Leaflet Map
      const map = L.map(mapContainerRef.current, {
        zoomControl: true,
        scrollWheelZoom: true,
      }).setView([latitude, longitude], 16);
      mapInstanceRef.current = map;

      // Add CartoDB / OpenStreetMap tiles (faster & reliable CDN)
      L.tileLayer("https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png", {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',
        subdomains: "abcd",
        maxZoom: 19,
      }).addTo(map);

      // Create Custom Leaflet Marker Icon
      const customIcon = L.divIcon({
        className: "custom-leaflet-marker",
        html: `
          <div style="
            background: #0284c7;
            width: 32px;
            height: 32px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 3px solid #ffffff;
            box-shadow: 0 4px 12px rgba(2, 132, 199, 0.4);
            color: #ffffff;
          ">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
              <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/>
              <circle cx="12" cy="10" r="3"/>
            </svg>
          </div>
        `,
        iconSize: [32, 32],
        iconAnchor: [16, 32],
        popupAnchor: [0, -32],
      });

      // Add Marker.
      const marker = L.marker([latitude, longitude], { icon: customIcon }).addTo(map);

      const popupNode = document.createElement("div");
      popupNode.style.cssText = "font-family: sans-serif; font-size: 12px; padding: 2px;";

      const nameEl = document.createElement("strong");
      nameEl.textContent = employeeName || "Employee";

      const titleEl = document.createElement("span");
      titleEl.textContent = title;

      const timeEl = document.createElement("small");
      timeEl.style.color = "#64748b";
      timeEl.textContent = timestamp || "";

      popupNode.append(nameEl, document.createElement("br"), titleEl, document.createElement("br"), timeEl);

      marker.bindPopup(popupNode).openPopup();

      // Add GPS Accuracy Circle
      if (accuracy) {
        L.circle([latitude, longitude], {
          color: "#0284c7",
          fillColor: "#0284c7",
          fillOpacity: 0.15,
          radius: Math.max(accuracy, 10),
        }).addTo(map);
      }

      // Multi-phase invalidateSize to handle modal animation pop-in seamlessly
      [50, 150, 300, 600, 1000].forEach((delay) => {
        setTimeout(() => {
          if (mapInstanceRef.current) {
            mapInstanceRef.current.invalidateSize();
          }
        }, delay);
      });
    };

    import("leaflet").then((mod) => initMap((mod.default ?? mod) as typeof LeafletNS));

    return () => {
      cancelled = true;
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
      }
    };
  }, [open, activeLocation, employeeName, title, timestamp]);

  const googleMapsUrl = activeLocation
    ? `https://www.google.com/maps?q=${activeLocation.latitude},${activeLocation.longitude}`
    : null;

  // A fix wider than this tells you which city someone is in, not which
  // building — it is a wifi/IP lookup, not a satellite fix.
  const isCoarse = activeLocation ? (activeLocation.accuracy ?? 0) > 500 : false;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl bg-card border-border text-foreground p-0 overflow-hidden rounded-2xl shadow-2xl">
        <DialogHeader className="px-6 pt-5 pb-3 border-b border-border">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-2.5">
              <div className="p-2 bg-primary/10 rounded-xl text-primary">
                <MapPin className="size-5" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <DialogTitle className="text-base font-bold text-foreground">
                    {title}
                  </DialogTitle>
                  {!activeLocation ? (
                    <Badge className="bg-muted text-muted-foreground border-border text-[10px] font-semibold">
                      No Location Recorded
                    </Badge>
                  ) : isCoarse ? (
                    <Badge className="bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20 text-[10px] font-semibold">
                      Approximate (Network Fix)
                    </Badge>
                  ) : hasRealGps ? (
                    <Badge className="bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20 text-[10px] font-semibold">
                      Verified Device GPS
                    </Badge>
                  ) : (
                    <Badge className="bg-sky-500/10 text-sky-600 dark:text-sky-400 border-sky-500/20 text-[10px] font-semibold">
                      Live Device Location
                    </Badge>
                  )}
                </div>
                <DialogDescription className="text-xs text-muted-foreground mt-0.5">
                  {employeeName ? `GPS Verification for ${employeeName}` : "GPS Location Verification"}
                </DialogDescription>
              </div>
            </div>
            
            <div className="flex items-center gap-2">
              <IconAction label="Detect My Live Location" icon={liveGpsLoading ? <Loader2 className="size-3.5 animate-spin" /> : <Navigation className="size-3.5 text-primary" />} type="button"
                variant="outline"
                onClick={handleFetchLiveDeviceGps}
                disabled={liveGpsLoading}
                className="h-8 text-xs gap-1.5 border-border bg-background hover:bg-muted text-foreground" />
              {googleMapsUrl && (
                <a
                  href={googleMapsUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary hover:underline bg-primary/10 px-3 py-1.5 rounded-lg transition-colors h-8"
                >
                  <ExternalLink className="size-3.5" />
                  Google Maps
                </a>
              )}
            </div>
          </div>
        </DialogHeader>

        {/* Leaflet / OpenStreetMap Map Container */}
        <div className="relative w-full h-[340px] bg-muted overflow-hidden">
          {activeLocation ? (
            <iframe
              title="Attendance GPS Map Location"
              className="w-full h-[340px] border-0"
              src={`https://www.openstreetmap.org/export/embed.html?bbox=${activeLocation.longitude - 0.005}%2C${activeLocation.latitude - 0.004}%2C${activeLocation.longitude + 0.005}%2C${activeLocation.latitude + 0.004}&layer=mapnik&marker=${activeLocation.latitude}%2C${activeLocation.longitude}`}
              style={{ width: "100%", height: "340px", border: 0 }}
            />
          ) : (
            <div className="flex h-full flex-col items-center justify-center gap-2 px-8 text-center">
              <MapPin className="size-8 text-muted-foreground/40" />
              <p className="text-sm font-semibold text-foreground">
                No location was recorded for this punch
              </p>
              <p className="max-w-sm text-xs text-muted-foreground">
                The device either denied location permission or could not get a
                fix at the time. Use &ldquo;Detect My Live Location&rdquo; to
                check the current device position — that is where the device is
                now, not where this punch happened.
              </p>
            </div>
          )}
        </div>

        {/* Footer Details */}
        <div className="px-6 py-4 bg-muted/30 border-t border-border grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
          <div className="space-y-0.5">
            <span className="text-muted-foreground flex items-center gap-1 text-[11px]">
              <Crosshair className="size-3 text-primary" /> Latitude
            </span>
            <p className="font-mono font-bold text-foreground">
              {activeLocation ? activeLocation.latitude.toFixed(6) : "—"}
            </p>
          </div>
          <div className="space-y-0.5">
            <span className="text-muted-foreground flex items-center gap-1 text-[11px]">
              <Crosshair className="size-3 text-primary" /> Longitude
            </span>
            <p className="font-mono font-bold text-foreground">
              {activeLocation ? activeLocation.longitude.toFixed(6) : "—"}
            </p>
          </div>
          <div className="space-y-0.5">
            <span className="text-muted-foreground flex items-center gap-1 text-[11px]">
              <ShieldCheck
                className={cn("size-3", isCoarse ? "text-amber-500" : "text-emerald-500")}
              />{" "}
              Accuracy
            </span>
            {/* Never invent an accuracy figure — an unknown radius shown as
                "±15 m" is what made a network fix look like a satellite one. */}
            <p
              className={cn(
                "font-mono font-bold",
                !activeLocation || activeLocation.accuracy == null
                  ? "text-muted-foreground"
                  : isCoarse
                    ? "text-amber-600 dark:text-amber-400"
                    : "text-emerald-600 dark:text-emerald-400"
              )}
            >
              {activeLocation && activeLocation.accuracy != null
                ? `±${Math.round(activeLocation.accuracy)} meters`
                : "Unknown"}
            </p>
          </div>
          <div className="space-y-0.5">
            <span className="text-muted-foreground flex items-center gap-1 text-[11px]">
              <Clock className="size-3 text-amber-500" /> Mode / Work Type
            </span>
            <p className="font-semibold text-foreground">{workLocation}</p>
          </div>
        </div>

        {/* Device provenance. Everything here except the IP is self-reported
            by the browser and can be spoofed, so it is labelled as such
            rather than presented as proof. */}
        <div className="border-t border-border px-6 py-4">
          <div className="mb-2 flex items-center gap-1.5">
            <Laptop className="size-3.5 text-primary" />
            <span className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
              Device &amp; Network
            </span>
          </div>

          {!deviceInfo && !ipAddress ? (
            <p className="text-xs text-muted-foreground">
              No device details were recorded for this punch.
            </p>
          ) : (
            <>
              <dl className="grid grid-cols-2 gap-x-4 gap-y-2 text-xs sm:grid-cols-3">
                <DeviceField label="Device" value={deviceInfo?.device_type} />
                <DeviceField label="Operating system" value={deviceInfo?.os} />
                <DeviceField label="Browser" value={deviceInfo?.browser} />
                <DeviceField label="IP address" value={ipAddress} mono />
                <DeviceField label="Device timezone" value={deviceInfo?.timezone} />
                <DeviceField label="Network" value={deviceInfo?.network_type} />
                <DeviceField label="Screen" value={deviceInfo?.screen} mono />
                <DeviceField label="Language" value={deviceInfo?.language} />
                <DeviceField
                  label="Touchscreen"
                  value={
                    deviceInfo?.touch_capable === undefined
                      ? undefined
                      : deviceInfo.touch_capable
                        ? "Yes"
                        : "No"
                  }
                />
              </dl>

              <p className="mt-3 text-[10px] leading-relaxed text-muted-foreground">
                The IP is recorded by the server and cannot be set by the
                device. Everything else is reported by the browser itself and
                can be altered by a determined user — treat it as supporting
                detail, not proof. A MAC address cannot be read from a browser
                at all.
              </p>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { 
  Loader2, 
  Fingerprint, 
  Coffee, 
  Play, 
  Clock,
  Building2,
  Home,
  Briefcase,
  MapPin
} from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
// The template-driven multi-row table replaces the old fixed
// task/hours/notes form, which ignored fields_json entirely.
import { TimesheetEntryTable } from '@/components/timesheets/timesheet-entry-table';
import { LocationMapModal } from '@/components/attendance/location-map-modal';
import { sanitizeErrorMessage } from '@/lib/commerce/barcode-utils';
import {
  acquirePreciseLocation,
  checkGeofence,
  formatDistance,
  GeolocationFailure,
  GEOLOCATION_FAILURE_MESSAGES,
  getGeolocationPermission,
  type PreciseLocation,
} from '@/lib/attendance/geolocation';
import { collectDeviceInfo } from '@/lib/attendance/device-info';
import { calculateAttendanceMetrics } from '@/lib/hr/attendance/attendance-engine';
import {
  DEFAULT_ATTENDANCE_POLICY,
  parseAttendancePolicy,
  type AttendancePolicy,
  type GeofenceStatus,
  type PunchLocation,
  type WorkLocation,
} from '@/lib/attendance/policy';
import { IconAction } from "@/components/ui/icon-action";

const WORK_LOCATION_ICONS: Record<WorkLocation, typeof Building2> = {
  OFFICE: Building2,
  WFH: Home,
  CLIENT_SITE: Briefcase,
  FIELD: MapPin,
};

const WORK_LOCATION_SHORT_LABELS: Record<WorkLocation, string> = {
  OFFICE: 'Office',
  WFH: 'WFH',
  CLIENT_SITE: 'Client',
  FIELD: 'Field',
};

export function PunchAction({ onPunch }: { onPunch?: () => void }) {
  const supabase = createClient();
  const { activeWorkspace, activeMember, moduleAccess } = useWorkspace();

  const [loading, setLoading] = useState(false);
  const [todayRecord, setTodayRecord] = useState<any | null>(null);
  const [activeBreak, setActiveBreak] = useState<any | null>(null);
  const [workLocation, setWorkLocation] = useState<WorkLocation>('OFFICE');
  const [policy, setPolicy] = useState<AttendancePolicy>(DEFAULT_ATTENDANCE_POLICY);
  const [locatingMessage, setLocatingMessage] = useState<string | null>(null);
  const [showLocationHelp, setShowLocationHelp] = useState(false);
  const [diagnostic, setDiagnostic] = useState<string | null>(null);
  // null = not yet known. Rendering the punch controls before this
  // resolves would flash them for people who never clock in.
  const [attendanceEnabled, setAttendanceEnabled] = useState<boolean | null>(null);
  const [breakType, setBreakType] = useState<'LUNCH' | 'TEA' | 'PERSONAL' | 'MEETING'>('LUNCH');
  const [showTimeLogModal, setShowTimeLogModal] = useState(false);
  const [lastLoggedHours, setLastLoggedHours] = useState<number | undefined>(undefined);
  
  const todayDate = new Date().toISOString().split('T')[0];

  const fetchTodayStatus = useCallback(async () => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    
    const { data, error } = await supabase
      .from('attendance')
      .select('*')
      .eq('workspace_id', activeWorkspace.id)
      .eq('workspace_member_id', activeMember.id)
      .eq('attendance_date', todayDate)
      .maybeSingle();
      
    if (!error && data) {
      setTodayRecord(data);

      // Check if there is an active ongoing break
      const { data: ongoingBreak } = await supabase
        .from('hr_attendance_breaks')
        .select('*')
        .eq('attendance_id', data.id)
        .is('end_time', null)
        .maybeSingle();

      setActiveBreak(ongoingBreak || null);
    }
  }, [supabase, activeWorkspace?.id, activeMember?.id, todayDate]);

  useEffect(() => {
    fetchTodayStatus();
  }, [fetchTodayStatus]);

  // Does this person clock in at all? Set per employee in HR; the punch
  // controls are hidden entirely when it is off.
  useEffect(() => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    let cancelled = false;
    (async () => {
      const { data, error } = await supabase
        .from('employee_profiles')
        .select('attendance_enabled')
        .eq('workspace_id', activeWorkspace.id)
        .eq('workspace_member_id', activeMember.id)
        .maybeSingle();
      if (cancelled) return;
      // No employee row, or the column not deployed yet: fall back to
      // showing the controls rather than hiding attendance from everyone.
      if (error) setAttendanceEnabled(true);
      else setAttendanceEnabled(data ? data.attendance_enabled !== false : false);
    })();
    return () => { cancelled = true; };
  }, [supabase, activeWorkspace?.id, activeMember?.id]);

  // Resolve this member's effective policy for today: which work locations
  // they may pick, whether GPS is required, the geofence, and whether
  // punching out asks for a timesheet.
  useEffect(() => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    let cancelled = false;

    (async () => {
      const { data, error } = await supabase.rpc('resolve_attendance_policy', {
        p_workspace_id: activeWorkspace.id,
        p_workspace_member_id: activeMember.id,
        p_date: todayDate,
      });
      if (cancelled) return;

      // Fall back to the permissive default rather than blocking punches if
      // the policy tables are not deployed yet.
      const resolved = error ? DEFAULT_ATTENDANCE_POLICY : parseAttendancePolicy(data);
      setPolicy(resolved);
      setWorkLocation((current) =>
        resolved.allowed_work_locations.includes(current)
          ? current
          : resolved.default_work_location
      );
    })();

    return () => {
      cancelled = true;
    };
  }, [supabase, activeWorkspace?.id, activeMember?.id, todayDate]);

  /**
   * Reports exactly what the browser says, rather than guessing which of
   * the three gates is closed. The raw error code is the thing that
   * actually distinguishes them: 1 = PERMISSION_DENIED (site or OS),
   * 2 = POSITION_UNAVAILABLE (no fix — OS services off, or no signal),
   * 3 = TIMEOUT.
   */
  const runLocationDiagnostic = async () => {
    setDiagnostic('Running…');
    const lines: string[] = [];
    lines.push(`Secure origin: ${typeof window !== 'undefined' && window.isSecureContext ? 'yes' : 'NO — location is blocked outright'}`);
    lines.push(`Origin: ${typeof window !== 'undefined' ? window.location.origin : '?'}`);
    lines.push(`Geolocation API present: ${typeof navigator !== 'undefined' && 'geolocation' in navigator ? 'yes' : 'no'}`);
    lines.push(`Permissions API reports: ${await getGeolocationPermission()}`);

    const raw = await new Promise<string>((resolve) => {
      if (typeof navigator === 'undefined' || !navigator.geolocation) {
        resolve('no geolocation object');
        return;
      }
      const started = Date.now();
      navigator.geolocation.getCurrentPosition(
        (pos) =>
          resolve(
            `SUCCESS in ${Date.now() - started}ms — accuracy ±${Math.round(pos.coords.accuracy)}m`
          ),
        (err) =>
          resolve(
            `FAILED code ${err.code} (${
              err.code === 1 ? 'PERMISSION_DENIED' : err.code === 2 ? 'POSITION_UNAVAILABLE' : 'TIMEOUT'
            }) after ${Date.now() - started}ms — "${err.message}"`
          ),
        { enableHighAccuracy: true, timeout: 15_000, maximumAge: 0 }
      );
    });
    lines.push(`Direct request: ${raw}`);

    // code 2 with the site allowed is the OS withholding it; code 1 with
    // the site allowed is almost always the OS too, on macOS.
    if (raw.includes('code 2')) {
      lines.push('');
      lines.push('POSITION_UNAVAILABLE with the site allowed means the operating system has no fix to give — macOS Location Services is off for this browser, or Wi-Fi/GPS is disabled.');
    } else if (raw.includes('code 1')) {
      lines.push('');
      lines.push('PERMISSION_DENIED while the site shows Allow points at the OS layer or a browser shield (Brave), not the site permission.');
    }
    setDiagnostic(lines.join('\n'));
  };

  /**
   * `skipLocation` records the punch with the location marked unavailable
   * instead of refusing it. Offered only after a genuine geolocation
   * failure, and never silently: blocking someone from clocking out
   * because macOS is withholding GPS from their browser is worse than
   * storing an honest "no fix, flagged for review" — they still have to
   * be paid for the day.
   */
  const handlePunch = async (type: 'in' | 'out', skipLocation = false) => {
    if (!activeWorkspace?.id || !activeMember?.id) return;
    setLoading(true);

    try {
      // Working from home has no office to stand near, so it never needs a
      // fix. Everything else does: this used to swallow every geolocation
      // failure and store null, which is why no punch has ever recorded a
      // location and the map fell back to a hardcoded city centre.
      const locationRequired =
        !skipLocation &&
        policy.require_location &&
        policy.require_location_for.includes(workLocation);

      let locationData: PunchLocation | null = null;
      let geofenceStatus: GeofenceStatus = locationRequired ? 'NOT_ENFORCED' : 'EXEMPT';
      let distanceM: number | null = null;
      // Recorded so HR can tell "WFH, no location needed" apart from
      // "location was required but the device could not supply one".
      const exemptReason: string | null = skipLocation
        ? 'Device could not provide a location; recorded by the employee without one.'
        : null;

      // Device and network context are captured for every punch, including
      // WFH — knowing which machine clocked in is useful even when there is
      // no location to check.
      const deviceInfo = collectDeviceInfo();
      const networkContext = await fetch('/api/attendance/device-context')
        .then((r) => (r.ok ? r.json() : null))
        .catch(() => null);

      if (locationRequired) {
        // Always ATTEMPT the fix, even when the Permissions API reports
        // 'denied'. Short-circuiting here was wrong: it meant the browser
        // was never asked, so the native "Allow location?" prompt could
        // not appear at all. The reported state can also be stale — a
        // user who has just re-allowed the site still reads as denied
        // until something queries again. Requesting costs nothing when it
        // really is blocked; the call simply fails and we explain.
        const permission = await getGeolocationPermission();
        setLocatingMessage(
          permission === 'denied'
            ? 'Requesting location — allow it if your browser asks…'
            : permission === 'prompt'
              ? 'Allow location access when your browser asks…'
              : 'Getting a precise GPS fix…'
        );
        let fix: PreciseLocation;
        try {
          fix = await acquirePreciseLocation({
            desiredAccuracyM: policy.min_gps_accuracy_m,
            timeoutMs: 25_000,
          });
        } catch (geoError) {
          // Surface the reason and stop. Recording a punch with no location
          // when policy demands one is what produced the bad data.
          const failure =
            geoError instanceof GeolocationFailure ? geoError : null;
          const message = failure
            ? failure.message
            : GEOLOCATION_FAILURE_MESSAGES.position_unavailable;

          // Only a blocked permission needs the browser-settings walkthrough;
          // a timeout or a bad fix just needs another go.
          // Punching OUT is never hard-blocked: the shift already happened,
          // and refusing to record its end loses real worked hours. Punching
          // IN still requires a fix unless HR allowed the exemption.
          if (type === 'out') {
            toast.error(message, {
              duration: 12_000,
              action: {
                label: 'Punch out anyway',
                onClick: () => handlePunch('out', true),
              },
            });
          } else {
            toast.error(message, {
              duration: 12_000,
              action:
                failure?.reason === 'permission_denied'
                  ? { label: 'How to fix', onClick: () => setShowLocationHelp(true) }
                  : { label: 'Try again', onClick: () => handlePunch(type) },
            });
          }
          return;
        } finally {
          setLocatingMessage(null);
        }

        if (fix.coarse && fix.accuracy > policy.min_gps_accuracy_m) {
          toast.error(
            `Location is only accurate to ±${Math.round(fix.accuracy)}m, but this workspace requires ±${policy.min_gps_accuracy_m}m. ` +
              `Move outdoors or enable precise location, then try again.`
          );
          return;
        }

        locationData = {
          latitude: fix.latitude,
          longitude: fix.longitude,
          accuracy: fix.accuracy,
          captured_at: fix.capturedAt,
        };

        if (policy.geofence) {
          const check = checkGeofence(fix, {
            latitude: policy.geofence.latitude,
            longitude: policy.geofence.longitude,
            radiusM: policy.geofence.radius_m,
          });
          distanceM = check.distanceM;
          geofenceStatus = check.inconclusive
            ? 'INCONCLUSIVE'
            : check.inside
              ? 'INSIDE'
              : 'OUTSIDE';

          if (!check.inside && !check.inconclusive && policy.block_outside_geofence) {
            toast.error(
              `You are ${formatDistance(check.distanceM)} from ${policy.geofence.label || 'the allowed location'} ` +
                `(limit ${formatDistance(check.radiusM)}). Punching in is only allowed on site.`
            );
            return;
          }
          if (geofenceStatus === 'OUTSIDE') {
            toast.warning(
              `Recorded ${formatDistance(check.distanceM)} outside ${policy.geofence.label || 'the allowed area'}. HR will see this flagged.`
            );
          }
        }
      }

      const now = new Date().toISOString();

      if (type === 'in') {
        const { error } = await supabase
          .from('attendance')
          .insert({
            workspace_id: activeWorkspace.id,
            workspace_member_id: activeMember.id,
            attendance_date: todayDate,
            punch_in_time: now,
            punch_in_location: locationData,
            punch_in_accuracy_m: locationData?.accuracy ?? null,
            punch_in_distance_m: distanceM,
            punch_in_geofence_status: geofenceStatus,
            location_exempt_reason: exemptReason,
            punch_in_device_json: deviceInfo,
            punch_in_ip: networkContext?.ip ?? null,
            work_location: workLocation,
            status: workLocation === 'WFH' ? 'Remote' : 'Present'
          });
        if (error) throw error;
        toast.success(
          locationData
            ? `Punched in (${workLocation}) — location accurate to ±${Math.round(locationData.accuracy)}m.`
            : `Punched in (${workLocation}).`
        );
      } else {
        if (!todayRecord?.punch_in_time) throw new Error("No punch in record found.");
        
        // If an active break is ongoing, end it first
        if (activeBreak) {
          await handleBreak('resume');
        }

        // Single source of truth for attendance arithmetic — this used to
        // recompute it inline and never derived overtime, which is why the
        // "Approved Overtime" KPI on /attendance was permanently 0.
        //
        // No `shift` is passed: hr_shifts is empty and no workspace timezone
        // is stored, so lateness cannot be scored honestly yet. The engine
        // returns null for it rather than a made-up 0, and status/late_minutes
        // are left untouched here.
        const breakHours = Number(todayRecord.break_hours || 0);
        const metrics = calculateAttendanceMetrics({
          punchInTime: todayRecord.punch_in_time,
          punchOutTime: now,
          totalBreakMinutes: breakHours * 60,
        });
        const workingHours = metrics.totalHours;
        const netProductive = metrics.netProductiveHours;

        const { error } = await supabase
          .from('attendance')
          .update({
            punch_out_time: now,
            punch_out_location: locationData,
            punch_out_accuracy_m: locationData?.accuracy ?? null,
            punch_out_distance_m: distanceM,
            punch_out_geofence_status: skipLocation ? 'INCONCLUSIVE' : geofenceStatus,
            punch_out_device_json: deviceInfo,
            punch_out_ip: networkContext?.ip ?? null,
            location_exempt_reason: exemptReason,
            // Surfaced to HR rather than buried: a punch with no location is
            // valid but worth a look.
            review_flags: skipLocation ? ['PUNCH_OUT_WITHOUT_LOCATION'] : null,
            working_hours: workingHours,
            net_productive_hours: netProductive,
            overtime_hours: metrics.overtimeHours
          })
          .eq('id', todayRecord.id);
        if (error) throw error;

        toast.success(`Punched out! Logged ${workingHours} hrs (${netProductive} hrs net productive).`);

        setLastLoggedHours(netProductive);
        // HR decides per employee whether punching out requires a timesheet.
        if (policy.require_timesheet_on_punch_out) {
          setShowTimeLogModal(true);
        }
      }

      await fetchTodayStatus();
      onPunch?.();
    } catch (error: any) {
      toast.error(sanitizeErrorMessage(error, 'Failed to update attendance'));
    } finally {
      setLoading(false);
    }
  };

  const handleBreak = async (action: 'start' | 'resume') => {
    if (!todayRecord?.id || !activeWorkspace?.id || !activeMember?.id) return;
    setLoading(true);

    try {
      const now = new Date().toISOString();

      if (action === 'start') {
        const { error } = await supabase
          .from('hr_attendance_breaks')
          .insert({
            workspace_id: activeWorkspace.id,
            attendance_id: todayRecord.id,
            workspace_member_id: activeMember.id,
            break_type: breakType,
            start_time: now,
          });
        if (error) throw error;
        toast.success(`Break started (${breakType})`);
      } else {
        if (!activeBreak?.id) return;
        const startTime = new Date(activeBreak.start_time).getTime();
        const endTime = new Date(now).getTime();
        const durationMins = Math.max(1, Math.round((endTime - startTime) / (1000 * 60)));

        const { error: breakErr } = await supabase
          .from('hr_attendance_breaks')
          .update({
            end_time: now,
            duration_minutes: durationMins,
          })
          .eq('id', activeBreak.id);
        if (breakErr) throw breakErr;

        // Recalculate total break hours on attendance record
        const { data: allBreaks } = await supabase
          .from('hr_attendance_breaks')
          .select('duration_minutes')
          .eq('attendance_id', todayRecord.id);

        const totalMins = (allBreaks || []).reduce((sum, b) => sum + Number(b.duration_minutes || 0), 0);
        const totalBreakHrs = parseFloat((totalMins / 60).toFixed(2));

        await supabase
          .from('attendance')
          .update({ break_hours: totalBreakHrs })
          .eq('id', todayRecord.id);

        toast.success(`Resumed work! Break duration: ${durationMins} mins.`);
      }

      await fetchTodayStatus();
      onPunch?.();
    } catch (error: any) {
      toast.error(sanitizeErrorMessage(error, 'Failed to update break status'));
    } finally {
      setLoading(false);
    }
  };

  const [showLocationMap, setShowLocationMap] = useState(false);

  // Must sit below every hook: this component renders in the global header,
  // so a mid-session permission change that flips `moduleAccess` while the
  // component stays mounted would otherwise change the hook count and
  // white-screen the whole dashboard.
  if (!moduleAccess?.hr) {
    return null;
  }

  // Hidden while unknown, and for anyone attendance is switched off for.
  if (attendanceEnabled !== true) {
    return null;
  }

  return (
    <>
      {/* Once a browser has been told "block", it will not ask again — the
          only route back is the site settings, so spell it out per
          platform rather than repeating "permission denied". */}
      <Dialog open={showLocationHelp} onOpenChange={setShowLocationHelp}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Turn location back on</DialogTitle>
            <DialogDescription>
              Your browser is blocking location for this site, so it will not ask again until you
              change it here.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 text-sm">
            <p className="text-muted-foreground">
              Location has <strong>two</strong> switches. The site permission is the one people
              check; the operating system one is the one that is usually actually off.
            </p>
            <div>
              <p className="font-semibold">1. Your operating system</p>
              <p className="text-muted-foreground">
                macOS: System Settings &rarr; Privacy &amp; Security &rarr; Location Services &rarr;
                switch it on <em>and</em> tick your browser in the list. Windows: Settings &rarr;
                Privacy &amp; security &rarr; Location. iPhone or Android: enable location for the
                browser app, and check GPS is on.
              </p>
            </div>
            <div>
              <p className="font-semibold">2. This site</p>
              <p className="text-muted-foreground">
                Click the icon at the left of the address bar &rarr; Location &rarr; Allow, then
                reload. In Brave, also check the Shields icon.
              </p>
            </div>
            <div>
              <p className="font-semibold">3. A secure connection</p>
              <p className="text-muted-foreground">
                Browsers block location on plain <code>http://</code> unless the address is exactly{" "}
                <code>localhost</code>. Opening a dev server by its IP — say{" "}
                <code>http://192.168.x.x:3000</code> — fails no matter what the permissions say.
              </p>
              {typeof window !== "undefined" && !window.isSecureContext && (
                <p className="mt-1 font-medium text-destructive">
                  This page is NOT on a secure origin, so location cannot work here until you use
                  HTTPS or localhost.
                </p>
              )}
            </div>
          </div>

          {diagnostic && (
            <pre className="max-h-52 overflow-auto whitespace-pre-wrap rounded-lg border border-border bg-muted/50 p-3 text-[11px] leading-relaxed text-foreground">
              {diagnostic}
            </pre>
          )}

          <div className="flex flex-wrap justify-end gap-2 border-t border-border pt-3">
            <Button variant="outline" onClick={runLocationDiagnostic}>
              Run diagnostic
            </Button>
            <Button variant="outline" onClick={() => setShowLocationHelp(false)}>
              Close
            </Button>
            <IconAction label="Try again" icon={<Fingerprint className="size-4" />} onClick={() => {
                setShowLocationHelp(false);
                handlePunch(todayRecord?.punch_in_time && !todayRecord?.punch_out_time ? 'out' : 'in');
              }}
              className="gap-1.5" />
          </div>
        </DialogContent>
      </Dialog>

      {/* Never wraps: this sits in a fixed-height header, so a second line
          overflows the bar instead of growing it. The controls degrade by
          width instead — the status pill collapses to its icon, the break
          picker drops out, and the punch button always survives. */}
      <div className="flex min-w-0 items-center gap-2">
        {!todayRecord || !todayRecord.punch_in_time ? (
          <div className="flex items-center gap-2">
            {/* Work Location Selector — renders only what HR allows this
                member. An on-site-only employee never sees a WFH option, so
                a single allowed mode shows as a static label instead. */}
            {policy.allowed_work_locations.length > 1 ? (
              <div className="hidden items-center rounded-lg border border-border bg-muted/50 p-0.5 text-xs sm:flex">
                {policy.allowed_work_locations.map((option) => {
                  const Icon = WORK_LOCATION_ICONS[option];
                  return (
                    <button
                      key={option}
                      type="button"
                      onClick={() => setWorkLocation(option)}
                      className={`px-2 py-1 rounded-md font-medium transition-all flex items-center gap-1 ${
                        workLocation === option
                          ? 'bg-primary text-primary-foreground font-semibold shadow-xs'
                          : 'text-muted-foreground hover:text-foreground'
                      }`}
                    >
                      <Icon className="h-3.5 w-3.5" />
                      {WORK_LOCATION_SHORT_LABELS[option]}
                    </button>
                  );
                })}
              </div>
            ) : (
              <div className="flex items-center gap-1 bg-muted/50 border border-border rounded-lg px-2 py-1.5 text-xs text-muted-foreground">
                {(() => {
                  const Icon = WORK_LOCATION_ICONS[workLocation];
                  return <Icon className="h-3.5 w-3.5" />;
                })()}
                <span className="font-medium text-foreground">
                  {WORK_LOCATION_SHORT_LABELS[workLocation]}
                </span>
              </div>
            )}

            <IconAction
              label={locatingMessage ? 'Locating…' : 'Punch in'}
              icon={loading ? <Loader2 className="size-3.5 animate-spin" /> : <Fingerprint className="size-3.5" />}
              onClick={() => handlePunch('in')}
              disabled={loading}
              className="h-9 shrink-0 rounded-lg bg-emerald-600 px-3 text-white shadow-xs hover:bg-emerald-700 dark:bg-emerald-600 dark:hover:bg-emerald-500"
            />

            {locatingMessage && (
              <span className="hidden text-[11px] text-muted-foreground lg:inline">{locatingMessage}</span>
            )}

            {policy.override_note && (
              <span className="hidden text-[11px] text-amber-600 lg:inline dark:text-amber-400">
                {policy.override_note}
              </span>
            )}
          </div>
        ) : todayRecord.punch_in_time && !todayRecord.punch_out_time ? (
          <div className="flex min-w-0 items-center gap-2">
            <div className="flex min-w-0 items-center gap-1.5 text-xs text-emerald-700 dark:text-emerald-400 font-medium bg-emerald-500/10 px-2.5 py-1.5 rounded-lg border border-emerald-500/20">
              <Clock className="size-3.5 text-emerald-600 dark:text-emerald-400" />
              {/* Below xl only the time survives; below sm, only the icon. */}
              <span className="hidden truncate sm:inline">
                <span className="hidden xl:inline">
                  Punched In ({todayRecord.work_location || 'OFFICE'}) at{' '}
                </span>
                {new Date(todayRecord.punch_in_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
              {todayRecord.punch_in_location && (
                <button
                  type="button"
                  onClick={() => setShowLocationMap(true)}
                  className="p-0.5 hover:bg-emerald-500/20 rounded transition-colors text-emerald-600 dark:text-emerald-400 ml-0.5"
                  title="View GPS Location Map"
                >
                  <MapPin className="size-3.5" />
                </button>
              )}
            </div>

            {/* Break Control Bar */}
            {activeBreak ? (
              <IconAction
                label={`Resume work from ${String(activeBreak.break_type).toLowerCase()} break`}
                icon={loading ? <Loader2 className="size-3.5 animate-spin" /> : <Play className="size-3.5" />}
                onClick={() => handleBreak('resume')}
                disabled={loading}
                className="h-9 shrink-0 rounded-lg bg-amber-600 px-3 text-white shadow-xs hover:bg-amber-700"
              />
            ) : (
              <div className="hidden items-center gap-1 rounded-lg border border-border bg-card p-0.5 md:flex">
                <select
                  value={breakType}
                  onChange={(e) => setBreakType(e.target.value as any)}
                  className="bg-background text-foreground border-none text-xs rounded-md px-2 py-1 focus:ring-0"
                >
                  <option value="LUNCH">Lunch Break</option>
                  <option value="TEA">Tea / Coffee</option>
                  <option value="PERSONAL">Personal</option>
                  <option value="MEETING">Client Meeting</option>
                </select>
                <IconAction label="Start Break" icon={<Coffee className="h-3.5 w-3.5" />} onClick={() => handleBreak('start')}
                  disabled={loading}
                  variant="outline"
                  className="h-7 border-amber-500/20 bg-amber-500/10 text-amber-700 dark:text-amber-300 hover:bg-amber-500/20 text-xs font-medium gap-1 rounded-md px-2" />
              </div>
            )}

            <IconAction
              label="Punch out"
              icon={loading ? <Loader2 className="size-3.5 animate-spin" /> : <Fingerprint className="size-3.5" />}
              onClick={() => handlePunch('out')}
              disabled={loading}
              className="h-9 shrink-0 rounded-lg bg-rose-600 px-3 text-white shadow-xs hover:bg-rose-700 dark:bg-rose-600 dark:hover:bg-rose-500"
            />
          </div>
        ) : (
          <div className="flex items-center gap-2 text-xs font-medium text-foreground bg-muted/40 px-3 py-1.5 rounded-lg border border-border">
            <Clock className="size-3.5 text-primary" />
            Logged {Number(todayRecord.working_hours ?? 0)} hrs ({Number(todayRecord.net_productive_hours ?? todayRecord.working_hours ?? 0)} hrs net) today
          </div>
        )}
      </div>

      <TimesheetEntryTable
        open={showTimeLogModal}
        onOpenChange={setShowTimeLogModal}
        templateId={policy.timesheet_template_id}
        loggedHours={lastLoggedHours}
        onSaved={() => {
          setShowTimeLogModal(false);
          fetchTodayStatus();
        }}
      />

      <LocationMapModal
        open={showLocationMap}
        onOpenChange={setShowLocationMap}
        location={todayRecord?.punch_in_location || null}
        title="Punch In GPS Location"
        timestamp={todayRecord?.punch_in_time ? new Date(todayRecord.punch_in_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : undefined}
        workLocation={todayRecord?.work_location || 'OFFICE'}
      />
    </>
  );
}

'use client';

import { useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Loader2, FileCheck2 } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';
import { sanitizeErrorMessage } from '@/lib/commerce/barcode-utils';

interface AttendanceRequestModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmitted: () => void;
}

export function AttendanceRequestModal({ open, onOpenChange, onSubmitted }: AttendanceRequestModalProps) {
  const supabase = createClient();
  const { activeWorkspace, activeMember } = useWorkspace();
  
  const [submitting, setSubmitting] = useState(false);
  const [requestType, setRequestType] = useState<'MISSED_PUNCH' | 'CORRECTION' | 'EARLY_EXIT' | 'WFH' | 'OVERTIME'>('MISSED_PUNCH');
  const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);
  const [requestedPunchIn, setRequestedPunchIn] = useState('09:00');
  const [requestedPunchOut, setRequestedPunchOut] = useState('18:00');
  const [reason, setReason] = useState('');

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!reason.trim()) {
      toast.error('Please enter a reason for your request');
      return;
    }

    if (!activeWorkspace?.id || !activeMember?.id) return;
    setSubmitting(true);

    try {
      const punchInISO = new Date(`${attendanceDate}T${requestedPunchIn}:00`).toISOString();
      const punchOutISO = new Date(`${attendanceDate}T${requestedPunchOut}:00`).toISOString();

      const { error } = await supabase
        .from('hr_attendance_requests')
        .insert({
          workspace_id: activeWorkspace.id,
          workspace_member_id: activeMember.id,
          request_type: requestType,
          attendance_date: attendanceDate,
          requested_punch_in: punchInISO,
          requested_punch_out: punchOutISO,
          reason: reason.trim(),
          status: 'PENDING',
        });

      if (error) throw error;

      toast.success('Attendance request submitted for manager approval');
      onSubmitted();
      onOpenChange(false);
      setReason('');
    } catch (err: any) {
      toast.error(sanitizeErrorMessage(err, 'Failed to submit request'));
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-card border-border text-foreground sm:max-w-md shadow-2xl">
        <DialogHeader>
          <DialogTitle className="text-foreground flex items-center gap-2 text-lg font-bold">
            <FileCheck2 className="h-5 w-5 text-[#00aef0]" />
            Request Attendance Regularization
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 py-2 text-xs">
          <div>
            <Label className="text-foreground mb-1 block">Request Type</Label>
            <select
              value={requestType}
              onChange={(e) => setRequestType(e.target.value as any)}
              className="w-full bg-background border border-border text-foreground rounded-xl p-2.5 text-xs font-semibold focus:border-[#00aef0]"
            >
              <option value="MISSED_PUNCH">Missed Punch (Forgot to Punch In/Out)</option>
              <option value="CORRECTION">Attendance Correction</option>
              <option value="EARLY_EXIT">Early Exit Approval</option>
              <option value="WFH">Work From Home Approval</option>
              <option value="OVERTIME">Overtime Hours Claim</option>
            </select>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <div>
              <Label className="text-foreground mb-1 block">Date *</Label>
              <Input
                type="date"
                value={attendanceDate}
                onChange={(e) => setAttendanceDate(e.target.value)}
                className="bg-background border-border text-foreground text-xs h-9"
                required
              />
            </div>
            <div>
              <Label className="text-foreground mb-1 block">Punch In</Label>
              <Input
                type="time"
                value={requestedPunchIn}
                onChange={(e) => setRequestedPunchIn(e.target.value)}
                className="bg-background border-border text-foreground text-xs h-9"
              />
            </div>
            <div>
              <Label className="text-foreground mb-1 block">Punch Out</Label>
              <Input
                type="time"
                value={requestedPunchOut}
                onChange={(e) => setRequestedPunchOut(e.target.value)}
                className="bg-background border-border text-foreground text-xs h-9"
              />
            </div>
          </div>

          <div>
            <Label className="text-foreground mb-1 block">Reason / Justification *</Label>
            <Textarea plain
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Provide a detailed explanation for your manager..."
              className="bg-background border-border text-foreground text-xs resize-none"
              rows={3}
              required
            />
          </div>

          <DialogFooter className="pt-3 border-t border-border">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="border-border text-muted-foreground hover:text-foreground"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={submitting}
              className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl shadow-lg shadow-[#00aef0]/20"
            >
              {submitting && <Loader2 className="size-4 animate-spin mr-2" />}
              Submit Request
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useEffect, useState, useCallback, useRef } from 'react';
import { toast } from 'sonner';
import { createClient } from '@/lib/supabase/client';
import { CustomField, Tag } from '@/types';
import { Button } from '@/components/ui/button';
import {
  Users,
  Tags,
  Filter,
  Upload,
  Loader2,
  ArrowRight,
  ArrowLeft,
  X,
} from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';
import { IconAction } from "@/components/ui/icon-action";

type AudienceType = 'all' | 'tags' | 'custom_field' | 'csv';
type CustomFieldOperator = 'is' | 'is_not' | 'contains';

interface CustomFieldFilter {
  fieldId: string;
  operator: CustomFieldOperator;
  value: string;
}

interface AudienceConfig {
  type: AudienceType;
  tagIds?: string[];
  customField?: CustomFieldFilter;
  csvContacts?: { phone: string; name?: string }[];
  excludeTagIds?: string[];
}

interface Step2Props {
  audience: AudienceConfig;
  onUpdate: (audience: AudienceConfig) => void;
  onNext: () => void;
  onBack: () => void;
}

const audienceOptions: {
  type: AudienceType;
  label: string;
  description: string;
  icon: typeof Users;
}[] = [
  {
    type: 'all',
    label: 'All Contacts',
    description: 'Send to every contact in your database',
    icon: Users,
  },
  {
    type: 'tags',
    label: 'Filter by Tags',
    description: 'Target contacts with specific tags',
    icon: Tags,
  },
  {
    type: 'custom_field',
    label: 'Custom Field',
    description: 'Filter by a custom field value',
    icon: Filter,
  },
  {
    type: 'csv',
    label: 'Upload CSV',
    description: 'Upload a list of phone numbers',
    icon: Upload,
  },
];

const OPERATOR_OPTIONS: { value: CustomFieldOperator; label: string }[] = [
  { value: 'is', label: 'is' },
  { value: 'is_not', label: 'is not' },
  { value: 'contains', label: 'contains' },
];

function parseCSV(text: string): { phone: string; name?: string }[] {
  const cleanText = text.replace(/^\uFEFF/, '');
  const lines = cleanText.trim().split(/\r?\n/);
  if (lines.length < 2) return [];

  const headerLine = lines[0];
  let delimiter = ',';
  if (!headerLine.includes(',') && headerLine.includes(';')) {
    delimiter = ';';
  } else if (!headerLine.includes(',') && headerLine.includes('\t')) {
    delimiter = '\t';
  }

  const headers = headerLine.split(delimiter).map((h) => h.trim().toLowerCase().replace(/["']/g, ''));
  const phoneIdx = headers.indexOf('phone');
  if (phoneIdx === -1) return [];

  const nameIdx = headers.indexOf('name');

  const rows: { phone: string; name?: string }[] = [];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const values: string[] = [];
    let current = '';
    let inQuotes = false;
    for (const char of line) {
      if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === delimiter && !inQuotes) {
        values.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    values.push(current.trim());

    const phone = values[phoneIdx]?.replace(/["']/g, '').trim();
    if (!phone) continue;

    rows.push({
      phone,
      name: nameIdx >= 0 ? values[nameIdx]?.replace(/["']/g, '').trim() || undefined : undefined,
    });
  }

  return rows;
}

export function Step2SelectAudience({
  audience,
  onUpdate,
  onNext,
  onBack,
}: Step2Props) {
  const { activeWorkspace } = useWorkspace();
  const workspaceId = activeWorkspace?.id;
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [csvFileName, setCsvFileName] = useState<string>('');
  
  const [tags, setTags] = useState<Tag[]>([]);
  const [customFields, setCustomFields] = useState<CustomField[]>([]);
  const [loadingTags, setLoadingTags] = useState(false);
  const [loadingFields, setLoadingFields] = useState(false);
  const [estimatedCount, setEstimatedCount] = useState<number | null>(null);
  const [loadingCount, setLoadingCount] = useState(false);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    setCsvFileName(selected.name);

    try {
      const text = await selected.text();
      const rows = parseCSV(text);

      if (rows.length === 0) {
        toast.error('No valid rows found. Ensure CSV has a "phone" column header.');
        onUpdate({ ...audience, csvContacts: [] });
        return;
      }

      onUpdate({ ...audience, csvContacts: rows });
      toast.success(`${rows.length} contacts loaded from CSV`);
    } catch (err) {
      console.error(err);
      toast.error('Failed to parse CSV file');
    }
  };

  // Tags are used both by the primary "Filter by Tags" audience type
  // AND by the exclude-list below — so always load once on mount.
  useEffect(() => {
    async function fetchTags() {
      if (!workspaceId) return;
      setLoadingTags(true);
      try {
        const supabase = createClient();
        const { data } = await supabase
          .from('tags')
          .select('*')
          .eq('workspace_id', workspaceId)
          .order('name');
        setTags(data ?? []);
      } finally {
        setLoadingTags(false);
      }
    }
    fetchTags();
  }, [workspaceId]);

  // Lazy-load custom fields only when that audience type is active.
  useEffect(() => {
    if (audience.type !== 'custom_field' || !workspaceId) return;
    async function fetchFields() {
      setLoadingFields(true);
      try {
        const supabase = createClient();
        const { data } = await supabase
          .from('custom_fields')
          .select('*')
          .eq('workspace_id', workspaceId)
          .order('field_name');
        setCustomFields(data ?? []);
      } finally {
        setLoadingFields(false);
      }
    }
    fetchFields();
  }, [audience.type, workspaceId]);

  const fetchEstimatedCount = useCallback(async () => {
    if (!activeWorkspace?.id) {
      setEstimatedCount(0);
      return;
    }
    setLoadingCount(true);
    try {
      const supabase = createClient();

      // Base query — produces the superset before exclude is applied.
      let baseIds: Set<string> | null = null; // null means "all contacts"

      if (audience.type === 'all') {
        // Handled below — full-table count adjusted by excludes.
      } else if (
        audience.type === 'tags' &&
        audience.tagIds &&
        audience.tagIds.length > 0
      ) {
        const { data } = await supabase
          .from('contact_tags')
          .select('contact_id, contacts!inner(workspace_id)')
          .eq('contacts.workspace_id', activeWorkspace.id)
          .in('tag_id', audience.tagIds);
        baseIds = new Set((data ?? []).map((r) => r.contact_id));
      } else if (
        audience.type === 'custom_field' &&
        audience.customField?.fieldId &&
        audience.customField.value
      ) {
        const { fieldId, operator, value } = audience.customField;
        let q = supabase
          .from('contact_custom_values')
          .select('contact_id, contacts!inner(workspace_id)')
          .eq('contacts.workspace_id', activeWorkspace.id)
          .eq('custom_field_id', fieldId);
        if (operator === 'is') q = q.eq('value', value);
        else if (operator === 'is_not') q = q.neq('value', value);
        else q = q.ilike('value', `%${value}%`);
        const { data } = await q;
        baseIds = new Set((data ?? []).map((r) => r.contact_id));
      } else if (
        audience.type === 'csv' &&
        audience.csvContacts &&
        audience.csvContacts.length > 0
      ) {
        setEstimatedCount(audience.csvContacts.length);
        return;
      } else {
        // Partially-configured audience — wait for the user to finish.
        setEstimatedCount(null);
        return;
      }

      // Apply exclude tags
      let excludeSet: Set<string> | null = null;
      if (audience.excludeTagIds && audience.excludeTagIds.length > 0) {
        const { data: excludeRows } = await supabase
          .from('contact_tags')
          .select('contact_id, contacts!inner(workspace_id)')
          .eq('contacts.workspace_id', activeWorkspace.id)
          .in('tag_id', audience.excludeTagIds);
        excludeSet = new Set((excludeRows ?? []).map((r) => r.contact_id));
      }

      if (baseIds) {
        const effective = [...baseIds].filter(
          (id) => !excludeSet?.has(id),
        );
        setEstimatedCount(effective.length);
      } else {
        // "All" — fetch the total, then subtract exclude set if any.
        const { count } = await supabase
          .from('contacts')
          .select('*', { count: 'exact', head: true })
          .eq('workspace_id', activeWorkspace.id);
        const total = count ?? 0;
        setEstimatedCount(excludeSet ? Math.max(0, total - excludeSet.size) : total);
      }
    } finally {
      setLoadingCount(false);
    }
  }, [
    audience.type,
    audience.tagIds,
    audience.customField,
    audience.csvContacts,
    audience.excludeTagIds,
    activeWorkspace?.id,
  ]);

  useEffect(() => {
    fetchEstimatedCount();
  }, [fetchEstimatedCount]);

  function toggleTag(tagId: string) {
    const current = audience.tagIds ?? [];
    const updated = current.includes(tagId)
      ? current.filter((id) => id !== tagId)
      : [...current, tagId];
    onUpdate({ ...audience, tagIds: updated });
  }

  function toggleExcludeTag(tagId: string) {
    const current = audience.excludeTagIds ?? [];
    const updated = current.includes(tagId)
      ? current.filter((id) => id !== tagId)
      : [...current, tagId];
    onUpdate({ ...audience, excludeTagIds: updated });
  }

  function updateCustomField(patch: Partial<CustomFieldFilter>) {
    const prev = audience.customField ?? {
      fieldId: '',
      operator: 'is' as CustomFieldOperator,
      value: '',
    };
    onUpdate({ ...audience, customField: { ...prev, ...patch } });
  }

  const isValid =
    audience.type === 'all' ||
    (audience.type === 'tags' && audience.tagIds && audience.tagIds.length > 0) ||
    (audience.type === 'custom_field' &&
      !!audience.customField?.fieldId &&
      audience.customField.value.length > 0) ||
    (audience.type === 'csv' &&
      audience.csvContacts &&
      audience.csvContacts.length > 0);

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-foreground">Select Audience</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Choose who will receive this broadcast.
        </p>
      </div>

      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
        {audienceOptions.map((option) => {
          const isSelected = audience.type === option.type;
          const Icon = option.icon;
          return (
            <button
              key={option.type}
              onClick={() =>
                onUpdate({
                  ...audience,
                  type: option.type,
                  // Wipe shape fields from other types to avoid stale
                  // config leaking across selections.
                  tagIds: option.type === 'tags' ? audience.tagIds : undefined,
                  customField:
                    option.type === 'custom_field'
                      ? audience.customField
                      : undefined,
                  csvContacts:
                    option.type === 'csv' ? audience.csvContacts : undefined,
                })
              }
              className={`flex items-start gap-3 rounded-xl border p-4 text-left transition-all ${
                isSelected
                  ? 'border-primary bg-primary/5 ring-1 ring-violet-500/30'
                  : 'border-border bg-card/50 hover:border-border'
              }`}
            >
              <div
                className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                  isSelected
                    ? 'bg-primary/10 text-primary'
                    : 'bg-muted text-muted-foreground'
                }`}
              >
                <Icon className="h-4 w-4" />
              </div>
              <div>
                <p className="text-sm font-medium text-foreground">{option.label}</p>
                <p className="mt-0.5 text-xs text-muted-foreground">
                  {option.description}
                </p>
              </div>
            </button>
          );
        })}
      </div>

      {audience.type === 'tags' && (
        <div className="rounded-xl border border-border bg-card/50 p-4">
          <p className="mb-3 text-sm font-medium text-foreground">Select Tags</p>
          {loadingTags ? (
            <Loader2 className="h-5 w-5 animate-spin text-primary" />
          ) : tags.length === 0 ? (
            <p className="text-xs text-muted-foreground">
              No tags found. Create tags in Settings.
            </p>
          ) : (
            <div className="flex flex-wrap gap-2">
              {tags.map((tag) => {
                const isSelected = audience.tagIds?.includes(tag.id);
                return (
                  <button
                    key={tag.id}
                    onClick={() => toggleTag(tag.id)}
                    className={`inline-flex items-center rounded-full border px-3 py-1 text-xs font-medium transition-all ${
                      isSelected
                        ? 'border-primary/30 bg-primary/10 text-primary'
                        : 'border-border bg-muted text-foreground hover:border-border'
                    }`}
                  >
                    <span
                      className="mr-1.5 h-2 w-2 rounded-full"
                      style={{ backgroundColor: tag.color }}
                    />
                    {tag.name}
                  </button>
                );
              })}
            </div>
          )}
        </div>
      )}

      {audience.type === 'custom_field' && (
        <div className="space-y-3 rounded-xl border border-border bg-card/50 p-4">
          <p className="text-sm font-medium text-foreground">Custom Field Filter</p>
          {loadingFields ? (
            <Loader2 className="h-5 w-5 animate-spin text-primary" />
          ) : customFields.length === 0 ? (
            <p className="text-xs text-muted-foreground">
              No custom fields defined. Create one in Settings → Custom Fields.
            </p>
          ) : (
            <div className="grid grid-cols-1 gap-2 sm:grid-cols-[minmax(0,1fr)_140px_minmax(0,1fr)]">
              <select
                value={audience.customField?.fieldId ?? ''}
                onChange={(e) => updateCustomField({ fieldId: e.target.value })}
                className="h-9 rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-primary focus:ring-1 focus:ring-violet-500"
              >
                <option value="">Select field…</option>
                {customFields.map((f) => (
                  <option key={f.id} value={f.id}>
                    {f.field_name}
                  </option>
                ))}
              </select>
              <select
                value={audience.customField?.operator ?? 'is'}
                onChange={(e) =>
                  updateCustomField({
                    operator: e.target.value as CustomFieldOperator,
                  })
                }
                className="h-9 rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-primary focus:ring-1 focus:ring-violet-500"
              >
                {OPERATOR_OPTIONS.map((op) => (
                  <option key={op.value} value={op.value}>
                    {op.label}
                  </option>
                ))}
              </select>
              <input
                type="text"
                value={audience.customField?.value ?? ''}
                onChange={(e) => updateCustomField({ value: e.target.value })}
                placeholder="Value"
                className="h-9 rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none placeholder:text-muted-foreground focus:border-primary focus:ring-1 focus:ring-violet-500"
              />
            </div>
          )}
        </div>
      )}

      {audience.type === 'csv' && (
        <div className="space-y-4 rounded-xl border border-border bg-card/50 p-4">
          <p className="text-sm font-medium text-foreground">Upload CSV File</p>
          
          <div
            onClick={() => fileInputRef.current?.click()}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-border p-6 cursor-pointer hover:border-primary/50 transition-colors bg-background/20"
          >
            {audience.csvContacts && audience.csvContacts.length > 0 ? (
              <>
                <Upload className="size-8 text-primary" />
                <p className="text-sm text-foreground">
                  {csvFileName || 'Contacts Loaded Successfully'}
                </p>
                <p className="text-xs text-muted-foreground">
                  {audience.csvContacts.length} recipient{audience.csvContacts.length !== 1 ? 's' : ''} detected
                </p>
              </>
            ) : (
              <>
                <Upload className="size-8 text-muted-foreground" />
                <p className="text-sm text-muted-foreground">Click to upload CSV file</p>
                <p className="text-xs text-muted-foreground">CSV with a &quot;phone&quot; column is required</p>
              </>
            )}
          </div>

          <input
            ref={fileInputRef}
            type="file"
            accept=".csv,text/csv"
            onChange={handleFileChange}
            className="hidden"
          />

          {audience.csvContacts && audience.csvContacts.length > 0 && (
            <div className="space-y-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                Preview (first 5 rows)
              </p>
              <div className="rounded-lg border border-border bg-background/30 overflow-hidden">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="bg-muted/80">
                      <th className="px-3 py-1.5 text-left text-muted-foreground font-medium">Phone</th>
                      <th className="px-3 py-1.5 text-left text-muted-foreground font-medium">Name</th>
                    </tr>
                  </thead>
                  <tbody>
                    {audience.csvContacts.slice(0, 5).map((row, i) => (
                      <tr key={i} className="border-t border-border">
                        <td className="px-3 py-1.5 text-foreground">{row.phone}</td>
                        <td className="px-3 py-1.5 text-foreground">{row.name || '-'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {audience.csvContacts.length > 5 && (
                <div className="flex items-center justify-between">
                  <p className="text-xs text-muted-foreground">
                    ...and {audience.csvContacts.length - 5} more rows
                  </p>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      onUpdate({ ...audience, csvContacts: undefined });
                      setCsvFileName('');
                      if (fileInputRef.current) fileInputRef.current.value = '';
                    }}
                    className="text-xs text-red-400 hover:text-red-300 flex items-center gap-1"
                  >
                    Clear File
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Exclude list — applies regardless of audience type */}
      <div className="rounded-xl border border-border bg-card/50 p-4">
        <div className="mb-3 flex items-center gap-2">
          <X className="h-4 w-4 text-red-400" />
          <p className="text-sm font-medium text-foreground">
            Exclude contacts with these tags
          </p>
          <span className="text-xs text-muted-foreground">(optional)</span>
        </div>
        {tags.length === 0 ? (
          <p className="text-xs text-muted-foreground">No tags available.</p>
        ) : (
          <div className="flex flex-wrap gap-2">
            {tags.map((tag) => {
              const isExcluded = audience.excludeTagIds?.includes(tag.id);
              return (
                <button
                  key={tag.id}
                  onClick={() => toggleExcludeTag(tag.id)}
                  className={`inline-flex items-center rounded-full border px-3 py-1 text-xs font-medium transition-all ${
                    isExcluded
                      ? 'border-red-500/30 bg-red-500/10 text-red-300'
                      : 'border-border bg-muted text-foreground hover:border-border'
                  }`}
                >
                  <span
                    className="mr-1.5 h-2 w-2 rounded-full"
                    style={{ backgroundColor: tag.color }}
                  />
                  {tag.name}
                </button>
              );
            })}
          </div>
        )}
      </div>

      {/* Audience Summary */}
      <div className="rounded-xl border border-border bg-card/50 p-4">
        <p className="mb-2 text-sm font-medium text-foreground">Audience Summary</p>
        {loadingCount ? (
          <div className="flex items-center gap-2">
            <Loader2 className="h-4 w-4 animate-spin text-primary" />
            <span className="text-xs text-muted-foreground">Calculating…</span>
          </div>
        ) : estimatedCount !== null ? (
          <div className="flex items-center gap-2">
            <Users className="h-4 w-4 text-primary" />
            <span className="text-sm text-foreground">
              {estimatedCount.toLocaleString()}
            </span>
            <span className="text-xs text-muted-foreground">estimated recipients</span>
          </div>
        ) : (
          <p className="text-xs text-muted-foreground">
            Select an audience type to see the estimate.
          </p>
        )}
      </div>

      <div className="flex items-center justify-between border-t border-border pt-4">
        <IconAction label="Back" icon={<ArrowLeft className="h-4 w-4" />} variant="outline"
          onClick={onBack}
          className="border-border text-foreground" />
        <IconAction label="Next" icon={<ArrowRight className="h-4 w-4" />} onClick={onNext}
          disabled={!isValid}
          className="bg-primary text-primary-foreground hover:bg-primary disabled:opacity-50" />
      </div>
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Contact, CustomField, MessageTemplate } from '@/types';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ArrowLeft, ArrowRight, Eye, Loader2 } from 'lucide-react';

import { useWorkspace } from '@/hooks/use-workspace';
import { IconAction } from "@/components/ui/icon-action";

type VariableType = 'static' | 'field' | 'custom_field';

interface VariableMapping {
  type: VariableType;
  value: string;
}

interface Step3Props {
  template: MessageTemplate;
  variables: Record<string, VariableMapping>;
  onUpdate: (variables: Record<string, VariableMapping>) => void;
  onNext: () => void;
  onBack: () => void;
}

const contactFields = [
  { value: 'name', label: 'Contact Name' },
  { value: 'phone', label: 'Phone Number' },
  { value: 'email', label: 'Email Address' },
  { value: 'company', label: 'Company' },
];

const SAMPLE_CONTACT: Contact = {
  id: 'sample',
  user_id: '',
  account_id: '',
  name: 'John Doe',
  phone: '+1234567890',
  email: 'john@example.com',
  company: 'Acme Corp',
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString(),
};

export function Step3Personalize({
  template,
  variables,
  onUpdate,
  onNext,
  onBack,
}: Step3Props) {
  const { activeWorkspace } = useWorkspace();
  const [customFields, setCustomFields] = useState<CustomField[]>([]);
  const [loadingFields, setLoadingFields] = useState(true);
  const [firstContact, setFirstContact] = useState<Contact | null>(null);
  const [firstContactCustomValues, setFirstContactCustomValues] = useState<
    Map<string, string>
  >(new Map());
  const [loadingPreview, setLoadingPreview] = useState(true);

  // Load user's custom fields + a representative contact for the
  // live preview. Fall back to sample data if no contacts exist yet.
  useEffect(() => {
    if (!activeWorkspace?.id) return;

    let cancelled = false;
    (async () => {
      const supabase = createClient();
      const [fieldsRes, contactRes] = await Promise.all([
        supabase
          .from('custom_fields')
          .select('*')
          .eq('workspace_id', activeWorkspace.id)
          .order('field_name'),
        supabase
          .from('contacts')
          .select('*')
          .eq('workspace_id', activeWorkspace.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle(),
      ]);
      if (cancelled) return;

      setCustomFields(fieldsRes.data ?? []);
      setLoadingFields(false);

      const contact = contactRes.data ?? null;
      setFirstContact(contact);

      if (contact) {
        const { data: customVals } = await supabase
          .from('contact_custom_values')
          .select('custom_field_id, value')
          .eq('contact_id', contact.id);
        if (!cancelled) {
          const map = new Map<string, string>();
          for (const row of customVals ?? []) {
            map.set(row.custom_field_id, row.value ?? '');
          }
          setFirstContactCustomValues(map);
        }
      }
      setLoadingPreview(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [activeWorkspace?.id]);

  const placeholders = useMemo(() => {
    const matches = template.body_text.match(/\{\{(\d+)\}\}/g);
    if (!matches) return [];
    return [...new Set(matches)].sort();
  }, [template.body_text]);

  /**
   * A placeholder is "unmapped" if the user hasn't picked either a
   * static value or a field/custom-field source. Blocks Next until
   * every placeholder has something — otherwise the broadcast would
   * ship with empty strings and confuse recipients.
   */
  const unmappedKeys = useMemo(() => {
    const missing: string[] = [];
    for (const placeholder of placeholders) {
      const key = placeholder.replace(/^\{\{|\}\}$/g, '');
      const mapping = variables[key];
      if (!mapping || !mapping.value?.trim()) {
        missing.push(placeholder);
      }
    }
    return missing;
  }, [placeholders, variables]);

  function updateVariable(key: string, patch: Partial<VariableMapping>) {
    const current = variables[key] ?? { type: 'static' as VariableType, value: '' };
    onUpdate({
      ...variables,
      [key]: { ...current, ...patch },
    });
  }

  /**
   * Substitute placeholders using the first real contact where
   * possible. Placeholders keyed by "{{N}}" map to variable key "N".
   */
  const previewText = useMemo(() => {
    const contact = firstContact ?? SAMPLE_CONTACT;
    const customValues = firstContact
      ? firstContactCustomValues
      : new Map<string, string>();

    let text = template.body_text;
    for (const placeholder of placeholders) {
      const key = placeholder.replace(/^\{\{|\}\}$/g, '');
      const mapping = variables[key];
      let replacement = placeholder;

      if (mapping) {
        if (mapping.type === 'static' && mapping.value) {
          replacement = mapping.value;
        } else if (mapping.type === 'field' && mapping.value) {
          const fieldMap: Record<string, string | undefined> = {
            name: contact.name,
            phone: contact.phone,
            email: contact.email,
            company: contact.company,
          };
          replacement = fieldMap[mapping.value] ?? placeholder;
        } else if (mapping.type === 'custom_field' && mapping.value) {
          replacement = customValues.get(mapping.value) || placeholder;
        }
      }
      text = text.replaceAll(placeholder, replacement);
    }
    return text;
  }, [
    template.body_text,
    variables,
    placeholders,
    firstContact,
    firstContactCustomValues,
  ]);

  const previewLabel = firstContact
    ? firstContact.name || firstContact.phone
    : 'sample data';

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-foreground">Personalize Message</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Map template variables to contact fields, custom fields, or static
          values.
        </p>
      </div>

      {placeholders.length === 0 ? (
        <div className="rounded-xl border border-border bg-card/50 p-6 text-center">
          <p className="text-sm text-muted-foreground">
            This template has no variables to personalize.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {placeholders.map((placeholder) => {
            const key = placeholder.replace(/^\{\{|\}\}$/g, '');
            const mapping = variables[key] ?? { type: 'static', value: '' };

            return (
              <div
                key={placeholder}
                className="rounded-xl border border-border bg-card/50 p-4"
              >
                <div className="mb-3 flex items-center gap-2">
                  <span className="inline-flex items-center rounded-md bg-primary/10 px-2 py-0.5 text-xs font-mono font-medium text-primary">
                    {placeholder}
                  </span>
                </div>

                <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                  <div>
                    <label className="mb-1.5 block text-xs font-medium text-muted-foreground">
                      Mapping Type
                    </label>
                    <Select
                      value={mapping.type}
                      onValueChange={(val) =>
                        updateVariable(key, {
                          type: val as VariableType,
                          value: '',
                        })
                      }
                    >
                      <SelectTrigger className="w-full border-border bg-muted text-foreground">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="border-border bg-muted">
                        <SelectItem value="static">Static Value</SelectItem>
                        <SelectItem value="field">Contact Field</SelectItem>
                        <SelectItem value="custom_field">
                          Custom Field
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <label className="mb-1.5 block text-xs font-medium text-muted-foreground">
                      {mapping.type === 'static' ? 'Value' : 'Field'}
                    </label>
                    {mapping.type === 'static' ? (
                      <Input
                        value={mapping.value}
                        onChange={(e) =>
                          updateVariable(key, { value: e.target.value })
                        }
                        placeholder="Enter value..."
                        className="border-border bg-muted text-foreground placeholder:text-muted-foreground"
                      />
                    ) : mapping.type === 'field' ? (
                      <Select
                        value={mapping.value || undefined}
                        onValueChange={(val) =>
                          updateVariable(key, { value: val || '' })
                        }
                      >
                        <SelectTrigger className="w-full border-border bg-muted text-foreground">
                          <SelectValue placeholder="Select field..." />
                        </SelectTrigger>
                        <SelectContent className="border-border bg-muted">
                          {contactFields.map((field) => (
                            <SelectItem key={field.value} value={field.value}>
                              {field.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : (
                      <Select
                        value={mapping.value || undefined}
                        onValueChange={(val) =>
                          updateVariable(key, { value: val || '' })
                        }
                      >
                        <SelectTrigger className="w-full border-border bg-muted text-foreground">
                          <SelectValue
                            placeholder={
                              loadingFields
                                ? 'Loading…'
                                : customFields.length === 0
                                  ? 'No custom fields'
                                  : 'Select custom field…'
                            }
                          />
                        </SelectTrigger>
                        <SelectContent className="border-border bg-muted">
                          {customFields.map((f) => (
                            <SelectItem key={f.id} value={f.id}>
                              {f.field_name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Live Preview — rendered as a WhatsApp-style bubble so the user
          sees approximately what the recipient will see. */}
      <div className="rounded-xl border border-border bg-card/50 p-4">
        <div className="mb-3 flex items-center gap-2">
          <Eye className="h-4 w-4 text-primary" />
          <p className="text-sm font-medium text-foreground">Live Preview</p>
          <span className="text-xs text-muted-foreground">({previewLabel})</span>
          {loadingPreview && (
            <Loader2 className="h-3.5 w-3.5 animate-spin text-primary" />
          )}
        </div>
        <div className="rounded-lg bg-[#0e1a12] p-3">
          <div className="ml-auto max-w-[85%] rounded-lg bg-primary/30 px-3 py-2 shadow-sm">
            <p className="whitespace-pre-wrap text-sm text-foreground">
              {previewText}
            </p>
          </div>
        </div>
      </div>

      {unmappedKeys.length > 0 && (
        <div className="rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
          Map every placeholder before continuing — still missing{' '}
          <span className="font-mono font-semibold">
            {unmappedKeys.join(', ')}
          </span>
          . Otherwise those placeholders will ship to Meta as empty strings.
        </div>
      )}

      <div className="flex items-center justify-between border-t border-border pt-4">
        <IconAction label="Back" icon={<ArrowLeft className="h-4 w-4" />} variant="outline"
          onClick={onBack}
          className="border-border text-foreground" />
        <IconAction label="Next" icon={<ArrowRight className="h-4 w-4" />} onClick={onNext}
          disabled={unmappedKeys.length > 0}
          className="bg-primary text-primary-foreground hover:bg-primary disabled:opacity-50" />
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Printer, X, Barcode as BarcodeIcon } from "lucide-react";
import { toast } from "sonner";
import { sanitizeErrorMessage } from "@/lib/commerce/barcode-utils";
import { IconAction } from "@/components/ui/icon-action";

interface Product {
  id: string;
  name: string;
  sku: string;
  barcode?: string;
  selling_price: number;
  mrp?: number;
  unit?: string;
  category?: { name: string };
  attributes?: Record<string, any>;
}

interface BarcodeTagModalProps {
  isOpen: boolean;
  onClose: () => void;
  product: Product | null;
  workspaceName?: string;
}

export function BarcodeTagModal({
  isOpen,
  onClose,
  product,
  workspaceName = "Daily CRM Store",
}: BarcodeTagModalProps) {
  const [printCopies] = useState(1);
  const [tagWidth, setTagWidth] = useState(50); // mm
  const [tagHeight, setTagHeight] = useState(30); // mm (Optimized for 32px barcode height)

  if (!isOpen || !product) return null;

  const displayBarcode = product.barcode || product.sku;
  const price = Number(product.selling_price || 0).toFixed(2);
  const mrpPrice = Number(product.mrp || product.selling_price || 0).toFixed(2);

  const handlePrint = () => {
    try {
      window.print();
      toast.success(`Printing ${printCopies} Barcode Tag(s)`);
    } catch (e: any) {
      const msg = sanitizeErrorMessage(e, "Failed to print barcode tag");
      toast.error(msg);
    }
  };

  return (
    <>
      {/* Scoped @media print CSS */}
      <style
        dangerouslySetInnerHTML={{
          __html: `
            @media print {
              body > *:not(.tag-print-modal-container) {
                display: none !important;
              }
              .tag-print-modal-container {
                display: block !important;
                position: absolute !important;
                top: 0; left: 0; width: 100%;
                background: #ffffff !important;
                color: #000000 !important;
              }
              @page {
                margin: 0;
                size: ${tagWidth}mm ${tagHeight}mm;
              }
            }
          `,
        }}
      />

      <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4">
        <div className="bg-card border border-border rounded-3xl max-w-md w-full p-6 space-y-5 shadow-2xl text-foreground">
          <div className="flex items-center justify-between border-b border-border pb-3">
            <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
              <BarcodeIcon className="h-5 w-5 text-[#00aef0]" />
              Barcode Tag Generator (32px High-Precision Scan)
            </h2>
            <button
              onClick={onClose}
              className="text-muted-foreground hover:text-foreground transition-colors"
            >
              <X className="h-5 w-5" />
            </button>
          </div>

          {/* Printable Tag Container */}
          <div className="flex justify-center p-4 bg-background border border-border rounded-2xl">
            <div
              className="tag-print-modal-container bg-white text-black p-3 rounded-lg border border-border shadow-md flex flex-col justify-between items-center text-center select-none"
              style={{
                width: `${tagWidth * 5}px`,
                height: `${tagHeight * 6}px`,
              }}
            >
              <div className="text-[10px] font-extrabold tracking-wider uppercase border-b border-black/20 pb-0.5 w-full truncate">
                {workspaceName}
              </div>

              <div className="my-1">
                <div className="text-xs font-bold leading-tight truncate max-w-[200px]">
                  {product.name}
                </div>
                <div className="text-[9px] text-gray-600 font-mono mt-0.5">
                  SKU: {product.sku}
                </div>
              </div>

              {/* 32px Standard Scanner Barcode Container with Quiet Zones */}
              <div className="w-full flex flex-col items-center my-1">
                {/* 32px Height High-Contrast Barcode Bars */}
                <div className="flex items-center justify-center h-[32px] gap-[1.5px] bg-black p-1 w-full max-w-[190px] rounded-sm">
                  {/* Quiet Zone Left */}
                  <div className="bg-white h-full w-[4px]" />
                  {/* Barcode Bars */}
                  <div className="bg-white h-full w-[2px]" />
                  <div className="bg-black h-full w-[1px]" />
                  <div className="bg-white h-full w-[3px]" />
                  <div className="bg-black h-full w-[1px]" />
                  <div className="bg-white h-full w-[2px]" />
                  <div className="bg-black h-full w-[2px]" />
                  <div className="bg-white h-full w-[4px]" />
                  <div className="bg-black h-full w-[1px]" />
                  <div className="bg-white h-full w-[3px]" />
                  <div className="bg-black h-full w-[2px]" />
                  <div className="bg-white h-full w-[2px]" />
                  {/* Quiet Zone Right */}
                  <div className="bg-white h-full w-[4px]" />
                </div>
                <span className="text-[10px] font-mono font-bold tracking-widest text-black mt-1">
                  {displayBarcode}
                </span>
              </div>

              <div className="w-full flex items-center justify-between border-t border-black/20 pt-1 text-[11px]">
                {mrpPrice !== price && (
                  <span className="line-through text-gray-500 text-[10px]">
                    MRP: ₹{mrpPrice}
                  </span>
                )}
                <span className="font-extrabold text-black text-sm">
                  Price: ₹{price}
                </span>
              </div>
            </div>
          </div>

          {/* Configuration controls */}
          <div className="grid grid-cols-2 gap-3 text-xs">
            <div className="space-y-1">
              <label className="text-muted-foreground">Tag Width (mm)</label>
              <input
                type="number"
                value={tagWidth}
                onChange={(e) => setTagWidth(Number(e.target.value))}
                className="w-full bg-background border border-border text-foreground rounded-lg px-2.5 py-1.5 font-mono"
              />
            </div>
            <div className="space-y-1">
              <label className="text-muted-foreground">Tag Height (mm)</label>
              <input
                type="number"
                value={tagHeight}
                onChange={(e) => setTagHeight(Number(e.target.value))}
                className="w-full bg-background border border-border text-foreground rounded-lg px-2.5 py-1.5 font-mono"
              />
            </div>
          </div>

          {/* Actions */}
          <div className="flex items-center justify-between pt-2 border-t border-border">
            <Button
              variant="outline"
              onClick={onClose}
              className="border-border text-foreground rounded-xl text-xs"
            >
              Close
            </Button>
            <IconAction label="Print 32px Barcode Tag" icon={<Printer className="h-4 w-4" />} onClick={handlePrint}
              className="bg-[#00aef0] hover:bg-[#0284c7] text-foreground font-bold rounded-xl gap-2 text-xs" />
          </div>
        </div>
      </div>
    </>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { Search, Barcode, Check, ChevronDown, Package } from "lucide-react";
import { Input } from "@/components/ui/input";

interface ProductComboboxProps {
  products: any[];
  selectedProductId: string;
  onSelect: (product: any | null) => void;
  placeholder?: string;
}

export function ProductCombobox({
  products,
  selectedProductId,
  onSelect,
  placeholder = "Type name, SKU, or scan barcode...",
}: ProductComboboxProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);

  const selectedProduct = products.find((p) => p.id === selectedProductId);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const filtered = products.filter((p) => {
    const q = query.toLowerCase();
    return (
      p.name?.toLowerCase().includes(q) ||
      p.sku?.toLowerCase().includes(q) ||
      (p.barcode && p.barcode.toLowerCase().includes(q))
    );
  });

  return (
    <div ref={containerRef} className="relative w-full">
      {/* Input / Display */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
        <Input
          type="text"
          value={
            isOpen
              ? query
              : selectedProduct
              ? `${selectedProduct.name} (${selectedProduct.sku})`
              : query
          }
          onChange={(e) => {
            setQuery(e.target.value);
            if (!isOpen) setIsOpen(true);
          }}
          onFocus={() => {
            setIsOpen(true);
            setQuery("");
          }}
          placeholder={placeholder}
          className="pl-9 pr-8 h-10 bg-background border-border text-foreground rounded-xl text-xs font-semibold focus:border-[#00aef0] focus:ring-1 focus:ring-[#00aef0]"
        />
        <button
          type="button"
          onClick={() => setIsOpen((prev) => !prev)}
          className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
        >
          <ChevronDown className="h-4 w-4" />
        </button>
      </div>

      {/* Dropdown Menu */}
      {isOpen && (
        <div className="absolute z-[100] left-0 mt-1 min-w-[320px] sm:min-w-[380px] w-full max-h-64 overflow-y-auto overflow-x-hidden bg-background border border-border rounded-2xl shadow-2xl divide-y divide-border text-xs [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
          {filtered.length === 0 ? (
            <div className="p-4 text-center text-muted-foreground text-xs">
              No products found matching &quot;{query}&quot;
            </div>
          ) : (
            filtered.map((p) => {
              const isSelected = p.id === selectedProductId;
              return (
                <div
                  key={p.id}
                  onClick={() => {
                    onSelect(p);
                    setIsOpen(false);
                    setQuery("");
                  }}
                  className={`p-3 hover:bg-muted/90 cursor-pointer flex items-center justify-between gap-3 transition-colors ${
                    isSelected ? "bg-muted/80 border-l-4 border-l-[#00aef0]" : ""
                  }`}
                >
                  <div className="space-y-1 min-w-0 flex-1">
                    <div className="font-extrabold text-foreground text-sm flex items-center gap-1.5 truncate">
                      <Package className="h-4 w-4 text-[#00aef0] shrink-0" />
                      <span className="truncate text-foreground">{p.name}</span>
                    </div>
                    <div className="text-[11px] text-foreground flex items-center gap-2 flex-wrap">
                      <span className="font-mono bg-card px-1.5 py-0.5 rounded-none text-foreground border border-border">
                        SKU: {p.sku}
                      </span>
                      {p.barcode && (
                        <span className="text-[#00aef0] font-mono flex items-center gap-1 bg-[#00aef0]/10 px-1.5 py-0.5 rounded-none border border-[#00aef0]/20">
                          <Barcode className="h-3 w-3" /> {p.barcode}
                        </span>
                      )}
                      <span className="text-muted-foreground">Unit: {p.unit || "Pcs"}</span>
                    </div>
                  </div>
                  <div className="text-right shrink-0">
                    <div className="font-extrabold text-emerald-400 text-sm">
                      ₹{Number(p.selling_price || p.purchase_price || 0).toFixed(2)}
                    </div>
                    {isSelected && <Check className="h-4 w-4 text-[#00aef0] ml-auto mt-0.5" />}
                  </div>
                </div>
              );
            })
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Package,
  X,
  Printer,
  Tag,
  Barcode as BarcodeIcon,
  ShieldCheck,
  Banknote,
  Warehouse,
  Sliders,
  Sparkles,
  Info,
  CheckCircle2,
  XCircle,
  Hash,
  Layers,
  MapPin,
  FileText,
  Calendar,
  Percent,
  Edit3 as Pencil,
} from "lucide-react";
import { IconAction } from "@/components/ui/icon-action";

export interface ProductDetails {
  id: string;
  name: string;
  sku: string;
  barcode?: string;
  alias_name?: string;
  manufacturer_name?: string;
  department_name?: string;
  brand_name?: string;
  category_name?: string;
  sub_category_name?: string;
  preferred_supplier?: string;
  product_status?: string;
  hsn_sac_code?: string;
  base_unit?: string;
  purchase_unit?: string;
  unit_conversion_factor?: number;
  purchase_price?: number;
  selling_price: number;
  wholesale_rate?: number;
  distributor_rate?: number;
  online_rate?: number;
  mrp?: number;
  min_selling_price?: number;
  tax_rate?: number;
  cess_rate?: number;
  is_tax_inclusive?: boolean;
  initial_stock?: number;
  reorder_level?: number;
  reorder_quantity?: number;
  min_stock_level?: number;
  max_stock_level?: number;
  shelf_number?: string;
  bin_location?: string;
  allow_negative_stock?: boolean;
  track_batch?: boolean;
  track_serial?: boolean;
  track_expiry?: boolean;
  attributes?: Record<string, any>;
  category?: { name: string };
  created_at?: string;
}

interface ProductDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  product: ProductDetails | null;
  onPrintTag?: (product: ProductDetails) => void;
  onEdit?: (product: ProductDetails) => void;
}

export function ProductDetailsModal({
  isOpen,
  onClose,
  product,
  onPrintTag,
  onEdit,
}: ProductDetailsModalProps) {
  const [activeTab, setActiveTab] = useState<
    "OVERVIEW" | "PRICING" | "STOCK" | "TAX" | "ATTRIBUTES"
  >("OVERVIEW");

  if (!isOpen || !product) return null;

  const sellingPrice = Number(product.selling_price || 0);
  const purchasePrice = Number(product.purchase_price || 0);
  const mrp = Number(product.mrp || sellingPrice);
  const marginAmt = sellingPrice - purchasePrice;
  const marginPct = sellingPrice > 0 ? (marginAmt / sellingPrice) * 100 : 0;
  const markupPct = purchasePrice > 0 ? (marginAmt / purchasePrice) * 100 : 0;

  const attributes = product.attributes || {};
  const industryTemplate = attributes.industry_template || "DEFAULT";

  // Filter out internal attributes if any
  const customUserFields = attributes.custom_user_fields || {};
  const attributeEntries = Object.entries(attributes).filter(
    ([key]) => key !== "industry_template" && key !== "custom_user_fields"
  );

  return (
    <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-md flex items-center justify-center p-4 overflow-y-auto">
      <div className="bg-card border border-border rounded-3xl max-w-3xl w-full p-6 space-y-6 shadow-2xl my-8 text-foreground relative">
        {/* Header */}
        <div className="flex items-start justify-between border-b border-border pb-4 gap-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="bg-[#00aef0]/10 text-[#00aef0] px-2.5 py-0.5 rounded-lg text-xs font-bold uppercase tracking-wider flex items-center gap-1">
                <Package className="h-3.5 w-3.5" /> Product Details
              </span>
              {industryTemplate !== "DEFAULT" && (
                <span className="bg-purple-500/10 text-purple-400 border border-purple-500/20 px-2.5 py-0.5 rounded-lg text-xs font-bold flex items-center gap-1">
                  <Sparkles className="h-3 w-3" /> Template: {industryTemplate}
                </span>
              )}
              <span
                className={`px-2.5 py-0.5 rounded-lg text-xs font-bold flex items-center gap-1 ${
                  product.product_status === "INACTIVE"
                    ? "bg-rose-500/10 text-rose-400 border border-rose-500/20"
                    : "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                }`}
              >
                {product.product_status || "ACTIVE"}
              </span>
            </div>

            <h2 className="text-lg font-semibold text-foreground tracking-tight mt-1">
              {product.name}
            </h2>

            <div className="flex items-center gap-4 text-xs text-muted-foreground flex-wrap font-mono pt-1">
              <span className="flex items-center gap-1">
                <Hash className="h-3.5 w-3.5 text-muted-foreground" /> SKU:{" "}
                <strong className="text-foreground">{product.sku}</strong>
              </span>
              {product.barcode && (
                <span className="flex items-center gap-1 text-[#00aef0]">
                  <BarcodeIcon className="h-3.5 w-3.5" /> Barcode:{" "}
                  <strong className="text-[#00aef0]">{product.barcode}</strong>
                </span>
              )}
              {product.hsn_sac_code && (
                <span className="flex items-center gap-1">
                  <Tag className="h-3.5 w-3.5 text-muted-foreground" /> HSN/SAC:{" "}
                  <strong className="text-foreground">{product.hsn_sac_code}</strong>
                </span>
              )}
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-2 text-muted-foreground hover:text-foreground hover:bg-muted rounded-xl transition-colors"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Quick Highlights Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          <div className="bg-background/80 p-3.5 rounded-2xl border border-border space-y-1">
            <span className="text-[11px] text-muted-foreground font-semibold uppercase tracking-wider block">
              Selling Price
            </span>
            <span className="text-xl font-extrabold text-[#00aef0] block">
              ₹{sellingPrice.toFixed(2)}
            </span>
            {mrp > sellingPrice && (
              <span className="text-[11px] text-muted-foreground line-through block">
                MRP: ₹{mrp.toFixed(2)}
              </span>
            )}
          </div>

          <div className="bg-background/80 p-3.5 rounded-2xl border border-border space-y-1">
            <span className="text-[11px] text-muted-foreground font-semibold uppercase tracking-wider block">
              Purchase Price
            </span>
            <span className="text-xl font-extrabold text-foreground block">
              ₹{purchasePrice.toFixed(2)}
            </span>
            {marginPct > 0 && (
              <span className="text-[11px] text-emerald-400 font-medium block">
                +{marginPct.toFixed(1)}% Margin
              </span>
            )}
          </div>

          <div className="bg-background/80 p-3.5 rounded-2xl border border-border space-y-1">
            <span className="text-[11px] text-muted-foreground font-semibold uppercase tracking-wider block">
              GST Tax Rate
            </span>
            <span className="text-xl font-extrabold text-purple-400 block">
              {product.tax_rate || 0}%
            </span>
            <span className="text-[11px] text-muted-foreground block">
              {product.is_tax_inclusive ? "Tax Inclusive" : "Tax Exclusive"}
            </span>
          </div>

          <div className="bg-background/80 p-3.5 rounded-2xl border border-border space-y-1">
            <span className="text-[11px] text-muted-foreground font-semibold uppercase tracking-wider block">
              Stock & Unit
            </span>
            <span className="text-xl font-extrabold text-amber-400 block">
              {product.initial_stock || 0} {product.base_unit || "PCS"}
            </span>
            <span className="text-[11px] text-muted-foreground block">
              Min Reorder: {product.reorder_level || 10}
            </span>
          </div>
        </div>

        {/* Tab Navigation Header */}
        <div className="flex items-center gap-1.5 border-b border-border pb-2 overflow-x-auto">
          {[
            { id: "OVERVIEW", label: "Overview & Master", icon: Info },
            { id: "PRICING", label: "Pricing & Rates", icon: Banknote },
            { id: "STOCK", label: "Inventory & Location", icon: Warehouse },
            { id: "TAX", label: "GST & Statutory", icon: ShieldCheck },
            { id: "ATTRIBUTES", label: "Attributes & Custom Fields", icon: Sliders },
          ].map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`px-3 py-2 text-xs font-bold rounded-xl flex items-center gap-1.5 transition-all whitespace-nowrap ${
                  activeTab === tab.id
                    ? "bg-[#00aef0] text-foreground shadow-lg shadow-[#00aef0]/20"
                    : "text-muted-foreground hover:text-foreground hover:bg-muted/60"
                }`}
              >
                <Icon className="h-3.5 w-3.5" />
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* Tab Contents */}
        <div className="min-h-[220px] max-h-[360px] overflow-y-auto pr-1 space-y-4">
          {/* TAB 1: OVERVIEW */}
          {activeTab === "OVERVIEW" && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <DetailCard label="Product Title" value={product.name} />
              <DetailCard label="SKU Code" value={product.sku} isMono />
              <DetailCard label="Barcode EAN/UPC" value={product.barcode || "N/A"} isMono />
              <DetailCard label="Alias / Alternate Name" value={product.alias_name || "N/A"} />
              <DetailCard label="Category" value={product.category_name || product.category?.name || "N/A"} />
              <DetailCard label="Sub Category" value={product.sub_category_name || "N/A"} />
              <DetailCard label="Brand" value={product.brand_name || "N/A"} />
              <DetailCard label="Manufacturer" value={product.manufacturer_name || "N/A"} />
              <DetailCard label="Department" value={product.department_name || "N/A"} />
              <DetailCard label="Preferred Supplier" value={product.preferred_supplier || "N/A"} />
            </div>
          )}

          {/* TAB 2: PRICING */}
          {activeTab === "PRICING" && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <DetailCard label="Selling Price" value={`₹${sellingPrice.toFixed(2)}`} highlight />
                <DetailCard label="Purchase Price" value={`₹${purchasePrice.toFixed(2)}`} />
                <DetailCard label="Maximum Retail Price (MRP)" value={`₹${mrp.toFixed(2)}`} />
                <DetailCard label="Wholesale Rate" value={product.wholesale_rate ? `₹${Number(product.wholesale_rate).toFixed(2)}` : "N/A"} />
                <DetailCard label="Distributor Rate" value={product.distributor_rate ? `₹${Number(product.distributor_rate).toFixed(2)}` : "N/A"} />
                <DetailCard label="Online Rate" value={product.online_rate ? `₹${Number(product.online_rate).toFixed(2)}` : "N/A"} />
                <DetailCard label="Minimum Selling Price" value={product.min_selling_price ? `₹${Number(product.min_selling_price).toFixed(2)}` : "N/A"} />
              </div>

              {/* Profitability Analysis Box */}
              <div className="bg-background p-4 rounded-2xl border border-border space-y-2">
                <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1.5">
                  <Percent className="h-4 w-4 text-[#00aef0]" /> Profitability Analysis
                </h4>
                <div className="grid grid-cols-3 gap-2 text-xs">
                  <div>
                    <span className="text-muted-foreground block">Profit per Unit</span>
                    <span className="font-extrabold text-emerald-400 text-sm">
                      ₹{marginAmt.toFixed(2)}
                    </span>
                  </div>
                  <div>
                    <span className="text-muted-foreground block">Gross Margin %</span>
                    <span className="font-extrabold text-emerald-400 text-sm">
                      {marginPct.toFixed(2)}%
                    </span>
                  </div>
                  <div>
                    <span className="text-muted-foreground block">Markup %</span>
                    <span className="font-extrabold text-purple-400 text-sm">
                      {markupPct.toFixed(2)}%
                    </span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* TAB 3: STOCK & WAREHOUSE */}
          {activeTab === "STOCK" && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <DetailCard label="Base Unit" value={product.base_unit || "PCS"} />
                <DetailCard label="Purchase Unit" value={product.purchase_unit || "BOX"} />
                <DetailCard
                  label="Unit Conversion Factor"
                  value={`1 ${product.purchase_unit || "BOX"} = ${product.unit_conversion_factor || 1} ${product.base_unit || "PCS"}`}
                />
                <DetailCard label="Initial Opening Stock" value={`${product.initial_stock || 0} ${product.base_unit || "PCS"}`} />
                <DetailCard label="Reorder Level" value={`${product.reorder_level || 10} ${product.base_unit || "PCS"}`} />
                <DetailCard label="Reorder Quantity" value={`${product.reorder_quantity || 50} ${product.base_unit || "PCS"}`} />
                <DetailCard label="Min Stock Level" value={`${product.min_stock_level || 5} ${product.base_unit || "PCS"}`} />
                <DetailCard label="Max Stock Level" value={`${product.max_stock_level || 1000} ${product.base_unit || "PCS"}`} />
                <DetailCard label="Shelf Location" value={product.shelf_number || "Unassigned"} />
                <DetailCard label="Bin Location" value={product.bin_location || "Unassigned"} />
              </div>

              {/* Tracking Flags Status */}
              <div className="bg-background p-4 rounded-2xl border border-border space-y-3">
                <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
                  Tracking & Inventory Rules
                </h4>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                  <FlagBadge label="Batch Tracking" active={!!product.track_batch} />
                  <FlagBadge label="Serial Tracking" active={!!product.track_serial} />
                  <FlagBadge label="Expiry Tracking" active={!!product.track_expiry} />
                  <FlagBadge label="Allow Negative Stock" active={!!product.allow_negative_stock} />
                </div>
              </div>
            </div>
          )}

          {/* TAB 4: GST & STATUTORY */}
          {activeTab === "TAX" && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <DetailCard label="HSN / SAC Code" value={product.hsn_sac_code || "6203"} isMono />
              <DetailCard label="GST Rate" value={`${product.tax_rate || 0}%`} />
              <DetailCard label="Cess Rate" value={`${product.cess_rate || 0}%`} />
              <DetailCard label="Tax Application" value={product.is_tax_inclusive ? "Tax Inclusive (Price includes GST)" : "Tax Exclusive (GST added at billing)"} />
            </div>
          )}

          {/* TAB 5: ATTRIBUTES & CUSTOM FIELDS */}
          {activeTab === "ATTRIBUTES" && (
            <div className="space-y-4">
              {attributeEntries.length > 0 ? (
                <div className="bg-background p-4 rounded-2xl border border-border space-y-3">
                  <h4 className="text-xs font-bold uppercase tracking-wider text-[#00aef0] flex items-center gap-1.5">
                    <Sparkles className="h-4 w-4" /> {industryTemplate} Industry Attributes
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
                    {attributeEntries.map(([k, v]) => (
                      <div key={k} className="bg-card/90 p-2.5 rounded-xl border border-border">
                        <span className="text-muted-foreground capitalize block text-[11px]">
                          {k.replace(/_/g, " ")}
                        </span>
                        <span className="font-semibold text-foreground block mt-0.5">
                          {typeof v === "boolean" ? (v ? "Yes" : "No") : String(v || "N/A")}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              ) : null}

              {Object.keys(customUserFields).length > 0 && (
                <div className="bg-background p-4 rounded-2xl border border-border space-y-3">
                  <h4 className="text-xs font-bold uppercase tracking-wider text-purple-400 flex items-center gap-1.5">
                    <Layers className="h-4 w-4" /> Custom Fields
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
                    {Object.entries(customUserFields).map(([k, v]) => (
                      <div key={k} className="bg-card/90 p-2.5 rounded-xl border border-border">
                        <span className="text-muted-foreground block text-[11px]">{k}</span>
                        <span className="font-semibold text-foreground block mt-0.5">
                          {String(v || "N/A")}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {attributeEntries.length === 0 && Object.keys(customUserFields).length === 0 && (
                <div className="py-8 text-center text-muted-foreground text-xs">
                  No additional industry attributes or custom fields configured for this product.
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-border pt-4">
          <div className="text-[11px] text-muted-foreground">
            Created: {product.created_at ? new Date(product.created_at).toLocaleDateString() : "Catalog Item"}
          </div>
          <div className="flex items-center gap-2">
            {onEdit && (
              <IconAction label="Edit Product" icon={<Pencil className="h-4 w-4" />} variant="outline"
                onClick={() => {
                  onClose();
                  onEdit(product);
                }}
                className="border-border hover:border-[#00aef0] bg-[#00aef0]/10 hover:bg-[#00aef0]/20 text-[#00aef0] gap-2 rounded-xl text-xs h-10 font-bold" />
            )}
            {onPrintTag && (
              <IconAction label="Print Barcode Tag" icon={<Printer className="h-4 w-4" />} variant="outline"
                onClick={() => {
                  onClose();
                  onPrintTag(product);
                }}
                className="border-border hover:border-[#00aef0] text-foreground hover:text-[#00aef0] gap-2 rounded-xl text-xs h-10" />
            )}
            <Button
              onClick={onClose}
              className="bg-muted hover:bg-muted text-foreground font-bold rounded-xl text-xs h-10 px-5"
            >
              Close
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

function DetailCard({
  label,
  value,
  isMono = false,
  highlight = false,
}: {
  label: string;
  value: string | number;
  isMono?: boolean;
  highlight?: boolean;
}) {
  return (
    <div className="bg-background/80 p-3 rounded-2xl border border-border/80 space-y-1">
      <span className="text-[11px] text-muted-foreground font-medium block">{label}</span>
      <span
        className={`block text-xs font-semibold ${
          highlight ? "text-[#00aef0] text-sm font-extrabold" : "text-foreground"
        } ${isMono ? "font-mono" : ""}`}
      >
        {value}
      </span>
    </div>
  );
}

function FlagBadge({ label, active }: { label: string; active: boolean }) {
  return (
    <div
      className={`p-2.5 rounded-xl border flex items-center gap-2 text-xs font-semibold ${
        active
          ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20"
          : "bg-card text-muted-foreground border-border"
      }`}
    >
      {active ? (
        <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400 shrink-0" />
      ) : (
        <XCircle className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
      )}
      <span className="truncate">{label}</span>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import type { Contact, Tag, ContactNote, CustomField, Deal } from '@/types';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import {
  Phone,
  Mail,
  Building2,
  Copy,
  Check,
  Loader2,
  Plus,
  Trash2,
  Save,
  Banknote,
} from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';
import { formatCurrency } from '@/lib/currency';
import { IconAction } from "@/components/ui/icon-action";

interface ContactDetailViewProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  contactId: string | null;
  onUpdated: () => void;
}

export function ContactDetailView({
  open,
  onOpenChange,
  contactId,
  onUpdated,
}: ContactDetailViewProps) {
  const supabase = createClient();
  const { activeWorkspace, defaultCurrency } = useWorkspace();

  const [contact, setContact] = useState<Contact | null>(null);
  const [loading, setLoading] = useState(false);
  const [copiedPhone, setCopiedPhone] = useState(false);

  // Details tab
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editEmail, setEditEmail] = useState('');
  const [editCompany, setEditCompany] = useState('');
  const [savingDetails, setSavingDetails] = useState(false);

  // Tags tab
  const [allTags, setAllTags] = useState<Tag[]>([]);
  const [contactTagIds, setContactTagIds] = useState<string[]>([]);
  const [savingTags, setSavingTags] = useState(false);

  // Notes tab
  const [notes, setNotes] = useState<ContactNote[]>([]);
  const [newNote, setNewNote] = useState('');
  const [savingNote, setSavingNote] = useState(false);
  const [loadingNotes, setLoadingNotes] = useState(false);

  // Custom fields tab
  const [customFields, setCustomFields] = useState<CustomField[]>([]);
  const [customValues, setCustomValues] = useState<Record<string, string>>({});
  const [savingCustom, setSavingCustom] = useState(false);
  const [loadingCustom, setLoadingCustom] = useState(false);

  // Deals tab
  const [deals, setDeals] = useState<Deal[]>([]);
  const [loadingDeals, setLoadingDeals] = useState(false);

  const fetchContact = useCallback(async () => {
    if (!contactId) return;
    setLoading(true);

    const { data } = await supabase
      .from('contacts')
      .select('*')
      .eq('id', contactId)
      .single();

    if (data) {
      setContact(data);
      setEditName(data.name ?? '');
      setEditPhone(data.phone);
      setEditEmail(data.email ?? '');
      setEditCompany(data.company ?? '');
    }
    setLoading(false);
  }, [contactId, supabase]);

  const fetchTags = useCallback(async () => {
    if (!contactId || !activeWorkspace?.id) return;

    const [tagsRes, contactTagsRes] = await Promise.all([
      supabase.from('tags').select('*').eq('workspace_id', activeWorkspace.id).order('name'),
      supabase.from('contact_tags').select('tag_id').eq('contact_id', contactId),
    ]);

    if (tagsRes.data) setAllTags(tagsRes.data);
    if (contactTagsRes.data) {
      setContactTagIds(contactTagsRes.data.map((ct) => ct.tag_id));
    }
  }, [contactId, supabase, activeWorkspace?.id]);

  const fetchNotes = useCallback(async () => {
    if (!contactId) return;
    setLoadingNotes(true);

    const { data } = await supabase
      .from('contact_notes')
      .select('*')
      .eq('contact_id', contactId)
      .order('created_at', { ascending: false });

    if (data) setNotes(data);
    setLoadingNotes(false);
  }, [contactId, supabase]);

  const fetchCustomFields = useCallback(async () => {
    if (!contactId || !activeWorkspace?.id) return;
    setLoadingCustom(true);

    const [fieldsRes, valuesRes] = await Promise.all([
      supabase.from('custom_fields').select('*').eq('workspace_id', activeWorkspace.id).order('field_name'),
      supabase
        .from('contact_custom_values')
        .select('*')
        .eq('contact_id', contactId),
    ]);

    if (fieldsRes.data) setCustomFields(fieldsRes.data);
    if (valuesRes.data) {
      const map: Record<string, string> = {};
      valuesRes.data.forEach((v) => {
        map[v.custom_field_id] = v.value ?? '';
      });
      setCustomValues(map);
    }
    setLoadingCustom(false);
  }, [contactId, supabase, activeWorkspace?.id]);

  const fetchDeals = useCallback(async () => {
    if (!contactId) return;
    setLoadingDeals(true);
    const { data } = await supabase
      .from('deals')
      .select('*, stage:pipeline_stages(*)')
      .eq('contact_id', contactId)
      .order('created_at', { ascending: false });
    setDeals((data ?? []) as Deal[]);
    setLoadingDeals(false);
  }, [contactId, supabase]);

  useEffect(() => {
    if (open && contactId) {
      fetchContact();
      fetchTags();
      fetchNotes();
      fetchCustomFields();
      fetchDeals();
    }
  }, [open, contactId, fetchContact, fetchTags, fetchNotes, fetchCustomFields, fetchDeals]);

  async function copyPhone() {
    if (!contact) return;
    await navigator.clipboard.writeText(contact.phone);
    setCopiedPhone(true);
    setTimeout(() => setCopiedPhone(false), 2000);
  }

  async function saveDetails() {
    if (!contactId || !editPhone.trim()) {
      toast.error('Phone number is required');
      return;
    }

    setSavingDetails(true);
    const { error } = await supabase
      .from('contacts')
      .update({
        name: editName.trim() || null,
        phone: editPhone.trim(),
        email: editEmail.trim() || null,
        company: editCompany.trim() || null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', contactId);

    if (error) {
      toast.error('Failed to update contact');
    } else {
      toast.success('Contact updated');
      fetchContact();
      onUpdated();
    }
    setSavingDetails(false);
  }

  async function toggleTag(tagId: string) {
    if (!contactId) return;
    setSavingTags(true);

    const isSelected = contactTagIds.includes(tagId);

    if (isSelected) {
      const { error } = await supabase
        .from('contact_tags')
        .delete()
        .eq('contact_id', contactId)
        .eq('tag_id', tagId);
      if (!error) {
        setContactTagIds((prev) => prev.filter((id) => id !== tagId));
        onUpdated();
      }
    } else {
      const { error } = await supabase
        .from('contact_tags')
        .insert({ contact_id: contactId, tag_id: tagId });
      if (!error) {
        setContactTagIds((prev) => [...prev, tagId]);
        onUpdated();
      }
    }
    setSavingTags(false);
  }

  async function addNote() {
    if (!contactId || !newNote.trim()) return;
    setSavingNote(true);

    const {
      data: { session },
    } = await supabase.auth.getSession();
    const user = session?.user;
    if (!user) {
      toast.error('Not authenticated');
      setSavingNote(false);
      return;
    }

    const { error } = await supabase.from('contact_notes').insert({
      contact_id: contactId,
      user_id: user.id,
      note_text: newNote.trim(),
    });

    if (error) {
      toast.error('Failed to add note');
    } else {
      setNewNote('');
      fetchNotes();
      toast.success('Note added');
    }
    setSavingNote(false);
  }

  async function deleteNote(noteId: string) {
    const { error } = await supabase
      .from('contact_notes')
      .delete()
      .eq('id', noteId);

    if (error) {
      toast.error('Failed to delete note');
    } else {
      setNotes((prev) => prev.filter((n) => n.id !== noteId));
      toast.success('Note deleted');
    }
  }

  async function saveCustomFields() {
    if (!contactId) return;
    setSavingCustom(true);

    try {
      // Delete existing values and re-insert
      await supabase
        .from('contact_custom_values')
        .delete()
        .eq('contact_id', contactId);

      const rows = Object.entries(customValues)
        .filter(([, val]) => val.trim())
        .map(([fieldId, val]) => ({
          contact_id: contactId,
          custom_field_id: fieldId,
          value: val.trim(),
        }));

      if (rows.length > 0) {
        const { error } = await supabase
          .from('contact_custom_values')
          .insert(rows);
        if (error) throw error;
      }

      toast.success('Custom fields saved');
    } catch {
      toast.error('Failed to save custom fields');
    }
    setSavingCustom(false);
  }

  function getInitials(name?: string | null) {
    if (!name) return '?';
    return name
      .split(' ')
      .map((w) => w[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="bg-popover border-border text-popover-foreground sm:max-w-lg w-full p-0"
      >
        {loading || !contact ? (
          <div className="flex items-center justify-center h-full">
            <Loader2 className="size-6 animate-spin text-primary" />
          </div>
        ) : (
          <div className="flex flex-col h-full">
            {/* Header */}
            <SheetHeader className="p-4 border-b border-border/50">
              <div className="flex items-center gap-3">
                <Avatar className="size-12 bg-muted border border-border">
                  <AvatarFallback className="bg-primary/10 text-primary text-sm font-medium">
                    {getInitials(contact.name)}
                  </AvatarFallback>
                </Avatar>
                <div className="flex-1 min-w-0">
                  <SheetTitle className="text-popover-foreground truncate">
                    {contact.name || 'Unknown'}
                  </SheetTitle>
                  <SheetDescription className="text-muted-foreground text-xs mt-0.5">
                    Contact details
                  </SheetDescription>
                  <div className="flex flex-wrap items-center gap-3 mt-1.5 text-xs text-muted-foreground">
                    <button
                      onClick={copyPhone}
                      className="flex items-center gap-1 hover:text-primary transition-colors cursor-pointer"
                    >
                      <Phone className="size-3" />
                      {contact.phone}
                      {copiedPhone ? (
                        <Check className="size-3 text-primary" />
                      ) : (
                        <Copy className="size-3" />
                      )}
                    </button>
                    {contact.email && (
                      <span className="flex items-center gap-1">
                        <Mail className="size-3" />
                        {contact.email}
                      </span>
                    )}
                    {contact.company && (
                      <span className="flex items-center gap-1">
                        <Building2 className="size-3" />
                        {contact.company}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            </SheetHeader>

            {/* Tabs */}
            <Tabs defaultValue="details" className="flex-1 flex flex-col min-h-0">
              <TabsList className="bg-muted/50 border-b border-border mx-4 mt-3">
                <TabsTrigger
                  value="details"
                  className="data-active:bg-muted data-active:text-primary text-muted-foreground"
                >
                  Details
                </TabsTrigger>
                <TabsTrigger
                  value="tags"
                  className="data-active:bg-muted data-active:text-primary text-muted-foreground"
                >
                  Tags
                </TabsTrigger>
                <TabsTrigger
                  value="notes"
                  className="data-active:bg-muted data-active:text-primary text-muted-foreground"
                >
                  Notes
                </TabsTrigger>
                <TabsTrigger
                  value="custom"
                  className="data-active:bg-muted data-active:text-primary text-muted-foreground"
                >
                  Custom Fields
                </TabsTrigger>
                <TabsTrigger
                  value="deals"
                  className="data-active:bg-muted data-active:text-primary text-muted-foreground"
                >
                  Deals
                </TabsTrigger>
              </TabsList>

              {/* Details Tab */}
              <TabsContent value="details" className="flex-1 overflow-y-auto px-4 py-3">
                <div className="space-y-3">
                  <div className="space-y-1.5">
                    <Label className="text-muted-foreground text-xs">Name</Label>
                    <Input
                      value={editName}
                      onChange={(e) => setEditName(e.target.value)}
                      className="bg-muted border-border text-foreground h-8 text-sm"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-muted-foreground text-xs">
                      Phone <span className="text-red-400">*</span>
                    </Label>
                    <Input
                      value={editPhone}
                      onChange={(e) => setEditPhone(e.target.value)}
                      className="bg-muted border-border text-foreground h-8 text-sm"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-muted-foreground text-xs">Email</Label>
                    <Input
                      value={editEmail}
                      onChange={(e) => setEditEmail(e.target.value)}
                      className="bg-muted border-border text-foreground h-8 text-sm"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-muted-foreground text-xs">Company</Label>
                    <Input
                      value={editCompany}
                      onChange={(e) => setEditCompany(e.target.value)}
                      className="bg-muted border-border text-foreground h-8 text-sm"
                    />
                  </div>
                  <IconAction label="Save Changes" icon={savingDetails ? (
                      <Loader2 className="size-3.5 animate-spin" />
                    ) : (
                      <Save className="size-3.5" />
                    )} onClick={saveDetails}
                    disabled={savingDetails}
                    className="bg-primary hover:bg-primary/90 text-primary-foreground w-full" />
                </div>
              </TabsContent>

              {/* Tags Tab */}
              <TabsContent value="tags" className="flex-1 overflow-y-auto px-4 py-3">
                <div className="space-y-3">
                  <p className="text-xs text-muted-foreground">
                    Click a tag to add or remove it from this contact.
                  </p>
                  {allTags.length === 0 ? (
                    <p className="text-sm text-muted-foreground">
                      No tags available. Create tags in Settings.
                    </p>
                  ) : (
                    <div className="flex flex-wrap gap-2">
                      {allTags.map((tag) => {
                        const selected = contactTagIds.includes(tag.id);
                        return (
                          <button
                            key={tag.id}
                            onClick={() => toggleTag(tag.id)}
                            disabled={savingTags}
                            className={`inline-flex items-center rounded-full px-3 py-1 text-xs font-medium transition-all cursor-pointer ${
                              selected
                                ? 'ring-2 ring-primary ring-offset-1 ring-offset-border'
                                : 'opacity-50 hover:opacity-80'
                            }`}
                            style={{
                              backgroundColor: tag.color + '20',
                              color: tag.color,
                            }}
                          >
                            {selected && <Check className="size-3 mr-1" />}
                            {tag.name}
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </TabsContent>

              {/* Notes Tab */}
              <TabsContent value="notes" className="flex-1 flex flex-col min-h-0 px-4 py-3">
                <div className="space-y-2 mb-3">
                  <Textarea
                    value={newNote}
                    onChange={(e) => setNewNote(e.target.value)}
                    placeholder="Write a note..."
                    className="bg-muted border-border text-foreground placeholder:text-muted-foreground min-h-[60px] text-sm resize-none"
                  />
                  <IconAction label="Add Note" icon={savingNote ? (
                      <Loader2 className="size-3.5 animate-spin" />
                    ) : (
                      <Plus className="size-3.5" />
                    )} onClick={addNote}
                    disabled={!newNote.trim() || savingNote}
                    className="bg-primary hover:bg-primary/90 text-primary-foreground" />
                </div>

                <div className="flex-1 overflow-y-auto space-y-2">
                  {loadingNotes ? (
                    <div className="flex items-center justify-center py-8">
                      <Loader2 className="size-5 animate-spin text-muted-foreground" />
                    </div>
                  ) : notes.length === 0 ? (
                    <p className="text-sm text-muted-foreground text-center py-8">
                      No notes yet.
                    </p>
                  ) : (
                    notes.map((note) => (
                      <div
                        key={note.id}
                        className="rounded-lg bg-muted/50 border border-border/50 p-3 group"
                      >
                        <div className="flex items-start justify-between gap-2">
                          <p className="text-sm text-muted-foreground whitespace-pre-wrap flex-1">
                            {note.note_text}
                          </p>
                          <button
                            onClick={() => deleteNote(note.id)}
                            className="opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-red-400 transition-all cursor-pointer shrink-0"
                          >
                            <Trash2 className="size-3.5" />
                          </button>
                        </div>
                        <p className="text-xs text-muted-foreground mt-1.5">
                          {new Date(note.created_at).toLocaleDateString('en-US', {
                            month: 'short',
                            day: 'numeric',
                            year: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </p>
                      </div>
                    ))
                  )}
                </div>
              </TabsContent>

              {/* Custom Fields Tab */}
              <TabsContent value="custom" className="flex-1 overflow-y-auto px-4 py-3">
                {loadingCustom ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="size-5 animate-spin text-muted-foreground" />
                  </div>
                ) : customFields.length === 0 ? (
                  <p className="text-sm text-muted-foreground text-center py-8">
                    No custom fields defined. Create them in Settings.
                  </p>
                ) : (
                  <div className="space-y-3">
                    {customFields.map((field) => (
                      <div key={field.id} className="space-y-1.5">
                        <Label className="text-muted-foreground text-xs capitalize">
                          {field.field_name}
                        </Label>
                        <Input
                          value={customValues[field.id] ?? ''}
                          onChange={(e) =>
                            setCustomValues((prev) => ({
                              ...prev,
                              [field.id]: e.target.value,
                            }))
                          }
                          placeholder={`Enter ${field.field_name}...`}
                          className="bg-muted border-border text-foreground h-8 text-sm placeholder:text-muted-foreground"
                        />
                      </div>
                    ))}
                    <IconAction label="Save Custom Fields" icon={savingCustom ? (
                        <Loader2 className="size-3.5 animate-spin" />
                      ) : (
                        <Save className="size-3.5" />
                      )} onClick={saveCustomFields}
                      disabled={savingCustom}
                      className="bg-primary hover:bg-primary/90 text-primary-foreground w-full" />
                  </div>
                )}
              </TabsContent>

              {/* Deals Tab */}
              <TabsContent value="deals" className="flex-1 overflow-y-auto px-4 py-3">
                {loadingDeals ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="size-5 animate-spin text-primary" />
                  </div>
                ) : deals.length === 0 ? (
                  <p className="text-xs text-muted-foreground">No deals yet</p>
                ) : (
                  <div className="space-y-2">
                    {deals.map((deal) => (
                      <div
                        key={deal.id}
                        className="rounded-lg border border-border bg-muted/50 p-3"
                      >
                        <div className="flex items-start justify-between gap-2">
                          <p className="text-sm font-medium text-foreground">
                            {deal.title}
                          </p>
                          {deal.stage && (
                            <span
                              className="shrink-0 rounded-full px-1.5 py-0.5 text-[10px] font-medium"
                              style={{
                                backgroundColor: `${deal.stage.color}20`,
                                color: deal.stage.color,
                              }}
                            >
                              {deal.stage.name}
                            </span>
                          )}
                        </div>
                        <div className="mt-1.5 flex items-center justify-between text-xs text-muted-foreground">
                          <span className="flex items-center gap-1">
                            <Banknote className="size-3" />
                            {formatCurrency(
                              Number(deal.value || 0),
                              deal.currency || defaultCurrency,
                            )}
                          </span>
                          {deal.status && deal.status !== 'open' && (
                            <span
                              className={
                                deal.status === 'won'
                                  ? 'text-primary'
                                  : 'text-red-400'
                              }
                            >
                              {deal.status}
                            </span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </TabsContent>
            </Tabs>
          </div>
        )}
      </SheetContent>
    </Sheet>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import type { Contact, Tag, ContactTag } from '@/types';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Loader2 } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';

interface ContactFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  contact?: Contact | null;
  contactTags?: ContactTag[];
  onSaved: () => void;
}

export function ContactForm({
  open,
  onOpenChange,
  contact,
  contactTags = [],
  onSaved,
}: ContactFormProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  const isEdit = !!contact;

  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [company, setCompany] = useState('');
  const [saving, setSaving] = useState(false);

  const [tags, setTags] = useState<Tag[]>([]);
  const [selectedTagIds, setSelectedTagIds] = useState<string[]>([]);
  const [loadingTags, setLoadingTags] = useState(false);

  useEffect(() => {
    if (open) {
      setName(contact?.name ?? '');
      setPhone(contact?.phone ?? '');
      setEmail(contact?.email ?? '');
      setCompany(contact?.company ?? '');
      setSelectedTagIds(contactTags.map((ct) => ct.tag_id));
      fetchTags();
    }
  }, [open, contact]);

  async function fetchTags() {
    if (!activeWorkspace?.id) return;
    setLoadingTags(true);
    const { data } = await supabase
      .from('tags')
      .select('*')
      .eq('workspace_id', activeWorkspace.id)
      .order('name');
    if (data) setTags(data);
    setLoadingTags(false);
  }

  function toggleTag(tagId: string) {
    setSelectedTagIds((prev) =>
      prev.includes(tagId)
        ? prev.filter((id) => id !== tagId)
        : [...prev, tagId]
    );
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    if (!activeWorkspace?.id) {
      toast.error('No active workspace selected');
      return;
    }

    if (!phone.trim()) {
      toast.error('Phone number is required');
      return;
    }

    setSaving(true);

    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const user = session?.user;
      if (!user) throw new Error('Not authenticated');

      let contactId = contact?.id;

      if (isEdit && contactId) {
        const { error } = await supabase
          .from('contacts')
          .update({
            name: name.trim() || null,
            phone: phone.trim(),
            email: email.trim() || null,
            company: company.trim() || null,
            updated_at: new Date().toISOString(),
          })
          .eq('id', contactId);
        if (error) throw error;
      } else {
        const { data, error } = await supabase
          .from('contacts')
          .insert({
            user_id: user.id,
            workspace_id: activeWorkspace.id,
            name: name.trim() || null,
            phone: phone.trim(),
            email: email.trim() || null,
            company: company.trim() || null,
          })
          .select('id')
          .single();
        if (error) throw error;
        contactId = data.id;
      }

      // Sync tags
      if (contactId) {
        await supabase
          .from('contact_tags')
          .delete()
          .eq('contact_id', contactId);

        if (selectedTagIds.length > 0) {
          const tagRows = selectedTagIds.map((tag_id) => ({
            contact_id: contactId!,
            tag_id,
          }));
          const { error: tagError } = await supabase
            .from('contact_tags')
            .insert(tagRows);
          if (tagError) throw tagError;
        }
      }

      toast.success(isEdit ? 'Contact updated' : 'Contact created');
      onOpenChange(false);
      onSaved();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Failed to save contact';
      toast.error(message);
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-popover-foreground">
            {isEdit ? 'Edit Contact' : 'Add Contact'}
          </DialogTitle>
          <DialogDescription className="text-muted-foreground">
            {isEdit
              ? 'Update the contact details below.'
              : 'Fill in the details to create a new contact.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="cf-name" className="text-muted-foreground">
              Name
            </Label>
            <Input
              id="cf-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="John Doe"
              className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="cf-phone" className="text-muted-foreground">
              Phone <span className="text-red-400">*</span>
            </Label>
            <Input
              id="cf-phone"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="+1 234 567 8900"
              className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
            />
            <p className="text-xs text-muted-foreground">
              Include country code, e.g. +1 for US
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="cf-email" className="text-muted-foreground">
              Email
            </Label>
            <Input
              id="cf-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="john@example.com"
              className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="cf-company" className="text-muted-foreground">
              Company
            </Label>
            <Input
              id="cf-company"
              value={company}
              onChange={(e) => setCompany(e.target.value)}
              placeholder="Acme Inc."
              className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
            />
          </div>

          <div className="space-y-2">
            <Label className="text-muted-foreground">Tags</Label>
            {loadingTags ? (
              <div className="flex items-center gap-2 text-muted-foreground text-sm">
                <Loader2 className="size-3 animate-spin" />
                Loading tags...
              </div>
            ) : tags.length === 0 ? (
              <p className="text-xs text-muted-foreground">
                No tags available. Create tags in Settings.
              </p>
            ) : (
              <div className="flex flex-wrap gap-1.5">
                {tags.map((tag) => {
                  const selected = selectedTagIds.includes(tag.id);
                  return (
                    <button
                      key={tag.id}
                      type="button"
                      onClick={() => toggleTag(tag.id)}
                      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium transition-colors cursor-pointer ${
                        selected
                          ? 'ring-2 ring-primary ring-offset-1 ring-offset-border'
                          : 'opacity-60 hover:opacity-100'
                      }`}
                      style={{
                        backgroundColor: tag.color + '20',
                        color: tag.color,
                        borderColor: tag.color,
                      }}
                    >
                      {tag.name}
                    </button>
                  );
                })}
              </div>
            )}
          </div>

          <DialogFooter className="bg-popover border-border">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="border-border text-muted-foreground hover:bg-muted"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={saving}
              className="bg-primary hover:bg-primary/90 text-primary-foreground"
            >
              {saving && <Loader2 className="size-4 animate-spin" />}
              {isEdit ? 'Update' : 'Create'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

