"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { useWorkspace } from "@/hooks/use-workspace";
import { createClient } from "@/lib/supabase/client";
import { Loader2, Upload, UserCheck, ShieldCheck, Trash2 } from "lucide-react";
import { IconAction } from "@/components/ui/icon-action";

interface SignatoryModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved: () => void;
  initialData?: any;
}

export function SignatoryModal({ open, onOpenChange, onSaved, initialData }: SignatoryModalProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  const [loading, setLoading] = useState(false);

  const [name, setName] = useState(initialData?.name || "");
  const [designation, setDesignation] = useState(initialData?.designation || "");
  const [department, setDepartment] = useState(initialData?.department || "HR");
  const [email, setEmail] = useState(initialData?.email || "");
  const [signatureUrl, setSignatureUrl] = useState(initialData?.signature_url || "");
  const [stampUrl, setStampUrl] = useState(initialData?.stamp_url || "");
  const [isDefault, setIsDefault] = useState(initialData?.is_default || false);

  const handleFileUpload = async (file: File, type: "signature" | "stamp") => {
    if (!activeWorkspace?.id) return;
    try {
      toast.loading(`Uploading ${type}...`);
      const fileExt = file.name.split(".").pop();
      const filePath = `${activeWorkspace.id}/signatories/${type}_${Date.now()}.${fileExt}`;

      const { error: uploadError } = await supabase.storage
        .from("employee-documents")
        .upload(filePath, file, { upsert: true });

      if (uploadError) throw uploadError;

      const { data: publicUrlData } = supabase.storage
        .from("employee-documents")
        .getPublicUrl(filePath);

      const url = publicUrlData.publicUrl;
      if (type === "signature") setSignatureUrl(url);
      else setStampUrl(url);

      toast.dismiss();
      toast.success(`${type === "signature" ? "Signature" : "Seal Stamp"} uploaded successfully!`);
    } catch (err: any) {
      toast.dismiss();
      toast.error(err.message || "Failed to upload image.");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !name.trim() || !designation.trim()) {
      toast.error("Please fill in signatory name and designation.");
      return;
    }

    setLoading(true);
    try {
      if (initialData?.id) {
        const { error } = await supabase
          .from("company_signatories")
          .update({
            name,
            designation,
            department,
            email,
            signature_url: signatureUrl,
            stamp_url: stampUrl,
            is_default: isDefault,
          })
          .eq("id", initialData.id);
        if (error) throw error;
        toast.success("Signatory updated successfully!");
      } else {
        const { error } = await supabase.from("company_signatories").insert({
          workspace_id: activeWorkspace.id,
          name,
          designation,
          department,
          email,
          signature_url: signatureUrl,
          stamp_url: stampUrl,
          is_default: isDefault,
        });
        if (error) throw error;
        toast.success("New signatory added successfully!");
      }

      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || "Failed to save signatory.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md bg-card border-border text-foreground rounded-2xl shadow-2xl">
        <DialogHeader>
          <DialogTitle className="text-base font-bold flex items-center gap-2">
            <UserCheck className="size-5 text-primary" />
            {initialData ? "Edit Signatory" : "Add Corporate Signatory"}
          </DialogTitle>
          <DialogDescription className="text-xs text-muted-foreground">
            Configure authorized signer details, digital signature image, and official seal stamp.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 pt-2">
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">Signatory Full Name *</Label>
            <Input
              type="text"
              placeholder="e.g. Swaraj Jakanoor"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="bg-background text-xs"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Designation *</Label>
              <Input
                type="text"
                placeholder="e.g. Chief Executive Officer"
                value={designation}
                onChange={(e) => setDesignation(e.target.value)}
                className="bg-background text-xs"
                required
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Department</Label>
              <select
                value={department}
                onChange={(e) => setDepartment(e.target.value)}
                className="w-full bg-background border border-border text-foreground text-xs rounded-lg px-3 py-2"
              >
                <option value="Executive">Executive</option>
                <option value="HR">HR & Operations</option>
                <option value="Finance">Finance</option>
                <option value="Legal">Legal</option>
                <option value="Sales">Sales</option>
              </select>
            </div>
          </div>

          {/* Signature Upload */}
          <div className="space-y-1.5 pt-1">
            <Label className="text-xs font-semibold">Digital Signature Image (PNG)</Label>
            {signatureUrl ? (
              <div className="p-3 bg-muted/40 rounded-xl border border-border flex items-center justify-between gap-3">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={signatureUrl} alt="Signature Preview" className="h-10 object-contain" />
                <IconAction label="Remove" icon={<Trash2 className="size-3.5 " />} type="button"
                  variant="ghost"
                  onClick={() => setSignatureUrl("")}
                  className="h-7 px-2 text-xs text-rose-500 hover:bg-rose-500/10" />
              </div>
            ) : (
              <label className="relative border-2 border-dashed border-primary/30 hover:border-primary/60 bg-primary/5 hover:bg-primary/10 transition-all rounded-xl p-3 flex flex-col items-center justify-center text-center cursor-pointer group">
                <input
                  type="file"
                  accept="image/png,image/jpeg,image/svg+xml"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleFileUpload(file, "signature");
                  }}
                  className="sr-only"
                />
                <div className="flex items-center gap-2 text-xs font-semibold text-primary">
                  <Upload className="size-4 group-hover:scale-110 transition-transform" />
                  <span>Upload Signature Image</span>
                </div>
              </label>
            )}
          </div>

          {/* Stamp Upload */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">Official Seal / Stamp Image (PNG)</Label>
            {stampUrl ? (
              <div className="p-3 bg-muted/40 rounded-xl border border-border flex items-center justify-between gap-3">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={stampUrl} alt="Stamp Preview" className="h-10 object-contain" />
                <IconAction label="Remove" icon={<Trash2 className="size-3.5 " />} type="button"
                  variant="ghost"
                  onClick={() => setStampUrl("")}
                  className="h-7 px-2 text-xs text-rose-500 hover:bg-rose-500/10" />
              </div>
            ) : (
              <label className="relative border-2 border-dashed border-purple-500/30 hover:border-purple-500/60 bg-purple-500/5 hover:bg-purple-500/10 transition-all rounded-xl p-3 flex flex-col items-center justify-center text-center cursor-pointer group">
                <input
                  type="file"
                  accept="image/png,image/jpeg,image/svg+xml"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleFileUpload(file, "stamp");
                  }}
                  className="sr-only"
                />
                <div className="flex items-center gap-2 text-xs font-semibold text-purple-600 dark:text-purple-400">
                  <Upload className="size-4 group-hover:scale-110 transition-transform" />
                  <span>Upload Seal Stamp Image</span>
                </div>
              </label>
            )}
          </div>

          <div className="flex items-center gap-2 pt-2">
            <input
              type="checkbox"
              id="isDefault"
              checked={isDefault}
              onChange={(e) => setIsDefault(e.target.checked)}
              className="rounded border-border"
            />
            <Label htmlFor="isDefault" className="text-xs cursor-pointer font-medium">
              Set as Default Signatory for Workspace Documents
            </Label>
          </div>

          <div className="flex justify-end gap-2 pt-4 border-t border-border">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)} className="text-xs h-9">
              Cancel
            </Button>
            <Button type="submit" disabled={loading} className="bg-primary text-primary-foreground text-xs h-9 font-semibold">
              {loading ? <Loader2 className="size-4 animate-spin mr-1.5" /> : null}
              Save Signatory
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2, UploadCloud } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';

interface UploadDocumentFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved: () => void;
}

const DOCUMENT_TYPES = [
  'NDA',
  'Offer Letter',
  'Relieving Letter',
  'Government ID (Aadhar)',
  'Government ID (PAN)',
  'Resume',
  'Other'
];

export function UploadDocumentForm({ open, onOpenChange, onSaved }: UploadDocumentFormProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [loadingDeps, setLoadingDeps] = useState(true);
  const [employees, setEmployees] = useState<any[]>([]);

  // Form State
  const [saving, setSaving] = useState(false);
  const [memberId, setMemberId] = useState('');
  const [docType, setDocType] = useState('');
  const [file, setFile] = useState<File | null>(null);

  useEffect(() => {
    if (open && activeWorkspace?.id) {
      loadEmployees();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, activeWorkspace?.id]);

  async function loadEmployees() {
    setLoadingDeps(true);
    try {
      // Fetch only onboarded employees — two-step required since workspace_members.user_id refs auth.users
      const { data: empData } = await supabase
        .from('employee_profiles')
        // See employees/page.tsx: the embed needs the FK hint because
        // employee_profiles points at workspace_members twice.
        .select('workspace_member_id, workspace_members!workspace_member_id(id, user_id)')
        .eq('workspace_id', activeWorkspace!.id)
        .eq('status', 'ACTIVE');

      const empList = empData || [];
      if (empList.length > 0) {
        const userIds = empList.map((e: any) => e.workspace_members?.user_id).filter(Boolean);
        const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name, email').in('user_id', userIds);
        const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
        const enriched = empList.map((e: any) => ({
          ...e,
          workspace_members: e.workspace_members
            ? { ...e.workspace_members, profiles: profileMap[e.workspace_members.user_id] || null }
            : null
        }));
        setEmployees(enriched);
      } else {
        setEmployees([]);
      }
    } catch {
      toast.error('Failed to load employees');
    } finally {
      setLoadingDeps(false);
    }
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!activeWorkspace?.id || !memberId || !docType || !file) return;

    setSaving(true);
    
    try {
      // 1. Upload through the service-role storage API — direct
      // client uploads fail (the buckets carry no storage RLS
      // policies), and HR documents live in the PRIVATE
      // employee-documents bucket, reachable only via signed URLs.
      // No placeholder fallback: if storage fails, the upload fails.
      const form = new FormData();
      form.append('bucket', 'employee-documents');
      form.append('workspace_id', activeWorkspace.id);
      form.append('file', file);
      const res = await fetch('/api/storage/upload', { method: 'POST', body: form });
      const json = await res.json();
      if (!res.ok || !json.path) {
        throw new Error(json.error || 'File upload failed');
      }

      // 2. Save metadata — the column is storage_path (NOT NULL);
      // document_url never existed and made every insert fail.
      const { error: dbError } = await supabase
        .from('employee_documents')
        .insert({
          workspace_id: activeWorkspace.id,
          workspace_member_id: memberId,
          document_type: docType,
          storage_path: json.path
        });

      if (dbError) throw dbError;
      
      toast.success('Document securely uploaded!');
      
      // Reset form
      setMemberId('');
      setDocType('');
      setFile(null);
      
      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to upload document');
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-popover-foreground">
            Upload Employee Document
          </DialogTitle>
        </DialogHeader>
        
        {loadingDeps ? (
          <div className="py-12 flex justify-center">
            <Loader2 className="size-6 animate-spin text-primary" />
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 py-4">
            
            <div className="space-y-2">
              <Label>Select Employee <span className="text-red-500">*</span></Label>
              {employees.length === 0 ? (
                <div className="text-sm text-amber-500 bg-amber-500/10 p-3 rounded-md border border-amber-500/20">
                  No active employees found. Onboard someone first.
                </div>
              ) : (
                <Select value={memberId} onValueChange={(v) => setMemberId(v || '')} required>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue placeholder="Select an employee..." />
                  </SelectTrigger>
                  <SelectContent>
                    {employees.map(emp => {
                      const profile = Array.isArray(emp.workspace_members?.profiles) 
                        ? emp.workspace_members?.profiles[0] 
                        : emp.workspace_members?.profiles;
                      
                      return (
                        <SelectItem key={emp.workspace_member_id} value={emp.workspace_member_id}>
                          {profile?.full_name || profile?.email || 'Unknown User'}
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              )}
            </div>

            <div className="space-y-2">
              <Label>Document Type <span className="text-red-500">*</span></Label>
              <Select value={docType} onValueChange={(v) => setDocType(v || '')} required>
                <SelectTrigger className="bg-card border-border">
                  <SelectValue placeholder="e.g. NDA" />
                </SelectTrigger>
                <SelectContent>
                  {DOCUMENT_TYPES.map(type => (
                    <SelectItem key={type} value={type}>{type}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            
            <div className="space-y-2 pt-2">
              <Label>Attach File (PDF, JPG, PNG) <span className="text-red-500">*</span></Label>
              <div className="mt-2 flex justify-center rounded-lg border border-dashed border-border px-6 py-10">
                <div className="text-center">
                  <UploadCloud className="mx-auto size-8 text-muted-foreground" aria-hidden="true" />
                  <div className="mt-4 flex text-sm leading-6 text-muted-foreground justify-center">
                    <label
                      htmlFor="file-upload"
                      className="relative cursor-pointer rounded-md font-semibold text-primary focus-within:outline-none hover:text-primary/80"
                    >
                      <span>Upload a file</span>
                      <Input
                        id="file-upload"
                        name="file-upload"
                        type="file"
                        className="sr-only"
                        onChange={(e) => setFile(e.target.files?.[0] || null)}
                        required
                        accept=".pdf,.png,.jpg,.jpeg"
                      />
                    </label>
                    <p className="pl-1">or drag and drop</p>
                  </div>
                  <p className="text-xs leading-5 text-muted-foreground mt-1">
                    {file ? <span className="text-emerald-500 font-medium">{file.name}</span> : 'PDF, PNG, JPG up to 10MB'}
                  </p>
                </div>
              </div>
            </div>

            <DialogFooter className="pt-4 border-t border-border mt-6">
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
                className="border-border text-muted-foreground hover:bg-muted"
                disabled={saving}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                className="bg-primary hover:bg-primary/90 text-primary-foreground"
                disabled={saving || !memberId || !docType || !file}
              >
                {saving && <Loader2 className="size-4 animate-spin mr-2" />}
                Save Document
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Loader2, Plus, Laptop, CheckCircle2 } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';
import { IconAction } from "@/components/ui/icon-action";

interface EmployeeAssetsTabProps {
  employeeId: string;
  canEdit: boolean;
}

export function EmployeeAssetsTab({ employeeId, canEdit }: EmployeeAssetsTabProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  
  const [assets, setAssets] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [formOpen, setFormOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  // Form State
  const [assetName, setAssetName] = useState('');
  const [serialNumber, setSerialNumber] = useState('');
  const [assignedDate, setAssignedDate] = useState(new Date().toISOString().split('T')[0]);

  const fetchAssets = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    const { data, error } = await supabase
      .from('employee_assets')
      .select('*')
      .eq('workspace_id', activeWorkspace.id)
      .eq('workspace_member_id', employeeId)
      .order('assigned_date', { ascending: false });

    if (error) {
      toast.error('Failed to load assets');
    } else {
      setAssets(data || []);
    }
    setLoading(false);
  }, [supabase, activeWorkspace?.id, employeeId]);

  useEffect(() => {
    fetchAssets();
  }, [fetchAssets]);

  const handleAssign = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !assetName.trim()) return;

    setSaving(true);
    try {
      const { error } = await supabase
        .from('employee_assets')
        .insert({
          workspace_id: activeWorkspace.id,
          workspace_member_id: employeeId,
          asset_name: assetName.trim(),
          serial_number: serialNumber.trim() || null,
          assigned_date: assignedDate
        });
      
      if (error) throw error;
      toast.success('Asset assigned successfully');
      setFormOpen(false);
      setAssetName('');
      setSerialNumber('');
      fetchAssets();
    } catch (err: any) {
      toast.error(err.message || 'Failed to assign asset');
    } finally {
      setSaving(false);
    }
  };

  const handleReturn = async (id: string) => {
    try {
      const { error } = await supabase
        .from('employee_assets')
        .update({ returned_date: new Date().toISOString().split('T')[0] })
        .eq('id', id);
      
      if (error) throw error;
      toast.success('Asset marked as returned');
      fetchAssets();
    } catch {
      toast.error('Failed to return asset');
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-foreground text-sm tracking-wide uppercase">Assigned Equipment</h3>
        {canEdit && (
          <IconAction label="Assign Asset" icon={<Plus className="size-4 " />} onClick={() => setFormOpen(true)} className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm" />
        )}
      </div>

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent">
              <TableHead className="text-muted-foreground">Asset Name</TableHead>
              <TableHead className="text-muted-foreground">Serial Number</TableHead>
              <TableHead className="text-muted-foreground">Assigned Date</TableHead>
              <TableHead className="text-muted-foreground">Returned Date</TableHead>
              {canEdit && <TableHead className="text-muted-foreground w-24">Action</TableHead>}
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={5} className="text-center py-8">
                  <div className="flex flex-col items-center gap-2">
                    <Loader2 className="size-5 animate-spin text-primary" />
                  </div>
                </TableCell>
              </TableRow>
            ) : assets.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={5} className="text-center py-8">
                  <div className="flex flex-col items-center gap-2">
                    <Laptop className="size-6 text-muted-foreground" />
                    <p className="text-sm text-muted-foreground">No assets assigned yet.</p>
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              assets.map((asset) => (
                <TableRow key={asset.id} className="border-border hover:bg-muted/50">
                  <TableCell className="font-medium text-foreground">{asset.asset_name}</TableCell>
                  <TableCell className="text-sm text-muted-foreground font-mono">{asset.serial_number || '-'}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">{new Date(asset.assigned_date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {asset.returned_date ? new Date(asset.returned_date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '-'}
                  </TableCell>
                  {canEdit && (
                    <TableCell>
                      {!asset.returned_date ? (
                        <IconAction label="Return" icon={<CheckCircle2 className="size-3 " />} variant="outline" onClick={() => handleReturn(asset.id)} className="border-border hover:bg-muted text-xs h-7" />
                      ) : (
                        <span className="text-xs text-muted-foreground px-2">Returned</span>
                      )}
                    </TableCell>
                  )}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={formOpen} onOpenChange={setFormOpen}>
        <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-popover-foreground">Assign Asset</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleAssign} className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Asset Name / Model <span className="text-red-500">*</span></Label>
              <Input 
                value={assetName} 
                onChange={(e) => setAssetName(e.target.value)} 
                placeholder="e.g. MacBook Pro M3" 
                className="bg-card border-border text-foreground"
                required 
              />
            </div>
            <div className="space-y-2">
              <Label>Serial Number</Label>
              <Input 
                value={serialNumber} 
                onChange={(e) => setSerialNumber(e.target.value)} 
                placeholder="Optional" 
                className="bg-card border-border text-foreground"
              />
            </div>
            <div className="space-y-2">
              <Label>Assigned Date <span className="text-red-500">*</span></Label>
              <Input 
                type="date"
                value={assignedDate} 
                onChange={(e) => setAssignedDate(e.target.value)} 
                className="bg-card border-border text-foreground"
                required 
              />
            </div>
            <DialogFooter className="pt-4 border-t border-border mt-6">
              <Button type="button" variant="outline" onClick={() => setFormOpen(false)} disabled={saving} className="border-border hover:bg-muted">Cancel</Button>
              <Button type="submit" disabled={saving || !assetName.trim()} className="bg-primary hover:bg-primary/90 text-primary-foreground">
                {saving && <Loader2 className="size-4 animate-spin mr-2" />} Assign
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { toast } from "sonner";
import { Loader2, Save, MapPin, Trash2, CalendarPlus, Info } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import Link from "next/link";
import {
  WORK_LOCATIONS,
  WORK_LOCATION_LABELS,
  type WorkLocation,
} from "@/lib/attendance/policy";
import { formatDistance } from "@/lib/attendance/geolocation";
import { assertAffected } from "@/lib/supabase/affected-rows";
import { IconAction } from "@/components/ui/icon-action";

const NONE = "none";
const INHERIT = "inherit";

interface WorkLocationRow {
  id: string;
  name: string;
  type: string;
  latitude: number | null;
  longitude: number | null;
  radius_m: number;
}

interface PolicyRow {
  id: string;
  allowed_work_locations: WorkLocation[] | null;
  default_work_location: WorkLocation | null;
  require_location: boolean | null;
  min_gps_accuracy_m: number | null;
  location_id: string | null;
  block_outside_geofence: boolean | null;
  require_timesheet_on_punch_out: boolean | null;
  timesheet_template_id: string | null;
}

interface OverrideRow {
  id: string;
  override_date: string;
  allowed_work_locations: WorkLocation[] | null;
  location_id: string | null;
  note: string | null;
}

function errorMessage(err: unknown, fallback: string): string {
  if (err instanceof Error && err.message) return err.message;
  if (typeof err === "object" && err !== null && "message" in err) {
    const m = (err as { message?: unknown }).message;
    if (typeof m === "string" && m) return m;
  }
  return fallback;
}

/**
 * Per-employee attendance rules, edited where the employee is rather
 * than in workspace settings.
 *
 * This writes a MEMBER-scoped row in `hr_attendance_policies`. Having no
 * row is meaningful: the person inherits their department's policy, or
 * the workspace default. "Use the workspace default" therefore deletes
 * the row rather than writing a copy of the defaults, which would
 * silently stop tracking later changes to them.
 */
export function EmployeeAttendanceTab({
  workspaceMemberId,
  canEdit,
}: {
  workspaceMemberId: string;
  canEdit: boolean;
}) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [locations, setLocations] = useState<WorkLocationRow[]>([]);
  const [templates, setTemplates] = useState<{ id: string; name: string }[]>([]);
  const [policy, setPolicy] = useState<PolicyRow | null>(null);
  const [overrides, setOverrides] = useState<OverrideRow[]>([]);

  const [hasOwnPolicy, setHasOwnPolicy] = useState(false);
  const [allowed, setAllowed] = useState<WorkLocation[]>(["OFFICE"]);
  const [requireLocation, setRequireLocation] = useState(true);
  const [minAccuracy, setMinAccuracy] = useState("100");
  const [locationId, setLocationId] = useState<string>(NONE);
  const [blockOutside, setBlockOutside] = useState(false);
  const [requireTimesheet, setRequireTimesheet] = useState(false);
  const [templateId, setTemplateId] = useState<string>(NONE);

  const [ovDate, setOvDate] = useState(() => new Date().toISOString().split("T")[0]);
  const [ovAllowWfh, setOvAllowWfh] = useState(true);
  const [ovLocationId, setOvLocationId] = useState<string>(INHERIT);
  const [ovNote, setOvNote] = useState("");
  const [savingOverride, setSavingOverride] = useState(false);
  const [attendanceEnabled, setAttendanceEnabled] = useState(true);
  const [savingEnabled, setSavingEnabled] = useState(false);

  const fetchData = useCallback(async () => {
    if (!activeWorkspace?.id || !workspaceMemberId) return;
    setLoading(true);
    try {
      const [locRes, tplRes, polRes, ovRes, empRes] = await Promise.all([
        supabase
          .from("work_locations")
          .select("id, name, type, latitude, longitude, radius_m")
          .eq("workspace_id", activeWorkspace.id)
          .is("deleted_at", null)
          .order("name"),
        supabase
          .from("hr_timesheet_templates")
          .select("id, name")
          .or(`workspace_id.is.null,workspace_id.eq.${activeWorkspace.id}`)
          .order("name"),
        supabase
          .from("hr_attendance_policies")
          .select("*")
          .eq("workspace_id", activeWorkspace.id)
          .eq("scope_type", "MEMBER")
          .eq("scope_id", workspaceMemberId)
          .maybeSingle(),
        supabase
          .from("hr_attendance_day_overrides")
          .select("*")
          .eq("workspace_member_id", workspaceMemberId)
          .gte("override_date", new Date().toISOString().split("T")[0])
          .order("override_date"),
        supabase
          .from("employee_profiles")
          .select("attendance_enabled")
          .eq("workspace_member_id", workspaceMemberId)
          .maybeSingle(),
      ]);

      setAttendanceEnabled(empRes.data?.attendance_enabled !== false);

      setLocations((locRes.data as WorkLocationRow[] | null) || []);
      setTemplates(tplRes.data || []);
      setOverrides((ovRes.data as OverrideRow[] | null) || []);

      const p = polRes.data as PolicyRow | null;
      setPolicy(p);
      setHasOwnPolicy(Boolean(p));
      if (p) {
        setAllowed((p.allowed_work_locations || ["OFFICE"]) as WorkLocation[]);
        setRequireLocation(p.require_location ?? true);
        setMinAccuracy(String(p.min_gps_accuracy_m ?? 100));
        setLocationId(p.location_id || NONE);
        setBlockOutside(p.block_outside_geofence ?? false);
        setRequireTimesheet(p.require_timesheet_on_punch_out ?? false);
        setTemplateId(p.timesheet_template_id || NONE);
      }
    } catch (err) {
      toast.error(errorMessage(err, "Failed to load attendance rules"));
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, workspaceMemberId, supabase]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  /** Whether this person clocks in at all. Off hides the punch controls. */
  const handleToggleAttendance = async (enabled: boolean) => {
    setAttendanceEnabled(enabled);
    setSavingEnabled(true);
    try {
      const result = await supabase
        .from("employee_profiles")
        .update({ attendance_enabled: enabled })
        .eq("workspace_member_id", workspaceMemberId)
        .select("workspace_member_id");
      assertAffected(result, "attendance for this employee", "save");
      toast.success(
        enabled
          ? "Attendance switched on — this person will see the punch controls."
          : "Attendance switched off — the punch controls are now hidden for them."
      );
    } catch (err) {
      setAttendanceEnabled(!enabled); // put the switch back on failure
      toast.error(errorMessage(err, "Failed to change attendance"));
    } finally {
      setSavingEnabled(false);
    }
  };

  const toggleAllowed = (loc: WorkLocation) => {
    setAllowed((current) => {
      const has = current.includes(loc);
      if (has && current.length === 1) return current; // never leave nothing selectable
      return has ? current.filter((l) => l !== loc) : [...current, loc];
    });
  };

  const handleSave = async () => {
    if (!activeWorkspace?.id) return;
    const accuracy = parseInt(minAccuracy || "0", 10);
    if (!Number.isFinite(accuracy) || accuracy <= 0) {
      toast.error("Required GPS accuracy must be a positive number of metres.");
      return;
    }

    setSaving(true);
    try {
      if (!hasOwnPolicy) {
        // Back to inheriting: remove the row entirely so later changes to
        // the department or workspace policy reach this person.
        if (policy) {
          const { error } = await supabase
            .from("hr_attendance_policies")
            .delete()
            .eq("id", policy.id);
          if (error) throw error;
        }
        toast.success("This employee now follows the workspace or department policy.");
        await fetchData();
        return;
      }

      const payload = {
        workspace_id: activeWorkspace.id,
        scope_type: "MEMBER",
        scope_id: workspaceMemberId,
        allowed_work_locations: allowed,
        default_work_location: allowed[0],
        require_location: requireLocation,
        min_gps_accuracy_m: accuracy,
        location_id: locationId === NONE ? null : locationId,
        block_outside_geofence: locationId === NONE ? false : blockOutside,
        require_timesheet_on_punch_out: requireTimesheet,
        timesheet_template_id: templateId === NONE ? null : templateId,
      };

      // Insert or update explicitly: scope uniqueness is enforced by a
      // partial index, which onConflict cannot target.
      const { error } = policy
        ? await supabase.from("hr_attendance_policies").update(payload).eq("id", policy.id)
        : await supabase.from("hr_attendance_policies").insert(payload);
      if (error) throw error;

      toast.success("Attendance rules saved for this employee.");
      await fetchData();
    } catch (err) {
      toast.error(errorMessage(err, "Failed to save attendance rules"));
    } finally {
      setSaving(false);
    }
  };

  const handleAddOverride = async () => {
    if (!activeWorkspace?.id) return;
    setSavingOverride(true);
    try {
      const { error } = await supabase.from("hr_attendance_day_overrides").upsert(
        {
          workspace_id: activeWorkspace.id,
          workspace_member_id: workspaceMemberId,
          override_date: ovDate,
          allowed_work_locations: ovAllowWfh ? ["WFH", "OFFICE"] : ["OFFICE"],
          // A work-from-home day has no office to stand near.
          require_location: ovAllowWfh ? false : null,
          location_id: ovLocationId === INHERIT ? null : ovLocationId,
          note: ovNote || null,
        },
        { onConflict: "workspace_member_id,override_date" }
      );
      if (error) throw error;
      toast.success("Day exception saved.");
      setOvNote("");
      await fetchData();
    } catch (err) {
      toast.error(errorMessage(err, "Failed to save day exception"));
    } finally {
      setSavingOverride(false);
    }
  };

  const handleDeleteOverride = async (id: string) => {
    try {
      const { error } = await supabase
        .from("hr_attendance_day_overrides")
        .delete()
        .eq("id", id)
        .eq("workspace_id", activeWorkspace!.id);
      if (error) throw error;
      toast.success("Day exception removed.");
      await fetchData();
    } catch (err) {
      toast.error(errorMessage(err, "Failed to remove day exception"));
    }
  };

  const selectedLocation = locations.find((l) => l.id === locationId);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="size-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-5">
      <Card>
        <CardContent className="pt-6">
          <div className="flex items-center justify-between gap-4">
            <div>
              <p className="text-sm font-medium">Attendance tracking</p>
              <p className="text-xs text-muted-foreground">
                Off for people who do not clock in — directors, contractors, client users. They
                stop seeing the punch controls entirely.
              </p>
            </div>
            <Switch
              checked={attendanceEnabled}
              onCheckedChange={handleToggleAttendance}
              disabled={!canEdit || savingEnabled}
            />
          </div>
        </CardContent>
      </Card>

      {!attendanceEnabled ? (
        <p className="rounded-lg border border-dashed border-border py-10 text-center text-xs text-muted-foreground">
          Attendance is off for this employee. Switch it on to set work locations, GPS rules and
          day exceptions.
        </p>
      ) : (
      <>
      <Card>
        <CardHeader className="flex flex-row items-start justify-between gap-4">
          <div>
            <CardTitle className="flex items-center gap-2 text-base">
              <MapPin className="size-4 text-primary" /> Attendance rules
            </CardTitle>
            <CardDescription>
              Where this person may punch in from, and how precise their location must be.
            </CardDescription>
          </div>
          {canEdit && (
            <IconAction label="Save" icon={saving ? <Loader2 className="size-4 animate-spin" /> : <Save className="size-4" />} onClick={handleSave} disabled={saving} className="shrink-0 gap-1.5" />
          )}
        </CardHeader>

        <CardContent className="space-y-4">
          <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
            <div>
              <p className="text-sm font-medium">Custom rules for this employee</p>
              <p className="text-xs text-muted-foreground">
                {hasOwnPolicy
                  ? "Overrides the department and workspace policy."
                  : "Currently following the department or workspace policy."}
              </p>
            </div>
            <Switch
              checked={hasOwnPolicy}
              onCheckedChange={setHasOwnPolicy}
              disabled={!canEdit}
            />
          </div>

          {hasOwnPolicy && (
            <>
              <div className="space-y-2">
                <Label className="text-xs font-semibold">Allowed work locations</Label>
                <div className="flex flex-wrap gap-2">
                  {WORK_LOCATIONS.map((loc) => {
                    const active = allowed.includes(loc);
                    return (
                      <button
                        key={loc}
                        type="button"
                        disabled={!canEdit}
                        onClick={() => toggleAllowed(loc)}
                        className={`rounded-lg border px-3 py-1.5 text-xs font-medium transition-colors disabled:opacity-60 ${
                          active
                            ? "border-primary bg-primary text-primary-foreground"
                            : "border-border bg-background text-muted-foreground hover:text-foreground"
                        }`}
                      >
                        {WORK_LOCATION_LABELS[loc]}
                      </button>
                    );
                  })}
                </div>
                <p className="text-[11px] text-muted-foreground">
                  Select only Office and this person never sees a work-from-home option.
                </p>
              </div>

              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-1.5">
                  <Label className="text-xs font-semibold">Work location / geofence</Label>
                  <Select value={locationId} onValueChange={setLocationId} disabled={!canEdit}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value={NONE}>No boundary</SelectItem>
                      {locations.map((l) => (
                        <SelectItem key={l.id} value={l.id}>
                          {l.name} {l.latitude == null ? "(no coordinates)" : ""}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {locations.length === 0 && (
                    <p className="text-[11px] text-muted-foreground">
                      No places yet —{" "}
                      <Link href="/settings?tab=attendance" className="text-primary underline">
                        add offices and client sites
                      </Link>
                      .
                    </p>
                  )}
                  {selectedLocation && selectedLocation.latitude != null && (
                    <p className="text-[11px] text-muted-foreground">
                      Within {formatDistance(selectedLocation.radius_m)} of {selectedLocation.name}.
                    </p>
                  )}
                </div>

                <div className="space-y-1.5">
                  <Label className="text-xs font-semibold">Required GPS accuracy (metres)</Label>
                  <Input
                    type="number"
                    min={1}
                    value={minAccuracy}
                    onChange={(e) => setMinAccuracy(e.target.value)}
                    disabled={!canEdit || !requireLocation}
                  />
                </div>
              </div>

              <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
                <div>
                  <p className="text-sm font-medium">Require a location for on-site punches</p>
                  <p className="text-xs text-muted-foreground">
                    Work from home never needs one.
                  </p>
                </div>
                <Switch
                  checked={requireLocation}
                  onCheckedChange={setRequireLocation}
                  disabled={!canEdit}
                />
              </div>

              {locationId !== NONE && (
                <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
                  <div>
                    <p className="text-sm font-medium">Block punches outside the boundary</p>
                    <p className="text-xs text-muted-foreground">
                      Off: recorded and flagged for review. On: refused.
                    </p>
                  </div>
                  <Switch
                    checked={blockOutside}
                    onCheckedChange={setBlockOutside}
                    disabled={!canEdit}
                  />
                </div>
              )}

              <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
                <div>
                  <p className="text-sm font-medium">Ask for a timesheet on punch out</p>
                  <p className="text-xs text-muted-foreground">
                    Choose which questions this person answers.
                  </p>
                </div>
                <Switch
                  checked={requireTimesheet}
                  onCheckedChange={setRequireTimesheet}
                  disabled={!canEdit}
                />
              </div>

              {requireTimesheet && (
                <div className="space-y-1.5 sm:max-w-md">
                  <Label className="text-xs font-semibold">Timesheet template</Label>
                  <Select value={templateId} onValueChange={setTemplateId} disabled={!canEdit}>
                    <SelectTrigger><SelectValue placeholder="Select…" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value={NONE}>None</SelectItem>
                      {templates.map((t) => (
                        <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <CalendarPlus className="size-4 text-primary" /> Day exceptions
          </CardTitle>
          <CardDescription>
            A one-off change for a single date — work from home on Thursday, or a client site
            visit. Beats every other rule.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {canEdit && (
            <div className="grid gap-3 rounded-lg border border-border p-3 sm:grid-cols-3">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">Date</Label>
                <Input type="date" value={ovDate} onChange={(e) => setOvDate(e.target.value)} />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">Where</Label>
                <Select value={ovLocationId} onValueChange={setOvLocationId}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value={INHERIT}>Usual place</SelectItem>
                    {locations.map((l) => (
                      <SelectItem key={l.id} value={l.id}>{l.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex items-end">
                <IconAction label="Add" icon={savingOverride ? (
                    <Loader2 className="size-4 animate-spin" />
                  ) : (
                    <CalendarPlus className="size-4" />
                  )} onClick={handleAddOverride}
                  disabled={savingOverride}
                  className="w-full gap-1.5" />
              </div>

              <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3 sm:col-span-2">
                <div>
                  <p className="text-sm font-medium">Allow working from home</p>
                  <p className="text-xs text-muted-foreground">No location needed that day.</p>
                </div>
                <Switch checked={ovAllowWfh} onCheckedChange={setOvAllowWfh} />
              </div>
              <div className="space-y-1.5 sm:col-span-3">
                <Label className="text-xs font-semibold">Note (shown to the employee)</Label>
                <Input
                  value={ovNote}
                  onChange={(e) => setOvNote(e.target.value)}
                  placeholder="Approved WFH — client visit cancelled"
                />
              </div>
            </div>
          )}

          {overrides.length === 0 ? (
            <p className="py-4 text-center text-xs text-muted-foreground">
              No upcoming day exceptions.
            </p>
          ) : (
            <div className="divide-y divide-border rounded-lg border border-border">
              {overrides.map((o) => (
                <div key={o.id} className="flex items-center justify-between gap-3 px-3 py-2">
                  <div className="min-w-0">
                    <p className="text-sm font-medium">{o.override_date}</p>
                    <p className="text-xs text-muted-foreground">
                      {o.allowed_work_locations?.includes("WFH") ? "WFH allowed" : "On site"}
                      {o.location_id
                        ? ` · ${locations.find((l) => l.id === o.location_id)?.name || "Custom place"}`
                        : ""}
                      {o.note ? ` · ${o.note}` : ""}
                    </p>
                  </div>
                  {canEdit && (
                    <IconAction
                      label={`Remove the exception on ${o.override_date}`}
                      icon={<Trash2 className="size-3.5" />}
                      onClick={() => handleDeleteOverride(o.id)}
                      destructive
                    />
                  )}
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      </>
      )}

      <div className="flex items-start gap-2 rounded-lg border border-border bg-muted/30 px-3 py-2 text-xs text-muted-foreground">
        <Info className="mt-0.5 size-3.5 shrink-0" />
        <span>
          Offices and client sites are shared across the workspace and managed in{" "}
          <Link href="/settings?tab=attendance" className="text-primary underline">
            Settings &rarr; Attendance &amp; Punch
          </Link>
          . Everything on this page applies to this employee only.
        </span>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Loader2, Plus, FileText, Download } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';
import { IconAction } from "@/components/ui/icon-action";

interface EmployeeDocumentsTabProps {
  employeeId: string;
  canEdit: boolean;
}

export function EmployeeDocumentsTab({ employeeId, canEdit }: EmployeeDocumentsTabProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  
  const [documents, setDocuments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [formOpen, setFormOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  // Form State
  const [docType, setDocType] = useState('');
  const [storagePath, setStoragePath] = useState('');

  const fetchDocs = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    const { data, error } = await supabase
      .from('employee_documents')
      .select('*')
      .eq('workspace_id', activeWorkspace.id)
      .eq('workspace_member_id', employeeId)
      .order('created_at', { ascending: false });

    if (error) {
      toast.error('Failed to load documents');
    } else {
      setDocuments(data || []);
    }
    setLoading(false);
  }, [supabase, activeWorkspace?.id, employeeId]);

  useEffect(() => {
    fetchDocs();
  }, [fetchDocs]);

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeWorkspace?.id || !docType.trim() || !storagePath.trim()) return;

    setSaving(true);
    try {
      const { error } = await supabase
        .from('employee_documents')
        .insert({
          workspace_id: activeWorkspace.id,
          workspace_member_id: employeeId,
          document_type: docType.trim(),
          storage_path: storagePath.trim()
        });
      
      if (error) throw error;
      toast.success('Document recorded successfully');
      setFormOpen(false);
      setDocType('');
      setStoragePath('');
      fetchDocs();
    } catch (err: any) {
      toast.error(err.message || 'Failed to record document');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-foreground text-sm tracking-wide uppercase">Compliance & Files</h3>
        {canEdit && (
          <IconAction label="Add Document" icon={<Plus className="size-4 " />} onClick={() => setFormOpen(true)} className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm" />
        )}
      </div>

      <div className="rounded-lg border border-border overflow-hidden bg-card">
        <Table>
          <TableHeader>
            <TableRow className="border-border hover:bg-transparent">
              <TableHead className="text-muted-foreground">Document Type</TableHead>
              <TableHead className="text-muted-foreground">Uploaded On</TableHead>
              <TableHead className="text-muted-foreground w-24">Action</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-8">
                  <div className="flex flex-col items-center gap-2">
                    <Loader2 className="size-5 animate-spin text-primary" />
                  </div>
                </TableCell>
              </TableRow>
            ) : documents.length === 0 ? (
              <TableRow className="border-border">
                <TableCell colSpan={3} className="text-center py-8">
                  <div className="flex flex-col items-center gap-2">
                    <FileText className="size-6 text-muted-foreground" />
                    <p className="text-sm text-muted-foreground">No documents uploaded yet.</p>
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              documents.map((doc) => (
                <TableRow key={doc.id} className="border-border hover:bg-muted/50">
                  <TableCell className="font-medium text-foreground">{doc.document_type}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {new Date(doc.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                  </TableCell>
                  <TableCell>
                    <a href={doc.storage_path} target="_blank" rel="noopener noreferrer">
                      <IconAction
                        label="Download"
                        icon={<Download className="size-4" />}
                        variant="ghost"
                        className="hover:bg-muted text-muted-foreground hover:text-foreground"
                      />
                    </a>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={formOpen} onOpenChange={setFormOpen}>
        <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-popover-foreground">Add Document</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleUpload} className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Document Type <span className="text-red-500">*</span></Label>
              <Input 
                value={docType} 
                onChange={(e) => setDocType(e.target.value)} 
                placeholder="e.g. Identity Card, Contract" 
                className="bg-card border-border text-foreground"
                required 
              />
            </div>
            <div className="space-y-2">
              <Label>File URL / Path <span className="text-red-500">*</span></Label>
              <Input 
                type="url"
                value={storagePath} 
                onChange={(e) => setStoragePath(e.target.value)} 
                placeholder="https://..." 
                className="bg-card border-border text-foreground"
                required 
              />
              <p className="text-xs text-muted-foreground mt-1">Direct file uploads will be supported in Sprint 7.</p>
            </div>
            <DialogFooter className="pt-4 border-t border-border mt-6">
              <Button type="button" variant="outline" onClick={() => setFormOpen(false)} disabled={saving} className="border-border hover:bg-muted">Cancel</Button>
              <Button type="submit" disabled={saving || !docType.trim() || !storagePath.trim()} className="bg-primary hover:bg-primary/90 text-primary-foreground">
                {saving && <Loader2 className="size-4 animate-spin mr-2" />} Save
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { assertAffected } from '@/lib/supabase/affected-rows';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { Loader2, Save } from 'lucide-react';

interface EmployeeProfileOverviewProps {
  employee: any;
  departments: any[];
  designations: any[];
  managers: any[];
  canEdit: boolean;
  onSaved: () => void;
}

export function EmployeeProfileOverview({ 
  employee, 
  departments, 
  designations, 
  managers,
  canEdit, 
  onSaved 
}: EmployeeProfileOverviewProps) {
  const supabase = createClient();
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    employee_code: employee.employee_code || '',
    department_id: employee.department_id || 'none',
    designation_id: employee.designation_id || 'none',
    manager_workspace_member_id: employee.manager_workspace_member_id || 'none',
    joining_date: employee.joining_date || '',
    employment_type: employee.employment_type || '',
    salary_grade: employee.salary_grade || '',
    status: employee.status || 'ACTIVE',
    address: employee.address || '',
    notes: employee.notes || ''
  });

  const handleChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canEdit) return;
    setSaving(true);

    try {
      const payload = {
        ...formData,
        department_id: formData.department_id === 'none' ? null : formData.department_id,
        designation_id: formData.designation_id === 'none' ? null : formData.designation_id,
        manager_workspace_member_id: formData.manager_workspace_member_id === 'none' ? null : formData.manager_workspace_member_id,
        joining_date: formData.joining_date || null
      };

      const result = await supabase
        .from('employee_profiles')
        .update(payload)
        .eq('workspace_member_id', employee.workspace_member_id)
        .select('workspace_member_id');

      assertAffected(result, 'this employee', 'save');
      toast.success('Profile updated successfully');
      onSaved();
    } catch (err: any) {
      toast.error(err.message || 'Failed to update profile');
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        
        {/* Core HR Details */}
        <div className="space-y-6">
          <div className="bg-card rounded-lg border border-border p-5 space-y-4">
            <h3 className="font-semibold text-foreground text-sm tracking-wide uppercase">Core Employment</h3>
            
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Employee ID (Code)</Label>
                <Input 
                  value={formData.employee_code}
                  onChange={(e) => handleChange('employee_code', e.target.value)}
                  disabled={!canEdit}
                  placeholder="EMP-0001"
                />
              </div>
              <div className="space-y-2">
                <Label>Employment Status</Label>
                <Select disabled={!canEdit} value={formData.status} onValueChange={(val) => handleChange('status', val)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ACTIVE">Active</SelectItem>
                    <SelectItem value="INACTIVE">Inactive</SelectItem>
                    <SelectItem value="ON_LEAVE">On Leave</SelectItem>
                    <SelectItem value="TERMINATED">Terminated</SelectItem>
                    <SelectItem value="PROBATION">Probation</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Department</Label>
                <Select disabled={!canEdit} value={formData.department_id} onValueChange={(val) => handleChange('department_id', val)}>
                  <SelectTrigger><SelectValue placeholder="Select Department" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">-- None --</SelectItem>
                    {departments.map(d => (
                      <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Designation</Label>
                <Select disabled={!canEdit} value={formData.designation_id} onValueChange={(val) => handleChange('designation_id', val)}>
                  <SelectTrigger><SelectValue placeholder="Select Designation" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">-- None --</SelectItem>
                    {designations.map(d => (
                      <SelectItem key={d.id} value={d.id}>{d.title}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Manager</Label>
                <Select disabled={!canEdit} value={formData.manager_workspace_member_id} onValueChange={(val) => handleChange('manager_workspace_member_id', val)}>
                  <SelectTrigger><SelectValue placeholder="Select Manager" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">-- None --</SelectItem>
                    {managers.filter(m => m.workspace_member_id !== employee.workspace_member_id).map(m => {
                      const profile = Array.isArray(m.workspace_members?.profiles) ? m.workspace_members.profiles[0] : m.workspace_members?.profiles;
                      return (
                        <SelectItem key={m.workspace_member_id} value={m.workspace_member_id}>
                          {profile?.full_name || 'Unknown User'}
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Joining Date</Label>
                <Input 
                  type="date"
                  value={formData.joining_date}
                  onChange={(e) => handleChange('joining_date', e.target.value)}
                  disabled={!canEdit}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Secondary Details */}
        <div className="space-y-6">
          <div className="bg-card rounded-lg border border-border p-5 space-y-4">
            <h3 className="font-semibold text-foreground text-sm tracking-wide uppercase">Compensation & Personal</h3>
            
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Employment Type</Label>
                <Input 
                  value={formData.employment_type}
                  onChange={(e) => handleChange('employment_type', e.target.value)}
                  disabled={!canEdit}
                  placeholder="Full-Time, Contract, etc."
                />
              </div>
              <div className="space-y-2">
                <Label>Salary Grade / Band</Label>
                <Input 
                  value={formData.salary_grade}
                  onChange={(e) => handleChange('salary_grade', e.target.value)}
                  disabled={!canEdit}
                  placeholder="L1, L2, etc."
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Address</Label>
              <Textarea 
                value={formData.address}
                onChange={(e) => handleChange('address', e.target.value)}
                disabled={!canEdit}
                rows={2}
                className="resize-none"
              />
            </div>
            <div className="space-y-2">
              <Label>HR Notes</Label>
              <Textarea 
                value={formData.notes}
                onChange={(e) => handleChange('notes', e.target.value)}
                disabled={!canEdit}
                rows={3}
                className="resize-none"
              />
            </div>
          </div>
        </div>
      </div>

      {canEdit && (
        <div className="flex justify-end pt-4 border-t border-border">
          <Button type="submit" disabled={saving}>
            {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : <Save className="size-4 mr-2" />}
            Save Changes
          </Button>
        </div>
      )}
    </form>
  );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { computeSalaryBreakdown, type SalaryComponent } from '@/lib/hr/salary';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2 } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';

interface OnboardEmployeeFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved: () => void;
}

export function OnboardEmployeeForm({ open, onOpenChange, onSaved }: OnboardEmployeeFormProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [loadingDeps, setLoadingDeps] = useState(true);
  
  // Data lists
  const [availableMembers, setAvailableMembers] = useState<any[]>([]);
  // Managers must be people who ALREADY have an employee record — the
  // opposite of availableMembers, which holds only members not yet
  // onboarded.
  const [managerOptions, setManagerOptions] = useState<{ id: string; full_name: string }[]>([]);
  // Assigning a salary structure at hire derives HRA, allowances and the
  // statutory deductions from basic, instead of leaving someone to type
  // six figures by hand and get them inconsistent with the slab.
  const [structures, setStructures] = useState<{ id: string; name: string }[]>([]);
  const [structureId, setStructureId] = useState('');
  const [structureComponents, setStructureComponents] = useState<SalaryComponent[]>([]);
  const [departments, setDepartments] = useState<any[]>([]);
  const [designations, setDesignations] = useState<any[]>([]);

  // Form State
  const [saving, setSaving] = useState(false);
  const [memberId, setMemberId] = useState('');
  const [employeeCode, setEmployeeCode] = useState('');
  const [departmentId, setDepartmentId] = useState('');
  const [designationId, setDesignationId] = useState('');
  const [joiningDate, setJoiningDate] = useState('');
  const [employmentType, setEmploymentType] = useState('FULL_TIME');
  // Present on the employee record and editable on the detail page, but
  // never collected at onboarding — so every new hire started with a
  // blank manager, grade, address and notes that someone had to go back
  // and fill in.
  const [managerId, setManagerId] = useState('');
  const [salaryGrade, setSalaryGrade] = useState('');
  const [address, setAddress] = useState('');
  const [emergencyContact, setEmergencyContact] = useState('');
  const [notes, setNotes] = useState('');
  const [status, setStatus] = useState('ACTIVE');
  
  // Salary Breakdown
  const [basicSalary, setBasicSalary] = useState('');
  const [professionalTax, setProfessionalTax] = useState('');
  const [attendanceEnabled, setAttendanceEnabled] = useState(true);
  const [hra, setHra] = useState('');
  const [allowances, setAllowances] = useState('');
  const [pfDeduction, setPfDeduction] = useState('');
  const [tds, setTds] = useState('');

  useEffect(() => {
    if (open && activeWorkspace?.id) {
      loadDependencies();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, activeWorkspace?.id]);

  async function loadDependencies() {
    setLoadingDeps(true);
    try {
      // 1. Fetch departments
      const { data: deps } = await supabase.from('departments').select('*').eq('workspace_id', activeWorkspace!.id);
      
      // 2. Fetch designations
      const { data: desigs } = await supabase.from('designations').select('*').eq('workspace_id', activeWorkspace!.id);
      
      // 3. Fetch workspace members via API to guarantee full name & email resolution
      let members: any[] = [];
      try {
        const res = await fetch(`/api/account/members?workspace_id=${activeWorkspace!.id}`);
        if (res.ok) {
          const json = await res.json();
          members = json.members || [];
        }
      } catch (err) {
        console.warn('Members API fetch failed, using fallback:', err);
      }

      if (members.length === 0) {
        const { data: rawMembers } = await supabase
          .from('workspace_members')
          .select('id, user_id')
          .eq('workspace_id', activeWorkspace!.id);

        if (rawMembers && rawMembers.length > 0) {
          const userIds = rawMembers.map((m: any) => m.user_id);
          const { data: profilesData } = await supabase
            .from('profiles')
            .select('user_id, full_name, email')
            .in('user_id', userIds);
          const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
          members = rawMembers.map((m: any) => {
            const p = profileMap[m.user_id];
            return {
              id: m.id,
              user_id: m.user_id,
              full_name: p?.full_name?.trim() || p?.email?.split('@')[0] || 'Workspace Member',
              email: p?.email || null,
            };
          });
        }
      }

      // 4. Fetch existing employee profiles
      const { data: profiles } = await supabase
        .from('employee_profiles')
        .select('workspace_member_id')
        .eq('workspace_id', activeWorkspace!.id);

      const existingIds = new Set((profiles || []).map(p => p.workspace_member_id));
      
      // Filter members who DO NOT have an employee profile yet
      const unassigned = members.filter(m => !existingIds.has(m.id));

      const { data: structs } = await supabase
        .from('hr_salary_structures')
        .select('id, name')
        .eq('workspace_id', activeWorkspace!.id)
        .is('deleted_at', null)
        .order('name');
      setStructures(structs || []);

      setDepartments(deps || []);
      setDesignations(desigs || []);
      setAvailableMembers(unassigned);
      setManagerOptions(members.filter(m => existingIds.has(m.id)));
    } catch {
      toast.error('Failed to load form requirements');
    } finally {
      setLoadingDeps(false);
    }
  }

  // Load the chosen structure's components so the breakdown can be derived.
  useEffect(() => {
    if (!structureId) { setStructureComponents([]); return; }
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from('hr_salary_structure_components')
        .select('value_override, calculation_type, hr_salary_components(id, name, code, type, calculation_type, value_number, is_statutory, payroll_field, sort_order)')
        .eq('structure_id', structureId);
      if (cancelled) return;
      type JoinRow = {
        value_override: number | null;
        calculation_type: string | null;
        hr_salary_components: SalaryComponent | SalaryComponent[] | null;
      };
      setStructureComponents(
        ((data as JoinRow[] | null) || [])
          .map((row) => {
            // PostgREST returns an object for a to-one embed but an array
            // when it cannot prove cardinality.
            const comp = Array.isArray(row.hr_salary_components)
              ? row.hr_salary_components[0]
              : row.hr_salary_components;
            if (!comp) return null;
            return {
              ...comp,
              value_number: row.value_override ?? comp.value_number,
              calculation_type: (row.calculation_type ||
                comp.calculation_type) as SalaryComponent['calculation_type'],
            } as SalaryComponent;
          })
          .filter((c): c is SalaryComponent => c !== null)
      );
    })();
    return () => { cancelled = true; };
  }, [structureId, supabase]);

  const derived = useMemo(
    () => computeSalaryBreakdown(structureComponents, Number(basicSalary) || 0),
    [structureComponents, basicSalary]
  );

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!activeWorkspace?.id || !memberId || !departmentId || !designationId || !joiningDate) return;

    setSaving(true);
    
    try {
      const { error } = await supabase
        .from('employee_profiles')
        .insert({
          workspace_id: activeWorkspace.id,
          workspace_member_id: memberId,
          employee_code: employeeCode.trim() || null,
          department_id: departmentId,
          designation_id: designationId,
          joining_date: joiningDate,
          employment_type: employmentType,
          // Salary goes into the real columns (077) — payroll reads
          // exclusively from these. It used to be serialized as JSON
          // into the free-text salary_grade band field, which meant
          // every onboarded employee was silently excluded from
          // payroll runs.
          // A structure is authoritative: its derived figures replace the
          // manual boxes so the two can never disagree.
          ...(structureId
            ? { ...derived.payrollFields, salary_structure_id: structureId, ctc_annual: derived.ctcAnnual }
            : {
                basic_salary: Number(basicSalary) || 0,
                hra: Number(hra) || 0,
                special_allowance: Number(allowances) || 0,
                pf_deduction: Number(pfDeduction) || 0,
                tds_deduction: Number(tds) || 0,
              }),
          salary_effective_from: joiningDate || null,
          // professional_tax exists in 077 and the payroll processor reads
          // it, but this form never collected it — it silently stayed 0
          // for every onboarded employee.
          ...(structureId ? {} : { professional_tax: Number(professionalTax) || 0 }),
          attendance_enabled: attendanceEnabled,
          manager_workspace_member_id: managerId || null,
          salary_grade: salaryGrade.trim() || null,
          address: address.trim() || null,
          emergency_contact: emergencyContact.trim() || null,
          notes: notes.trim() || null,
          status
        });

      if (error) throw error;
      
      toast.success('Employee onboarded successfully!');
      
      // Reset form
      setMemberId('');
      setEmployeeCode('');
      setDepartmentId('');
      setDesignationId('');
      setJoiningDate('');
      setBasicSalary('');
      setHra('');
      setAllowances('');
      setPfDeduction('');
      setTds('');
      
      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to onboard employee');
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-popover-foreground">
            HR Onboarding
          </DialogTitle>
        </DialogHeader>
        
        {loadingDeps ? (
          <div className="py-12 flex justify-center">
            <Loader2 className="size-6 animate-spin text-primary" />
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 py-4">
            
            <div className="space-y-2">
              <Label>Select Workspace Member <span className="text-red-500">*</span></Label>
              {availableMembers.length === 0 ? (
                <div className="text-sm text-amber-500 bg-amber-500/10 p-3 rounded-md border border-amber-500/20">
                  No pending members available. Invite someone via Workspace Settings first.
                </div>
              ) : (
                <Select value={memberId} onValueChange={(v) => setMemberId(v || '')} required>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue placeholder="Select a member..." />
                  </SelectTrigger>
                  <SelectContent>
                    {availableMembers.map(m => {
                      const rawName = m.full_name?.trim() || (Array.isArray(m.profiles) ? m.profiles[0]?.full_name : m.profiles?.full_name);
                      const email = m.email || (Array.isArray(m.profiles) ? m.profiles[0]?.email : m.profiles?.email);

                      let name = rawName;
                      if (!name || ['workspace member', 'member', 'user', 'unknown user'].includes(name.toLowerCase())) {
                        if (email) {
                          const local = email.split('@')[0];
                          name = local.charAt(0).toUpperCase() + local.slice(1);
                        } else {
                          name = `Member (${m.id.slice(0, 6)})`;
                        }
                      }

                      return (
                        <SelectItem key={m.id} value={m.id}>
                          {name} {email && !name.toLowerCase().includes(email.toLowerCase()) ? `(${email})` : ''}
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              )}
            </div>

            <div className="space-y-2">
              <Label>Employee Code (ID)</Label>
              <Input
                value={employeeCode}
                onChange={(e) => setEmployeeCode(e.target.value)}
                placeholder="e.g. EMP-042"
                className="bg-card border-border"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Department <span className="text-red-500">*</span></Label>
                <Select value={departmentId} onValueChange={(v) => setDepartmentId(v || '')} required>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue placeholder="Select..." />
                  </SelectTrigger>
                  <SelectContent>
                    {departments.map(d => (
                      <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Designation <span className="text-red-500">*</span></Label>
                <Select value={designationId} onValueChange={(v) => setDesignationId(v || '')} required>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue placeholder="Select..." />
                  </SelectTrigger>
                  <SelectContent>
                    {designations.map(d => (
                      <SelectItem key={d.id} value={d.id}>{d.title || d.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Reporting Manager</Label>
                <Select value={managerId} onValueChange={(v) => setManagerId(v || '')}>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue placeholder="No manager" />
                  </SelectTrigger>
                  <SelectContent>
                    {managerOptions.length === 0 ? (
                      <SelectItem value="" disabled>
                        No onboarded employees yet
                      </SelectItem>
                    ) : (
                      managerOptions.map((m: { id: string; full_name: string }) => (
                        <SelectItem key={m.id} value={m.id}>
                          {m.full_name}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Employment Status</Label>
                <Select value={status} onValueChange={(v) => setStatus(v || 'ACTIVE')}>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ACTIVE">Active</SelectItem>
                    <SelectItem value="PROBATION">Probation</SelectItem>
                    <SelectItem value="NOTICE_PERIOD">Notice period</SelectItem>
                    <SelectItem value="INACTIVE">Inactive</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Salary Grade / Band</Label>
                <Input
                  value={salaryGrade}
                  onChange={(e) => setSalaryGrade(e.target.value)}
                  placeholder="e.g. L3"
                  className="bg-card border-border text-foreground"
                />
              </div>

              <div className="space-y-2">
                <Label>Emergency Contact</Label>
                <Input
                  value={emergencyContact}
                  onChange={(e) => setEmergencyContact(e.target.value)}
                  placeholder="Name and phone"
                  className="bg-card border-border text-foreground"
                />
              </div>

              <div className="space-y-2 col-span-2">
                <Label>Address</Label>
                <Input
                  value={address}
                  onChange={(e) => setAddress(e.target.value)}
                  placeholder="Residential address"
                  className="bg-card border-border text-foreground"
                />
              </div>

              <div className="space-y-2 col-span-2">
                <Label>Notes</Label>
                {/* `plain`: stored as text and rendered as text on the
                    employee record, so the rich-text editor would wrap it
                    in HTML that then shows as markup. */}
                <Textarea
                  plain
                  rows={2}
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Anything HR should know"
                  className="bg-card border-border text-foreground"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Joining Date <span className="text-red-500">*</span></Label>
                <Input
                  type="date"
                  value={joiningDate}
                  onChange={(e) => setJoiningDate(e.target.value)}
                  className="bg-card border-border text-foreground"
                  required
                />
              </div>

              <div className="space-y-2">
                <Label>Type <span className="text-red-500">*</span></Label>
                <Select value={employmentType} onValueChange={(v) => setEmploymentType(v || '')} required>
                  <SelectTrigger className="bg-card border-border">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="FULL_TIME">Full Time</SelectItem>
                    <SelectItem value="PART_TIME">Part Time</SelectItem>
                    <SelectItem value="CONTRACTOR">Contractor</SelectItem>
                    <SelectItem value="INTERN">Intern</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="pt-4 border-t border-border mt-4">
              <Label className="text-muted-foreground font-semibold mb-3 block">Salary Breakdown (Monthly)</Label>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Basic Salary <span className="text-red-500">*</span></Label>
                  <Input type="number" value={basicSalary} onChange={(e) => setBasicSalary(e.target.value)} placeholder="e.g. 25000" className="bg-card border-border" required />
                </div>
                <div className="space-y-2 sm:col-span-2">
                  <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
                    <div>
                      <p className="text-sm font-medium">Attendance tracking</p>
                      <p className="text-xs text-muted-foreground">
                        Leave off for people who do not clock in — they never see the punch controls.
                      </p>
                    </div>
                    <Switch checked={attendanceEnabled} onCheckedChange={setAttendanceEnabled} />
                  </div>
                </div>
                <div className="space-y-2 sm:col-span-2">
                  <Label>Salary Structure</Label>
                  <Select value={structureId} onValueChange={(v) => setStructureId(v || '')}>
                    <SelectTrigger className="bg-card border-border">
                      <SelectValue placeholder="None — enter the amounts by hand" />
                    </SelectTrigger>
                    <SelectContent>
                      {structures.length === 0 ? (
                        <SelectItem value="" disabled>No structures defined yet</SelectItem>
                      ) : (
                        structures.map((st) => (
                          <SelectItem key={st.id} value={st.id}>{st.name}</SelectItem>
                        ))
                      )}
                    </SelectContent>
                  </Select>
                  {structureId && (
                    <p className="text-[11px] text-muted-foreground">
                      Derived from basic: gross {derived.grossMonthly.toLocaleString()} ·
                      deductions {derived.totalDeductions.toLocaleString()} ·
                      net {derived.netMonthly.toLocaleString()} · CTC{' '}
                      {derived.ctcAnnual.toLocaleString()}/yr. The boxes below are ignored while a
                      structure is selected.
                    </p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label>Professional Tax</Label>
                  <Input type="number" value={professionalTax} onChange={(e) => setProfessionalTax(e.target.value)} placeholder="e.g. 200" className="bg-card border-border" />
                </div>
                <div className="space-y-2">
                  <Label>HRA (House Rent)</Label>
                  <Input type="number" value={hra} onChange={(e) => setHra(e.target.value)} placeholder="e.g. 10000" className="bg-card border-border" />
                </div>
                <div className="space-y-2">
                  <Label>Special Allowances / LTA</Label>
                  <Input type="number" value={allowances} onChange={(e) => setAllowances(e.target.value)} placeholder="e.g. 15000" className="bg-card border-border" />
                </div>
                <div className="space-y-2">
                  <Label>PF Deduction</Label>
                  <Input type="number" value={pfDeduction} onChange={(e) => setPfDeduction(e.target.value)} placeholder="e.g. 1800" className="bg-card border-border" />
                </div>
                <div className="space-y-2">
                  <Label>TDS (Income Tax)</Label>
                  <Input type="number" value={tds} onChange={(e) => setTds(e.target.value)} placeholder="e.g. 2000" className="bg-card border-border" />
                </div>
              </div>
            </div>

            <DialogFooter className="pt-4 border-t border-border mt-6">
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
                className="border-border text-muted-foreground hover:bg-muted"
                disabled={saving}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                className="bg-primary hover:bg-primary/90 text-primary-foreground"
                disabled={saving || !memberId || availableMembers.length === 0}
              >
                {saving && <Loader2 className="size-4 animate-spin mr-2" />}
                Complete Onboarding
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

/**
 * Per-node configuration form, dispatched by node_type.
 *
 * One component, ten branches. Each branch renders the inputs that
 * map onto the node's `config` JSONB shape (text + buttons for
 * send_buttons, prompt + var_key for collect_input, etc.) and forwards
 * edits up via `onUpdateConfig`.
 *
 * Why this lives in src/components/flows/forms/ instead of next to
 * the list editor: PR 2 (canvas editing) needs to mount the same
 * form in a side panel when a user clicks a node on the canvas.
 * Keeping the per-node forms here means there's exactly one place
 * where each form's behaviour and validation lives — drift between
 * "what the list editor shows" and "what the canvas side panel
 * shows" becomes impossible.
 *
 * `showAdvanced` is the disclosure that surfaces internal
 * identifiers (node_key, button reply_id, list row reply_id) — owned
 * by the host (NodeCard / SideSheet) so the toggle is rendered
 * outside this form alongside whatever delete/cancel buttons that
 * host wants. The form just reads the boolean and conditionally
 * renders the advanced rows.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import {
  Loader2,
  Paperclip,
  Plus,
  Trash2,
  Upload,
  X,
} from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { uploadAccountMedia, MEDIA_MAX_BYTES } from "@/lib/storage/upload-media";
import { slugify, type BuilderNode } from "../shared";
import { NextNodeRow, NodeKeySelect, TextRow } from "./fields";
import { IconAction } from "@/components/ui/icon-action";

interface NodeConfigFormProps {
  node: BuilderNode;
  allNodes: BuilderNode[];
  showAdvanced: boolean;
  onUpdateConfig: (patch: Record<string, unknown>) => void;
}

export function NodeConfigForm({
  node,
  allNodes,
  showAdvanced,
  onUpdateConfig,
}: NodeConfigFormProps) {
  const cfg = node.config;
  switch (node.node_type) {
    case "start":
      return (
        <NextNodeRow
          value={(cfg as { next_node_key?: string }).next_node_key ?? ""}
          allNodes={allNodes}
          currentKey={node.node_key}
          onChange={(v) => onUpdateConfig({ next_node_key: v })}
          label="Advances to"
        />
      );

    case "send_message":
      return (
        <>
          <TextRow
            label="Text sent to the customer"
            value={(cfg as { text?: string }).text ?? ""}
            onChange={(v) => onUpdateConfig({ text: v })}
          />
          <NextNodeRow
            value={(cfg as { next_node_key?: string }).next_node_key ?? ""}
            allNodes={allNodes}
            currentKey={node.node_key}
            onChange={(v) => onUpdateConfig({ next_node_key: v })}
            label="Advances to"
          />
        </>
      );

    case "send_buttons":
      return (
        <SendButtonsForm
          cfg={cfg as SendButtonsCfg}
          allNodes={allNodes}
          currentKey={node.node_key}
          onUpdateConfig={onUpdateConfig}
          showAdvanced={showAdvanced}
        />
      );

    case "send_list":
      return (
        <SendListForm
          cfg={cfg as SendListCfg}
          allNodes={allNodes}
          currentKey={node.node_key}
          onUpdateConfig={onUpdateConfig}
          showAdvanced={showAdvanced}
        />
      );

    case "send_media":
      return (
        <SendMediaForm
          cfg={cfg as SendMediaCfg}
          allNodes={allNodes}
          currentKey={node.node_key}
          onUpdateConfig={onUpdateConfig}
        />
      );

    case "collect_input":
      return (
        <>
          <TextRow
            label="Prompt sent to the customer"
            value={(cfg as { prompt_text?: string }).prompt_text ?? ""}
            onChange={(v) => onUpdateConfig({ prompt_text: v })}
            rows={2}
          />
          <div>
            <label className="mb-1 block text-xs text-muted-foreground">
              Variable key (stored in flow_runs.vars; alphanumeric + underscore)
            </label>
            <Input
              value={(cfg as { var_key?: string }).var_key ?? ""}
              onChange={(e) =>
                onUpdateConfig({
                  var_key: e.target.value.replace(/[^a-zA-Z0-9_]/g, ""),
                })
              }
              placeholder="e.g. name, email, company"
              className="bg-muted font-mono text-xs"
            />
            <p className="mt-1 text-[10px] text-muted-foreground">
              Interpolate in downstream prompts and handoff notes with{" "}
              <code className="rounded-none bg-muted px-1">
                {"{{vars."}
                {(cfg as { var_key?: string }).var_key || "name"}
                {"}}"}
              </code>
              .
            </p>
          </div>
          <NextNodeRow
            value={(cfg as { next_node_key?: string }).next_node_key ?? ""}
            allNodes={allNodes}
            currentKey={node.node_key}
            onChange={(v) => onUpdateConfig({ next_node_key: v })}
            label="After capturing, advance to"
          />
        </>
      );

    case "condition":
      return (
        <ConditionForm
          cfg={cfg as ConditionCfg}
          allNodes={allNodes}
          currentKey={node.node_key}
          onUpdateConfig={onUpdateConfig}
        />
      );

    case "set_tag":
      return (
        <SetTagForm
          cfg={cfg as SetTagCfg}
          allNodes={allNodes}
          currentKey={node.node_key}
          onUpdateConfig={onUpdateConfig}
        />
      );

    case "handoff":
      return (
        <TextRow
          label="Internal note (for the agent picking up)"
          value={(cfg as { note?: string }).note ?? ""}
          onChange={(v) => onUpdateConfig({ note: v })}
          rows={2}
        />
      );

    case "end":
      return (
        <p className="text-xs text-muted-foreground">
          Terminal node. When the runner reaches this node the run is marked
          complete. No config needed.
        </p>
      );
  }
}

// ============================================================
// send_buttons
// ============================================================

interface SendButtonsCfg {
  text?: string;
  footer_text?: string;
  buttons?: Array<{ reply_id: string; title: string; next_node_key: string }>;
}

function SendButtonsForm({
  cfg,
  allNodes,
  currentKey,
  onUpdateConfig,
  showAdvanced,
}: {
  cfg: SendButtonsCfg;
  allNodes: BuilderNode[];
  currentKey: string;
  onUpdateConfig: (patch: Record<string, unknown>) => void;
  showAdvanced: boolean;
}) {
  const buttons = cfg.buttons ?? [];
  const updateButton = (
    idx: number,
    patch: Partial<NonNullable<SendButtonsCfg["buttons"]>[number]>,
  ) => {
    onUpdateConfig({
      buttons: buttons.map((b, i) => (i === idx ? { ...b, ...patch } : b)),
    });
  };
  const addButton = () =>
    onUpdateConfig({
      buttons: [
        ...buttons,
        {
          reply_id: `btn_${buttons.length + 1}`,
          title: "Option",
          next_node_key: "",
        },
      ],
    });
  const removeButton = (idx: number) =>
    onUpdateConfig({ buttons: buttons.filter((_, i) => i !== idx) });

  return (
    <>
      <TextRow
        label="Body text"
        value={cfg.text ?? ""}
        onChange={(v) => onUpdateConfig({ text: v })}
        rows={3}
      />
      <TextRow
        label="Footer (optional, 60 chars)"
        value={cfg.footer_text ?? ""}
        onChange={(v) => onUpdateConfig({ footer_text: v })}
      />
      <div>
        <div className="mb-2 flex items-center justify-between">
          <label className="text-xs text-muted-foreground">
            Buttons (1–3) — each one routes to a different next node
          </label>
        </div>
        <div className="flex flex-col gap-3">
          {buttons.map((b, i) => (
            <div
              key={i}
              className={cn(
                "grid grid-cols-1 gap-2 rounded-md border border-border bg-muted/40 p-3",
                showAdvanced
                  ? "md:grid-cols-[1fr_2fr_2fr_auto]"
                  : "md:grid-cols-[2fr_2fr_auto]",
              )}
            >
              {showAdvanced && (
                <Input
                  value={b.reply_id}
                  onChange={(e) =>
                    updateButton(i, {
                      reply_id: slugify(e.target.value, `btn_${i + 1}`),
                    })
                  }
                  placeholder="reply_id"
                  className="bg-muted font-mono text-xs"
                />
              )}
              <Input
                value={b.title}
                onChange={(e) => updateButton(i, { title: e.target.value })}
                placeholder="Visible title (≤20 chars)"
                className="bg-muted"
                maxLength={20}
              />
              <NodeKeySelect
                value={b.next_node_key || null}
                nodes={allNodes}
                excludeKey={currentKey}
                onChange={(v) => updateButton(i, { next_node_key: v ?? "" })}
                placeholder="Next node…"
              />
              <IconAction
                label="Delete"
                icon={<Trash2 className="h-3.5 w-3.5" />}
                variant="ghost"
                onClick={() => removeButton(i)}
                className="text-red-400 hover:bg-red-500/10 hover:text-red-300"
              />
            </div>
          ))}
        </div>
        {buttons.length < 3 && (
          <IconAction label="Add button" icon={<Plus className="h-3.5 w-3.5" />} variant="ghost"
            onClick={addButton}
            className="mt-2" />
        )}
      </div>
    </>
  );
}

// ============================================================
// send_list
// ============================================================

interface SendListCfg {
  text?: string;
  button_label?: string;
  footer_text?: string;
  sections?: Array<{
    title?: string;
    rows: Array<{
      reply_id: string;
      title: string;
      description?: string;
      next_node_key: string;
    }>;
  }>;
}

function SendListForm({
  cfg,
  allNodes,
  currentKey,
  onUpdateConfig,
  showAdvanced,
}: {
  cfg: SendListCfg;
  allNodes: BuilderNode[];
  currentKey: string;
  onUpdateConfig: (patch: Record<string, unknown>) => void;
  showAdvanced: boolean;
}) {
  const sections = cfg.sections ?? [];
  const totalRows = sections.reduce((sum, s) => sum + s.rows.length, 0);

  const updateSection = (
    sIdx: number,
    patch: Partial<NonNullable<SendListCfg["sections"]>[number]>,
  ) => {
    onUpdateConfig({
      sections: sections.map((s, i) =>
        i === sIdx ? { ...s, ...patch } : s,
      ),
    });
  };
  const addSection = () =>
    onUpdateConfig({
      sections: [
        ...sections,
        {
          title: "",
          rows: [
            {
              reply_id: `row_${totalRows + 1}`,
              title: `Option ${totalRows + 1}`,
              next_node_key: "",
            },
          ],
        },
      ],
    });
  const removeSection = (sIdx: number) =>
    onUpdateConfig({ sections: sections.filter((_, i) => i !== sIdx) });
  const updateRow = (
    sIdx: number,
    rIdx: number,
    patch: Partial<
      NonNullable<SendListCfg["sections"]>[number]["rows"][number]
    >,
  ) => {
    onUpdateConfig({
      sections: sections.map((s, i) =>
        i === sIdx
          ? {
              ...s,
              rows: s.rows.map((r, j) => (j === rIdx ? { ...r, ...patch } : r)),
            }
          : s,
      ),
    });
  };
  const addRow = (sIdx: number) =>
    onUpdateConfig({
      sections: sections.map((s, i) =>
        i === sIdx
          ? {
              ...s,
              rows: [
                ...s.rows,
                {
                  reply_id: `row_${totalRows + 1}`,
                  title: `Option ${totalRows + 1}`,
                  next_node_key: "",
                },
              ],
            }
          : s,
      ),
    });
  const removeRow = (sIdx: number, rIdx: number) =>
    onUpdateConfig({
      sections: sections.map((s, i) =>
        i === sIdx ? { ...s, rows: s.rows.filter((_, j) => j !== rIdx) } : s,
      ),
    });

  return (
    <>
      <TextRow
        label="Body text"
        value={cfg.text ?? ""}
        onChange={(v) => onUpdateConfig({ text: v })}
        rows={3}
      />
      <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
        <TextRow
          label="Tap-to-expand button label (≤20 chars)"
          value={cfg.button_label ?? ""}
          onChange={(v) => onUpdateConfig({ button_label: v })}
        />
        <TextRow
          label="Footer (optional, 60 chars)"
          value={cfg.footer_text ?? ""}
          onChange={(v) => onUpdateConfig({ footer_text: v })}
        />
      </div>

      <div className="mt-2">
        <label className="mb-2 block text-xs text-muted-foreground">
          Rows (1–10 total across all sections)
        </label>
        {sections.map((section, sIdx) => (
          <div
            key={sIdx}
            className="mb-3 rounded-md border border-border bg-muted/40 p-3"
          >
            <div className="mb-2 flex items-center gap-2">
              <Input
                value={section.title ?? ""}
                onChange={(e) =>
                  updateSection(sIdx, { title: e.target.value })
                }
                placeholder={`Section ${sIdx + 1} title (optional)`}
                className="bg-muted text-xs"
              />
              {sections.length > 1 && (
                <IconAction
                  label="Remove section"
                  icon={<Trash2 className="h-3.5 w-3.5" />}
                  variant="ghost"
                  onClick={() => removeSection(sIdx)}
                  className="shrink-0 text-red-400 hover:bg-red-500/10 hover:text-red-300"
                />
              )}
            </div>
            {section.rows.map((row, rIdx) => (
              <div
                key={rIdx}
                className={cn(
                  "mb-2 grid grid-cols-1 gap-2",
                  showAdvanced
                    ? "md:grid-cols-[1fr_2fr_2fr_auto]"
                    : "md:grid-cols-[2fr_2fr_auto]",
                )}
              >
                {showAdvanced && (
                  <Input
                    value={row.reply_id}
                    onChange={(e) =>
                      updateRow(sIdx, rIdx, {
                        reply_id: slugify(
                          e.target.value,
                          `row_${rIdx + 1}`,
                        ),
                      })
                    }
                    placeholder="reply_id"
                    className="bg-muted font-mono text-xs"
                  />
                )}
                <Input
                  value={row.title}
                  onChange={(e) =>
                    updateRow(sIdx, rIdx, { title: e.target.value })
                  }
                  placeholder="Row title (≤24)"
                  className="bg-muted"
                  maxLength={24}
                />
                <NodeKeySelect
                  value={row.next_node_key || null}
                  nodes={allNodes}
                  excludeKey={currentKey}
                  onChange={(v) =>
                    updateRow(sIdx, rIdx, { next_node_key: v ?? "" })
                  }
                  placeholder="Next node…"
                />
                <IconAction
                  label="Delete"
                  icon={<Trash2 className="h-3.5 w-3.5" />}
                  variant="ghost"
                  onClick={() => removeRow(sIdx, rIdx)}
                  className="text-red-400 hover:bg-red-500/10 hover:text-red-300"
                />
              </div>
            ))}
            {totalRows < 10 && (
              <IconAction label="Add row" icon={<Plus className="h-3.5 w-3.5" />} variant="ghost"
                onClick={() => addRow(sIdx)}
                className="mt-1" />
            )}
          </div>
        ))}
        {/* WhatsApp's interactive-list spec caps sections at 10. Group rows
            by category (Billing / Support / Sales etc.) to give customers a
            scannable menu. */}
        {sections.length < 10 && (
          <IconAction label="Add section" icon={<Plus className="h-3.5 w-3.5" />} variant="outline" onClick={addSection} />
        )}
      </div>
    </>
  );
}

// ============================================================
// condition
// ============================================================

interface ConditionCfg {
  subject?: "var" | "tag" | "contact_field";
  subject_key?: string;
  operator?: "equals" | "contains" | "present" | "absent";
  value?: string;
  true_next?: string;
  false_next?: string;
}

interface UserTag {
  id: string;
  name: string;
  color?: string;
}

function ConditionForm({
  cfg,
  allNodes,
  currentKey,
  onUpdateConfig,
}: {
  cfg: ConditionCfg;
  allNodes: BuilderNode[];
  currentKey: string;
  onUpdateConfig: (patch: Record<string, unknown>) => void;
}) {
  const tags = useUserTags();

  const subject = cfg.subject ?? "var";
  const operator = cfg.operator ?? "equals";
  const showValue = operator === "equals" || operator === "contains";

  return (
    <>
      <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
        <div>
          <label className="mb-1 block text-xs text-muted-foreground">If</label>
          <Select
            value={subject}
            onValueChange={(v) =>
              onUpdateConfig({ subject: v as ConditionCfg["subject"] })
            }
          >
            <SelectTrigger className="bg-muted">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="var">Captured variable</SelectItem>
              <SelectItem value="tag">Contact has tag</SelectItem>
              <SelectItem value="contact_field">Contact field</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="md:col-span-2">
          <label className="mb-1 block text-xs text-muted-foreground">
            {subject === "var"
              ? "var name"
              : subject === "tag"
                ? "Tag"
                : "Field"}
          </label>
          {subject === "tag" && tags.length > 0 ? (
            <Select
              value={cfg.subject_key ?? ""}
              onValueChange={(v) => onUpdateConfig({ subject_key: v })}
            >
              <SelectTrigger className="bg-muted">
                <SelectValue placeholder="Pick a tag…" />
              </SelectTrigger>
              <SelectContent>
                {tags.map((t) => (
                  <SelectItem key={t.id} value={t.id}>
                    {t.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          ) : subject === "contact_field" ? (
            <Select
              value={cfg.subject_key ?? ""}
              onValueChange={(v) => onUpdateConfig({ subject_key: v })}
            >
              <SelectTrigger className="bg-muted">
                <SelectValue placeholder="Pick a field…" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="name">name</SelectItem>
                <SelectItem value="email">email</SelectItem>
                <SelectItem value="phone">phone</SelectItem>
                <SelectItem value="company">company</SelectItem>
              </SelectContent>
            </Select>
          ) : (
            <Input
              value={cfg.subject_key ?? ""}
              onChange={(e) =>
                onUpdateConfig({ subject_key: e.target.value })
              }
              placeholder={subject === "var" ? "e.g. email" : "tag UUID"}
              className="bg-muted font-mono text-xs"
            />
          )}
        </div>
      </div>

      <div
        className={cn(
          "grid grid-cols-1 gap-3",
          showValue ? "md:grid-cols-2" : "",
        )}
      >
        <div>
          <label className="mb-1 block text-xs text-muted-foreground">Operator</label>
          <Select
            value={operator}
            onValueChange={(v) =>
              onUpdateConfig({ operator: v as ConditionCfg["operator"] })
            }
          >
            <SelectTrigger className="bg-muted">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="present">is present</SelectItem>
              <SelectItem value="absent">is absent</SelectItem>
              <SelectItem value="equals">equals</SelectItem>
              <SelectItem value="contains">contains</SelectItem>
            </SelectContent>
          </Select>
        </div>
        {showValue && (
          <div>
            <label className="mb-1 block text-xs text-muted-foreground">Value</label>
            <Input
              value={cfg.value ?? ""}
              onChange={(e) => onUpdateConfig({ value: e.target.value })}
              className="bg-muted"
            />
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
        <NextNodeRow
          value={cfg.true_next ?? ""}
          allNodes={allNodes}
          currentKey={currentKey}
          onChange={(v) => onUpdateConfig({ true_next: v })}
          label="If true → advance to"
        />
        <NextNodeRow
          value={cfg.false_next ?? ""}
          allNodes={allNodes}
          currentKey={currentKey}
          onChange={(v) => onUpdateConfig({ false_next: v })}
          label="If false → advance to"
        />
      </div>
    </>
  );
}

// ============================================================
// set_tag
// ============================================================

interface SetTagCfg {
  mode?: "add" | "remove";
  tag_id?: string;
  next_node_key?: string;
}

function SetTagForm({
  cfg,
  allNodes,
  currentKey,
  onUpdateConfig,
}: {
  cfg: SetTagCfg;
  allNodes: BuilderNode[];
  currentKey: string;
  onUpdateConfig: (patch: Record<string, unknown>) => void;
}) {
