        label="Then advance to"
      />
    </>
  );
}

/**
 * Shared loader for both `condition` (subject=tag) and `set_tag`.
 * Falls back to raw UUID input if the endpoint is absent on older
 * deployments — the form remains authorable in that case.
 */
function useUserTags(): UserTag[] {
  const [tags, setTags] = useState<UserTag[]>([]);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch("/api/tags").catch(() => null);
        if (!res || !res.ok) return;
        const json = (await res.json()) as { tags?: UserTag[] };
        if (!cancelled) setTags(json.tags ?? []);
      } catch {
        // Tags endpoint absent — caller falls back to raw input.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);
  return tags;
}

// ============================================================
// send_media
// ============================================================

interface SendMediaCfg {
  media_type?: "image" | "video" | "document";
  media_url?: string;
  caption?: string;
  filename?: string;
  next_node_key?: string;
}

// Mirrors the bucket's allowed_mime_types from migration 016. Kept in
// sync with the storage policy so the picker rejects unsupported files
// before they hit the network rather than failing with a confusing
// Supabase RLS / mime-type error.
const MEDIA_ACCEPT: Record<NonNullable<SendMediaCfg["media_type"]>, string> = {
  image: "image/png,image/jpeg,image/webp",
  video: "video/mp4,video/3gpp",
  document:
    "application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation,text/plain",
};

const FLOW_MEDIA_BUCKET = "flow-media";

function SendMediaForm({
  cfg,
  allNodes,
  currentKey,
  onUpdateConfig,
}: {
  cfg: SendMediaCfg;
  allNodes: BuilderNode[];
  currentKey: string;
  onUpdateConfig: (patch: Record<string, unknown>) => void;
}) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);

  const mediaType = cfg.media_type ?? "image";
  const isDocument = mediaType === "document";
  const displayName =
    cfg.filename ||
    (cfg.media_url ? cfg.media_url.split("/").pop() ?? "" : "");

  const handleFile = useCallback(
    async (file: File) => {
      if (file.size > MEDIA_MAX_BYTES) {
        toast.error(
          `File is ${(file.size / 1024 / 1024).toFixed(1)} MB — limit is 16 MB.`,
        );
        return;
      }
      setUploading(true);
      try {
        // Account-scoped upload (path `account-<id>/...`) — see
        // uploadAccountMedia + migration 020's flow-media RLS policy.
        const { publicUrl } = await uploadAccountMedia(FLOW_MEDIA_BUCKET, file);
        // Patch all fields in one call so the form doesn't re-render
        // with a half-uploaded state.
        onUpdateConfig({
          media_url: publicUrl,
          filename: file.name,
        });
        toast.success("File uploaded.");
      } catch (err) {
        const msg = err instanceof Error ? err.message : "Upload failed.";
        toast.error(msg);
      } finally {
        setUploading(false);
      }
    },
    [onUpdateConfig],
  );

  const handleClear = () => {
    onUpdateConfig({ media_url: "", filename: "" });
  };

  return (
    <>
      <div>
        <label className="mb-1 block text-xs text-muted-foreground">Media type</label>
        <Select
          value={mediaType}
          onValueChange={(v) => {
            // Changing type clears the existing file — the bucket
            // accepts different MIME sets per type and a previously
            // uploaded PDF can't be sent as an image.
            onUpdateConfig({
              media_type: v as NonNullable<SendMediaCfg["media_type"]>,
              media_url: "",
              filename: "",
            });
          }}
        >
          <SelectTrigger className="bg-muted">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="image">Image (PNG, JPEG, WebP)</SelectItem>
            <SelectItem value="video">Video (MP4, 3GP)</SelectItem>
            <SelectItem value="document">
              Document (PDF, Word, Excel, PowerPoint, TXT)
            </SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div>
        <label className="mb-1 block text-xs text-muted-foreground">File</label>
        {cfg.media_url ? (
          <div className="flex items-center gap-2 rounded-md border border-border bg-muted px-3 py-2 text-xs">
            <Paperclip className="h-3.5 w-3.5 shrink-0 text-cyan-400" />
            <a
              href={cfg.media_url}
              target="_blank"
              rel="noopener noreferrer"
              className="min-w-0 flex-1 truncate text-foreground hover:text-cyan-300"
              title={displayName || cfg.media_url}
            >
              {displayName || cfg.media_url}
            </a>
            <button
              type="button"
              onClick={handleClear}
              className="rounded-none p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
              aria-label="Remove file"
              disabled={uploading}
            >
              <X className="h-3.5 w-3.5" />
            </button>
          </div>
        ) : (
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
            className="flex w-full items-center justify-center gap-2 rounded-md border border-dashed border-border bg-card px-3 py-4 text-xs text-muted-foreground transition-colors hover:border-border hover:bg-muted hover:text-foreground disabled:cursor-not-allowed disabled:opacity-60"
          >
            {uploading ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Uploading…
              </>
            ) : (
              <>
                <Upload className="h-3.5 w-3.5" />
                Click to upload (max 16 MB)
              </>
            )}
          </button>
        )}
        <input
          ref={fileInputRef}
          type="file"
          accept={MEDIA_ACCEPT[mediaType]}
          className="hidden"
          onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) void handleFile(f);
            // Reset so picking the same file twice still fires onChange.
            e.target.value = "";
          }}
        />
      </div>

      <TextRow
        label="Caption (optional, shown under the media)"
        value={cfg.caption ?? ""}
        onChange={(v) => onUpdateConfig({ caption: v })}
        rows={2}
      />

      {isDocument && (
        <div>
          <label className="mb-1 block text-xs text-muted-foreground">
            Filename shown to the customer (documents only)
          </label>
          <Input
            value={cfg.filename ?? ""}
            onChange={(e) => onUpdateConfig({ filename: e.target.value })}
            placeholder="invoice.pdf"
            className="bg-muted text-xs"
          />
        </div>
      )}

      <NextNodeRow
        value={cfg.next_node_key ?? ""}
        allNodes={allNodes}
        currentKey={currentKey}
        onChange={(v) => onUpdateConfig({ next_node_key: v })}
        label="After sending, advance to"
      />
    </>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Plus, Search, Loader2, BookOpen } from "lucide-react";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { IconAction } from "@/components/ui/icon-action";

interface PolicyItem {
  id: string;
  title: string;
  category: string;
  status: string;
  mandatory: boolean;
}

interface AddPolicyDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  workspaceId: string;
  existingPolicyIds: string[];
  onAdded: () => void;
}

export function AddPolicyDialog({
  open,
  onOpenChange,
  workspaceId,
  existingPolicyIds,
  onAdded,
}: AddPolicyDialogProps) {
  const [loading, setLoading] = useState(false);
  const [policies, setPolicies] = useState<PolicyItem[]>([]);
  const [search, setSearch] = useState("");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [adding, setAdding] = useState(false);

  useEffect(() => {
    if (!open || !workspaceId) return;
    setLoading(true);
    setSelectedIds([]);
    setSearch("");

    fetch(`/api/hr/policies?workspaceId=${workspaceId}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.error) throw new Error(data.error);
        if (data.policies) {
          // Filter out policies that are already in the handbook
          const available = data.policies.filter(
            (p: PolicyItem) => !existingPolicyIds.includes(p.id)
          );
          setPolicies(available);
        }
      })
      .catch((err) => {
        toast.error("Failed to load available policies");
        console.error(err);
      })
      .finally(() => setLoading(false));
  }, [open, workspaceId, existingPolicyIds]);

  const filtered = policies.filter((p) =>
    p.title.toLowerCase().includes(search.toLowerCase()) ||
    p.category.toLowerCase().includes(search.toLowerCase())
  );

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleAdd = async () => {
    if (selectedIds.length === 0) return;
    setAdding(true);
    try {
      const res = await fetch("/api/hr/handbook/add-section", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          workspaceId,
          policyIds: selectedIds,
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to add policies");

      const added = typeof json.count === "number" ? json.count : selectedIds.length;
      if (added === 0) {
        toast.error("Nothing was added — those policies could not be found in this workspace");
      } else {
        toast.success(`Added ${added} policy section${added === 1 ? "" : "s"} to Handbook`);
      }
      onAdded();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || "Failed to add policies to handbook");
    } finally {
      setAdding(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[85vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-lg">
            <Plus className="size-5 text-primary" /> Add Policies from Policies & Compliance
          </DialogTitle>
          <DialogDescription>
            Select existing policies from your workspace library to include as sections in the Employee Handbook.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2 flex-1 overflow-hidden flex flex-col">
          <div className="relative">
            <Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" />
            <Input
              placeholder="Search policies by title or category..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9"
            />
          </div>

          <div className="border border-border rounded-md flex-1 overflow-y-auto min-h-[220px] max-h-[360px] p-2 space-y-1">
            {loading ? (
              <div className="flex h-40 items-center justify-center text-muted-foreground">
                <Loader2 className="size-6 animate-spin text-primary" />
              </div>
            ) : filtered.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-40 text-center p-4">
                <BookOpen className="size-8 text-muted-foreground mb-2" />
                <p className="text-sm font-medium">No available policies found</p>
                <p className="text-xs text-muted-foreground mt-1">
                  {policies.length === 0
                    ? "All workspace policies are already included in the handbook."
                    : "No policies match your search term."}
                </p>
              </div>
            ) : (
              filtered.map((policy) => {
                const checked = selectedIds.includes(policy.id);
                return (
                  <div
                    key={policy.id}
                    onClick={() => toggleSelect(policy.id)}
                    className={`flex items-center justify-between p-3 rounded-md border transition-colors cursor-pointer ${
                      checked
                        ? "bg-primary/10 border-primary/40"
                        : "bg-card border-border/60 hover:bg-muted/50"
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <Checkbox
                        checked={checked}
                        onCheckedChange={() => toggleSelect(policy.id)}
                      />
                      <div>
                        <p className="text-sm font-medium text-foreground">{policy.title}</p>
                        <p className="text-xs text-muted-foreground capitalize">
                          {policy.category.replace(/_/g, " ")}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      {policy.mandatory && (
                        <Badge variant="outline" className="text-[10px] uppercase border-amber-500/30 text-amber-500 bg-amber-500/10">
                          Mandatory
                        </Badge>
                      )}
                      <Badge variant="secondary" className="text-xs">
                        {policy.status}
                      </Badge>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        <DialogFooter className="flex items-center justify-between pt-2">
          <span className="text-xs text-muted-foreground">
            {selectedIds.length} policy{selectedIds.length === 1 ? "" : "s"} selected
          </span>
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <IconAction label="Add to Handbook" icon={adding ? <Loader2 className="size-4 animate-spin " /> : <Plus className="size-4 " />} onClick={handleAdd}
              disabled={selectedIds.length === 0 || adding} />
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Printer, X, Building2, ShieldCheck, Download, Loader2 } from "lucide-react";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { markdownToHtml } from "@/lib/markdown-utils";
import { IconAction } from "@/components/ui/icon-action";

interface PrintableSection {
  order: number;
  title: string;
  category?: string;
  mandatory?: boolean;
  content: string;
}

interface CompanyDetails {
  legal_name?: string;
  brand_name?: string;
  director_name?: string;
  registered_address?: string;
  website?: string;
  contact_email?: string;
  logo_url?: string;
}

interface PrintableHandbookModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  workspaceId: string;
  workspaceName: string;
}

export function PrintableHandbookModal({
  open,
  onOpenChange,
  workspaceId,
  workspaceName,
}: PrintableHandbookModalProps) {
  const [loading, setLoading] = useState(true);
  const [company, setCompany] = useState<CompanyDetails | null>(null);
  const [sections, setSections] = useState<PrintableSection[]>([]);
  // The subtree that actually gets printed.
  const printRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open || !workspaceId) return;
    setLoading(true);

    // Fetch company details + full policy sections for print
    Promise.all([
      // NOTE: these routes read `workspaceId` (camelCase). Sending
      // `workspace_id` returned 400 and printed an empty handbook.
      fetch(`/api/hr/handbook?workspace_id=${workspaceId}`).then((r) => r.json()),
      fetch(`/api/hr/policies?workspaceId=${workspaceId}`).then((r) => r.json()),
    ])
      .then(([hbData, polData]) => {
        const details = hbData.details || {};
        const logo = details.logo_url || null;
        setCompany({
          legal_name: details.legal_name || workspaceName,
          brand_name: details.brand_name || workspaceName,
          director_name: details.director_name || "Authorized Director",
          registered_address: details.registered_address || "Company Headquarters",
          website: details.website || "www.dailycrm.cloud",
          contact_email: details.contact_email || "hr@dailycrm.cloud",
          logo_url: logo,
        });

        const allPolicies = polData.policies || [];
        // Map sections in order
        const hbSections = hbData.sections || [];
        const fullSections: PrintableSection[] = hbSections.map((sec: any) => {
          const match = allPolicies.find((p: any) => p.id === sec.policy_id);
          // Only PUBLISHED versions may be printed for signature —
          // picking the highest version number could print an
          // in-progress draft as official policy.
          const versions = (match?.versions || []).filter((v: any) => v.published_at);
          const maxVerNum = versions.reduce((max: number, v: any) => Math.max(max, v.version_number || 1), 0);
          const latestVer = versions.find((v: any) => v.version_number === maxVerNum);

          return {
            order: sec.order,
            title: sec.title.replace(/^Handbook §\d+ — /, ""),
            category: match?.category || sec.key,
            mandatory: sec.mandatory,
            content: latestVer?.content || "This section has no published version yet — publish it in Policies & Compliance before printing for signature.",
          };
        });

        setSections(fullSections);
      })
      .catch((err) => {
        console.error("Failed to load printable handbook:", err);
      })
      .finally(() => setLoading(false));
  }, [open, workspaceId, workspaceName]);

  const handlePrintWindow = () => {
    // The dialog is fixed-position with its own scroll container, so a
    // bare window.print() emitted the whole dashboard clipped to one
    // page. Print from a dedicated window containing just the
    // handbook markup instead.
    const node = printRef.current;
    if (!node) {
      window.print();
      return;
    }
    const win = window.open("", "_blank", "width=980,height=1200");
    if (!win) {
      toast.error("Allow pop-ups for this site to print the handbook");
      return;
    }
    const styles = Array.from(
      document.querySelectorAll('link[rel="stylesheet"], style')
    )
      .map((el) => el.outerHTML)
      .join("\n");
    win.document.write(
      `<!doctype html><html><head><title>${
        company?.legal_name ?? "Employee Handbook"
      } — Employee Handbook</title>${styles}` +
        `<style>
           @page { size: A4; margin: 18mm 16mm; }
           body { background:#fff; color:#0f172a; }
           .hb-section { break-inside: avoid; }
           .hb-page-break { break-before: page; }
         </style></head><body>${node.innerHTML}</body></html>`
    );
    win.document.close();
    // Wait for the copied stylesheets to apply before printing.
    win.onload = () => {
      win.focus();
      win.print();
      win.close();
    };
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-[96vw] max-w-6xl max-h-[94vh] p-0 overflow-hidden flex flex-col bg-card shadow-2xl">
        {/* Top Control Bar (Hidden during printing) */}
        <div className="flex items-center justify-between p-4 border-b border-border bg-muted/30 print:hidden">
          <div className="flex items-center gap-2 font-bold text-foreground">
            <Building2 className="size-5 text-primary" />
            Official Letterhead Handbook Document
          </div>
          <div className="flex items-center gap-2">
            <IconAction label="Print / Save PDF" icon={<Printer className="size-4 " />} onClick={handlePrintWindow} className="bg-primary text-primary-foreground shadow" />
            <IconAction
              label="Close"
              icon={<X className="size-4" />}
              variant="ghost"
              onClick={() => onOpenChange(false)}
            />
          </div>
        </div>

        {/* Scrollable Printable Document Canvas */}
        <div className="flex-1 overflow-y-auto p-6 sm:p-10 space-y-8 bg-muted/40 text-foreground font-sans leading-relaxed print:p-0 print:overflow-visible print:bg-white print:text-black">
          {loading ? (
            <div className="flex h-64 items-center justify-center text-muted-foreground print:hidden">
              <Loader2 className="size-8 animate-spin text-primary mr-2" /> Generating Official Handbook Letterhead...
            </div>
          ) : (
            <div ref={printRef} id="printable-handbook-document" className="w-full max-w-4xl mx-auto space-y-8 bg-white p-8 sm:p-12 border border-slate-200 shadow-md print:border-none print:shadow-none print:p-0">
              {/* ── 1. OFFICIAL COMPANY LETTERHEAD HEADER ── */}
              <div className="border-b-2 border-slate-900 pb-4 flex items-start justify-between">
                <div>
                  <h1 className="text-lg font-semibold uppercase tracking-tight text-slate-900">
                    {company?.legal_name}
                  </h1>
                  <p className="text-xs text-slate-600 font-medium mt-0.5">{company?.brand_name} Corporate Group</p>
                  <p className="text-[11px] text-slate-500 mt-1 max-w-md">
                    {company?.registered_address}
                  </p>
                  <p className="text-[10px] text-slate-500 mt-0.5">
                    Email: {company?.contact_email} • Web: {company?.website}
                  </p>
                </div>
                <div className="text-right space-y-1">
                  <div className="inline-block px-3 py-1 bg-slate-100 border border-slate-300 text-[10px] font-mono font-bold text-slate-800 uppercase">
                    Ref: CRM-HBK-2026
                  </div>
                  <p className="text-[10px] text-slate-500 font-medium">
                    Date: {new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" })}
                  </p>
                </div>
              </div>

              {/* ── 2. HANDBOOK TITLE & SUBTITLE ── */}
              <div className="text-center py-6 border-b border-slate-200 space-y-2">
                <h2 className="text-lg font-black text-slate-900 tracking-wide uppercase">
                  EMPLOYEE HANDBOOK & COMPLIANCE MANUAL
                </h2>
                <p className="text-xs text-slate-600 font-medium italic">
                  Standard Operating Guidelines, Employment Policies & Organizational Code of Conduct
                </p>
              </div>

              {/* ── 3. TABLE OF CONTENTS ── */}
              <div className="bg-slate-50 p-5 border border-slate-200 rounded-md space-y-3">
                <h3 className="text-xs font-extrabold text-slate-900 uppercase tracking-wider">
                  Table of Contents
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
                  {sections.map((sec) => (
                    <div key={sec.order} className="flex items-center justify-between border-b border-slate-200/60 pb-1">
                      <span className="font-semibold text-slate-800">
                        {sec.order}. {sec.title}
                      </span>
                      {sec.mandatory && (
                        <span className="text-[9px] uppercase font-bold text-amber-700 bg-amber-100 px-1 rounded">
                          Mandatory
                        </span>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {/* ── 4. FULL HANDBOOK SECTION CONTENTS ── */}
              <div className="space-y-8 pt-4">
                {sections.map((sec) => (
                  <div key={sec.order} className="space-y-3 hb-section border-b border-slate-200 pb-6">
                    <div className="flex items-center justify-between border-b border-slate-800 pb-1">
                      <h3 className="text-base font-bold text-slate-900">
                        Section {sec.order}: {sec.title}
                      </h3>
                      {sec.mandatory && (
                        <span className="text-[10px] font-bold text-slate-600 uppercase">
                          Mandatory Compliance
                        </span>
                      )}
                    </div>

                    <div
                      className="rich-text text-xs text-slate-800 leading-relaxed space-y-2"
                      dangerouslySetInnerHTML={{ __html: markdownToHtml(sec.content) }}
                    />
                  </div>
                ))}
              </div>

              {/* ── 5. OFFICIAL SIGN-OFF & ATTESTATION PAGE ── */}
              <div className="pt-8 space-y-6 hb-page-break border-t-2 border-slate-900">
                <div className="text-center space-y-1">
                  <h3 className="text-sm font-black uppercase text-slate-900">
                    Employee Acknowledgement & Attestation Sign-off
                  </h3>
                  <p className="text-[11px] text-slate-600">
                    This document must be signed and returned to the HR department upon joining.
                  </p>
                </div>

                <div className="p-4 bg-slate-50 border border-slate-300 rounded text-xs text-slate-800 leading-relaxed font-medium">
                  <strong>FORMAL ATTESTATION STATEMENT:</strong> I hereby acknowledge that I have received, read, thoroughly understood, and voluntarily agree to abide by all policies, procedures, and regulations outlined in this Employee Handbook of {company?.legal_name}. I understand that failure to adhere to these rules may result in disciplinary action up to and including termination of employment.
                </div>

                <div className="grid grid-cols-2 gap-8 pt-8">
                  <div className="space-y-12">
                    <div className="border-b border-slate-400 pb-1"></div>
                    <div className="space-y-0.5 text-xs text-slate-800">
                      <p className="font-bold">Employee Signature</p>
                      <p className="text-[11px] text-slate-500">Printed Name: _______________________</p>
                      <p className="text-[11px] text-slate-500">Employee ID: _______________________</p>
                      <p className="text-[11px] text-slate-500">Date: _____________________________</p>
                    </div>
                  </div>

                  <div className="space-y-12">
                    <div className="border-b border-slate-400 pb-1"></div>
                    <div className="space-y-0.5 text-xs text-slate-800">
                      <p className="font-bold">For {company?.legal_name}</p>
                      <p className="text-[11px] text-slate-500">Director: {company?.director_name}</p>
                      <p className="text-[11px] text-slate-500">Authorized Signature & Seal</p>
                      <p className="text-[11px] text-slate-500">Date: {new Date().toLocaleDateString()}</p>
                    </div>
                  </div>
                </div>

                <div className="pt-6 border-t border-slate-200 text-center text-[10px] text-slate-400 font-mono flex items-center justify-between">
                  <span>SHA-256 AUDIT SEAL: VERIFIED DIGITAL HANDBOOK</span>
                  <span>CONFIDENTIAL — INTERNAL COMPANY PROPERTY</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Sparkles, Loader2, RefreshCw } from "lucide-react";
import { toast } from "sonner";

interface AiSummaryModalProps {
  conversationId: string;
}

export function AiSummaryModal({ conversationId }: AiSummaryModalProps) {
  const [summary, setSummary] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);

  async function fetchSummary() {
    setLoading(true);
    try {
      const res = await fetch(`/api/conversations/${conversationId}/summarize`, {
        method: "POST",
      });
      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || `HTTP ${res.status}`);
      }

      if (data.summary) {
        setSummary(data.summary);
      }
    } catch (err: any) {
      console.error("[AiSummaryModal] Error:", err);
      toast.error(`Summary failed: ${err.message || "Unknown error"}`);
    } finally {
      setLoading(false);
    }
  }

  function handleOpenChange(newOpen: boolean) {
    setOpen(newOpen);
    if (newOpen && !summary && !loading) {
      void fetchSummary();
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger
        render={
          <Button
            variant="outline"
            size="sm"
            className="inline-flex h-7 items-center gap-1.5 rounded-md border border-primary/30 bg-primary/10 px-2 text-xs font-medium text-primary transition-colors hover:bg-primary/15 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            title="Generate AI executive summary of this chat"
          />
        }
      >
        <Sparkles className="h-3.5 w-3.5" />
        <span className="hidden sm:inline">AI Summarize</span>
      </DialogTrigger>

      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between">
            <span className="flex items-center gap-2 text-base font-semibold">
              <Sparkles className="h-5 w-5 text-primary" />
              Chat Summary (Groq AI)
            </span>
            {summary && !loading && (
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => void fetchSummary()}
                title="Regenerate summary"
              >
                <RefreshCw className="h-3.5 w-3.5" />
              </Button>
            )}
          </DialogTitle>
        </DialogHeader>

        <div className="mt-2 min-h-[160px] rounded-lg border bg-muted/50 p-4 text-xs sm:text-sm font-sans leading-relaxed whitespace-pre-wrap">
          {loading ? (
            <div className="flex h-36 flex-col items-center justify-center gap-2 text-muted-foreground">
              <Loader2 className="h-6 w-6 animate-spin text-primary" />
              <p className="text-xs">Analyzing conversation history via Groq Llama 3...</p>
            </div>
          ) : summary ? (
            summary
          ) : (
            <div className="flex h-36 flex-col items-center justify-center text-muted-foreground">
              <p className="text-xs">Click regenerate to load summary.</p>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

