import { cn } from "@/lib/utils";
import { useAuth } from "@/hooks/use-auth";
import { useWorkspace, type WorkspacePermissions } from "@/hooks/use-workspace";
import type { ModuleKey } from "@/lib/auth/modules";
import { useTotalUnread } from "@/hooks/use-total-unread";
import { useTheme } from "@/hooks/use-theme";
import {
  LayoutDashboard,
  MessageSquare,
  Users,
  UserCircle,
  GitBranch,
  Radio,
  Zap,
  Settings,
  LogOut,
  User,
  X,
  Blocks,
  BookOpen,
  ImageIcon,
  FileText,
  Calculator,
  Handshake,
  Landmark,
  PenSquare,
  Scale,
  Briefcase,
  CheckSquare,
  Clock,
  CalendarClock,
  Umbrella,
  Building,
  BadgeCheck,
  Laptop,
  BarChart3,
  ShieldCheck,
  Banknote,
  Receipt,
  ShoppingCart,
  Package,
  Layers,
  Truck,
  Building2,
  RefreshCw,
  Store,
  Wallet,
  ChevronRight,
  Activity,
  Calendar,
  TrendingUp,
  FileCheck,
  ChevronLeft,
  ChevronsUpDown,
  AppWindow,
  Tag,
  Bookmark
} from "lucide-react";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@/components/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { WorkspaceSwitcher } from "./workspace-switcher";

type NavItem = {
  href: string;
  label: string;
  icon: React.ElementType;
  permission?: keyof WorkspacePermissions;
  badge?: boolean;
};

type NavGroup = {
  label: string;
  icon: React.ElementType;
  items: NavItem[];
};

/**
 * Maps each sidebar nav group's label to the app module that gates it.
 * `null` = ungated (always visible, e.g. the System group). Groups whose
 * module the member can't access are hidden from the module switcher.
 * Keep the keys in sync with the `navGroups` labels below.
 */
const NAV_GROUP_MODULE: Record<string, ModuleKey | null> = {
  // Self-service is deliberately ungated: requesting your own leave or
  // seeing your own payslip is not an HR-module capability, and routing
  // staff through the HR module to do it both exposes the whole module and
  // requires a permission they should not need.
  "My Workspace": null,
  CRM: "crm",
  Accounting: "accounting",
  Retail: "retail",
  "Project Management": "projects",
  "HR Management": "hr",
  System: null,
};

const navGroups: NavGroup[] = [
  {
    label: "My Workspace",
    icon: UserCircle,
    items: [
      { href: "/dashboard", label: "Home", icon: LayoutDashboard },
      { href: "/me/attendance", label: "My Attendance", icon: CalendarClock },
      { href: "/me/leave", label: "My Leave", icon: Umbrella },
      { href: "/me/timesheets", label: "My Timesheets", icon: Clock },
      { href: "/me/payslips", label: "My Payslips", icon: Banknote },
      { href: "/me/requests", label: "My Requests", icon: FileCheck },
      { href: "/me/documents", label: "My Documents", icon: FileText },
      { href: "/handbook", label: "Handbook", icon: BookOpen },
      { href: "/settings?tab=profile", label: "My Profile", icon: Settings },
    ]
  },
  {
    label: "CRM",
    icon: MessageSquare,
    items: [
      { href: "/dashboard", label: "Dashboard", icon: LayoutDashboard },
      { href: "/inbox", label: "Inbox", icon: MessageSquare, permission: "inbox", badge: true },
      // Ordered to follow the customer lifecycle end to end:
      // Contacts -> Pipelines -> Commercials -> Quotations -> Invoices.
      { href: "/contacts", label: "Contacts", icon: Users, permission: "contacts" },
      { href: "/pipelines", label: "Pipelines", icon: GitBranch, permission: "pipelines" },
      { href: "/commercials", label: "Commercials", icon: Handshake },
      { href: "/quotations", label: "Quotations", icon: Calculator },
      { href: "/invoices", label: "Invoices", icon: Receipt },
      { href: "/broadcasts", label: "Broadcasts", icon: Radio, permission: "broadcasts" },
      { href: "/media", label: "Media", icon: ImageIcon },
      { href: "/forms", label: "Forms", icon: FileText },
      { href: "/settings?tab=crm", label: "CRM Settings", icon: Settings },
    ]
  },
  {
    // Finance lives in its own module now — the ledger, GST and GL
    // pages moved here out of Retail, which keeps only store
    // operations. Physical table names keep their commerce_ prefix;
    // the module split is presentation + RBAC only.
    label: "Accounting",
    icon: Landmark,
    items: [
      { href: "/accounting/ledgers", label: "Ledgers", icon: BookOpen },
      { href: "/accounting/new-entry", label: "New Entry", icon: PenSquare },
      { href: "/commerce/accounting", label: "Day Book", icon: CalendarClock },
      { href: "/accounting/trial-balance", label: "Trial Balance", icon: Scale },
      { href: "/accounting/profit-loss", label: "Profit & Loss", icon: TrendingUp },
      { href: "/accounting/balance-sheet", label: "Balance Sheet", icon: Landmark },
      { href: "/commerce/ledger", label: "Receivables / Khata", icon: Wallet },
      { href: "/commerce/gst", label: "GST Reports", icon: FileText },
      { href: "/invoices", label: "Invoices", icon: Receipt },
      { href: "/expenses", label: "Expenses", icon: Receipt, permission: "people_view" },
      { href: "/settings?tab=accounting", label: "Accounting Settings", icon: Settings },
    ]
  },
  {
    label: "Retail",
    icon: Store,
    items: [
      { href: "/pos", label: "POS Terminal", icon: ShoppingCart },
      { href: "/commerce/products", label: "Products", icon: Package },
      { href: "/commerce/categories", label: "Categories", icon: Tag },
      { href: "/commerce/brands", label: "Brands", icon: Bookmark },
      { href: "/commerce/units", label: "Units", icon: Scale },
      { href: "/commerce/inventory", label: "Inventory", icon: Layers },
      { href: "/commerce/sales", label: "Sales Orders", icon: Receipt },
      { href: "/commerce/purchases", label: "Purchases & POs", icon: Truck },
      { href: "/commerce/suppliers", label: "Suppliers", icon: Building2 },
      { href: "/commerce/returns", label: "Returns", icon: RefreshCw },
      { href: "/settings?tab=retail", label: "Retail Settings", icon: Settings },
    ]
  },
  {
    label: "Project Management",
    icon: Briefcase,
    items: [
      { href: "/projects/dashboard", label: "Dashboard", icon: LayoutDashboard, permission: "projects_view" },
      { href: "/projects", label: "Projects", icon: Briefcase, permission: "projects_view" },
      { href: "/planning", label: "Planning", icon: CalendarClock, permission: "projects_view" },
      { href: "/tasks", label: "Tasks", icon: CheckSquare, permission: "projects_view" },
      { href: "/workloads", label: "Workload", icon: Activity, permission: "projects_view" },
      { href: "/timesheets", label: "Timesheets", icon: Clock, permission: "projects_view" },
      { href: "/invoices", label: "Invoices", icon: Receipt, permission: "projects_view" },
      { href: "/settings?tab=projects", label: "Project Settings", icon: Settings, permission: "projects_manage" },
    ]
  },
  {
    label: "HR Management",
    icon: Users,
    items: [
      { href: "/hr-dashboard", label: "Dashboard", icon: LayoutDashboard, permission: "people_view" },
      { href: "/employees", label: "Employees", icon: Users, permission: "people_view" },
      { href: "/recruitment", label: "Recruitment", icon: Briefcase, permission: "people_manage" },
      { href: "/policies", label: "Policies & Compliance", icon: ShieldCheck, permission: "people_view" },
      { href: "/handbook", label: "Employee Handbook", icon: BookOpen, permission: "people_view" },
      { href: "/attendance", label: "Attendance", icon: CalendarClock, permission: "people_view" },
      // Also in Project Management, but its own page gates on
      // attendance_manage/people_manage — so an HR manager without
      // projects_view previously had no route to it at all.
      { href: "/timesheets", label: "Timesheets", icon: Clock, permission: "people_view" },
      { href: "/shifts", label: "Shifts", icon: Clock, permission: "people_manage" },
      { href: "/holidays", label: "Holidays", icon: Calendar, permission: "people_view" },
      { href: "/leave", label: "Leave", icon: Umbrella, permission: "people_view" },
      { href: "/payroll", label: "Payroll", icon: Banknote, permission: "people_manage" },
      { href: "/expenses", label: "Expenses", icon: Receipt, permission: "people_view" },
      { href: "/performance", label: "Performance", icon: TrendingUp, permission: "people_manage" },
      { href: "/requests", label: "Requests", icon: FileCheck, permission: "people_view" },
      { href: "/assets", label: "Assets", icon: Laptop, permission: "people_manage" },
      { href: "/documents", label: "Official Documents", icon: FileText },
      { href: "/departments", label: "Departments", icon: Building, permission: "people_manage" },
      { href: "/designations", label: "Designations", icon: BadgeCheck, permission: "people_manage" },
      { href: "/reports", label: "Analytics & Reports", icon: BarChart3, permission: "people_manage" },
      { href: "/settings?tab=hr", label: "HR Settings", icon: Settings, permission: "people_manage" },
    ]
  },
  {
    label: "System",
    icon: Settings,
    items: [
      { href: "/automations", label: "Automations", icon: Zap },
      { href: "/integrations", label: "Integrations", icon: Blocks },
      { href: "/docs", label: "Documentation", icon: BookOpen },
      { href: "/settings?tab=workspace", label: "Workspace Settings", icon: Settings },
    ]
  }
];

interface SidebarProps {
  open?: boolean;
  onClose?: () => void;
}

export function Sidebar({ open = false, onClose }: SidebarProps) {
  const pathname = usePathname();
  const router = useRouter();
  const { profile, signOut } = useAuth();
  const { can, moduleAccess, activeWorkspace } = useWorkspace();
  const totalUnread = useTotalUnread();
  const { mode } = useTheme();
  const isDark = mode === "dark";

  // Sidebar Layout & Active Module state
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [activeModule, setActiveModule] = useState<string>("CRM");

  // Sync collapsed preference
  useEffect(() => {
    const savedCollapse = localStorage.getItem("sidebar_collapsed");
    if (savedCollapse === "true") {
      setIsCollapsed(true);
    }
    const savedModule = localStorage.getItem("active_app_module");
    if (savedModule) {
      setActiveModule(savedModule);
    }
  }, []);

  // Determine current active group on page mount/change to auto-switch module active view
  useEffect(() => {
    // Ignore the query string: an item href of "/settings?tab=hr" must
    // still match the pathname "/settings", otherwise those links never
    // highlight and the group never opens.
    const matches = (item: { href: string }) => {
      const base = item.href.split("?")[0];
      return pathname === base || (base !== "/dashboard" && pathname.startsWith(base));
    };

    // Several destinations legitimately belong to more than one module —
    // /invoices sits in CRM, Accounting AND Project Management, /expenses in
    // both Accounting and HR. Picking the first match sent the rail jumping
    // to a different module than the one you clicked from. Staying put when
    // the current module also owns the destination is what makes navigation
    // feel predictable.
    const currentGroup = navGroups.find((g) => g.label === activeModule);
    if (currentGroup?.items.some(matches)) return;

    const matchedGroup = navGroups.find((group) => group.items.some(matches));
    if (matchedGroup) {
      setActiveModule(matchedGroup.label);
      localStorage.setItem("active_app_module", matchedGroup.label);
    }
  }, [pathname, activeModule]);

  const toggleCollapse = () => {
    const next = !isCollapsed;
    setIsCollapsed(next);
    localStorage.setItem("sidebar_collapsed", String(next));
  };

  // Only surface module groups the current member can access. Ungated
  // groups (NAV_GROUP_MODULE === null, e.g. System) always show. Preserves
  // navGroups order, so accessibleGroups[0] is CRM whenever CRM is allowed.
  const accessibleGroups = useMemo(() => {
    return navGroups.filter((group) => {
      const mod = NAV_GROUP_MODULE[group.label];
      return mod == null || moduleAccess[mod];
    });
  }, [moduleAccess]);

  // If the active module became inaccessible (role change, direct nav),
  // fall back to the first accessible group (CRM when available).
  useEffect(() => {
    if (accessibleGroups.length === 0) return;
    const stillAccessible = accessibleGroups.some((g) => g.label === activeModule);
    if (!stillAccessible) {
      const fallback = accessibleGroups[0].label;
      setActiveModule(fallback);
      localStorage.setItem("active_app_module", fallback);
    }
  }, [accessibleGroups, activeModule]);

  const handleSwitchModule = (moduleLabel: string) => {
    setActiveModule(moduleLabel);
    localStorage.setItem("active_app_module", moduleLabel);

    // Auto-navigate to first item of switched module for clean user flow
    const group = accessibleGroups.find(g => g.label === moduleLabel);
    if (group && group.items.length > 0) {
      const firstItem = group.items.find(item => !item.permission || can(item.permission));
      if (firstItem) {
        router.push(firstItem.href);
      }
    }
  };

  // Get active menu items for selected module (only from accessible groups)
  const visibleItems = useMemo(() => {
    const group = accessibleGroups.find(g => g.label === activeModule);
    if (!group) return [];
    return group.items.filter(item => !item.permission || can(item.permission));
  }, [accessibleGroups, activeModule, can]);

  // Find active group icon
  const ActiveGroupIcon = useMemo(() => {
    const group = accessibleGroups.find(g => g.label === activeModule);
    return group ? group.icon : AppWindow;
  }, [accessibleGroups, activeModule]);

  // Dynamic Theme Colors
  const sidebarBgClass = "bg-sidebar border-r border-sidebar-border text-sidebar-foreground";

  const switcherBg = isDark
    ? "border-border bg-transparent hover:bg-muted/10 text-foreground"
    : "border-border/80 bg-transparent hover:bg-muted/30 text-foreground";

  const dividerClass = isDark ? "border-t border-border" : "border-t border-border/60";

  const linkClass = (isActive: boolean) => {
    if (isActive) {
      return "bg-[rgba(37,99,235,0.16)] text-foreground font-medium";
    }
    return "text-muted-foreground hover:bg-muted/30 hover:text-foreground";
  };

  return (
    <>
      {/* Mobile Overlay */}
      {open && (
        <button
          type="button"
          aria-label="Close menu"
          onClick={onClose}
          className="fixed inset-0 z-30 bg-background/70 backdrop-blur-sm transition-opacity lg:hidden"
        />
      )}

      {/* Main Sidebar Panel */}
      <aside
        className={cn(
          "fixed inset-y-0 left-0 z-40 flex h-full flex-col transition-all duration-300 ease-in-out",
          sidebarBgClass,
          isCollapsed ? "w-16" : "w-[248px]",
          open ? "translate-x-0" : "-translate-x-full",
          "lg:static lg:translate-x-0 lg:transition-all"
        )}
        aria-label="Primary"
      >
        {/* Unified Header Row: Logo & Workspace Switcher in a single line */}
        <div className="flex h-[56px] shrink-0 items-center justify-between gap-1.5 px-3 border-b border-sidebar-border">
          {isCollapsed ? (
            /* Collapsed view: Show just the workspace avatar dropdown centered */
            <div className="w-full flex justify-center py-1">
              <WorkspaceSwitcher hideText minimalist />
            </div>
          ) : (
            /* Expanded view: Logo + Workspace Switcher + Collapse button in a single line */
            <div className="flex items-center gap-2 min-w-0 flex-1">
              {/* The workspace's own logo when they have uploaded one in
                  Branding, so the tool wears the customer's brand rather
                  than ours. Falls back to ours only when none is set. */}
              <Link href="/dashboard" className="shrink-0 flex items-center justify-center">
                {activeWorkspace?.logo_url ? (
                  // eslint-disable-next-line @next/next/no-img-element -- a
                  // user-uploaded URL on an arbitrary host; next/image would
                  // need every one of them in remotePatterns.
                  <img
                    src={activeWorkspace.logo_url}
                    alt={activeWorkspace.name}
                    className="h-9 w-9 shrink-0 rounded object-contain"
                  />
                ) : (
                  <Image
                    src="/logolight.png"
                    alt="Daily CRM Logo"
                    width={36}
                    height={36}
                    className="h-9 w-9 object-contain shrink-0"
                    priority
                  />
                )}
              </Link>
              <div className="flex-1 min-w-0">
                <WorkspaceSwitcher hideText={false} minimalist />
              </div>
            </div>
          )}

          {/* Collapse Toggle Button (Desktop Only) */}
          {!open && !isCollapsed && (
            <button
              onClick={toggleCollapse}
              className="hidden lg:flex h-7 w-7 shrink-0 items-center justify-center rounded-lg hover:bg-slate-850 text-muted-foreground hover:text-foreground transition-colors"
              title="Collapse Sidebar"
            >
              <ChevronLeft className="h-4 w-4" strokeWidth={3} />
            </button>
          )}

          {/* Close button (Mobile Only) */}
          {open && (
            <button
              type="button"
              onClick={onClose}
              className="flex h-8 w-8 items-center justify-center rounded-md lg:hidden text-muted-foreground hover:text-foreground"
            >
              <X className="h-5 w-5" />
            </button>
          )}
        </div>

        {/* App Module Switcher Dropdown (Just like Workspace Switcher) */}
        <div className="px-3 pt-3 pb-3 shrink-0">
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <button
                  type="button"
                  className={cn(
                    "flex w-full items-center justify-between gap-1.5 rounded-lg border transition-all focus:outline-none px-2 py-1.5 text-left text-sm font-medium",
                    switcherBg,
                    isCollapsed ? "px-1 py-1 justify-center border-transparent bg-transparent hover:bg-muted/40" : ""
                  )}
                  title={isCollapsed ? activeModule : "Switch module"}
                >
                  <div className="flex items-center gap-2 min-w-0">
                    <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-none bg-primary/15 text-primary border border-primary/20">
                      <ActiveGroupIcon className="h-3.5 w-3.5" />
                    </div>
                    {!isCollapsed && (
                      <div className="min-w-0">
                        <p className="truncate text-xs font-bold text-foreground leading-tight">
                          {activeModule}
                        </p>
                        <p className="text-[8px] text-primary font-extrabold uppercase tracking-wider leading-none mt-0.5">
                          Switch module
                        </p>
                      </div>
                    )}
                  </div>
                  {!isCollapsed && <ChevronsUpDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />}
                </button>
              }
            />
            
            <DropdownMenuContent
              align={isCollapsed ? "start" : "center"}
              side={isCollapsed ? "right" : "bottom"}
              sideOffset={12}
              className="w-56 bg-card border border-border text-foreground p-1.5 rounded-2xl shadow-xl z-50"
            >
              <div className="px-3 py-2 text-xs font-extrabold uppercase tracking-wider text-muted-foreground">
                App Modules
              </div>
              <DropdownMenuSeparator className="bg-border my-1" />
              
              {accessibleGroups.map((group) => {
                const GroupIcon = group.icon;
                const isSelected = activeModule === group.label;
                
                return (
                  <DropdownMenuItem
                    key={group.label}
                    onClick={() => handleSwitchModule(group.label)}
                    className={cn(
                      "flex items-center gap-2.5 rounded-lg px-3 py-2 text-xs font-bold transition-all focus:bg-muted focus:text-foreground cursor-pointer",
                      isSelected
                        ? "bg-primary/15 text-primary focus:bg-primary/20 focus:text-primary"
                        : "text-muted-foreground hover:text-foreground"
                    )}
                  >
                    <GroupIcon className="h-4 w-4 shrink-0" />
                    <span className="truncate flex-1">{group.label}</span>
                  </DropdownMenuItem>
                );
              })}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        {/* Separator */}
        <div className="px-3 py-2 shrink-0">
          <div className="border-t border-border/40 w-full" />
        </div>

        {/* Dynamic Sidebar Links (Only show selected module links) */}
        <nav className="flex-1 overflow-y-auto px-2 py-3 space-y-1 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
          {visibleItems.map((item) => {
            const isActive =
              pathname === item.href ||
              (item.href !== "/dashboard" && pathname.startsWith(item.href));
            const showUnreadDot = item.href === "/inbox" && totalUnread > 0 && !isActive;
            const ItemIcon = item.icon;

            return (
              <Link
                key={item.href}
                href={item.href}
                onClick={onClose}
                // Collapsed hides the label span, leaving the link with no
                // accessible name at all — an icon is not a name.
                aria-label={isCollapsed ? item.label : undefined}
                title={undefined}
                className={cn(
                  "flex items-center gap-2.5 rounded-lg px-3 py-2 text-sm font-bold transition-all relative group",
                  linkClass(isActive),
                  isCollapsed ? "justify-center px-0 py-2.5 h-10 w-10 mx-auto rounded-xl" : ""
                )}
              >
                <ItemIcon className="h-5 w-5 shrink-0" />
                {!isCollapsed && <span className="flex-1 truncate">{item.label}</span>}
                
                {/* Collapsed Tooltip */}
                {isCollapsed && (
                  <span
                    role="tooltip"
                    className="pointer-events-none absolute left-14 z-50 origin-left scale-0 whitespace-nowrap rounded-md bg-foreground px-2.5 py-1.5 text-xs font-medium text-background shadow-md transition-transform group-hover:scale-100 group-focus-visible:scale-100"
                  >
                    {item.label}
                  </span>
                )}

                {showUnreadDot && (
                  <span className="relative flex h-1.5 w-1.5 shrink-0">
                    <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-primary opacity-75" />
                    <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-primary" />
                  </span>
                )}
              </Link>
            );
          })}
        </nav>

        {/* User Account Section */}
        <div className={cn("shrink-0 p-3 flex flex-col gap-2", dividerClass)}>
          {isCollapsed && (
            <button
              type="button"
              onClick={toggleCollapse}
              className="flex h-11 w-11 mx-auto items-center justify-center rounded-xl text-muted-foreground hover:text-foreground hover:bg-slate-850 mb-1"
              title="Expand sidebar"
              aria-label="Expand sidebar"
            >
              <ChevronRight className="h-5 w-5" strokeWidth={3} />
            </button>
          )}
          {!isCollapsed && (
            <div className="flex items-center justify-between px-2 pb-1 text-[10px] font-medium tracking-wide text-muted-foreground/60">
              <span>CRM v2</span>
              <span>by Daylink</span>
            </div>
          )}
          
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <button
                  type="button"
                  // Collapsed shows only the avatar, so the trigger needs a
                  // name of its own.
                  aria-label={isCollapsed ? `Account: ${profile?.full_name ?? "User"}` : undefined}
                  title={isCollapsed ? (profile?.full_name ?? "Account") : undefined}
                  className={cn(
                    "flex w-full items-center gap-3 rounded-lg px-2.5 py-2 text-left transition-colors focus:outline-none cursor-pointer hover:bg-muted/30",
                    isCollapsed ? "justify-center" : ""
                  )}
                >
                  <Avatar className="size-8 shrink-0">
                    {profile?.avatar_url && (
                      <AvatarImage src={profile.avatar_url} alt={profile.full_name ?? "Avatar"} />
                    )}
                    <AvatarFallback className="bg-primary/20 text-xs font-bold text-primary">
                      {profile?.full_name?.charAt(0)?.toUpperCase() ?? "U"}
                    </AvatarFallback>
                  </Avatar>
                  {!isCollapsed && (
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-xs font-bold text-foreground">
                        {profile?.full_name ?? "User"}
                      </p>
                      <p className="truncate text-[10px] text-muted-foreground mt-0.5">
                        {profile?.email ?? ""}
                      </p>
                    </div>
                  )}
                </button>
              }
            />
            
            <DropdownMenuContent
              align="end"
              side={isCollapsed ? "right" : "bottom"}
              sideOffset={12}
              className="min-w-56 bg-card border border-border text-foreground p-1.5 rounded-2xl shadow-xl z-50"
            >
              {!isCollapsed && (
                <div className="px-3 py-2 border-b border-border/60 mb-1">
                  <p className="text-xs font-bold text-foreground truncate">{profile?.full_name ?? "User"}</p>
                  <p className="text-[10px] text-muted-foreground truncate mt-0.5">{profile?.email ?? ""}</p>
                </div>
              )}
              <DropdownMenuItem render={<Link href="/settings?tab=profile" />}>
                <User className="size-4" /> Profile
              </DropdownMenuItem>
              <DropdownMenuItem render={<Link href="/settings?tab=overview" />}>
                <Settings className="size-4" /> Settings
              </DropdownMenuItem>
              <DropdownMenuSeparator className="bg-muted/60" />
              <DropdownMenuItem onClick={signOut} className="text-rose-400 focus:bg-rose-500/10 focus:text-rose-400">
                <LogOut className="size-4" /> Sign out
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </aside>
    </>
  );
}

"use client";

import { useState } from "react";
import { useWorkspace } from "@/hooks/use-workspace";
import { ChevronsUpDown, Plus, Check, Building2, AlertTriangle } from "lucide-react";
import { useTheme } from "@/hooks/use-theme";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";

export function WorkspaceSwitcher({ hideText = false, minimalist = false }: { hideText?: boolean; minimalist?: boolean }) {
  const {
    workspaces,
    activeWorkspace,
    activeRole,
    loading,
    switchWorkspace,
    createWorkspace,
  } = useWorkspace();

  const { mode } = useTheme();
  const isDark = mode === "dark";

  // Dynamic switcher styling depending on light vs dark sidebar look
  const switcherBg = minimalist
    ? "border-transparent bg-transparent hover:bg-muted/40 text-foreground px-2 py-1.5"
    : isDark
    ? "border-border bg-card hover:bg-muted/80 text-foreground"
    : "border-border bg-background/40 hover:bg-muted/80 text-foreground";

  const switcherTextClass = isDark ? "text-foreground" : "text-foreground";
  const switcherRoleClass = isDark ? "text-primary" : "text-primary-foreground/80";
  const switcherArrowClass = isDark ? "text-muted-foreground" : "text-foreground";
  const switcherLogoBorder = isDark ? "border-border bg-muted" : "border-border bg-background";

  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [newWorkspaceName, setNewWorkspaceName] = useState("");
  const [isCreating, setIsCreating] = useState(false);

  const maxWorkspaces = activeWorkspace?.plan_limits?.max_workspaces;
  const isLimitReached = maxWorkspaces !== null && maxWorkspaces !== undefined && workspaces.length >= maxWorkspaces;

  const handleCreateWorkspace = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWorkspaceName.trim()) return;

    setIsCreating(true);
    try {
      const created = await createWorkspace(newWorkspaceName.trim());
      if (created) {
        setNewWorkspaceName("");
        setIsDialogOpen(false);
        toast.success("Workspace created");
      }
    } catch (error: any) {
      console.error("Error creating workspace:", error);
      toast.error(error.message || "Failed to create workspace");
    } finally {
      setIsCreating(false);
    }
  };

  if (loading) {
    return (
      <div className={cn("flex items-center justify-between rounded-lg border border-border bg-card px-3 py-2 text-muted-foreground", hideText ? "px-1.5 py-1.5" : "")}>
        <div className="flex items-center gap-2">
          <div className="h-5 w-5 animate-pulse rounded-none bg-muted" />
          {!hideText && <div className="h-4 w-24 animate-pulse rounded-none bg-muted" />}
        </div>
      </div>
    );
  }

  if (!activeWorkspace) {
    return (
      <>
        <button
          type="button"
          onClick={() => setIsDialogOpen(true)}
          className={cn(
            "flex w-full items-center justify-between gap-2 rounded-lg border border-dashed border-border bg-card px-3 py-2.5 text-left text-sm font-medium text-muted-foreground transition-all hover:bg-muted hover:text-foreground focus:outline-none focus:ring-1 focus:ring-primary",
            hideText ? "px-1.5 py-1.5 justify-center" : ""
          )}
        >
          <div className="flex items-center gap-2.5 min-w-0">
            <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-none bg-muted text-muted-foreground">
              <Plus className="h-4 w-4" />
            </div>
            {!hideText && <span className="truncate text-xs font-semibold">Create Workspace</span>}
          </div>
        </button>

        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
            {isLimitReached ? (
              <div className="py-6 text-center space-y-4">
                <AlertTriangle className="mx-auto h-8 w-8 text-amber-500" />
                <DialogTitle className="text-lg font-semibold text-foreground">
                  Workspace limit reached
                </DialogTitle>
                <p className="text-sm text-foreground">
                  You have reached the maximum of <strong>{maxWorkspaces}</strong> workspaces allowed by your current plan.
                </p>
                <p className="text-xs text-muted-foreground">
                  Upgrade your plan to unlock more workspaces.
                </p>
                <DialogFooter className="mt-4 justify-center sm:justify-center flex-row gap-2">
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={() => setIsDialogOpen(false)}
                    className="text-muted-foreground hover:text-foreground hover:bg-muted"
                  >
                    Cancel
                  </Button>
                  <Button
                    type="button"
                    onClick={() => {
                      setIsDialogOpen(false);
                      window.location.href = "/settings?tab=billing";
                    }}
                    className="bg-primary hover:bg-primary-hover text-foreground font-medium"
                  >
                    Upgrade Plan
                  </Button>
                </DialogFooter>
              </div>
            ) : (
              <form onSubmit={handleCreateWorkspace}>
                <DialogHeader>
                  <DialogTitle className="text-lg font-semibold text-foreground">
                    Create New Workspace
                  </DialogTitle>
                </DialogHeader>
                <div className="grid gap-4 py-4">
                  <div className="grid gap-2">
                    <Label htmlFor="name-empty" className="text-sm font-medium text-foreground">
                      Workspace Name
                    </Label>
                    <Input
                      id="name-empty"
                      placeholder="e.g. Sales Team, Marketing Dept"
                      value={newWorkspaceName}
                      onChange={(e) => setNewWorkspaceName(e.target.value)}
                      className="bg-background border-border focus:border-primary focus:ring-primary text-foreground"
                      required
                      autoFocus
                    />
                  </div>
                </div>
                <DialogFooter className="gap-2 sm:gap-0">
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={() => setIsDialogOpen(false)}
                    className="text-muted-foreground hover:text-foreground hover:bg-muted"
                  >
                    Cancel
                  </Button>
                  <Button
                    type="submit"
                    disabled={isCreating || !newWorkspaceName.trim()}
                    className="bg-primary hover:bg-primary-hover text-foreground font-medium"
                  >
                    {isCreating ? "Creating..." : "Create Workspace"}
                  </Button>
                </DialogFooter>
              </form>
            )}
          </DialogContent>
        </Dialog>
      </>
    );
  }

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <button
              type="button"
              className={cn("flex w-full items-center justify-between gap-2 rounded-lg transition-all focus:outline-none focus:ring-1 focus:ring-primary px-3 py-2.5 text-left text-sm font-medium", switcherBg, hideText ? "px-1 py-1 justify-center" : "")}
            >
              <div className="flex items-center gap-2.5 min-w-0">
                {/* Only a real logo is shown. The generic Building2 tile was
                    a placeholder standing in for branding that does not
                    exist — with the brand logo already in the sidebar beside
                    this, a second empty icon square is pure noise. When
                    collapsed there is nothing else to identify the
                    workspace, so an initial stands in there. */}
                {/* Only when collapsed. Expanded, the sidebar already shows
                    the workspace logo immediately to the left of this
                    switcher — rendering it again put two copies of the same
                    logo side by side. Collapsed there is nothing else, so
                    the logo (or an initial) still identifies the
                    workspace. */}
                {hideText && activeWorkspace.logo_url ? (
                  <div className={cn("relative h-7 w-7 shrink-0 overflow-hidden rounded border", switcherLogoBorder)}>
                    {/* Deliberately NOT next/image: it throws on a host
                        absent from remotePatterns, and this renders inside
                        the sidebar — so a single unexpected logo_url
                        white-screened the entire app shell. A plain img
                        degrades to a broken image instead. */}
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={activeWorkspace.logo_url}
                      alt={activeWorkspace.name}
                      className="absolute inset-0 size-full object-cover"
                    />
                  </div>
                ) : hideText ? (
                  <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded bg-primary/10 text-xs font-semibold text-primary">
                    {activeWorkspace.name?.charAt(0)?.toUpperCase() ?? "W"}
                  </div>
                ) : null}
                {!hideText && (
                  <div className="min-w-0">
                    <p className={cn("truncate text-xs font-semibold", switcherTextClass)}>
                      {activeWorkspace.name}
                    </p>
                    <p className={cn("text-[10px] capitalize font-medium", switcherRoleClass)}>
                      {activeRole || "Member"}
                    </p>
                  </div>
                )}
              </div>
              {!hideText && <ChevronsUpDown className={cn("h-4 w-4 shrink-0", switcherArrowClass)} />}
            </button>
          }
        />
        <DropdownMenuContent
          align="start"
          sideOffset={6}
          className="w-56 bg-popover border-border text-popover-foreground rounded-lg shadow-md"
        >
          <DropdownMenuLabel className="text-xs text-muted-foreground font-medium px-2 py-1.5">
            Workspaces
          </DropdownMenuLabel>
          <DropdownMenuSeparator className="bg-border" />
          <div className="max-h-60 overflow-y-auto">
            {workspaces.map((workspace) => {
              const isActive = workspace.id === activeWorkspace.id;
              return (
                <DropdownMenuItem
                  key={workspace.id}
                  onClick={() => switchWorkspace(workspace.id)}
                  className="flex items-center justify-between px-2 py-2 text-foreground focus:bg-primary/10 focus:text-primary cursor-pointer rounded-md"
                >
                  <div className="flex items-center gap-2 min-w-0">
                    {workspace.logo_url ? (
                      <div className="h-5 w-5 shrink-0 rounded-none overflow-hidden relative border border-border bg-muted">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                          src={workspace.logo_url}
                          alt={workspace.name}
                          className="absolute inset-0 size-full object-cover"
                        />
                      </div>
                    ) : (
                      <div className="flex h-5 w-5 shrink-0 items-center justify-center rounded-none bg-primary/10 text-primary">
                        <Building2 className="h-3.5 w-3.5" />
                      </div>
                    )}
                    <span className="truncate text-sm font-medium">
                      {workspace.name}
                    </span>
                  </div>
                  {isActive && <Check className="h-4 w-4 text-primary shrink-0 ml-2" />}
                </DropdownMenuItem>
              );
            })}
          </div>
          <DropdownMenuSeparator className="bg-border" />
          <DropdownMenuItem
            onClick={() => setIsDialogOpen(true)}
            className="flex items-center gap-2 px-2 py-2 text-primary focus:bg-primary/10 focus:text-primary font-medium cursor-pointer rounded-md"
          >
            <Plus className="h-4 w-4 shrink-0" />
            Create Workspace
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
          {isLimitReached ? (
            <div className="py-6 text-center space-y-4">
              <AlertTriangle className="mx-auto h-8 w-8 text-amber-500" />
              <DialogTitle className="text-lg font-semibold text-foreground">
                Workspace limit reached
              </DialogTitle>
              <p className="text-sm text-foreground">
                You have reached the maximum of <strong>{maxWorkspaces}</strong> workspaces allowed by your current plan.
              </p>
              <p className="text-xs text-muted-foreground">
                Upgrade your plan to unlock more workspaces.
              </p>
              <DialogFooter className="mt-4 justify-center sm:justify-center flex-row gap-2">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setIsDialogOpen(false)}
                  className="text-muted-foreground hover:text-foreground hover:bg-muted"
                >
                  Cancel
                </Button>
                <Button
                  type="button"
                  onClick={() => {
                    setIsDialogOpen(false);
                    window.location.href = "/settings?tab=billing";
                  }}
                  className="bg-primary hover:bg-primary-hover text-primary-foreground font-medium"
                >
                  Upgrade Plan
                </Button>
              </DialogFooter>
            </div>
          ) : (
            <form onSubmit={handleCreateWorkspace}>
              <DialogHeader>
                <DialogTitle className="text-lg font-semibold text-foreground">
                  Create New Workspace
                </DialogTitle>
              </DialogHeader>
              <div className="grid gap-4 py-4">
                <div className="grid gap-2">
                  <Label htmlFor="name" className="text-sm font-medium text-foreground">
                    Workspace Name
                  </Label>
                  <Input
                    id="name"
                    placeholder="e.g. Sales Team, Marketing Dept"
                    value={newWorkspaceName}
                    onChange={(e) => setNewWorkspaceName(e.target.value)}
                    className="bg-background border-border focus:border-primary focus:ring-primary text-foreground"
                    required
                    autoFocus
                  />
                </div>
              </div>
              <DialogFooter className="gap-2 sm:gap-0">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setIsDialogOpen(false)}
                  className="text-muted-foreground hover:text-foreground hover:bg-muted"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={isCreating || !newWorkspaceName.trim()}
                  className="bg-primary hover:bg-primary-hover text-primary-foreground font-medium shadow-md shadow-primary/10"
                >
                  {isCreating ? "Creating..." : "Create Workspace"}
                </Button>
              </DialogFooter>
            </form>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import { useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { Loader2 } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';

interface LeaveRequestFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved: () => void;
}

export function LeaveRequestForm({ open, onOpenChange, onSaved }: LeaveRequestFormProps) {
  const supabase = createClient();
  const { activeWorkspace, activeMember } = useWorkspace();
  
  const [saving, setSaving] = useState(false);
  const [leaveType, setLeaveType] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [reason, setReason] = useState('');

  const LEAVE_TYPES = ['Sick Leave', 'Casual Leave', 'Paid Time Off', 'Unpaid Leave', 'Maternity/Paternity'];

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!activeWorkspace?.id || !activeMember?.id || !leaveType || !fromDate || !toDate) return;

    if (new Date(toDate) < new Date(fromDate)) {
      toast.error('End date cannot be before start date.');
      return;
    }

    setSaving(true);
    
    try {
      const { error } = await supabase
        .from('leave_requests')
        .insert({ 
          workspace_id: activeWorkspace.id, 
          workspace_member_id: activeMember.id,
          leave_type: leaveType, 
          from_date: fromDate,
          to_date: toDate,
          reason: reason.trim(),
          status: 'pending'
        });
        
      if (error) throw error;
      toast.success('Leave request submitted successfully');
      
      // Reset form
      setLeaveType('');
      setFromDate('');
      setToDate('');
      setReason('');
      
      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to submit leave request');
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-popover-foreground">
            Request Leave
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          <div className="space-y-2">
            <Label className="text-foreground">
              Leave Type <span className="text-red-500">*</span>
            </Label>
            <Select value={leaveType} onValueChange={(val) => setLeaveType(val || '')} required>
              <SelectTrigger className="bg-card border-border">
                <SelectValue placeholder="Select type..." />
              </SelectTrigger>
              <SelectContent>
                {LEAVE_TYPES.map(t => (
                  <SelectItem key={t} value={t}>{t}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label className="text-foreground">From Date <span className="text-red-500">*</span></Label>
              <Input
                type="date"
                value={fromDate}
                onChange={(e) => setFromDate(e.target.value)}
                className="bg-card border-border text-foreground"
                required
              />
            </div>
            <div className="space-y-2">
              <Label className="text-foreground">To Date <span className="text-red-500">*</span></Label>
              <Input
                type="date"
                value={toDate}
                onChange={(e) => setToDate(e.target.value)}
                className="bg-card border-border text-foreground"
                required
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label className="text-foreground">Reason / Remarks (Optional)</Label>
            <Textarea plain
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Provide a brief explanation..."
              className="bg-card border-border text-foreground resize-none"
              rows={3}
            />
          </div>
          <DialogFooter className="pt-4 border-t border-border mt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="border-border text-muted-foreground hover:bg-muted"
              disabled={saving}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              className="bg-primary hover:bg-primary/90 text-primary-foreground"
              disabled={saving || !leaveType || !fromDate || !toDate}
            >
              {saving && <Loader2 className="size-4 animate-spin mr-2" />}
              Submit Request
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { createClient } from "@/lib/supabase/client";
import type {
  Contact,
  Conversation,
  Deal,
  DealStatus,
  PipelineStage,
  Profile,
} from "@/types";
import { useWorkspace } from "@/hooks/use-workspace";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Check,
  X,
  Trash2,
  MessageSquare,
  Loader2,
  File,
  Upload,
} from "lucide-react";
import { CURRENCIES, getCurrencySymbol } from "@/lib/currency";
import { toast } from "sonner";

interface DealFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  deal?: Deal | null;
  pipelineId: string;
  stages: PipelineStage[];
  defaultStageId?: string;
  onSaved: () => void;
}
import { useRef } from "react";
import { IconAction } from "@/components/ui/icon-action";

export function DealForm({
  open,
  onOpenChange,
  deal,
  pipelineId,
  stages,
  defaultStageId,
  onSaved,
}: DealFormProps) {
  const supabase = createClient();
  const { activeWorkspace, defaultCurrency } = useWorkspace();

  const [title, setTitle] = useState("");
  const [value, setValue] = useState("");
  const [currency, setCurrency] = useState(defaultCurrency);
  const [contactId, setContactId] = useState("");
  const [stageId, setStageId] = useState("");
  const [assignedTo, setAssignedTo] = useState("");
  const [expectedCloseDate, setExpectedCloseDate] = useState("");
  const [notes, setNotes] = useState("");
  const [sourceId, setSourceId] = useState("");
  const [lostReasonId, setLostReasonId] = useState("");

  const [contacts, setContacts] = useState<Contact[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [sources, setSources] = useState<any[]>([]);
  const [reasons, setReasons] = useState<any[]>([]);
  const [isAddingSource, setIsAddingSource] = useState(false);
  const [newSourceName, setNewSourceName] = useState("");
  const [showLostReasonPrompt, setShowLostReasonPrompt] = useState(false);

  const [linkedConversation, setLinkedConversation] =
    useState<Conversation | null>(null);

  const [saving, setSaving] = useState(false);
  const [statusAction, setStatusAction] = useState<DealStatus | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [files, setFiles] = useState<any[]>([]);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Reset the form fields every time the sheet opens or its input
  // props change. This is a legitimate prop-driven sync.
  useEffect(() => {
    if (!open) return;
    setConfirmDelete(false);
    if (deal) {
      setTitle(deal.title);
      setValue(String(deal.value ?? ""));
      setCurrency(deal.currency || defaultCurrency);
      // contact_id is nullable when the contact has been deleted
      // (migration 004: ON DELETE SET NULL). "" means "no selection".
      setContactId(deal.contact_id ?? "");
      setStageId(deal.stage_id);
      setAssignedTo(deal.assigned_to ?? "");
      setExpectedCloseDate(deal.expected_close_date ?? "");
      setNotes(deal.notes ?? "");
      setSourceId(deal.source_id ?? "");
      setLostReasonId(deal.lost_reason_id ?? "");
    } else {
      setTitle("");
      setValue("");
      setCurrency(defaultCurrency);
      setContactId("");
      setStageId(defaultStageId || stages[0]?.id || "");
      setAssignedTo("");
      setExpectedCloseDate("");
      setNotes("");
      setSourceId("");
      setLostReasonId("");
    }
  }, [open, deal, defaultStageId, stages, defaultCurrency]);

  // Load supporting data once the sheet is open
  useEffect(() => {
    if (!open || !activeWorkspace?.id) return;
    let cancelled = false;
    (async () => {
      const [c, p, s, r] = await Promise.all([
        supabase
          .from("contacts")
          .select("*")
          .eq("workspace_id", activeWorkspace.id)
          .order("name"),
        supabase.from("profiles").select("*").order("full_name"),
        supabase.from("deal_sources").select("*").order("name"),
        supabase.from("deal_lost_reasons").select("*").order("name"),
      ]);
      if (cancelled) return;
      setContacts((c.data ?? []) as Contact[]);
      setProfiles((p.data ?? []) as Profile[]);
      setSources(s.data ?? []);
      setReasons(r.data ?? []);
    })();
    return () => {
      cancelled = true;
    };
  }, [open, activeWorkspace?.id, supabase]);

  // Fetch linked conversation for the selected contact (newest open one).
  // Clearing on no-selection is sync with prop state; the populated
  // case runs setLinkedConversation inside the async fetch callback.
  useEffect(() => {
    if (!open || !contactId) {
      setLinkedConversation(null);
      return;
    }
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from("conversations")
        .select("*")
        .eq("contact_id", contactId)
        .order("last_message_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (cancelled) return;
      setLinkedConversation((data as Conversation | null) ?? null);
    })();
    return () => {
      cancelled = true;
    };
  }, [open, contactId, supabase]);

  // Fetch deal files
  useEffect(() => {
    if (!open) return;
    if (!deal) {
      setFiles([]);
      return;
    }
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from("media_files")
        .select("*")
        .eq("deal_id", deal.id)
        .order("created_at", { ascending: false });
      if (!cancelled) setFiles(data || []);
    })();
    return () => {
      cancelled = true;
    };
  }, [open, deal, supabase]);

  async function handleFileUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file || !activeWorkspace) return;

    if (!deal && !title.trim()) {
      toast.error("Please enter a Title first to upload documents.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setUploading(true);
    const formData = new FormData();
    formData.append("file", file);
    formData.append("workspace_id", activeWorkspace.id);
    if (deal) formData.append("deal_id", deal.id);
    
    // Automatically creates/puts in a folder named after the deal title
    formData.append("auto_folder", deal ? deal.title : title.trim()); 

    try {
      const res = await fetch('/api/media/upload', {
        method: 'POST',
        body: formData,
      });
      if (!res.ok) throw new Error("Failed to upload file");
      const result = await res.json();
      toast.success(deal ? "File uploaded to deal" : "File uploaded");
      
      if (deal) {
        // Refresh files
        const { data } = await supabase
          .from("media_files")
          .select("*")
          .eq("deal_id", deal.id)
          .order("created_at", { ascending: false });
        setFiles(data || []);
      } else {
        // Keep in state to attach when deal is saved
        if (result.file) {
          setFiles(prev => [result.file, ...prev]);
        }
      }
    } catch (e: any) {
      toast.error(e.message);
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  }

  async function handleSave() {
    if (!title.trim() || !contactId || !stageId) {
      toast.error("Title, contact, and stage are required");
      return;
    }
    setSaving(true);

    const payload = {
      title: title.trim(),
      value: parseFloat(value) || 0,
      currency,
      contact_id: contactId,
      pipeline_id: pipelineId,
      stage_id: stageId,
      assigned_to: assignedTo || null,
      notes: notes.trim() || null,
      expected_close_date: expectedCloseDate || null,
      source_id: sourceId || null,
      lost_reason_id: lostReasonId || null,
    };

    if (deal) {
      const { error } = await supabase
        .from("deals")
        .update(payload)
        .eq("id", deal.id);
      if (error) {
        toast.error("Failed to save deal");
        setSaving(false);
        return;
      }
    } else {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const user = session?.user;
      if (!user) {
        toast.error("Not signed in");
        setSaving(false);
        return;
      }
      if (!activeWorkspace?.id) {
        toast.error("No active workspace selected");
        setSaving(false);
        return;
      }
      const { error, data: newDeal } = await supabase
        .from("deals")
        .insert({
          ...payload,
          user_id: user.id,
          workspace_id: activeWorkspace.id,
          status: "open",
        })
        .select()
        .single();
        
      if (error) {
        toast.error("Failed to create deal");
        setSaving(false);
        return;
      }

      // Attach any files uploaded before the deal was created
      if (files.length > 0 && newDeal?.id) {
        const fileIds = files.map(f => f.id);
        await supabase.from("media_files").update({ deal_id: newDeal.id }).in("id", fileIds);
      }
    }

    setSaving(false);
    toast.success(deal ? "Deal updated" : "Deal created");
    onOpenChange(false);
    onSaved();
  }

  async function handleStatusChange(status: DealStatus, reasonId?: string) {
    if (!deal) return;
    setStatusAction(status);
    const updates: any = { status };
    if (status === "lost") updates.lost_reason_id = reasonId || null;
    if (status === "open") updates.lost_reason_id = null;
    
    const { error } = await supabase
      .from("deals")
      .update(updates)
      .eq("id", deal.id);
    setStatusAction(null);
    if (error) {
      toast.error("Failed to update deal status");
      return;
    }
    toast.success(
      status === "won" ? "Marked as won" : status === "lost" ? "Marked as lost" : "Deal reopened",
    );
    setShowLostReasonPrompt(false);
    onOpenChange(false);
    onSaved();
  }

  async function handleDelete() {
    if (!deal) return;
    setDeleting(true);
    const { error } = await supabase.from("deals").delete().eq("id", deal.id);
    setDeleting(false);
    if (error) {
      toast.error("Failed to delete deal");
      return;
    }
    toast.success("Deal deleted");
    setConfirmDelete(false);
    onOpenChange(false);
    onSaved();
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="bg-card border-border text-foreground sm:max-w-lg w-full p-0"
      >
        <div className="flex h-full flex-col">
          <SheetHeader className="border-b border-border/50 p-4">
            <SheetTitle className="text-foreground">
              {deal ? "Edit Deal" : "New Deal"}
            </SheetTitle>
          </SheetHeader>

          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            <div className="grid gap-2">
              <Label className="text-foreground">Title</Label>
              <Input
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="Deal title"
                className="border-border bg-muted text-foreground"
              />
            </div>

            <div className="grid gap-2">
              <Label className="text-foreground">Contact</Label>
              <select
                value={contactId}
                onChange={(e) => setContactId(e.target.value)}
                className="h-9 w-full rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-primary focus:ring-1 focus:ring-primary"
              >
                <option value="">Select a contact</option>
                {contacts.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name || c.phone}
                  </option>
                ))}
              </select>

              {linkedConversation && (
                <Link
                  href="/inbox"
                  className="mt-1 inline-flex items-center gap-1.5 self-start rounded-md bg-primary/10 px-2 py-1 text-xs text-primary hover:bg-primary/20"
                >
                  <MessageSquare className="h-3 w-3" />
                  Link to Conversation
                </Link>
              )}
            </div>

            <div className="grid grid-cols-[1fr_110px] gap-3">
              <div className="grid gap-2">
                <Label className="text-foreground">Value</Label>
                <div className="relative">
                  <span className="pointer-events-none absolute left-2 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                    {getCurrencySymbol(currency)}
                  </span>
                  <Input
                    type="number"
                    value={value}
                    onChange={(e) => setValue(e.target.value)}
                    placeholder="0"
                    className="border-border bg-muted pl-7 text-foreground"
                  />
                </div>
              </div>
              <div className="grid gap-2">
                <Label className="text-foreground">Currency</Label>
                <select
                  value={currency}
                  onChange={(e) => setCurrency(e.target.value)}
                  className="h-9 w-full rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-primary"
                >
                  {/* Keep a legacy/unknown saved code selectable so
                      editing an old deal doesn't silently rewrite it. */}
                  {currency && !CURRENCIES.some((c) => c.code === currency) && (
                    <option value={currency}>{currency}</option>
                  )}
                  {CURRENCIES.map((c) => (
                    <option key={c.code} value={c.code}>
                      {c.code}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="grid gap-2">
                <Label className="text-foreground">Expected Close Date</Label>
                <Input
                  type="date"
                  value={expectedCloseDate}
                  onChange={(e) => setExpectedCloseDate(e.target.value)}
                  className="border-border bg-muted text-foreground [color-scheme:dark]"
                />
              </div>
              <div className="grid gap-2">
                <Label className="text-foreground">Source</Label>
                {isAddingSource ? (
                  <div className="flex gap-2">
                    <Input
                      value={newSourceName}
                      onChange={(e) => setNewSourceName(e.target.value)}
                      placeholder="Name"
                      className="border-border bg-muted text-foreground flex-1 h-9"
                    />
                    <Button
                      type="button"
                      disabled={!newSourceName.trim()}
                      onClick={async () => {
                        if (!newSourceName.trim()) return;
                        const { data, error } = await supabase.from('deal_sources').insert({ name: newSourceName.trim() }).select().single();
                        if (data) {
                           setSources([...sources, data].sort((a,b) => a.name.localeCompare(b.name)));
                           setSourceId(data.id);
                           setIsAddingSource(false);
                           setNewSourceName("");
                        } else {
                           toast.error(error?.message || "Failed to create source");
                        }
                      }}
                      className="h-9 px-3 bg-primary text-primary-foreground hover:bg-primary-hover"
                    >
                      Add
                    </Button>
                    <IconAction
                      label="Close"
                      icon={<X className="h-4 w-4" />}
                      variant="ghost"
                      onClick={() => setIsAddingSource(false)}
                      className="h-9 px-3 text-muted-foreground hover:text-foreground"
                    />
                  </div>
                ) : (
                  <select
                    value={sourceId}
                    onChange={(e) => {
                      if (e.target.value === "ADD_NEW") setIsAddingSource(true);
                      else setSourceId(e.target.value);
                    }}
                    className="h-9 w-full rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-primary focus:ring-1 focus:ring-primary"
                  >
                    <option value="">Select source</option>
                    {sources.map((s) => (
                      <option key={s.id} value={s.id}>{s.name}</option>
                    ))}
                    <option value="ADD_NEW">+ Add New Source</option>
                  </select>
                )}
              </div>
            </div>

            <div className="grid gap-2">
              <Label className="text-foreground">Stage</Label>
              <select
                value={stageId}
                onChange={(e) => setStageId(e.target.value)}
                className="h-9 w-full rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-primary"
              >
                {stages.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="grid gap-2">
              <Label className="text-foreground">Assigned To</Label>
              <select
                value={assignedTo}
                onChange={(e) => setAssignedTo(e.target.value)}
                className="h-9 w-full rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-primary"
              >
                <option value="">Unassigned</option>
                {profiles.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.full_name || p.email}
                  </option>
                ))}
              </select>
            </div>

            <div className="grid gap-2">
              <Label className="text-foreground">Notes</Label>
              <Textarea plain
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Add notes..."
                className="min-h-[100px] border-border bg-muted text-foreground"
              />
            </div>

            <div className="grid gap-2 pt-4 border-t border-border/50 mt-4">
              <div className="flex items-center justify-between">
                <Label className="text-foreground">Documents</Label>
                <Button 
                  type="button"
                  variant="outline" 
                  size="sm"
                  className="h-7 text-xs border-border bg-muted text-foreground"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={uploading}
                >
                  <Upload className="w-3 h-3 mr-1" />
                  {uploading ? "Uploading..." : "Upload"}
                </Button>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  onChange={handleFileUpload}
                />
              </div>
              
              {files.length > 0 ? (
                <div className="space-y-2 mt-2">
                  {files.map(f => (
                    <a 
                      key={f.id}
                      href={f.local_path} 
                      target="_blank" 
                      rel="noreferrer"
                      className="flex items-center gap-2 p-2 rounded-lg bg-card/50 border border-border hover:border-border transition-colors text-sm text-foreground hover:text-foreground"
                    >
                      <File className="w-4 h-4 text-primary" />
                      <span className="truncate">{f.name}</span>
                    </a>
                  ))}
                </div>
              ) : (
                <p className="text-xs text-muted-foreground mt-1">No documents attached.</p>
              )}
            </div>

            {deal && (
              <div className="space-y-2 rounded-lg border border-border bg-card/50 p-3">
                <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                  Status
                </p>
                <div className="flex gap-2">
                  <Button
                    type="button"
                    onClick={() => handleStatusChange("won")}
                    disabled={!!statusAction || deal.status === "won"}
                    className="flex-1 bg-primary text-primary-foreground hover:bg-primary disabled:opacity-50"
                  >
                    {statusAction === "won" ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <>
                        <Check className="mr-1 h-4 w-4" />
                        Mark as Won
                      </>
                    )}
                  </Button>
                  <Button
                    type="button"
                    onClick={() => setShowLostReasonPrompt(true)}
                    disabled={!!statusAction || deal.status === "lost"}
                    className="flex-1 bg-red-600 text-foreground hover:bg-red-700 disabled:opacity-50"
                  >
                    {statusAction === "lost" ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <>
                        <X className="mr-1 h-4 w-4" />
                        Mark as Lost
                      </>
                    )}
                  </Button>
                </div>
                {showLostReasonPrompt && (
                  <div className="mt-2 space-y-2 border border-red-500/30 bg-red-500/10 p-3 rounded-lg">
                    <Label className="text-red-300 text-xs">Reason for loss (Optional)</Label>
                    <select
                      value={lostReasonId}
                      onChange={(e) => setLostReasonId(e.target.value)}
                      className="h-9 w-full rounded-lg border border-border bg-muted px-2.5 text-sm text-foreground outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500"
                    >
                      <option value="">Select a reason</option>
                      {reasons.map((r) => (
                        <option key={r.id} value={r.id}>{r.name}</option>
                      ))}
                    </select>
                    <div className="flex gap-2">
                      <Button
                        type="button"
                        onClick={() => handleStatusChange("lost", lostReasonId)}
                        disabled={!!statusAction}
                        className="flex-1 h-8 bg-red-600 text-foreground hover:bg-red-700 text-xs"
                      >
                        Confirm Lost
                      </Button>
                      <Button
                        type="button"
                        variant="ghost"
                        onClick={() => setShowLostReasonPrompt(false)}
                        className="flex-1 h-8 text-muted-foreground hover:text-foreground text-xs"
                      >
                        Cancel
                      </Button>
                    </div>
                  </div>
                )}
                {deal.status && deal.status !== "open" && (
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={() => handleStatusChange("open")}
                    disabled={!!statusAction}
                    className="w-full text-muted-foreground hover:text-foreground"
                  >
                    Reopen deal
                  </Button>
                )}
              </div>
            )}
          </div>

          <div className="border-t border-border/50 bg-card/80 p-4">
            <div className="flex gap-2">
              <Button
                variant="outline"
                onClick={() => onOpenChange(false)}
                className="flex-1 border-border bg-transparent text-foreground hover:bg-muted"
              >
                Cancel
              </Button>
              <Button
                onClick={handleSave}
                disabled={saving || !title.trim() || !contactId || !stageId}
                className="flex-1 bg-primary text-primary-foreground hover:bg-primary"
              >
                {saving ? "Saving..." : deal ? "Save Changes" : "Create Deal"}
              </Button>
            </div>

            {deal &&
              (confirmDelete ? (
                <div className="mt-3 flex items-center justify-between gap-2 rounded-md border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs">
                  <span className="text-red-300">Delete this deal?</span>
                  <div className="flex gap-1">
                    <button
                      type="button"
                      onClick={() => setConfirmDelete(false)}
                      disabled={deleting}
                      className="rounded-none px-2 py-1 text-foreground hover:bg-muted"
                    >
                      Cancel
                    </button>
                    <button
                      type="button"
                      onClick={handleDelete}
                      disabled={deleting}
                      className="rounded-none bg-red-600 px-2 py-1 font-medium text-foreground hover:bg-red-700 disabled:opacity-50"
                    >
                      {deleting ? "Deleting..." : "Confirm"}
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => setConfirmDelete(true)}
                  className="mt-3 flex w-full items-center justify-center gap-1 text-xs text-red-400 hover:text-red-300"
                >
                  <Trash2 className="h-3 w-3" />
                  Delete Deal
                </button>
              ))}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  useDroppable,
  useDraggable,
  closestCorners,
  type DragEndEvent,
  type DragStartEvent,
} from "@dnd-kit/core";
import type { Deal, PipelineStage } from "@/types";
import { DealCard } from "./deal-card";
import { Button } from "@/components/ui/button";
import { Plus } from "lucide-react";
import { useAuth } from "@/hooks/use-auth";
import { formatCurrency } from "@/lib/currency";
import { IconAction } from "@/components/ui/icon-action";

interface PipelineBoardProps {
  stages: PipelineStage[];
  deals: Deal[];
  onDealMoved: (dealId: string, newStageId: string) => void;
  onAddDeal: (stageId: string) => void;
  onEditDeal: (deal: Deal) => void;
}

export function PipelineBoard({
  stages,
  deals,
  onDealMoved,
  onAddDeal,
  onEditDeal,
}: PipelineBoardProps) {
  const { defaultCurrency } = useAuth();
  const [activeDealId, setActiveDealId] = useState<string | null>(null);

  const sortedStages = useMemo(
    () => [...stages].sort((a, b) => a.position - b.position),
    [stages],
  );

  const dealsByStage = useMemo(() => {
    const map = new Map<string, Deal[]>();
    for (const stage of sortedStages) map.set(stage.id, []);
    for (const deal of deals) {
      const bucket = map.get(deal.stage_id);
      if (bucket) bucket.push(deal);
    }
    return map;
  }, [sortedStages, deals]);

  const sensors = useSensors(
    // 5px activation distance avoids clicks being interpreted as drags.
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    // Keyboard drag support: focus a card, Space to pick up, arrows to move,
    // Space to drop, Escape to cancel.
    useSensor(KeyboardSensor),
  );

  const activeDeal = activeDealId
    ? deals.find((d) => d.id === activeDealId) ?? null
    : null;

  function handleDragStart(event: DragStartEvent) {
    setActiveDealId(String(event.active.id));
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveDealId(null);
    const { active, over } = event;
    if (!over) return;
    const dealId = String(active.id);
    const targetStageId = String(over.id);

    const deal = deals.find((d) => d.id === dealId);
    if (!deal || deal.stage_id === targetStageId) return;
    if (!sortedStages.some((s) => s.id === targetStageId)) return;

    onDealMoved(dealId, targetStageId);
  }

  function handleDragCancel() {
    setActiveDealId(null);
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCorners}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onDragCancel={handleDragCancel}
    >
      {/* snap-x + snap-mandatory on mobile so swipes land the next
          stage cleanly at the viewport edge instead of mid-column.
          Disabled on lg+ where snapping would interfere with the
          natural layout. The board can still overflow horizontally on
          lg+ once a pipeline has many stages (columns keep a 260px
          min-width), so a thin scrollbar stays visible on desktop. */}
      <div className="pipeline-scroll flex snap-x snap-mandatory gap-3 overflow-x-auto pb-4 lg:snap-none">
        {sortedStages.map((stage) => {
          const stageDeals = dealsByStage.get(stage.id) ?? [];
          const totalValue = stageDeals.reduce(
            (s, d) => s + Number(d.value || 0),
            0,
          );
          return (
            <StageColumn
              key={stage.id}
              stage={stage}
              deals={stageDeals}
              totalValue={totalValue}
              currency={defaultCurrency}
              onAddDeal={onAddDeal}
              onEditDeal={onEditDeal}
            />
          );
        })}
      </div>

      <DragOverlay
        dropAnimation={{
          duration: 200,
          easing: "cubic-bezier(0.2, 0, 0, 1)",
        }}
      >
        {activeDeal ? (
          <div className="opacity-90">
            <DealCard
              deal={activeDeal}
              stage={
                sortedStages.find((s) => s.id === activeDeal.stage_id) ?? null
              }
              onEdit={() => {}}
              isOverlay
            />
          </div>
        ) : null}
      </DragOverlay>

      <style jsx>{`
        .pipeline-scroll {
          scroll-behavior: smooth;
        }
        /* On touch devices the peek/snap layout already signals there's
           more to swipe, so the scrollbar is hidden for a clean look.
           On desktop (mouse) the board can overflow with many stages
           and there is no peek hint, so keep a thin, themed scrollbar
           visible to make the overflow discoverable and usable. */
        @media (hover: none), (pointer: coarse) {
          .pipeline-scroll::-webkit-scrollbar {
            height: 0;
            display: none;
          }
          .pipeline-scroll {
            scrollbar-width: none;
          }
        }
        @media (hover: hover) and (pointer: fine) {
          .pipeline-scroll {
            scrollbar-width: thin;
            scrollbar-color: var(--border) transparent;
          }
          .pipeline-scroll::-webkit-scrollbar {
            height: 8px;
          }
          .pipeline-scroll::-webkit-scrollbar-track {
            background: transparent;
          }
          .pipeline-scroll::-webkit-scrollbar-thumb {
            background-color: var(--border);
            border-radius: 9999px;
          }
          .pipeline-scroll::-webkit-scrollbar-thumb:hover {
            background-color: var(--muted-foreground);
          }
        }
      `}</style>
    </DndContext>
  );
}

function StageColumn({
  stage,
  deals,
  totalValue,
  currency,
  onAddDeal,
  onEditDeal,
}: {
  stage: PipelineStage;
  deals: Deal[];
  totalValue: number;
  currency: string;
  onAddDeal: (stageId: string) => void;
  onEditDeal: (deal: Deal) => void;
}) {
  const { setNodeRef, isOver } = useDroppable({ id: stage.id });

  return (
    // On mobile each column is `w-[85vw]` (with a reasonable min/max)
    // so the next column's edge peeks in — a "there's more here" hint.
    // snap-start lands each column cleanly when swiping. On lg+ we
    // restore the flex-1 share-the-row behavior. The droppable ref is
    // on the inner messages region below — intentionally NOT here, so
    // a drag over the column header doesn't highlight the whole column.
    <div className="flex w-[85vw] min-w-[260px] max-w-[320px] shrink-0 snap-start flex-col rounded-xl border border-border bg-card/60 p-4 lg:w-auto lg:max-w-none lg:flex-1 lg:basis-[260px] lg:shrink lg:snap-none">
      {/* 3px colored top border — sits above the column's padding */}
      <div
        className="-mx-4 -mt-4 h-[3px] rounded-t-xl"
        style={{ backgroundColor: stage.color }}
      />
      <div className="flex items-center justify-between pt-3">
        <h3 className="truncate text-sm font-semibold text-foreground">
          {stage.name}
        </h3>
        <span className="shrink-0 rounded-full bg-muted px-2 py-0.5 text-[11px] font-medium text-muted-foreground">
          {deals.length}
        </span>
      </div>
      <p className="text-xs text-muted-foreground">
        {formatCurrency(totalValue, currency)}
      </p>

      <div
        ref={setNodeRef}
        className={`mt-3 flex flex-1 flex-col gap-2 rounded-lg transition-all ${
          isOver
            ? "bg-primary/5 outline outline-2 outline-dashed outline-primary outline-offset-2"
            : ""
        }`}
      >
        {deals.length === 0 ? (
          <div className="flex flex-1 items-center justify-center rounded-lg border-2 border-dashed border-border py-10 text-xs text-muted-foreground">
            Drop a deal here
          </div>
        ) : (
          deals.map((deal) => (
            <DraggableDealCard
              key={deal.id}
              deal={deal}
              stage={stage}
              onEdit={onEditDeal}
            />
          ))
        )}
      </div>

      <IconAction label="Add Deal" icon={<Plus className="h-3 w-3" />} variant="ghost"
        onClick={() => onAddDeal(stage.id)}
        className="mt-3 w-full justify-start border border-dashed border-border bg-transparent text-muted-foreground hover:border-border hover:bg-muted hover:text-foreground" />
    </div>
  );
}

function DraggableDealCard({
  deal,
  stage,
  onEdit,
}: {
  deal: Deal;
  stage: PipelineStage;
  onEdit: (deal: Deal) => void;
}) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: deal.id,
  });

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      style={{ opacity: isDragging ? 0.3 : 1, touchAction: "none" }}
    >
      <DealCard deal={deal} stage={stage} onEdit={onEdit} />
    </div>
  );
}

