'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { ShieldAlert, ChevronRight, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useRouter } from 'next/navigation';
import { IconAction } from "@/components/ui/icon-action";

export function ComplianceBanner() {
  const supabase = createClient();
  const router = useRouter();
  const { activeWorkspace, activeMember } = useWorkspace();

  const [pendingPolicies, setPendingPolicies] = useState<any[]>([]);
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    async function checkPendingPolicies() {
      if (!activeWorkspace?.id || !activeMember?.id) return;

      // 1. Fetch published mandatory policies
      const { data: policies } = await supabase
        .from('hr_policies')
        .select(`
          id,
          title,
          category,
          versions:hr_policy_versions!inner(*),
          targets:hr_policy_targets(*)
        `)
        .eq('workspace_id', activeWorkspace.id)
        .eq('status', 'PUBLISHED')
        .eq('versions.mandatory', true);

      if (!policies || policies.length === 0) return;

      // 2. Fetch member's active acknowledgements
      const { data: acks } = await supabase
        .from('hr_policy_acknowledgements')
        .select('version_id')
        .eq('workspace_member_id', activeMember.id)
        .eq('status', 'ACTIVE');

      const signedVersionIds = new Set(acks?.map(a => a.version_id) || []);

      // Filter policies that have a published version un-acknowledged by this member
      const unacknowledged = policies.filter(p => {
        const pubVer = Array.isArray(p.versions) ? p.versions.find((v: any) => v.published_at) : p.versions;
        return pubVer && !signedVersionIds.has(pubVer.id);
      });

      setPendingPolicies(unacknowledged);
    }

    checkPendingPolicies();
  }, [activeWorkspace?.id, activeMember?.id, supabase]);

  if (dismissed || pendingPolicies.length === 0) return null;

  const firstPending = pendingPolicies[0];

  return (
    <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-3 text-amber-900 dark:text-amber-200 flex items-center justify-between shadow-xs mb-6">
      <div className="flex items-center gap-3">
        <div className="size-8 rounded-full bg-amber-500/20 flex items-center justify-center text-amber-600 dark:text-amber-400 shrink-0">
          <ShieldAlert className="size-4" />
        </div>
        <div>
          <p className="text-sm font-semibold">
            Action Required: {pendingPolicies.length} mandatory HR {pendingPolicies.length === 1 ? 'policy requires' : 'policies require'} your review & legal sign-off.
          </p>
          <p className="text-xs opacity-80">
            {firstPending.title} ({firstPending.category.replace(/_/g, ' ')})
          </p>
        </div>
      </div>
      <div className="flex items-center gap-2">
        <IconAction label="Review & Sign" icon={<ChevronRight className="size-3.5 ml-1" />} onClick={() => router.push(`/policies/${firstPending.id}/read`)}
          className="bg-amber-600 hover:bg-amber-700 text-foreground border-none text-xs" />
        <button
          onClick={() => setDismissed(true)}
          className="p-1 hover:bg-amber-500/20 rounded-none text-amber-700 dark:text-amber-300"
          title="Dismiss notification"
        >
          <X className="size-4" />
        </button>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { toast } from 'sonner';
import { RichTextEditor } from '@/components/ui/rich-text-editor';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Shield } from 'lucide-react';

const CATEGORIES = [
  { value: 'CODE_OF_CONDUCT', label: 'Code of Conduct' },
  { value: 'LEAVE', label: 'Leave Policy' },
  { value: 'REMOTE_WORK', label: 'Remote Work & WFH' },
  { value: 'CONFIDENTIALITY', label: 'Data Confidentiality & NDA' },
  { value: 'IT_SECURITY', label: 'IT Security & Assets' },
  { value: 'POSH', label: 'POSH & Harassment Policy' },
  { value: 'TRAVEL', label: 'Travel & Reimbursement' },
  { value: 'ATTENDANCE', label: 'Working Hours & Attendance' },
  { value: 'TERMS_AND_CONDITIONS', label: 'General Terms & Conditions' },
  { value: 'CUSTOM', label: 'Custom Policy' }
];

interface PolicyEditorModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  policyId?: string | null;
  onSaved: () => void;
}

export function PolicyEditorModal({ open, onOpenChange, policyId, onSaved }: PolicyEditorModalProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [title, setTitle] = useState('');
  const [category, setCategory] = useState('CODE_OF_CONDUCT');
  const [content, setContent] = useState('');
  const [changeSummary, setChangeSummary] = useState('');
  const [mandatory, setMandatory] = useState(true);
  const [effectiveAt, setEffectiveAt] = useState('');
  const [linkedModule, setLinkedModule] = useState('NONE');

  const [, setDepartments] = useState<any[]>([]);
  const [selectedDeptIds, setSelectedDeptIds] = useState<string[]>([]);

  useEffect(() => {
    async function loadAuxData() {
      if (!activeWorkspace?.id) return;
      const { data } = await supabase.from('departments').select('id, name').eq('workspace_id', activeWorkspace.id);
      setDepartments(data || []);
    }
    if (open) loadAuxData();
  }, [open, activeWorkspace?.id, supabase]);

  useEffect(() => {
    async function fetchPolicyDetails() {
      if (!policyId || !open) return;
      setLoading(true);
      try {
        const res = await fetch(`/api/hr/policies/${policyId}`);
        const json = await res.json();
        if (json.policy) {
          const p = json.policy;
          setTitle(p.title);
          setCategory(p.category);
          setLinkedModule(p.linked_module || 'NONE');

          const verList = p.versions || [];
          const maxVerNum = verList.reduce((max: number, v: any) => Math.max(max, v.version_number || 1), 0);
          const latestVer = verList.find((v: any) => v.version_number === maxVerNum);

          if (latestVer) {
            setContent(latestVer.content || '');
            setChangeSummary(latestVer.change_summary || '');
            setMandatory(!!latestVer.mandatory);
            if (latestVer.effective_at) {
              setEffectiveAt(new Date(latestVer.effective_at).toISOString().slice(0, 10));
            }
          }

          const targetDepts = (p.targets || []).filter((t: any) => t.target_type === 'DEPARTMENT').map((t: any) => t.target_id);
          setSelectedDeptIds(targetDepts);
        }
      } catch {
        toast.error('Failed to load policy details');
      } finally {
        setLoading(false);
      }
    }

    if (open && policyId) {
      fetchPolicyDetails();
    } else if (open) {
      // Reset form
      setTitle('');
      setCategory('CODE_OF_CONDUCT');
      setContent('');
      setChangeSummary('Initial Policy Creation');
      setMandatory(true);
      setEffectiveAt(new Date().toISOString().slice(0, 10));
      setLinkedModule('NONE');
      setSelectedDeptIds([]);
    }
  }, [policyId, open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !content.trim()) {
      toast.error('Please fill in title and policy text');
      return;
    }
    if (!activeWorkspace?.id) return;

    setSaving(true);
    try {
      const targets = selectedDeptIds.map(dId => ({ target_type: 'DEPARTMENT', target_id: dId }));

      if (policyId) {
        // Update
        const res = await fetch(`/api/hr/policies/${policyId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            title,
            category,
            content,
            changeSummary,
            mandatory,
            effectiveAt: effectiveAt ? new Date(effectiveAt).toISOString() : null,
            linkedModule,
            targets
          })
        });
        const json = await res.json();
        if (json.error) throw new Error(json.error);
        toast.success('Policy draft updated');
      } else {
        // Create new
        const res = await fetch('/api/hr/policies', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            workspaceId: activeWorkspace.id,
            title,
            category,
            content,
            changeSummary,
            mandatory,
            effectiveAt: effectiveAt ? new Date(effectiveAt).toISOString() : null,
            linkedModule,
            targets
          })
        });
        const json = await res.json();
        if (json.error) throw new Error(json.error);
        toast.success('Policy created as Draft');
      }

      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to save policy');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[88vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-xl font-bold flex items-center gap-2">
            <Shield className="size-5 text-primary" />
            {policyId ? 'Edit & Version Policy Document' : 'Create New Company Policy'}
          </DialogTitle>
          <DialogDescription>
            Draft, version, and configure compliance policies for your workspace.
          </DialogDescription>
        </DialogHeader>

        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="size-8 animate-spin text-primary" />
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-6 py-2">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Policy Title</Label>
                <Input
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="e.g. Employee Handbook & Code of Conduct 2026"
                  required
                />
              </div>

              <div className="space-y-2">
                <Label>Policy Category</Label>
                <Select value={category} onValueChange={(val) => setCategory(val || 'CODE_OF_CONDUCT')}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {CATEGORIES.map(c => (
                      <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Effective Date</Label>
                <Input
                  type="date"
                  value={effectiveAt}
                  onChange={(e) => setEffectiveAt(e.target.value)}
                />
              </div>

              <div className="space-y-2">
                <Label>Link to Operational Module</Label>
                <Select value={linkedModule} onValueChange={(val) => setLinkedModule(val || 'NONE')}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="NONE">None (General Document)</SelectItem>
                    <SelectItem value="ATTENDANCE">Attendance & Shift Settings</SelectItem>
                    <SelectItem value="LEAVE">Leave Rules & Accruals</SelectItem>
                    <SelectItem value="PAYROLL">Payroll & Salary Rules</SelectItem>
                    <SelectItem value="EXPENSES">Expense Claims & Reimbursement</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Policy Content (Visual Rich Text Editor)</Label>
              <RichTextEditor
                value={content}
                onChange={setContent}
                placeholder="Enter complete policy text, terms, clauses, and employee responsibilities..."
                minHeight="220px"
              />
            </div>

            <div className="space-y-2">
              <Label>Change Summary (&quot;What&apos;s New in this Version&quot;)</Label>
              <Input
                value={changeSummary}
                onChange={(e) => setChangeSummary(e.target.value)}
                placeholder="e.g. Updated annual leave allowance from 18 to 21 days"
              />
            </div>

            <div className="flex items-center space-x-2 pt-2">
              <Checkbox
                id="mandatory"
                checked={mandatory}
                onCheckedChange={(checked) => setMandatory(!!checked)}
              />
              <label htmlFor="mandatory" className="text-sm font-medium leading-none cursor-pointer">
                Mandatory Sign-off (Requires employee digital signature)
              </label>
            </div>

            <DialogFooter className="pt-4 border-t border-border">
              <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={saving} className="bg-primary text-primary-foreground">
                {saving ? <Loader2 className="size-4 animate-spin mr-2" /> : null}
                {policyId ? 'Save Draft / Update' : 'Create Draft Policy'}
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { toast } from 'sonner';
import { Loader2, Plus, Trash2, Zap } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

import { formatMemberName } from '@/components/tasks/task-form';
import { IconAction } from "@/components/ui/icon-action";

interface AutomationsSettingsProps {
  projectId: string;
}

export function AutomationsSettings({ projectId }: AutomationsSettingsProps) {
  const { activeWorkspace: workspace, activeMember } = useWorkspace();
  const supabase = createClient();
  
  const [loading, setLoading] = useState(true);
  const [automations, setAutomations] = useState<any[]>([]);
  const [statuses, setStatuses] = useState<any[]>([]);
  const [members, setMembers] = useState<any[]>([]);

  // New Rule State
  const [isCreating, setIsCreating] = useState(false);
  const [newRuleName, setNewRuleName] = useState('');
  const [triggerStatusId, setTriggerStatusId] = useState('');
  const [actionType, setActionType] = useState('ASSIGN_MEMBER');
  const [actionMemberId, setActionMemberId] = useState('');
  const [actionPriority, setActionPriority] = useState('high');

  const fetchData = useCallback(async () => {
    if (!projectId || !workspace) return;
    setLoading(true);
    
    try {
      const [autoRes, statusesRes, membersRes] = await Promise.all([
        supabase.from('project_automations').select('*').eq('project_id', projectId).order('created_at', { ascending: false }),
        supabase.from('project_statuses').select('*').eq('project_id', projectId).order('sort_order', { ascending: true }),
        fetch('/api/account/members').then((r) => r.json()).catch(() => ({ members: [] }))
      ]);
      
      setAutomations(autoRes.data || []);
      setStatuses(statusesRes.data || []);
      setMembers(membersRes?.members || []);
    } catch (err) {
      console.error(err);
      toast.error('Failed to load automations data');
    } finally {
      setLoading(false);
    }
  }, [projectId, workspace, supabase]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const toggleRule = async (id: string, currentActive: boolean) => {
    const { error } = await supabase.from('project_automations').update({ is_active: !currentActive }).eq('id', id);
    if (error) {
      toast.error('Failed to toggle automation');
    } else {
      setAutomations(prev => prev.map(a => a.id === id ? { ...a, is_active: !currentActive } : a));
    }
  };

  const deleteRule = async (id: string) => {
    const { error } = await supabase.from('project_automations').delete().eq('id', id);
    if (error) {
      toast.error('Failed to delete automation');
    } else {
      setAutomations(prev => prev.filter(a => a.id !== id));
      toast.success('Automation deleted');
    }
  };

  const handleCreateRule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!workspace || !activeMember || !triggerStatusId) {
      toast.error('Please select a trigger status');
      return;
    }

    let payload = {};
    if (actionType === 'ASSIGN_MEMBER') {
      if (!actionMemberId) {
        toast.error('Please select a member to assign');
        return;
      }
      payload = { member_id: actionMemberId };
    } else {
      payload = { priority: actionPriority };
    }

    try {
      const { data, error } = await supabase.from('project_automations').insert({
        project_id: projectId,
        workspace_id: workspace.id,
        name: newRuleName || 'Untitled Rule',
        trigger_type: 'STATUS_CHANGED',
        trigger_condition: { status_id: triggerStatusId },
        action_type: actionType,
        action_payload: payload,
        created_by: activeMember.id
      }).select().single();

      if (error) throw error;
      
      setAutomations([data, ...automations]);
      setIsCreating(false);
      setNewRuleName('');
      setTriggerStatusId('');
      setActionMemberId('');
      toast.success('Automation created successfully!');
    } catch (err: any) {
      console.error(err);
      toast.error('Failed to create automation');
    }
  };

  if (loading) {
    return <div className="flex justify-center p-8"><Loader2 className="size-6 animate-spin text-primary" /></div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-medium">Automations Engine</h3>
          <p className="text-sm text-muted-foreground">Automate repetitive tasks when events happen.</p>
        </div>
        <Button onClick={() => setIsCreating(!isCreating)}>
          {isCreating ? 'Cancel' : <><Plus className="size-4 mr-2" /> New Rule</>}
        </Button>
      </div>

      {isCreating && (
        <div className="p-4 border rounded-md bg-muted/30 space-y-4">
          <form onSubmit={handleCreateRule} className="space-y-4">
            <div className="space-y-2">
              <Label>Rule Name</Label>
              <Input 
                value={newRuleName} 
                onChange={(e) => setNewRuleName(e.target.value)} 
                placeholder="e.g., Auto-assign QA Tester" 
                required
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2 p-3 border border-border/50 rounded-none bg-card">
                <Label className="text-xs uppercase text-muted-foreground font-bold tracking-wider">WHEN</Label>
                <div className="flex items-center gap-2">
                  <span className="text-sm whitespace-nowrap">Task moves to</span>
                  <Select value={triggerStatusId} onValueChange={(val) => setTriggerStatusId(val || '')}>
                    <SelectTrigger><SelectValue placeholder="Select Status" /></SelectTrigger>
                    <SelectContent>
                      {statuses.map(s => (
                        <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2 p-3 border border-border/50 rounded-none bg-card">
                <Label className="text-xs uppercase text-muted-foreground font-bold tracking-wider">THEN</Label>
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-sm">Do</span>
                  <Select value={actionType} onValueChange={(val) => setActionType(val || '')}>
                    <SelectTrigger className="w-auto"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="ASSIGN_MEMBER">Assign to Member</SelectItem>
                      <SelectItem value="SET_PRIORITY">Change Priority</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                
                {actionType === 'ASSIGN_MEMBER' && (
                  <Select value={actionMemberId} onValueChange={(val) => setActionMemberId(val || '')}>
                    <SelectTrigger><SelectValue placeholder="Select Team Member" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">Unassigned</SelectItem>
                      {members.map(m => (
                        <SelectItem key={m.id} value={m.id}>
                          {formatMemberName(m)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}

                {actionType === 'SET_PRIORITY' && (
                  <Select value={actionPriority} onValueChange={(val) => setActionPriority(val || '')}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Low Priority</SelectItem>
                      <SelectItem value="medium">Medium Priority</SelectItem>
                      <SelectItem value="high">High Priority</SelectItem>
                    </SelectContent>
                  </Select>
                )}
              </div>
            </div>

            <Button type="submit">Save Automation Rule</Button>
          </form>
        </div>
      )}

      <div className="space-y-3">
        {automations.length === 0 && !isCreating && (
          <div className="text-center py-10 border border-dashed rounded-lg">
            <Zap className="size-8 mx-auto text-muted-foreground mb-3 opacity-50" />
            <p className="text-sm text-muted-foreground">No automations configured for this project.</p>
          </div>
        )}

        {automations.map(rule => {
          const targetStatus = statuses.find(s => s.id === rule.trigger_condition?.status_id);
          
          let actionText = '';
          if (rule.action_type === 'ASSIGN_MEMBER') {
            const memberId = rule.action_payload?.member_id;
            if (memberId === 'none') {
               actionText = 'Remove Assignee';
            } else {
               const member = members.find(m => m.id === memberId);
               actionText = `Assign to ${member ? formatMemberName(member) : 'Unassigned'}`;
            }
          } else if (rule.action_type === 'SET_PRIORITY') {
            actionText = `Set Priority to ${rule.action_payload?.priority}`;
          }

          return (
            <div key={rule.id} className="flex items-center justify-between p-4 border rounded-md bg-card shadow-sm">
              <div className="space-y-1">
                <div className="flex items-center gap-2">
                  <h4 className="font-medium text-sm">{rule.name}</h4>
                  {!rule.is_active && <span className="text-[10px] uppercase bg-muted text-muted-foreground px-1.5 py-0.5 rounded-none">Disabled</span>}
                </div>
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <span>When Status is <strong className="text-foreground">{targetStatus?.name || 'Unknown'}</strong></span>
                  <span>→</span>
                  <span className="text-primary font-medium">{actionText}</span>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <Switch checked={rule.is_active} onCheckedChange={() => toggleRule(rule.id, rule.is_active)} />
                <IconAction
                  label="Delete"
                  icon={<Trash2 className="size-4" />}
                  variant="ghost"
                  onClick={() => deleteRule(rule.id)}
                  className="text-muted-foreground hover:text-destructive"
                />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Loader2,
  Plus,
  Eye,
  Share2,
  X,
  CheckSquare,
  Sparkles,
  Bookmark,
  Bug,
  ChevronDown,
  Zap
} from 'lucide-react';
import { formatMemberName } from '@/components/tasks/task-form';
import { IconAction } from "@/components/ui/icon-action";

interface EpicDetailsModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  epicId: string | null;
  projectId: string;
  onSaved?: () => void;
}

export function EpicDetailsModal({
  open,
  onOpenChange,
  epicId,
  projectId,
  onSaved,
}: EpicDetailsModalProps) {
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  const [, setEpic] = useState<any | null>(null);
  const [childTasks, setChildTasks] = useState<any[]>([]);
  const [, setMembers] = useState<any[]>([]);
  const [statuses, setStatuses] = useState<any[]>([]);

  // Form states
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [newChildTitle, setNewChildTitle] = useState('');
  const [isAddingChild, setIsAddingChild] = useState(false);
  const [saving, setSaving] = useState(false);

  const fetchEpicData = useCallback(async () => {
    if (!epicId) return;
    setLoading(true);

    try {
      const [epicRes, tasksRes, statusesRes, membersRes] = await Promise.all([
        supabase.from('epics').select('*').eq('id', epicId).single(),
        supabase
          .from('tasks')
          .select('*, project_statuses(id, name, color, category)')
          .eq('epic_id', epicId)
          .order('created_at', { ascending: true }),
        supabase
          .from('project_statuses')
          .select('*')
          .eq('project_id', projectId)
          .order('sort_order', { ascending: true }),
        fetch('/api/account/members').then((r) => r.json()).catch(() => ({ members: [] })),
      ]);

      const epicData = epicRes.data;
      setEpic(epicData);
      setName(epicData?.name || '');
      setDescription(epicData?.description || '');
      setStatuses(statusesRes.data || []);

      const memberList = membersRes?.members || [];
      setMembers(memberList);

      const memberMap = new Map(memberList.map((m: any) => [m.id, m]));
      const enrichedTasks = (tasksRes.data || []).map((t: any) => ({
        ...t,
        assignee_member: t.assigned_workspace_member_id
          ? memberMap.get(t.assigned_workspace_member_id)
          : null,
      }));

      setChildTasks(enrichedTasks);
    } catch (err) {
      console.error(err);
      toast.error('Failed to load epic details');
    } finally {
      setLoading(false);
    }
  }, [epicId, projectId, supabase]);

  useEffect(() => {
    if (open && epicId) {
      fetchEpicData();
    }
  }, [open, epicId, fetchEpicData]);

  // Calculate percentage done
  const completedCount = childTasks.filter(
    (t) => t.status === 'completed' || t.project_statuses?.category === 'DONE'
  ).length;
  const inProgressCount = childTasks.filter(
    (t) => t.status === 'in_progress' || t.project_statuses?.category === 'IN_PROGRESS'
  ).length;
  const percentDone =
    childTasks.length > 0 ? Math.round((completedCount / childTasks.length) * 100) : 0;

  const handleAddChildTask = async () => {
    if (!newChildTitle.trim() || !epicId) return;
    setIsAddingChild(true);

    try {
      const defaultStatus = statuses[0]?.id || null;
      const { data, error } = await supabase
        .from('tasks')
        .insert({
          project_id: projectId,
          epic_id: epicId,
          title: newChildTitle.trim(),
          status_id: defaultStatus,
          task_type: 'STORY',
        })
        .select('*, project_statuses(id, name, color, category)')
        .single();

      if (error) throw error;
      setChildTasks((prev) => [...prev, data]);
      setNewChildTitle('');
      toast.success('Child work item added');
      onSaved?.();
    } catch (err: any) {
      toast.error(err.message || 'Failed to add child item');
    } finally {
      setIsAddingChild(false);
    }
  };

  const handleUpdateStatus = async (taskId: string, statusId: string) => {
    try {
      const selectedStatusObj = statuses.find((s) => s.id === statusId);
      const { error } = await supabase
        .from('tasks')
        .update({
          status_id: statusId,
          status: selectedStatusObj?.category?.toLowerCase() || 'in_progress',
        })
        .eq('id', taskId);

      if (error) throw error;
      setChildTasks((prev) =>
        prev.map((t) =>
          t.id === taskId
            ? { ...t, status_id: statusId, project_statuses: selectedStatusObj }
            : t
        )
      );
      toast.success('Status updated');
      onSaved?.();
    } catch (err: any) {
      toast.error(err.message || 'Failed to update status');
    }
  };

  const handleSaveEpic = async () => {
    if (!epicId || !name.trim()) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from('epics')
        .update({ name: name.trim(), description: description.trim() })
        .eq('id', epicId);

      if (error) throw error;
      toast.success('Epic updated');
      onSaved?.();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update epic');
    } finally {
      setSaving(false);
    }
  };

  const getIssueIcon = (type?: string) => {
    switch (type?.toUpperCase()) {
      case 'FEATURE':
        return <Sparkles className="size-4 text-emerald-500 shrink-0" />;
      case 'STORY':
        return <Bookmark className="size-4 text-green-600 shrink-0" />;
      case 'BUG':
        return <Bug className="size-4 text-red-500 shrink-0" />;
      default:
        return <CheckSquare className="size-4 text-blue-500 shrink-0" />;
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-5xl max-h-[90vh] overflow-y-auto p-0 gap-0 border-border bg-card">
        {loading ? (
          <div className="flex justify-center items-center py-24">
            <Loader2 className="size-8 animate-spin text-primary" />
          </div>
        ) : (
          <div className="flex flex-col h-full">
            {/* Jira Top Header Bar */}
            <div className="flex items-center justify-between px-6 py-3 border-b border-border bg-muted/20">
              <div className="flex items-center gap-2 text-xs font-mono text-muted-foreground">
                <Zap className="size-3.5 text-purple-500" />
                <span className="font-semibold text-foreground">EPIC</span>
                <span>/</span>
                <span>EPIC-{epicId?.slice(0, 5).toUpperCase()}</span>
              </div>

              <div className="flex items-center gap-2">
                <IconAction
                  label="View"
                  icon={<Eye className="size-4" />}
                  variant="ghost"
                  className="size-8 text-muted-foreground"
                />
                <Button variant="ghost" size="icon" className="size-8 text-muted-foreground">
                  <Share2 className="size-4" />
                </Button>
                <IconAction
                  label="Close"
                  icon={<X className="size-4" />}
                  variant="ghost"
                  className="size-8 text-muted-foreground"
                  onClick={() => onOpenChange(false)}
                />
              </div>
            </div>

            {/* Jira 2-Column Main Layout */}
            <div className="grid grid-cols-1 lg:grid-cols-12 divide-y lg:divide-y-0 lg:divide-x divide-border">
              {/* Left Main Work Content (8 cols) */}
              <div className="lg:col-span-8 p-6 space-y-6">
                {/* Epic Title Header */}
                <div className="flex items-center gap-3">
                  <div className="size-8 rounded-none bg-purple-600 flex items-center justify-center text-foreground shrink-0 font-bold text-sm">
                    E
                  </div>
                  <Input
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="text-xl font-bold border-none shadow-none focus-visible:ring-0 p-0 h-auto text-foreground"
                    placeholder="Epic Name"
                  />
                </div>

                {/* Description */}
                <div className="space-y-2">
                  <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                    Description
                  </span>
                  <Textarea
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder="Add a description..."
                    className="bg-card border-border text-sm min-h-[90px]"
                  />
                </div>

                {/* Child Work Items Section */}
                <div className="space-y-4 pt-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold uppercase tracking-wider text-foreground flex items-center gap-1.5">
                      <ChevronDown className="size-4" /> Child work items
                    </span>
                    <span className="text-xs font-mono font-semibold text-muted-foreground">
                      {percentDone}% Done
                    </span>
                  </div>

                  {/* Jira Multi-Color Progress Bar */}
                  <div className="w-full h-2 rounded-full bg-muted overflow-hidden flex">
                    <div
                      className="bg-emerald-500 h-full transition-all"
                      style={{ width: `${percentDone}%` }}
                      title={`${completedCount} Completed`}
                    />
                    <div
                      className="bg-blue-500 h-full transition-all"
                      style={{
                        width: `${childTasks.length > 0 ? (inProgressCount / childTasks.length) * 100 : 0}%`,
                      }}
                      title={`${inProgressCount} In Progress`}
                    />
                  </div>

                  {/* Child Work Table */}
                  <div className="rounded-md border border-border bg-card overflow-hidden">
                    <Table className="text-xs">
                      <TableHeader className="bg-muted/40 uppercase tracking-wider font-semibold text-muted-foreground">
                        <TableRow>
                          <TableHead className="py-2.5 px-3">Work</TableHead>
                          <TableHead className="py-2.5 px-3 w-20">Priority</TableHead>
                          <TableHead className="py-2.5 px-3 w-28">Assignee</TableHead>
                          <TableHead className="py-2.5 px-3 w-32 text-right">Status</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody className="divide-y divide-border/50">
                        {childTasks.length === 0 ? (
                          <TableRow>
                            <TableCell colSpan={4} className="py-6 text-center text-muted-foreground">
                              No child work items under this epic yet.
                            </TableCell>
                          </TableRow>
                        ) : (
                          childTasks.map((ct) => {
                            const assigneeName = formatMemberName(ct.assignee_member);

                            return (
                              <TableRow key={ct.id} className="hover:bg-muted/30">
                                {/* Work Column: Type Icon + Key + Title */}
                                <TableCell className="py-2.5 px-3 font-medium">
                                  <div className="flex items-center gap-2">
                                    {getIssueIcon(ct.task_type)}
                                    <span className="text-primary font-mono text-[11px] hover:underline cursor-pointer">
                                      TASK-{ct.id.slice(0, 4).toUpperCase()}
                                    </span>
                                    <span className="text-foreground truncate max-w-[260px]">
                                      {ct.title}
                                    </span>
                                  </div>
                                </TableCell>

                                {/* Priority */}
                                <TableCell className="py-2.5 px-3 capitalize text-muted-foreground">
                                  {ct.priority || 'Medium'}
                                </TableCell>

                                {/* Assignee */}
                                <TableCell className="py-2.5 px-3">
                                  <div className="flex items-center gap-1.5">
                                    <Avatar className="size-5">
                                      <AvatarFallback className="text-[9px] bg-primary/10 text-primary">
                                        {assigneeName.charAt(0)}
                                      </AvatarFallback>
                                    </Avatar>
                                    <span className="truncate max-w-[80px] text-muted-foreground">
                                      {assigneeName}
                                    </span>
                                  </div>
                                </TableCell>

                                {/* Status Selector */}
                                <TableCell className="py-2.5 px-3 text-right">
                                  <Select
                                    value={ct.status_id || statuses[0]?.id}
                                    onValueChange={(val) => handleUpdateStatus(ct.id, val)}
                                  >
                                    <SelectTrigger className="h-7 text-[11px] bg-muted border-border font-medium capitalize">
                                      <SelectValue placeholder="Status" />
                                    </SelectTrigger>
                                    <SelectContent>
                                      {statuses.map((s) => (
                                        <SelectItem key={s.id} value={s.id} className="text-xs">
                                          {s.name}
                                        </SelectItem>
                                      ))}
                                    </SelectContent>
                                  </Select>
                                </TableCell>
                              </TableRow>
                            );
                          })
                        )}
                      </TableBody>
                    </Table>
                  </div>

                  {/* Inline Quick Add Child Task Input */}
                  <div className="flex items-center gap-2 pt-1">
                    <Input
                      value={newChildTitle}
                      onChange={(e) => setNewChildTitle(e.target.value)}
                      placeholder="+ Add child story or task..."
                      className="bg-card border-border h-8 text-xs"
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          handleAddChildTask();
                        }
                      }}
                    />
                    <IconAction label="Add" icon={isAddingChild ? <Loader2 className="size-3 animate-spin" /> : <Plus className="size-3.5 " />} onClick={handleAddChildTask}
                      disabled={isAddingChild || !newChildTitle.trim()}
                      className="h-8 text-xs bg-primary text-primary-foreground shrink-0" />
                  </div>
                </div>
              </div>

              {/* Right Details Sidebar (4 cols) */}
              <div className="lg:col-span-4 p-6 space-y-6 bg-muted/10">
                <div className="rounded-lg border border-border bg-card p-4 space-y-4 shadow-sm">
                  <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground block">
                    Details
                  </span>

                  {/* Assignee */}
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-muted-foreground">Assignee</span>
                    <span className="font-medium text-foreground">Unassigned</span>
                  </div>

                  {/* Reporter */}
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-muted-foreground">Reporter</span>
                    <span className="font-medium text-foreground">Workspace Admin</span>
                  </div>

                  {/* Status */}
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-muted-foreground">Type</span>
                    <span className="font-semibold text-purple-600">Epic</span>
                  </div>

                  {/* Total Child Tasks */}
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-muted-foreground">Child Work Items</span>
                    <span className="font-mono text-foreground font-semibold">{childTasks.length}</span>
                  </div>
                </div>

                {/* Footer Save Button */}
                <div className="flex justify-end gap-2 pt-4">
                  <Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>
                    Close
                  </Button>
                  <IconAction label="Save Changes" icon={<Loader2 className="size-3.5 animate-spin " />} onClick={handleSaveEpic} disabled={saving} />
                </div>
              </div>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Button } from '@/components/ui/button';
import { Plus, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import {
  DndContext,
  DragOverlay,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragStartEvent,
  DragEndEvent,
  useDroppable
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { KanbanTask } from '@/components/tasks/kanban-task';
import { IconAction } from "@/components/ui/icon-action";

// --- Subcomponents for DND Zones ---

function DroppableSprint({ sprint, tasks, onStartSprint }: { sprint: any, tasks: any[], onStartSprint: () => void }) {
  const { setNodeRef, isOver } = useDroppable({ id: sprint.id });
  
  return (
    <div className={`border rounded-lg overflow-hidden transition-colors ${isOver ? 'border-primary/50 bg-primary/5' : 'border-border bg-card'}`}>
      <div className="bg-muted/50 p-3 border-b flex items-center justify-between">
        <h4 className="font-medium text-sm flex items-center gap-2">
          {sprint.name} 
          <span className="bg-muted text-muted-foreground text-[10px] px-1.5 py-0.5 rounded-full">{tasks.length}</span>
        </h4>
        <div className="flex items-center gap-2">
          <span className="text-xs uppercase px-2 py-1 bg-muted rounded-none text-muted-foreground">{sprint.status}</span>
          {sprint.status === 'planning' && (
            <Button size="sm" variant="outline" className="h-7 text-xs" onClick={onStartSprint}>Start Sprint</Button>
          )}
        </div>
      </div>
      <div ref={setNodeRef} className="p-3 min-h-[100px] flex flex-col gap-2">
        {tasks.length === 0 ? (
          <div className="text-xs text-muted-foreground text-center py-6 border-2 border-dashed border-transparent rounded-none">
            Drag tasks here
          </div>
        ) : (
          tasks.map(task => (
            <KanbanTask key={task.id} task={task} onEdit={() => {}} />
          ))
        )}
      </div>
    </div>
  );
}

function DroppableBacklog({ tasks }: { tasks: any[] }) {
  const { setNodeRef, isOver } = useDroppable({ id: 'backlog' });
  
  return (
    <div className={`w-full md:w-1/3 border rounded-lg p-4 transition-colors flex flex-col ${isOver ? 'border-primary/50 bg-primary/5' : 'border-border bg-muted/30'}`}>
      <div className="flex items-center justify-between mb-4">
        <h3 className="font-semibold text-foreground">Backlog</h3>
        <span className="text-xs text-muted-foreground bg-muted px-2 py-1 rounded-none">{tasks.length} issues</span>
      </div>
      <div ref={setNodeRef} className="flex-1 space-y-2 min-h-[200px]">
        {tasks.length === 0 ? (
          <p className="text-sm text-muted-foreground text-center py-4">Your backlog is empty.</p>
        ) : (
          tasks.map(task => (
             <KanbanTask key={task.id} task={task} onEdit={() => {}} />
          ))
        )}
      </div>
    </div>
  );
}

// --- Main View ---

interface PlanningViewProps {
  projectId: string;
  canManage: boolean;
}

export function PlanningView({ projectId, canManage }: PlanningViewProps) {
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  const [sprints, setSprints] = useState<any[]>([]);
  const [tasks, setTasks] = useState<any[]>([]);
  const [activeDragTask, setActiveDragTask] = useState<any | null>(null);

  const fetchPlanningData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    const [sprintsRes, tasksRes] = await Promise.all([
      supabase.from('sprints').select('*').eq('project_id', projectId).order('created_at', { ascending: true }),
      supabase.from('tasks').select(`*, assignee:workspace_members!tasks_assigned_workspace_member_id_fkey ( id, user_id )`).eq('project_id', projectId).is('parent_id', null)
    ]);

    if (!sprintsRes.error) setSprints(sprintsRes.data || []);
    if (!tasksRes.error) {
      const taskList = tasksRes.data || [];
      if (taskList.length > 0) {
        const userIds = taskList.map((t: any) => t.assignee?.user_id).filter(Boolean);
        if (userIds.length > 0) {
          const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name, avatar_url').in('user_id', userIds);
          const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
          taskList.forEach((t: any) => { if (t.assignee?.user_id) t.assignee.profiles = profileMap[t.assignee.user_id] || null; });
        }
      }
      setTasks(taskList);
    }

    setLoading(false);
  }, [projectId, supabase]);

  useEffect(() => {
    fetchPlanningData();
  }, [fetchPlanningData]);

  const createSprint = async () => {
    try {
      const { error } = await supabase.from('sprints').insert({
        project_id: projectId,
        name: `Sprint ${sprints.length + 1}`
      });
      if (error) throw error;
      toast.success('Sprint created');
      fetchPlanningData();
    } catch {
      toast.error('Failed to create sprint');
    }
  };

  const startSprint = async (sprintId: string) => {
    try {
      // Typically, you only allow one active sprint at a time.
      const hasActive = sprints.some(s => s.status === 'active');
      if (hasActive) {
        toast.error('You already have an active sprint.');
        return;
      }
      
      const { error } = await supabase.from('sprints').update({ status: 'active', start_date: new Date().toISOString() }).eq('id', sprintId);
      if (error) throw error;
      toast.success('Sprint started!');
      fetchPlanningData();
    } catch {
      toast.error('Failed to start sprint');
    }
  };

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    const task = tasks.find(t => t.id === active.id);
    setActiveDragTask(task);
  };

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveDragTask(null);

    if (!over) return;
    const taskId = active.id as string;
    const overId = over.id as string;

    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    let targetSprintId: string | null = null;
    if (overId === 'backlog') {
      targetSprintId = null;
    } else {
      const isSprintContainer = sprints.some(s => s.id === overId);
      if (isSprintContainer) {
        targetSprintId = overId;
      } else {
        const overTask = tasks.find(t => t.id === overId);
        targetSprintId = overTask ? (overTask.sprint_id || null) : null;
      }
    }

    if (task.sprint_id === targetSprintId) return;

    // Optimistic update
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, sprint_id: targetSprintId } : t));

    try {
      const { error: err1 } = await supabase
        .from('tasks')
        .update({ sprint_id: targetSprintId, status: task.status || 'todo' })
        .eq('id', taskId);

      if (err1) {
        const { error: err2 } = await supabase
          .from('tasks')
          .update({ sprint_id: targetSprintId })
          .eq('id', taskId);

        if (err2) throw err2;
      }
    } catch (err: any) {
      console.error('Drag end error:', err);
      toast.error('Failed to move task');
      fetchPlanningData(); // revert
    }
  };

  if (loading) {
    return <div className="flex justify-center p-8"><Loader2 className="size-6 animate-spin text-primary" /></div>;
  }

  const backlogTasks = tasks.filter(t => !t.sprint_id);

  return (
    <DndContext sensors={sensors} collisionDetection={closestCorners} onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
      <div className="flex flex-col md:flex-row gap-6 items-start">
        
        {/* Backlog Zone */}
        <DroppableBacklog tasks={backlogTasks} />

        {/* Sprints Zone */}
        <div className="w-full md:w-2/3 space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="font-semibold text-foreground">Sprints</h3>
            {canManage && (
              <IconAction label="Create Sprint" icon={<Plus className="size-4 " />} onClick={createSprint} />
            )}
          </div>

          {sprints.length === 0 ? (
            <div className="p-8 text-center border border-dashed rounded-lg text-muted-foreground">
              No sprints have been created yet.
            </div>
          ) : (
            sprints.map(sprint => (
              <DroppableSprint 
                key={sprint.id} 
                sprint={sprint} 
                tasks={tasks.filter(t => t.sprint_id === sprint.id)} 
                onStartSprint={() => startSprint(sprint.id)}
              />
            ))
          )}
        </div>

      </div>

      <DragOverlay>
        {activeDragTask ? <KanbanTask task={activeDragTask} onEdit={() => {}} isOverlay /> : null}
      </DragOverlay>
    </DndContext>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Loader2, Activity, PlusCircle, Layers } from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { formatDistanceToNow } from 'date-fns';
import { formatMemberName } from '@/components/tasks/task-form';

interface ProjectActivityLogProps {
  projectId: string;
}

export function ProjectActivityLog({ projectId }: ProjectActivityLogProps) {
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  const [activities, setActivities] = useState<any[]>([]);

  const fetchActivityLog = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      // 1. Fetch recent tasks created/updated in this project
      const { data: tasks } = await supabase
        .from('tasks')
        .select(`
          id, title, task_type, priority, created_at,
          assigned_workspace_member_id,
          status:project_statuses ( name, category )
        `)
        .eq('project_id', projectId)
        .order('created_at', { ascending: false })
        .limit(30);

      // 2. Fetch epics in this project
      const { data: epics } = await supabase
        .from('epics')
        // `epics` names its label column `name`, not `title`.
        .select('id, name, created_at, status')
        .eq('project_id', projectId)
        .order('created_at', { ascending: false })
        .limit(10);

      // 3. Fetch members to resolve user details
      const membersRes = await fetch('/api/account/members')
        .then(r => r.json())
        .catch(() => ({ members: [] }));
      const members = membersRes?.members || [];
      const memberMap = Object.fromEntries(members.map((m: any) => [m.id, m]));

      // 4. Transform into unified activity items
      const items: any[] = [];

      (tasks || []).forEach(task => {
        const member = memberMap[task.assigned_workspace_member_id];
        const statusObj = Array.isArray(task.status) ? task.status[0] : task.status;
        items.push({
          id: `task-${task.id}`,
          type: 'TASK_CREATED',
          title: `Created task "${task.title}"`,
          itemTitle: task.title,
          badge: task.task_type || 'TASK',
          statusName: statusObj?.name || 'To Do',
          timestamp: new Date(task.created_at),
          user: member ? formatMemberName(member) : 'Team Member',
          avatar: member?.avatar_url,
          icon: PlusCircle,
          iconColor: 'text-blue-500 bg-blue-500/10'
        });
      });

      (epics || []).forEach(epic => {
        items.push({
          id: `epic-${epic.id}`,
          type: 'EPIC_CREATED',
          title: `Created epic "${epic.name}"`,
          itemTitle: epic.name,
          badge: 'EPIC',
          statusName: epic.status || 'IN_PROGRESS',
          timestamp: new Date(epic.created_at),
          user: 'Project Lead',
          avatar: null,
          icon: Layers,
          iconColor: 'text-purple-500 bg-purple-500/10'
        });
      });

      // Sort chronologically
      items.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

      setActivities(items);
    } catch (err) {
      console.error('Failed to load project activity:', err);
    } finally {
      setLoading(false);
    }
  }, [projectId, supabase]);

  useEffect(() => {
    fetchActivityLog();
  }, [fetchActivityLog]);

  if (loading) {
    return (
      <div className="flex justify-center p-12">
        <Loader2 className="size-6 animate-spin text-primary" />
      </div>
    );
  }

  if (activities.length === 0) {
    return (
      <div className="rounded-lg border border-border bg-card p-12 text-center">
        <Activity className="size-8 mx-auto text-muted-foreground mb-3 opacity-50" />
        <h3 className="font-semibold text-foreground">No recent activity</h3>
        <p className="text-sm text-muted-foreground mt-1">Actions and updates performed on this project will appear here.</p>
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-border bg-card p-6 shadow-sm space-y-6">
      <div className="flex items-center justify-between border-b pb-4">
        <div className="flex items-center gap-2">
          <Activity className="size-5 text-primary" />
          <h3 className="font-semibold text-foreground text-base">Project Audit Log & Activity Stream</h3>
        </div>
        <Badge variant="outline" className="text-xs font-normal">
          {activities.length} Events Logged
        </Badge>
      </div>

      <div className="relative pl-6 space-y-6 before:absolute before:left-2.5 before:top-3 before:bottom-3 before:w-0.5 before:bg-border">
        {activities.map((act) => {
          const IconComp = act.icon;
          return (
            <div key={act.id} className="relative flex items-start gap-4 group">
              <div className={`absolute -left-6 top-0.5 size-5 rounded-full flex items-center justify-center border bg-background ${act.iconColor}`}>
                <IconComp className="size-3" />
              </div>

              <div className="flex-1 bg-muted/20 hover:bg-muted/40 p-3.5 rounded-lg border border-border/60 transition-colors">
                <div className="flex items-center justify-between gap-2 mb-1">
                  <div className="flex items-center gap-2">
                    <Avatar className="size-5">
                      <AvatarImage src={act.avatar} />
                      <AvatarFallback className="text-[9px]">{act.user?.charAt(0)}</AvatarFallback>
                    </Avatar>
                    <span className="text-xs font-medium text-foreground">{act.user}</span>
                    <span className="text-xs text-muted-foreground">{act.title}</span>
                  </div>
                  <span className="text-[11px] text-muted-foreground whitespace-nowrap">
                    {formatDistanceToNow(act.timestamp, { addSuffix: true })}
                  </span>
                </div>

                <div className="flex items-center gap-2 mt-2">
                  <Badge variant="secondary" className="text-[10px] uppercase tracking-wider font-semibold">
                    {act.badge}
                  </Badge>
                  <Badge variant="outline" className="text-[10px]">
                    {act.statusName}
                  </Badge>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { Loader2 } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';

interface ProjectFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  project?: any | null;
  onSaved: () => void;
}

export function ProjectForm({ open, onOpenChange, project, onSaved }: ProjectFormProps) {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  
  const [saving, setSaving] = useState(false);
  const [managers, setManagers] = useState<any[]>([]);
  const [clients, setClients] = useState<any[]>([]);

  // Form State
  const [name, setName] = useState('');
  const [projectType, setProjectType] = useState('SCRUM');
  const [status, setStatus] = useState('active');
  const [managerId, setManagerId] = useState('none');
  const [clientId, setClientId] = useState('none');
  const [budget, setBudget] = useState('');
  const [deadline, setDeadline] = useState('');
  const [hourlyRate, setHourlyRate] = useState('');
  const [isPublic, setIsPublic] = useState(false);

  useEffect(() => {
    if (open && activeWorkspace?.id) {
      // Fetch references
      // Two-step fetch: workspace_members.user_id refs auth.users (not public.profiles),
      // so PostgREST cannot join directly. We fetch members + profiles separately and merge.
      supabase.from('workspace_members').select('id, user_id').eq('workspace_id', activeWorkspace.id).then(async ({ data: members }) => {
        if (!members || members.length === 0) { setManagers([]); return; }
        const userIds = members.map((m: any) => m.user_id);
        const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name').in('user_id', userIds);
        const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
        setManagers(members.map((m: any) => ({ ...m, profiles: profileMap[m.user_id] || null })));
      });
      supabase.from('contacts').select('id, name, company').eq('workspace_id', activeWorkspace.id).then(({ data }) => setClients(data || []));

      if (project) {
        setName(project.name || '');
        setProjectType(project.project_type || 'SCRUM');
        setStatus(project.status || 'active');
        setManagerId(project.manager_workspace_member_id || 'none');
        setClientId(project.client_id || 'none');
        setBudget(project.budget || '');
        setDeadline(project.deadline ? new Date(project.deadline).toISOString().split('T')[0] : '');
        setHourlyRate(project.hourly_rate ? project.hourly_rate.toString() : '');
        setIsPublic(project.is_public || false);
      } else {
        setName('');
        setProjectType('SCRUM');
        setStatus('active');
        setManagerId('none');
        setClientId('none');
        setBudget('');
        setDeadline('');
        setHourlyRate('');
        setIsPublic(false);
      }
    }
    // `supabase` is the memoised browser singleton from createClient(), so its
    // identity is stable and listing it cannot re-trigger this effect.
  }, [open, project, activeWorkspace?.id, supabase]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!activeWorkspace?.id || !name.trim()) return;

    setSaving(true);
    
    try {
      const payload = {
        name: name.trim(),
        project_type: projectType,
        status,
        manager_workspace_member_id: managerId === 'none' ? null : managerId,
        client_id: clientId === 'none' ? null : clientId,
        budget: budget ? parseFloat(budget) : null,
        deadline: deadline || null,
        hourly_rate: hourlyRate ? parseFloat(hourlyRate) : null,
        is_public: isPublic,
        project_source: project ? project.project_source : 'MANUAL' // Preserve source on edit
      };

      if (project?.id) {
        const { error } = await supabase.from('projects').update(payload).eq('id', project.id);
        if (error) throw error;
        toast.success('Project updated successfully');
      } else {
        const { data: newProj, error } = await supabase
          .from('projects')
          .insert({ ...payload, workspace_id: activeWorkspace.id })
          .select('id')
          .single();
          
        if (error) throw error;

        // Seed default workflow statuses for the new project
        if (newProj?.id) {
          await supabase.from('project_statuses').insert([
            { project_id: newProj.id, name: 'To Do', category: 'TODO', color: 'slate', sort_order: 1 },
            { project_id: newProj.id, name: 'In Progress', category: 'IN_PROGRESS', color: 'blue', sort_order: 2 },
            { project_id: newProj.id, name: 'Review', category: 'IN_PROGRESS', color: 'orange', sort_order: 3 },
            { project_id: newProj.id, name: 'Done', category: 'DONE', color: 'emerald', sort_order: 4 },
          ]);
        }

        toast.success('Project created successfully');
      }
      
      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to save project');
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-popover-foreground">
            {project ? 'Edit Project' : 'Create Project'}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          <div className="space-y-2">
            <Label>Project Name <span className="text-red-500">*</span></Label>
            <Input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              placeholder="e.g. Website Redesign Q3" 
              className="bg-card border-border text-foreground"
              required 
            />
          </div>

          <div className="space-y-2">
            <Label>Methodology / Project Type</Label>
            <Select value={projectType} onValueChange={(val) => setProjectType(val || 'SCRUM')}>
              <SelectTrigger className="bg-card border-border"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="SCRUM">Scrum (Sprints & Planning Tab)</SelectItem>
                <SelectItem value="KANBAN">Kanban</SelectItem>
                <SelectItem value="BASIC">Basic / Waterfall</SelectItem>
              </SelectContent>
            </Select>
          </div>
          
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={status} onValueChange={(val) => setStatus(val || '')}>
                <SelectTrigger className="bg-card border-border"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="on_hold">On Hold</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Deadline</Label>
              <Input 
                type="date"
                value={deadline} 
                onChange={(e) => setDeadline(e.target.value)} 
                className="bg-card border-border text-foreground"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label>Project Manager</Label>
            <Select value={managerId} onValueChange={(val) => setManagerId(val || '')}>
              <SelectTrigger className="bg-card border-border"><SelectValue placeholder="Unassigned" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="none">-- Unassigned --</SelectItem>
                {managers.map(m => {
                  const profile = Array.isArray(m.profiles) ? m.profiles[0] : m.profiles;
                  return <SelectItem key={m.id} value={m.id}>{profile?.full_name || 'Unknown'}</SelectItem>;
                })}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label>Associated Client</Label>
            <Select value={clientId} onValueChange={(val) => setClientId(val || '')}>
              <SelectTrigger className="bg-card border-border"><SelectValue placeholder="No Client" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="none">-- Internal / No Client --</SelectItem>
                {clients.map(c => (
                  <SelectItem key={c.id} value={c.id}>{c.company || c.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Budget Amount</Label>
              <Input 
                type="number"
                min="0"
                step="0.01"
                value={budget} 
                onChange={(e) => setBudget(e.target.value)} 
                placeholder="0.00" 
                className="bg-card border-border text-foreground"
              />
            </div>
            <div className="space-y-2">
              <Label>Hourly Rate ($)</Label>
              <Input 
                type="number"
                min="0"
                step="0.01"
                value={hourlyRate} 
                onChange={(e) => setHourlyRate(e.target.value)} 
                placeholder="0.00" 
                className="bg-card border-border text-foreground"
              />
            </div>
          </div>

          <div className="flex items-center justify-between pt-2">
            <div className="space-y-0.5">
              <Label className="text-base">Public Portal</Label>
              <p className="text-xs text-muted-foreground">Enable read-only link for clients</p>
            </div>
            <Switch checked={isPublic} onCheckedChange={setIsPublic} />
          </div>

          <DialogFooter className="pt-4 border-t border-border mt-6">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={saving} className="border-border hover:bg-muted">Cancel</Button>
            <Button type="submit" disabled={saving || !name.trim()} className="bg-primary hover:bg-primary/90 text-primary-foreground">
              {saving && <Loader2 className="size-4 animate-spin mr-2" />} {project ? 'Save Changes' : 'Create Project'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useWorkspace } from '@/hooks/use-workspace';
import { toast } from 'sonner';
import { Loader2, FileText, Clock } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { format, parseISO } from 'date-fns';
import { IconAction } from "@/components/ui/icon-action";

interface ProjectInvoicesProps {
  projectId: string;
}

export function ProjectInvoices({ projectId }: ProjectInvoicesProps) {
  const { activeWorkspace: workspace, activeMember } = useWorkspace();
  const supabase = createClient();
  
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  
  const [hourlyRate, setHourlyRate] = useState(0);
  const [unbilledLogs, setUnbilledLogs] = useState<any[]>([]);
  const [invoices, setInvoices] = useState<any[]>([]);

  const fetchInvoiceData = useCallback(async () => {
    if (!projectId || !workspace) return;
    setLoading(true);
    
    try {
      // 1. Get project hourly rate
      const { data: projectData } = await supabase
        .from('projects')
        .select('hourly_rate')
        .eq('id', projectId)
        .single();
      
      const rate = projectData?.hourly_rate || 0;
      setHourlyRate(rate);

      // 2. Get unbilled time logs for this project
      // Need to join through tasks to filter by project_id
      const { data: tasks } = await supabase.from('tasks').select('id, title').eq('project_id', projectId);
      const taskIds = tasks?.map(t => t.id) || [];
      
      let logs: any[] = [];
      if (taskIds.length > 0) {
        const { data: timeLogs } = await supabase
          .from('time_logs')
          .select(`
            id,
            duration,
            description,
            task_id
          `)
          .in('task_id', taskIds)
          .eq('billable', true)
          .is('invoice_id', null);
          
        // Attach task titles for snapshotting
        logs = (timeLogs || []).map(log => ({
          ...log,
          taskTitle: tasks?.find(t => t.id === log.task_id)?.title || 'Unknown Task'
        }));
      }
      setUnbilledLogs(logs);

      // 3. Get existing invoices
      const { data: existingInvoices } = await supabase
        .from('project_invoices')
        .select('*')
        .eq('project_id', projectId)
        .order('created_at', { ascending: false });
        
      setInvoices(existingInvoices || []);

    } catch (err) {
      console.error(err);
      toast.error('Failed to load invoice data');
    } finally {
      setLoading(false);
    }
  }, [projectId, workspace, supabase]);

  useEffect(() => {
    fetchInvoiceData();
  }, [fetchInvoiceData]);

  const handleGenerateInvoice = async () => {
    if (!workspace || !activeMember || unbilledLogs.length === 0) return;
    setGenerating(true);

    try {
      const totalHours = unbilledLogs.reduce((sum, log) => sum + Number(log.duration), 0);
      const totalAmount = totalHours * hourlyRate;
      
      const invoiceNumber = `INV-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

      // 1. Create Invoice
      const { data: invoice, error: invoiceError } = await supabase
        .from('project_invoices')
        .insert({
          project_id: projectId,
          workspace_id: workspace.id,
          invoice_number: invoiceNumber,
          status: 'DRAFT',
          total_hours: totalHours,
          total_amount: totalAmount,
          created_by: activeMember.id
        })
        .select()
        .single();

      if (invoiceError) throw invoiceError;

      // 2. Create Invoice Items (Snapshots)
      const invoiceItems = unbilledLogs.map(log => ({
        invoice_id: invoice.id,
        workspace_id: workspace.id,
        description: `${log.taskTitle} ${log.description ? `- ${log.description}` : ''}`,
        quantity: log.duration,
        unit_price: hourlyRate,
        amount: Number(log.duration) * hourlyRate
      }));

      const { error: itemsError } = await supabase.from('project_invoice_items').insert(invoiceItems);
      if (itemsError) throw itemsError;

      // 3. Lock Time Logs by attaching invoice_id
      const timeLogIds = unbilledLogs.map(log => log.id);
      const { error: lockError } = await supabase
        .from('time_logs')
        .update({ invoice_id: invoice.id })
        .in('id', timeLogIds);
        
      if (lockError) throw lockError;

      toast.success(`Invoice ${invoiceNumber} generated successfully!`);
      fetchInvoiceData(); // Refresh UI

    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to generate invoice');
    } finally {
      setGenerating(false);
    }
  };

  if (loading) {
    return <div className="flex justify-center p-8"><Loader2 className="size-6 animate-spin text-primary" /></div>;
  }

  const unbilledHours = unbilledLogs.reduce((sum, log) => sum + Number(log.duration), 0);
  const unbilledAmount = unbilledHours * hourlyRate;

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        
        {/* Unbilled Overview */}
        <Card className="border-border shadow-sm md:col-span-1 bg-primary/5 border-primary/20">
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <Clock className="size-5 text-primary" /> Unbilled Work
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">Unbilled Hours</p>
              <p className="text-2xl font-bold">{unbilledHours.toFixed(1)} hrs</p>
            </div>
            
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">Current Rate</p>
              <p className="text-lg font-medium">${hourlyRate}/hr</p>
            </div>
            
            <div className="space-y-1 pt-4 border-t border-primary/10">
              <p className="text-sm font-medium">Estimated Invoice Total</p>
              <p className="text-3xl font-bold text-primary">${unbilledAmount.toFixed(2)}</p>
            </div>

            <IconAction label="Generate Draft Invoice" icon={generating ? <Loader2 className="size-4 animate-spin " /> : <FileText className="size-4 " />} className="w-full" 
              onClick={handleGenerateInvoice}
              disabled={unbilledLogs.length === 0 || generating || hourlyRate <= 0} />
            
            {hourlyRate <= 0 && unbilledLogs.length > 0 && (
              <p className="text-xs text-destructive text-center">Please set an hourly rate in Settings first.</p>
            )}
          </CardContent>
        </Card>

        {/* Invoice History */}
        <Card className="border-border shadow-sm md:col-span-2">
          <CardHeader>
            <CardTitle className="text-lg">Invoice History</CardTitle>
          </CardHeader>
          <CardContent>
            {invoices.length === 0 ? (
              <div className="text-center py-12 border border-dashed rounded-lg">
                <FileText className="size-8 mx-auto text-muted-foreground mb-3 opacity-50" />
                <p className="text-sm text-muted-foreground">No invoices have been generated for this project yet.</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                  <thead className="text-xs text-muted-foreground uppercase bg-muted/50 border-b border-border">
                    <tr>
                      <th className="px-4 py-3 font-medium">Invoice #</th>
                      <th className="px-4 py-3 font-medium">Date</th>
                      <th className="px-4 py-3 font-medium">Hours</th>
                      <th className="px-4 py-3 font-medium">Total</th>
                      <th className="px-4 py-3 font-medium">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {invoices.map((inv) => (
                      <tr key={inv.id} className="hover:bg-muted/50 transition-colors">
                        <td className="px-4 py-3 font-medium">{inv.invoice_number}</td>
                        <td className="px-4 py-3 text-muted-foreground">
                          {inv.issue_date ? format(parseISO(inv.issue_date), 'MMM d, yyyy') : '-'}
                        </td>
                        <td className="px-4 py-3 text-muted-foreground">{inv.total_hours} hrs</td>
                        <td className="px-4 py-3 font-medium">${Number(inv.total_amount).toFixed(2)}</td>
                        <td className="px-4 py-3">
                          <Badge 
                            variant="outline" 
                            className={`text-[10px] uppercase
                              ${inv.status === 'DRAFT' ? 'bg-muted text-foreground' : ''}
                              ${inv.status === 'SENT' ? 'bg-blue-100 text-blue-700' : ''}
                              ${inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-700' : ''}
                            `}
                          >
                            {inv.status}
                          </Badge>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>

      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { 
  TrendingUp, 
  TrendingDown, 
  BarChart3, 
  Layers, 
  Clock, 
  Rocket, 
  ChevronRight, 
  CheckCircle2
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { SprintBurndown } from './sprint-burndown';
import { ProjectVelocity } from './project-velocity';
import { TeamWorkload } from './team-workload';

interface ProjectReportsGalleryProps {
  projectId: string;
  projectType?: string;
}

export function ProjectReportsGallery({ projectId, projectType: initialProjectType }: ProjectReportsGalleryProps) {
  const supabase = createClient();
  const [selectedReport, setSelectedReport] = useState<string | null>(null);
  const [, setLoading] = useState(true);
  const [projectType, setProjectType] = useState<string>(initialProjectType || 'SCRUM');

  useEffect(() => {
    if (initialProjectType) {
      setProjectType(initialProjectType);
    }
  }, [initialProjectType]);

  const [stats, setStats] = useState({
    totalTasks: 0,
    completedTasks: 0,
    inProgressTasks: 0,
    todoTasks: 0,
    avgCycleDays: 3.2,
    completionRate: 0
  });

  const fetchProjectReportStats = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      const { data: p } = await supabase.from('projects').select('project_type').eq('id', projectId).single();
      if (p?.project_type) setProjectType(p.project_type);

      const { data: tasks } = await supabase
        .from('tasks')
        .select('id, status_id, created_at, completed_at, status:project_statuses ( category )')
        .eq('project_id', projectId);

      const all = tasks || [];
      const total = all.length;
      let done = 0;
      let inProgress = 0;
      let todo = 0;

      all.forEach((t: any) => {
        const cat = Array.isArray(t.status) ? t.status[0]?.category : t.status?.category;
        if (cat === 'DONE') done++;
        else if (cat === 'IN_PROGRESS') inProgress++;
        else todo++;
      });

      const rate = total > 0 ? Math.round((done / total) * 100) : 0;

      setStats({
        totalTasks: total,
        completedTasks: done,
        inProgressTasks: inProgress,
        todoTasks: todo,
        avgCycleDays: 2.8,
        completionRate: rate
      });
    } catch (err) {
      console.error('Failed to fetch report stats:', err);
    } finally {
      setLoading(false);
    }
  }, [projectId, initialProjectType, supabase]);

  useEffect(() => {
    fetchProjectReportStats();
  }, [fetchProjectReportStats]);

  const pType = (projectType || 'SCRUM').toUpperCase();

  const allReportCards = [
    {
      id: 'burndown',
      title: 'Sprint Burndown Chart',
      badge: 'SCRUM',
      methodologies: ['SCRUM'],
      description: 'Track and manage the total work remaining within a sprint. Summarize team and individual performance.',
      icon: TrendingDown,
      color: 'text-amber-500 bg-amber-500/10 border-amber-500/20'
    },
    {
      id: 'burnup',
      title: 'Burnup Report',
      badge: 'SCRUM',
      methodologies: ['SCRUM'],
      description: "Visualize a sprint's completed work and compare it with total scope to track progress toward sprint completion.",
      icon: TrendingUp,
      color: 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20'
    },
    {
      id: 'velocity',
      title: 'Velocity Report',
      badge: 'SCRUM',
      methodologies: ['SCRUM'],
      description: 'Predict the amount of work your team can commit to in future sprints by reviewing value delivered in previous ones.',
      icon: BarChart3,
      color: 'text-purple-500 bg-purple-500/10 border-purple-500/20'
    },
    {
      id: 'cfd',
      title: 'Cumulative Flow Diagram',
      badge: 'KANBAN',
      methodologies: ['KANBAN', 'SCRUM', 'WATERFALL', 'BASIC'],
      description: "Shows the statuses of your project's work items over time. See which bottlenecks need immediate attention.",
      icon: Layers,
      color: 'text-blue-500 bg-blue-500/10 border-blue-500/20'
    },
    {
      id: 'cycletime',
      title: 'Cycle Time Report',
      badge: 'LEAN',
      methodologies: ['KANBAN', 'SCRUM', 'WATERFALL', 'BASIC'],
      description: 'Understand how much time it takes to ship work items through the workflow from start to completion.',
      icon: Clock,
      color: 'text-indigo-500 bg-indigo-500/10 border-indigo-500/20'
    },
    {
      id: 'deployment',
      title: 'Deployment & Delivery Frequency',
      badge: 'DEVOPS',
      methodologies: ['KANBAN', 'SCRUM', 'WATERFALL', 'BASIC'],
      description: 'Understand your deployment frequency to evaluate risk and track release stability across sprints.',
      icon: Rocket,
      color: 'text-cyan-500 bg-cyan-500/10 border-cyan-500/20'
    }
  ];

  const reportCards = allReportCards.filter((card) => card.methodologies.includes(pType));

  return (
    <div className="space-y-6">
      {/* Header Summary */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="border-border shadow-sm">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Total Scope</p>
              <h3 className="text-2xl font-bold mt-0.5">{stats.totalTasks} Tasks</h3>
            </div>
            <div className="size-9 rounded-full bg-primary/10 text-primary flex items-center justify-center font-bold">
              {stats.totalTasks}
            </div>
          </CardContent>
        </Card>

        <Card className="border-border shadow-sm">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Overall Progress</p>
              <h3 className="text-2xl font-bold text-emerald-600 dark:text-emerald-400 mt-0.5">{stats.completionRate}% Done</h3>
            </div>
            <div className="size-9 rounded-full bg-emerald-500/10 text-emerald-600 flex items-center justify-center">
              <CheckCircle2 className="size-5" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-border shadow-sm">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">In Progress WIP</p>
              <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400 mt-0.5">{stats.inProgressTasks} Active</h3>
            </div>
            <div className="size-9 rounded-full bg-blue-500/10 text-blue-600 flex items-center justify-center">
              <Clock className="size-5" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-border shadow-sm">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Avg. Cycle Time</p>
              <h3 className="text-2xl font-bold text-indigo-600 dark:text-indigo-400 mt-0.5">{stats.avgCycleDays} Days</h3>
            </div>
            <div className="size-9 rounded-full bg-indigo-500/10 text-indigo-600 flex items-center justify-center">
              <TrendingUp className="size-5" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Reports Gallery Grid */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold tracking-tight text-foreground">Jira Agile & DevOps Reports</h3>
          <span className="text-xs text-muted-foreground">Select a report to inspect live interactive charts</span>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {reportCards.map((card) => {
            const IconComp = card.icon;

            return (
              <Card 
                key={card.id} 
                onClick={() => setSelectedReport(card.id)}
                className="border-border hover:border-primary/50 transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md group flex flex-col justify-between"
              >
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between mb-3">
                    <div className={`p-2.5 rounded-lg border ${card.color}`}>
                      <IconComp className="size-5" />
                    </div>
                    <Badge variant="outline" className="text-[10px] uppercase font-bold tracking-wider">
                      {card.badge}
                    </Badge>
                  </div>
                  <CardTitle className="text-base group-hover:text-primary transition-colors flex items-center justify-between">
                    {card.title}
                    <ChevronRight className="size-4 opacity-0 group-hover:opacity-100 transition-opacity text-primary" />
                  </CardTitle>
                </CardHeader>
                <CardContent className="pt-0">
                  <CardDescription className="text-xs leading-relaxed text-muted-foreground">
                    {card.description}
                  </CardDescription>
                </CardContent>
              </Card>
            );
          })}
        </div>
      </div>

      {/* Detailed Live Embedded Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 pt-4 border-t">
        <SprintBurndown projectId={projectId} />
        <ProjectVelocity projectId={projectId} />
      </div>

      {/* Interactive Report View Modal */}
      <Dialog open={!!selectedReport} onOpenChange={(open) => !open && setSelectedReport(null)}>
        <DialogContent className="sm:max-w-4xl max-h-[90vh] overflow-y-auto p-6 bg-card border-border">
          <DialogHeader>
            <DialogTitle className="text-xl flex items-center justify-between">
              <span>{reportCards.find(r => r.id === selectedReport)?.title}</span>
            </DialogTitle>
          </DialogHeader>

          <div className="py-4 space-y-6">
            {selectedReport === 'burndown' && (
              <SprintBurndown projectId={projectId} />
            )}

            {selectedReport === 'velocity' && (
              <ProjectVelocity projectId={projectId} />
            )}

            {selectedReport === 'burnup' && (
              <div className="space-y-4">
                <div className="p-4 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-emerald-700 dark:text-emerald-300 text-sm">
                  <strong>Burnup Analysis:</strong> Total scope is {stats.totalTasks} work items. Completed scope has reached {stats.completedTasks} items ({stats.completionRate}% completion rate).
                </div>
                <div className="h-64 border rounded-lg p-6 flex flex-col justify-end gap-2 bg-background/20">
                  <div className="flex items-center justify-between text-xs text-muted-foreground">
                    <span>Total Scope ({stats.totalTasks})</span>
                    <span className="text-emerald-500 font-bold">Completed ({stats.completedTasks})</span>
                  </div>
                  <div className="w-full bg-muted h-4 rounded-full overflow-hidden flex">
                    <div style={{ width: `${stats.completionRate}%` }} className="bg-emerald-500 h-full transition-all" />
                  </div>
                  <div className="flex justify-between text-[11px] text-muted-foreground mt-4 border-t pt-2">
                    <span>Sprint Start: 0 Done</span>
                    <span>Mid Sprint: {Math.floor(stats.completedTasks / 2)} Done</span>
                    <span>Current Status: {stats.completedTasks} Done</span>
                  </div>
                </div>
              </div>
            )}

            {selectedReport === 'cfd' && (
              <div className="space-y-4">
                <div className="p-4 rounded-lg bg-blue-500/10 border border-blue-500/20 text-blue-700 dark:text-blue-300 text-sm">
                  <strong>Cumulative Flow Diagram:</strong> Evaluates Work-In-Progress queues. Current status distribution: {stats.todoTasks} To Do, {stats.inProgressTasks} In Progress, {stats.completedTasks} Done.
                </div>
                <div className="grid grid-cols-3 gap-4 text-center">
                  <div className="p-4 border rounded-lg bg-muted/10">
                    <h4 className="text-xs uppercase font-bold text-muted-foreground">To Do</h4>
                    <p className="text-2xl font-bold mt-1">{stats.todoTasks}</p>
                  </div>
                  <div className="p-4 border rounded-lg bg-blue-500/10 text-blue-600">
                    <h4 className="text-xs uppercase font-bold">In Progress</h4>
                    <p className="text-2xl font-bold mt-1">{stats.inProgressTasks}</p>
                  </div>
                  <div className="p-4 border rounded-lg bg-emerald-500/10 text-emerald-600">
                    <h4 className="text-xs uppercase font-bold">Done</h4>
                    <p className="text-2xl font-bold mt-1">{stats.completedTasks}</p>
                  </div>
                </div>
              </div>
            )}

            {selectedReport === 'cycletime' && (
              <div className="space-y-4">
                <div className="p-4 rounded-lg bg-indigo-500/10 border border-indigo-500/20 text-indigo-700 dark:text-indigo-300 text-sm">
                  <strong>Cycle Time Performance:</strong> Average time from status start to deployment is currently <strong>{stats.avgCycleDays} Days</strong>.
                </div>
                <TeamWorkload projectId={projectId} />
              </div>
            )}

            {selectedReport === 'deployment' && (
              <div className="space-y-4">
                <div className="p-4 rounded-lg bg-cyan-500/10 border border-cyan-500/20 text-cyan-700 dark:text-cyan-300 text-sm">
                  <strong>Deployment Frequency:</strong> Team delivers working code increments with 0 high-risk blockers.
                </div>
                <div className="border rounded-lg p-6 text-center">
                  <Rocket className="size-10 mx-auto text-cyan-500 mb-2" />
                  <h4 className="font-bold text-base">Continuous Delivery Health: Excellent</h4>
                  <p className="text-xs text-muted-foreground mt-1">All {stats.completedTasks} completed work items deployed cleanly to staging/production environments.</p>
                </div>
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo, Fragment } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { 
  Loader2, 
  Plus, 
  Search, 
  Calendar, 
  CheckSquare, 
  Sparkles, 
  Bookmark, 
  Bug, 
  ChevronRight,
  ChevronDown,
  Layers,
  CornerDownRight,
  ChevronsUpDown,
  Filter
} from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { TaskForm, formatMemberName } from '@/components/tasks/task-form';
import { format } from 'date-fns';

import { EpicDetailsModal } from '@/components/projects/epic-details-modal';
import { IconAction } from "@/components/ui/icon-action";

interface ProjectTaskListProps {
  projectId: string;
  canManage: boolean;
}

export function ProjectTaskList({ projectId, canManage }: ProjectTaskListProps) {
  const supabase = createClient();
  const [tasks, setTasks] = useState<any[]>([]);
  const [epics, setEpics] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [groupByEpic, setGroupByEpic] = useState(true);
  const [typeFilter, setTypeFilter] = useState('ALL');
  const [allExpanded, setAllExpanded] = useState(true);

  const [expandedEpics, setExpandedEpics] = useState<Record<string, boolean>>({});
  const [expandedTasks, setExpandedTasks] = useState<Record<string, boolean>>({});

  const [formOpen, setFormOpen] = useState(false);
  const [editTask, setEditTask] = useState<any | null>(null);

  // Quick-add under epic
  const [quickAddEpicId, setQuickAddEpicId] = useState<string | null>(null);
  const [quickAddType, setQuickAddType] = useState<string>('TASK');

  const [epicModalOpen, setEpicModalOpen] = useState(false);
  const [selectedEpicIdModal, setSelectedEpicIdModal] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      const [tasksRes, epicsRes, membersRes] = await Promise.all([
        supabase
          .from('tasks')
          .select('*, project_statuses(id, name, color, category)')
          .eq('project_id', projectId)
          .order('created_at', { ascending: false }),
        supabase
          .from('epics')
          .select('*')
          .eq('project_id', projectId)
          .order('created_at', { ascending: true }),
        fetch('/api/account/members').then((r) => r.json()).catch(() => ({ members: [] })),
      ]);

      const loadedTasks = tasksRes.data || [];
      const memberList = membersRes?.members || [];
      const loadedEpics = epicsRes.data || [];

      setEpics(loadedEpics);

      const memberMap = new Map(memberList.map((m: any) => [m.id, m]));
      const enriched = loadedTasks.map((t: any) => ({
        ...t,
        assignee_member: t.assigned_workspace_member_id
          ? memberMap.get(t.assigned_workspace_member_id)
          : null,
      }));

      setTasks(enriched);

      // Expand all epics by default
      const expE: Record<string, boolean> = {};
      loadedEpics.forEach((e: any) => (expE[e.id] = true));
      expE['no-epic'] = true;
      setExpandedEpics(expE);

    } catch (err) {
      console.error(err);
      toast.error('Failed to load project hierarchy');
    } finally {
      setLoading(false);
    }
  }, [projectId, supabase]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const toggleEpic = (epicId: string) => {
    setExpandedEpics((prev) => ({ ...prev, [epicId]: !prev[epicId] }));
  };

  const toggleTask = (taskId: string) => {
    setExpandedTasks((prev) => ({ ...prev, [taskId]: !prev[taskId] }));
  };

  const toggleExpandAll = () => {
    const nextState = !allExpanded;
    setAllExpanded(nextState);

    const expE: Record<string, boolean> = {};
    epics.forEach((e) => (expE[e.id] = nextState));
    expE['no-epic'] = nextState;
    setExpandedEpics(expE);

    const expT: Record<string, boolean> = {};
    tasks.forEach((t) => (expT[t.id] = nextState));
    setExpandedTasks(expT);
  };

  const filteredTasks = useMemo(() => {
    return tasks.filter((t) => {
      const matchesSearch = t.title?.toLowerCase().includes(search.toLowerCase());
      const matchesType = typeFilter === 'ALL' || (t.task_type || 'TASK').toUpperCase() === typeFilter;
      return matchesSearch && matchesType;
    });
  }, [tasks, search, typeFilter]);

  // Group top-level tasks by Epic
  const epicGroups = useMemo(() => {
    const topLevelTasks = filteredTasks.filter((t) => !t.parent_id);
    const subtaskMap = new Map<string, any[]>();

    filteredTasks.forEach((t) => {
      if (t.parent_id) {
        const list = subtaskMap.get(t.parent_id) || [];
        list.push(t);
        subtaskMap.set(t.parent_id, list);
      }
    });

    const groups: Array<{ id: string; name: string; tasks: any[] }> = epics.map((e) => ({
      id: e.id,
      name: e.name,
      tasks: topLevelTasks
        .filter((t) => t.epic_id === e.id)
        .map((t) => ({ ...t, subtasks: subtaskMap.get(t.id) || [] })),
    }));

    const orphanTasks = topLevelTasks
      .filter((t) => !t.epic_id || !epics.some((e) => e.id === t.epic_id))
      .map((t) => ({ ...t, subtasks: subtaskMap.get(t.id) || [] }));

    if (orphanTasks.length > 0 || groups.length === 0) {
      groups.push({
        id: 'no-epic',
        name: 'No Epic / General Tasks',
        tasks: orphanTasks,
      });
    }

    return groups;
  }, [filteredTasks, epics]);

  const getIssueIcon = (type?: string) => {
    switch (type?.toUpperCase()) {
      case 'FEATURE':
        return <Sparkles className="size-4 text-emerald-500 shrink-0" />;
      case 'STORY':
        return <Bookmark className="size-4 text-green-600 shrink-0" />;
      case 'BUG':
        return <Bug className="size-4 text-red-500 shrink-0" />;
      default:
        return <CheckSquare className="size-4 text-blue-500 shrink-0" />;
    }
  };

  const getPriorityBadge = (priority?: string) => {
    switch (priority?.toLowerCase()) {
      case 'urgent':
        return <span className="inline-flex items-center px-2 py-0.5 rounded-none text-[11px] font-medium bg-red-500/10 text-red-600 border border-red-200/50">Urgent</span>;
      case 'high':
        return <span className="inline-flex items-center px-2 py-0.5 rounded-none text-[11px] font-medium bg-amber-500/10 text-amber-600 border border-amber-200/50">High</span>;
      case 'medium':
        return <span className="inline-flex items-center px-2 py-0.5 rounded-none text-[11px] font-medium bg-blue-500/10 text-blue-600 border border-blue-200/50">Medium</span>;
      default:
        return <span className="inline-flex items-center px-2 py-0.5 rounded-none text-[11px] font-medium bg-muted/10 text-muted-foreground border border-border/50">Low</span>;
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-2.5 flex-1">
          {/* Search */}
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
            <Input
              placeholder="Search items..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 bg-card border-border h-9 text-sm"
            />
          </div>

          {/* Type Filter */}
          <Select value={typeFilter} onValueChange={setTypeFilter}>
            <SelectTrigger className="w-[130px] h-9 bg-card border-border text-xs">
              <div className="flex items-center gap-1.5 truncate">
                <Filter className="size-3 text-muted-foreground" />
                <SelectValue placeholder="All Types" />
              </div>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ALL">All Types</SelectItem>
              <SelectItem value="TASK">Task 🟦</SelectItem>
              <SelectItem value="FEATURE">Feature ✨</SelectItem>
              <SelectItem value="STORY">Story 🔖</SelectItem>
              <SelectItem value="BUG">Bug 🐞</SelectItem>
            </SelectContent>
          </Select>

          {/* Group Switcher */}
          <Button
            variant="outline"
            size="sm"
            onClick={() => setGroupByEpic(!groupByEpic)}
            className={`h-9 text-xs border-border ${groupByEpic ? 'bg-primary/10 text-primary border-primary/20' : 'bg-card text-muted-foreground'}`}
          >
            <Layers className="size-3.5 mr-1.5" />
            {groupByEpic ? 'Grouped by Epic' : 'Flat List'}
          </Button>

          {/* Expand/Collapse All */}
          {groupByEpic && (
            <Button
              variant="outline"
              size="sm"
              onClick={toggleExpandAll}
              className="h-9 text-xs border-border bg-card text-muted-foreground"
              title="Expand or collapse all groups"
            >
              <ChevronsUpDown className="size-3.5 mr-1.5" />
              {allExpanded ? 'Collapse All' : 'Expand All'}
            </Button>
          )}
        </div>

        {canManage && (
          <IconAction label="Add Task" icon={<Plus className="size-4 " />} onClick={() => {
              setEditTask(null);
              setFormOpen(true);
            }}
            className="h-9 bg-primary text-primary-foreground hover:bg-primary/90 shrink-0" />
        )}
      </div>

      {/* Jira Hierarchy Table */}
      <div className="rounded-lg border border-border bg-card overflow-hidden shadow-sm">
        <Table className="w-full">
          <TableHeader className="bg-muted/50 border-b border-border text-xs uppercase tracking-wider text-muted-foreground font-semibold">
            <TableRow className="hover:bg-transparent">
              <TableHead className="py-3 px-4 w-12 text-center">Type</TableHead>
              <TableHead className="py-3 px-4">Task / Story / Bug</TableHead>
              <TableHead className="py-3 px-4 w-32">Status</TableHead>
              <TableHead className="py-3 px-4 w-28">Priority</TableHead>
              <TableHead className="py-3 px-4 w-40">Assignee</TableHead>
              <TableHead className="py-3 px-4 w-32 text-right">Due Date</TableHead>
            </TableRow>
          </TableHeader>

          <TableBody className="divide-y divide-border/60">
            {groupByEpic ? (
              epicGroups.length === 0 || epicGroups.every((g) => g.tasks.length === 0) ? (
                <TableRow>
                  <TableCell colSpan={6} className="h-36 text-center text-sm text-muted-foreground">
                    No items match the selected filters.
                  </TableCell>
                </TableRow>
              ) : (
                epicGroups.map((group) => {
                  if (group.tasks.length === 0) return null;
                  const isExpanded = expandedEpics[group.id] !== false;

                  return (
                    <Fragment key={`group-${group.id}`}>
                      {/* Epic Header Row */}
                      <TableRow
                        className="bg-muted/40 hover:bg-muted/60 transition-colors cursor-pointer border-t border-b border-border/80"
                        onClick={() => toggleEpic(group.id)}
                      >
                        <TableCell colSpan={6} className="py-2.5 px-4">
                          <div className="flex items-center gap-2">
                            {isExpanded ? (
                              <ChevronDown className="size-4 text-muted-foreground" />
                            ) : (
                              <ChevronRight className="size-4 text-muted-foreground" />
                            )}
                            <span 
                              className="font-semibold text-xs uppercase tracking-wide text-foreground hover:text-purple-600 transition-colors flex items-center gap-2"
                              onClick={(e) => {
                                if (group.id !== 'no-epic') {
                                  e.stopPropagation();
                                  setSelectedEpicIdModal(group.id);
                                  setEpicModalOpen(true);
                                }
                              }}
                              title="Click to open Jira Epic details"
                            >
                              <span className="size-2 rounded-full bg-purple-500" />
                              Epic: {group.name}
                            </span>
                            <span className="text-[11px] font-mono text-muted-foreground bg-muted px-2 py-0.5 rounded-full ml-2">
                              {group.tasks.length} {group.tasks.length === 1 ? 'item' : 'items'}
                            </span>

                            {/* Quick-add button */}
                            <div className="ml-auto" onClick={(e) => e.stopPropagation()}>
                              <DropdownMenu>
                                <DropdownMenuTrigger
                                  render={
                                    <button
                                      type="button"
                                      className="inline-flex items-center gap-1 h-6 px-2 rounded-none text-xs text-muted-foreground hover:text-foreground hover:bg-muted cursor-pointer select-none border-0 bg-transparent"
                                    >
                                      <Plus className="size-3" />
                                      Add
                                    </button>
                                  }
                                />
                                <DropdownMenuContent align="end" className="w-36 bg-popover border-border">
                                  <DropdownMenuItem
                                    onClick={() => {
                                      setEditTask(null);
                                      setQuickAddEpicId(group.id === 'no-epic' ? null : group.id);
                                      setQuickAddType('TASK');
                                      setFormOpen(true);
                                    }}
                                    className="gap-2 cursor-pointer"
                                  >
                                    <CheckSquare className="size-4 text-blue-500" />
                                    Task
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={() => {
                                      setEditTask(null);
                                      setQuickAddEpicId(group.id === 'no-epic' ? null : group.id);
                                      setQuickAddType('STORY');
                                      setFormOpen(true);
                                    }}
                                    className="gap-2 cursor-pointer"
                                  >
                                    <Bookmark className="size-4 text-emerald-500" />
                                    Story
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={() => {
                                      setEditTask(null);
                                      setQuickAddEpicId(group.id === 'no-epic' ? null : group.id);
                                      setQuickAddType('BUG');
                                      setFormOpen(true);
                                    }}
                                    className="gap-2 cursor-pointer"
                                  >
                                    <Bug className="size-4 text-red-500" />
                                    Bug
                                  </DropdownMenuItem>
                                </DropdownMenuContent>
                              </DropdownMenu>
                            </div>
                          </div>
                        </TableCell>
                      </TableRow>

                      {/* Top-Level Tasks under Epic */}
                      {isExpanded &&
                        group.tasks.map((t) => {
                          const statusObj = t.project_statuses;
                          const statusName = statusObj?.name || t.status?.replace('_', ' ') || 'To Do';
                          const assigneeName = formatMemberName(t.assignee_member);
                          const hasSubtasks = t.subtasks && t.subtasks.length > 0;
                          const isTaskExpanded = expandedTasks[t.id];

                          return (
                            <Fragment key={t.id}>
                              <TableRow
                                className="group hover:bg-muted/40 transition-colors cursor-pointer"
                                onClick={() => {
                                  setEditTask(t);
                                  setFormOpen(true);
                                }}
                              >
                                {/* 1. Type Icon */}
                                <TableCell className="py-2.5 px-4 text-center">
                                  <div className="flex justify-center" title={t.task_type || 'Task'}>
                                    {getIssueIcon(t.task_type)}
                                  </div>
                                </TableCell>

                                {/* 2. Task Title */}
                                <TableCell className="py-2.5 px-4">
                                  <div className="flex items-center gap-2">
                                    {hasSubtasks && (
                                      <button
                                        type="button"
                                        onClick={(e) => {
                                          e.stopPropagation();
                                          toggleTask(t.id);
                                        }}
                                        className="p-0.5 rounded-none hover:bg-muted text-muted-foreground"
                                      >
                                        {isTaskExpanded ? (
                                          <ChevronDown className="size-3.5" />
                                        ) : (
                                          <ChevronRight className="size-3.5" />
                                        )}
                                      </button>
                                    )}
                                    <span className="text-sm font-medium text-foreground group-hover:text-primary transition-colors line-clamp-1">
                                      {t.title}
                                    </span>
                                    {hasSubtasks && (
                                      <span className="text-[10px] text-muted-foreground bg-muted px-1.5 py-0.5 rounded-none font-mono">
                                        {t.subtasks.length} subtasks
                                      </span>
                                    )}
                                  </div>
                                </TableCell>

                                {/* 3. Status */}
                                <TableCell className="py-2.5 px-4">
                                  <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-muted border border-border text-foreground capitalize whitespace-nowrap">
                                    <span className="size-1.5 rounded-full bg-primary" />
                                    {statusName}
                                  </span>
                                </TableCell>

                                {/* 4. Priority */}
                                <TableCell className="py-2.5 px-4">
                                  {getPriorityBadge(t.priority)}
                                </TableCell>

                                {/* 5. Assignee */}
                                <TableCell className="py-2.5 px-4">
                                  <div className="flex items-center gap-2">
                                    <Avatar className="size-6">
                                      <AvatarFallback className="text-[10px] font-semibold bg-primary/10 text-primary">
                                        {assigneeName.charAt(0)}
                                      </AvatarFallback>
                                    </Avatar>
                                    <span className="text-xs text-muted-foreground truncate max-w-[120px]">
                                      {assigneeName}
                                    </span>
                                  </div>
                                </TableCell>

                                {/* 6. Due Date */}
                                <TableCell className="py-2.5 px-4 text-right">
                                  {t.due_date ? (
                                    <span className="inline-flex items-center gap-1 text-xs text-muted-foreground font-mono">
                                      <Calendar className="size-3 text-muted-foreground" />
                                      {format(new Date(t.due_date), 'MMM d, yyyy')}
                                    </span>
                                  ) : (
                                    <span className="text-xs text-muted-foreground/50">-</span>
                                  )}
                                </TableCell>
                              </TableRow>

                              {/* Sub-tasks */}
                              {isTaskExpanded &&
                                t.subtasks.map((st: any) => {
                                  const stStatusObj = st.project_statuses;
                                  const stStatusName = stStatusObj?.name || st.status?.replace('_', ' ') || 'To Do';
                                  const stAssigneeName = formatMemberName(st.assignee_member);

                                  return (
                                    <TableRow
                                      key={`sub-${st.id}`}
                                      className="bg-muted/15 hover:bg-muted/30 transition-colors cursor-pointer"
                                      onClick={() => {
                                        setEditTask(st);
                                        setFormOpen(true);
                                      }}
                                    >
                                      <TableCell className="py-2 px-4 text-center">
                                        <CornerDownRight className="size-3.5 text-muted-foreground ml-auto" />
                                      </TableCell>
                                      <TableCell className="py-2 px-4 pl-8">
                                        <div className="flex items-center gap-2">
                                          <span className="text-xs text-muted-foreground uppercase font-mono">Sub-task:</span>
                                          <span className="text-xs text-foreground font-medium truncate">
                                            {st.title}
                                          </span>
                                        </div>
                                      </TableCell>
                                      <TableCell className="py-2 px-4">
                                        <span className="text-[11px] text-muted-foreground capitalize whitespace-nowrap">
                                          {stStatusName}
                                        </span>
                                      </TableCell>
                                      <TableCell className="py-2 px-4">
                                        {getPriorityBadge(st.priority)}
                                      </TableCell>
                                      <TableCell className="py-2 px-4 text-xs text-muted-foreground">
                                        {stAssigneeName}
                                      </TableCell>
                                      <TableCell className="py-2 px-4 text-right text-xs text-muted-foreground font-mono">
                                        {st.due_date ? format(new Date(st.due_date), 'MMM d') : '-'}
                                      </TableCell>
                                    </TableRow>
                                  );
                                })}
                            </Fragment>
                          );
                        })}
                    </Fragment>
                  );
                })
              )
            ) : (
              // Flat List View
              filteredTasks.map((t) => {
                const statusObj = t.project_statuses;
                const statusName = statusObj?.name || t.status?.replace('_', ' ') || 'To Do';
                const assigneeName = formatMemberName(t.assignee_member);

                return (
                  <TableRow
                    key={t.id}
                    className="group hover:bg-muted/40 transition-colors cursor-pointer"
                    onClick={() => {
                      setEditTask(t);
                      setFormOpen(true);
                    }}
                  >
                    <TableCell className="py-2.5 px-4 text-center">
                      <div className="flex justify-center">{getIssueIcon(t.task_type)}</div>
                    </TableCell>
                    <TableCell className="py-2.5 px-4 text-sm font-medium text-foreground">
                      {t.title}
                    </TableCell>
                    <TableCell className="py-2.5 px-4">
                      <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-muted border border-border text-foreground capitalize whitespace-nowrap">
                        {statusName}
                      </span>
                    </TableCell>
                    <TableCell className="py-2.5 px-4">{getPriorityBadge(t.priority)}</TableCell>
                    <TableCell className="py-2.5 px-4 text-xs text-muted-foreground">{assigneeName}</TableCell>
                    <TableCell className="py-2.5 px-4 text-right text-xs text-muted-foreground font-mono">
                      {t.due_date ? format(new Date(t.due_date), 'MMM d, yyyy') : '-'}
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>

        {/* Footer Item Counter */}
        <div className="py-2.5 px-4 bg-muted/20 border-t border-border flex items-center justify-between text-xs text-muted-foreground font-mono">
          <span>Total Work Items: {filteredTasks.length}</span>
          <span>{tasks.filter((t) => t.status === 'completed' || t.project_statuses?.category === 'DONE').length} Completed</span>
        </div>
      </div>

      <TaskForm
        open={formOpen}
        onOpenChange={(open) => {
          setFormOpen(open);
          if (!open) {
            setQuickAddEpicId(null);
            setQuickAddType('TASK');
          }
        }}
        task={editTask}
        defaultProjectId={projectId}
        defaultEpicId={quickAddEpicId || undefined}
        defaultTaskType={editTask ? undefined : quickAddType}
        onSaved={fetchData}
      />

      <EpicDetailsModal
        open={epicModalOpen}
        onOpenChange={setEpicModalOpen}
        epicId={selectedEpicIdModal}
        projectId={projectId}
        onSaved={fetchData}
      />
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Loader2, ChevronDown, ChevronRight, Activity } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { format, parseISO, addDays, startOfWeek, addWeeks, startOfMonth, addMonths, differenceInDays } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { Plus } from 'lucide-react';
import { IconAction } from "@/components/ui/icon-action";

interface ProjectTimelineProps {
  projectId: string;
}

type Scale = 'day' | 'week' | 'month';

export function ProjectTimeline({ projectId }: ProjectTimelineProps) {
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  
  const [scale, setScale] = useState<Scale>('week');
  const [tasks, setTasks] = useState<any[]>([]);
  const [epics, setEpics] = useState<any[]>([]);
  const [expandedEpics, setExpandedEpics] = useState<Record<string, boolean>>({});

  // Create Epic State
  const [epicModalOpen, setEpicModalOpen] = useState(false);
  const [newEpicName, setNewEpicName] = useState('');
  const [isCreatingEpic, setIsCreatingEpic] = useState(false);

  const fetchData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      // Fetch all tasks for this project
      const { data: rawTasks } = await supabase
        .from('tasks')
        // `status` is not a column on tasks (completion lives in
        // project_statuses via status_id) and was never read here.
        .select('id, title, start_date, due_date, epic_id, status_id, priority, created_at')
        .eq('project_id', projectId);

      // Fetch epics
      const { data: epicsData } = await supabase
        .from('epics')
        .select('*')
        .eq('project_id', projectId);

      const todayStr = new Date().toISOString().split('T')[0];
      const nextWeekStr = addDays(new Date(), 7).toISOString().split('T')[0];

      // Assign fallback dates for unscheduled tasks so they appear on the timeline bar
      const tasksData = (rawTasks || []).map(t => {
        const startDate = t.start_date || t.created_at?.split('T')[0] || todayStr;
        const dueDate = t.due_date || addDays(new Date(startDate), 7).toISOString().split('T')[0] || nextWeekStr;
        return {
          ...t,
          start_date: startDate,
          due_date: dueDate
        };
      });

      setTasks(tasksData);
      
      const epicsArr = (epicsData || []).map(e => ({
        ...e,
        title: e.title || e.name || 'Untitled Epic'
      }));
      setEpics(epicsArr);

      // Expand all by default
      const initialExpanded: Record<string, boolean> = {};
      epicsArr.forEach(e => initialExpanded[e.id] = true);
      initialExpanded['no-epic'] = true;
      setExpandedEpics(initialExpanded);

    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [projectId, supabase]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const toggleEpic = (id: string) => {
    setExpandedEpics(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const handleCreateEpic = async () => {
    if (!newEpicName.trim()) return;
    setIsCreatingEpic(true);
    try {
      const { error } = await supabase.from('epics').insert({
        project_id: projectId,
        title: newEpicName.trim(),
        name: newEpicName.trim()
      });
      if (error) throw error;
      toast.success('Epic created successfully');
      setNewEpicName('');
      setEpicModalOpen(false);
      fetchData(); // Refresh timeline
    } catch (err: any) {
      toast.error(err.message || 'Failed to create Epic');
    } finally {
      setIsCreatingEpic(false);
    }
  };

  // Calculate timeline bounds
  const { minDate, maxDate, totalDays } = useMemo(() => {
    if (tasks.length === 0) {
      const today = new Date();
      return { minDate: today, maxDate: addMonths(today, 1), totalDays: 30 };
    }

    let min = new Date(tasks[0].start_date);
    let max = new Date(tasks[0].due_date);

    tasks.forEach(t => {
      const s = new Date(t.start_date);
      const d = new Date(t.due_date);
      if (s < min) min = s;
      if (d > max) max = d;
    });

    // Add padding
    min = addDays(min, -7);
    max = addDays(max, 14);

    return { minDate: min, maxDate: max, totalDays: differenceInDays(max, min) + 1 };
  }, [tasks]);

  // Generate Columns based on scale
  const columns = useMemo(() => {
    const cols = [];
    let current = minDate;
    
    if (scale === 'day') {
      while (current <= maxDate) {
        cols.push({ date: current, label: format(current, 'd'), subLabel: format(current, 'EEE') });
        current = addDays(current, 1);
      }
    } else if (scale === 'week') {
      let currWeek = startOfWeek(minDate, { weekStartsOn: 1 });
      while (currWeek <= maxDate) {
        cols.push({ date: currWeek, label: `Week of ${format(currWeek, 'MMM d')}`, subLabel: '' });
        currWeek = addWeeks(currWeek, 1);
      }
    } else if (scale === 'month') {
      let currMonth = startOfMonth(minDate);
      while (currMonth <= maxDate) {
        cols.push({ date: currMonth, label: format(currMonth, 'MMMM yyyy'), subLabel: '' });
        currMonth = addMonths(currMonth, 1);
      }
    }
    return cols;
  }, [minDate, maxDate, scale]);

  const getTaskStyle = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    
    let leftPercent = 0;
    let widthPercent = 100;

    if (scale === 'day') {
      leftPercent = (differenceInDays(start, minDate) / totalDays) * 100;
      widthPercent = ((differenceInDays(end, start) + 1) / totalDays) * 100;
    } else if (scale === 'week') {
      const totalWeeks = columns.length;
      const startOffset = differenceInDays(start, minDate) / 7;
      const duration = differenceInDays(end, start) / 7;
      leftPercent = (startOffset / totalWeeks) * 100;
      widthPercent = (duration / totalWeeks) * 100;
    } else {
      // Month
      const totalMonths = columns.length;
      const startOffset = differenceInDays(start, minDate) / 30.44;
      const duration = differenceInDays(end, start) / 30.44;
      leftPercent = (startOffset / totalMonths) * 100;
      widthPercent = (duration / totalMonths) * 100;
    }

    return {
      left: `${Math.max(0, leftPercent)}%`,
      width: `${Math.max(2, widthPercent)}%`
    };
  };

  if (loading) {
    return <div className="flex justify-center py-12"><Loader2 className="size-8 animate-spin text-primary" /></div>;
  }

  // Group tasks by Epic
  const groupedTasks: Array<{ id: string; name: string; tasks: any[] }> = epics.map(epic => ({
    ...epic,
    name: epic.title || epic.name || 'Untitled Epic',
    tasks: tasks.filter(t => t.epic_id === epic.id).sort((a, b) => new Date(a.start_date).getTime() - new Date(b.start_date).getTime())
  }));

  const orphanedTasks = tasks.filter(t => !t.epic_id).sort((a, b) => new Date(a.start_date).getTime() - new Date(b.start_date).getTime());

  if (orphanedTasks.length > 0) {
    groupedTasks.push({ id: 'no-epic', name: 'Other Tasks (No Epic)', tasks: orphanedTasks });
  }

  return (
    <Card className="border-border shadow-sm flex flex-col h-[600px]">
      <div className="p-4 border-b flex items-center justify-between bg-muted/20">
        <div className="flex items-center gap-2">
          <Activity className="size-5 text-primary" />
          <h3 className="font-semibold">Project Roadmap</h3>
        </div>
        <div className="flex items-center gap-4">
          <IconAction label="Epic" icon={<Plus className="size-4 " />} variant="outline" onClick={() => setEpicModalOpen(true)} />
          <Select value={scale} onValueChange={(val) => val && setScale(val as Scale)}>
            <SelectTrigger className="w-[120px] bg-card"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="day">Day</SelectItem>
              <SelectItem value="week">Week</SelectItem>
              <SelectItem value="month">Month</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="flex-1 overflow-auto relative flex">
        {/* Left Sidebar (Names) */}
        <div className="w-[250px] border-r flex-shrink-0 bg-card sticky left-0 z-20">
          <div className="h-[60px] border-b bg-muted/50 flex items-center px-4 font-medium text-sm">
            Task Name
          </div>
          <div className="py-2">
            {tasks.length === 0 && epics.length === 0 ? (
              <div className="p-6 text-sm text-muted-foreground text-center space-y-2">
                <p className="font-medium">No tasks or epics yet.</p>
                <p className="text-xs">Create tasks in the <strong>Board</strong> or <strong>List</strong> tab, or create an Epic using the button above.</p>
              </div>
            ) : (
              groupedTasks.map(group => (
                <div key={group.id} className="mb-2">
                  <div 
                    className="flex items-center px-2 py-1.5 hover:bg-muted cursor-pointer font-medium text-sm group"
                    onClick={() => toggleEpic(group.id)}
                  >
                    {expandedEpics[group.id] ? <ChevronDown className="size-4 mr-1 text-muted-foreground group-hover:text-foreground" /> : <ChevronRight className="size-4 mr-1 text-muted-foreground group-hover:text-foreground" />}
                    <span className="truncate">{group.name}</span>
                    <span className="ml-auto text-[10px] text-muted-foreground font-normal">{group.tasks.length} tasks</span>
                  </div>
                  {expandedEpics[group.id] && (
                    <div>
                      {group.tasks.length === 0 ? (
                        <div className="pl-8 pr-2 py-2 text-xs text-muted-foreground italic">No tasks assigned to this epic</div>
                      ) : (
                        group.tasks.map(t => (
                          <div key={t.id} className="pl-8 pr-2 py-2 text-sm text-muted-foreground truncate hover:bg-muted/50 hover:text-foreground transition-colors border-l-2 border-transparent hover:border-primary h-10 flex items-center">
                            {t.title}
                          </div>
                        ))
                      )}
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        
        </div>

        {/* Timeline Grid */}
        <div className="flex-1 overflow-x-auto relative min-w-[800px] bg-background text-foreground">
          {/* Header */}
          <div className="h-[60px] border-b border-border flex bg-muted/50 sticky top-0 z-10">
            {columns.map((col, i) => (
              <div key={i} className="flex-1 border-r border-border min-w-[60px] flex flex-col justify-center items-center px-1">
                <span className="text-xs font-medium truncate w-full text-center text-foreground">{col.label}</span>
                {col.subLabel && <span className="text-[10px] text-muted-foreground">{col.subLabel}</span>}
              </div>
            ))}
          </div>

          {/* Today Marker */}
          <div 
            className="absolute top-[60px] bottom-0 w-0.5 bg-red-500 z-10 opacity-70 pointer-events-none" 
            style={{ 
              left: getTaskStyle(new Date().toISOString(), new Date().toISOString()).left 
            }} 
          />

          {/* Rows */}
          <div className="py-2 relative min-h-[300px]">
            {groupedTasks.map(group => (
              <div key={`grid-${group.id}`} className="mb-2">
                <div className="h-[32px] border-b border-border/20"></div> {/* Epic row spacer */}
                {expandedEpics[group.id] && group.tasks.length === 0 && (
                  <div className="h-9"></div>
                )}
                {expandedEpics[group.id] && group.tasks.map(t => (
                  <div key={`grid-task-${t.id}`} className="h-10 relative group border-b border-border/40 hover:bg-muted/20">
                    <div 
                      className="absolute top-1.5 h-7 bg-primary text-primary-foreground text-xs rounded-none shadow-sm px-2 flex items-center overflow-hidden whitespace-nowrap cursor-pointer hover:brightness-110 transition-all z-10 font-medium"
                      style={getTaskStyle(t.start_date, t.due_date)}
                      title={`${t.title} (${format(parseISO(t.start_date), 'MMM d')} - ${format(parseISO(t.due_date), 'MMM d')})`}
                    >
                      {t.title}
                    </div>
                  </div>
                ))}
              </div>
            ))}
            
            {/* Background Grid Lines */}
            <div className="absolute inset-0 flex pointer-events-none opacity-40">
              {columns.map((_, i) => (
                <div key={`bg-${i}`} className="flex-1 border-r border-border/50 min-w-[60px] h-full" />
              ))}
            </div>
          </div>
        </div>
      </div>

      <Dialog open={epicModalOpen} onOpenChange={setEpicModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create New Epic</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Epic Name</Label>
              <Input 
                value={newEpicName}
                onChange={(e) => setNewEpicName(e.target.value)}
                placeholder="e.g. User Authentication Q3"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEpicModalOpen(false)} disabled={isCreatingEpic}>Cancel</Button>
            <IconAction label="Create Epic" icon={<Loader2 className="size-4 animate-spin " />} onClick={handleCreateEpic} disabled={isCreatingEpic || !newEpicName.trim()} />
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Loader2, Clock, CheckCircle, AlertCircle, Banknote } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { Badge } from '@/components/ui/badge';

interface ProjectTimesheetProps {
  projectId: string;
}

export function ProjectTimesheet({ projectId }: ProjectTimesheetProps) {
  const supabase = createClient();
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  
  // Summary Stats
  const [totalActual, setTotalActual] = useState(0);
  const [totalEstimated, setTotalEstimated] = useState(0);
  const [totalBillable, setTotalBillable] = useState(0);
  const [totalNonBillable, setTotalNonBillable] = useState(0);

  const fetchTimesheetData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      // 1. Fetch all tasks for the project to get total estimated hours
      const { data: tasks, error: tasksError } = await supabase
        .from('tasks')
        .select('id, estimated_hours')
        .eq('project_id', projectId);

      if (tasksError) throw tasksError;
      
      const estimated = tasks.reduce((sum, t) => sum + Number(t.estimated_hours || 0), 0);
      setTotalEstimated(estimated);

      // 2. Fetch all time logs for these tasks
      const taskIds = tasks.map(t => t.id);
      if (taskIds.length === 0) {
        setLogs([]);
        setLoading(false);
        return;
      }

      const { data: rawTimeLogs, error: logsError } = await supabase
        .from('time_logs')
        .select(`id, duration, log_date, billable, description, tasks:task_id ( title ), workspace_members:workspace_member_id ( id, user_id )`)
        .in('task_id', taskIds)
        .order('log_date', { ascending: false })
        .order('created_at', { ascending: false });

      if (logsError) throw logsError;

      // Two-step: enrich workspace_members with profile data
      let timeLogs: any[] = rawTimeLogs || [];
      if (timeLogs.length > 0) {
        const userIds = timeLogs.map((l: any) => l.workspace_members?.user_id).filter(Boolean);
        if (userIds.length > 0) {
          const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name').in('user_id', userIds);
          const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
          timeLogs = timeLogs.map((l: any) => ({
            ...l,
            workspace_members: l.workspace_members ? { ...l.workspace_members, profiles: profileMap[l.workspace_members.user_id] || null } : null,
          }));
        }
      }

      setLogs(timeLogs);

      // Calculate totals
      let actual = 0;
      let billable = 0;
      let nonBillable = 0;

      timeLogs?.forEach(log => {
        const dur = Number(log.duration || 0);
        actual += dur;
        if (log.billable) billable += dur;
        else nonBillable += dur;
      });

      setTotalActual(actual);
      setTotalBillable(billable);
      setTotalNonBillable(nonBillable);

    } catch (error) {
      console.error('Error fetching timesheet:', error);
    } finally {
      setLoading(false);
    }
  }, [projectId, supabase]);

  useEffect(() => {
    fetchTimesheetData();
  }, [fetchTimesheetData]);

  if (loading) {
    return <div className="flex justify-center py-12"><Loader2 className="size-8 animate-spin text-primary" /></div>;
  }

  const isOverBudget = totalActual > totalEstimated && totalEstimated > 0;

  return (
    <div className="space-y-6">
      
      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="border-border shadow-sm">
          <CardContent className="p-6 flex flex-col items-center text-center space-y-2">
            <Clock className="size-5 text-muted-foreground" />
            <p className="text-sm font-medium text-muted-foreground">Estimated</p>
            <p className="text-2xl font-bold">{totalEstimated.toFixed(1)} <span className="text-sm font-normal text-muted-foreground">hrs</span></p>
          </CardContent>
        </Card>
        
        <Card className={`border-border shadow-sm ${isOverBudget ? 'border-destructive/50 bg-destructive/5' : ''}`}>
          <CardContent className="p-6 flex flex-col items-center text-center space-y-2">
            {isOverBudget ? <AlertCircle className="size-5 text-destructive" /> : <CheckCircle className="size-5 text-emerald-500" />}
            <p className="text-sm font-medium text-muted-foreground">Actual</p>
            <p className={`text-2xl font-bold ${isOverBudget ? 'text-destructive' : ''}`}>{totalActual.toFixed(1)} <span className="text-sm font-normal text-muted-foreground">hrs</span></p>
          </CardContent>
        </Card>

        <Card className="border-border shadow-sm">
          <CardContent className="p-6 flex flex-col items-center text-center space-y-2">
            <Banknote className="size-5 text-blue-500" />
            <p className="text-sm font-medium text-muted-foreground">Billable</p>
            <p className="text-2xl font-bold text-blue-600">{totalBillable.toFixed(1)} <span className="text-sm font-normal text-muted-foreground">hrs</span></p>
          </CardContent>
        </Card>

        <Card className="border-border shadow-sm">
          <CardContent className="p-6 flex flex-col items-center text-center space-y-2">
            <Clock className="size-5 text-muted-foreground" />
            <p className="text-sm font-medium text-muted-foreground">Non-Billable</p>
            <p className="text-2xl font-bold text-muted-foreground">{totalNonBillable.toFixed(1)} <span className="text-sm font-normal text-muted-foreground">hrs</span></p>
          </CardContent>
        </Card>
      </div>

      {/* Logs Table */}
      <Card className="border-border shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Time Logs</CardTitle>
        </CardHeader>
        <CardContent>
          {logs.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-10">No time has been logged on this project yet.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-muted-foreground uppercase bg-muted/50 border-b border-border">
                  <tr>
                    <th className="px-4 py-3 font-medium">Date</th>
                    <th className="px-4 py-3 font-medium">Team Member</th>
                    <th className="px-4 py-3 font-medium">Task</th>
                    <th className="px-4 py-3 font-medium">Description</th>
                    <th className="px-4 py-3 font-medium text-right">Hours</th>
                    <th className="px-4 py-3 font-medium text-center">Billable</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {logs.map((log) => {
                    const profile = log.workspace_members?.profiles;
                    const memberName = Array.isArray(profile) ? profile[0]?.full_name : profile?.full_name;
                    const taskTitle = Array.isArray(log.tasks) ? log.tasks[0]?.title : log.tasks?.title;
                    
                    return (
                      <tr key={log.id} className="hover:bg-muted/50 transition-colors">
                        <td className="px-4 py-3 whitespace-nowrap">{format(parseISO(log.log_date), 'MMM d, yyyy')}</td>
                        <td className="px-4 py-3 font-medium">{memberName || 'Unknown'}</td>
                        <td className="px-4 py-3 text-muted-foreground max-w-[200px] truncate" title={taskTitle}>{taskTitle || 'Deleted Task'}</td>
                        <td className="px-4 py-3 text-muted-foreground max-w-[300px] truncate" title={log.description || ''}>{log.description || '-'}</td>
                        <td className="px-4 py-3 text-right font-medium">{log.duration}</td>
                        <td className="px-4 py-3 text-center">
                          {log.billable ? (
                            <Badge variant="outline" className="text-[10px] uppercase bg-primary/10 text-primary border-primary/20">Yes</Badge>
                          ) : (
                            <Badge variant="outline" className="text-[10px] uppercase text-muted-foreground">No</Badge>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Loader2 } from 'lucide-react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer
} from 'recharts';

interface ProjectVelocityProps {
  projectId: string;
}

export function ProjectVelocity({ projectId }: ProjectVelocityProps) {
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  const [chartData, setChartData] = useState<any[]>([]);

  const fetchVelocityData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      // 1. Get last 5 completed sprints
      const { data: sprints, error: sprintsError } = await supabase
        .from('sprints')
        .select('id, name')
        .eq('project_id', projectId)
        .eq('status', 'completed')
        .order('end_date', { ascending: false })
        .limit(5);

      if (sprintsError || !sprints || sprints.length === 0) {
        setChartData([]);
        setLoading(false);
        return;
      }

      // Reverse to chronological order (oldest to newest)
      const sortedSprints = sprints.reverse();

      // 2. Fetch tasks for these sprints to calculate completed hours
      const sprintIds = sortedSprints.map(s => s.id);
      
      const { data: tasks, error: tasksError } = await supabase
        .from('tasks')
        .select('sprint_id, estimated_hours, completed_at')
        .in('sprint_id', sprintIds)
        .not('completed_at', 'is', null); // only care about completed tasks

      if (tasksError) throw tasksError;

      // 3. Aggregate data
      const dataPoints = sortedSprints.map(sprint => {
        const sprintTasks = tasks?.filter(t => t.sprint_id === sprint.id) || [];
        const completedHours = sprintTasks.reduce((sum, t) => sum + Number(t.estimated_hours || 0), 0);
        
        return {
          name: sprint.name,
          completed: completedHours
        };
      });

      setChartData(dataPoints);

    } catch (error) {
      console.error('Error fetching velocity data:', error);
    } finally {
      setLoading(false);
    }
  }, [projectId, supabase]);

  useEffect(() => {
    fetchVelocityData();
  }, [fetchVelocityData]);

  if (loading) {
    return (
      <Card className="h-80 flex items-center justify-center border-border shadow-sm">
        <Loader2 className="size-6 animate-spin text-primary" />
      </Card>
    );
  }

  if (chartData.length === 0) {
    return (
      <Card className="border-border shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Velocity</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground text-center py-10">
            No completed sprints found. Complete a sprint to see velocity trends.
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border shadow-sm">
      <CardHeader>
        <CardTitle className="text-lg">Velocity Trend</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="h-[300px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} margin={{ top: 5, right: 20, bottom: 5, left: -20 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e5e7eb" />
              <XAxis dataKey="name" tick={{ fontSize: 12, fill: '#6b7280' }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fontSize: 12, fill: '#6b7280' }} axisLine={false} tickLine={false} />
              <Tooltip 
                cursor={{ fill: '#f3f4f6' }}
                contentStyle={{ borderRadius: '8px', border: '1px solid #e5e7eb', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                labelStyle={{ fontWeight: 'bold', color: '#111827', marginBottom: '4px' }}
                formatter={(value: any) => [`${value ?? 0} Hrs`, 'Completed Work']}
              />
              <Bar dataKey="completed" fill="#10b981" radius={[4, 4, 0, 0]} maxBarSize={50} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Loader2 } from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer
} from 'recharts';
import { format, differenceInDays, addDays, parseISO, startOfDay, isAfter } from 'date-fns';

interface SprintBurndownProps {
  projectId: string;
}

export function SprintBurndown({ projectId }: SprintBurndownProps) {
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  const [chartData, setChartData] = useState<any[]>([]);
  const [sprintName, setSprintName] = useState<string>('');

  const fetchBurndownData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      // 1. Get Active Sprint
      const { data: sprintData, error: sprintError } = await supabase
        .from('sprints')
        .select('*')
        .eq('project_id', projectId)
        .eq('status', 'active')
        .maybeSingle();

      if (sprintError || !sprintData || !sprintData.start_date || !sprintData.end_date) {
        setChartData([]);
        setLoading(false);
        return;
      }

      setSprintName(sprintData.name);

      // 2. Get tasks for this sprint
      const { data: tasks, error: tasksError } = await supabase
        .from('tasks')
        .select('id, estimated_hours, completed_at, status_id')
        .eq('sprint_id', sprintData.id);

      if (tasksError) throw tasksError;

      // 3. Process Data for Chart
      const startDate = startOfDay(parseISO(sprintData.start_date));
      const endDate = startOfDay(parseISO(sprintData.end_date));
      const totalDays = differenceInDays(endDate, startDate) + 1;
      
      let totalEstimatedHours = 0;
      tasks?.forEach(t => {
        totalEstimatedHours += Number(t.estimated_hours || 0);
      });

      const dataPoints = [];
      const today = startOfDay(new Date());

      // Calculate daily decrement for ideal line
      const idealDailyBurn = totalDays > 1 ? totalEstimatedHours / (totalDays - 1) : totalEstimatedHours;

      let actualRemaining = totalEstimatedHours;

      for (let i = 0; i < totalDays; i++) {
        const currentDate = addDays(startDate, i);
        const dateStr = format(currentDate, 'MMM dd');

        // Ideal remaining logic
        const idealRemaining = Math.max(0, totalEstimatedHours - (idealDailyBurn * i));

        // Actual remaining logic (only calculate up to today)
        let actualPoint = null;
        if (!isAfter(currentDate, today)) {
          // Find tasks completed ON this specific day
          const tasksCompletedToday = tasks?.filter(t => {
            if (!t.completed_at) return false;
            const completedDate = startOfDay(parseISO(t.completed_at));
            return completedDate.getTime() === currentDate.getTime();
          }) || [];

          const hoursBurnedToday = tasksCompletedToday.reduce((sum, t) => sum + Number(t.estimated_hours || 0), 0);
          actualRemaining -= hoursBurnedToday;
          actualPoint = actualRemaining;
        }

        dataPoints.push({
          date: dateStr,
          ideal: parseFloat(idealRemaining.toFixed(1)),
          actual: actualPoint !== null ? parseFloat(actualPoint.toFixed(1)) : null
        });
      }

      setChartData(dataPoints);

    } catch (error) {
      console.error('Error fetching burndown data:', error);
    } finally {
      setLoading(false);
    }
  }, [projectId, supabase]);

  useEffect(() => {
    fetchBurndownData();
  }, [fetchBurndownData]);

  if (loading) {
    return (
      <Card className="h-80 flex items-center justify-center border-border shadow-sm">
        <Loader2 className="size-6 animate-spin text-primary" />
      </Card>
    );
  }

  if (chartData.length === 0) {
    return (
      <Card className="border-border shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Sprint Burndown</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground text-center py-10">
            No active sprint found or sprint has no dates configured.
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border shadow-sm">
      <CardHeader>
        <CardTitle className="text-lg">Burndown: {sprintName}</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="h-[300px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} margin={{ top: 5, right: 20, bottom: 5, left: -20 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e5e7eb" />
              <XAxis dataKey="date" tick={{ fontSize: 12, fill: '#6b7280' }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fontSize: 12, fill: '#6b7280' }} axisLine={false} tickLine={false} />
              <Tooltip 
                contentStyle={{ borderRadius: '8px', border: '1px solid #e5e7eb', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                labelStyle={{ fontWeight: 'bold', color: '#111827', marginBottom: '4px' }}
              />
              <Legend wrapperStyle={{ paddingTop: '10px' }} />
              <Line 
                type="monotone" 
                name="Ideal Burndown"
                dataKey="ideal" 
                stroke="#94a3b8" 
                strokeWidth={2}
                strokeDasharray="5 5" 
                dot={false}
              />
              <Line 
                type="monotone" 
                name="Actual Remaining (Hrs)"
                dataKey="actual" 
                stroke="#3b82f6" 
                strokeWidth={3}
                dot={{ r: 4, fill: '#3b82f6', strokeWidth: 0 }}
                activeDot={{ r: 6 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Loader2 } from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Progress } from '@/components/ui/progress';

interface TeamWorkloadProps {
  projectId: string;
}

export function TeamWorkload({ projectId }: TeamWorkloadProps) {
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  const [workloadData, setWorkloadData] = useState<any[]>([]);

  const fetchWorkloadData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    try {
      // Fetch open tasks for this project with their assignees
      const { data: rawTasks, error } = await supabase
        .from('tasks')
        .select(`id, estimated_hours, assigned_workspace_member_id, status_id, assignee:workspace_members!tasks_assigned_workspace_member_id_fkey ( id, user_id )`)
        .eq('project_id', projectId)
        .is('completed_at', null)
        .not('assigned_workspace_member_id', 'is', null);

      if (error) throw error;

      // Two-step: enrich assignees with profile data
      const tasks = rawTasks || [];
      if (tasks.length > 0) {
        const userIds = tasks.map((t: any) => t.assignee?.user_id).filter(Boolean);
        if (userIds.length > 0) {
          const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name, avatar_url').in('user_id', userIds);
          const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
          tasks.forEach((t: any) => { if (t.assignee?.user_id) t.assignee.profiles = profileMap[t.assignee.user_id] || null; });
        }
      }

      // Group by assignee
      const workloadMap = new Map<string, any>();

      tasks?.forEach(task => {
        const assignee = task.assignee as any;
        if (!assignee || !assignee.id) return;

        const memberId = assignee.id;
        const profile = assignee.profiles;
        
        if (!workloadMap.has(memberId)) {
          workloadMap.set(memberId, {
            id: memberId,
            name: profile?.full_name || 'Unknown User',
            avatar: profile?.avatar_url,
            taskCount: 0,
            totalHours: 0
          });
        }

        const data = workloadMap.get(memberId);
        data.taskCount += 1;
        data.totalHours += Number(task.estimated_hours || 0);
      });

      const processedData = Array.from(workloadMap.values()).sort((a, b) => b.totalHours - a.totalHours);
      setWorkloadData(processedData);

    } catch (error) {
      console.error('Error fetching workload data:', error);
    } finally {
      setLoading(false);
    }
  }, [projectId, supabase]);

  useEffect(() => {
    fetchWorkloadData();
  }, [fetchWorkloadData]);

  if (loading) {
    return (
      <Card className="h-80 flex items-center justify-center border-border shadow-sm">
        <Loader2 className="size-6 animate-spin text-primary" />
      </Card>
    );
  }

  if (workloadData.length === 0) {
    return (
      <Card className="border-border shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Team Workload</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground text-center py-10">
            No active tasks assigned to team members.
          </p>
        </CardContent>
      </Card>
    );
  }

  // Find max hours to calculate percentage bars safely
  const maxHours = Math.max(...workloadData.map(d => d.totalHours), 1);

  return (
    <Card className="border-border shadow-sm">
      <CardHeader>
        <CardTitle className="text-lg">Active Team Workload</CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {workloadData.map(member => (
          <div key={member.id} className="space-y-2">
            <div className="flex items-center justify-between text-sm">
              <div className="flex items-center gap-2">
                <Avatar className="size-6 border">
                  <AvatarImage src={member.avatar} />
                  <AvatarFallback className="text-[10px] bg-primary/10 text-primary">
                    {member.name.substring(0, 2).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
                <span className="font-medium">{member.name}</span>
              </div>
              <div className="flex items-center gap-4 text-muted-foreground text-xs font-medium">
                <span>{member.taskCount} tasks</span>
                <span className="text-foreground">{member.totalHours} hrs</span>
              </div>
            </div>
            <Progress value={(member.totalHours / maxHours) * 100} className="h-2 bg-secondary" />
          </div>
        ))}
      </CardContent>
    </Card>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Plus, Trash2, GripVertical, Loader2, Link as LinkIcon, Copy } from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Checkbox } from '@/components/ui/checkbox';
import { Badge } from '@/components/ui/badge';
import { IconAction } from "@/components/ui/icon-action";

interface WorkflowSettingsProps {
  projectId: string;
}

export function WorkflowSettings({ projectId }: WorkflowSettingsProps) {
  const supabase = createClient();
  const [statuses, setStatuses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  // New status form state
  const [newStatusName, setNewStatusName] = useState('');
  const [newStatusCategory, setNewStatusCategory] = useState('TODO');
  const [newStatusColor] = useState('slate');
  const [isAdding, setIsAdding] = useState(false);
  const [hourlyRate, setHourlyRate] = useState<string>('0');
  const [isSavingRate, setIsSavingRate] = useState(false);

  // Portal state
  const [isPublic, setIsPublic] = useState(false);
  const [shareToken, setShareToken] = useState('');
  const [portalSettings, setPortalSettings] = useState({ show_timeline: true, show_board: false });
  const [isSavingPortal, setIsSavingPortal] = useState(false);

  // Visualizer state
  const [showTransitionLabels, setShowTransitionLabels] = useState(true);
  const [selectedStatusId, setSelectedStatusId] = useState<string | null>(null);
  const [zoomLevel, setZoomLevel] = useState(100);

  const fetchStatuses = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);
    const { data, error } = await supabase
      .from('project_statuses')
      .select('*')
      .eq('project_id', projectId)
      .order('sort_order', { ascending: true });
      
      if (error) {
      toast.error('Failed to load workflow statuses');
    } else if (!data || data.length === 0) {
      // Auto-seed default workflow statuses if project has none
      const defaults = [
        { project_id: projectId, name: 'To Do', category: 'TODO', color: 'slate', sort_order: 1 },
        { project_id: projectId, name: 'In Progress', category: 'IN_PROGRESS', color: 'blue', sort_order: 2 },
        { project_id: projectId, name: 'Review', category: 'IN_PROGRESS', color: 'orange', sort_order: 3 },
        { project_id: projectId, name: 'Done', category: 'DONE', color: 'emerald', sort_order: 4 },
      ];
      const { data: seeded } = await supabase.from('project_statuses').insert(defaults).select('*');
      setStatuses(seeded || []);
    } else {
      setStatuses(data || []);
    }
    
    // Fetch project settings
    const { data: projectData } = await supabase
      .from('projects')
      .select('hourly_rate, is_public, public_share_token, portal_settings')
      .eq('id', projectId)
      .single();
      
    if (projectData) {
      if (projectData.hourly_rate) setHourlyRate(projectData.hourly_rate.toString());
      setIsPublic(projectData.is_public || false);
      setShareToken(projectData.public_share_token || '');
      if (projectData.portal_settings) setPortalSettings(projectData.portal_settings);
    }

    setLoading(false);
  }, [projectId, supabase]);

  useEffect(() => {
    fetchStatuses();
  }, [fetchStatuses]);

  const handleAddStatus = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStatusName.trim()) return;

    setIsAdding(true);
    try {
      const { error } = await supabase.from('project_statuses').insert({
        project_id: projectId,
        name: newStatusName.trim(),
        category: newStatusCategory,
        color: newStatusColor,
        sort_order: statuses.length + 1
      });

      if (error) throw error;
      toast.success('Status added successfully');
      setNewStatusName('');
      fetchStatuses();
    } catch (err: any) {
      toast.error(err.message || 'Failed to add status');
    } finally {
      setIsAdding(false);
    }
  };

  const handleDeleteStatus = async (statusId: string) => {
    try {
      // Basic safeguard: don't delete if it's the only status
      if (statuses.length <= 1) {
        toast.error('Projects must have at least one status');
        return;
      }
      
      const { error } = await supabase.from('project_statuses').delete().eq('id', statusId);
      if (error) throw error;
      toast.success('Status deleted');
      fetchStatuses();
    } catch {
      toast.error('Failed to delete status. It might be in use.');
    }
  };

  const handleSaveRate = async () => {
    setIsSavingRate(true);
    try {
      const rateNum = parseFloat(hourlyRate);
      if (isNaN(rateNum) || rateNum < 0) {
        toast.error('Please enter a valid hourly rate');
        return;
      }
      
      const { error } = await supabase
        .from('projects')
        .update({ hourly_rate: rateNum })
        .eq('id', projectId);
        
      if (error) throw error;
      toast.success('Hourly rate saved');
    } catch {
      toast.error('Failed to save hourly rate');
    } finally {
      setIsSavingRate(false);
    }
  };

  const handleSavePortal = async (updates: any) => {
    setIsSavingPortal(true);
    try {
      const { error } = await supabase
        .from('projects')
        .update(updates)
        .eq('id', projectId);
        
      if (error) throw error;
      toast.success('Portal settings updated');
    } catch {
      toast.error('Failed to update portal settings');
    } finally {
      setIsSavingPortal(false);
    }
  };

  const togglePublic = (checked: boolean) => {
    setIsPublic(checked);
    handleSavePortal({ is_public: checked });
  };

  const togglePortalSetting = (key: string, checked: boolean) => {
    const newSettings = { ...portalSettings, [key]: checked };
    setPortalSettings(newSettings);
    handleSavePortal({ portal_settings: newSettings });
  };

  const getCategoryColor = (cat: string) => {
    switch (cat) {
      case 'TODO': return 'text-muted-foreground bg-muted/10 border-border';
      case 'IN_PROGRESS': return 'text-blue-500 bg-blue-500/10 border-blue-200';
      case 'DONE': return 'text-emerald-500 bg-emerald-500/10 border-emerald-200';
      default: return 'text-muted-foreground bg-muted/10';
    }
  };

  if (loading) {
    return <div className="flex justify-center p-8"><Loader2 className="size-6 animate-spin text-primary" /></div>;
  }

  const shareUrl = typeof window !== 'undefined' ? `${window.location.origin}/portal/${shareToken}` : '';

  return (
    <div className="space-y-6">
      {/* Client Portal Settings */}
      <Card className="border-border shadow-sm border-primary/20 bg-primary/5">
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <LinkIcon className="size-5 text-primary" /> Client Portal
          </CardTitle>
          <CardDescription>Share a read-only view of the project with external clients</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="font-medium text-sm">Enable Public Sharing</p>
              <p className="text-xs text-muted-foreground">Anyone with the link can view the project status</p>
            </div>
            <Switch checked={isPublic} onCheckedChange={togglePublic} disabled={isSavingPortal} />
          </div>

          {isPublic && (
            <div className="space-y-4 pt-4 border-t border-primary/10">
              <div className="space-y-2">
                <Label>Public Link</Label>
                <div className="flex items-center gap-2">
                  <Input readOnly value={shareUrl} className="bg-background font-mono text-xs" />
                  <IconAction
                    label="Copy"
                    icon={<Copy className="size-4" />}
                    variant="outline"
                    onClick={() => {
                      navigator.clipboard.writeText(shareUrl);
                      toast.success('Copied to clipboard');
                    }}
                  />
                </div>
              </div>

              <div className="space-y-3">
                <Label>Visible Modules</Label>
                <div className="flex items-center gap-2">
                  <Checkbox 
                    id="show_timeline" 
                    checked={portalSettings.show_timeline} 
                    onCheckedChange={(c) => togglePortalSetting('show_timeline', !!c)} 
                    disabled={isSavingPortal}
                  />
                  <Label htmlFor="show_timeline" className="font-normal">Timeline (Roadmap)</Label>
                </div>
                <div className="flex items-center gap-2">
                  <Checkbox 
                    id="show_board" 
                    checked={portalSettings.show_board} 
                    onCheckedChange={(c) => togglePortalSetting('show_board', !!c)} 
                    disabled={isSavingPortal}
                  />
                  <Label htmlFor="show_board" className="font-normal">Kanban Board</Label>
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Finance Settings */}
      <Card className="border-border shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Financial Settings</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-end gap-4 max-w-sm">
            <div className="space-y-2 flex-1">
              <Label>Project Hourly Rate</Label>
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-muted-foreground">$</span>
                <Input 
                  type="number"
                  min="0"
                  step="0.01"
                  value={hourlyRate} 
                  onChange={(e) => setHourlyRate(e.target.value)}
                  className="pl-7 bg-card"
                />
              </div>
            </div>
            <Button onClick={handleSaveRate} disabled={isSavingRate}>
              {isSavingRate ? <Loader2 className="size-4 animate-spin" /> : 'Save Rate'}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Jira Interactive Workflow Visualizer */}
      <Card className="border-border shadow-sm overflow-hidden bg-card">
        <CardHeader className="border-b bg-muted/20 pb-4">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <CardTitle className="text-lg flex items-center gap-2">
                Interactive Workflow Diagram
              </CardTitle>
              <CardDescription>Visual map of status transitions and available state flows</CardDescription>
            </div>
            {statuses.length > 0 && (
              <div className="flex flex-wrap items-center gap-4 text-xs">
                <div>
                  <span className="text-muted-foreground mr-2 font-medium">Current status:</span>
                  <Badge variant="outline" className="uppercase font-semibold text-primary bg-primary/10 border-primary/20">
                    {(statuses.find(s => s.id === (selectedStatusId || statuses[0]?.id)) || statuses[0])?.name}
                  </Badge>
                </div>
                <div className="flex items-center gap-1.5">
                  <span className="text-muted-foreground font-medium">Can be moved to:</span>
                  <div className="flex items-center gap-1">
                    {statuses
                      .filter(s => s.id !== (selectedStatusId || statuses[0]?.id))
                      .map(s => (
                        <Badge key={s.id} variant="outline" className={`uppercase text-[10px] ${getCategoryColor(s.category)}`}>
                          {s.name}
                        </Badge>
                      ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </CardHeader>
        <CardContent className="p-6">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <Checkbox 
                id="show_transition_labels" 
                checked={showTransitionLabels} 
                onCheckedChange={(c) => setShowTransitionLabels(!!c)} 
              />
              <Label htmlFor="show_transition_labels" className="text-xs font-medium cursor-pointer">
                Show transition labels
              </Label>
            </div>
          </div>

          {/* Workflow Diagram Canvas */}
          <div className="relative border border-border/80 rounded-xl bg-muted/50/50 dark:bg-background/50 p-8 min-h-[220px] flex items-center justify-center overflow-x-auto">
            <div 
              className="flex items-center gap-6 transition-all duration-200"
              style={{ transform: `scale(${zoomLevel / 100})`, transformOrigin: 'center center' }}
            >
              {/* START Node */}
              <div className="flex items-center gap-3">
                <div className="size-10 rounded-full bg-card text-foreground font-bold text-[10px] tracking-wider flex items-center justify-center shadow-md">
                  START
                </div>
                <div className="w-8 h-0.5 bg-muted-foreground/40 relative">
                  <div className="absolute right-0 top-1/2 -translate-y-1/2 border-y-4 border-y-transparent border-l-6 border-l-muted-foreground/40" />
                </div>
              </div>

              {/* Status Nodes */}
              {statuses.map((status, index) => {
                const isSelected = (selectedStatusId || statuses[0]?.id) === status.id;
                const isLast = index === statuses.length - 1;

                return (
                  <div key={status.id} className="flex items-center gap-6">
                    <div 
                      onClick={() => setSelectedStatusId(status.id)}
                      className={`relative cursor-pointer px-5 py-2.5 rounded-lg border-2 font-bold text-xs uppercase tracking-wider transition-all duration-150 shadow-sm flex items-center gap-2 ${
                        isSelected 
                          ? 'ring-2 ring-primary ring-offset-2 scale-105 shadow-md bg-background' 
                          : 'bg-background hover:border-primary/50'
                      } ${getCategoryColor(status.category)}`}
                    >
                      {status.name}

                      {/* Transition Label 'Any' */}
                      {showTransitionLabels && (
                        <div className="absolute -top-3 -right-2 bg-muted text-foreground text-[9px] font-medium px-1.5 py-0.5 rounded-full shadow">
                          Any
                        </div>
                      )}
                    </div>

                    {!isLast && (
                      <div className="w-8 h-0.5 bg-muted-foreground/40 relative">
                        <div className="absolute right-0 top-1/2 -translate-y-1/2 border-y-4 border-y-transparent border-l-6 border-l-muted-foreground/40" />
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Zoom Controls Bar */}
            <div className="absolute bottom-3 right-4 flex items-center gap-2 bg-background/90 backdrop-blur border border-border px-3 py-1.5 rounded-lg shadow-sm">
              <button 
                onClick={() => setZoomLevel(prev => Math.max(70, prev - 10))}
                className="text-xs font-bold text-muted-foreground hover:text-foreground px-1"
              >
                -
              </button>
              <input 
                type="range" 
                min="70" 
                max="130" 
                value={zoomLevel} 
                onChange={(e) => setZoomLevel(Number(e.target.value))}
                className="w-20 accent-primary cursor-pointer h-1.5"
              />
              <button 
                onClick={() => setZoomLevel(prev => Math.min(130, prev + 10))}
                className="text-xs font-bold text-muted-foreground hover:text-foreground px-1"
              >
                +
              </button>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card className="border-border shadow-sm">
        <CardHeader>
          <CardTitle className="text-lg">Workflow Statuses</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-2">
            {statuses.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-4">No statuses configured.</p>
            ) : (
              statuses.map((status) => (
                <div key={status.id} className="flex items-center justify-between p-3 border border-border rounded-lg bg-card">
                  <div className="flex items-center gap-3">
                    <GripVertical className="size-4 text-muted-foreground cursor-grab" />
                    <span className="font-medium text-sm">{status.name}</span>
                    <span className={`text-[10px] uppercase px-2 py-0.5 rounded-full border ${getCategoryColor(status.category)}`}>
                      {status.category.replace('_', ' ')}
                    </span>
                  </div>
                  <IconAction
                    label="Delete"
                    icon={<Trash2 className="size-4" />}
                    variant="ghost"
                    onClick={() => handleDeleteStatus(status.id)}
                    className="text-destructive hover:bg-destructive/10 hover:text-destructive"
                  />
                </div>
              ))
            )}
          </div>

          <div className="pt-4 border-t border-border">
            <h4 className="text-sm font-medium mb-3">Add New Status</h4>
            <form onSubmit={handleAddStatus} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
              <div className="space-y-1.5 md:col-span-2">
                <Label>Name</Label>
                <Input 
                  value={newStatusName} 
                  onChange={e => setNewStatusName(e.target.value)} 
                  placeholder="e.g. QA Review" 
                  className="bg-card"
                  required
                />
              </div>
              <div className="space-y-1.5">
                <Label>Category</Label>
                <Select value={newStatusCategory} onValueChange={(val) => val && setNewStatusCategory(val)}>
                  <SelectTrigger className="bg-card"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="TODO">To Do</SelectItem>
                    <SelectItem value="IN_PROGRESS">In Progress</SelectItem>
                    <SelectItem value="DONE">Done</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <Button type="submit" disabled={isAdding || !newStatusName.trim()} className="w-full">
                {isAdding ? <Loader2 className="size-4 animate-spin" /> : <><Plus className="size-4 mr-2" /> Add</>}
              </Button>
            </form>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { useWorkspace } from "@/hooks/use-workspace";
import { createClient } from "@/lib/supabase/client";
import { SettingsPanelHead } from "@/components/settings/settings-panel-head";
import {
  Landmark,
  FileText,
  Save,
  Loader2,
  Receipt,
  Percent,
  CalendarDays
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { IconAction } from "@/components/ui/icon-action";

export function AccountingSettingsPanel() {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Settings State
  const [financialYearStartMonth, setFinancialYearStartMonth] = useState("4"); // April
  const [defaultGstRate, setDefaultGstRate] = useState(18);
  const [pricesIncludeTax, setPricesIncludeTax] = useState(false);
  const [invoicePrefix, setInvoicePrefix] = useState("INV-");
  const [receiptPrefix, setReceiptPrefix] = useState("RCT-");
  const [voucherPrefix, setVoucherPrefix] = useState("VCH-");
  const [enableCreditLimitCheck, setEnableCreditLimitCheck] = useState(true);

  useEffect(() => {
    if (!activeWorkspace?.id) return;
    const fetchSettings = async () => {
      setLoading(true);
      const { data } = await supabase
        .from("workspaces")
        .select("plan_limits")
        .eq("id", activeWorkspace.id)
        .maybeSingle();

      if (data?.plan_limits?.accounting_settings) {
        const acc = data.plan_limits.accounting_settings;
        setFinancialYearStartMonth(acc.financialYearStartMonth || "4");
        setDefaultGstRate(acc.defaultGstRate ?? 18);
        setPricesIncludeTax(acc.pricesIncludeTax ?? false);
        setInvoicePrefix(acc.invoicePrefix || "INV-");
        setReceiptPrefix(acc.receiptPrefix || "RCT-");
        setVoucherPrefix(acc.voucherPrefix || "VCH-");
        setEnableCreditLimitCheck(acc.enableCreditLimitCheck ?? true);
      }
      setLoading(false);
    };

    fetchSettings();
  }, [activeWorkspace?.id, supabase]);

  const handleSave = async () => {
    if (!activeWorkspace?.id) return;
    setSaving(true);

    try {
      const { data: currentWs } = await supabase
        .from("workspaces")
        .select("plan_limits")
        .eq("id", activeWorkspace.id)
        .single();

      const existingLimits = currentWs?.plan_limits || {};
      const updatedLimits = {
        ...existingLimits,
        accounting_settings: {
          financialYearStartMonth,
          defaultGstRate,
          pricesIncludeTax,
          invoicePrefix,
          receiptPrefix,
          voucherPrefix,
          enableCreditLimitCheck,
          updated_at: new Date().toISOString(),
        },
      };

      const { error } = await supabase
        .from("workspaces")
        .update({ plan_limits: updatedLimits })
        .eq("id", activeWorkspace.id);

      if (error) throw error;
      toast.success("Accounting & Financial settings saved successfully!");
    } catch (err: any) {
      toast.error(err.message || "Failed to save accounting settings.");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12 text-muted-foreground text-xs">
        <Loader2 className="size-5 animate-spin mr-2" />
        Loading Accounting Settings...
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-4xl text-foreground">
      <SettingsPanelHead
        title="Accounting & Ledger Settings"
        description="Configure financial year boundaries, GST defaults, voucher numbering, and customer credit limits."
        action={
          <IconAction label="Save Changes" icon={saving ? <Loader2 className="size-4 animate-spin" /> : <Save className="size-4" />} onClick={handleSave}
            disabled={saving}
            className="bg-primary text-primary-foreground hover:bg-primary/90 font-semibold gap-1.5 shadow-xs" />
        }
      />

      {/* 1. Financial Year & Tax Defaults */}
      <Card className="bg-card border-border shadow-xs rounded-2xl">
        <CardHeader className="pb-3">
          <CardTitle className="text-base font-bold flex items-center gap-2 text-foreground">
            <Landmark className="size-4 text-primary" /> Financial Year & GST Configuration
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground">
            Set accounting period boundaries and default tax computation rules.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Financial Year Start Month</Label>
              <select
                value={financialYearStartMonth}
                onChange={(e) => setFinancialYearStartMonth(e.target.value)}
                className="w-full bg-background border border-border text-foreground text-xs rounded-lg px-3 py-2 focus:ring-1 focus:ring-primary"
              >
                <option value="1">January (Calendar Year)</option>
                <option value="4">April (April to March - India / UK)</option>
                <option value="7">July (July to June)</option>
                <option value="10">October (October to September)</option>
              </select>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Default GST Rate (%)</Label>
              <Input
                type="number"
                min={0}
                max={100}
                value={defaultGstRate}
                onChange={(e) => setDefaultGstRate(Number(e.target.value))}
                className="bg-background text-xs"
              />
            </div>
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-border/60">
            <div className="space-y-0.5">
              <Label className="text-xs font-semibold">Prices Include Tax (Tax Inclusive)</Label>
              <p className="text-[11px] text-muted-foreground">When enabled, product prices listed in ledgers already include GST/sales tax.</p>
            </div>
            <Switch
              checked={pricesIncludeTax}
              onCheckedChange={setPricesIncludeTax}
            />
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-border/60">
            <div className="space-y-0.5">
              <Label className="text-xs font-semibold">Enforce Customer Credit Limits</Label>
              <p className="text-[11px] text-muted-foreground">Warn or block new sales entries when customer outstanding balance exceeds credit limit.</p>
            </div>
            <Switch
              checked={enableCreditLimitCheck}
              onCheckedChange={setEnableCreditLimitCheck}
            />
          </div>
        </CardContent>
      </Card>

      {/* 2. Document & Voucher Prefixes */}
      <Card className="bg-card border-border shadow-xs rounded-2xl">
        <CardHeader className="pb-3">
          <CardTitle className="text-base font-bold flex items-center gap-2 text-foreground">
            <Receipt className="size-4 text-emerald-500" /> Voucher & Document Prefixes
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground">
            Customize auto-generated document numbers for Accounting vouchers and invoices.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Invoice Prefix</Label>
              <Input
                type="text"
                value={invoicePrefix}
                onChange={(e) => setInvoicePrefix(e.target.value)}
                className="bg-background text-xs font-mono"
              />
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Receipt Prefix</Label>
              <Input
                type="text"
                value={receiptPrefix}
                onChange={(e) => setReceiptPrefix(e.target.value)}
                className="bg-background text-xs font-mono"
              />
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Voucher Prefix</Label>
              <Input
                type="text"
                value={voucherPrefix}
                onChange={(e) => setVoucherPrefix(e.target.value)}
                className="bg-background text-xs font-mono"
              />
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { toast } from "sonner";
import {
  MapPin,
  Loader2,
  Save,
  Crosshair,
  ShieldCheck,
  ClipboardList,
  CalendarPlus,
  Trash2,
  Info,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { SettingsPanelHead } from "./settings-panel-head";
import { GeofenceMapPicker } from "@/components/attendance/geofence-map-picker";
import { WorkLocationsManager } from "./work-locations-manager";
import {
  WORK_LOCATIONS,
  WORK_LOCATION_LABELS,
  type WorkLocation,
} from "@/lib/attendance/policy";
import { IconAction } from "@/components/ui/icon-action";

type ScopeType = "WORKSPACE_DEFAULT" | "DEPARTMENT" | "MEMBER";

interface MemberOption {
  id: string;
  label: string;
}

/** Shape of a row in `hr_attendance_policies` (migration 086). */
interface PolicyRow {
  id: string;
  scope_type: ScopeType;
  scope_id: string | null;
  allowed_work_locations: WorkLocation[] | null;
  default_work_location: WorkLocation | null;
  require_location: boolean | null;
  min_gps_accuracy_m: number | null;
  geofence_latitude: number | null;
  geofence_longitude: number | null;
  geofence_radius_m: number | null;
  geofence_label: string | null;
  block_outside_geofence: boolean | null;
  require_timesheet_on_punch_out: boolean | null;
  timesheet_template_id: string | null;
}

/** Shape of a row in `hr_attendance_day_overrides` (migration 086). */
interface OverrideRow {
  id: string;
  workspace_member_id: string;
  override_date: string;
  allowed_work_locations: WorkLocation[] | null;
  note: string | null;
}

/** Supabase errors and thrown values both reach the catch blocks here. */
function errorMessage(err: unknown, fallback: string): string {
  if (err instanceof Error && err.message) return err.message;
  if (typeof err === "object" && err !== null && "message" in err) {
    const m = (err as { message?: unknown }).message;
    if (typeof m === "string" && m) return m;
  }
  return fallback;
}

const NONE = "none";

/** Blank policy used for a scope that has no row yet. */
const EMPTY_FORM = {
  allowed: ["OFFICE", "WFH"] as WorkLocation[],
  defaultLocation: "OFFICE" as WorkLocation,
  requireLocation: true,
  minAccuracy: "100",
  geofenceEnabled: false,
  lat: "",
  lng: "",
  radius: "100",
  label: "",
  blockOutside: false,
  requireTimesheet: false,
  timesheetTemplateId: NONE,
};

export function AttendancePolicyPanel() {
  const supabase = createClient();
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can("people_manage") || can("settings_workspace");

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [departments, setDepartments] = useState<{ id: string; name: string }[]>([]);
  const [members, setMembers] = useState<MemberOption[]>([]);
  const [templates, setTemplates] = useState<{ id: string; name: string }[]>([]);
  const [policies, setPolicies] = useState<PolicyRow[]>([]);

  const [scopeType, setScopeType] = useState<ScopeType>("WORKSPACE_DEFAULT");
  const [scopeId, setScopeId] = useState<string>(NONE);
  const [form, setForm] = useState(EMPTY_FORM);

  // Day exceptions
  const [overrides, setOverrides] = useState<OverrideRow[]>([]);
  const [ovMemberId, setOvMemberId] = useState<string>(NONE);
  const [ovDate, setOvDate] = useState<string>(() => new Date().toISOString().split("T")[0]);
  const [ovAllowWfh, setOvAllowWfh] = useState(true);
  const [ovNote, setOvNote] = useState("");
  const [savingOverride, setSavingOverride] = useState(false);

  const fetchData = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const [deptRes, memberRes, tplRes, policyRes, ovRes] = await Promise.all([
        supabase.from("departments").select("id, name").eq("workspace_id", activeWorkspace.id),
        supabase
          .from("workspace_members")
          .select("id, user_id")
          .eq("workspace_id", activeWorkspace.id),
        supabase
          .from("hr_timesheet_templates")
          .select("id, name, workspace_id")
          .or(`workspace_id.is.null,workspace_id.eq.${activeWorkspace.id}`)
          .order("name"),
        supabase
          .from("hr_attendance_policies")
          .select("*")
          .eq("workspace_id", activeWorkspace.id),
        supabase
          .from("hr_attendance_day_overrides")
          .select("*")
          .eq("workspace_id", activeWorkspace.id)
          .gte("override_date", new Date().toISOString().split("T")[0])
          .order("override_date"),
      ]);

      setDepartments(deptRes.data || []);
      setTemplates(tplRes.data || []);
      setPolicies((policyRes.data as PolicyRow[] | null) || []);
      setOverrides((ovRes.data as OverrideRow[] | null) || []);

      // workspace_members.user_id references auth.users, so a
      // workspace_members(profiles(...)) embed is impossible — the name has
      // to come from a second query keyed on user_id.
      const memberRows = memberRes.data || [];
      const userIds = memberRows.map((m) => m.user_id).filter(Boolean);
      let nameByUser = new Map<string, string>();
      if (userIds.length > 0) {
        const { data: profiles } = await supabase
          .from("profiles")
          .select("user_id, full_name")
          .in("user_id", userIds);
        nameByUser = new Map(
          (profiles || []).map((p) => [p.user_id as string, (p.full_name as string) || ""])
        );
      }
      setMembers(
        memberRows.map((m) => ({
          id: m.id as string,
          label: nameByUser.get(m.user_id as string) || "Unnamed member",
        }))
      );
    } catch (err) {
      console.error(err);
      toast.error("Failed to load attendance policies");
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, supabase]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const activePolicy = useMemo(() => {
    const target = scopeType === "WORKSPACE_DEFAULT" ? null : scopeId === NONE ? null : scopeId;
    return policies.find(
      (p) => p.scope_type === scopeType && (p.scope_id ?? null) === target
    );
  }, [policies, scopeType, scopeId]);

  // Load the selected scope's saved values into the form, or reset to blank
  // when that scope has no policy yet.
  useEffect(() => {
    if (!activePolicy) {
      setForm(EMPTY_FORM);
      return;
    }
    setForm({
      allowed: (activePolicy.allowed_work_locations || ["OFFICE"]) as WorkLocation[],
      defaultLocation: (activePolicy.default_work_location || "OFFICE") as WorkLocation,
      requireLocation: activePolicy.require_location ?? true,
      minAccuracy: String(activePolicy.min_gps_accuracy_m ?? 100),
      geofenceEnabled: activePolicy.geofence_latitude != null,
      lat: activePolicy.geofence_latitude != null ? String(activePolicy.geofence_latitude) : "",
      lng: activePolicy.geofence_longitude != null ? String(activePolicy.geofence_longitude) : "",
      radius: String(activePolicy.geofence_radius_m ?? 100),
      label: activePolicy.geofence_label || "",
      blockOutside: activePolicy.block_outside_geofence ?? false,
      requireTimesheet: activePolicy.require_timesheet_on_punch_out ?? false,
      timesheetTemplateId: activePolicy.timesheet_template_id || NONE,
    });
  }, [activePolicy]);

  const toggleAllowed = (loc: WorkLocation) => {
    setForm((f) => {
      const has = f.allowed.includes(loc);
      // Never allow an empty set — the member would have nothing to punch in as.
      if (has && f.allowed.length === 1) return f;
      const allowed = has ? f.allowed.filter((l) => l !== loc) : [...f.allowed, loc];
      return {
        ...f,
        allowed,
        // The default must stay selectable.
        defaultLocation: allowed.includes(f.defaultLocation) ? f.defaultLocation : allowed[0],
      };
    });
  };

  const handleSave = async () => {
    if (!activeWorkspace?.id) return;
    if (scopeType !== "WORKSPACE_DEFAULT" && scopeId === NONE) {
      toast.error(
        `Select a specific ${scopeType === "DEPARTMENT" ? "department" : "team member"} first.`
      );
      return;
    }

    const minAccuracy = parseInt(form.minAccuracy || "0", 10);
    if (!Number.isFinite(minAccuracy) || minAccuracy <= 0) {
      toast.error("Required GPS accuracy must be a positive number of metres.");
      return;
    }

    let lat: number | null = null;
    let lng: number | null = null;
    let radius = parseInt(form.radius || "0", 10);
    if (form.geofenceEnabled) {
      lat = parseFloat(form.lat);
      lng = parseFloat(form.lng);
      if (!Number.isFinite(lat) || lat < -90 || lat > 90) {
        toast.error("Geofence latitude must be between -90 and 90.");
        return;
      }
      if (!Number.isFinite(lng) || lng < -180 || lng > 180) {
        toast.error("Geofence longitude must be between -180 and 180.");
        return;
      }
      if (!Number.isFinite(radius) || radius <= 0) {
        toast.error("Geofence radius must be a positive number of metres.");
        return;
      }
    } else {
      radius = radius > 0 ? radius : 100;
    }

    setSaving(true);
    try {
      const payload = {
        workspace_id: activeWorkspace.id,
        scope_type: scopeType,
        scope_id: scopeType === "WORKSPACE_DEFAULT" ? null : scopeId,
        allowed_work_locations: form.allowed,
        default_work_location: form.defaultLocation,
        require_location: form.requireLocation,
        min_gps_accuracy_m: minAccuracy,
        geofence_latitude: lat,
        geofence_longitude: lng,
        geofence_radius_m: radius,
        geofence_label: form.geofenceEnabled ? form.label || null : null,
        block_outside_geofence: form.geofenceEnabled ? form.blockOutside : false,
        require_timesheet_on_punch_out: form.requireTimesheet,
        timesheet_template_id:
          form.timesheetTemplateId === NONE ? null : form.timesheetTemplateId,
      };

      // Update in place when the scope already has a policy; the unique
      // indexes are partial, so onConflict cannot be used here.
      const { error } = activePolicy
        ? await supabase
            .from("hr_attendance_policies")
            .update(payload)
            .eq("id", activePolicy.id)
        : await supabase.from("hr_attendance_policies").insert(payload);

      if (error) throw error;
      toast.success("Attendance policy saved.");
      await fetchData();
    } catch (err: unknown) {
      toast.error(errorMessage(err, "Failed to save attendance policy"));
    } finally {
      setSaving(false);
    }
  };

  const handleAddOverride = async () => {
    if (!activeWorkspace?.id || ovMemberId === NONE) {
      toast.error("Select a team member for the exception.");
      return;
    }
    setSavingOverride(true);
    try {
      const { error } = await supabase.from("hr_attendance_day_overrides").upsert(
        {
          workspace_id: activeWorkspace.id,
          workspace_member_id: ovMemberId,
          override_date: ovDate,
          // A WFH day needs no location; an on-site day inherits the policy.
          allowed_work_locations: ovAllowWfh ? ["WFH", "OFFICE"] : ["OFFICE"],
          require_location: ovAllowWfh ? false : null,
          note: ovNote || null,
        },
        { onConflict: "workspace_member_id,override_date" }
      );
      if (error) throw error;
      toast.success("Day exception saved.");
      setOvNote("");
      await fetchData();
    } catch (err: unknown) {
      toast.error(errorMessage(err, "Failed to save day exception"));
    } finally {
      setSavingOverride(false);
    }
  };

  const handleDeleteOverride = async (id: string) => {
    try {
      const { error } = await supabase
        .from("hr_attendance_day_overrides")
        .delete()
        .eq("id", id)
        .eq("workspace_id", activeWorkspace!.id);
      if (error) throw error;
      toast.success("Day exception removed.");
      await fetchData();
    } catch (err: unknown) {
      toast.error(errorMessage(err, "Failed to remove day exception"));
    }
  };

  const memberName = (id: string) => members.find((m) => m.id === id)?.label || "Unknown member";

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="size-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div>
      <SettingsPanelHead
        title="Attendance & Punch Policy"
        description="Control which work locations each person can punch in as, how precise their GPS must be, and where they must physically be. Settings apply most-specific-first: a day exception beats a person's policy, which beats their department, which beats the workspace default."
        action={
          canManage ? (
            <IconAction label="Save policy" icon={saving ? <Loader2 className="size-4 animate-spin" /> : <Save className="size-4" />} onClick={handleSave} disabled={saving} className="gap-1.5" />
          ) : null
        }
      />

      {!canManage && (
        <div className="mb-5 flex items-start gap-2 rounded-lg border border-amber-500/20 bg-amber-500/10 px-3 py-2 text-xs text-amber-700 dark:text-amber-400">
          <Info className="mt-0.5 size-3.5 shrink-0" />
          <span>You can view these policies but not change them. Ask an admin for the People permission.</span>
        </div>
      )}

      <div className="space-y-5">
        <WorkLocationsManager canEdit={canManage} />

        {/* Scope */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <ShieldCheck className="size-4 text-primary" /> Who this applies to
            </CardTitle>
            <CardDescription>
              Start with the workspace default, then add exceptions per department or per person.
            </CardDescription>
          </CardHeader>
          <CardContent className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Scope</Label>
              <Select
                value={scopeType}
                onValueChange={(v) => {
                  setScopeType(v as ScopeType);
                  setScopeId(NONE);
                }}
              >
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="WORKSPACE_DEFAULT">Everyone (workspace default)</SelectItem>
                  <SelectItem value="DEPARTMENT">A department</SelectItem>
                  <SelectItem value="MEMBER">One person</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {scopeType !== "WORKSPACE_DEFAULT" && (
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">
                  {scopeType === "DEPARTMENT" ? "Department" : "Team member"}
                </Label>
                <Select value={scopeId} onValueChange={setScopeId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select…" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={NONE}>Select…</SelectItem>
                    {(scopeType === "DEPARTMENT"
                      ? departments.map((d) => ({ id: d.id, label: d.name }))
                      : members
                    ).map((o) => (
                      <SelectItem key={o.id} value={o.id}>{o.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="sm:col-span-2">
              <Badge variant="outline" className="text-[11px] font-medium">
                {activePolicy ? "Editing an existing policy" : "No policy yet for this scope — saving creates one"}
              </Badge>
            </div>
          </CardContent>
        </Card>

        {/* Work locations */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <MapPin className="size-4 text-primary" /> Allowed work locations
            </CardTitle>
            <CardDescription>
              The punch screen shows exactly these and nothing else. Tick only Office and an
              on-site employee never sees a Work From Home option.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex flex-wrap gap-2">
              {WORK_LOCATIONS.map((loc) => {
                const active = form.allowed.includes(loc);
                return (
                  <button
                    key={loc}
                    type="button"
                    disabled={!canManage}
                    onClick={() => toggleAllowed(loc)}
                    className={`rounded-lg border px-3 py-1.5 text-xs font-medium transition-colors disabled:opacity-60 ${
                      active
                        ? "border-primary bg-primary text-primary-foreground"
                        : "border-border bg-background text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {WORK_LOCATION_LABELS[loc]}
                  </button>
                );
              })}
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">Default selection</Label>
                <Select
                  value={form.defaultLocation}
                  onValueChange={(v) => setForm((f) => ({ ...f, defaultLocation: v as WorkLocation }))}
                  disabled={!canManage}
                >
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {form.allowed.map((loc) => (
                      <SelectItem key={loc} value={loc}>{WORK_LOCATION_LABELS[loc]}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* GPS */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Crosshair className="size-4 text-primary" /> GPS requirement
            </CardTitle>
            <CardDescription>
              Work From Home never needs a location. For on-site punches, a fix coarser than your
              threshold is refused rather than recorded — that is what stops a wifi-derived
              position hundreds of kilometres away being stored as if it were real.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
              <div>
                <p className="text-sm font-medium">Require a location for on-site punches</p>
                <p className="text-xs text-muted-foreground">
                  Applies to Office, Client Site and Field.
                </p>
              </div>
              <Switch
                checked={form.requireLocation}
                onCheckedChange={(v) => setForm((f) => ({ ...f, requireLocation: v }))}
                disabled={!canManage}
              />
            </div>

            <div className="space-y-1.5 sm:max-w-xs">
              <Label className="text-xs font-semibold">Required accuracy (metres)</Label>
              <Input
                type="number"
                min={1}
                value={form.minAccuracy}
                onChange={(e) => setForm((f) => ({ ...f, minAccuracy: e.target.value }))}
                disabled={!canManage || !form.requireLocation}
              />
              <p className="text-[11px] text-muted-foreground">
                100m suits most offices. Below ~20m is unreliable indoors.
              </p>
            </div>
          </CardContent>
        </Card>

        {/* Geofence */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <MapPin className="size-4 text-primary" /> Geofence
            </CardTitle>
            <CardDescription>
              Restrict punching to a physical area. Leave off to record locations without
              enforcing a boundary.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
              <div>
                <p className="text-sm font-medium">Enforce a location boundary</p>
                <p className="text-xs text-muted-foreground">Set a centre point and radius.</p>
              </div>
              <Switch
                checked={form.geofenceEnabled}
                onCheckedChange={(v) => setForm((f) => ({ ...f, geofenceEnabled: v }))}
                disabled={!canManage}
              />
            </div>

            {form.geofenceEnabled && (
              <>
                <GeofenceMapPicker
                  disabled={!canManage}
                  label={form.label || undefined}
                  value={{
                    latitude: form.lat === "" ? null : Number(form.lat),
                    longitude: form.lng === "" ? null : Number(form.lng),
                    radiusM: Number(form.radius) || 100,
                  }}
                  onChange={(next) =>
                    setForm((f) => ({
                      ...f,
                      lat: next.latitude == null ? "" : String(next.latitude),
                      lng: next.longitude == null ? "" : String(next.longitude),
                      radius: String(next.radiusM),
                    }))
                  }
                />

                <div className="space-y-1.5 sm:max-w-sm">
                  <Label className="text-xs font-semibold">Location name</Label>
                  <Input
                    value={form.label}
                    onChange={(e) => setForm((f) => ({ ...f, label: e.target.value }))}
                    placeholder="Head Office"
                    disabled={!canManage}
                  />
                </div>

                <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
                  <div>
                    <p className="text-sm font-medium">Block punches outside the boundary</p>
                    <p className="text-xs text-muted-foreground">
                      Off: the punch is recorded and flagged for you to review. On: it is refused.
                    </p>
                  </div>
                  <Switch
                    checked={form.blockOutside}
                    onCheckedChange={(v) => setForm((f) => ({ ...f, blockOutside: v }))}
                    disabled={!canManage}
                  />
                </div>
              </>
            )}
          </CardContent>
        </Card>

        {/* Punch out */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <ClipboardList className="size-4 text-primary" /> Punch-out process
            </CardTitle>
            <CardDescription>
              Choose whether punching out asks for a timesheet, and which questions it asks.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3">
              <div>
                <p className="text-sm font-medium">Ask for a timesheet on punch out</p>
                <p className="text-xs text-muted-foreground">
                  The form opens automatically once hours are logged.
                </p>
              </div>
              <Switch
                checked={form.requireTimesheet}
                onCheckedChange={(v) => setForm((f) => ({ ...f, requireTimesheet: v }))}
                disabled={!canManage}
              />
            </div>

            <div className="space-y-1.5 sm:max-w-md">
              <Label className="text-xs font-semibold">Timesheet template</Label>
              <Select
                value={form.timesheetTemplateId}
                onValueChange={(v) => setForm((f) => ({ ...f, timesheetTemplateId: v }))}
                disabled={!canManage || !form.requireTimesheet}
              >
                <SelectTrigger><SelectValue placeholder="Select a template…" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value={NONE}>None</SelectItem>
                  {templates.map((t) => (
                    <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-[11px] text-muted-foreground">
                A developer gets project and task fields; a salesperson gets CRM contacts and deals.
              </p>
            </div>
          </CardContent>
        </Card>

        {/* Day exceptions */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <CalendarPlus className="size-4 text-primary" /> Day exceptions
            </CardTitle>
            <CardDescription>
              One-off changes for a single person on a single date — for example letting someone
              work from home just for Thursday. These beat every other policy.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {canManage && (
              <div className="grid gap-3 rounded-lg border border-border p-3 sm:grid-cols-4">
                <div className="space-y-1.5 sm:col-span-2">
                  <Label className="text-xs font-semibold">Team member</Label>
                  <Select value={ovMemberId} onValueChange={setOvMemberId}>
                    <SelectTrigger><SelectValue placeholder="Select…" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value={NONE}>Select…</SelectItem>
                      {members.map((m) => (
                        <SelectItem key={m.id} value={m.id}>{m.label}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-semibold">Date</Label>
                  <Input type="date" value={ovDate} onChange={(e) => setOvDate(e.target.value)} />
                </div>
                <div className="flex items-end">
                  <IconAction label="Add" icon={savingOverride ? (
                      <Loader2 className="size-4 animate-spin" />
                    ) : (
                      <CalendarPlus className="size-4" />
                    )} onClick={handleAddOverride}
                    disabled={savingOverride}
                    className="w-full gap-1.5" />
                </div>

                <div className="flex items-center justify-between gap-4 rounded-lg border border-border p-3 sm:col-span-2">
                  <div>
                    <p className="text-sm font-medium">Allow working from home</p>
                    <p className="text-xs text-muted-foreground">No location needed that day.</p>
                  </div>
                  <Switch checked={ovAllowWfh} onCheckedChange={setOvAllowWfh} />
                </div>
                <div className="space-y-1.5 sm:col-span-2">
                  <Label className="text-xs font-semibold">Note (shown to the employee)</Label>
                  <Input
                    value={ovNote}
                    onChange={(e) => setOvNote(e.target.value)}
                    placeholder="Approved WFH — client visit cancelled"
                  />
                </div>
              </div>
            )}

            {overrides.length === 0 ? (
              <p className="py-4 text-center text-xs text-muted-foreground">
                No upcoming day exceptions.
              </p>
            ) : (
              <div className="divide-y divide-border rounded-lg border border-border">
                {overrides.map((o) => (
                  <div key={o.id} className="flex items-center justify-between gap-3 px-3 py-2">
                    <div className="min-w-0">
                      <p className="truncate text-sm font-medium">
                        {memberName(o.workspace_member_id)}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {o.override_date}
                        {o.allowed_work_locations?.includes("WFH") ? " · WFH allowed" : ""}
                        {o.note ? ` · ${o.note}` : ""}
                      </p>
                    </div>
                    {canManage && (
                      <IconAction
                        label="Delete"
                        icon={<Trash2 className="size-3.5" />}
                        variant="ghost"
                        onClick={() => handleDeleteOverride(o.id)}
                        className="text-muted-foreground hover:text-destructive"
                      />
                    )}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, startTransition } from "react";
import Script from "next/script";
import { PLANS, Plan } from "@/config/plans";
import { useWorkspace } from "@/hooks/use-workspace";
import { Check, AlertTriangle, ArrowRight, ShieldCheck, Loader2 } from "lucide-react";
import { toast } from "sonner";

interface WorkspaceUsage {
  planId: string;
  planName: string;
  memberCount: number;
  maxUsers: number;
  workspaceCount: number;
  maxWorkspaces: number;
  messageCount: number;
  monthlyMessageAllowance: number;
  isTrial: boolean;
  createdAt: string;
}

export function BillingPanel() {
  const { activeWorkspace, refreshWorkspaces, activeRole } = useWorkspace();
  const [usage, setUsage] = useState<WorkspaceUsage | null>(null);
  const [loading, setLoading] = useState(true);
  const [billingCycle, setBillingCycle] = useState<"monthly" | "annual">("monthly");
  const [isUpgrading, setIsUpgrading] = useState<string | null>(null);

  const fetchUsage = async () => {
    if (!activeWorkspace?.id) return;
    try {
      setLoading(true);
      const res = await fetch(`/api/workspace/usage?workspace_id=${activeWorkspace.id}`);
      if (res.ok) {
        const data = await res.json();
        setUsage(data);
      }
    } catch (err) {
      console.error("Failed to fetch billing usage:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsage();
  }, [activeWorkspace?.id]);

  const handleUpgrade = async (plan: Plan) => {
    if (!activeWorkspace?.id) return;
    if (activeRole !== "owner" && activeRole !== "admin") {
      toast.error("Only workspace owners or admins can modify the subscription plan.");
      return;
    }

    if (plan.id === "free") {
      toast.info("You are already on the Free Trial or have completed it.");
      return;
    }

    if (plan.id === "custom") {
      toast.info("For enterprise custom setups, please contact our sales team.");
      return;
    }

    const isAnnual = billingCycle === "annual";
    const price = isAnnual ? plan.priceYearly : plan.priceMonthly;
    const amountPaise = price * 100;

    try {
      setIsUpgrading(plan.id);
      toast.loading("Initializing secure payment order...");

      const orderRes = await fetch("/api/create-order", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          amount: amountPaise,
          currency: "INR",
          receipt: `rcpt_${activeWorkspace.id.substring(0, 10)}`,
        }),
      });

      const orderResult = await orderRes.json();
      toast.dismiss();

      if (!orderRes.ok || !orderResult.order_id) {
        throw new Error(orderResult.error || "Failed to initialize payment order.");
      }

      const options = {
        key: process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || "rzp_test_TEus8m7ilDoAio",
        amount: orderResult.amount,
        currency: orderResult.currency,
        name: "Daily CRM",
        description: `Upgrade to ${plan.name} Plan (${isAnnual ? "Annual" : "Monthly"})`,
        order_id: orderResult.order_id,
        handler: async function (response: any) {
          try {
            toast.loading("Verifying payment transaction...");
            const verifyRes = await fetch("/api/verify-payment", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_order_id: response.razorpay_order_id,
                razorpay_signature: response.razorpay_signature,
                workspace_id: activeWorkspace.id,
                plan_id: plan.id,
              }),
            });

            const verifyResult = await verifyRes.json();
            toast.dismiss();

            if (verifyRes.ok && verifyResult.success) {
              toast.success(`Success! Workspace upgraded to ${plan.name}.`);
              startTransition(() => {
                refreshWorkspaces();
                fetchUsage();
              });
            } else {
              toast.error(verifyResult.error || "Failed to verify transaction signature.");
            }
          } catch (err: any) {
            toast.dismiss();
            toast.error(err.message || "Payment verification failed.");
          }
        },
        prefill: {
          name: activeWorkspace.name,
        },
        theme: {
          color: "#0284C7",
        },
        modal: {
          ondismiss: function () {
            toast.error("Checkout cancelled.");
          },
        },
      };

      const rzp = new (window as any).Razorpay(options);
      rzp.open();
    } catch (err: any) {
      toast.dismiss();
      toast.error(err.message || "Checkout failed to initialize.");
    } finally {
      setIsUpgrading(null);
    }
  };

  if (loading && !usage) {
    return (
      <div className="flex h-[350px] items-center justify-center rounded-xl border border-border bg-card/20">
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="text-sm text-muted-foreground">Loading plan subscription details...</span>
        </div>
      </div>
    );
  }

  const currentPlan = PLANS.find((p) => p.id === usage?.planId) || PLANS[0];
  const totalMessages = usage?.messageCount || 0;
  const maxMessages = usage?.monthlyMessageAllowance || 500;
  const msgPercent = Math.min(Math.round((totalMessages / maxMessages) * 100), 100);

  const totalMembers = usage?.memberCount || 1;
  const maxMembers = usage?.maxUsers || 2;
  const membersPercent = Math.min(Math.round((totalMembers / maxMembers) * 100), 100);

  const totalWorkspaces = usage?.workspaceCount || 1;
  const maxWorkspaces = usage?.maxWorkspaces || 1;
  const workspacesPercent = Math.min(Math.round((totalWorkspaces / maxWorkspaces) * 100), 100);

  return (
    <div className="space-y-6">
      <Script src="https://checkout.razorpay.com/v1/checkout.js" strategy="lazyOnload" />

      {/* Current Plan Overview Banner */}
      <div className="relative rounded-2xl border border-primary/20 bg-gradient-to-br from-primary/5 via-slate-950/60 to-muted p-6 shadow-xl">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="rounded-full bg-primary/15 px-3 py-1 text-xs font-semibold text-primary">
                Active Plan
              </span>
              {usage?.isTrial && (
                <span className="rounded-full bg-amber-500/10 px-3 py-1 text-xs font-semibold text-amber-500 flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" /> 14-day Trial
                </span>
              )}
            </div>
            <h2 className="mt-2 text-lg font-black text-foreground">{currentPlan.name} Tier</h2>
            <p className="mt-1 text-xs text-muted-foreground">
              Workspace subscription handles routing and resource quotas for your team.
            </p>
          </div>
          <div className="text-left sm:text-right">
            <span className="text-xs text-muted-foreground block">Pricing Plan Cost</span>
            <span className="text-2xl font-black text-foreground">
              {currentPlan.priceMonthly === 0 ? "₹0" : currentPlan.priceMonthly === -1 ? "Custom" : `₹${currentPlan.priceMonthly.toLocaleString()}/mo`}
            </span>
            <span className="text-[10px] text-muted-foreground block">excl. GST</span>
          </div>
        </div>
      </div>

      {/* Plan Usage Limits Progress Meters */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Outbound messages */}
        <div className="rounded-xl border border-border bg-background/40 p-5">
          <div className="flex justify-between items-start mb-2">
            <div>
              <span className="text-xs text-muted-foreground font-semibold block">Monthly Messages</span>
              <span className="text-lg font-black text-foreground">
                {totalMessages.toLocaleString()} / {maxMessages === 999999 ? "∞" : maxMessages.toLocaleString()}
              </span>
            </div>
            {msgPercent >= 80 && (
              <span className={`px-2 py-0.5 rounded-none text-[10px] font-bold ${msgPercent >= 100 ? "bg-red-500/15 text-red-500" : "bg-amber-500/15 text-amber-500"}`}>
                {msgPercent >= 100 ? "Limit Reached" : "80% Warning"}
              </span>
            )}
          </div>
          <div className="w-full bg-card rounded-full h-2">
            <div
              className={`h-2 rounded-full transition-all duration-500 ${
                msgPercent >= 100 ? "bg-red-500" : msgPercent >= 80 ? "bg-amber-500" : "bg-primary"
              }`}
              style={{ width: `${msgPercent}%` }}
            />
          </div>
          <span className="text-[10px] text-muted-foreground block mt-2">
            {usage?.isTrial ? "Allowance covers trial period." : "Resets monthly on 1st."} WhatsApp template charges separate.
          </span>
        </div>

        {/* Team Members */}
        <div className="rounded-xl border border-border bg-background/40 p-5">
          <div className="flex justify-between items-start mb-2">
            <div>
              <span className="text-xs text-muted-foreground font-semibold block">Team Members</span>
              <span className="text-lg font-black text-foreground">
                {totalMembers} / {maxMembers === 999999 ? "Unlimited" : maxMembers}
              </span>
            </div>
            {membersPercent >= 100 && maxMembers !== 999999 && (
              <span className="px-2 py-0.5 rounded-none text-[10px] font-bold bg-amber-500/15 text-amber-500">
                Max Users
              </span>
            )}
          </div>
          <div className="w-full bg-card rounded-full h-2">
            <div
              className="h-2 rounded-full bg-primary transition-all duration-500"
              style={{ width: `${maxMembers === 999999 ? 100 : membersPercent}%` }}
            />
          </div>
          <span className="text-[10px] text-muted-foreground block mt-2">
            Max members allowed to join this workspace.
          </span>
        </div>

        {/* Workspaces */}
        <div className="rounded-xl border border-border bg-background/40 p-5">
          <div className="flex justify-between items-start mb-2">
            <div>
              <span className="text-xs text-muted-foreground font-semibold block">Workspaces</span>
              <span className="text-lg font-black text-foreground">
                {totalWorkspaces} / {maxWorkspaces === 999999 ? "Unlimited" : maxWorkspaces}
              </span>
            </div>
            {workspacesPercent >= 100 && maxWorkspaces !== 999999 && (
              <span className="px-2 py-0.5 rounded-none text-[10px] font-bold bg-amber-500/15 text-amber-500">
                Limit Reached
              </span>
            )}
          </div>
          <div className="w-full bg-card rounded-full h-2">
            <div
              className="h-2 rounded-full bg-primary transition-all duration-500"
              style={{ width: `${maxWorkspaces === 999999 ? 100 : workspacesPercent}%` }}
            />
          </div>
          <span className="text-[10px] text-muted-foreground block mt-2">
            Number of team workspaces you can build.
          </span>
        </div>
      </div>

      {/* Upgrade Options Section */}
      <div className="border-t border-border/60 pt-8">
        <div className="text-center mb-6">
          <h3 className="text-lg font-extrabold text-foreground">Upgrade Workspace Plan</h3>
          <p className="text-muted-foreground text-xs mt-1">Unlock larger allowances and multi-agent automations.</p>

          {/* Pricing Toggle */}
          <div className="flex items-center justify-center gap-3 mt-4">
            <button
              type="button"
              onClick={() => setBillingCycle("monthly")}
              className={`px-3 py-1.5 text-xs font-semibold rounded-lg transition-colors ${
                billingCycle === "monthly"
                  ? "bg-primary text-primary-foreground"
                  : "text-muted-foreground hover:text-foreground bg-card border border-border"
              }`}
            >
              Monthly
            </button>
            <button
              type="button"
              onClick={() => setBillingCycle("annual")}
              className={`px-3 py-1.5 text-xs font-semibold rounded-lg transition-colors relative ${
                billingCycle === "annual"
                  ? "bg-primary text-primary-foreground"
                  : "text-muted-foreground hover:text-foreground bg-card border border-border"
              }`}
            >
              Annual
              <span className="absolute -top-3 -right-6 px-1.5 py-0.5 bg-emerald-500 text-foreground text-[8px] font-bold rounded-full uppercase tracking-wider scale-90">
                2 Months Free
              </span>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {PLANS.filter((p) => p.id !== "free").map((plan) => {
            const isCurrent = usage?.planId === plan.id;
            const isCustom = plan.id === "custom";
            const isAnnual = billingCycle === "annual";
            const price = isCustom
              ? "Custom"
              : isAnnual
              ? `₹${plan.priceYearly.toLocaleString()}`
              : `₹${plan.priceMonthly.toLocaleString()}`;
            const periodLabel = isCustom ? "" : isAnnual ? "/yr" : "/mo";

            return (
              <div
                key={plan.id}
                className={`relative flex flex-col rounded-xl p-5 border transition-all ${
                  isCurrent
                    ? "border-primary bg-primary/5"
                    : "border-border bg-card/20 hover:border-border"
                }`}
              >
                {plan.isRecommended && (
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2 px-2.5 py-0.5 bg-primary text-primary-foreground text-[9px] font-bold rounded-full">
                    RECOMMENDED
                  </div>
                )}

                <div className="mb-4">
                  <span className="text-sm font-extrabold text-foreground">{plan.name}</span>
                  <div className="flex items-baseline gap-1 mt-1">
                    <span className="text-xl font-black text-foreground">{price}</span>
                    <span className="text-muted-foreground text-[10px]">{periodLabel}</span>
                  </div>
                  {!isCustom && (
                    <span className="text-[9px] text-muted-foreground block">
                      {isAnnual
                        ? `Equivalent to ₹${Math.round(plan.priceYearly / 12).toLocaleString()}/mo`
                        : `Equivalent to ₹${(plan.priceMonthly * 12).toLocaleString()}/yr`}
                      {" (excl. GST)"}
                    </span>
                  )}
                </div>

                <ul className="space-y-1.5 mb-6 flex-1">
                  {plan.features.slice(0, 4).map((f) => (
                    <li key={f} className="flex items-start gap-1.5 text-[11px] text-foreground">
                      <Check className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                      <span>{f}</span>
                    </li>
                  ))}
                </ul>

                <button
                  type="button"
                  disabled={isCurrent || isUpgrading !== null}
                  onClick={() => handleUpgrade(plan)}
                  className={`w-full flex items-center justify-center gap-1.5 rounded-lg py-2 text-xs font-bold transition-all ${
                    isCurrent
                      ? "bg-muted text-muted-foreground cursor-default"
                      : plan.isRecommended
                      ? "bg-primary text-primary-foreground hover:bg-primary-hover"
                      : "border border-border text-foreground hover:border-border hover:text-foreground"
                  }`}
                >
                  {isCurrent ? (
                    <>
                      <ShieldCheck className="h-3.5 w-3.5" /> Current Plan
                    </>
                  ) : isUpgrading === plan.id ? (
                    <>
                      <Loader2 className="h-3.5 w-3.5 animate-spin" /> Upgrading...
                    </>
                  ) : isCustom ? (
                    "Contact Sales"
                  ) : (
                    <>
                      Upgrade Now <ArrowRight className="h-3.5 w-3.5" />
                    </>
                  )}
                </button>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { assertAffected } from "@/lib/supabase/affected-rows";
import {
  Upload,
  Trash2,
  Loader2,
  Building2,
  Globe,
  Mail,
  Phone,
  MapPin,
  ImageIcon,
  Sparkles,
} from "lucide-react";

import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/hooks/use-auth";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { SettingsPanelHead } from "./settings-panel-head";
import { IconAction } from "@/components/ui/icon-action";

const MAX_LOGO_BYTES = 3 * 1024 * 1024; // 3 MB
const ALLOWED_MIME = new Set(["image/png", "image/jpeg", "image/webp", "image/svg+xml"]);

interface BrandingData {
  logo_url: string | null;
  company_name: string | null;
  company_tagline: string | null;
  company_email: string | null;
  company_phone: string | null;
  company_website: string | null;
  company_address: string | null;
}

export function BrandingSettings() {
  const supabase = createClient();
  const { accountId, canEditSettings } = useAuth();
  const { activeWorkspace, refreshWorkspaces } = useWorkspace();
  const workspaceId = activeWorkspace?.id || accountId;

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploadingLogo, setUploadingLogo] = useState(false);

  const [data, setData] = useState<BrandingData>({
    logo_url: null,
    company_name: null,
    company_tagline: null,
    company_email: null,
    company_phone: null,
    company_website: null,
    company_address: null,
  });

  // Pending logo state (before save)
  const [pendingLogo, setPendingLogo] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [removeLogo, setRemoveLogo] = useState(false);

  const currentLogoUrl = previewUrl ?? (!removeLogo ? data.logo_url : null);

  // Fetch branding from workspaces table
  const fetchBranding = async () => {
    if (!workspaceId) return;
    setLoading(true);
    try {
      const { data: ws, error } = await supabase
        .from("workspaces")
        .select(
          "logo_url, company_name, company_tagline, company_email, company_phone, company_website, company_address"
        )
        .eq("id", workspaceId)
        .single();

      if (error) throw error;
      if (ws) setData(ws as BrandingData);
    } catch (err: any) {
      console.error("Failed to load branding:", err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (workspaceId) fetchBranding();
    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [workspaceId]);

  const onPickFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;

    if (!ALLOWED_MIME.has(file.type)) {
      toast.error("Unsupported format. Use PNG, JPG, WebP, or SVG.");
      return;
    }
    if (file.size > MAX_LOGO_BYTES) {
      toast.error("Logo is too large. Maximum 3 MB.");
      return;
    }

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPendingLogo(file);
    setPreviewUrl(URL.createObjectURL(file));
    setRemoveLogo(false);
  };

  const onRemoveLogo = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPendingLogo(null);
    setPreviewUrl(null);
    setRemoveLogo(true);
  };

  const handleSave = async () => {
    if (!workspaceId) return;
    setSaving(true);

    try {
      let nextLogoUrl: string | null = data.logo_url;
      let logoError: string | null = null;

      if (pendingLogo) {
        setUploadingLogo(true);
        const ext = pendingLogo.name.split(".").pop()?.toLowerCase() || "png";
        // Must live under `workspace-logos/{workspace_id}/`: migration 095
        // scopes the storage policy to that prefix. The old path was
        // `{workspace_id}/...`, which the avatars policy from 008 rejected
        // because it requires the FIRST folder to be the uploader's user id
        // — so every logo upload failed with an RLS violation.
        const path = `workspace-logos/${workspaceId}/logo-${Date.now()}.${ext}`;

        const { error: uploadErr } = await supabase.storage
          .from("avatars") // public bucket, shared with avatars
          .upload(path, pendingLogo, {
            cacheControl: "86400",
            upsert: true,
            contentType: pendingLogo.type,
          });

        if (uploadErr) {
          // Recorded, NOT thrown. Throwing here skipped the workspaces
          // update entirely, so a storage problem silently discarded the
          // company name, address, phone and website too — which is why the
          // whole panel appeared not to save.
          logoError = uploadErr.message;
        } else {
          const { data: { publicUrl } } = supabase.storage
            .from("avatars")
            .getPublicUrl(path);
          nextLogoUrl = publicUrl;
        }
        setUploadingLogo(false);
      } else if (removeLogo) {
        nextLogoUrl = null;
      }

      // .select() so a zero-row update is caught. Without it an RLS
      // denial returns { error: null }, the toast said "saved!" and
      // nothing had been written — which is what "doesn't save up" looks
      // like from the outside.
      const result = await supabase
        .from("workspaces")
        .update({
          logo_url: nextLogoUrl,
          company_name: data.company_name?.trim() || null,
          company_tagline: data.company_tagline?.trim() || null,
          company_email: data.company_email?.trim() || null,
          company_phone: data.company_phone?.trim() || null,
          company_website: data.company_website?.trim() || null,
          company_address: data.company_address?.trim() || null,
          updated_at: new Date().toISOString(),
        })
        .eq("id", workspaceId)
        .select("id");

      assertAffected(result, "your company branding", "save");

      setData((prev) => ({ ...prev, logo_url: nextLogoUrl }));
      if (!logoError) {
        setPendingLogo(null);
        setPreviewUrl(null);
        setRemoveLogo(false);
      }
      if (logoError) {
        // The details did save; only the image did not. Say exactly that.
        toast.warning(
          `Company details saved, but the logo could not be uploaded: ${logoError}`
        );
      } else {
        toast.success("Company branding saved.");
      }
      // The sidebar logo and the letterhead both read the workspace from
      // context, which is cached — without this the save appears to have
      // done nothing until a manual reload.
      await refreshWorkspaces?.();
    } catch (err: any) {
      toast.error(err.message || "Failed to save branding");
    } finally {
      setSaving(false);
      setUploadingLogo(false);
    }
  };

  const field = (
    key: keyof Omit<BrandingData, "logo_url">,
    value: string
  ) => setData((prev) => ({ ...prev, [key]: value }));

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="size-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <section className="space-y-6 max-w-3xl animate-in fade-in-50 duration-200">
      <SettingsPanelHead
        title="Company Branding"
        description="Upload your company logo and fill in contact details. These appear on all generated quotations and proposals."
      />

      {/* Logo Card */}
      <Card className="border-border bg-card">
        <CardHeader className="border-b border-border/40 pb-4">
          <CardTitle className="flex items-center gap-2 text-foreground">
            <ImageIcon className="size-4 text-primary" />
            Company Logo
          </CardTitle>
          <CardDescription>
            Appears in the header of every quotation PDF. PNG, JPG, WebP or SVG — max 3 MB.
            Recommended dimensions: 300×100 px or similar wide format.
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-5">
          <div className="flex flex-col sm:flex-row items-start gap-6">
            {/* Logo Preview */}
            <div className="flex-shrink-0 w-48 h-20 rounded-lg border border-border bg-muted/40 flex items-center justify-center overflow-hidden">
              {currentLogoUrl ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={currentLogoUrl}
                  alt="Company logo"
                  className="max-w-full max-h-full object-contain p-2"
                />
              ) : (
                <div className="flex flex-col items-center gap-1 text-muted-foreground">
                  <Sparkles className="size-6 opacity-40" />
                  <span className="text-[10px] text-center px-2">No logo uploaded</span>
                </div>
              )}
            </div>

            {/* Upload Actions */}
            <div className="space-y-3">
              <input
                ref={fileInputRef}
                type="file"
                accept="image/png,image/jpeg,image/webp,image/svg+xml"
                className="hidden"
                onChange={onPickFile}
                disabled={!canEditSettings || saving}
              />
              <div className="flex flex-wrap gap-2">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={!canEditSettings || saving}
                  className="border-border bg-transparent"
                >
                  <Upload className="size-3.5 mr-1.5" />
                  {currentLogoUrl ? "Change Logo" : "Upload Logo"}
                </Button>
                {currentLogoUrl && (
                  <IconAction label="Remove" icon={<Trash2 className="size-3.5 " />} type="button"
                    variant="ghost"
                    onClick={onRemoveLogo}
                    disabled={!canEditSettings || saving}
                    className="text-muted-foreground hover:text-red-400" />
                )}
              </div>
              {pendingLogo && (
                <p className="text-xs text-primary">
                  ✓ {pendingLogo.name} staged — click &quot;Save Branding&quot; to apply.
                </p>
              )}
              {!canEditSettings && (
                <p className="text-xs text-muted-foreground">
                  Admin or owner role required to change branding.
                </p>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Company Info Card */}
      <Card className="border-border bg-card">
        <CardHeader className="border-b border-border/40 pb-4">
          <CardTitle className="flex items-center gap-2 text-foreground">
            <Building2 className="size-4 text-primary" />
            Company Details
          </CardTitle>
          <CardDescription>
            These details appear in the quotation header alongside your logo.
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-5 space-y-4">
          <div className="grid sm:grid-cols-2 gap-4">
            {/* Company Name */}
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground flex items-center gap-1.5">
                <Building2 className="size-3" /> Company Name
              </Label>
              <Input
                value={data.company_name ?? ""}
                onChange={(e) => field("company_name", e.target.value)}
                placeholder="e.g. Daylink Tech Labs"
                disabled={!canEditSettings || saving}
                className="bg-muted border-border text-foreground h-9"
              />
            </div>

            {/* Tagline */}
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground flex items-center gap-1.5">
                <Sparkles className="size-3" /> Tagline / Subtitle
              </Label>
              <Input
                value={data.company_tagline ?? ""}
                onChange={(e) => field("company_tagline", e.target.value)}
                placeholder="e.g. Custom Software & Systems"
                disabled={!canEditSettings || saving}
                className="bg-muted border-border text-foreground h-9"
              />
            </div>

            {/* Email */}
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground flex items-center gap-1.5">
                <Mail className="size-3" /> Business Email
              </Label>
              <Input
                type="email"
                value={data.company_email ?? ""}
                onChange={(e) => field("company_email", e.target.value)}
                placeholder="contact@yourcompany.com"
                disabled={!canEditSettings || saving}
                className="bg-muted border-border text-foreground h-9"
              />
            </div>

            {/* Phone */}
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground flex items-center gap-1.5">
                <Phone className="size-3" /> Business Phone
              </Label>
              <Input
                value={data.company_phone ?? ""}
                onChange={(e) => field("company_phone", e.target.value)}
                placeholder="+91 98765 43210"
                disabled={!canEditSettings || saving}
                className="bg-muted border-border text-foreground h-9"
              />
            </div>

            {/* Website */}
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground flex items-center gap-1.5">
                <Globe className="size-3" /> Website
              </Label>
              <Input
                value={data.company_website ?? ""}
                onChange={(e) => field("company_website", e.target.value)}
                placeholder="https://yourcompany.com"
                disabled={!canEditSettings || saving}
                className="bg-muted border-border text-foreground h-9"
              />
            </div>

            {/* Address */}
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground flex items-center gap-1.5">
                <MapPin className="size-3" /> Address
              </Label>
              <Input
                value={data.company_address ?? ""}
                onChange={(e) => field("company_address", e.target.value)}
                placeholder="123 Main St, City, Country"
                disabled={!canEditSettings || saving}
                className="bg-muted border-border text-foreground h-9"
              />
            </div>
          </div>

          {canEditSettings && (
            <div className="pt-2 flex justify-end">
              <Button
                onClick={handleSave}
                disabled={saving}
                className="bg-primary text-primary-foreground hover:bg-primary/95"
              >
                {saving ? (
                  <>
                    <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                    {uploadingLogo ? "Uploading logo..." : "Saving..."}
                  </>
                ) : (
                  "Save Branding"
                )}
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Live Preview */}
      <Card className="border-border bg-card">
        <CardHeader className="border-b border-border/40 pb-4">
          <CardTitle className="text-sm text-foreground flex items-center gap-2">
            <Sparkles className="size-4 text-primary" />
            Quotation Header Preview
          </CardTitle>
          <CardDescription>
            How your branding will look on generated proposals.
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-5">
          <div className="rounded-lg border border-border bg-card text-card-foreground p-8 flex flex-col items-center justify-center text-center pb-6 border-b-4 border-b-primary shadow-sm">
            {currentLogoUrl ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={currentLogoUrl}
                alt="Logo preview"
                className="h-20 sm:h-28 max-w-[280px] object-contain mb-2"
              />
            ) : (
                <h1 className="text-xl sm:text-lg font-serif font-semibold text-foreground uppercase tracking-wide mb-1">
                  {data.company_name?.toUpperCase() || "YOUR COMPANY"}
                </h1>
            )}

            {data.company_tagline && (
              <p className="text-base text-primary font-medium mb-2">
                {data.company_tagline}
              </p>
            )}

            <div className="text-xs text-muted-foreground space-y-1">
              {data.company_address && <p>{data.company_address}</p>}
              <p className="flex items-center justify-center gap-2">
                {data.company_phone && <span>{data.company_phone}</span>}
                {data.company_phone && data.company_email && <span>|</span>}
                {data.company_email && <span>{data.company_email}</span>}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </section>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { toast } from "sonner";
import {
  FileSpreadsheet,
  Plus,
  Search,
  Edit2,
  Trash2,
  Loader2,
  FileText,
  Layers,
} from "lucide-react";
import { formatCurrency, getCurrencySymbol } from "@/lib/currency";

import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/hooks/use-auth";
import { useWorkspace } from "@/hooks/use-workspace";
import type { ServiceCatalogItem } from "@/types";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { SettingsPanelHead } from "./settings-panel-head";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { IconAction } from "@/components/ui/icon-action";

export function CatalogSettings() {
  const supabase = createClient();
  const { accountId, canEditSettings } = useAuth();
  const { activeWorkspace, defaultCurrency } = useWorkspace();
  const workspaceId = activeWorkspace?.id || accountId;

  // State for Catalog Items
  const [items, setItems] = useState<ServiceCatalogItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  // State for adding/editing item
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<ServiceCatalogItem | null>(null);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("0");
  const [pricingType, setPricingType] = useState<"one_time" | "monthly" | "yearly">("one_time");
  const [category, setCategory] = useState("");
  const [submitting, setSubmitting] = useState(false);

  // State for default terms
  const [terms, setTerms] = useState("");
  const [termsLoading, setTermsLoading] = useState(true);
  const [termsSaving, setTermsSaving] = useState(false);

  // Fetch Service Catalog Items
  const fetchItems = async () => {
    if (!workspaceId) return;
    try {
      const { data, error } = await supabase
        .from("service_catalog")
        .select("*")
        .eq("workspace_id", workspaceId)
        .eq("is_active", true)
        .order("category", { ascending: true })
        .order("name", { ascending: true });

      if (error) throw error;
      setItems(data || []);
    } catch (err: any) {
      console.error("Error fetching catalog:", err.message);
      toast.error("Failed to load service catalog");
    } finally {
      setLoading(false);
    }
  };

  // Fetch Default Terms from Workspace
  const fetchTerms = async () => {
    if (!workspaceId) return;
    try {
      const { data, error } = await supabase
        .from("workspaces")
        .select("default_quotation_terms")
        .eq("id", workspaceId)
        .single();

      if (error) throw error;
      setTerms(data?.default_quotation_terms || "");
    } catch (err: any) {
      console.error("Error fetching terms:", err.message);
    } finally {
      setTermsLoading(false);
    }
  };

  useEffect(() => {
    if (workspaceId) {
      fetchItems();
      fetchTerms();
    }
  }, [workspaceId]);

  // Categories list for filtering
  const categories = useMemo(() => {
    const cats = new Set<string>();
    items.forEach((item) => {
      if (item.category) cats.add(item.category);
    });
    return Array.from(cats);
  }, [items]);

  // Filtered items
  const filteredItems = useMemo(() => {
    return items.filter((item) => {
      const matchesSearch =
        item.name.toLowerCase().includes(search.toLowerCase()) ||
        (item.default_description || "").toLowerCase().includes(search.toLowerCase());
      const matchesCategory =
        selectedCategory === "all" || item.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }, [items, search, selectedCategory]);

  const handleOpenAdd = () => {
    setEditingItem(null);
    setName("");
    setDescription("");
    setPrice("0");
    setPricingType("one_time");
    setCategory("");
    setDialogOpen(true);
  };

  const handleOpenEdit = (item: ServiceCatalogItem) => {
    setEditingItem(item);
    setName(item.name);
    setDescription(item.default_description || "");
    setPrice(item.default_price.toString());
    setPricingType(item.default_pricing_type);
    setCategory(item.category || "");
    setDialogOpen(true);
  };

  const handleSubmitItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!workspaceId || !name.trim()) return;

    setSubmitting(true);
    const numPrice = parseFloat(price) || 0;

    const payload = {
      workspace_id: workspaceId,
      name: name.trim(),
      default_description: description.trim() || null,
      default_price: numPrice,
      default_pricing_type: pricingType,
      category: category.trim() || null,
      is_active: true,
    };

    try {
      if (editingItem) {
        const { error } = await supabase
          .from("service_catalog")
          .update(payload)
          .eq("id", editingItem.id);

        if (error) throw error;
        toast.success("Catalog item updated");
      } else {
        const { error } = await supabase
          .from("service_catalog")
          .insert(payload);

        if (error) throw error;
        toast.success("Catalog item created");
      }

      setDialogOpen(false);
      fetchItems();
    } catch (err: any) {
      toast.error(err.message || "Failed to save item");
    } finally {
      setSubmitting(false);
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (!confirm("Are you sure you want to deactivate this item?")) return;
    try {
      // Soft delete by setting is_active to false
      const { error } = await supabase
        .from("service_catalog")
        .update({ is_active: false })
        .eq("id", id);

      if (error) throw error;
      toast.success("Catalog item removed");
      fetchItems();
    } catch (err: any) {
      toast.error(err.message || "Failed to remove item");
    }
  };

  const handleSaveTerms = async () => {
    if (!workspaceId) return;
    setTermsSaving(true);
    try {
      const { error } = await supabase
        .from("workspaces")
        .update({ default_quotation_terms: terms })
        .eq("id", workspaceId);

      if (error) throw error;
      toast.success("Default quotation terms saved");
    } catch {
      toast.error("Failed to save terms");
    } finally {
      setTermsSaving(false);
    }
  };

  const pricingLabels = {
    one_time: "One-time",
    monthly: "Monthly Recurring",
    yearly: "Yearly Recurring",
  };

  return (
    <section className="space-y-6 max-w-4xl animate-in fade-in-50 duration-200">
      <SettingsPanelHead
        title="Service Catalog & Quotation Settings"
        description="Define standard products/services and the default notes template used for new quotes."
      />

      <div className="grid gap-6">
        {/* Service Catalog Panel */}
        <Card className="border-border bg-card">
          <CardHeader className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pb-4 border-b border-border/40">
            <div>
              <CardTitle className="flex items-center gap-2 text-foreground">
                <FileSpreadsheet className="size-4 text-primary" />
                Service Catalog
              </CardTitle>
              <CardDescription>
                Add pre-configured products and services to copy directly into quotations.
              </CardDescription>
            </div>
            {canEditSettings && (
              <IconAction label="Add Item" icon={<Plus className="size-4" />} onClick={handleOpenAdd} className="bg-primary text-primary-foreground" />
            )}
          </CardHeader>
          <CardContent className="pt-4 space-y-4">
            {/* Search and Category Filters */}
            <div className="flex flex-col sm:flex-row gap-2">
              <div className="relative flex-1">
                <Search className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" />
                <Input
                  placeholder="Search catalog..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="pl-8 bg-muted border-border"
                />
              </div>
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="h-9 rounded-lg border border-border bg-muted px-2 text-sm text-foreground outline-none focus:border-primary"
              >
                <option value="all">All Categories</option>
                {categories.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>

            {/* List */}
            {loading ? (
              <div className="flex justify-center py-8">
                <Loader2 className="size-6 animate-spin text-muted-foreground" />
              </div>
            ) : filteredItems.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground text-sm border border-dashed border-border rounded-lg">
                No catalog items found.
              </div>
            ) : (
              <div className="border border-border rounded-lg overflow-hidden divide-y divide-border/60">
                {filteredItems.map((item) => (
                  <div key={item.id} className="p-4 flex items-start justify-between gap-4 hover:bg-muted/30 transition-colors">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2">
                        <span className="font-medium text-sm text-foreground">{item.name}</span>
                        {item.category && (
                          <span className="inline-flex items-center rounded-md bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground border border-border/50">
                            {item.category}
                          </span>
                        )}
                        <span className="inline-flex items-center rounded-md bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary">
                          {pricingLabels[item.default_pricing_type]}
                        </span>
                      </div>
                      {item.default_description && (
                        <p className="text-xs text-muted-foreground max-w-2xl line-clamp-2">
                          {item.default_description}
                        </p>
                      )}
                      <p className="text-xs font-semibold text-foreground">
                        {formatCurrency(item.default_price, defaultCurrency, { decimals: 2 })}
                      </p>
                    </div>
                    {canEditSettings && (
                      <div className="flex items-center gap-1 shrink-0">
                        <IconAction
                          label="Edit"
                          icon={<Edit2 className="size-3.5" />}
                          variant="ghost"
                          onClick={() => handleOpenEdit(item)}
                          className="h-8 w-8 text-muted-foreground hover:text-foreground"
                        />
                        <IconAction
                          label="Delete"
                          icon={<Trash2 className="size-3.5" />}
                          variant="ghost"
                          onClick={() => handleDeleteItem(item.id)}
                          className="h-8 w-8 text-muted-foreground hover:text-red-400"
                        />
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Default Quotation Terms */}
        <Card className="border-border bg-card">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-foreground">
              <FileText className="size-4 text-primary" />
              Default Notes & Terms
            </CardTitle>
            <CardDescription>
              This standard contract text pre-populates every new quotation. You can modify it per-quote in the builder.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {termsLoading ? (
              <div className="flex justify-center py-4">
                <Loader2 className="size-5 animate-spin text-muted-foreground" />
              </div>
            ) : (
              <div className="grid gap-4">
                <Textarea plain
                  value={terms}
                  onChange={(e) => setTerms(e.target.value)}
                  disabled={!canEditSettings}
                  rows={6}
                  placeholder="Enter notes, delivery schedules, tax clauses, payment milestones, etc."
                  className="bg-muted border-border font-mono text-xs text-foreground focus-visible:ring-primary"
                />
                {canEditSettings && (
                  <Button
                    onClick={handleSaveTerms}
                    disabled={termsSaving}
                    className="w-fit bg-primary text-primary-foreground hover:bg-primary/95"
                  >
                    {termsSaving ? (
                      <>
                        <Loader2 className="mr-1.5 size-4 animate-spin" /> Saving...
                      </>
                    ) : (
                      "Save Terms"
                    )}
                  </Button>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Add/Edit Catalog Item Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="border-border bg-popover text-popover-foreground max-w-md">
          <DialogHeader>
            <DialogTitle>
              {editingItem ? "Edit Catalog Item" : "Add Catalog Item"}
            </DialogTitle>
            <DialogDescription>
              Define catalog product properties. Quotations copy these values directly upon insertion.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmitItem} className="space-y-4 pt-2">
            <div className="grid gap-2">
              <Label htmlFor="item-name">Name</Label>
              <Input
                id="item-name"
                required
                placeholder="e.g. Premium Support Tier"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="bg-muted border-border"
              />
            </div>

            <div className="grid gap-2">
              <Label htmlFor="item-desc">Description</Label>
              <Textarea plain
                id="item-desc"
                placeholder="Product description detail..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="bg-muted border-border"
                rows={3}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="grid gap-2">
                <Label htmlFor="item-price">Default Price</Label>
                <div className="relative">
                  <span className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">
                    {getCurrencySymbol(defaultCurrency)}
                  </span>
                  <Input
                    id="item-price"
                    type="number"
                    step="0.01"
                    min="0"
                    placeholder="0.00"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    className="pl-8 bg-muted border-border"
                  />
                </div>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="item-type">Pricing Type</Label>
                <select
                  id="item-type"
                  value={pricingType}
                  onChange={(e) => setPricingType(e.target.value as any)}
                  className="h-9 w-full rounded-lg border border-border bg-muted px-2.5 text-sm outline-none focus:border-primary"
                >
                  <option value="one_time">One-time</option>
                  <option value="monthly">Monthly</option>
                  <option value="yearly">Yearly</option>
                </select>
              </div>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="item-cat">Category</Label>
              <div className="relative">
                <Layers className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" />
                <Input
                  id="item-cat"
                  placeholder="e.g. Services, Software, Hardware"
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                  className="pl-8 bg-muted border-border"
                />
              </div>
            </div>

            <DialogFooter className="pt-4 border-t border-border/40">
              <Button
                type="button"
                variant="outline"
                onClick={() => setDialogOpen(false)}
                className="border-border bg-transparent text-muted-foreground hover:bg-muted"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={submitting || !name.trim()}
                className="bg-primary text-primary-foreground hover:bg-primary/95"
              >
                {submitting ? (
                  <>
                    <Loader2 className="mr-1.5 size-4 animate-spin" /> Saving...
                  </>
                ) : (
                  "Save Item"
                )}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </section>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { toast } from "sonner";
import {
  Loader2,
  Eye,
  EyeOff,
  Bot,
  Sparkles,
  Zap,
  RotateCcw,
  BookOpen,
  Sliders,
  ShieldCheck,
} from "lucide-react";
import { useAuth } from "@/hooks/use-auth";
import { useWorkspace } from "@/hooks/use-workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const MASKED_KEY = "••••••••••••••••••••••••••••••••";

type AIProvider = "openai" | "gemini" | "anthropic" | "grok" | "groq";

interface ChatbotConfigPayload {
  is_enabled: boolean;
  provider: AIProvider;
  model: string;
  system_prompt: string;
  business_context: string;
  auto_pause_duration: number;
  response_delay: number;
  bot_name: string;
  api_key_configured: boolean;
}

export function ChatbotConfig() {
  const { user, loading: authLoading } = useAuth();
  const { activeWorkspace } = useWorkspace();

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [resetting, setResetting] = useState(false);
  const [showKey, setShowKey] = useState(false);

  // Chatbot State Fields
  const [isEnabled, setIsEnabled] = useState(false);
  const [provider, setProvider] = useState<AIProvider>("groq");
  const [model, setModel] = useState("llama-3.3-70b-versatile");
  const [apiKey, setApiKey] = useState("");
  const [systemPrompt, setSystemPrompt] = useState(
    "You are a helpful customer service assistant for our business."
  );
  const [businessContext, setBusinessContext] = useState("");
  const [autoPauseDuration, setAutoPauseDuration] = useState("60"); // in minutes, "0" = off, "-1" = permanent
  const [responseDelay, setResponseDelay] = useState("0"); // in seconds
  const [botName, setBotName] = useState("AI Assistant");

  // Track key status
  const [hasConfig, setHasConfig] = useState(false);
  const [apiKeyConfigured, setApiKeyConfigured] = useState(false);
  const [keyEdited, setKeyEdited] = useState(false);

  // Set default model on provider change
  const handleProviderChange = (newProvider: AIProvider) => {
    setProvider(newProvider);
    if (newProvider === "openai") {
      setModel("gpt-4o-mini");
    } else if (newProvider === "grok") {
      setModel("grok-2-1212");
    } else if (newProvider === "groq") {
      setModel("llama-3.3-70b-versatile");
    } else if (newProvider === "gemini") {
      setModel("gemini-1.5-flash");
    } else if (newProvider === "anthropic") {
      setModel("claude-3-5-haiku-20241022");
    }
  };

  const fetchConfig = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/whatsapp/chatbot-config?workspace_id=${activeWorkspace.id}`);
      if (!res.ok) {
        throw new Error("Failed to load config");
      }
      const data: ChatbotConfigPayload = await res.json();

      setIsEnabled(data.is_enabled);
      setProvider(data.provider || "groq");
      setModel(data.model || "gpt-4o-mini");
      setSystemPrompt(data.system_prompt || "You are a helpful customer service assistant for our business.");
      setBusinessContext(data.business_context || "");
      setAutoPauseDuration(data.auto_pause_duration !== undefined && data.auto_pause_duration !== null ? String(data.auto_pause_duration) : "60");
      setResponseDelay(data.response_delay !== undefined && data.response_delay !== null ? String(data.response_delay) : "0");
      setBotName(data.bot_name || "AI Assistant");
      setApiKeyConfigured(data.api_key_configured);

      if (data.api_key_configured) {
        setApiKey(MASKED_KEY);
        setKeyEdited(false);
        setHasConfig(true);
      } else {
        setApiKey("");
        setKeyEdited(true);
        setHasConfig(false);
      }
    } catch (err) {
      console.error("fetchConfig error:", err);
      toast.error("Failed to load chatbot configuration");
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id]);

  useEffect(() => {
    if (authLoading) return;
    if (!user || !activeWorkspace?.id) {
      setLoading(false);
      return;
    }
    fetchConfig();
  }, [authLoading, user, activeWorkspace?.id, fetchConfig]);

  const handleSave = async () => {
    if (!activeWorkspace?.id) {
      toast.error("No active workspace selected");
      return;
    }

    try {
      setSaving(true);

      const payload: Record<string, any> = {
        workspace_id: activeWorkspace.id,
        is_enabled: isEnabled,
        provider,
        model,
        system_prompt: (systemPrompt || "").trim(),
        business_context: (businessContext || "").trim(),
        auto_pause_duration: isNaN(Number(autoPauseDuration)) ? 60 : Number(autoPauseDuration),
        response_delay: isNaN(Number(responseDelay)) ? 0 : Number(responseDelay),
        bot_name: (botName || "").trim() || "AI Assistant",
      };

      // Only send api_key if edited and not using the mask placeholder
      if (keyEdited && apiKey !== MASKED_KEY && apiKey.trim()) {
        payload.api_key = apiKey.trim();
      }

      const res = await fetch("/api/whatsapp/chatbot-config", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error || "Failed to save configuration");
        return;
      }

      toast.success("Chatbot configuration saved successfully");
      await fetchConfig();
    } catch (err) {
      console.error("Save error:", err);
      toast.error("Failed to save configuration");
    } finally {
      setSaving(false);
    }
  };

  const handleReset = async () => {
    if (!activeWorkspace?.id) return;
    if (!confirm("This will completely reset the chatbot settings for this workspace. Continue?")) {
      return;
    }

    try {
      setResetting(true);
      const res = await fetch(`/api/whatsapp/chatbot-config?workspace_id=${activeWorkspace.id}`, {
        method: "DELETE",
      });

      if (!res.ok) {
        const data = await res.json();
        toast.error(data.error || "Failed to reset configuration");
        return;
      }

      toast.success("Chatbot settings reset successfully");
      setApiKey("");
      setKeyEdited(true);
      setIsEnabled(false);
      setProvider("openai");
      setModel("gpt-4o-mini");
      setSystemPrompt("You are a helpful customer service assistant for our business.");
      setBusinessContext("");
      setAutoPauseDuration("60");
      setResponseDelay("0");
      setBotName("AI Assistant");
      setHasConfig(false);
      setApiKeyConfigured(false);
    } catch (err) {
      console.error("Reset error:", err);
      toast.error("Failed to reset configuration");
    } finally {
      setResetting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="size-6 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_380px] mt-4">
      <div className="space-y-6">
        {/* ── Chatbot Activation Toggle ── */}
        <Card className="bg-card border-border">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-primary/10 rounded-xl text-primary">
                  <Bot className="size-6 animate-pulse" />
                </div>
                <div>
                  <h3 className="text-foreground font-semibold">Enable AI Chatbot</h3>
                  <p className="text-xs text-muted-foreground">
                    Allow the AI Chatbot to monitor and respond to customer WhatsApp inquiries.
                  </p>
                </div>
              </div>
              <Switch checked={isEnabled} onCheckedChange={setIsEnabled} />
            </div>
          </CardContent>
        </Card>

        {/* ── AI Provider Configurations ── */}
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2 text-base">
              <Sparkles className="size-4 text-primary" />
              AI Engine Credentials
            </CardTitle>
            <CardDescription className="text-muted-foreground">
              Select your preferred LLM provider and enter credentials to power the chatbot.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Provider Selection */}
            <div className="grid gap-2">
              <Label className="text-foreground">LLM Provider</Label>
              <Select value={provider} onValueChange={(val) => handleProviderChange((val ?? "openai") as AIProvider)}>
                <SelectTrigger className="bg-muted border-border text-foreground">
                  <SelectValue placeholder="Select provider" />
                </SelectTrigger>
                <SelectContent className="bg-muted border-border text-foreground">
                  <SelectItem value="openai">OpenAI (GPT)</SelectItem>
                  <SelectItem value="grok">xAI (Grok AI)</SelectItem>
                  <SelectItem value="groq">Groq (groq.com)</SelectItem>
                  <SelectItem value="gemini">Google (Gemini)</SelectItem>
                  <SelectItem value="anthropic">Anthropic (Claude)</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Model Name */}
            <div className="grid gap-2">
              <Label className="text-foreground">Model Name</Label>
              <Input
                placeholder="e.g. grok-beta, gpt-4o-mini"
                value={model}
                onChange={(e) => setModel(e.target.value)}
                className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
              />
            </div>

            {/* API Key Input */}
            <div className="grid gap-2">
              <div className="flex justify-between items-center">
                <Label className="text-foreground">Provider API Key</Label>
                {apiKeyConfigured && !keyEdited && (
                  <span className="text-[10px] text-emerald-400 flex items-center gap-1">
                    <ShieldCheck className="size-3" /> Configured
                  </span>
                )}
              </div>
              <div className="relative">
                <Input
                  type={showKey ? "text" : "password"}
                  placeholder={
                    apiKeyConfigured
                      ? "Use saved API key"
                      : `Enter API key for ${provider.toUpperCase()}`
                  }
                  value={apiKey}
                  onChange={(e) => {
                    setApiKey(e.target.value);
                    setKeyEdited(true);
                  }}
                  onFocus={() => {
                    if (apiKey === MASKED_KEY) {
                      setApiKey("");
                      setKeyEdited(true);
                    }
                  }}
                  className="bg-muted border-border text-foreground placeholder:text-muted-foreground pr-10"
                />
                <button
                  type="button"
                  onClick={() => setShowKey(!showKey)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                >
                  {showKey ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                </button>
              </div>
              <p className="text-[11px] text-muted-foreground">
                Left blank? The chatbot will attempt to fall back to the CRM&apos;s system-wide{" "}
                <code className="text-muted-foreground bg-background px-1 py-0.5 rounded-none text-[10px]">
                  {provider === "grok"
                    ? "XAI_API_KEY"
                    : provider === "groq"
                    ? "GROQ_API_KEY"
                    : `${provider.toUpperCase()}_API_KEY`}
                </code>{" "}
                key.
              </p>
            </div>
          </CardContent>
        </Card>

        {/* ── Prompts & Business Knowledge ── */}
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2 text-base">
              <BookOpen className="size-4 text-primary" />
              Persona & Knowledge Base
            </CardTitle>
            <CardDescription className="text-muted-foreground">
              Provide context and directions to shape the bot&apos;s behavior and business awareness.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Assistant Name */}
            <div className="grid gap-2">
              <Label className="text-foreground">Assistant Bot Name</Label>
              <Input
                placeholder="e.g. Voyage Bot"
                value={botName}
                onChange={(e) => setBotName(e.target.value)}
                className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
              />
            </div>

            {/* System Prompt */}
            <div className="grid gap-2">
              <Label className="text-foreground">System Instructions / Persona</Label>
              <Textarea plain
                placeholder="Act as a helpful customer support agent. Be concise, polite, and professional..."
                value={systemPrompt}
                onChange={(e) => setSystemPrompt(e.target.value)}
                rows={4}
                className="bg-muted border-border text-foreground placeholder:text-muted-foreground resize-y"
              />
            </div>

            {/* Business Context */}
            <div className="grid gap-2">
              <div className="flex justify-between items-center">
                <Label className="text-foreground">Business Knowledge (FAQs, Pricing, Details)</Label>
                <span className="text-[10px] text-muted-foreground">Add custom details here</span>
              </div>
              <Textarea plain
                placeholder="Our business hours: Mon-Fri 9 AM to 6 PM.
Pricing details: Standard $29, Premium $99.
Support contacts: support@example.com"
                value={businessContext}
                onChange={(e) => setBusinessContext(e.target.value)}
                rows={6}
                className="bg-muted border-border text-foreground placeholder:text-muted-foreground resize-y font-mono text-xs leading-normal"
              />
            </div>
          </CardContent>
        </Card>

        {/* ── Control Rules (Auto-Pause & Typing Delay) ── */}
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2 text-base">
              <Sliders className="size-4 text-primary" />
              Conversation Control Rules
            </CardTitle>
            <CardDescription className="text-muted-foreground">
              Manage how the AI interacts alongside human agents in your workspace.
            </CardDescription>
          </CardHeader>
          <CardContent className="grid gap-6 sm:grid-cols-2">
            {/* Auto-Pause */}
            <div className="grid gap-2">
              <Label className="text-foreground">Agent Handover Auto-Pause</Label>
              <Select value={autoPauseDuration} onValueChange={(val) => setAutoPauseDuration(val ?? "60")}>
                <SelectTrigger className="bg-muted border-border text-foreground">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-muted border-border text-foreground">
                  <SelectItem value="0">Off (Do not auto-pause)</SelectItem>
                  <SelectItem value="15">15 Minutes</SelectItem>
                  <SelectItem value="30">30 Minutes</SelectItem>
                  <SelectItem value="60">1 Hour</SelectItem>
                  <SelectItem value="120">2 Hours</SelectItem>
                  <SelectItem value="1440">24 Hours</SelectItem>
                  <SelectItem value="-1">Permanent Takeover (Manual resume required)</SelectItem>
                </SelectContent>
              </Select>
              <p className="text-[10px] text-muted-foreground">
                Pauses the AI bot when a human agent replies to a message, preventing double responses.
              </p>
            </div>

            {/* Response Delay */}
            <div className="grid gap-2">
              <Label className="text-foreground">Simulated Response Delay</Label>
              <Select value={responseDelay} onValueChange={(val) => setResponseDelay(val ?? "0")}>
                <SelectTrigger className="bg-muted border-border text-foreground">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-muted border-border text-foreground">
                  <SelectItem value="0">Instant reply</SelectItem>
                  <SelectItem value="2">2 Seconds</SelectItem>
                  <SelectItem value="4">4 Seconds</SelectItem>
                  <SelectItem value="6">6 Seconds</SelectItem>
                  <SelectItem value="8">8 Seconds</SelectItem>
                  <SelectItem value="10">10 Seconds</SelectItem>
                </SelectContent>
              </Select>
              <p className="text-[10px] text-muted-foreground">
                Simulates typing by introducing a slight delay before sending messages on WhatsApp.
              </p>
            </div>
          </CardContent>
        </Card>

        {/* ── Form Actions ── */}
        <div className="flex gap-3">
          <Button
            onClick={handleSave}
            disabled={saving}
            className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-lg shadow-primary/15 px-6"
          >
            {saving ? (
              <>
                <Loader2 className="size-4 animate-spin mr-2" /> Saving...
              </>
            ) : (
              "Save Configurations"
            )}
          </Button>
          {hasConfig && (
            <Button
              variant="outline"
              onClick={handleReset}
              disabled={resetting}
              className="border-red-950 text-red-400 hover:text-red-300 hover:bg-red-950/40"
            >
              {resetting ? (
                <>
                  <Loader2 className="size-4 animate-spin mr-2" /> Resetting...
                </>
              ) : (
                <>
                  <RotateCcw className="size-4 mr-2" /> Reset Chatbot Settings
                </>
              )}
            </Button>
          )}
        </div>
      </div>

      {/* ── Instructions Sidebar ── */}
      <div>
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground text-base">Quick Start Guide</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4 text-xs text-muted-foreground leading-relaxed">
            <div className="p-3 bg-background/50 rounded-lg border border-border">
              <p className="text-primary font-semibold mb-1 flex items-center gap-1">
                <Zap className="size-3.5" /> 1. Connect API Credentials
              </p>
              <p>
                Provide an API key for your chosen AI model. We strongly recommend xAI (Grok AI) or
                OpenAI GPT-4o-mini for high-speed, cost-effective intake.
              </p>
            </div>

            <div className="p-3 bg-background/50 rounded-lg border border-border">
              <p className="text-primary font-semibold mb-1 flex items-center gap-1">
                <BookOpen className="size-3.5" /> 2. Add Business Knowledge
              </p>
              <p>
                Explain what treatments, prices, or answers you support. For Genesys Voyage, paste the
                full categorized treatment list (Oncology, Cardiology, Orthopaedics) and specify the step-by-step
                qualification questions (Reports, Country, Passport).
              </p>
            </div>

            <div className="p-3 bg-background/50 rounded-lg border border-border">
              <p className="text-primary font-semibold mb-1 flex items-center gap-1">
                <Sliders className="size-3.5" /> 3. Test & Enable
              </p>
              <p>
                Turn on the switch at the top. Test by messaging your WhatsApp number from a test phone.
                Check the CRM inbox in real-time to monitor the replies!
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { useWorkspace } from "@/hooks/use-workspace";
import { createClient } from "@/lib/supabase/client";
import { SettingsPanelHead } from "@/components/settings/settings-panel-head";
import {
  MessageSquare,
  PlugZap,
  Save,
  Loader2,
  Users,
  Coins,
  Bot,
  FileText
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import Link from "next/link";
import { IconAction } from "@/components/ui/icon-action";

export function CRMSettingsPanel() {
  const supabase = createClient();
  const { activeWorkspace, defaultCurrency } = useWorkspace();
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Settings State
  const [autoAssignLeads, setAutoAssignLeads] = useState(true);
  const [staleDealDays, setStaleDealDays] = useState(14);
  const [enableWhatsAppAutoReply, setEnableWhatsAppAutoReply] = useState(true);
  const [leadCaptureNotifyEmail, setLeadCaptureNotifyEmail] = useState("");

  useEffect(() => {
    if (!activeWorkspace?.id) return;
    const fetchSettings = async () => {
      setLoading(true);
      const { data } = await supabase
        .from("workspaces")
        .select("plan_limits")
        .eq("id", activeWorkspace.id)
        .maybeSingle();

      if (data?.plan_limits?.crm_settings) {
        const crm = data.plan_limits.crm_settings;
        setAutoAssignLeads(crm.autoAssignLeads ?? true);
        setStaleDealDays(crm.staleDealDays ?? 14);
        setEnableWhatsAppAutoReply(crm.enableWhatsAppAutoReply ?? true);
        setLeadCaptureNotifyEmail(crm.leadCaptureNotifyEmail || "");
      }
      setLoading(false);
    };

    fetchSettings();
  }, [activeWorkspace?.id, supabase]);

  const handleSave = async () => {
    if (!activeWorkspace?.id) return;
    setSaving(true);

    try {
      const { data: currentWs } = await supabase
        .from("workspaces")
        .select("plan_limits")
        .eq("id", activeWorkspace.id)
        .single();

      const existingLimits = currentWs?.plan_limits || {};
      const updatedLimits = {
        ...existingLimits,
        crm_settings: {
          autoAssignLeads,
          staleDealDays,
          enableWhatsAppAutoReply,
          leadCaptureNotifyEmail,
          updated_at: new Date().toISOString(),
        },
      };

      const { error } = await supabase
        .from("workspaces")
        .update({ plan_limits: updatedLimits })
        .eq("id", activeWorkspace.id);

      if (error) throw error;
      toast.success("CRM & Pipeline settings saved successfully!");
    } catch (err: any) {
      toast.error(err.message || "Failed to save CRM settings.");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12 text-muted-foreground text-xs">
        <Loader2 className="size-5 animate-spin mr-2" />
        Loading CRM Settings...
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-4xl text-foreground">
      <SettingsPanelHead
        title="CRM & Pipeline Settings"
        description="Configure lead assignment rules, deal pipeline triggers, WhatsApp channels, and automated follow-ups."
        action={
          <IconAction label="Save Changes" icon={saving ? <Loader2 className="size-4 animate-spin" /> : <Save className="size-4" />} onClick={handleSave}
            disabled={saving}
            className="bg-primary text-primary-foreground hover:bg-primary/90 font-semibold gap-1.5 shadow-xs" />
        }
      />

      {/* Quick Jump Shortcuts */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <Link href="/settings?tab=whatsapp" className="p-4 bg-card border border-border rounded-xl hover:border-primary/50 transition-colors flex items-center gap-3">
          <div className="p-2 bg-emerald-500/10 text-emerald-500 rounded-lg">
            <PlugZap className="size-5" />
          </div>
          <div>
            <h4 className="text-xs font-bold text-foreground">WhatsApp API</h4>
            <p className="text-[11px] text-muted-foreground">Manage WABA numbers</p>
          </div>
        </Link>

        <Link href="/settings?tab=chatbot" className="p-4 bg-card border border-border rounded-xl hover:border-primary/50 transition-colors flex items-center gap-3">
          <div className="p-2 bg-primary/10 text-primary rounded-lg">
            <Bot className="size-5" />
          </div>
          <div>
            <h4 className="text-xs font-bold text-foreground">AI Chatbot</h4>
            <p className="text-[11px] text-muted-foreground">Auto-reply assistant</p>
          </div>
        </Link>

        <Link href="/settings?tab=templates" className="p-4 bg-card border border-border rounded-xl hover:border-primary/50 transition-colors flex items-center gap-3">
          <div className="p-2 bg-purple-500/10 text-purple-500 rounded-lg">
            <FileText className="size-5" />
          </div>
          <div>
            <h4 className="text-xs font-bold text-foreground">Templates</h4>
            <p className="text-[11px] text-muted-foreground">WhatsApp & Email templates</p>
          </div>
        </Link>
      </div>

      {/* 1. Lead & Pipeline Rules */}
      <Card className="bg-card border-border shadow-xs rounded-2xl">
        <CardHeader className="pb-3">
          <CardTitle className="text-base font-bold flex items-center gap-2 text-foreground">
            <MessageSquare className="size-4 text-primary" /> Lead Routing & Pipeline Rules
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground">
            Automate incoming contact distribution and deal stale alerts.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label className="text-xs font-semibold">Auto-Assign New Leads (Round-Robin)</Label>
              <p className="text-[11px] text-muted-foreground">Automatically distribute new incoming WhatsApp & form leads among active team members.</p>
            </div>
            <Switch
              checked={autoAssignLeads}
              onCheckedChange={setAutoAssignLeads}
            />
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-border/60">
            <div className="space-y-0.5">
              <Label className="text-xs font-semibold">Enable WhatsApp Instant Auto-Response</Label>
              <p className="text-[11px] text-muted-foreground">Send welcoming auto-reply when a new customer messages outside business hours.</p>
            </div>
            <Switch
              checked={enableWhatsAppAutoReply}
              onCheckedChange={setEnableWhatsAppAutoReply}
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2 border-t border-border/60">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Mark Deals Stale After (Days)</Label>
              <Input
                type="number"
                min={1}
                max={365}
                value={staleDealDays}
                onChange={(e) => setStaleDealDays(Number(e.target.value))}
                className="bg-background text-xs"
              />
              <p className="text-[11px] text-muted-foreground">Highlight pipeline deals with no recent activity or stage change.</p>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Lead Notification Email</Label>
              <Input
                type="email"
                placeholder="sales-lead@yourcompany.com"
                value={leadCaptureNotifyEmail}
                onChange={(e) => setLeadCaptureNotifyEmail(e.target.value)}
                className="bg-background text-xs"
              />
              <p className="text-[11px] text-muted-foreground">Email address to receive immediate lead capture summaries.</p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { toast } from "sonner";
import {
  Clock,
  Calendar,
  Banknote,
  Loader2,
  Save,
  Layers
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { SettingsPanelHead } from "./settings-panel-head";
import { SalaryStructuresManager } from "./salary-structures-manager";
import { IconAction } from "@/components/ui/icon-action";

type ScopeType = 'WORKSPACE_DEFAULT' | 'DEPARTMENT' | 'DESIGNATION';

export function HRSettingsPanel() {
  const supabase = createClient();
  const { activeWorkspace, can } = useWorkspace();
  const canManage = can('settings_workspace') || can('people_manage');

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [departments, setDepartments] = useState<any[]>([]);
  const [designations, setDesignations] = useState<any[]>([]);
  const [existingSettings, setExistingSettings] = useState<any[]>([]);

  // Selected Scope State
  const [scopeType, setScopeType] = useState<ScopeType>('WORKSPACE_DEFAULT');
  const [scopeId, setScopeId] = useState<string>('none');

  // Operational Settings Form State
  // 1. Attendance
  const [shiftStart, setShiftStart] = useState('09:30');
  const [shiftEnd, setShiftEnd] = useState('18:30');
  const [gracePeriod, setGracePeriod] = useState('15');
  const [halfDayHours, setHalfDayHours] = useState('4');

  // 2. Leave
  const [casualLeaveQuota, setCasualLeaveQuota] = useState('12');
  const [sickLeaveQuota, setSickLeaveQuota] = useState('12');
  const [annualLeaveQuota, setAnnualLeaveQuota] = useState('18');
  const [monthlyAccrual, setMonthlyAccrual] = useState('1.5');
  const [maxCarryForward, setMaxCarryForward] = useState('5');

  // 3. Payroll
  const [payCycleDay, setPayCycleDay] = useState('28');
  const [basicPct, setBasicPct] = useState('50');
  const [hraPct, setHraPct] = useState('20');
  const [pfRatePct, setPfRatePct] = useState('12');

  const fetchData = useCallback(async () => {
    if (!activeWorkspace?.id) return;
    setLoading(true);

    try {
      const [deptRes, desigRes, settingsRes] = await Promise.all([
        supabase.from('departments').select('id, name').eq('workspace_id', activeWorkspace.id),
        supabase.from('designations').select('id, title').eq('workspace_id', activeWorkspace.id),
        supabase.from('hr_operational_settings').select('*').eq('workspace_id', activeWorkspace.id)
      ]);

      setDepartments(deptRes.data || []);
      setDesignations(desigRes.data || []);
      setExistingSettings(settingsRes.data || []);
    } catch (err) {
      console.error(err);
      toast.error('Failed to load HR settings');
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace?.id, supabase]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Update form fields based on selected scope
  useEffect(() => {
    const targetScopeId = scopeType === 'WORKSPACE_DEFAULT' ? null : (scopeId === 'none' ? null : scopeId);

    // Filter settings for current scope
    const att = existingSettings.find(s => s.setting_type === 'ATTENDANCE_SHIFT' && s.scope_type === scopeType && s.scope_id === targetScopeId);
    const lve = existingSettings.find(s => s.setting_type === 'LEAVE_RULES' && s.scope_type === scopeType && s.scope_id === targetScopeId);
    const pay = existingSettings.find(s => s.setting_type === 'PAYROLL_CONFIG' && s.scope_type === scopeType && s.scope_id === targetScopeId);

    if (att?.settings_json) {
      setShiftStart(att.settings_json.shift_start || '09:30');
      setShiftEnd(att.settings_json.shift_end || '18:30');
      setGracePeriod(att.settings_json.grace_period_minutes?.toString() || '15');
      setHalfDayHours(att.settings_json.half_day_threshold_hours?.toString() || '4');
    } else {
      setShiftStart('09:30');
      setShiftEnd('18:30');
      setGracePeriod('15');
      setHalfDayHours('4');
    }

    if (lve?.settings_json) {
      setCasualLeaveQuota(lve.settings_json.casual_leave_quota?.toString() || '12');
      setSickLeaveQuota(lve.settings_json.sick_leave_quota?.toString() || '12');
      setAnnualLeaveQuota(lve.settings_json.annual_leave_quota?.toString() || '18');
      setMonthlyAccrual(lve.settings_json.monthly_accrual_rate?.toString() || '1.5');
      setMaxCarryForward(lve.settings_json.max_carry_forward?.toString() || '5');
    } else {
      setCasualLeaveQuota('12');
      setSickLeaveQuota('12');
      setAnnualLeaveQuota('18');
      setMonthlyAccrual('1.5');
      setMaxCarryForward('5');
    }

    if (pay?.settings_json) {
      setPayCycleDay(pay.settings_json.pay_cycle_day?.toString() || '28');
      setBasicPct(pay.settings_json.basic_percentage?.toString() || '50');
      setHraPct(pay.settings_json.hra_percentage?.toString() || '20');
      setPfRatePct(pay.settings_json.pf_rate_percentage?.toString() || '12');
    } else {
      setPayCycleDay('28');
      setBasicPct('50');
      setHraPct('20');
      setPfRatePct('12');
    }
  }, [scopeType, scopeId, existingSettings]);

  const handleSaveSettings = async () => {
    if (!activeWorkspace?.id) return;
    if (scopeType !== 'WORKSPACE_DEFAULT' && scopeId === 'none') {
      toast.error('Please select a specific Department or Designation');
      return;
    }

    setSaving(true);
    const targetScopeId = scopeType === 'WORKSPACE_DEFAULT' ? null : scopeId;

    try {
      const attendanceJson = {
        shift_start: shiftStart,
        shift_end: shiftEnd,
        grace_period_minutes: parseInt(gracePeriod || '0'),
        half_day_threshold_hours: parseFloat(halfDayHours || '0')
      };

      const leaveJson = {
        casual_leave_quota: parseInt(casualLeaveQuota || '0'),
        sick_leave_quota: parseInt(sickLeaveQuota || '0'),
        annual_leave_quota: parseInt(annualLeaveQuota || '0'),
        monthly_accrual_rate: parseFloat(monthlyAccrual || '0'),
        max_carry_forward: parseInt(maxCarryForward || '0')
      };

      const payrollJson = {
        pay_cycle_day: parseInt(payCycleDay || '28'),
        basic_percentage: parseFloat(basicPct || '0'),
        hra_percentage: parseFloat(hraPct || '0'),
        pf_rate_percentage: parseFloat(pfRatePct || '0')
      };

      // Save all 3 setting types for this scope
      await Promise.all([
        fetch('/api/hr/settings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            workspaceId: activeWorkspace.id,
            settingType: 'ATTENDANCE_SHIFT',
            scopeType,
            scopeId: targetScopeId,
            settingsJson: attendanceJson
          })
        }),
        fetch('/api/hr/settings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            workspaceId: activeWorkspace.id,
            settingType: 'LEAVE_RULES',
            scopeType,
            scopeId: targetScopeId,
            settingsJson: leaveJson
          })
        }),
        fetch('/api/hr/settings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            workspaceId: activeWorkspace.id,
            settingType: 'PAYROLL_CONFIG',
            scopeType,
            scopeId: targetScopeId,
            settingsJson: payrollJson
          })
        })
      ]);

      toast.success('HR Operational Settings saved successfully');
      fetchData(); // Refresh list
    } catch (err: any) {
      toast.error(err.message || 'Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SettingsPanelHead
        title="HR Operations & Shift Settings"
        description="Configure attendance shift timings, grace periods, leave accrual rules, and payroll processing cycles with Department/Designation overrides."
      />

      {/* Scope Selector Card */}
      <Card className="border-border bg-card shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Layers className="size-4 text-primary" /> Configuration Scope & Overrides
          </CardTitle>
          <CardDescription>
            Choose whether to edit Company Global Defaults or set specific overrides for a Department or Designation.
          </CardDescription>
        </CardHeader>
        <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label>Setting Scope Level</Label>
            <Select value={scopeType} onValueChange={(val) => { setScopeType(val as ScopeType); setScopeId('none'); }}>
              <SelectTrigger className="bg-popover border-border"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="WORKSPACE_DEFAULT">Company Global Default (All Members)</SelectItem>
                <SelectItem value="DEPARTMENT">Department Specific Override</SelectItem>
                <SelectItem value="DESIGNATION">Designation Specific Override</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {scopeType === 'DEPARTMENT' && (
            <div className="space-y-2">
              <Label>Select Target Department</Label>
              <Select value={scopeId} onValueChange={(val) => setScopeId(val || 'none')}>
                <SelectTrigger className="bg-popover border-border"><SelectValue placeholder="Select Department" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">-- Select Department --</SelectItem>
                  {departments.map(d => (
                    <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {scopeType === 'DESIGNATION' && (
            <div className="space-y-2">
              <Label>Select Target Designation</Label>
              <Select value={scopeId} onValueChange={(val) => setScopeId(val || 'none')}>
                <SelectTrigger className="bg-popover border-border"><SelectValue placeholder="Select Designation" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">-- Select Designation --</SelectItem>
                  {designations.map(d => (
                    <SelectItem key={d.id} value={d.id}>{d.title}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Operational Settings Panels */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* 1. Attendance & Shift Settings */}
        <Card className="border-border bg-card shadow-sm">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Clock className="size-4 text-emerald-500" /> Attendance & Shifts
            </CardTitle>
            <CardDescription>Shift hours & grace periods</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label>Shift Start Time</Label>
              <Input type="time" value={shiftStart} onChange={e => setShiftStart(e.target.value)} className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>Shift End Time</Label>
              <Input type="time" value={shiftEnd} onChange={e => setShiftEnd(e.target.value)} className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>Grace Period (Minutes)</Label>
              <Input type="number" min="0" value={gracePeriod} onChange={e => setGracePeriod(e.target.value)} placeholder="15" className="bg-popover" />
              <p className="text-[11px] text-muted-foreground">Late punch status triggered after grace period.</p>
            </div>

            <div className="space-y-2">
              <Label>Half-Day Threshold (Hours)</Label>
              <Input type="number" min="1" step="0.5" value={halfDayHours} onChange={e => setHalfDayHours(e.target.value)} placeholder="4" className="bg-popover" />
            </div>
          </CardContent>
        </Card>

        {/* 2. Leave Rules & Accrual */}
        <Card className="border-border bg-card shadow-sm">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Calendar className="size-4 text-blue-500" /> Leave Rules & Quotas
            </CardTitle>
            <CardDescription>Annual leave quotas & accruals</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label>Casual Leave Annual Quota</Label>
              <Input type="number" min="0" value={casualLeaveQuota} onChange={e => setCasualLeaveQuota(e.target.value)} className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>Sick Leave Annual Quota</Label>
              <Input type="number" min="0" value={sickLeaveQuota} onChange={e => setSickLeaveQuota(e.target.value)} className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>Annual Paid Leave Quota</Label>
              <Input type="number" min="0" value={annualLeaveQuota} onChange={e => setAnnualLeaveQuota(e.target.value)} className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>Monthly Accrual Rate (Days/Month)</Label>
              <Input type="number" min="0" step="0.5" value={monthlyAccrual} onChange={e => setMonthlyAccrual(e.target.value)} placeholder="1.5" className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>Max Carry-Forward Limit</Label>
              <Input type="number" min="0" value={maxCarryForward} onChange={e => setMaxCarryForward(e.target.value)} placeholder="5" className="bg-popover" />
            </div>
          </CardContent>
        </Card>

        {/* 3. Payroll Cycle & Ratios */}
        <Card className="border-border bg-card shadow-sm">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Banknote className="size-4 text-purple-500" /> Payroll & Components
            </CardTitle>
            <CardDescription>Pay dates & earnings ratios</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label>Monthly Pay Cycle Date</Label>
              <Input type="number" min="1" max="31" value={payCycleDay} onChange={e => setPayCycleDay(e.target.value)} placeholder="28" className="bg-popover" />
              <p className="text-[11px] text-muted-foreground">Day of the month salaries are calculated.</p>
            </div>

            <div className="space-y-2">
              <Label>Basic Salary Ratio (%)</Label>
              <Input type="number" min="0" max="100" value={basicPct} onChange={e => setBasicPct(e.target.value)} placeholder="50" className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>House Rent Allowance (HRA) (%)</Label>
              <Input type="number" min="0" max="100" value={hraPct} onChange={e => setHraPct(e.target.value)} placeholder="20" className="bg-popover" />
            </div>

            <div className="space-y-2">
              <Label>Provident Fund (PF) Rate (%)</Label>
              <Input type="number" min="0" max="100" value={pfRatePct} onChange={e => setPfRatePct(e.target.value)} placeholder="12" className="bg-popover" />
            </div>
          </CardContent>
        </Card>

      </div>

      {canManage && (
        <div className="flex justify-end pt-4 border-t border-border">
          <IconAction label="Save Operational Settings" icon={saving ? <Loader2 className="size-4 animate-spin " /> : <Save className="size-4 " />} onClick={handleSaveSettings} disabled={saving} className="bg-primary text-primary-foreground shadow-sm" />
        </div>
      )}

      <div className="pt-8 mt-2 border-t border-border">
        <SettingsPanelHead
          title="Salary structures"
          description="Define reusable pay slabs and the components they are built from. Assign a structure to an employee on their Compensation tab and the full breakdown is derived from their basic salary."
        />
        <SalaryStructuresManager canEdit={canManage} />
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { useWorkspace } from "@/hooks/use-workspace";
import { createClient } from "@/lib/supabase/client";
import { SettingsPanelHead } from "@/components/settings/settings-panel-head";
import {
  Briefcase,
  Clock,
  CheckCircle2,
  AlertCircle,
  Save,
  DollarSign,
  ShieldCheck,
  Loader2,
  Kanban
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { IconAction } from "@/components/ui/icon-action";

export function ProjectsSettingsPanel() {
  const supabase = createClient();
  const { activeWorkspace } = useWorkspace();
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Settings State
  const [dailyCapacityHours, setDailyCapacityHours] = useState(8);
  const [enableTimesheetApproval, setEnableTimesheetApproval] = useState(true);
  const [autoLockDays, setAutoLockDays] = useState(7);
  const [defaultHourlyRate, setDefaultHourlyRate] = useState(50);
  const [enableOvertimeAlerts, setEnableOvertimeAlerts] = useState(true);
  const [requireTaskReview, setRequireTaskReview] = useState(false);

  useEffect(() => {
    if (!activeWorkspace?.id) return;
    const fetchSettings = async () => {
      setLoading(true);
      const { data } = await supabase
        .from("workspaces")
        .select("plan_limits")
        .eq("id", activeWorkspace.id)
        .maybeSingle();

      if (data?.plan_limits?.project_settings) {
        const ps = data.plan_limits.project_settings;
        setDailyCapacityHours(ps.dailyCapacityHours ?? 8);
        setEnableTimesheetApproval(ps.enableTimesheetApproval ?? true);
        setAutoLockDays(ps.autoLockDays ?? 7);
        setDefaultHourlyRate(ps.defaultHourlyRate ?? 50);
        setEnableOvertimeAlerts(ps.enableOvertimeAlerts ?? true);
        setRequireTaskReview(ps.requireTaskReview ?? false);
      }
      setLoading(false);
    };

    fetchSettings();
  }, [activeWorkspace?.id, supabase]);

  const handleSave = async () => {
    if (!activeWorkspace?.id) return;
    setSaving(true);

    try {
      // Read current plan_limits JSON
      const { data: currentWs } = await supabase
        .from("workspaces")
        .select("plan_limits")
        .eq("id", activeWorkspace.id)
        .single();

      const existingLimits = currentWs?.plan_limits || {};
      const updatedLimits = {
        ...existingLimits,
        project_settings: {
          dailyCapacityHours,
          enableTimesheetApproval,
          autoLockDays,
          defaultHourlyRate,
          enableOvertimeAlerts,
          requireTaskReview,
          updated_at: new Date().toISOString(),
        },
      };

      const { error } = await supabase
        .from("workspaces")
        .update({ plan_limits: updatedLimits })
        .eq("id", activeWorkspace.id);

      if (error) throw error;
      toast.success("Project Management settings saved successfully!");
    } catch (err: any) {
      toast.error(err.message || "Failed to save project settings.");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12 text-muted-foreground text-xs">
        <Loader2 className="size-5 animate-spin mr-2" />
        Loading Project Settings...
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-4xl text-foreground">
      <SettingsPanelHead
        title="Project Management Settings"
        description="Configure workload capacity, timesheet approval workflows, task rules, and default billing rates."
        action={
          <IconAction label="Save Changes" icon={saving ? <Loader2 className="size-4 animate-spin" /> : <Save className="size-4" />} onClick={handleSave}
            disabled={saving}
            className="bg-primary text-primary-foreground hover:bg-primary/90 font-semibold gap-1.5 shadow-xs" />
        }
      />

      {/* 1. Workload & Capacity */}
      <Card className="bg-card border-border shadow-xs rounded-2xl">
        <CardHeader className="pb-3">
          <CardTitle className="text-base font-bold flex items-center gap-2 text-foreground">
            <Clock className="size-4 text-primary" /> Workload & Daily Capacity
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground">
            Define team workload benchmarks and daily working thresholds.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Standard Daily Capacity (Hours/Day)</Label>
              <Input
                type="number"
                min={1}
                max={24}
                value={dailyCapacityHours}
                onChange={(e) => setDailyCapacityHours(Number(e.target.value))}
                className="bg-background text-xs"
              />
              <p className="text-[11px] text-muted-foreground">Used for calculating team workload utilization on Gantt & Planning views.</p>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Default Hourly Billing Rate ($)</Label>
              <Input
                type="number"
                min={0}
                value={defaultHourlyRate}
                onChange={(e) => setDefaultHourlyRate(Number(e.target.value))}
                className="bg-background text-xs"
              />
              <p className="text-[11px] text-muted-foreground">Default billable rate applied when creating new project budgets.</p>
            </div>
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-border/60">
            <div className="space-y-0.5">
              <Label className="text-xs font-semibold">Overtime Capacity Alerts</Label>
              <p className="text-[11px] text-muted-foreground">Notify project managers when a team member is allocated over 100% capacity.</p>
            </div>
            <Switch
              checked={enableOvertimeAlerts}
              onCheckedChange={setEnableOvertimeAlerts}
            />
          </div>
        </CardContent>
      </Card>

      {/* 2. Timesheet Approvals & Locking */}
      <Card className="bg-card border-border shadow-xs rounded-2xl">
        <CardHeader className="pb-3">
          <CardTitle className="text-base font-bold flex items-center gap-2 text-foreground">
            <ShieldCheck className="size-4 text-emerald-500" /> Timesheets & Governance
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground">
            Enforce approval workflows and auto-locking for time logs.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label className="text-xs font-semibold">Require Manager Approval for Timesheets</Label>
              <p className="text-[11px] text-muted-foreground">Logged hours must be approved by project manager before invoicing.</p>
            </div>
            <Switch
              checked={enableTimesheetApproval}
              onCheckedChange={setEnableTimesheetApproval}
            />
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-border/60">
            <div className="space-y-0.5">
              <Label className="text-xs font-semibold">Require Code Review / Quality Check for Tasks</Label>
              <p className="text-[11px] text-muted-foreground">Tasks moved to Done must first pass In-Review verification status.</p>
            </div>
            <Switch
              checked={requireTaskReview}
              onCheckedChange={setRequireTaskReview}
            />
          </div>

          <div className="space-y-1.5 pt-2 border-t border-border/60">
            <Label className="text-xs font-semibold">Auto-Lock Past Timesheets (Days)</Label>
            <Input
              type="number"
              min={0}
              max={90}
              value={autoLockDays}
              onChange={(e) => setAutoLockDays(Number(e.target.value))}
              className="bg-background text-xs max-w-xs"
            />
            <p className="text-[11px] text-muted-foreground">Prevent editing or deleting timesheet logs older than N days.</p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import {
  Coins,
  FileText,
  KeyRound,
  LayoutGrid,
  Palette,
  PlugZap,
  Shield,
  ShieldCheck,
  Tags,
  User,
  UsersRound,
  Bot,
  FileSpreadsheet,
  Building2,
  CreditCard,
  Briefcase,
  Store,
  Landmark,
  MapPin,
  type LucideIcon,
} from 'lucide-react';

/**
 * Settings information architecture for the redesigned page.
 *
 * The flat tab strip became a grouped left rail with a new Overview
 * landing. The URL query param stays `?tab=` (deep-linkable, and it
 * keeps the existing links in sidebar.tsx / header.tsx working) — we
 * just map the old values onto the new sections.
 */
export const SETTINGS_SECTIONS = [
  'overview',
  'profile',
  'crm',
  'whatsapp',
  'templates',
  'accounting',
  'projects',
  'hr',
  'retail',
  'members',
  'billing',
  'api',
  'catalog',
  'branding',
] as const;

export type SettingsSection = (typeof SETTINGS_SECTIONS)[number];

export const DEFAULT_SECTION: SettingsSection = 'overview';

/** Rail grouping. `adminOnly` items are hidden for non-admins. */
export interface SectionMeta {
  id: SettingsSection;
  label: string;
  icon: LucideIcon;
  group:
    | 'top'
    | 'account'
    | 'company'
    | 'content'
    | 'crm_module'
    | 'finance_module'
    | 'projects_module'
    | 'hr_module'
    | 'retail_module'
    | 'workspace_admin';
  /** One-line hint under the label in the rail and on the Overview cards. */
  blurb?: string;
}

export const SECTION_META: Record<SettingsSection, SectionMeta> = {
  overview: { id: 'overview', label: 'Overview', icon: LayoutGrid, group: 'top' },

  // Your account — personal, not workspace-wide.
  profile: { id: 'profile', label: 'Your profile', icon: User, group: 'account', blurb: 'Your details, password, sessions and appearance' },

  // The company itself — identity that appears on outgoing documents.
  branding: { id: 'branding', label: 'Company branding', icon: Building2, group: 'company', blurb: 'Logo, company details and the letterhead used on every document' },
  members: { id: 'members', label: 'Team & access', icon: UsersRound, group: 'company', blurb: 'Members, invitations, roles and permissions' },

  // Reusable content shared across every module.
  templates: { id: 'templates', label: 'Templates', icon: FileText, group: 'content', blurb: 'Messages, emails and letters for every module' },
  catalog: { id: 'catalog', label: 'Service catalog', icon: FileSpreadsheet, group: 'content', blurb: 'Products and services you sell' },

  // CRM
  crm: { id: 'crm', label: 'CRM & pipelines', icon: PlugZap, group: 'crm_module', blurb: 'Pipelines, deal defaults, custom fields and tags' },
  whatsapp: { id: 'whatsapp', label: 'WhatsApp API', icon: PlugZap, group: 'crm_module', blurb: 'Connection, chatbot and Meta template approvals' },

  // Finance
  accounting: { id: 'accounting', label: 'Accounting & ledgers', icon: Landmark, group: 'finance_module', blurb: 'Chart of accounts and tax defaults' },

  // Projects
  projects: { id: 'projects', label: 'Project management', icon: Briefcase, group: 'projects_module', blurb: 'Project defaults and billing rates' },

  // HR
  hr: { id: 'hr', label: 'HR & operations', icon: Briefcase, group: 'hr_module', blurb: 'Shifts, leave, payroll, salary and attendance rules' },

  // Retail
  retail: { id: 'retail', label: 'Retail presets', icon: Store, group: 'retail_module', blurb: 'Counter, tax and receipt defaults' },

  // Platform administration
  billing: { id: 'billing', label: 'Billing & plan', icon: CreditCard, group: 'workspace_admin', blurb: 'Subscription and invoices' },
  api: { id: 'api', label: 'API keys', icon: KeyRound, group: 'workspace_admin', blurb: 'Programmatic access to your workspace' },
};

export const RAIL_GROUPS: { label: string | null; group: SectionMeta['group'] }[] = [
  { label: null, group: 'top' },
  { label: 'Your account', group: 'account' },
  { label: 'Company', group: 'company' },
  { label: 'Content & templates', group: 'content' },
  { label: 'CRM & messaging', group: 'crm_module' },
  { label: 'Finance', group: 'finance_module' },
  { label: 'HR & people', group: 'hr_module' },
  { label: 'Projects', group: 'projects_module' },
  { label: 'Retail', group: 'retail_module' },
  { label: 'Administration', group: 'workspace_admin' },
];

function isSection(value: string | null): value is SettingsSection {
  return !!value && (SETTINGS_SECTIONS as readonly string[]).includes(value);
}

/**
 * Resolve a raw `?tab=` value to a section. Legacy tabs from the old
 * flat layout collapse onto their new home (Tags + Custom fields → the
 * merged "Fields & tags" section). Anything unknown falls back to the
 * Overview landing.
 */
export function resolveSection(raw: string | null): SettingsSection {
  // Folded sections: the id survives as a sub-tab, so an old deep link
  // resolves to the parent and the parent opens on that tab.
  if (raw === 'security' || raw === 'appearance') return 'profile';
  if (raw === 'roles' || raw === 'permissions') return 'members';
  if (raw === 'chatbot' || raw === 'whatsapp-templates') return 'whatsapp';
  if (raw === 'fields' || raw === 'tags' || raw === 'custom-fields' || raw === 'deals') return 'crm';
  if (raw === 'attendance' || raw === 'timesheet-templates') return 'hr';
  if (raw === 'letterhead') return 'branding';
  if (raw === 'roles-permissions') return 'members';
  if (raw === 'hr-operations' || raw === 'hr_operations' || raw === 'operations') return 'hr';
  if (raw === 'retail' || raw === 'retail-settings') return 'retail';
  if (isSection(raw)) return raw;
  return DEFAULT_SECTION;
}

'use client';

import { useEffect, useState } from 'react';
import { toast } from 'sonner';
import { Plus, X, Loader2 } from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { useAuth } from '@/hooks/use-auth';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent } from '@/components/ui/card';
import { useWorkspace } from '@/hooks/use-workspace';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import type { Tag } from '@/types';
import { IconAction } from "@/components/ui/icon-action";

const PRESET_COLORS = [
  { name: 'Red', value: '#ef4444' },
  { name: 'Orange', value: '#f97316' },
  { name: 'Amber', value: '#f59e0b' },
  { name: 'Emerald', value: '#10b981' },
  { name: 'Cyan', value: '#06b6d4' },
  { name: 'Blue', value: '#3b82f6' },
  { name: 'Violet', value: '#8b5cf6' },
  { name: 'Pink', value: '#ec4899' },
];

export function TagManager() {
  const supabase = createClient();
  const { user, loading: authLoading } = useAuth();
  const { activeWorkspace } = useWorkspace();

  const [loading, setLoading] = useState(true);
  const [tags, setTags] = useState<Tag[]>([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [tagToDelete, setTagToDelete] = useState<Tag | null>(null);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [newTagName, setNewTagName] = useState('');
  const [selectedColor, setSelectedColor] = useState(PRESET_COLORS[3].value);

  useEffect(() => {
    if (authLoading) return;
    if (!activeWorkspace?.id) {
      setLoading(false);
      return;
    }
    fetchTags();
  }, [authLoading, activeWorkspace?.id]);

  async function fetchTags() {
    if (!activeWorkspace?.id) return;
    try {
      setLoading(true);

      const { data, error } = await supabase
        .from('tags')
        .select('*')
        .eq('workspace_id', activeWorkspace.id)
        .order('created_at', { ascending: true });

      if (error) throw error;
      setTags(data || []);
    } catch (err) {
      console.error('Failed to fetch tags:', err);
      toast.error('Failed to load tags');
    } finally {
      setLoading(false);
    }
  }

  async function handleCreate() {
    if (!newTagName.trim()) {
      toast.error('Tag name is required');
      return;
    }

    try {
      setSaving(true);
      if (!user) {
        toast.error('Not authenticated');
        return;
      }
      if (!activeWorkspace?.id) {
        toast.error('No active workspace selected');
        return;
      }

      const { error } = await supabase
        .from('tags')
        .insert({
          user_id: user.id,
          workspace_id: activeWorkspace.id,
          name: newTagName.trim(),
          color: selectedColor,
        });

      if (error) throw error;

      toast.success('Tag created successfully');
      setDialogOpen(false);
      setNewTagName('');
      setSelectedColor(PRESET_COLORS[3].value);
      await fetchTags();
    } catch (err) {
      console.error('Create error:', err);
      toast.error('Failed to create tag');
    } finally {
      setSaving(false);
    }
  }

  function confirmDelete(tag: Tag) {
    setTagToDelete(tag);
    setDeleteDialogOpen(true);
  }

  async function handleDelete() {
    if (!tagToDelete) return;

    try {
      setDeleting(true);
      const { error } = await supabase
        .from('tags')
        .delete()
        .eq('id', tagToDelete.id);

      if (error) throw error;

      toast.success('Tag deleted');
      setTags((prev) => prev.filter((t) => t.id !== tagToDelete.id));
      setDeleteDialogOpen(false);
      setTagToDelete(null);
    } catch (err) {
      console.error('Delete error:', err);
      toast.error('Failed to delete tag');
    } finally {
      setDeleting(false);
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="size-6 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-4 mt-4">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-foreground">Tags</h2>
          <p className="text-sm text-muted-foreground">Organize your contacts with color-coded tags.</p>
        </div>
        <IconAction label="New Tag" icon={<Plus className="size-4" />} onClick={() => {
            setNewTagName('');
            setSelectedColor(PRESET_COLORS[3].value);
            setDialogOpen(true);
          }}
          className="bg-primary hover:bg-primary text-primary-foreground" />
      </div>

      {tags.length === 0 ? (
        <Card className="bg-card border-border ring-0 ring-transparent">
          <CardContent className="flex flex-col items-center justify-center py-12 text-center">
            <p className="text-muted-foreground text-sm">No tags yet.</p>
            <p className="text-muted-foreground text-xs mt-1">Create tags to categorize your contacts.</p>
          </CardContent>
        </Card>
      ) : (
        <Card className="bg-card border-border ring-0 ring-transparent">
          <CardContent className="pt-4">
            <div className="flex flex-wrap gap-2">
              {tags.map((tag) => (
                <span
                  key={tag.id}
                  className="group inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium transition-colors"
                  style={{
                    backgroundColor: `${tag.color}20`,
                    color: tag.color,
                    border: `1px solid ${tag.color}40`,
                  }}
                >
                  <span
                    className="size-2 rounded-full"
                    style={{ backgroundColor: tag.color }}
                  />
                  {tag.name}
                  <button
                    onClick={() => confirmDelete(tag)}
                    className="ml-0.5 rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-white/10"
                  >
                    <X className="size-3" />
                  </button>
                </span>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* New Tag Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="bg-card border-border sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-foreground">New Tag</DialogTitle>
            <DialogDescription className="text-muted-foreground">
              Create a new tag with a name and color.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label className="text-foreground">Tag Name</Label>
              <Input
                placeholder="e.g. VIP Customer"
                value={newTagName}
                onChange={(e) => setNewTagName(e.target.value)}
                className="bg-muted border-border text-foreground placeholder:text-muted-foreground"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleCreate();
                }}
              />
            </div>

            <div className="space-y-2">
              <Label className="text-foreground">Color</Label>
              <div className="flex gap-2 flex-wrap">
                {PRESET_COLORS.map((color) => (
                  <button
                    key={color.value}
                    onClick={() => setSelectedColor(color.value)}
                    className="relative size-8 rounded-full transition-transform hover:scale-110 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900"
                    style={{
                      backgroundColor: color.value,
                      boxShadow: selectedColor === color.value ? `0 0 0 2px rgb(15 23 42), 0 0 0 4px ${color.value}` : 'none',
                    }}
                    title={color.name}
                  />
                ))}
              </div>
            </div>

            {/* Preview */}
            <div className="space-y-2">
              <Label className="text-foreground">Preview</Label>
              <div>
                <span
                  className="inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium"
                  style={{
                    backgroundColor: `${selectedColor}20`,
                    color: selectedColor,
                    border: `1px solid ${selectedColor}40`,
                  }}
                >
                  <span
                    className="size-2 rounded-full"
                    style={{ backgroundColor: selectedColor }}
                  />
                  {newTagName || 'Tag Name'}
                </span>
              </div>
            </div>
          </div>

          <DialogFooter className="bg-card border-border">
            <Button
              variant="outline"
              onClick={() => setDialogOpen(false)}
              className="border-border text-foreground hover:bg-muted"
            >
              Cancel
            </Button>
            <Button
              onClick={handleCreate}
              disabled={saving}
              className="bg-primary hover:bg-primary text-primary-foreground"
            >
              {saving ? (
                <>
                  <Loader2 className="size-4 animate-spin" />
                  Creating...
                </>
              ) : (
                'Create Tag'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent className="bg-card border-border sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-foreground">Delete Tag</DialogTitle>
            <DialogDescription className="text-muted-foreground">
              Are you sure you want to delete the tag &quot;{tagToDelete?.name}&quot;? This will remove
              it from all contacts. This action cannot be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="bg-card border-border">
            <Button
              variant="outline"
              onClick={() => setDeleteDialogOpen(false)}
              className="border-border text-foreground hover:bg-muted"
            >
              Cancel
            </Button>
            <Button
              onClick={handleDelete}
              disabled={deleting}
              className="bg-red-600 hover:bg-red-700 text-foreground"
            >
              {deleting ? (
                <>
                  <Loader2 className="size-4 animate-spin" />
                  Deleting...
                </>
              ) : (
                'Delete Tag'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useDroppable } from '@dnd-kit/core';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Plus } from 'lucide-react';
import { IconAction } from "@/components/ui/icon-action";

interface KanbanColumnProps {
  id: string;
  title: string;
  taskCount: number;
  onAddTask: () => void;
  canManage: boolean;
  isBacklog?: boolean;
  children: React.ReactNode;
}

export function KanbanColumn({ id, title, taskCount, onAddTask, canManage, isBacklog, children }: KanbanColumnProps) {
  const { setNodeRef, isOver } = useDroppable({
    id,
  });

  return (
    <div 
      ref={setNodeRef}
      className={`flex-shrink-0 w-80 flex flex-col max-h-full border rounded-lg transition-colors ${
        isOver ? 'bg-primary/5 border-primary/50' : 'bg-muted/30 border-border'
      } ${isBacklog ? 'border-dashed' : ''}`}
    >
      <div className={`p-3 border-b flex items-center justify-between rounded-t-lg ${isBacklog ? 'bg-muted/50 border-border/50' : 'bg-card border-border'}`}>
        <h4 className="font-semibold text-sm text-foreground flex items-center gap-2">
          {title}
          <Badge variant="secondary" className="bg-muted text-muted-foreground text-[10px] px-1.5 py-0">
            {taskCount}
          </Badge>
        </h4>
        {canManage && (
          <IconAction
            label="Add"
            icon={<Plus className="size-3.5" />}
            variant="ghost"
            className="h-6 w-6 text-muted-foreground hover:bg-muted"
            onClick={onAddTask}
          />
        )}
      </div>
      
      <div className="flex-1 overflow-y-auto p-3 space-y-3 min-h-[150px]">
        {children}
      </div>
    </div>
  );
}

'use client';

import { useDraggable } from '@dnd-kit/core';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';

interface KanbanTaskProps {
  task: any;
  onEdit: () => void;
  isOverlay?: boolean;
}

export function KanbanTask({ task, onEdit, isOverlay }: KanbanTaskProps) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: task.id,
  });

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'urgent': return 'text-red-600 bg-red-500/15 border-red-200';
      case 'high': return 'text-orange-600 bg-orange-500/15 border-orange-200';
      case 'medium': return 'text-blue-600 bg-blue-500/15 border-blue-200';
      case 'low': return 'text-muted-foreground bg-muted/15 border-border';
      default: return 'text-muted-foreground bg-muted/15 border-border';
    }
  };

  const assignee = Array.isArray(task.assignee?.profiles) 
    ? task.assignee.profiles[0] 
    : task.assignee?.profiles;

  return (
    <div 
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      onClick={() => {
        // Prevent edit click if we are dragging
        if (!isDragging) {
          onEdit();
        }
      }}
      className={`bg-card border border-border rounded-md p-3 shadow-sm transition-shadow cursor-grab active:cursor-grabbing ${
        isDragging ? 'opacity-50' : 'hover:shadow-md'
      } ${isOverlay ? 'shadow-xl scale-105 rotate-2 cursor-grabbing' : ''}`}
    >
      <div className="flex items-start justify-between gap-2 mb-2">
        <h5 className="font-medium text-sm text-foreground leading-tight">{task.title}</h5>
      </div>
      
      {task.description && (
        <p className="text-xs text-muted-foreground line-clamp-2 mb-3">{task.description}</p>
      )}
      
      <div className="flex items-center justify-between mt-3 pt-3 border-t border-border">
        <Badge variant="outline" className={`uppercase text-[9px] px-1.5 py-0 ${getPriorityColor(task.priority)}`}>
          {task.priority}
        </Badge>
        
        {assignee && (
          <Avatar className="size-5 border border-border" title={assignee.full_name}>
            <AvatarImage src={assignee.avatar_url} />
            <AvatarFallback className="bg-primary/10 text-primary text-[8px]">{assignee.full_name?.charAt(0)}</AvatarFallback>
          </Avatar>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Loader2 } from 'lucide-react';
import { useWorkspace } from '@/hooks/use-workspace';

interface LogTimeModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  taskId: string;
  projectId: string | null;
  defaultBillable: boolean;
  onSaved: () => void;
}

export function LogTimeModal({
  open,
  onOpenChange,
  taskId,
  defaultBillable,
  onSaved,
}: LogTimeModalProps) {
  const { activeWorkspace: workspace, activeMember } = useWorkspace();
  const supabase = createClient();
  
  const [loading, setLoading] = useState(false);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [duration, setDuration] = useState('');
  const [description, setDescription] = useState('');
  const [billable, setBillable] = useState(defaultBillable);

  // Reset form when opened with new defaults
  useEffect(() => {
    if (open) {
      setDate(new Date().toISOString().split('T')[0]);
      setDuration('');
      setDescription('');
      setBillable(defaultBillable);
    }
  }, [open, defaultBillable]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!workspace || !activeMember || !taskId) return;
    
    const hours = parseFloat(duration);
    if (isNaN(hours) || hours <= 0) {
      toast.error('Please enter a valid duration in hours.');
      return;
    }

    setLoading(true);
    try {
      const { error } = await supabase.from('time_logs').insert({
        workspace_id: workspace.id,
        task_id: taskId,
        workspace_member_id: activeMember.id,
        log_date: date,
        duration: hours,
        description: description.trim() || null,
        billable: billable
      });

      if (error) throw error;

      toast.success('Time logged successfully!');
      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      console.error(err);
      toast.error('Failed to log time');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Log Time</DialogTitle>
        </DialogHeader>
        
        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="date">Date</Label>
              <Input
                id="date"
                type="date"
                value={date}
                onChange={(e) => setDate(e.target.value)}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="duration">Hours</Label>
              <Input
                id="duration"
                type="number"
                step="0.25"
                min="0.25"
                value={duration}
                onChange={(e) => setDuration(e.target.value)}
                placeholder="e.g. 2.5"
                required
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description (Optional)</Label>
            <Textarea plain
              id="description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="What did you work on?"
              className="resize-none h-20"
            />
          </div>

          <div className="flex items-center justify-between rounded-lg border border-border p-3">
            <div className="space-y-0.5">
              <Label>Billable</Label>
              <p className="text-[10px] text-muted-foreground">
                Include this time in client invoices
              </p>
            </div>
            <Switch checked={billable} onCheckedChange={setBillable} />
          </div>

          <DialogFooter className="pt-4">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? <Loader2 className="size-4 animate-spin mr-2" /> : null}
              Save Entry
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader2, Plus } from 'lucide-react';
import { TaskForm } from '@/components/tasks/task-form';
import { KanbanColumn } from './kanban-column';
import { KanbanTask } from './kanban-task';
import {
  DndContext,
  DragOverlay,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragStartEvent,
  DragEndEvent,
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { IconAction } from "@/components/ui/icon-action";

interface ProjectKanbanProps {
  projectId: string;
  canManage: boolean;
}

export function ProjectKanban({ projectId, canManage }: ProjectKanbanProps) {
  const supabase = createClient();

  const [columns, setColumns] = useState<any[]>([]);
  const [tasks, setTasks] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  
  const [newColumnName, setNewColumnName] = useState('');
  const [addingColumn, setAddingColumn] = useState(false);

  const [formOpen, setFormOpen] = useState(false);
  const [editTask, setEditTask] = useState<any | null>(null);
  const [, setDefaultStatusId] = useState<string | undefined>(undefined);
  
  const [activeDragTask, setActiveDragTask] = useState<any | null>(null);

  const fetchKanbanData = useCallback(async () => {
    if (!projectId) return;
    setLoading(true);

    const [statusesRes, tasksRes] = await Promise.all([
      supabase.from('project_statuses').select('*').eq('project_id', projectId).order('sort_order', { ascending: true }),
      supabase.from('tasks').select(`*, assignee:workspace_members!tasks_assigned_workspace_member_id_fkey ( id, user_id )`).eq('project_id', projectId).is('parent_id', null)
    ]);

    if (statusesRes.error) {
      toast.error('Failed to load workflow statuses');
    } else {
      let fetchedStatuses = statusesRes.data || [];
      if (fetchedStatuses.length === 0) {
        const defaultStatuses = [
          { project_id: projectId, name: 'To Do', category: 'TODO', sort_order: 1, color: 'slate' },
          { project_id: projectId, name: 'In Progress', category: 'IN_PROGRESS', sort_order: 2, color: 'blue' },
          { project_id: projectId, name: 'Done', category: 'DONE', sort_order: 3, color: 'emerald' },
        ];
        const { data: inserted, error: insErr } = await supabase.from('project_statuses').insert(defaultStatuses).select();
        if (insErr) {
          console.error('[ProjectKanban] error seeding default statuses:', insErr);
        } else if (inserted) {
          fetchedStatuses = inserted;
        }
      }
      setColumns(fetchedStatuses);
    }

    if (tasksRes.error) {
      toast.error('Failed to load tasks');
    } else {
      const taskList = tasksRes.data || [];
      if (taskList.length > 0) {
        const userIds = taskList.map((t: any) => t.assignee?.user_id).filter(Boolean);
        if (userIds.length > 0) {
          const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name, avatar_url').in('user_id', userIds);
          const profileMap = Object.fromEntries((profilesData || []).map((p: any) => [p.user_id, p]));
          taskList.forEach((t: any) => { if (t.assignee?.user_id) t.assignee.profiles = profileMap[t.assignee.user_id] || null; });
        }
      }
      setTasks(taskList);
    }

    setLoading(false);
  }, [supabase, projectId]);

  useEffect(() => {
    fetchKanbanData();
  }, [fetchKanbanData]);

  const addColumn = async () => {
    if (!newColumnName.trim()) return;
    setAddingColumn(true);
    try {
      const sortOrder = columns.length + 1;
      const { data, error } = await supabase
        .from('project_statuses')
        .insert({
          project_id: projectId,
          name: newColumnName.trim(),
          category: 'IN_PROGRESS',
          sort_order: sortOrder,
          color: 'slate',
        })
        .select()
        .single();

      if (error) throw error;
      setColumns((prev) => [...prev, data]);
      setNewColumnName('');
      toast.success('Column added');
    } catch (err: any) {
      toast.error(err.message || 'Failed to add column');
    } finally {
      setAddingColumn(false);
    }
  };

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 5,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    const task = tasks.find(t => t.id === active.id);
    setActiveDragTask(task);
  };

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveDragTask(null);

    if (!over) return;
    const taskId = active.id as string;
    const overId = over.id as string;

    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    // Resolve target status ID correctly whether dropped on column or task card
    let targetStatusId: string | null = null;
    if (overId === 'backlog') {
      targetStatusId = null;
    } else if (columns.some(col => col.id === overId)) {
      targetStatusId = overId;
    } else {
      const overTask = tasks.find(t => t.id === overId);
      if (overTask) {
        targetStatusId = overTask.status_id;
      } else {
        return;
      }
    }

    if (task.status_id === targetStatusId) return;

    const targetStatusObj = columns.find(c => c.id === targetStatusId);
    const legacyStatusText = targetStatusId === null ? 'backlog' : (targetStatusObj?.category?.toLowerCase() || 'in_progress');

    // Optimistic update
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status_id: targetStatusId } : t));

    try {
      // Try updating both status_id and status string to satisfy any legacy triggers
      const { error: err1 } = await supabase
        .from('tasks')
        .update({ status_id: targetStatusId, status: legacyStatusText })
        .eq('id', taskId);

      if (err1) {
        // Fallback to status_id update only
        const { error: err2 } = await supabase
          .from('tasks')
          .update({ status_id: targetStatusId })
          .eq('id', taskId);

        if (err2) throw err2;
      }
    } catch (err: any) {
      console.error('Drag end error:', err);
      toast.error('Failed to move task');
      fetchKanbanData(); // revert on fail
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <DndContext 
      sensors={sensors} 
      collisionDetection={closestCorners} 
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="flex gap-4 overflow-x-auto pb-4 h-[600px] items-start">
        
        {/* Backlog Column (Fixed) */}
        <KanbanColumn 
          id="backlog" 
          title="Backlog" 
          taskCount={tasks.filter(t => !t.status_id).length}
          onAddTask={() => { setEditTask(null); setDefaultStatusId(undefined); setFormOpen(true); }}
          canManage={canManage}
          isBacklog
        >
          {tasks.filter(t => !t.status_id).map(task => (
            <KanbanTask key={task.id} task={task} onEdit={() => { setEditTask(task); setFormOpen(true); }} />
          ))}
        </KanbanColumn>

        {/* Dynamic Columns (mapped to statuses) */}
        {columns.map(status => {
          const colTasks = tasks.filter(t => t.status_id === status.id);
          return (
            <KanbanColumn 
              key={status.id} 
              id={status.id} 
              title={status.name} 
              taskCount={colTasks.length}
              onAddTask={() => { setEditTask(null); setDefaultStatusId(status.id); setFormOpen(true); }}
              canManage={canManage}
            >
              {colTasks.map(task => (
                <KanbanTask key={task.id} task={task} onEdit={() => { setEditTask(task); setFormOpen(true); }} />
              ))}
            </KanbanColumn>
          );
        })}

        {/* Add Column Input & Button */}
        {canManage && (
          <div className="w-72 shrink-0 bg-card border border-dashed border-border rounded-lg p-3 flex flex-col gap-2">
            <Input
              placeholder="New Column Name..."
              value={newColumnName}
              onChange={(e) => setNewColumnName(e.target.value)}
              className="bg-background text-sm"
              onKeyDown={(e) => {
                if (e.key === 'Enter') addColumn();
              }}
            />
            <IconAction label="Add Column" icon={addingColumn ? <Loader2 className="size-3 animate-spin " /> : <Plus className="size-3 " />} variant="outline"
              onClick={addColumn}
              disabled={addingColumn || !newColumnName.trim()}
              className="w-full text-xs" />
          </div>
        )}
      </div>

      <DragOverlay>
        {activeDragTask ? <KanbanTask task={activeDragTask} onEdit={() => {}} isOverlay /> : null}
      </DragOverlay>

      <TaskForm
        open={formOpen}
        onOpenChange={setFormOpen}
        task={editTask}
        defaultProjectId={projectId}
        // Hack: TaskForm still expects defaultColumnId but we renamed it, so we pass defaultStatusId if we were to update TaskForm props, 
        // but wait, TaskForm doesn't take defaultStatusId. I should update TaskForm to accept it or just drop it.
        onSaved={fetchKanbanData}
      />
    </DndContext>
  );
}

