'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Loader2 } from 'lucide-react';
import { format, parseISO } from 'date-fns';

interface TaskTimeLogsProps {
  taskId: string;
}

export function TaskTimeLogs({ taskId }: TaskTimeLogsProps) {
  const supabase = createClient();
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchLogs = useCallback(async () => {
    if (!taskId) return;
    setLoading(true);
    
    const { data: rawData, error } = await supabase
      .from('time_logs')
      .select(`id, duration, log_date, billable, description, workspace_member_id, workspace_members:workspace_member_id ( id, user_id )`)
      .eq('task_id', taskId)
      .order('log_date', { ascending: false });

    if (!error && rawData && rawData.length > 0) {
      const userIds = rawData.map((l: any) => l.workspace_members?.user_id).filter(Boolean);
      const profileMap: Record<string, any> = {};
      if (userIds.length > 0) {
        const { data: profilesData } = await supabase.from('profiles').select('user_id, full_name').in('user_id', userIds);
        (profilesData || []).forEach((p: any) => { profileMap[p.user_id] = p; });
      }
      setLogs(rawData.map((l: any) => ({
        ...l,
        workspace_members: l.workspace_members ? { ...l.workspace_members, profiles: profileMap[l.workspace_members.user_id] || null } : null,
      })));
    } else if (!error) {
      setLogs([]);
    }
    setLoading(false);
  }, [taskId, supabase]);

  useEffect(() => {
    fetchLogs();
  }, [fetchLogs]);

  if (loading) {
    return <div className="flex justify-center py-8"><Loader2 className="size-5 animate-spin text-muted-foreground" /></div>;
  }

  if (logs.length === 0) {
    return <div className="text-center py-8 text-sm text-muted-foreground">No time logged for this task yet.</div>;
  }

  return (
    <div className="space-y-4">
      <div className="border rounded-md divide-y bg-card overflow-hidden">
        {logs.map(log => {
          const profile = log.workspace_members?.profiles;
          const memberName = Array.isArray(profile) ? profile[0]?.full_name : profile?.full_name;

          return (
            <div key={log.id} className="p-3 text-sm grid grid-cols-1 md:grid-cols-4 gap-2 items-center">
              <div>
                <span className="font-medium">{memberName || 'Unknown'}</span>
                <p className="text-xs text-muted-foreground">{format(parseISO(log.log_date), 'MMM d, yyyy')}</p>
              </div>
              <div className="md:col-span-2">
                <span className="text-muted-foreground">{log.description || 'No description'}</span>
              </div>
              <div className="text-right flex flex-col items-end">
                <span className="font-medium">{log.duration} hrs</span>
                {log.billable && <span className="text-[10px] uppercase bg-primary/10 text-primary px-1.5 py-0.5 rounded-none">Billable</span>}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { Loader2, Plus, Sparkles, Trash2, Clock, Calendar } from 'lucide-react';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { useWorkspace } from '@/hooks/use-workspace';
import { sanitizeErrorMessage } from '@/lib/commerce/barcode-utils';

interface LogEntryItem {
  id: string;
  taskId: string;
  hours: string;
  description: string;
  isBillable: boolean;
  showQuickTask: boolean;
  quickTaskTitle: string;
  creatingTask?: boolean;
}

interface TimeLogFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  defaultTaskId?: string;
  defaultHours?: string | number;
  onSaved: () => void;
}

export function TimeLogForm({ open, onOpenChange, defaultTaskId, defaultHours, onSaved }: TimeLogFormProps) {
  const supabase = createClient();
  const { activeWorkspace, activeMember } = useWorkspace();
  
  const [saving, setSaving] = useState(false);
  const [tasks, setTasks] = useState<any[]>([]);
  const [logDate, setLogDate] = useState('');

  // Multi-Entry Form State
  const [entries, setEntries] = useState<LogEntryItem[]>([]);

  useEffect(() => {
    if (open && activeWorkspace?.id && activeMember?.id) {
      // Fetch open tasks assigned to the user
      // `tasks` has no `status` column — completion is
      // project_statuses.category via status_id. The old .neq('status','DONE')
      // errored, so `data` was null and the task dropdown was always empty.
      // Filtered client-side rather than with .not('status_id','in',…) because
      // a task with no status set has status_id NULL, and NULL NOT IN (…)
      // yields NULL — which would silently drop unstatused tasks.
      supabase.from('tasks')
        .select('id, title, project_id, project:projects!tasks_project_id_fkey(name), status:project_statuses(category)')
        .eq('workspace_id', activeWorkspace.id)
        .eq('assigned_workspace_member_id', activeMember.id)
        .then(({ data }) =>
          setTasks(
            (data || []).filter(
              (t) => (t.status as { category?: string } | null)?.category !== 'DONE'
            )
          )
        );

      setLogDate(new Date().toISOString().split('T')[0]);
      
      // Initialize with default or single entry
      setEntries([
        {
          id: Math.random().toString(36).substring(2, 9),
          taskId: defaultTaskId || 'none',
          hours: defaultHours ? String(defaultHours) : '',
          description: '',
          isBillable: false,
          showQuickTask: false,
          quickTaskTitle: '',
        },
      ]);
    }
  }, [open, activeWorkspace?.id, activeMember?.id, defaultTaskId, defaultHours, supabase]);

  const addEntry = () => {
    setEntries((prev) => [
      ...prev,
      {
        id: Math.random().toString(36).substring(2, 9),
        taskId: 'none',
        hours: '',
        description: '',
        isBillable: false,
        showQuickTask: false,
        quickTaskTitle: '',
      },
    ]);
  };

  const removeEntry = (id: string) => {
    if (entries.length <= 1) return;
    setEntries((prev) => prev.filter((item) => item.id !== id));
  };

  const updateEntry = (id: string, updates: Partial<LogEntryItem>) => {
    setEntries((prev) =>
      prev.map((item) => (item.id === id ? { ...item, ...updates } : item))
    );
  };

  async function handleCreateQuickTaskForEntry(entryId: string) {
    const target = entries.find((e) => e.id === entryId);
    if (!target || !target.quickTaskTitle.trim()) {
      toast.error('Please enter a task title');
      return;
    }
    if (!activeWorkspace?.id || !activeMember?.id) return;

    updateEntry(entryId, { creatingTask: true });
    try {
      const payload: any = {
        workspace_id: activeWorkspace.id,
        created_by_workspace_member_id: activeMember.id,
        assigned_workspace_member_id: activeMember.id,
        title: target.quickTaskTitle.trim(),
        priority: 'MEDIUM',
      };

      let { data, error } = await supabase
        .from('tasks')
        .insert(payload)
        .select('id, title')
        .single();

      if (error && error.message?.includes('status')) {
        delete payload.status;
        const retry = await supabase
          .from('tasks')
          .insert({ ...payload, status: 'todo' })
          .select('id, title')
          .single();
        data = retry.data;
        error = retry.error;
      }

      if (error) throw error;
      if (!data) throw new Error('Failed to retrieve created task');

      toast.success(`Task "${data.title}" created & selected!`);
      setTasks((prev) => [data, ...prev]);
      updateEntry(entryId, {
        taskId: data.id,
        showQuickTask: false,
        quickTaskTitle: '',
      });
    } catch (err: any) {
      toast.error(sanitizeErrorMessage(err, 'Failed to create task'));
    } finally {
      updateEntry(entryId, { creatingTask: false });
    }
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    if (!logDate) {
      toast.error('Please select a date');
      return;
    }

    // Validate all entries
    for (let i = 0; i < entries.length; i++) {
      const entry = entries[i];
      const hrs = parseFloat(entry.hours);
      if (isNaN(hrs) || hrs <= 0) {
        toast.error(`Entry #${i + 1}: Please enter valid hours (e.g. 2.5)`);
        return;
      }
      if (!entry.taskId || entry.taskId === 'none') {
        toast.error(`Entry #${i + 1}: Please pick or create a task`);
        return;
      }
    }

    if (!activeWorkspace?.id || !activeMember?.id) return;

    setSaving(true);
    try {
      const timeLogPayloads = entries.map((entry) => ({
        workspace_id: activeWorkspace.id,
        workspace_member_id: activeMember.id,
        task_id: entry.taskId,
        log_date: logDate,
        duration: parseFloat(entry.hours),
        description: entry.description.trim() || null,
        billable: entry.isBillable,
      }));

      const { error } = await supabase.from('time_logs').insert(timeLogPayloads);
      if (error) throw error;

      const totalHours = entries.reduce((sum, e) => sum + parseFloat(e.hours || '0'), 0);
      toast.success(`Successfully logged ${entries.length} time ${entries.length === 1 ? 'entry' : 'entries'} (${totalHours.toFixed(1)} hrs total)!`);

      onSaved();
      onOpenChange(false);
    } catch (err: any) {
      const msg = sanitizeErrorMessage(err, 'Failed to save time entries');
      toast.error(msg);
    } finally {
      setSaving(false);
    }
  }

  const totalHours = entries.reduce((sum, e) => {
    const val = parseFloat(e.hours);
    return isNaN(val) ? sum : sum + val;
  }, 0);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-xl max-h-[90vh] flex flex-col p-0 overflow-hidden">
        
        {/* Modal Header */}
        <DialogHeader className="px-6 pt-5 pb-4 border-b border-border bg-card">
          <div className="flex items-center justify-between">
            <div>
              <DialogTitle className="text-lg font-bold text-foreground flex items-center gap-2">
                <Clock className="size-5 text-primary" /> Log Daily Time
              </DialogTitle>
              <p className="text-xs text-muted-foreground mt-0.5">
                Add multiple task entries for the day in a single submission.
              </p>
            </div>
            {totalHours > 0 && (
              <Badge variant="outline" className="bg-primary/10 text-primary border-primary/20 font-mono font-bold px-3 py-1 text-xs">
                Total: {totalHours.toFixed(2)} hrs
              </Badge>
            )}
          </div>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="flex-1 flex flex-col overflow-hidden">
          <div className="p-6 overflow-y-auto space-y-5 flex-1 max-h-[60vh]">
            
            {/* Global Date Input */}
            <div className="flex items-center justify-between gap-4 p-3.5 bg-muted/40 border border-border rounded-xl">
              <div className="flex items-center gap-2">
                <Calendar className="size-4 text-primary" />
                <Label className="text-sm font-semibold text-foreground">Log Date <span className="text-red-500">*</span></Label>
              </div>
              <Input
                type="date"
                value={logDate}
                onChange={(e) => setLogDate(e.target.value)}
                className="bg-card border-border text-foreground text-sm w-44 font-medium"
                required
              />
            </div>

            {/* Entries List */}
            <div className="space-y-4">
              {entries.map((entry, index) => (
                <div key={entry.id} className="p-4 bg-card border border-border rounded-xl space-y-3.5 relative shadow-xs group">
                  
                  {/* Card Entry Header */}
                  <div className="flex items-center justify-between border-b border-border/60 pb-2">
                    <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1.5">
                      <span className="size-5 rounded-full bg-primary/10 text-primary text-[10px] font-bold flex items-center justify-center">
                        {index + 1}
                      </span>
                      Entry #{index + 1}
                    </span>
                    <div className="flex items-center gap-2">
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => updateEntry(entry.id, { showQuickTask: !entry.showQuickTask })}
                        className="h-6 px-2 text-[11px] font-semibold text-primary hover:text-primary/80 hover:bg-primary/10 gap-1 rounded-md"
                      >
                        <Plus className="size-3" />
                        {entry.showQuickTask ? 'Select Task' : 'Create Task'}
                      </Button>
                      {entries.length > 1 && (
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          onClick={() => removeEntry(entry.id)}
                          className="size-6 text-muted-foreground hover:text-red-600 hover:bg-red-500/10 rounded-md"
                          title="Remove entry"
                        >
                          <Trash2 className="size-3.5" />
                        </Button>
                      )}
                    </div>
                  </div>

                  {/* Task Selector / Quick Task */}
                  {entry.showQuickTask ? (
                    <div className="p-3 bg-muted/50 border border-primary/20 rounded-xl space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-xs font-semibold text-foreground flex items-center gap-1.5">
                          <Sparkles className="size-3.5 text-primary" /> Create New Task
                        </span>
                        <Badge variant="outline" className="text-[10px] bg-primary/10 text-primary border-primary/20">
                          Quick Add
                        </Badge>
                      </div>
                      <div className="flex gap-2">
                        <Input
                          value={entry.quickTaskTitle}
                          onChange={(e) => updateEntry(entry.id, { quickTaskTitle: e.target.value })}
                          placeholder="Task title (e.g., Client Meeting / Bug Fix)..."
                          className="bg-card border-border text-foreground text-xs h-9"
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                              e.preventDefault();
                              handleCreateQuickTaskForEntry(entry.id);
                            }
                          }}
                        />
                        <Button
                          type="button"
                          size="sm"
                          disabled={entry.creatingTask || !entry.quickTaskTitle.trim()}
                          onClick={() => handleCreateQuickTaskForEntry(entry.id)}
                          className="h-9 px-3 text-xs font-semibold bg-primary hover:bg-primary/90 text-primary-foreground shrink-0 rounded-lg"
                        >
                          {entry.creatingTask ? <Loader2 className="size-3.5 animate-spin" /> : 'Create'}
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <div>
                      <Select
                        value={entry.taskId}
                        onValueChange={(val) => {
                          if (val === 'create_new_task') {
                            updateEntry(entry.id, { showQuickTask: true });
                          } else {
                            updateEntry(entry.id, { taskId: val });
                          }
                        }}
                      >
                        <SelectTrigger className="bg-background border-border text-sm font-medium">
                          <SelectValue placeholder="-- Select a task --">
                            {(val: any) => {
                              if (!val || val === 'none') return '-- Select a task --';
                              const taskObj = tasks.find((t) => t.id === val);
                              if (taskObj) {
                                return `${taskObj.title}${taskObj.project?.name ? ` (${taskObj.project.name})` : ''}`;
                              }
                              return '-- Select a task --';
                            }}
                          </SelectValue>
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="none">-- Select a task --</SelectItem>
                          <SelectItem value="create_new_task" className="text-primary font-semibold">
                            + Create New Task
                          </SelectItem>
                          {tasks.map((t) => (
                            <SelectItem key={t.id} value={t.id}>
                              {t.title} {t.project ? `(${t.project.name})` : ''}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}

                  {/* Hours & Billable Row */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 items-center">
                    <div>
                      <Label className="text-xs font-medium text-foreground">Hours Logged <span className="text-red-500">*</span></Label>
                      <Input
                        type="number"
                        step="0.25"
                        min="0.1"
                        max="24"
                        value={entry.hours}
                        onChange={(e) => updateEntry(entry.id, { hours: e.target.value })}
                        placeholder="e.g. 2.5"
                        className="bg-background border-border text-foreground font-semibold text-sm h-9 mt-1"
                        required
                      />
                    </div>
                    <div className="flex items-center justify-between sm:justify-start sm:gap-3 pt-5">
                      <Switch
                        id={`billable-${entry.id}`}
                        checked={entry.isBillable}
                        onCheckedChange={(val) => updateEntry(entry.id, { isBillable: val })}
                      />
                      <Label htmlFor={`billable-${entry.id}`} className="text-xs text-muted-foreground cursor-pointer select-none">
                        Billable time
                      </Label>
                    </div>
                  </div>

                  {/* Description */}
                  <div>
                    <Label className="text-xs font-medium text-foreground">Description (Optional)</Label>
                    <Textarea plain
                      value={entry.description}
                      onChange={(e) => updateEntry(entry.id, { description: e.target.value })}
                      placeholder="What did you work on for this task?"
                      className="bg-background border-border text-foreground resize-none text-xs h-16 mt-1"
                    />
                  </div>
                </div>
              ))}
            </div>

            {/* Add Another Entry Button */}
            <Button
              type="button"
              variant="outline"
              onClick={addEntry}
              className="w-full py-2.5 text-xs font-bold border-dashed border-primary/30 text-primary hover:bg-primary/5 hover:border-primary/50 gap-2 rounded-xl"
            >
              <Plus className="size-4" /> Add Another Task Entry
            </Button>
          </div>

          {/* Footer Actions */}
          <DialogFooter className="px-6 py-4 border-t border-border bg-card flex items-center justify-between gap-3">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="border-border text-muted-foreground hover:bg-muted"
              disabled={saving}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              className="bg-primary hover:bg-primary/90 text-primary-foreground font-bold px-5"
              disabled={saving}
            >
              {saving && <Loader2 className="size-4 animate-spin mr-2" />}
              {saving
                ? 'Saving Entries...'
                : entries.length > 1
                ? `Save All ${entries.length} Entries (${totalHours.toFixed(1)} hrs)`
                : 'Save Entry'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import {
  Bold,
  Italic,
  Underline,
  Strikethrough,
  List,
  ListOrdered,
  Heading1,
  Heading2,
  Heading3,
  Quote,
  Code,
  Link as LinkIcon,
  RotateCcw,
  RotateCw,
  RemoveFormatting,
} from "lucide-react";
import { Button } from "./button";
import { cn } from "@/lib/utils";
import { normalisePastedHtml } from "@/lib/paste-normalise";
import {
  textDraftKey,
  parseTextDraft,
  serializeTextDraft,
  describeAge,
} from "@/lib/tables/draft-storage";
import { markdownToHtml, sanitizeHtml } from "@/lib/markdown-utils";

interface RichTextEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  minHeight?: string;
  disabled?: boolean;
  /**
   * Distinguishes this editor's draft from others on the same page. Only
   * needed when a page has more than one rich editor; otherwise the route
   * is enough.
   */
  draftScope?: string;
  /** Set false for a field where local recovery is unwanted. */
  autosave?: boolean;
}


/**
 * Toolbar button.
 *
 * `onMouseDown` preventDefault is the load-bearing part: without it,
 * pressing a toolbar button moves focus to the button and the browser
 * DISCARDS the contentEditable selection. execCommand then has no range
 * to act on, so heading, list, bold — everything needing a selection —
 * silently did nothing. Re-focusing afterwards does not help, because the
 * range is already gone.
 *
 * Declared at module scope, not inside the editor: a component created
 * during render is a new type on every keystroke, which remounts every
 * button and throws away their DOM state.
 */
function ToolbarButton({
  onAction,
  label,
  disabled,
  className,
  children,
}: {
  onAction: () => void;
  label: string;
  disabled?: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      title={label}
      aria-label={label}
      disabled={disabled}
      className={cn("size-8 p-0", className)}
      onMouseDown={(e) => e.preventDefault()}
      onClick={onAction}
    >
      {children}
    </Button>
  );
}

export function RichTextEditor({
  draftScope,
  autosave = true,
  value,
  onChange,
  placeholder = "Write content here...",
  className = "",
  minHeight = "160px",
  disabled = false,
}: RichTextEditorProps) {
  const editorRef = useRef<HTMLDivElement>(null);
  const isUpdatingRef = useRef(false);
  const [isFocused, setIsFocused] = useState(false);

  // Synchronize internal innerHTML when external `value` prop changes
  useEffect(() => {
    if (!editorRef.current) return;
    if (isUpdatingRef.current) {
      isUpdatingRef.current = false;
      return;
    }
    const formattedHtml = markdownToHtml(value || "");
    if (editorRef.current.innerHTML !== formattedHtml) {
      editorRef.current.innerHTML = formattedHtml;
    }
  }, [value]);

  /**
   * Crash recovery for long-form text.
   *
   * Motivating incident: someone typed a long policy, the tab closed, and
   * the work was gone with no way to recover it. Every rich editor now
   * keeps a local draft as you type.
   *
   * Two deliberate constraints:
   *  * The draft is OFFERED, never auto-applied. Silently replacing what
   *    the server sent could let a stale draft clobber a colleague's newer
   *    edit, and the person would never know.
   *  * The key is derived from the route so this works with no changes at
   *    any of the 31 call sites. `draftScope` disambiguates a page with
   *    more than one editor.
   */
  const scope =
    draftScope ??
    (typeof window !== "undefined" ? `${window.location.pathname}:${placeholder ?? "body"}` : "");
  const storageKey = textDraftKey(scope);

  const [recovered, setRecovered] = useState<{ html: string; at: number; baseChanged: boolean } | null>(null);
  const [draftDismissed, setDraftDismissed] = useState(false);
  const [blockValue, setBlockValue] = useState("p");
  const [fontSizeValue, setFontSizeValue] = useState("3");
  // Position of the floating selection toolbar, null when nothing is selected.
  const [bubble, setBubble] = useState<{ top: number; left: number } | null>(null);
  // What the server gave us when this editor mounted, so a draft can tell
  // whether the underlying record has since changed.
  const baseValueRef = useRef(value);

  // Offer any surviving draft once, on mount.
  useEffect(() => {
    if (!autosave || disabled || typeof window === "undefined") return;
    const found = parseTextDraft(window.localStorage.getItem(storageKey), value, Date.now());
    if (found) setRecovered(found);
    // Intentionally mount-only: re-running as `value` changes would keep
    // re-offering a draft the user has already dismissed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Persist as the user types, debounced so we are not writing per keystroke.
  useEffect(() => {
    if (!autosave || disabled || typeof window === "undefined") return;
    const t = setTimeout(() => {
      const payload = serializeTextDraft(value, baseValueRef.current, Date.now());
      if (payload) window.localStorage.setItem(storageKey, payload);
      // Content now matches what was loaded — it has been saved, so stop
      // holding a draft that would nag on the next visit.
      else window.localStorage.removeItem(storageKey);
    }, 600);
    return () => clearTimeout(t);
  }, [value, autosave, disabled, storageKey]);

  /**
   * Show the floating toolbar over a non-empty selection inside this
   * editor, so formatting is reachable without scrolling to the top of a
   * long document.
   */
  const updateBubble = () => {
    if (disabled || typeof window === "undefined") return;
    const sel = window.getSelection();
    if (!sel || sel.isCollapsed || sel.rangeCount === 0) {
      setBubble(null);
      return;
    }
    const range = sel.getRangeAt(0);
    // Only for selections that belong to THIS editor — several can be on
    // one page.
    if (!editorRef.current?.contains(range.commonAncestorContainer)) {
      setBubble(null);
      return;
    }
    const rect = range.getBoundingClientRect();
    const host = editorRef.current.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) {
      setBubble(null);
      return;
    }
    setBubble({
      // Relative to the editor shell, which is the positioning context.
      top: rect.top - host.top - 44,
      left: Math.max(4, rect.left - host.left + rect.width / 2 - 90),
    });
    setBlockValue(currentBlock());
  };

  useEffect(() => {
    if (disabled) return;
    const onSelectionChange = () => updateBubble();
    document.addEventListener("selectionchange", onSelectionChange);
    return () => document.removeEventListener("selectionchange", onSelectionChange);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [disabled]);

  const handleInput = () => {
    if (!editorRef.current) return;
    isUpdatingRef.current = true;
    const html = editorRef.current.innerHTML;
    // Clean empty breaks
    const cleanHtml = html === "<br>" || html === "<div><br></div>" ? "" : html;
    onChange(cleanHtml);
  };

  /**
   * A contenteditable accepts the clipboard's full HTML, so pasting
   * from a web page or Word can carry scripts, event handlers and a
   * mountain of foreign styling. Insert an allowlisted version
   * instead. Rendering sanitises again (defence in depth), but
   * cleaning here keeps what we *store* clean too.
   */
  const handlePaste = (e: React.ClipboardEvent<HTMLDivElement>) => {
    if (disabled) return;
    const html = e.clipboardData.getData("text/html");
    const text = e.clipboardData.getData("text/plain");
    if (!html && !text) return;
    e.preventDefault();
    if (html) {
      document.execCommand("insertHTML", false, sanitizeHtml(normalisePastedHtml(html)));
    } else {
      document.execCommand("insertText", false, text);
    }
    handleInput();
  };

  const exec = (command: string, value: string | undefined = undefined) => {
    if (disabled) return;
    editorRef.current?.focus();
    // THE fix for "bold does not survive a save". With styleWithCSS on —
    // which is the default in some engines and gets switched on implicitly
    // by other operations — the browser emits
    // `<span style="font-weight:700">` instead of `<b>`. The sanitiser
    // strips `style` (correctly; it carries url() and expression()), so the
    // formatting was thrown away on save and came back plain. Off, the
    // browser emits semantic tags, which the allowlist keeps.
    try {
      document.execCommand("styleWithCSS", false, "false");
    } catch {
      // Not supported everywhere; the command below still runs.
    }
    document.execCommand(command, false, value);
    handleInput();
  };

  /** Font size 1–7 as execCommand understands it, labelled in points. */
  const FONT_SIZES: { value: string; label: string }[] = [
    { value: "1", label: "8 pt" },
    { value: "2", label: "10 pt" },
    { value: "3", label: "12 pt" },
    { value: "4", label: "14 pt" },
    { value: "5", label: "18 pt" },
    { value: "6", label: "24 pt" },
    { value: "7", label: "36 pt" },
  ];

  const BLOCK_OPTIONS: { value: string; label: string }[] = [
    { value: "p", label: "Normal text" },
    { value: "h1", label: "Heading 1" },
    { value: "h2", label: "Heading 2" },
    { value: "h3", label: "Heading 3" },
    { value: "blockquote", label: "Quote" },
    { value: "pre", label: "Code block" },
  ];

  /** The block tag the caret currently sits in, for the dropdown. */
  const currentBlock = (): string => {
    try {
      const v = (document.queryCommandValue("formatBlock") || "").toLowerCase().replace(/[<>]/g, "");
      return BLOCK_OPTIONS.some((o) => o.value === v) ? v : "p";
    } catch {
      return "p";
    }
  };

  /**
   * Sets the block directly rather than toggling. A dropdown showing the
   * current value makes "turn this heading back into normal text" an
   * explicit choice — pressing an H1 button to undo an H1 was the part
   * people could not find.
   */
  const applyBlock = (tag: string) => {
    if (disabled) return;
    editorRef.current?.focus();
    try {
      document.execCommand("styleWithCSS", false, "false");
    } catch {
      /* ignore */
    }
    document.execCommand("formatBlock", false, tag);
    handleInput();
    setBlockValue(tag);
  };

  /**
   * Block formatting is a TOGGLE, not a one-way apply.
   *
   * Calling formatBlock("h1") on a selection that is already an h1
   * produced nested `<h1><h1>…</h1></h1>`, and that malformed nesting
   * then broke later commands — a bullet list applied over it silently
   * did nothing. Pressing the active heading now returns the block to a
   * paragraph, which is what every editor does and what stops the
   * nesting.
   */
  const toggleBlock = (tag: string) => {
    if (disabled) return;
    editorRef.current?.focus();
    let current = "";
    try {
      current = (document.queryCommandValue("formatBlock") || "").toLowerCase();
    } catch {
      current = "";
    }
    // Engines report this as either "h1" or "<h1>".
    const normalised = current.replace(/[<>]/g, "");
    document.execCommand("formatBlock", false, normalised === tag ? "p" : tag);
    handleInput();
  };

  const handleAddLink = () => {
    if (disabled) return;
    const url = prompt("Enter URL:", "https://");
    if (url) {
      exec("createLink", url);
    }
  };

  const isEmpty = !value || value === "<br>" || value === "<div><br></div>";

  return (
    <div
      className={`relative rounded-md border border-input bg-card shadow-sm transition-colors ${
        isFocused ? "ring-2 ring-ring border-transparent" : ""
      } ${disabled ? "opacity-60 pointer-events-none" : ""} ${className}`}
    >
      {recovered && !draftDismissed && (
        <div className="flex flex-wrap items-center gap-2 border-b border-amber-500/25 bg-amber-500/10 px-2 py-1.5 text-[11px] text-amber-800 dark:text-amber-300">
          <RotateCcw className="size-3.5 shrink-0" />
          <span className="min-w-0 flex-1">
            Unsaved text from {describeAge(recovered.at, Date.now())} was recovered
            {recovered.baseChanged
              ? " — but this record has changed since, so restoring will replace the current text."
              : "."}
          </span>
          <button
            type="button"
            onClick={() => {
              // Applied only on request: the draft may be older than what
              // the server now holds.
              onChange(recovered.html);
              if (editorRef.current) editorRef.current.innerHTML = recovered.html;
              setDraftDismissed(true);
            }}
            className="shrink-0 rounded-md bg-amber-600 px-2 py-1 font-medium text-white"
          >
            Restore it
          </button>
          <button
            type="button"
            onClick={() => {
              if (typeof window !== "undefined") window.localStorage.removeItem(storageKey);
              setDraftDismissed(true);
            }}
            className="shrink-0 rounded-md px-2 py-1 font-medium underline"
          >
            Discard
          </button>
        </div>
      )}

      {/* Toolbar. `sticky` so it stays reachable partway down a long
          document instead of forcing a scroll back to the top. It sticks to
          the top of the nearest scroll container, which is the editor's own
          overflow area or the dialog body. */}
      <div className="sticky top-0 z-20 flex flex-wrap items-center gap-1 rounded-t-md border-b border-border/80 bg-muted/95 p-1.5 text-foreground backdrop-blur supports-[backdrop-filter]:bg-muted/80">
        <ToolbarButton onAction={() => exec("bold")} label="Bold (Ctrl+B)" disabled={disabled}>
          <Bold className="size-4" />
        </ToolbarButton>
        <ToolbarButton onAction={() => exec("italic")} label="Italic (Ctrl+I)" disabled={disabled}>
          <Italic className="size-4" />
        </ToolbarButton>
        <ToolbarButton onAction={() => exec("underline")} label="Underline (Ctrl+U)" disabled={disabled}>
          <Underline className="size-4" />
        </ToolbarButton>
        <ToolbarButton onAction={() => exec("strikeThrough")} label="Strikethrough" disabled={disabled}>
          <Strikethrough className="size-4" />
        </ToolbarButton>

        <div className="h-4 w-px bg-border mx-0.5" />

        <select
          aria-label="Paragraph style"
          value={blockValue}
          disabled={disabled}
          onMouseDown={(e) => e.stopPropagation()}
          onChange={(e) => applyBlock(e.target.value)}
          className="h-7 rounded-md border border-input bg-background px-1.5 text-[11px]"
        >
          {BLOCK_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>

        <select
          aria-label="Font size"
          value={fontSizeValue}
          disabled={disabled}
          onChange={(e) => {
            setFontSizeValue(e.target.value);
            exec("fontSize", e.target.value);
          }}
          className="h-7 rounded-md border border-input bg-background px-1.5 text-[11px]"
        >
          {FONT_SIZES.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>


        <div className="h-4 w-px bg-border mx-0.5" />

        <ToolbarButton onAction={() => exec("insertUnorderedList")} label="Bullet List" disabled={disabled}>
          <List className="size-4" />
        </ToolbarButton>
        <ToolbarButton onAction={() => exec("insertOrderedList")} label="Numbered List" disabled={disabled}>
          <ListOrdered className="size-4" />
        </ToolbarButton>
        <ToolbarButton onAction={() => toggleBlock("blockquote")} label="Quote" disabled={disabled}>
          <Quote className="size-4" />
        </ToolbarButton>
        <ToolbarButton onAction={() => toggleBlock("pre")} label="Code Block" disabled={disabled}>
          <Code className="size-4" />
        </ToolbarButton>

        <div className="h-4 w-px bg-border mx-0.5" />

        <ToolbarButton onAction={handleAddLink} label="Insert Link" disabled={disabled}>
          <LinkIcon className="size-4" />
        </ToolbarButton>
        <ToolbarButton onAction={() => exec("removeFormat")} label="Clear Formatting" disabled={disabled}>
          <RemoveFormatting className="size-4" />
        </ToolbarButton>

        <div className="ml-auto flex items-center gap-0.5">
          <ToolbarButton onAction={() => exec("undo")} label="Undo" disabled={disabled}>
            <RotateCcw className="size-3.5" />
          </ToolbarButton>
          <ToolbarButton onAction={() => exec("redo")} label="Redo" disabled={disabled}>
            <RotateCw className="size-3.5" />
          </ToolbarButton>
        </div>
      </div>

      {/* Editor Content Area */}
      <div className="relative p-3">
        {isEmpty && !isFocused && (
          <div className="pointer-events-none absolute left-3 top-3 text-xs text-muted-foreground select-none">
            {placeholder}
          </div>
        )}
        {bubble && !disabled && (
          <div
            // Appears over the selection so formatting is reachable in a
            // long document without going back to the toolbar.
            style={{ top: bubble.top, left: bubble.left }}
            className="absolute z-30 flex items-center gap-0.5 rounded-lg border border-border bg-popover px-1 py-0.5 shadow-lg"
            // Keep the selection alive: any focus change would collapse it
            // and leave execCommand with nothing to act on.
            onMouseDown={(e) => e.preventDefault()}
          >
            <ToolbarButton onAction={() => exec("bold")} label="Bold" disabled={disabled}>
              <Bold className="size-3.5" />
            </ToolbarButton>
            <ToolbarButton onAction={() => exec("italic")} label="Italic" disabled={disabled}>
              <Italic className="size-3.5" />
            </ToolbarButton>
            <ToolbarButton onAction={() => exec("underline")} label="Underline" disabled={disabled}>
              <Underline className="size-3.5" />
            </ToolbarButton>
            <div className="mx-0.5 h-4 w-px bg-border" />
            <select
              aria-label="Paragraph style"
              value={blockValue}
              onChange={(e) => applyBlock(e.target.value)}
              className="h-6 rounded border border-input bg-background px-1 text-[11px]"
            >
              {BLOCK_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>{o.label}</option>
              ))}
            </select>
            <select
              aria-label="Font size"
              value={fontSizeValue}
              onChange={(e) => {
                setFontSizeValue(e.target.value);
                exec("fontSize", e.target.value);
              }}
              className="h-6 rounded border border-input bg-background px-1 text-[11px]"
            >
              {FONT_SIZES.map((o) => (
                <option key={o.value} value={o.value}>{o.label}</option>
              ))}
            </select>
            <ToolbarButton onAction={handleAddLink} label="Insert link" disabled={disabled}>
              <LinkIcon className="size-3.5" />
            </ToolbarButton>
          </div>
        )}

        <div
          ref={editorRef}
          contentEditable={!disabled}
          onInput={handleInput}
          onPaste={handlePaste}
          onFocus={() => setIsFocused(true)}
          onBlur={() => {
            setIsFocused(false);
            // Delayed: clicking the bubble itself blurs the editor, and
            // removing it immediately would cancel the click.
            setTimeout(() => setBubble(null), 200);
          }}
          onKeyUp={updateBubble}
          onMouseUp={updateBubble}
          style={{ minHeight }}
          className="rich-text max-w-none overflow-y-auto text-xs leading-relaxed focus:outline-none"
        />
      </div>
    </div>
  );
}

"use client"

import * as React from "react"
import { Select as SelectPrimitive } from "@base-ui/react/select"

import { cn } from "@/lib/utils"
import { ChevronDownIcon, CheckIcon, ChevronUpIcon, SearchIcon } from "lucide-react"

interface SelectContextType {
  labelsMap: Map<string, string>;
  registerLabel: (value: string, label: string) => void;
  /** Current search text. Empty string = no filtering. */
  query: string;
  setQuery: (q: string) => void;
}

const SelectContext = React.createContext<SelectContextType | null>(null);

/**
 * Case- and whitespace-insensitive substring match. Kept here so the
 * item filter and the "no results" count can never disagree.
 */
function matchesQuery(label: string | undefined, query: string): boolean {
  if (!query.trim()) return true;
  // An item whose label we can't read stays visible — better a stray
  // row than silently hiding a selectable option.
  if (!label) return true;
  return label.toLowerCase().includes(query.trim().toLowerCase());
}

function Select({ children, onOpenChange, ...props }: SelectPrimitive.Root.Props<any>) {
  const [labelsMap, setLabelsMap] = React.useState<Map<string, string>>(() => new Map());
  const [query, setQuery] = React.useState("");

  const registerLabel = React.useCallback((value: string, label: string) => {
    setLabelsMap((prev) => {
      if (prev.get(value) === label) return prev;
      const next = new Map(prev);
      next.set(value, label);
      return next;
    });
  }, []);

  // Reset the filter whenever the popup closes, so reopening always
  // shows the full list rather than the previous search.
  const handleOpenChange = React.useCallback(
    (open: boolean, eventDetails: any) => {
      if (!open) setQuery("");
      onOpenChange?.(open, eventDetails);
    },
    [onOpenChange]
  );

  return (
    <SelectContext.Provider value={{ labelsMap, registerLabel, query, setQuery }}>
      <SelectPrimitive.Root onOpenChange={handleOpenChange} {...props}>
        {children}
      </SelectPrimitive.Root>
    </SelectContext.Provider>
  );
}

function SelectGroup({ className, ...props }: SelectPrimitive.Group.Props) {
  return (
    <SelectPrimitive.Group
      data-slot="select-group"
      className={cn("scroll-my-1 p-1", className)}
      {...props}
    />
  )
}

function SelectValue({
  className,
  placeholder,
  children,
  ...props
}: SelectPrimitive.Value.Props & { placeholder?: string }) {
  const ctx = React.useContext(SelectContext);

  return (
    <SelectPrimitive.Value
      data-slot="select-value"
      className={cn("flex flex-1 text-left", className)}
      {...props}
    >
      {(val: any) => {
        if (children) {
          if (typeof children === "function") {
            return (children as any)(val);
          }
          return children;
        }
        if (val === undefined || val === null || val === "" || val === "none") {
          if (val === "none" && ctx?.labelsMap.has("none")) {
            return ctx.labelsMap.get("none");
          }
          return placeholder;
        }
        const valStr = String(val);
        const mappedLabel = ctx?.labelsMap.get(valStr);
        if (mappedLabel) return mappedLabel;
        if (/^[0-9a-fA-F-]{32,36}$/.test(valStr)) {
          return placeholder ?? "-- Select --";
        }
        return valStr;
      }}
    </SelectPrimitive.Value>
  )
}

function SelectTrigger({
  className,
  size = "default",
  children,
  ...props
}: SelectPrimitive.Trigger.Props & {
  size?: "sm" | "default"
}) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      data-size={size}
      className={cn(
        "flex w-full items-center justify-between gap-1.5 rounded-none border border-input bg-transparent py-2 pr-2 pl-2.5 text-sm whitespace-nowrap transition-colors outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 data-placeholder:text-muted-foreground data-[size=default]:h-9 data-[size=sm]:h-8 *:data-[slot=select-value]:line-clamp-1 *:data-[slot=select-value]:flex *:data-[slot=select-value]:items-center *:data-[slot=select-value]:gap-1.5 dark:bg-input/30 dark:hover:bg-input/50 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      {children}
      <ChevronDownIcon className="pointer-events-none size-4 text-muted-foreground shrink-0 opacity-70" />
    </SelectPrimitive.Trigger>
  )
}

/** Keys that must reach Base UI so the list stays navigable from the
 *  search box. Everything else is text input and is kept local. */
const NAV_KEYS = new Set([
  "ArrowDown",
  "ArrowUp",
  "Enter",
  "Escape",
  "Tab",
  "PageDown",
  "PageUp",
  "Home",
  "End",
]);

function SelectSearch({ placeholder }: { placeholder?: string }) {
  const ctx = React.useContext(SelectContext);
  const inputRef = React.useRef<HTMLInputElement>(null);

  // Base UI focuses the selected item when the popup opens, so claim
  // focus on the next frame instead of fighting it with autoFocus.
  React.useEffect(() => {
    const raf = requestAnimationFrame(() => inputRef.current?.focus());
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div
      data-slot="select-search"
      className="sticky top-0 z-20 flex items-center gap-1.5 border-b border-border bg-popover px-2"
    >
      <SearchIcon className="size-3.5 shrink-0 text-muted-foreground" />
      <input
        ref={inputRef}
        type="text"
        value={ctx?.query ?? ""}
        onChange={(e) => ctx?.setQuery(e.target.value)}
        placeholder={placeholder ?? "Search..."}
        // Base UI's Select runs a typeahead that jumps to items as you
        // type; without this it would swallow every keystroke meant
        // for this box. Navigation keys are deliberately let through.
        onKeyDown={(e) => {
          if (!NAV_KEYS.has(e.key)) e.stopPropagation();
        }}
        className="h-8 w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground"
        aria-label={placeholder ?? "Search options"}
      />
    </div>
  );
}

function SelectEmpty() {
  const ctx = React.useContext(SelectContext);
  const query = ctx?.query ?? "";
  if (!query.trim() || !ctx || ctx.labelsMap.size === 0) return null;
  const anyMatch = [...ctx.labelsMap.values()].some((l) => matchesQuery(l, query));
  if (anyMatch) return null;
  return (
    <div className="px-2.5 py-4 text-center text-sm text-muted-foreground">
      No results found.
    </div>
  );
}

function SelectContent({
  className,
  children,
  side = "bottom",
  sideOffset = 4,
  align = "start",
  alignOffset = 0,
  alignItemWithTrigger = false,
  searchable = true,
  searchPlaceholder,
  ...props
}: SelectPrimitive.Popup.Props &
  Pick<
    SelectPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset" | "alignItemWithTrigger"
  > & {
    /** Every dropdown is searchable by default; opt out per-use. */
    searchable?: boolean
    searchPlaceholder?: string
  }) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        alignItemWithTrigger={alignItemWithTrigger}
        className="isolate z-50"
      >
        <SelectPrimitive.Popup
          data-slot="select-content"
          data-align-trigger={alignItemWithTrigger}
          className={cn("relative isolate z-50 max-h-(--available-height) min-w-(--anchor-width) w-max max-w-md origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-none bg-popover text-popover-foreground shadow-md ring-1 ring-foreground/10 duration-100 data-[align-trigger=true]:animate-none data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95", className )}
          {...props}
        >
          {searchable ? <SelectSearch placeholder={searchPlaceholder} /> : null}
          <SelectScrollUpButton />
          <SelectPrimitive.List>{children}</SelectPrimitive.List>
          {searchable ? <SelectEmpty /> : null}
          <SelectScrollDownButton />
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  )
}

function SelectLabel({
  className,
  ...props
}: SelectPrimitive.GroupLabel.Props) {
  return (
    <SelectPrimitive.GroupLabel
      data-slot="select-label"
      className={cn("px-1.5 py-1 text-xs text-muted-foreground", className)}
      {...props}
    />
  )
}

/**
 * Flatten an item's children into searchable text. Recurses through
 * elements (not just strings and arrays) so that items rendering an
 * icon beside a label — or wrapping the label in a span — are still
 * matchable by the search filter.
 */
function getLabelFromChildren(children: React.ReactNode): string | undefined {
  if (typeof children === "string" || typeof children === "number") {
    return String(children);
  }
  if (Array.isArray(children)) {
    const text = children.map(getLabelFromChildren).filter(Boolean).join(" ").trim();
    return text || undefined;
  }
  if (React.isValidElement(children)) {
    const nested = (children.props as { children?: React.ReactNode })?.children;
    return nested === undefined ? undefined : getLabelFromChildren(nested);
  }
  return undefined;
}

function SelectItem({
  className,
  children,
  value,
  label,
  ...props
}: SelectPrimitive.Item.Props & { label?: string }) {
  const ctx = React.useContext(SelectContext);
  const itemLabel = label ?? getLabelFromChildren(children);

  React.useEffect(() => {
    if (ctx && value !== undefined && itemLabel) {
      ctx.registerLabel(String(value), itemLabel);
    }
  }, [ctx, value, itemLabel]);

  // Unmount rather than hide non-matching items: a hidden-but-mounted
  // option stays reachable by Base UI's keyboard navigation, which
  // would let you arrow onto an item the filter says isn't there.
  // The effect above still runs first, so the label stays registered
  // for rendering the trigger's selected value.
  if (!matchesQuery(itemLabel, ctx?.query ?? "")) return null;

  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      value={value}
      label={itemLabel}
      className={cn(
        "relative flex w-full cursor-default items-center gap-1.5 rounded-md py-1 pr-8 pl-1.5 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground not-data-[variant=destructive]:focus:**:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 *:[span]:last:flex *:[span]:last:items-center *:[span]:last:gap-2",
        className
      )}
      {...props}
    >
      <SelectPrimitive.ItemText className="flex flex-1 shrink-0 gap-2 whitespace-nowrap">
        {children}
      </SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator
        render={
          <span className="pointer-events-none absolute right-2 flex size-4 items-center justify-center" />
        }
      >
        <CheckIcon className="pointer-events-none" />
      </SelectPrimitive.ItemIndicator>
    </SelectPrimitive.Item>
  )
}

function SelectSeparator({
  className,
  ...props
}: SelectPrimitive.Separator.Props) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn("pointer-events-none -mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  )
}

function SelectScrollUpButton({
  className,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.ScrollUpArrow>) {
  return (
