"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Sound + desktop notifications for incoming customer messages.
 *
 * Design notes:
 *
 * - The alert tone is synthesised with the Web Audio API rather than
 *   shipped as an audio file: no binary asset in the repo, no network
 *   request, and it works offline.
 * - Browsers only allow `Notification.requestPermission()` and starting
 *   an AudioContext from a user gesture, so both happen when the user
 *   flips the toggle — never on mount. An AudioContext created without
 *   a gesture starts `suspended` and would play nothing.
 * - The preference is persisted, but permission is authoritative: if
 *   the user later revokes notification permission in the browser, we
 *   fall back to sound only rather than silently doing nothing.
 */

const STORAGE_KEY = "dailycrm.notifications.enabled";

export type NotificationPermissionState =
  | "unsupported"
  | "default"
  | "granted"
  | "denied";

function readStoredEnabled(): boolean {
  try {
    return window.localStorage.getItem(STORAGE_KEY) === "true";
  } catch {
    return false;
  }
}

/** Two-tone chime, WhatsApp-ish: short, quiet, non-annoying. */
function playChime(ctx: AudioContext) {
  const now = ctx.currentTime;
  const master = ctx.createGain();
  // Deliberately quiet — this fires on every inbound message.
  master.gain.value = 0.09;
  master.connect(ctx.destination);

  for (const [index, frequency] of [880, 1170].entries()) {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.value = frequency;
    const start = now + index * 0.11;
    const end = start + 0.16;
    // Envelope: instant attack, exponential release. Without the ramp
    // the abrupt stop produces an audible click.
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(1, start + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, end);
    osc.connect(gain);
    gain.connect(master);
    osc.start(start);
    osc.stop(end + 0.02);
  }
}

export interface IncomingNotification {
  /** Stable id used to suppress duplicates across realtime + polling. */
  id: string;
  title: string;
  body: string;
  /** Conversation to open when the notification is clicked. */
  conversationId?: string;
}

export interface UseMessageNotificationsResult {
  enabled: boolean;
  permission: NotificationPermissionState;
  /** Turn alerts on (requests permission) or off. Call from a click. */
  toggle: () => Promise<void>;
  /** Fire an alert. No-op when disabled or already seen. */
  notify: (input: IncomingNotification) => void;
}

export function useMessageNotifications(options: {
  onOpenConversation?: (conversationId: string) => void;
} = {}): UseMessageNotificationsResult {
  const { onOpenConversation } = options;

  const [enabled, setEnabled] = useState(false);
  const [permission, setPermission] =
    useState<NotificationPermissionState>("default");

  const audioCtxRef = useRef<AudioContext | null>(null);
  const seenRef = useRef<Set<string>>(new Set());
  const openConversationRef = useRef(onOpenConversation);
  useEffect(() => {
    openConversationRef.current = onOpenConversation;
  });

  useEffect(() => {
    setEnabled(readStoredEnabled());
    if (typeof window === "undefined" || !("Notification" in window)) {
      setPermission("unsupported");
      return;
    }
    setPermission(Notification.permission as NotificationPermissionState);
  }, []);

  useEffect(() => {
    // Release the audio device when the view unmounts.
    return () => {
      void audioCtxRef.current?.close();
      audioCtxRef.current = null;
    };
  }, []);

  const toggle = useCallback(async () => {
    if (enabled) {
      setEnabled(false);
      try {
        window.localStorage.setItem(STORAGE_KEY, "false");
      } catch {
        /* storage unavailable — in-memory state still applies */
      }
      return;
    }

    // Runs inside the click handler, which is what lets the browser
    // show its permission prompt and start audio.
    if (typeof window !== "undefined" && "Notification" in window) {
      try {
        const result = await Notification.requestPermission();
        setPermission(result as NotificationPermissionState);
      } catch {
        // Older Safari uses the callback form; treat as unknown and
        // continue — sound still works without notification permission.
      }
    }

    try {
      const Ctor =
        window.AudioContext ??
        (window as unknown as { webkitAudioContext?: typeof AudioContext })
          .webkitAudioContext;
      if (Ctor) {
        audioCtxRef.current = audioCtxRef.current ?? new Ctor();
        if (audioCtxRef.current.state === "suspended") {
          await audioCtxRef.current.resume();
        }
        // Confirmation blip so the user hears what they just enabled.
        playChime(audioCtxRef.current);
      }
    } catch {
      /* audio unavailable — notifications may still work */
    }

    setEnabled(true);
    try {
      window.localStorage.setItem(STORAGE_KEY, "true");
    } catch {
      /* ignore */
    }
  }, [enabled]);

  const notify = useCallback(
    (input: IncomingNotification) => {
      if (!enabled) return;
      // Realtime and the backup poll can both surface the same message.
      if (seenRef.current.has(input.id)) return;
      seenRef.current.add(input.id);
      // Bound the set so a long-lived tab doesn't grow it forever.
      if (seenRef.current.size > 500) {
        seenRef.current = new Set(Array.from(seenRef.current).slice(-200));
      }

      const ctx = audioCtxRef.current;
      if (ctx && ctx.state === "running") {
        try {
          playChime(ctx);
        } catch {
          /* ignore audio failures */
        }
      }

      if (
        typeof window !== "undefined" &&
        "Notification" in window &&
        Notification.permission === "granted"
      ) {
        try {
          const notification = new Notification(input.title, {
            body: input.body,
            // Collapses repeat alerts for one chat into a single toast
            // instead of stacking one per message.
            tag: input.conversationId ?? input.id,
            icon: "/icon.png",
          });
          notification.onclick = () => {
            window.focus();
            if (input.conversationId) {
              openConversationRef.current?.(input.conversationId);
            }
            notification.close();
          };
        } catch {
          /* some browsers throw when constructing off a service worker */
        }
      }
    },
    [enabled],
  );

  return { enabled, permission, toggle, notify };
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { createClient } from "@/lib/supabase/client";
import { useWorkspace } from "@/hooks/use-workspace";
import { evaluateSetup, type SetupStatus, type SetupFacts } from "@/lib/workspace/setup-checklist";

/**
 * Gathers what the setup checklist needs to know.
 *
 * Deliberately cheap: head-only counts, no row payloads, and it only runs
 * for people who can actually act on the result. Showing a member a
 * checklist they cannot complete is worse than showing nothing.
 */
export function useWorkspaceSetup(): {
  status: SetupStatus | null;
  loading: boolean;
  refresh: () => void;
  canAct: boolean;
} {
  const supabase = createClient();
  const { activeWorkspace, moduleAccess, can, activeRole } = useWorkspace();
  const [status, setStatus] = useState<SetupStatus | null>(null);
  const [loading, setLoading] = useState(true);

  // Only owners and admins can change branding, signatories or structures.
  const canAct =
    activeRole === "owner" || activeRole === "admin" || can("settings_workspace");

  const load = useCallback(async () => {
    if (!activeWorkspace?.id || !canAct) {
      setStatus(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const ws = activeWorkspace as {
        id: string;
        name?: string | null;
        logo_url?: string | null;
        company_name?: string | null;
        company_address?: string | null;
      };

      const count = async (table: string, extra?: (q: unknown) => unknown) => {
        let q = supabase
          .from(table)
          .select("*", { count: "exact", head: true })
          .eq("workspace_id", activeWorkspace.id);
        if (extra) q = extra(q) as typeof q;
        const { count: n, error } = await q;
        // A failed count must not read as zero, or the banner nags about
        // something that is actually configured.
        return error ? null : n ?? 0;
      };

      const [sig, dept, loc, struct, letterhead, whatsapp] = await Promise.all([
        count("company_signatories", (q) => (q as { is: Function }).is("deleted_at", null)),
        count("departments"),
        count("work_locations", (q) => (q as { is: Function }).is("deleted_at", null)),
        count("hr_salary_structures", (q) => (q as { is: Function }).is("deleted_at", null)),
        supabase
          .from("company_letterhead_configs")
          .select("company_name, tax_id")
          .eq("workspace_id", activeWorkspace.id)
          .maybeSingle(),
        supabase
          .from("whatsapp_config")
          .select("id")
          .eq("workspace_id", activeWorkspace.id)
          .maybeSingle(),
      ]);

      const lh = letterhead.data as { company_name?: string | null; tax_id?: string | null } | null;

      const facts: SetupFacts = {
        companyName: Boolean((ws.company_name || lh?.company_name || "").trim()),
        logo: Boolean(ws.logo_url),
        // A letterhead row with a company name on it is the minimum that
        // makes a document look like it came from a company.
        letterheadConfigured: Boolean(lh && (lh.company_name || "").trim()),
        taxId: Boolean((lh?.tax_id || "").trim()),
        companyAddress: Boolean((ws.company_address || "").trim()),
        signatoryCount: sig ?? 1,
        departmentCount: dept ?? 1,
        workLocationCount: loc ?? 1,
        salaryStructureCount: struct ?? 1,
        whatsappConnected: Boolean(whatsapp.data),
        modules: {
          hr: Boolean(moduleAccess?.hr),
          crm: Boolean(moduleAccess?.crm),
          accounting: Boolean(moduleAccess?.accounting),
        },
      };

      setStatus(evaluateSetup(facts));
    } catch {
      // Never block the app on the checklist.
      setStatus(null);
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace, canAct, moduleAccess, supabase]);

  useEffect(() => {
    load();
  }, [load]);

  return { status, loading, refresh: load, canAct };
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  useMemo,
  type ReactNode,
} from "react";
import { createClient } from "@/lib/supabase/client";
import { withDerivedLegacyPermissions } from "@/lib/auth/legacy-permissions";
import { DEFAULT_CURRENCY } from "@/lib/currency";
import {
  deriveModuleAccess,
  type ModuleAccess,
} from "@/lib/auth/modules";
import { useAuth } from "./use-auth";

export interface WorkspacePlanLimits {
  max_members: number | null;
  max_workspaces: number | null;
  max_storage_gb: number | null;
  channels: string[];
  max_automations: number | null;
  max_messages?: number | null;
}

export interface Workspace {
  id: string;
  name: string;
  plan: string;
  plan_limits: WorkspacePlanLimits;
  created_at: string;
  logo_url?: string | null;
  /** Workspace default currency (ISO-4217, migration 033). */
  default_currency?: string | null;
  /** Company identity, edited in Settings -> Branding. Selected here
   *  because the setup checklist reads them from context — without them
   *  it reported a saved address as still missing. */
  company_name?: string | null;
  company_address?: string | null;
}

export interface WorkspaceMember {
  id: string;
  workspace_id: string;
  user_id: string;
  role: "owner" | "admin" | "member" | "viewer";
  role_id: string | null;
  created_at: string;
  profile?: {
    id: string;
    full_name: string | null;
    email: string;
    avatar_url: string | null;
  };
}

/** ABAC permission keys — keep in sync with DB workspace_roles.permissions JSONB */
export interface WorkspacePermissions {
  inbox: boolean;
  contacts: boolean;
  pipelines: boolean;
  broadcasts: boolean;
  automations: boolean;
  integrations: boolean;
  settings_profile: boolean;
  settings_workspace: boolean;
  settings_templates: boolean;
  settings_tags: boolean;
  reports: boolean;
  manage_users: boolean;
  manage_roles: boolean;
  manage_workspaces: boolean;
  projects_view: boolean;
  projects_manage: boolean;
  people_view: boolean;
  people_manage: boolean;
  attendance_manage: boolean;
  leave_approve: boolean;
}

export const DEFAULT_MEMBER_PERMISSIONS: WorkspacePermissions = {
  inbox: true,
  contacts: true,
  pipelines: true,
  broadcasts: true,
  automations: false,
  integrations: false,
  settings_profile: true,
  settings_workspace: false,
  settings_templates: false,
  settings_tags: false,
  reports: false,
  manage_users: false,
  manage_roles: false,
  manage_workspaces: false,
  projects_view: true,
  projects_manage: false,
  people_view: true,
  people_manage: false,
  attendance_manage: false,
  leave_approve: false,
};

export const OWNER_PERMISSIONS: WorkspacePermissions = {
  inbox: true,
  contacts: true,
  pipelines: true,
  broadcasts: true,
  automations: true,
  integrations: true,
  settings_profile: true,
  settings_workspace: true,
  settings_templates: true,
  settings_tags: true,
  reports: true,
  manage_users: true,
  manage_roles: true,
  manage_workspaces: true,
  projects_view: true,
  projects_manage: true,
  people_view: true,
  people_manage: true,
  attendance_manage: true,
  leave_approve: true,
};

interface WorkspaceContextValue {
  workspaces: Workspace[];
  activeWorkspace: Workspace | null;
  activeMember: { id: string } | null;
  activeRole: "owner" | "admin" | "member" | "viewer" | null;
  permissions: WorkspacePermissions;
  /**
   * Per-app-module access for the current member, derived from their enum
   * role + custom-role permissions JSONB. Owners/admins get every module.
   * See `deriveModuleAccess` in `@/lib/auth/modules`.
   */
  moduleAccess: ModuleAccess;
  /** Active workspace's default currency (ISO-4217, falls back to USD). */
  defaultCurrency: string;
  loading: boolean;
  switchWorkspace: (workspaceId: string) => void;
  refreshWorkspaces: () => Promise<void>;
  createWorkspace: (name: string) => Promise<Workspace | null>;
  /** True if the current user has a given permission key */
  can: (key: keyof WorkspacePermissions) => boolean;
}

const WorkspaceContext = createContext<WorkspaceContextValue | null>(null);

export function WorkspaceProvider({ children }: { children: ReactNode }) {
  const { user, loading: authLoading } = useAuth();
  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
  const [activeWorkspace, setActiveWorkspace] = useState<Workspace | null>(null);
  const [activeMember, setActiveMember] = useState<{ id: string } | null>(null);
  const [activeRole, setActiveRole] = useState<"owner" | "admin" | "member" | "viewer" | null>(null);
  const [permissions, setPermissions] = useState<WorkspacePermissions>(DEFAULT_MEMBER_PERMISSIONS);
  // Raw `workspace_roles.permissions` JSONB for the active member's custom
  // role (null when they have no custom role assigned). Kept separate from
  // `permissions` because module access is derived from the raw booleans —
  // see `moduleAccess` below.
  const [rolePermissions, setRolePermissions] = useState<Record<string, unknown> | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchWorkspaces = useCallback(async () => {
    if (authLoading) {
      return;
    }
    setLoading(true);
    if (!user?.id) {
      setWorkspaces([]);
      setActiveWorkspace(null);
      setActiveMember(null);
      setActiveRole(null);
      setPermissions(DEFAULT_MEMBER_PERMISSIONS);
      setRolePermissions(null);
      setLoading(false);
      return;
    }

    const supabase = createClient();
    try {
      const { data: memberData, error } = await supabase
        .from("workspace_members")
        .select(`
          id,
          workspace_id,
          role,
          role_id,
          workspaces (
            id,
            name,
            plan,
            plan_limits,
            created_at,
            logo_url,
            default_currency,
            company_name,
            company_address
          )
        `)
        .eq("user_id", user.id);

      if (error) {
        console.error("[WorkspaceProvider] error fetching memberships:", error);
        return;
      }

      if (memberData && memberData.length > 0) {
        const fetchedWorkspaces: Workspace[] = [];
        const roleMap: Record<string, "owner" | "admin" | "member" | "viewer"> = {};
        const roleIdMap: Record<string, string | null> = {};
        const memberMap: Record<string, { id: string }> = {};

        memberData.forEach((item: any) => {
          if (item.workspaces) {
            const ws = item.workspaces as unknown as Workspace;
            fetchedWorkspaces.push(ws);
            roleMap[ws.id] = item.role;
            roleIdMap[ws.id] = item.role_id ?? null;
            memberMap[ws.id] = { id: item.id };
          }
        });

        setWorkspaces(fetchedWorkspaces);

        const savedActiveId =
          typeof window !== "undefined"
            ? localStorage.getItem("crm_active_workspace_id")
            : null;
        const matchedWorkspace = fetchedWorkspaces.find((w) => w.id === savedActiveId);

        const chosenWorkspace = matchedWorkspace ?? fetchedWorkspaces[0];
        setActiveWorkspace(chosenWorkspace);
        const chosenRole = roleMap[chosenWorkspace.id];
        setActiveRole(chosenRole);
        setActiveMember(memberMap[chosenWorkspace.id] || null);

        if (!matchedWorkspace && typeof window !== "undefined") {
          localStorage.setItem("crm_active_workspace_id", chosenWorkspace.id);
        }

        // Fetch ABAC permissions for this workspace
        await loadPermissions(
          supabase,
          chosenWorkspace.id,
          chosenRole,
          roleIdMap[chosenWorkspace.id] ?? null,
        );
      } else {
        setWorkspaces([]);
        setActiveWorkspace(null);
        setActiveMember(null);
        setActiveRole(null);
        setPermissions(DEFAULT_MEMBER_PERMISSIONS);
        setRolePermissions(null);
      }
    } catch (err) {
      console.error("[WorkspaceProvider] exception:", err);
    } finally {
      setLoading(false);
    }
  }, [user?.id, authLoading]);

  const loadPermissions = async (
    supabase: ReturnType<typeof createClient>,
    workspaceId: string,
    role: "owner" | "admin" | "member" | "viewer" | null,
    roleId: string | null
  ) => {
    // Owners & Admins always get all permissions — no DB call needed.
    // Their module access is derived from the enum role alone, so the raw
    // role JSONB can stay null (the owner/admin bypass ignores it).
    if (role === "owner" || role === "admin") {
      setPermissions(OWNER_PERMISSIONS);
      setRolePermissions(null);
      return;
    }

    // Fetch the member's custom-role permissions JSONB directly. RLS scopes
    // workspace_roles to the caller's workspace, and we filter on both id and
    // workspace_id, so this can never read another tenant's role. Module
    // access is derived from these raw booleans (module_crm/hr/retail/projects).
    if (roleId) {
      const { data: roleRow } = await supabase
        .from("workspace_roles")
        .select("permissions")
        .eq("id", roleId)
        .eq("workspace_id", workspaceId)
        .maybeSingle();
      setRolePermissions(
        (roleRow?.permissions as Record<string, unknown> | undefined) ?? null,
      );
    } else {
      // No custom role assigned → module access falls back to the default.
      setRolePermissions(null);
    }

    try {
      const { data, error } = await supabase
        .rpc("get_user_permissions", { p_workspace_id: workspaceId })
        .single();

      if (error || !data) {
        setPermissions(DEFAULT_MEMBER_PERMISSIONS);
        return;
      }

      // The seeded roles carry only CRUD keys, so the coarse keys the HR
      // UI gates on (people_manage, attendance_manage, leave_approve) are
      // absent and the defaults below would deny them forever. Derive them
      // from the CRUD keys that ARE granted.
      setPermissions(
        withDerivedLegacyPermissions({
          ...DEFAULT_MEMBER_PERMISSIONS,
          ...(data as WorkspacePermissions),
        }) as WorkspacePermissions
      );
    } catch {
      setPermissions(DEFAULT_MEMBER_PERMISSIONS);
    }
  };

  useEffect(() => {
    fetchWorkspaces();
  }, [fetchWorkspaces]);

  const switchWorkspace = useCallback(
    (workspaceId: string) => {
      const matched = workspaces.find((w) => w.id === workspaceId);
      if (matched) {
        setActiveWorkspace(matched);
        // Note: activeMember/activeRole reload on fetchWorkspaces. 
        // For a full context switch, reload is standard in this app.
        if (typeof window !== "undefined") {
          localStorage.setItem("crm_active_workspace_id", workspaceId);
        }
        window.location.reload();
      }
    },
    [workspaces]
  );

  const refreshWorkspaces = useCallback(async () => {
    setLoading(true);
    await fetchWorkspaces();
  }, [fetchWorkspaces]);

  const createWorkspace = useCallback(
    async (name: string): Promise<Workspace | null> => {
      if (!user?.id) return null;
      const supabase = createClient();
      try {
        const { data, error } = await supabase
          .rpc("create_workspace_for_user", { p_name: name.trim() })
          .single();

        if (error) {
          console.error("[WorkspaceProvider] error creating workspace:", error);
          throw new Error(error.message || "Failed to create workspace");
        }

        const wsData = data as Workspace;
        await fetchWorkspaces();
        setActiveWorkspace(wsData);
        if (typeof window !== "undefined") {
          localStorage.setItem("crm_active_workspace_id", wsData.id);
        }
        return wsData;
      } catch (err: any) {
        console.error("[WorkspaceProvider] exception during workspace creation:", err);
        throw err;
      }
    },
    [user?.id, fetchWorkspaces]
  );

  const can = useCallback(
    (key: keyof WorkspacePermissions) => permissions[key] === true,
    [permissions]
  );

  // Derive per-module access from the enum role + raw custom-role JSONB.
  // Owner/admin ⇒ all modules; role-less members ⇒ DEFAULT_MODULE_ACCESS.
  const moduleAccess = useMemo(
    () => deriveModuleAccess(activeRole, rolePermissions),
    [activeRole, rolePermissions]
  );

  return (
    <WorkspaceContext.Provider
      value={{
        workspaces,
        activeWorkspace,
        activeMember,
        activeRole,
        permissions,
        moduleAccess,
        defaultCurrency: activeWorkspace?.default_currency || DEFAULT_CURRENCY,
        loading,
        switchWorkspace,
        refreshWorkspaces,
        createWorkspace,
        can,
      }}
    >
      {children}
    </WorkspaceContext.Provider>
  );
}

export function useWorkspace(): WorkspaceContextValue {
  const ctx = useContext(WorkspaceContext);
  if (!ctx) {
    throw new Error("useWorkspace must be used within a WorkspaceProvider");
  }
  return ctx;
}

/**
 * Convenience hook returning just the current member's per-module access
 * `{ crm, hr, retail, projects }`. Owner/admin get every module; a member
 * with no custom role falls back to DEFAULT_MODULE_ACCESS (CRM only).
 */
export function useModuleAccess(): ModuleAccess {
  return useWorkspace().moduleAccess;
}

import { createClient } from "@supabase/supabase-js";
import { decrypt } from "@/lib/whatsapp/encryption";
import { generateChatbotResponse } from "./ai-service";
import { engineSendText } from "@/lib/automations/meta-send";

// Lazy-initialized admin client
let _adminClient: any = null;
function supabaseAdmin() {
  if (!_adminClient) {
    _adminClient = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    );
  }
  return _adminClient;
}

interface ProcessChatbotReplyArgs {
  workspaceId: string;
  conversationId: string;
  contactId: string;
  messageText: string;
}

export async function processChatbotReply({
  workspaceId,
  conversationId,
  contactId,
  messageText,
}: ProcessChatbotReplyArgs): Promise<void> {
  try {
    const db = supabaseAdmin();

    // 1. Fetch chatbot config for the workspace
    const { data: config, error: configErr } = await db
      .from("chatbot_config")
      .select("*")
      .eq("workspace_id", workspaceId)
      .maybeSingle();

    if (configErr) {
      console.error("[chatbot processor] Error fetching chatbot_config:", configErr);
      return;
    }

    if (!config || !config.is_enabled) {
      // Chatbot not configured or disabled globally
      return;
    }

    // 2. Fetch conversation to check bot_status and bot_paused_until
    const { data: conversation, error: convErr } = await db
      .from("conversations")
      .select("bot_status, bot_paused_until")
      .eq("id", conversationId)
      .maybeSingle();

    if (convErr || !conversation) {
      console.error("[chatbot processor] Error fetching conversation status:", convErr);
      return;
    }

    let isBotActive = conversation.bot_status === "active";

    // Handle auto-resume if the pause timer has expired
    if (!isBotActive && conversation.bot_paused_until) {
      const now = new Date();
      const pausedUntil = new Date(conversation.bot_paused_until);
      if (now > pausedUntil) {
        // Pause has expired! Auto-resume the bot
        isBotActive = true;
        const { error: resumeErr } = await db
          .from("conversations")
          .update({
            bot_status: "active",
            bot_paused_until: null,
          })
          .eq("id", conversationId);

        if (resumeErr) {
          console.error("[chatbot processor] Failed to auto-resume conversation bot status:", resumeErr);
        }
      }
    }

    if (!isBotActive) {
      // Bot is currently paused
      return;
    }

    // 3. Fetch recent message history (last 10 messages)
    const { data: dbMessages, error: msgErr } = await db
      .from("messages")
      .select("sender_type, content_text, created_at")
      .eq("conversation_id", conversationId)
      .order("created_at", { ascending: false })
      .limit(10);

    if (msgErr) {
      console.error("[chatbot processor] Error fetching message history:", msgErr);
      return;
    }

    // Map DB messages to LLM chat format (reverse to be chronological)
    // Filter out empty messages or non-text messages
    const history: { role: "user" | "assistant"; content: string }[] = [];
    const reversedMessages = dbMessages ? [...dbMessages].reverse() : [];

    // We exclude the very last message if it's the current user message,
    // as we pass that separately to the AI service.
    const lastMsg = reversedMessages[reversedMessages.length - 1];
    const contextMessages =
      lastMsg && lastMsg.content_text === messageText
        ? reversedMessages.slice(0, -1)
        : reversedMessages;

    for (const msg of contextMessages) {
      if (!msg.content_text) continue;
      history.push({
        role: msg.sender_type === "customer" ? "user" : "assistant",
        content: msg.content_text,
      });
    }

    // 4. Decrypt tenant-specific API key if present
    let decryptedKey: string | null = null;
    if (config.api_key) {
      try {
        decryptedKey = decrypt(config.api_key);
      } catch (err) {
        console.error("[chatbot processor] Decrypting tenant API key failed:", err);
      }
    }

    // 5. Generate reply via AI Service
    const formattingInstructions = `
CRITICAL RESPONSE FORMATTING RULES:
1. You are chatting with a user on WhatsApp.
2. The Business Context contains script templates containing metadata indicators such as:
   - "Typing... (X seconds)"
   - "Buttons:"
   - "IF YES", "IF NO", "COUNTRY FALLBACK", "CONTACT COLLECTION"
3. DO NOT output any of these metadata instructions, indicators, or section headers literally.
   - NEVER include the literal phrase "Typing..." or the duration in your response.
   - NEVER include the word "Buttons:" or "Free text field".
   - Simply output the final clean conversational text. If options are listed under "Buttons:", present them naturally in the conversation (e.g., "• Option 1\n• Option 2") so the user can easily select or type their choice.
`;

    const systemPrompt = `${config.system_prompt}\n${formattingInstructions}\n\nBusiness Context / Info:\n${config.business_context || ""}`;

    const reply = await generateChatbotResponse({
      provider: config.provider,
      apiKey: decryptedKey,
      model: config.model,
      systemPrompt,
      history,
      userMessage: messageText,
    });

    if (!reply || !reply.trim()) {
      return;
    }

    // 6. Simulate delay if configured
    if (config.response_delay > 0) {
      const delayMs = Math.min(Math.max(config.response_delay, 0), 10) * 1000;
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }

    // 7. Send the text via provider and persist to database
    await engineSendText({
      workspaceId,
      conversationId,
      contactId,
      text: reply.trim(),
    });
  } catch (error) {
    console.error("[chatbot processor] Error processing chatbot reply:", error);
  }
}

import { SupabaseClient } from "@supabase/supabase-js";
import { sanitizeErrorMessage } from "./barcode-utils";
import {
  ensureAccounts,
  isKhataMode,
  resolveBankLedger,
  roleForPaymentMode,
} from "@/lib/accounting/posting";

export interface PaymentLinePayload {
  /** 'KHATA' (the sales-order enum spelling) and 'KHATA_CREDIT' are
   *  both accepted — the historical mismatch between them silently
   *  debited credit sales to Cash in Hand. */
  mode: "CASH" | "UPI" | "CARD" | "BANK_TRANSFER" | "CHEQUE" | "KHATA_CREDIT" | "KHATA";
  bank_account_id?: string;
  amount: number;
  utr_number?: string;
  payment_app?: "PhonePe" | "Google Pay" | "Paytm" | "BHIM" | string;
  card_type?: "DEBIT" | "CREDIT";
  card_last_digits?: string;
  cheque_number?: string;
  cheque_bank?: string;
  credit_days?: number;
}

export interface POSAccountingPayload {
  workspace_id: string;
  sales_order_id: string;
  order_number: string;
  customer_id?: string | null;
  total_sales_amount: number;
  payments: PaymentLinePayload[];
  cashier_member_id?: string | null;
}

/**
 * On-the-fly Chart of Accounts Auto-Seeder (Rule #6)
 * Ensures standard default GL accounts exist for the workspace.
 * Seeding is delegated to the central posting engine's catalog so
 * the POS path and every other module share one chart of accounts.
 */
export async function getOrCreateDefaultAccounts(supabase: SupabaseClient, workspaceId: string) {
  await ensureAccounts(supabase, workspaceId);

  const { data: allAccounts } = await supabase
    .from("commerce_chart_of_accounts")
    .select("*")
    .eq("workspace_id", workspaceId);

  return allAccounts || [];
}

/**
 * Automatic Double-Entry Journal Generator for POS Sales
 */
export async function postPOSSalesJournal(supabase: SupabaseClient, payload: POSAccountingPayload) {
  const { workspace_id, sales_order_id, order_number, customer_id, total_sales_amount, payments, cashier_member_id } = payload;

  // 1. Get GL Accounts Map
  const accounts = await getOrCreateDefaultAccounts(supabase, workspace_id);
  const accountMapBySub: Record<string, any> = {};
  accounts.forEach((acc) => {
    if (acc.sub_category) accountMapBySub[acc.sub_category] = acc;
  });

  const cashAccount = accountMapBySub["CASH"] || accounts[0];
  const bankAccount = accountMapBySub["BANK"] || accounts[0];
  const chequeAccount = accountMapBySub["CHEQUE_IN_HAND"] || accounts[0];
  const khataAccount = accountMapBySub["CUSTOMER_KHATA"] || accounts[0];
  const salesAccount = accountMapBySub["SALES_REVENUE"] || accounts[0];

  const voucherNumber = `JV-${Date.now().toString().slice(-6)}`;

  // Check UTR duplicate validation
  for (const p of payments) {
    if (p.utr_number && p.utr_number.trim() !== "") {
      const { data: dup } = await supabase
        .from("commerce_journal_entries")
        .select("id")
        .eq("workspace_id", workspace_id)
        .eq("utr_number", p.utr_number.trim())
        .maybeSingle();

      if (dup) {
        throw new Error(`Duplicate UTR/Transaction number: ${p.utr_number}`);
      }
    }
  }

  // 2. Create Journal Header
  const { data: journalEntry, error: jError } = await supabase
    .from("commerce_journal_entries")
    .insert({
      workspace_id,
      voucher_number: voucherNumber,
      reference_type: "POS_SALE",
      reference_id: sales_order_id,
      utr_number: payments.map((p) => p.utr_number).filter(Boolean).join(", ") || null,
      payment_app: payments.map((p) => p.payment_app).filter(Boolean).join(", ") || null,
      card_last_digits: payments.map((p) => p.card_last_digits).filter(Boolean).join(", ") || null,
      cheque_number: payments.map((p) => p.cheque_number).filter(Boolean).join(", ") || null,
      narration: `Automated accounting entry for POS Order #${order_number}`,
      created_by: cashier_member_id,
    })
    .select()
    .single();

  if (jError || !journalEntry) {
    throw new Error(sanitizeErrorMessage(jError, "Failed to create journal entry"));
  }

  const linesToInsert: any[] = [];
  let customerKhataAddition = 0;

  // 3. Build Debit Lines per payment mode.
  //    roleForPaymentMode treats 'KHATA' and 'KHATA_CREDIT' alike,
  //    and bank_account_id is resolved through the bank account's
  //    ledger_id — it is a commerce_bank_accounts id, not a
  //    chart-of-accounts id, and non-UUID junk (the POS UI used to
  //    send a free-text label) falls back to the default bank ledger.
  for (const p of payments) {
    const amt = Number(p.amount || 0);
    if (amt <= 0) continue;

    const role = roleForPaymentMode(p.mode);
    let targetAccountId =
      role === "CASH" ? cashAccount.id
      : role === "BANK" ? bankAccount.id
      : role === "CHEQUE_IN_HAND" ? chequeAccount.id
      : khataAccount.id;

    if (role === "BANK" && p.bank_account_id) {
      targetAccountId = await resolveBankLedger(supabase, workspace_id, p.bank_account_id, bankAccount);
    }
    if (isKhataMode(p.mode)) {
      customerKhataAddition += amt;
    }

    linesToInsert.push({
      journal_entry_id: journalEntry.id,
      account_id: targetAccountId,
      contact_id: isKhataMode(p.mode) ? customer_id || null : null,
      debit_amount: amt,
      credit_amount: 0,
    });
  }

  // 4. Build Credit Line for Sales Revenue Account
  linesToInsert.push({
    journal_entry_id: journalEntry.id,
    account_id: salesAccount.id,
    contact_id: customer_id || null,
    debit_amount: 0,
    credit_amount: total_sales_amount,
  });

  const { error: linesError } = await supabase
    .from("commerce_journal_lines")
    .insert(linesToInsert);
  if (linesError) {
    // The DB rejects unbalanced entries at commit (075). Never leave
    // the header behind as an orphan voucher.
    await supabase.from("commerce_journal_entries").delete().eq("id", journalEntry.id);
    throw new Error(sanitizeErrorMessage(linesError, "Failed to write journal lines"));
  }

  // 5. Update Customer Khata balance if credit purchase was made
  if (customerKhataAddition > 0 && customer_id) {
    const { data: existingKhata } = await supabase
      .from("commerce_customer_khata")
      .select("*")
      .eq("workspace_id", workspace_id)
      .eq("contact_id", customer_id)
      .maybeSingle();

    if (existingKhata) {
      await supabase
        .from("commerce_customer_khata")
        .update({
          outstanding_balance: Number(existingKhata.outstanding_balance || 0) + customerKhataAddition,
        })
        .eq("id", existingKhata.id);
    } else {
      await supabase.from("commerce_customer_khata").insert({
        workspace_id,
        contact_id: customer_id,
        outstanding_balance: customerKhataAddition,
      });
    }
  }

  return { journalEntry, lines: linesToInsert };
}

/**
 * Defensive Scanner Input Extraction
 * Cleanly strips carriage returns, JSON brackets, or tag placeholders from barcode scanners.
 */
export function extractCleanSku(input: string): string {
  if (!input) return "";
  const str = input.trim().replace(/[\r\n]+/g, "");

  // Parse JSON if scanned
  if (str.includes("{") && str.includes("}")) {
    try {
      const s = str.indexOf("{");
      const e = str.lastIndexOf("}") + 1;
      const parsed = JSON.parse(str.substring(s, e));
      return (parsed.code || parsed.sku || parsed.itemCode || parsed.id || str).trim();
    } catch {
      /* fallback */
    }
  }

  // Strip brackets or non-alphanumeric outer padding
  return str.replace(/^[\[{\s]+|[\]}\s]+$/g, "");
}

/**
 * Unified Financial Math Helper
 * Handles PERCENTAGE, PER_GRAM, and FIXED calculation modes seamlessly.
 */
export function computeItemFinancials(
  baseValue: number,
  chargeType: "PERCENTAGE" | "PER_GRAM" | "FIXED" = "FIXED",
  chargeValue: number = 0,
  netWeight: number = 1,
  taxRate: number = 0
) {
  const chargeAmount =
    chargeType === "PER_GRAM"
      ? netWeight * chargeValue
      : chargeType === "PERCENTAGE"
      ? baseValue * (chargeValue / 100)
      : chargeValue;

  const subtotal = baseValue + chargeAmount;
  const tax = subtotal * (taxRate / 100);
  const totalPrice = subtotal + tax;

  return { baseValue, chargeAmount, subtotal, tax, totalPrice };
}

/**
 * Helper to safely extract string message from error objects
 * Prevents React Fiber crashes in toast.error(e)
 */
export function sanitizeErrorMessage(e: any, fallback: string = "Operation failed"): string {
  if (typeof e === "string") return e;
  if (typeof e?.message === "string") return e.message;
  if (typeof e?.error?.message === "string") return e.error.message;
  if (typeof e?.error === "string") return e.error;
  return fallback;
}

