/** Variables grouped by module, for a picker UI. */
export function variablesByModule(): Record<VariableModule, DocumentVariableMeta[]> {
  const out = {} as Record<VariableModule, DocumentVariableMeta[]>;
  for (const m of VARIABLE_MODULES) out[m] = [];
  for (const v of VARIABLE_DICTIONARY) out[v.module].push(v);
  return out;
}

/**
 * Escape a context value for insertion into an HTML document body.
 *
 * Interpolated values are user-supplied (recipient name, designation,
 * salary, contact fields) and the result is persisted to
 * `official_documents.body_html`, which is rendered through
 * `dangerouslySetInnerHTML`. Without this, typing markup into
 * "Recipient Full Name" is stored XSS for every later viewer.
 */
function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * Replaces Handlebars-style {{variable.key}} tokens in HTML text with contextual dictionary values.
 */
export function interpolateVariables(
  templateHtml: string,
  contextData: Record<string, any>
): string {
  if (!templateHtml) return "";

  return templateHtml.replace(/\{\{\s*([a-zA-Z0-9_\.]+)\s*\}\}/g, (match, token) => {
    const value = getNestedValue(contextData, token);
    if (value !== undefined && value !== null) {
      return escapeHtml(String(value));
    }
    // Return empty placeholder string if context missing
    return `<span class="text-primary font-mono underline bg-primary/10 px-1 py-0.5 rounded">[${token}]</span>`;
  });
}

function getNestedValue(obj: Record<string, any>, path: string): any {
  const parts = path.split(".");
  let curr = obj;
  for (const part of parts) {
    if (curr === null || curr === undefined) return undefined;
    curr = curr[part];
  }
  return curr;
}

/**
 * Microsoft Outlook / Azure AD App Registration Email Integration Engine.
 * Uses Client Credentials Grant against Microsoft Graph API.
 */

export interface OutlookConfig {
  tenantId: string;
  clientId: string;
  clientSecret: string;
  fromEmail: string;
}

export interface SendOutlookEmailArgs {
  config: OutlookConfig;
  to: string;
  subject: string;
  bodyHtml: string;
}

/**
 * Fetch OAuth2 Access Token for Azure AD App Registration using Client Credentials Flow.
 */
export async function getOutlookAccessToken(config: OutlookConfig): Promise<string> {
  const { tenantId, clientId, clientSecret } = config;
  const tokenUrl = `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`;

  const params = new URLSearchParams();
  params.append("grant_type", "client_credentials");
  params.append("client_id", clientId);
  params.append("client_secret", clientSecret);
  params.append("scope", "https://graph.microsoft.com/.default");

  const res = await fetch(tokenUrl, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: params.toString(),
  });

  const json = await res.json();
  if (!res.ok) {
    throw new Error(
      json.error_description || json.error || `Azure AD Authentication Failed (Status ${res.status})`
    );
  }

  return json.access_token;
}

/**
 * Test Azure AD App Registration credentials.
 */
export async function testOutlookConnection(config: OutlookConfig): Promise<{ success: boolean; message: string }> {
  try {
    const token = await getOutlookAccessToken(config);
    // Test fetching sender profile or mailbox
    const res = await fetch(`https://graph.microsoft.com/v1.0/users/${config.fromEmail}`, {
      headers: { Authorization: `Bearer ${token}` },
    });

    if (!res.ok) {
      const errJson = await res.json().catch(() => ({}));
      throw new Error(errJson.error?.message || `User mailbox "${config.fromEmail}" not accessible (Status ${res.status})`);
    }

    return {
      success: true,
      message: `Successfully connected to Microsoft Graph API for mailbox ${config.fromEmail}`,
    };
  } catch (err: any) {
    return {
      success: false,
      message: err.message || "Failed to authenticate with Microsoft Outlook",
    };
  }
}

/**
 * Send Email via Microsoft Graph API.
 */
export async function sendOutlookEmail(args: SendOutlookEmailArgs): Promise<void> {
  const { config, to, subject, bodyHtml } = args;
  const token = await getOutlookAccessToken(config);

  const sendMailUrl = `https://graph.microsoft.com/v1.0/users/${config.fromEmail}/sendMail`;

  const payload = {
    message: {
      subject,
      body: {
        contentType: "HTML",
        content: bodyHtml,
      },
      toRecipients: [
        {
          emailAddress: {
            address: to,
          },
        },
      ],
    },
    saveToSentItems: "true",
  };

  const res = await fetch(sendMailUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const errJson = await res.json().catch(() => ({}));
    throw new Error(errJson.error?.message || `Microsoft Graph API sendMail failed (${res.status})`);
  }
}

import { createAdminClient } from '@/lib/supabase/admin';
import { PLANS } from '@/config/plans';

export interface WorkspaceUsageInfo {
  planId: string;
  planName: string;
  memberCount: number;
  maxUsers: number;
  workspaceCount: number;
  maxWorkspaces: number;
  messageCount: number;
  monthlyMessageAllowance: number;
  isTrial: boolean;
  createdAt: Date;
}

export async function getWorkspaceUsageAndLimits(workspaceId: string): Promise<WorkspaceUsageInfo> {
  const admin = createAdminClient();

  // 1. Get the workspace plan and limits
  const { data: ws, error: wsError } = await admin
    .from('workspaces')
    .select('plan, plan_limits, created_at')
    .eq('id', workspaceId)
    .single();

  if (wsError || !ws) {
    throw new Error('Workspace not found');
  }

  const planId = ws.plan || 'growth';
  const createdAt = new Date(ws.created_at);

  // 2. Count members
  const { count: memberCount } = await admin
    .from('workspace_members')
    .select('*', { count: 'exact', head: true })
    .eq('workspace_id', workspaceId);

  // 3. Count workspaces owned by the owner of this workspace
  const { data: ownerMember } = await admin
    .from('workspace_members')
    .select('user_id')
    .eq('workspace_id', workspaceId)
    .eq('role', 'owner')
    .maybeSingle();

  let workspaceCount = 1;
  if (ownerMember) {
    const { count: wsCount } = await admin
      .from('workspace_members')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', ownerMember.user_id)
      .eq('role', 'owner');
    workspaceCount = wsCount || 1;
  }

  // 4. Count outbound messages ('agent' or 'bot') in the current month (or total if free trial)
  let startDateTime = new Date();
  if (planId === 'free') {
    startDateTime = createdAt;
  } else {
    startDateTime = new Date();
    startDateTime.setUTCDate(1);
    startDateTime.setUTCHours(0, 0, 0, 0);
  }

  const { count: messageCount } = await admin
    .from('messages')
    .select('id, conversations!inner(workspace_id)', { count: 'exact', head: true })
    .eq('conversations.workspace_id', workspaceId)
    .in('sender_type', ['agent', 'bot'])
    .gte('created_at', startDateTime.toISOString());

  // Find the plan config
  const planConfig = PLANS.find((p) => p.id === planId) || PLANS.find((p) => p.id === 'growth')!;

  return {
    planId,
    planName: planConfig.name,
    memberCount: memberCount || 0,
    maxUsers: planConfig.maxUsers,
    workspaceCount,
    maxWorkspaces: planConfig.maxWorkspaces,
    messageCount: messageCount || 0,
    monthlyMessageAllowance: planConfig.monthlyMessageAllowance,
    isTrial: planId === 'free',
    createdAt,
  };
}

export async function checkMessageLimit(workspaceId: string): Promise<{
  allowed: boolean;
  warn: boolean;
  messageCount: number;
  limit: number;
  error?: string;
}> {
  try {
    const info = await getWorkspaceUsageAndLimits(workspaceId);
    const limit = info.monthlyMessageAllowance;
    const count = info.messageCount;

    // Check if free trial has expired (14 days)
    if (info.planId === 'free') {
      const trialDurationMs = 14 * 24 * 60 * 60 * 1000;
      const trialExpired = (Date.now() - info.createdAt.getTime()) > trialDurationMs;
      if (trialExpired) {
        return {
          allowed: false,
          warn: false,
          messageCount: count,
          limit,
          error: `Your 14-day Free Trial has expired. Please upgrade your plan to resume messaging.`,
        };
      }
    }

    if (count >= limit) {
      return {
        allowed: false,
        warn: false,
        messageCount: count,
        limit,
        error: `Message limit reached. You have sent ${count}/${limit} messages on the ${info.planName} plan. Please upgrade to send more.`,
      };
    }

    const warnThreshold = limit * 0.8;
    return {
      allowed: true,
      warn: count >= warnThreshold,
      messageCount: count,
      limit,
    };
  } catch (err: any) {
    console.error('[checkMessageLimit] error:', err.message);
    // A workspace that definitively doesn't exist must not send —
    // fail closed. Transient DB errors still fail open so a hiccup
    // doesn't block every tenant's messaging.
    if (typeof err?.message === 'string' && err.message.includes('Workspace not found')) {
      return {
        allowed: false,
        warn: false,
        messageCount: 0,
        limit: 0,
        error: 'Workspace not found for this conversation. Cannot verify plan limits.',
      };
    }
    return { allowed: true, warn: false, messageCount: 0, limit: 999999 };
  }
}

import { WhatsAppProvider } from '../provider-interface'

export class ApiAutoProvider implements WhatsAppProvider {
  private getHeaders(token: string) {
    return {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    }
  }

  async verifyConfig(credentials: {
    phoneId: string
    wabaId?: string
    token: string
  }): Promise<{ verifiedName: string; quality?: string }> {
    // ApiAuto doesn't seem to have a dedicated verify endpoint in the docs.
    // We'll return a stub name for now, but in a real scenario we'd do a quick check.
    return {
      verifiedName: 'ApiAuto Account',
      quality: 'GREEN',
    }
  }

  async sendMessage(args: {
    phoneId: string
    wabaId?: string
    token: string
    to: string
    text: string
  }): Promise<{ messageId: string }> {
    const url = `https://official.apiauto.in/api/v1/send-message?token=${args.token}`

    const payload = {
      messageObject: {
        messaging_product: 'whatsapp',
        to: args.to,
        type: 'text',
        text: {
          body: args.text,
        },
      },
    }

    const response = await fetch(url, {
      method: 'POST',
      headers: this.getHeaders(args.token),
      body: JSON.stringify(payload),
    })

    if (!response.ok) {
      const errorText = await response.text()
      throw new Error(`ApiAuto sendMessage failed: ${response.status} ${errorText}`)
    }

    const data = await response.json()
    if (data.success === false) {
      throw new Error(`ApiAuto error: ${data.message}`)
    }

    // ApiAuto docs don't show message_id in the success response for /send-message,
    // so we'll generate a pseudo-ID or use what we can.
    const messageId = data.metaResponse?.message_id || `apiauto-${Date.now()}`
    return { messageId }
  }

  async sendTemplate(args: {
    phoneId: string
    wabaId?: string
    token: string
    to: string
    templateName: string
    params?: string[]
  }): Promise<{ messageId: string }> {
    const url = 'https://official.apiauto.in/api/v1/send_templet'

    const payload = {
      sendTo: args.to,
      templetName: args.templateName,
      exampleArr: args.params || [],
      token: args.token,
    }

    const response = await fetch(url, {
      method: 'POST',
      headers: this.getHeaders(args.token),
      body: JSON.stringify(payload),
    })

    if (!response.ok) {
      const errorText = await response.text()
      throw new Error(`ApiAuto sendTemplate failed: ${response.status} ${errorText}`)
    }

    const data = await response.json()
    if (data.success === false) {
      throw new Error(`ApiAuto template error: ${data.message}`)
    }

    const messageId = data.metaResponse?.message_id || `apiauto-tpl-${Date.now()}`
    return { messageId }
  }
}

