import { WhatsAppProvider } from "../provider-interface";
import { supabaseAdmin } from "@/lib/automations/admin-client";

function formatTwilioNumber(num: string): string {
  const clean = num.trim();
  if (clean.startsWith("whatsapp:")) return clean;
  return `whatsapp:${clean.startsWith("+") ? clean : "+" + clean}`;
}

export class TwilioProvider implements WhatsAppProvider {
  async verifyConfig(credentials: {
    phoneId: string;
    wabaId?: string;
    token: string;
  }): Promise<{ verifiedName: string; quality?: string }> {
    const accountSid = credentials.wabaId;
    const authToken = credentials.token;

    if (!accountSid) {
      throw new Error("Twilio Account SID (WABA ID field) is required.");
    }

    const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}.json`;
    const authHeader = `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString("base64")}`;

    const response = await fetch(url, {
      method: "GET",
      headers: {
        Authorization: authHeader,
      },
    });

    if (!response.ok) {
      throw new Error(`Twilio authentication failed: ${response.statusText} (${response.status})`);
    }

    const data = await response.json();
    return {
      verifiedName: data.friendly_name || "Twilio Account",
      quality: "GREEN",
    };
  }

  async sendMessage(args: {
    phoneId: string;
    wabaId?: string;
    token: string;
    to: string;
    text: string;
  }): Promise<{ messageId: string }> {
    const accountSid = args.wabaId;
    const authToken = args.token;

    if (!accountSid) {
      throw new Error("Twilio Account SID (WABA ID field) is required to send messages.");
    }

    const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
    const authHeader = `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString("base64")}`;

    const fromFormatted = formatTwilioNumber(args.phoneId);
    const toFormatted = formatTwilioNumber(args.to);

    const bodyParams = new URLSearchParams({
      From: fromFormatted,
      To: toFormatted,
      Body: args.text,
    });

    const response = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: authHeader,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: bodyParams.toString(),
    });

    if (!response.ok) {
      const errText = await response.text();
      throw new Error(`Twilio send failed: ${errText} (${response.status})`);
    }

    const data = await response.json();
    return { messageId: data.sid };
  }

  async sendTemplate(args: {
    phoneId: string;
    wabaId?: string;
    token: string;
    to: string;
    templateName: string;
    params?: string[];
  }): Promise<{ messageId: string }> {
    const accountSid = args.wabaId;
    const authToken = args.token;

    if (!accountSid) {
      throw new Error("Twilio Account SID (WABA ID field) is required to send templates.");
    }

    // Resolve workspace ID from database to locate correct message template
    const { data: config, error: configError } = await supabaseAdmin()
      .from("whatsapp_config")
      .select("workspace_id")
      .eq("waba_id", accountSid)
      .maybeSingle();

    if (configError || !config) {
      throw new Error(`Failed to resolve workspace details for Twilio Account SID: ${configError?.message || "Not found"}`);
    }

    // Fetch the correct template row
    const { data: template, error: templateError } = await supabaseAdmin()
      .from("message_templates")
      .select("body_text")
      .eq("name", args.templateName)
      .eq("workspace_id", config.workspace_id)
      .maybeSingle();

    if (templateError || !template) {
      throw new Error(`Failed to fetch message template "${args.templateName}": ${templateError?.message || "Not found"}`);
    }

    // Substitute template parameters {{1}}, {{2}} with dynamic args values
    let compiledBody = template.body_text || "";
    if (args.params && args.params.length > 0) {
      args.params.forEach((param, index) => {
        compiledBody = compiledBody.replace(new RegExp(`\\{\\{${index + 1}\\}\\}`, "g"), param);
      });
    }

    // Deliver the compiled template via normal Twilio text message endpoint
    return this.sendMessage({
      phoneId: args.phoneId,
      wabaId: args.wabaId,
      token: args.token,
      to: args.to,
      text: compiledBody,
    });
  }
}

/**
 * Workspace setup checklist.
 *
 * WHY THIS EXISTS: several settings are load-bearing for output the
 * customer sees, and their absence degrades things silently rather than
 * failing. A missing letterhead means every offer letter goes out reading
 * "Company Legal Name". No signatory means letters are unsigned. No
 * salary structure means the Compensation tab has an empty dropdown. None
 * of that errors — it just produces poor documents, and nobody notices
 * until a candidate does.
 *
 * The rules are pure so they can be unit tested, and so the banner, the
 * setup page and any future onboarding wizard all agree on what "ready"
 * means.
 */

export type SetupSeverity = "blocking" | "recommended";

export interface SetupItem {
  id: string;
  label: string;
  /** What goes wrong while this is missing — shown to the user. */
  consequence: string;
  severity: SetupSeverity;
  href: string;
  /** Only checked when the workspace uses this module. */
  module?: "hr" | "crm" | "accounting";
}

/** What the checker is told about the workspace. */
export interface SetupFacts {
  companyName: boolean;
  logo: boolean;
  letterheadConfigured: boolean;
  taxId: boolean;
  companyAddress: boolean;
  signatoryCount: number;
  departmentCount: number;
  workLocationCount: number;
  salaryStructureCount: number;
  whatsappConnected: boolean;
  modules: { hr: boolean; crm: boolean; accounting: boolean };
}

/**
 * Ordered so the first thing a new workspace sees is the thing with the
 * widest blast radius.
 */
export const SETUP_ITEMS: (SetupItem & { satisfied: (f: SetupFacts) => boolean })[] = [
  {
    id: "company_name",
    label: "Company legal name",
    consequence: "Documents and letters print a placeholder name.",
    severity: "blocking",
    href: "/settings?tab=branding",
    satisfied: (f) => f.companyName,
  },
  {
    id: "company_address",
    label: "Registered address",
    consequence: "Letters and invoices have no address on them.",
    severity: "blocking",
    href: "/settings?tab=branding",
    satisfied: (f) => f.companyAddress,
  },
  {
    id: "letterhead",
    label: "Letterhead",
    consequence:
      "Every offer letter, certificate and official document goes out unbranded.",
    severity: "blocking",
    href: "/settings?tab=branding",
    satisfied: (f) => f.letterheadConfigured,
  },
  {
    id: "signatory",
    label: "An authorised signatory",
    consequence: "Letters are issued unsigned, which makes them unusable.",
    severity: "blocking",
    href: "/documents/signatories",
    satisfied: (f) => f.signatoryCount > 0,
  },
  {
    id: "logo",
    label: "Company logo",
    consequence: "Our logo shows in place of yours.",
    severity: "recommended",
    href: "/settings?tab=branding",
    satisfied: (f) => f.logo,
  },
  {
    id: "tax_id",
    label: "Tax registration number",
    consequence: "Invoices are issued without a GSTIN or tax number.",
    severity: "recommended",
    href: "/settings?tab=branding",
    module: "accounting",
    satisfied: (f) => f.taxId,
  },
  {
    id: "departments",
    label: "At least one department",
    consequence: "Employees cannot be organised or reported on by team.",
    severity: "recommended",
    href: "/departments",
    module: "hr",
    satisfied: (f) => f.departmentCount > 0,
  },
  {
    id: "work_location",
    label: "A work location",
    consequence:
      "Attendance cannot enforce a geofence, so punches are recorded without a boundary.",
    severity: "recommended",
    href: "/settings?tab=hr",
    module: "hr",
    satisfied: (f) => f.workLocationCount > 0,
  },
  {
    id: "salary_structure",
    label: "A salary structure",
    consequence:
      "Compensation must be typed in by hand for every hire, and payroll cannot derive allowances.",
    severity: "recommended",
    href: "/settings?tab=hr",
    module: "hr",
    satisfied: (f) => f.salaryStructureCount > 0,
  },
  {
    id: "whatsapp",
    label: "WhatsApp connection",
    consequence: "Messages and broadcasts cannot be sent.",
    severity: "recommended",
    href: "/settings?tab=whatsapp",
    module: "crm",
    satisfied: (f) => f.whatsappConnected,
  },
];

export interface SetupStatus {
  outstanding: SetupItem[];
  blocking: SetupItem[];
  recommended: SetupItem[];
  completed: number;
  total: number;
  /** True when nothing blocking remains. */
  ready: boolean;
}

/**
 * Items are skipped entirely when their module is off — telling a
 * CRM-only workspace to define a salary structure is noise, and noise is
 * what makes people ignore a checklist.
 */
export function evaluateSetup(facts: SetupFacts): SetupStatus {
  const applicable = SETUP_ITEMS.filter(
    (i) => !i.module || facts.modules[i.module]
  );
  const outstanding = applicable.filter((i) => !i.satisfied(facts));

  return {
    outstanding: outstanding.map(strip),
    blocking: outstanding.filter((i) => i.severity === "blocking").map(strip),
    recommended: outstanding.filter((i) => i.severity === "recommended").map(strip),
    completed: applicable.length - outstanding.length,
    total: applicable.length,
    ready: outstanding.every((i) => i.severity !== "blocking"),
  };
}

function strip(i: SetupItem & { satisfied: unknown }): SetupItem {
  const { satisfied: _ignored, ...rest } = i;
  return rest;
}

/** One line for the banner. Names the worst outstanding item. */
export function setupSummary(status: SetupStatus): string | null {
  if (status.outstanding.length === 0) return null;
  const worst = status.blocking[0] ?? status.recommended[0];
  const others = status.outstanding.length - 1;
  const tail = others > 0 ? ` and ${others} other item${others === 1 ? "" : "s"}` : "";
  return `Set up ${worst.label.toLowerCase()}${tail} — ${worst.consequence}`;
}

import type { AccountRole } from "@/lib/auth/roles";

export interface Profile {
  id: string;
  user_id: string;
  full_name: string;
  email: string;
  avatar_url?: string;
  /**
   * Legacy free-form role column from migration 001. Never read
   * by the app since 017_account_sharing.sql introduced the typed
   * `account_role` enum. Flagged for removal in a later cleanup
   * migration — kept on the type so existing destructures don't
   * break.
   */
  role: string;
  /**
   * Opted-in beta feature keys for this account. The column survives
   * for future beta gates; no current feature reads it (Flows was
   * the last user and went to soft-GA in PR #134). Defaults to `[]`
   * for every profile; toggled per-account via a direct UPDATE on
   * the `profiles` row.
   */
  beta_features?: string[];
  /**
   * Account this profile is a member of. Added by
   * `017_account_sharing.sql`; NOT NULL in the DB post-backfill.
   * Optional on the type only because older serialised payloads
   * (cached client state, test fixtures) may not have it yet.
   */
  account_id?: string;
  /**
   * Caller's role within their account. Source of truth for every
   * role-gated UI / API check — call `hasMinRole` from
   * `@/lib/auth/roles` rather than comparing this string directly.
   */
  account_role?: AccountRole;
  created_at: string;
}

// ============================================================
// Account-sharing entities (017_account_sharing.sql)
// ============================================================

export interface Account {
  id: string;
  name: string;
  /** auth.users.id of the immutable owner. */
  owner_user_id: string;
  created_at: string;
  updated_at: string;
}

/**
 * Hydrated member row for the Settings → Members tab. Combines
 * the profile and its account_role for a single member of the
 * caller's account. Sensitive fields (email) are populated only
 * when the caller has admin+ — agents and viewers see name +
 * avatar + role only.
 */
export interface AccountMember {
  user_id: string;
  full_name: string;
  email: string | null;
  avatar_url: string | null;
  role: AccountRole;
  joined_at: string;
}

/**
 * Outstanding invite link row. `token_hash` is intentionally
 * absent — it lives only in the DB and on the server. The
 * plaintext token is returned once at creation time and surfaced
 * via the invite URL; never re-emitted.
 */
export interface AccountInvitation {
  id: string;
  account_id: string;
  /** Roles offered via invite — owner is never offered. */
  role: Exclude<AccountRole, "owner">;
  created_by_user_id: string | null;
  label: string | null;
  created_at: string;
  expires_at: string;
  accepted_at: string | null;
  accepted_by_user_id: string | null;
}

export interface Contact {
  id: string;
  user_id: string;
  account_id: string;
  phone: string;
  /** Digits-only form of `phone`, generated by the DB (migration 022)
   *  and unique per account. Read-only. */
  phone_normalized?: string;
  name?: string;
  email?: string;
  company?: string;
  avatar_url?: string;
  created_at: string;
  updated_at: string;
}

export interface Tag {
